:root {
  --night: #0e0f15;
  --night-2: #15161e;
  --panel: #1c1d27;
  --panel-2: #252734;
  --panel-3: #2d2f3d;
  --paper: #f3ecd6;
  --paper-2: #e6dec6;
  --paper-3: #d4c7a3;
  --ink: #16151c;
  --ink-soft: #4a4754;
  --ink-mist: #8a8590;
  --mist: #c0b9b3;
  --muted: #7b7682;
  --line: rgba(243, 236, 214, .16);
  --line-soft: rgba(243, 236, 214, .08);
  --acid: #d6f06a;
  --acid-soft: rgba(214, 240, 106, .17);
  --coral: #f06e5b;
  --coral-soft: rgba(240, 110, 91, .15);
  --blue: #9bbcff;
  --blue-soft: rgba(155, 188, 255, .15);
  --wax: #b34a3a;
  --gold: #d4a85a;
  --lead-1: #f0e8d2;
  --lead-2: #d6c8a4;
  --lead-3: #a89c79;
  --plum: #1d1721;
  --serif: 'Iowan Old Style', 'Palatino Linotype', Palatino, 'Book Antiqua', Georgia, 'Times New Roman', serif;
  --sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --display: 'Iowan Old Style', 'Palatino Linotype', 'Book Antiqua', Georgia, 'Times New Roman', serif;
  --mono: ui-monospace, 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, Monaco, monospace;
  --ease: cubic-bezier(.2, .8, .2, 1);
  --ease-out: cubic-bezier(.16, 1, .3, 1);
  --ease-spring: cubic-bezier(.34, 1.32, .52, 1);
  --ease-soft: cubic-bezier(.4, 0, .2, 1);
  --gutter: clamp(22px, 5vw, 96px);
}

* {
  box-sizing: border-box;
}

html {
  background: var(--night);
  color-scheme: dark;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--night);
  color: var(--paper);
  font-family: var(--sans);
  font-feature-settings: 'kern' 1, 'liga' 1, 'calt' 1, 'ss01' 1;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
a {
  color: inherit;
  font: inherit;
}

a {
  text-decoration: none;
}

button {
  border: 0;
  cursor: pointer;
  background: transparent;
}

::selection {
  background: var(--coral);
  color: var(--ink);
}

:focus-visible {
  outline: 2px solid var(--acid);
  outline-offset: 4px;
  border-radius: 1px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app {
  position: relative;
  min-height: 100vh;
  overflow: hidden;
  background:
    radial-gradient(circle at 78% 6%, rgba(91, 121, 203, .18), transparent 30rem),
    radial-gradient(circle at 6% 60%, rgba(255, 118, 95, .06), transparent 28rem),
    linear-gradient(160deg, var(--night) 0%, #0f1522 52%, #0a0e16 100%);
  transition: background .9s var(--ease);
}

.app--voice-human {
  background:
    radial-gradient(circle at 82% 12%, rgba(255, 118, 95, .14), transparent 32rem),
    radial-gradient(circle at 10% 60%, rgba(216, 255, 98, .04), transparent 28rem),
    linear-gradient(160deg, #13101c 0%, #1d1721 52%, #100c14 100%);
}

.app--voice-bold {
  background:
    radial-gradient(circle at 76% 10%, rgba(216, 255, 98, .2), transparent 30rem),
    radial-gradient(circle at 14% 56%, rgba(255, 118, 95, .06), transparent 28rem),
    linear-gradient(160deg, var(--night) 0%, #13191f 52%, #0a0d12 100%);
}

.app::before {
  position: fixed;
  inset: 0;
  z-index: 0;
  background-image:
    linear-gradient(rgba(190, 209, 246, .03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(190, 209, 246, .03) 1px, transparent 1px);
  background-size: 96px 96px;
  content: '';
  mask-image: radial-gradient(ellipse at 50% 0%, black 0%, transparent 78%);
  pointer-events: none;
}

.app__grain {
  position: fixed;
  inset: 0;
  z-index: 1;
  opacity: .06;
  background-image: repeating-radial-gradient(circle at 0 0, rgba(255, 255, 255, .7) 0 1px, transparent 1px 4px);
  background-size: 7px 7px;
  mix-blend-mode: soft-light;
  pointer-events: none;
}

.app__pencil {
  position: fixed;
  inset: 0;
  z-index: 1;
  opacity: .03;
  background-image:
    repeating-linear-gradient(72deg, rgba(216, 255, 98, .35) 0 1px, transparent 1px 5px),
    repeating-linear-gradient(108deg, rgba(255, 118, 95, .25) 0 1px, transparent 1px 7px);
  mix-blend-mode: screen;
  pointer-events: none;
}

.press-mark-bg {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: clamp(320px, 70vw, 920px);
  height: auto;
  color: var(--paper);
  opacity: 0;
  z-index: 0;
  pointer-events: none;
}

.press-mark-bg text {
  font-feature-settings: 'kern' 1;
}

/* ────────────────────────────────────────────────────────────
   MARGIN THREAD · a vertical folio column on the right edge
   that runs alongside the page. The thread sticks to the page,
   tracks the active folio, and offers a quick-jump into each
   section. A paper rule keeps the navigation honest.
   ──────────────────────────────────────────────────────────── */

.margin-thread {
  --margin-progress: 0;
  position: fixed;
  top: 130px;
  right: clamp(14px, 2.4vw, 30px);
  z-index: 5;
  display: grid;
  grid-template-columns: minmax(56px, 64px) auto;
  gap: clamp(14px, 1.6vw, 20px);
  align-items: stretch;
  pointer-events: none;
  color: var(--paper);
  opacity: 0;
  animation: marginThreadIn 1.1s var(--ease-out) .5s forwards;
}

.margin-thread__stick {
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  align-items: stretch;
  pointer-events: auto;
  width: 28px;
  margin-left: auto;
}

.margin-thread__stick-head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-rows: auto auto;
  align-items: center;
  column-gap: 4px;
  row-gap: 2px;
  margin-bottom: 10px;
  color: var(--coral);
}

.margin-thread__stick-head-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(255, 118, 95, .14);
  justify-self: start;
}

.margin-thread__stick-head-rule {
  display: block;
  width: 100%;
  height: 1px;
  background: linear-gradient(to right, var(--coral), transparent);
}

.margin-thread__stick-head-tag {
  grid-column: 1 / -1;
  color: var(--coral);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .28em;
  text-transform: uppercase;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  text-align: left;
  align-self: start;
  justify-self: center;
  height: 86px;
  display: grid;
  place-items: center;
  margin-top: 2px;
}

.app--voice-quiet .margin-thread__stick-head,
.app--voice-quiet .margin-thread__stick-head-tag { color: var(--blue); }
.app--voice-human .margin-thread__stick-head,
.app--voice-human .margin-thread__stick-head-tag { color: var(--coral); }
.app--voice-bold .margin-thread__stick-head,
.app--voice-bold .margin-thread__stick-head-tag { color: var(--acid); }

.margin-thread__stick-rail {
  position: relative;
  width: 4px;
  margin: 0 auto;
  background:
    linear-gradient(to bottom, transparent 0%, var(--line) 8%, var(--line) 92%, transparent 100%);
  border-radius: 4px;
  min-height: 220px;
}

.margin-thread__stick-rail-fill {
  position: absolute;
  inset: 0 0 auto 0;
  background: linear-gradient(to bottom, var(--acid), var(--coral) 60%, var(--blue));
  transform-origin: top center;
  transform: scaleY(var(--margin-progress, 0));
  transition: transform .25s linear;
  border-radius: 4px;
  opacity: .9;
}

.app--voice-quiet .margin-thread__stick-rail-fill {
  background: linear-gradient(to bottom, var(--blue), var(--acid));
}

.app--voice-bold .margin-thread__stick-rail-fill {
  background: linear-gradient(to bottom, var(--acid), var(--coral));
}

.margin-thread__stick-node {
  position: absolute;
  left: 50%;
  top: calc((var(--node-i, 0)) * (100% / 10));
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  width: 14px;
  height: 14px;
  pointer-events: none;
  transition: top-color .4s var(--ease);
}

.margin-thread__stick-node-pip {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--night);
  border: 1.2px solid currentColor;
  color: var(--muted);
  transition: background .45s var(--ease), border-color .45s var(--ease), transform .5s var(--ease-spring), box-shadow .5s var(--ease);
}

.margin-thread__stick-node-tick {
  position: absolute;
  left: 16px;
  width: 8px;
  height: 1px;
  background: currentColor;
  opacity: .35;
  transition: width .35s var(--ease), opacity .35s var(--ease);
}

.margin-thread__stick-node.is-past .margin-thread__stick-node-pip {
  color: var(--coral);
  background: rgba(255, 118, 95, .15);
}

.margin-thread__stick-node.is-active .margin-thread__stick-node-pip {
  color: var(--coral);
  background: var(--coral);
  border-color: var(--coral);
  transform: scale(1.4);
  box-shadow: 0 0 0 4px rgba(255, 118, 95, .14), 0 0 12px rgba(255, 118, 95, .4);
}

.app--voice-quiet .margin-thread__stick-node.is-active .margin-thread__stick-node-pip {
  background: var(--blue);
  border-color: var(--blue);
  box-shadow: 0 0 0 4px rgba(155, 188, 255, .14), 0 0 12px rgba(155, 188, 255, .4);
}

.app--voice-bold .margin-thread__stick-node.is-active .margin-thread__stick-node-pip {
  background: var(--acid);
  border-color: var(--acid);
  box-shadow: 0 0 0 4px rgba(216, 255, 106, .14), 0 0 12px rgba(216, 255, 106, .4);
}

.margin-thread__stick-node.is-active .margin-thread__stick-node-tick {
  width: 14px;
  opacity: 1;
}

.margin-thread__stick-foot {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 4px;
  margin-top: 10px;
}

.margin-thread__stick-foot-rule {
  height: 1px;
  background: linear-gradient(to right, transparent, var(--coral), transparent);
  grid-column: 1 / -1;
  width: 70%;
  justify-self: center;
}

.margin-thread__stick-foot-rule:first-child {
  grid-column: 1;
  width: 12px;
  background: linear-gradient(to right, transparent, var(--coral));
}

.margin-thread__stick-foot-rule:last-child {
  grid-column: 3;
  width: 12px;
  background: linear-gradient(to left, transparent, var(--coral));
}

.margin-thread__stick-foot-tag {
  grid-column: 2;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 3px;
  color: var(--coral);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.app--voice-quiet .margin-thread__stick-foot-tag,
.app--voice-quiet .margin-thread__stick-foot-rule { color: var(--blue); }
.app--voice-human .margin-thread__stick-foot-tag,
.app--voice-human .margin-thread__stick-foot-rule { color: var(--coral); }
.app--voice-bold .margin-thread__stick-foot-tag,
.app--voice-bold .margin-thread__stick-foot-rule { color: var(--acid); }

.margin-thread__list {
  position: relative;
  display: grid;
  gap: clamp(8px, 1vw, 12px);
  margin: 0;
  padding: 0 0 0 clamp(8px, 1.2vw, 14px);
  border-left: 1px dashed rgba(146, 186, 255, .12);
  list-style: none;
  pointer-events: auto;
  min-width: 0;
}

.margin-thread__item {
  position: relative;
  margin: 0;
}

.margin-thread__item::before {
  content: '';
  position: absolute;
  left: calc(clamp(8px, 1.2vw, 14px) * -1 - 1px);
  top: 50%;
  width: 6px;
  height: 1px;
  background: var(--muted);
  opacity: .35;
  transform: translateY(-50%);
  transition: width .35s var(--ease), opacity .35s var(--ease), background .45s var(--ease);
}

.margin-thread__item.is-active::before {
  width: 12px;
  opacity: 1;
  background: var(--coral);
}

.app--voice-quiet .margin-thread__item.is-active::before { background: var(--blue); }
.app--voice-bold .margin-thread__item.is-active::before { background: var(--acid); }

.margin-thread__link {
  position: relative;
  display: grid;
  grid-template-columns: minmax(20px, auto) minmax(0, 1fr) auto;
  align-items: baseline;
  gap: clamp(6px, .8vw, 10px);
  padding: 4px 6px 4px 0;
  color: var(--muted);
  text-decoration: none;
  transition: color .35s var(--ease), padding-left .35s var(--ease-out);
}

.margin-thread__link:hover,
.margin-thread__link:focus-visible {
  color: var(--paper);
  padding-left: 4px;
}

.margin-thread__num {
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
  opacity: .65;
  transition: opacity .35s var(--ease), color .45s var(--ease);
}

.margin-thread__item.is-active .margin-thread__num {
  color: var(--coral);
  opacity: 1;
}

.app--voice-quiet .margin-thread__item.is-active .margin-thread__num { color: var(--blue); }
.app--voice-bold .margin-thread__item.is-active .margin-thread__num { color: var(--acid); }

.margin-thread__copy {
  display: grid;
  gap: 2px;
  min-width: 0;
  max-width: 0;
  overflow: hidden;
  opacity: 0;
  transform: translateX(-6px);
  transition: max-width .45s var(--ease-out), opacity .35s var(--ease), transform .45s var(--ease-out);
}

.margin-thread__link:hover .margin-thread__copy,
.margin-thread__link:focus-visible .margin-thread__copy,
.margin-thread__item.is-active .margin-thread__copy {
  max-width: 220px;
  opacity: 1;
  transform: translateX(0);
}

.margin-thread__label {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1vw, 14px);
  letter-spacing: -.01em;
  line-height: 1.15;
  color: var(--paper);
  text-transform: none;
  white-space: nowrap;
}

.margin-thread__hint {
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}

.margin-thread__corner {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  color: var(--muted);
  opacity: .35;
  transition: transform .35s var(--ease-out), opacity .35s var(--ease), color .4s var(--ease);
}

.margin-thread__link:hover .margin-thread__corner,
.margin-thread__link:focus-visible .margin-thread__corner,
.margin-thread__item.is-active .margin-thread__corner {
  opacity: 1;
  color: var(--coral);
  transform: translateX(2px);
}

.app--voice-quiet .margin-thread__link:hover .margin-thread__corner,
.app--voice-quiet .margin-thread__link:focus-visible .margin-thread__corner,
.app--voice-quiet .margin-thread__item.is-active .margin-thread__corner { color: var(--blue); }

.app--voice-bold .margin-thread__link:hover .margin-thread__corner,
.app--voice-bold .margin-thread__link:focus-visible .margin-thread__corner,
.app--voice-bold .margin-thread__item.is-active .margin-thread__corner { color: var(--acid); }

@media (prefers-reduced-motion: reduce) {
  .margin-thread {
    animation: none !important;
    opacity: 1;
  }

  .margin-thread__stick-rail-fill {
    transition: none !important;
  }
}

@keyframes marginThreadIn {
  0% { opacity: 0; transform: translateX(8px); }
  100% { opacity: 1; transform: translateX(0); }
}

@media (max-width: 1180px) {
  .margin-thread {
    display: none;
  }
}

.margin-thread--mobile {
  display: none;
}

@media (max-width: 1180px) {
  .margin-thread--mobile {
    position: relative;
    display: block;
    width: min(100%, 1440px);
    margin: clamp(20px, 2.4vw, 32px) auto clamp(28px, 3.4vw, 44px);
    padding: 14px var(--gutter) 16px;
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
    background:
      radial-gradient(circle at 0% 0%, rgba(146, 186, 255, .05), transparent 60%),
      linear-gradient(180deg, rgba(14, 18, 28, .25), rgba(14, 18, 28, .45));
    opacity: 1;
    animation: none;
    pointer-events: auto;
  }

  .margin-thread--mobile .margin-thread__stick {
    display: none;
  }

  .margin-thread--mobile .margin-thread__list {
    display: flex;
    align-items: stretch;
    gap: 0;
    padding: 0;
    border-left: 0;
    overflow-x: auto;
    scrollbar-width: none;
    -ms-overflow-style: none;
    scroll-snap-type: x proximity;
    mask-image: linear-gradient(90deg, transparent 0, black 18px, black calc(100% - 28px), transparent 100%);
  }

  .margin-thread--mobile .margin-thread__list::-webkit-scrollbar {
    display: none;
  }

  .margin-thread--mobile .margin-thread__item {
    flex: 0 0 auto;
    margin: 0;
    scroll-snap-align: center;
  }

  .margin-thread--mobile .margin-thread__item::before {
    display: none;
  }

  .margin-thread--mobile .margin-thread__link {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    gap: 8px;
    padding: 6px 12px 7px;
    border: 1px solid var(--line);
    background: rgba(20, 26, 38, .35);
    color: var(--muted);
    white-space: nowrap;
    transition: color .3s var(--ease), border-color .3s var(--ease), background .3s var(--ease);
  }

  .margin-thread--mobile .margin-thread__link:hover,
  .margin-thread--mobile .margin-thread__link:focus-visible {
    color: var(--paper);
    border-color: rgba(216, 255, 98, .35);
    padding-left: 12px;
  }

  .margin-thread--mobile .margin-thread__item.is-active .margin-thread__link {
    color: var(--coral);
    border-color: var(--coral);
    background: rgba(255, 118, 95, .07);
  }

  .app--voice-quiet .margin-thread--mobile .margin-thread__item.is-active .margin-thread__link {
    color: var(--blue);
    border-color: var(--blue);
  }

  .app--voice-bold .margin-thread--mobile .margin-thread__item.is-active .margin-thread__link {
    color: var(--acid);
    border-color: var(--acid);
  }

  .margin-thread--mobile .margin-thread__num {
    display: inline-grid;
    place-items: center;
    width: 20px;
    height: 20px;
    border: 1px solid currentColor;
    border-radius: 50%;
    font-family: var(--serif);
    font-style: italic;
    font-size: 11px;
    letter-spacing: 0;
    opacity: .85;
  }

  .margin-thread--mobile .margin-thread__item.is-active .margin-thread__num {
    background: currentColor;
    color: var(--night);
  }

  .margin-thread--mobile .margin-thread__copy {
    max-width: none;
    opacity: 1;
    transform: none;
    display: grid;
    gap: 0;
  }

  .margin-thread--mobile .margin-thread__label {
    font-family: var(--serif);
    font-style: italic;
    font-size: 13px;
    line-height: 1;
  }

  .margin-thread--mobile .margin-thread__hint {
    display: none;
  }

  .margin-thread--mobile .margin-thread__corner {
    display: none;
  }
}


/* ────────────────────────────────────────────────────────────
   INK DUST · ambient motes drifting up from the press
   ──────────────────────────────────────────────────────────── */

.ink-dust {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  mix-blend-mode: screen;
  opacity: .55;
}

@media (prefers-reduced-motion: reduce) {
  .ink-dust {
    display: none;
  }
}

/* ────────────────────────────────────────────────────────────
   INK TRAIL · a quiet flourish that follows the cursor
   ──────────────────────────────────────────────────────────── */

.ink-trail {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  z-index: 7;
  pointer-events: none;
  mix-blend-mode: screen;
  opacity: .9;
  display: block;
}

@media (prefers-reduced-motion: reduce) {
  .ink-trail {
    display: none;
  }
}

@media (hover: none) {
  .ink-trail {
    display: none;
  }
}


/* ────────────────────────────────────────────────────────────
   READING FOLIO · the running footer that records the page state
   ──────────────────────────────────────────────────────────── */

.reading-folio {
  width: min(100%, 1440px);
  margin: clamp(40px, 6vw, 80px) auto 0;
  padding: clamp(28px, 4vw, 48px) var(--gutter) clamp(28px, 3.6vw, 44px);
  border-top: 1px solid var(--line);
  background:
    radial-gradient(circle at 12% 100%, rgba(216, 255, 98, .05), transparent 36%),
    radial-gradient(circle at 88% 0%, rgba(255, 118, 95, .04), transparent 40%),
    linear-gradient(180deg, rgba(28, 36, 52, .32), rgba(14, 20, 32, .48));
  box-shadow:
    inset 0 1px 0 rgba(146, 186, 255, .05),
    0 -22px 60px -42px rgba(0, 0, 0, .35);
}

.reading-folio__plate {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 0 0 clamp(18px, 2.4vw, 28px);
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.reading-folio__plate-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 12%, var(--line) 88%, transparent);
}

.reading-folio__plate-tag {
  flex: 0 0 auto;
}

.reading-folio__row {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(12px, 1.6vw, 22px);
  margin: 0;
  padding: 0;
  list-style: none;
}

.reading-folio__cell {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: clamp(14px, 1.8vw, 22px) clamp(14px, 1.8vw, 22px);
  border: 1px solid var(--line);
  border-radius: 1px;
  background:
    radial-gradient(circle at 0 0%, rgba(216, 255, 98, .03), transparent 60%),
    rgba(20, 26, 38, .55);
  transition: border-color .45s var(--ease), background .45s var(--ease);
}

.reading-folio__cell + .reading-folio__cell::before {
  position: absolute;
  top: 18%;
  bottom: 18%;
  left: calc(clamp(12px, 1.6vw, 22px) * -1 - 1px);
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 14%, var(--line) 86%, transparent);
  content: '';
  pointer-events: none;
}

.reading-folio__cell:hover {
  border-color: rgba(216, 255, 98, .3);
}

.reading-folio__cell-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.reading-folio__cell-tag::before {
  content: '';
  display: block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  opacity: .55;
}

.reading-folio__cell-main {
  display: flex;
  align-items: baseline;
  gap: 12px;
  flex-wrap: wrap;
}

.reading-folio__cell-num {
  color: var(--coral);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(28px, 3.2vw, 40px);
  letter-spacing: -.04em;
  line-height: 1;
  transition: color .45s var(--ease);
}

.reading-folio__cell-name {
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(17px, 1.7vw, 22px);
  font-style: italic;
  letter-spacing: -.02em;
  line-height: 1.1;
}

.reading-folio__cell-mark {
  display: inline-grid;
  width: clamp(34px, 3vw, 40px);
  height: clamp(34px, 3vw, 40px);
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  letter-spacing: -.02em;
  line-height: 1;
  transition: background .4s var(--ease), color .4s var(--ease);
}

.reading-folio__cell-mark--m3 { color: var(--acid); }
.reading-folio__cell-mark--good { color: var(--coral); }
.reading-folio__cell-mark--yet { color: var(--blue); }

.reading-folio__cell-voice {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 10px 6px;
  border: 1px solid currentColor;
  border-radius: 1px;
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .18em;
  text-transform: uppercase;
  transition: background .45s var(--ease), color .45s var(--ease);
}

.reading-folio__cell-voice--quiet { color: var(--blue); }
.reading-folio__cell-voice--human { color: var(--coral); }
.reading-folio__cell-voice--bold { color: var(--acid); }

.reading-folio__cell-voice::before {
  content: '';
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px currentColor;
  opacity: 1;
  filter: blur(0);
}

.app--voice-quiet .reading-folio__cell-voice--quiet { background: rgba(155, 188, 255, .12); }
.app--voice-human .reading-folio__cell-voice--human { background: rgba(255, 118, 95, .12); }
.app--voice-bold .reading-folio__cell-voice--bold { background: rgba(216, 255, 106, .12); }

.reading-folio__cell-state {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.4vw, 19px);
  letter-spacing: -.01em;
}

.reading-folio__cell-state-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ink-mist);
  box-shadow: 0 0 0 2px rgba(0, 0, 0, .35);
  transition: background .45s var(--ease), box-shadow .55s var(--ease);
}

.reading-folio__cell-state.is-open {
  color: var(--coral);
}

.reading-folio__cell-state.is-open .reading-folio__cell-state-dot {
  background: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 118, 95, .16), 0 0 12px rgba(255, 118, 95, .35);
  animation: composePulse 2.4s var(--ease) infinite;
}

.reading-folio__sign {
  display: block;
  width: clamp(160px, 24vw, 240px);
  height: 14px;
  margin: clamp(20px, 2.4vw, 28px) auto 0;
  color: var(--coral);
  opacity: .7;
}

.reading-folio__sign-stroke {
  stroke-dashoffset: 100;
  animation: titleRuleDraw 1.4s var(--ease-out) .25s forwards;
}

.reading-folio__sign-dot {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: titleRuleDot .4s var(--ease-spring) 1.55s forwards;
}

@media (max-width: 880px) {
  .reading-folio__row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .reading-folio__cell + .reading-folio__cell::before {
    display: none;
  }
}

@media (max-width: 540px) {
  .reading-folio {
    padding: 28px 18px 24px;
  }

  .reading-folio__row {
    grid-template-columns: 1fr;
  }

  .reading-folio__cell {
    padding: 14px 16px;
  }

  .reading-folio__cell-num {
    font-size: 26px;
  }

  .reading-folio__cell-name {
    font-size: 16px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .reading-folio__sign-stroke,
  .reading-folio__sign-dot {
    animation: none !important;
    stroke-dashoffset: 0 !important;
    opacity: 1 !important;
  }

  .reading-folio__cell-state-dot {
    animation: none !important;
  }
}

/* ────────────────────────────────────────────────────────────
   ITERATION 234 · refinement on the title page and bound page
   ──────────────────────────────────────────────────────────── */

/* Inherit a slightly tighter, hand-drawn read on the title baseline. */

.hero__spread::before {
  inset: 7px;
  border-color: rgba(146, 186, 255, .085);
}

.hero__spread::after {
  inset: 17px;
  border-color: rgba(243, 236, 214, .035);
}

.hero__copy {
  perspective-origin: 50% 10%;
  transform-style: preserve-3d;
}

.hero__lead-in {
  position: relative;
}

.hero__lead-in::before,
.hero__lead-in::after {
  content: '';
  position: absolute;
  top: 50%;
  width: 6px;
  height: 1px;
  background: currentColor;
  opacity: .5;
  transform: translateY(-50%);
}

.hero__lead-in::before { left: -16px; }
.hero__lead-in::after { right: -16px; }

/* Gentle ink-stain pulse propagated when the voice is reset. */

.app--voice-quiet .hero__compose-rule::before,
.app--voice-human .hero__compose-rule::before,
.app--voice-bold .hero__compose-rule::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, currentColor 0%, transparent 60%);
  opacity: 0;
  pointer-events: none;
  animation: heroComposePulse 1.2s var(--ease-out);
}

@keyframes heroComposePulse {
  0% { opacity: 0; transform: scale(.6); }
  35% { opacity: .14; transform: scale(.8); }
  100% { opacity: 0; transform: scale(1.4); }
}

@media (prefers-reduced-motion: reduce) {
  .app--voice-quiet .hero__compose-rule::before,
  .app--voice-human .hero__compose-rule::before,
  .app--voice-bold .hero__compose-rule::before {
    animation: none !important;
  }
}

/* Marked words are drawn with a hand-set underline that traces itself
   when the word is selected, hovered, or focused. The mark lives beneath
   the type rather than around it, so the word reads as integral part of
   the question rather than a separate button. */

.title-token {
  position: relative;
  display: inline-block;
  padding: 0 .04em .12em;
  background: transparent;
  font-family: inherit;
  font-style: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  line-height: inherit;
  text-shadow: none;
  cursor: pointer;
  transition:
    color .35s var(--ease),
    background-color .35s var(--ease),
    border-color .35s var(--ease),
    text-shadow .45s var(--ease);
}

.title-token__text {
  position: relative;
  z-index: 1;
}

.title-token__mark {
  position: absolute;
  left: -.04em;
  right: -.04em;
  bottom: -.14em;
  width: calc(100% + .08em);
  height: 14px;
  color: var(--coral);
  pointer-events: none;
  z-index: 0;
}

.title-token--m3 .title-token__mark { color: var(--acid); }
.title-token--good .title-token__mark { color: var(--coral); }
.title-token--yet .title-token__mark { color: var(--blue); }

.title-token__stroke {
  stroke-dashoffset: 100;
  transition: stroke-dashoffset .85s var(--ease-out);
}

.title-token__tail {
  fill: currentColor;
  opacity: 0;
  transform-origin: 196px 6px;
  transform: scale(.4);
  transition: opacity .35s var(--ease) .25s, transform .55s var(--ease-spring) .25s;
}

.title-token__glyph {
  position: absolute;
  left: -.18em;
  top: -.12em;
  width: .9em;
  height: .9em;
  color: currentColor;
  opacity: 0;
  pointer-events: none;
  transform: translateY(2px) rotate(-4deg);
  transition: opacity .4s var(--ease), transform .55s var(--ease-spring);
  z-index: 2;
}

.title-token__glyph svg {
  width: 100%;
  height: 100%;
  display: block;
}

.title-token--m3 { color: var(--acid); }
.title-token--good { color: var(--paper); }
.title-token--yet { color: var(--coral); }

.title-token:hover,
.title-token:focus-visible,
.title-token.is-selected {
  color: var(--paper);
  text-shadow: 0 0 .4em rgba(216, 240, 106, .22);
}

.title-token--good:hover,
.title-token--good:focus-visible,
.title-token--good.is-selected {
  color: var(--paper);
  text-shadow: 0 0 .4em rgba(255, 118, 95, .26);
}

.title-token--yet:hover,
.title-token--yet:focus-visible,
.title-token--yet.is-selected {
  color: var(--coral);
  text-shadow: 0 0 .4em rgba(155, 188, 255, .32);
}

.title-token:hover .title-token__stroke,
.title-token:focus-visible .title-token__stroke,
.title-token.is-selected .title-token__stroke {
  stroke-dashoffset: 0;
}

.title-token:hover .title-token__tail,
.title-token:focus-visible .title-token__tail,
.title-token.is-selected .title-token__tail {
  opacity: 1;
  transform: scale(1);
}

.title-token:hover .title-token__glyph,
.title-token:focus-visible .title-token__glyph,
.title-token.is-selected .title-token__glyph {
  opacity: .85;
  transform: translateY(0) rotate(0);
}

@media (prefers-reduced-motion: reduce) {
  .title-token__stroke,
  .title-token__tail,
  .title-token__glyph {
    transition: none !important;
  }

  .title-token__stroke { stroke-dashoffset: 0; }
  .title-token__tail { opacity: 1; transform: none; }
  .title-token__glyph { opacity: .85; transform: none; }
}

/* When a marked word is active on the page, the hairline below the
   title picks up that word's tone subtly. */

.app--word-m3 .hero__compose-rule { color: var(--acid); }
.app--word-good .hero__compose-rule { color: var(--coral); }
.app--word-yet .hero__compose-rule { color: var(--blue); }

/* ────────────────────────────────────────────────────────────
   PUBLICATION MARK · a centered, three-column imprint that
   closes the title with the press mark, voice, and date.
   ──────────────────────────────────────────────────────────── */

.publication-mark {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.6vw, 18px);
  width: clamp(360px, 88%, 1080px);
  margin: clamp(12px, 1.6vw, 18px) auto 0;
  color: var(--pm-tone, var(--coral));
  opacity: 0;
  animation: publicationMarkIn .85s var(--ease-out) 1.05s forwards;
}

.publication-mark--in-hero {
  margin-top: clamp(8px, 1.2vw, 12px);
}

.publication-mark::before,
.publication-mark::after {
  content: '';
  flex: 1;
  height: 1px;
  background: currentColor;
  opacity: .25;
}

.publication-mark::before {
  background: linear-gradient(to right, transparent, currentColor);
}

.publication-mark::after {
  background: linear-gradient(to left, transparent, currentColor);
}

@keyframes publicationMarkIn {
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .publication-mark {
    animation: none !important;
    opacity: 1;
  }
}

.publication-mark__rule {
  display: block;
  flex: 1;
  height: 1px;
  max-width: 80px;
  background: currentColor;
  opacity: .3;
}

.publication-mark__rule--left {
  background: linear-gradient(to right, transparent, currentColor);
}

.publication-mark__rule--right {
  background: linear-gradient(to left, transparent, currentColor);
}

.publication-mark__core {
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.4vw, 16px);
  flex: 0 0 auto;
}

.publication-mark__core-mark {
  display: inline-grid;
  place-items: center;
  width: clamp(28px, 3vw, 36px);
  height: clamp(28px, 3vw, 36px);
  color: currentColor;
}

.publication-mark__core-row {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(8px, 1.2vw, 14px);
  flex-wrap: wrap;
  font-family: var(--mono);
  font-size: clamp(8px, .75vw, 9.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.publication-mark__press {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  color: var(--paper);
  font-family: var(--mono);
}

.publication-mark__press-mark {
  font-weight: 600;
  letter-spacing: .22em;
}

.publication-mark__press-folio {
  color: currentColor;
}

.publication-mark__press-sep {
  color: var(--muted);
  opacity: .6;
}

.publication-mark__voice {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 3px 8px 4px;
  border: 1px solid currentColor;
  border-radius: 1px;
  color: currentColor;
}

.publication-mark__voice-letter {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 10px;
  letter-spacing: 0;
  text-transform: none;
}

.publication-mark__voice-name {
  font-size: inherit;
  letter-spacing: .18em;
}

.publication-mark__date {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .95vw, 13px);
  letter-spacing: 0;
  text-transform: none;
}

.publication-mark__date-tag {
  color: currentColor;
  font-family: var(--mono);
  font-style: normal;
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.publication-mark__date-text {
  white-space: nowrap;
}

.publication-mark__sweep {
  position: absolute;
  left: 50%;
  bottom: -16px;
  width: clamp(160px, 22vw, 240px);
  height: 10px;
  color: currentColor;
  opacity: .55;
