   ──────────────────────────────────────────────────────────── */

.reading-folio__plate-mark {
  display: inline-block;
  margin: 0 6px;
  color: var(--coral);
  font-family: var(--serif);
  font-style: normal;
  font-size: 12px;
  letter-spacing: 0;
  opacity: .55;
}

.reading-folio__plate-mark--alt {
  transform: scaleX(-1);
}

.reading-folio__cell {
  position: relative;
}

.reading-folio__cell-foot {
  display: block;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px dashed var(--line-soft);
  color: var(--muted);
  font-family: var(--serif);
  font-size: clamp(11px, .9vw, 12px);
  font-style: italic;
  letter-spacing: 0;
