/* ────────────────────────────────────────────────────────────
   HERO VOICE-ROW · refined voice tabs: more confident active
   state, quieter non-active state, tighter alignment.
   ──────────────────────────────────────────────────────────── */

.hero__voice-tab.is-active {
  background:
    linear-gradient(180deg, rgba(216, 255, 106, .05), rgba(216, 255, 106, 0)),
    rgba(0, 0, 0, .22);
  box-shadow: inset 0 0 0 1px rgba(216, 255, 106, .08);
}

.app--voice-quiet .hero__voice-tab--quiet.is-active {
  background:
    linear-gradient(180deg, rgba(155, 188, 255, .08), rgba(155, 188, 255, 0)),
    rgba(0, 0, 0, .22);
  box-shadow: inset 0 0 0 1px rgba(155, 188, 255, .14);
}

.app--voice-human .hero__voice-tab--human.is-active {
  background:
    linear-gradient(180deg, rgba(255, 118, 95, .08), rgba(255, 118, 95, 0)),
    rgba(0, 0, 0, .22);
  box-shadow: inset 0 0 0 1px rgba(255, 118, 95, .14);
}

.app--voice-bold .hero__voice-tab--bold.is-active {
  background:
    linear-gradient(180deg, rgba(216, 255, 106, .1), rgba(216, 255, 106, 0)),
