  box-shadow: inset 0 0 0 1px rgba(216, 255, 106, .18);
}

.hero__voice-tab-letter {
  transition: transform .4s var(--ease-spring), background .35s var(--ease), color .35s var(--ease);
}

.hero__voice-tab.is-active .hero__voice-tab-letter {
  transform: scale(1.08);
}

/* Quiet hairline below the active voice name for emphasis. */
.hero__voice-tab.is-active .hero__voice-tab-name::after {
