  display: inline-block;
  margin-left: 8px;
  width: 0;
  height: 1px;
  background: currentColor;
  opacity: .85;
  vertical-align: middle;
  animation: voiceTabLead 1s var(--ease-out) .15s forwards;
}

@keyframes voiceTabLead {
  0% { width: 0; opacity: 0; }
  100% { width: 24px; opacity: .85; }
}

@media (prefers-reduced-motion: reduce) {
  .hero__voice-tab.is-active .hero__voice-tab-name::after { animation: none !important; width: 24px; opacity: .85; }
  .hero__voice-tab-letter { transform: none !important; }
}

/* ────────────────────────────────────────────────────────────
   ANNOTATION RIBBON · refine the card and the connector for a
   cleaner, more editorial register.
   ──────────────────────────────────────────────────────────── */

.annotation-ribbon__card {
  padding: 18px 16px 16px;
  border-top: 0;
  border-left: 3px solid currentColor;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(14, 20, 32, .62));
  box-shadow: inset 0 0 0 1px rgba(146, 186, 255, .04);
}

.annotation-ribbon__item.is-active .annotation-ribbon__card {
  background:
    linear-gradient(180deg, rgba(36, 46, 66, .58), rgba(20, 28, 42, .76));
}

.annotation-ribbon__card .annotation-ribbon__gloss {
  border-left: 1px solid rgba(146, 186, 255, .1);
  padding-left: 10px;
  font-style: italic;
}

.annotation-ribbon__card .annotation-ribbon__gloss-mark {
  position: absolute;
  left: -10px;
  top: 0;
  background: linear-gradient(180deg, rgba(28, 36, 52, .85), rgba(14, 20, 32, .85));
  padding: 2px 4px 2px 0;
  font-size: 13px;
}

/* Reset the rule corner we no longer want. */
