/* ────────────────────────────────────────────────────────────
   COMPOSITION SIGNATURE · a tasteful press mark that sits
   between the hero and the marks section, summarizing what
   the page just composed.
   ──────────────────────────────────────────────────────────── */

.app--voice-quiet { --compose-tone: var(--blue); }
.app--voice-human { --compose-tone: var(--coral); }
.app--voice-bold { --compose-tone: var(--acid); }
.press-stamp {
  display: block;
  color: var(--coral);
  transition: color .5s var(--ease), transform .7s var(--ease-spring);
}

.press-stamp--quiet { color: var(--blue); }
.press-stamp--human { color: var(--coral); }
.press-stamp--bold {
  color: var(--acid);
  transform: rotate(-3deg);
}

.answer-reveal__seal .press-stamp {
  animation: stampPress 1.2s var(--ease-spring) .35s backwards;
}

@keyframes stampPress {
  0% { opacity: 0; transform: scale(1.4) rotate(-18deg); }
  60% { opacity: .95; transform: scale(.95) rotate(2deg); }
  100% { opacity: .95; transform: scale(1) rotate(-4deg); }
}

.answer-reveal__wax-drop {
  position: absolute;
  top: 64%;
  left: 18%;
  width: 18px;
  height: 26px;
  pointer-events: none;
  opacity: 0;
}

.answer-reveal__wax-drop-bead {
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 6px;
  height: 8px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  background: currentColor;
  transform: translate(-50%, 0) scale(.6);
  transform-origin: 50% 0;
  filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, .25));
}

.answer-reveal__wax-drop-wisp {
  position: absolute;
  top: 0;
  left: 50%;
  width: 2px;
  height: 22px;
  background: linear-gradient(180deg, transparent, currentColor 60%);
  transform: translateX(-50%) scaleY(.4);
  transform-origin: 50% 0;
  opacity: .55;
}

.answer-reveal.is-open .answer-reveal__wax-drop {
  animation: waxDropFall .55s var(--ease) 1.45s backwards;
}

@keyframes waxDropFall {
  0% { opacity: 0; transform: translateY(-12px); }
  40% { opacity: 1; transform: translateY(0); }
  55% { transform: translateY(2px); }
  70% { transform: translateY(0); }
  100% { opacity: 1; transform: translateY(2px); }
}

.answer-reveal.is-open .answer-reveal__wax-drop-wisp {
  animation: waxWispStretch .55s var(--ease) 1.45s backwards;
}

@keyframes waxWispStretch {
  0% { transform: translateX(-50%) scaleY(.2); opacity: 0; }
  35% { transform: translateX(-50%) scaleY(1); opacity: .7; }
  100% { transform: translateX(-50%) scaleY(.6); opacity: .35; }
}

@media (prefers-reduced-motion: reduce) {
  .answer-reveal__wax-drop,
  .answer-reveal__wax-drop-bead,
  .answer-reveal__wax-drop-wisp {
    animation: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

