/* ────────────────────────────────────
   HERO EPIGRAPH · a delicate editorial
   tone-setter above the folio mark. Two
   small ornament stars flank a single
   italic line that names the page's
   matter. It is the page's own preface.
   ──────────────────────────────────── */

.hero__epigraph {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, 1vw, 14px);
  margin: 0 auto clamp(14px, 1.6vw, 22px);
  padding: 0;
  max-width: 760px;
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12.5px, 1.15vw, 15px);
  letter-spacing: -.005em;
  line-height: 1.35;
  text-align: center;
  opacity: 0;
  animation: traceFade .7s var(--ease-out) .12s forwards;
}

.hero__epigraph em {
  font-style: italic;
  color: var(--paper);
  text-wrap: balance;
}

.hero__epigraph-mark {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  color: var(--coral);
  opacity: .85;
  transition: color .5s var(--ease), transform .6s var(--ease-spring);
  animation: heroEpigraphMarkPulse 4s var(--ease) 1.4s infinite;
  transform-origin: center;
}

.hero__epigraph-mark--alt {
  animation-delay: 1.6s;
}

.app--voice-quiet .hero__epigraph-mark { color: var(--blue); }
.app--voice-human .hero__epigraph-mark { color: var(--coral); }
.app--voice-bold .hero__epigraph-mark { color: var(--acid); }

.hero__epigraph-rule {
  display: block;
  flex: 0 0 auto;
  width: clamp(36px, 7vw, 84px);
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line));
  transform-origin: left center;
  animation: heroEpigraphRuleDraw .9s var(--ease-out) .35s backwards;
}

.hero__epigraph-rule--end {
  background: linear-gradient(to left, transparent, var(--line));
  transform-origin: right center;
}

@keyframes heroEpigraphMarkPulse {
  0%, 100% { transform: rotate(0deg) scale(1); opacity: .85; }
  50% { transform: rotate(12deg) scale(1.06); opacity: 1; }
}

@keyframes heroEpigraphRuleDraw {
  0% { transform: scaleX(0); opacity: 0; }
  100% { transform: scaleX(1); opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
