}

.hero__edition-mark {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(14px, 1.8vw, 22px);
  margin: 0;
  padding: 0;
  color: var(--mist);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .24em;
  text-transform: uppercase;
  opacity: 0;
  animation: traceFade .85s var(--ease-out) .05s forwards;
}

.hero__edition-mark-rule {
  display: block;
  width: clamp(14px, 2vw, 28px);
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 60%, var(--line) 100%);
