.app--voice-quiet .hero__edition-mark-line em { color: var(--blue); }
.app--voice-human .hero__edition-mark-line em { color: var(--coral); }
.app--voice-bold .hero__edition-mark-line em { color: var(--acid); }

.hero__edition-mark-line--soft {
