  }
}

.hero__lead-in-line {
  display: block;
  width: clamp(28px, 5vw, 56px);
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor, transparent);
}

.hero__lead-in-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.hero__lead-in-tag::before {
  content: '';
