  font-weight: 400;
  letter-spacing: -.096em;
  word-spacing: -.04em;
  line-height: .86;
  text-wrap: balance;
  text-rendering: geometricPrecision;
  font-feature-settings: 'kern' 1, 'liga' 1, 'dlig' 1, 'onum' 1;
  text-shadow:
    0 1px 0 rgba(0, 0, 0, .42),
