}

/* ────────────────────────────────────
   HERO FLOURISH · a single signature
   calligraphic sweep that runs beneath
   the title and threads the three marked
   words. It is the page's own gesture,
   drawn once on arrival and held quiet.
   ──────────────────────────────────── */

.hero__flourish {
  display: block;
  width: clamp(540px, 92%, 1200px);
  height: clamp(48px, 6vw, 72px);
  margin: clamp(6px, 1vw, 14px) auto clamp(8px, 1.2vw, 18px);
  color: var(--flourish-tone, var(--coral));
  opacity: 0;
  animation: heroFlourishIn .55s var(--ease-out) .55s forwards;
  transition: color .55s var(--ease);
}

.hero__flourish-group {
  transition: color .55s var(--ease);
}

.hero__flourish-trail,
.hero__flourish-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: heroFlourishDraw 1.6s var(--ease-out) .85s forwards;
}

.hero__flourish-stroke {
  animation-delay: 1s;
}

.hero__flourish-tail {
  opacity: 0;
  animation: heroFlourishTail .55s var(--ease-out) 2.25s forwards;
}

.hero__flourish-tail--end { animation-delay: 2.5s; }

.hero__flourish-node {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: heroFlourishNodeIn .55s var(--ease-spring) forwards;
}

.hero__flourish-node--m3 { animation-delay: 1.15s; }
.hero__flourish-node--good { animation-delay: 1.4s; }
.hero__flourish-node--yet { animation-delay: 1.65s; }

.hero__flourish-node-pulse {
  transform-box: fill-box;
  transform-origin: center;
  animation: heroFlourishPulse 3.6s var(--ease) infinite;
}

.hero__flourish-node--m3 .hero__flourish-node-pulse { animation-delay: 2.4s; }
.hero__flourish-node--good .hero__flourish-node-pulse { animation-delay: 2.6s; }
.hero__flourish-node--yet .hero__flourish-node-pulse { animation-delay: 2.8s; }

.hero__flourish-node--m3 .hero__flourish-node-pulse,
.hero__flourish-node--m3 .hero__flourish-node-ring,
.hero__flourish-node--m3 .hero__flourish-node-bead { color: var(--acid); }
.hero__flourish-node--good .hero__flourish-node-pulse,
.hero__flourish-node--good .hero__flourish-node-ring,
.hero__flourish-node--good .hero__flourish-node-bead { color: var(--coral); }
.hero__flourish-node--yet .hero__flourish-node-pulse,
.hero__flourish-node--yet .hero__flourish-node-ring,
.hero__flourish-node--yet .hero__flourish-node-bead { color: var(--blue); }

.hero__flourish-label {
  opacity: 0;
  animation: heroFlourishLabel .55s var(--ease-out) forwards;
  animation-delay: 2s;
}

.hero__flourish-node--good .hero__flourish-label { animation-delay: 2.1s; }
.hero__flourish-node--yet .hero__flourish-label { animation-delay: 2.2s; }

.hero__flourish-node.is-active .hero__flourish-node-ring {
  opacity: 1;
}

.hero__flourish-node.is-active .hero__flourish-node-bead {
  filter: drop-shadow(0 0 6px currentColor);
}

@keyframes heroFlourishIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes heroFlourishDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes heroFlourishTail {
  from { opacity: 0; transform: translateX(-4px); }
  to { opacity: .85; transform: translateX(0); }
}

@keyframes heroFlourishNodeIn {
  from { opacity: 0; transform: scale(.4); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes heroFlourishPulse {
  0% { opacity: .35; transform: scale(.85); }
  60% { opacity: 0; transform: scale(1.6); }
  100% { opacity: 0; transform: scale(1.6); }
}

@keyframes heroFlourishLabel {
  from { opacity: 0; transform: translateY(2px); }
  to { opacity: .65; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .hero__flourish { animation: none !important; opacity: 1; }
  .hero__flourish-trail,
  .hero__flourish-stroke { stroke-dashoffset: 0 !important; animation: none !important; }
  .hero__flourish-tail { opacity: .85 !important; animation: none !important; }
  .hero__flourish-node { animation: none !important; opacity: 1 !important; transform: none !important; }
  .hero__flourish-node-pulse { animation: none !important; }
  .hero__flourish-label { animation: none !important; opacity: .65 !important; }
}

/* ────────────────────────────────────
   HERO PULL · a single short editorial
   motto that closes the body and opens
   the page-turn. Two thin printer's
   rules flank the line; the second clause
   sits in a softer tone so the line reads
   as a single breath.
   ──────────────────────────────────── */

.hero__pull {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(12px, 1.8vw, 22px);
  margin: clamp(10px, 1.4vw, 18px) auto clamp(20px, 2.4vw, 32px);
  padding: clamp(10px, 1.3vw, 16px) 0;
  max-width: 720px;
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.3vw, 17px);
  letter-spacing: -.005em;
  line-height: 1;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .9s var(--ease-out) 1.05s, transform .9s var(--ease-out) 1.05s;
}

.hero__body.is-in-view .hero__pull {
  opacity: 1;
  transform: translateY(0);
}

.hero__pull-rule {
  display: block;
  flex: 1;
  max-width: 96px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line));
}

.hero__pull-rule--end {
  background: linear-gradient(to left, transparent, var(--line));
}

.hero__pull-text {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(6px, .7vw, 10px);
  color: var(--mist);
  white-space: nowrap;
  text-align: center;
}

.hero__pull-motto {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(15px, 1.55vw, 20px);
  letter-spacing: -.018em;
  line-height: 1;
  text-shadow: 0 0 .04em rgba(243, 236, 214, .12);
}

.app--voice-quiet .hero__pull-motto { font-style: italic; letter-spacing: -.012em; }
.app--voice-human .hero__pull-motto { font-style: italic; letter-spacing: -.018em; }
.app--voice-bold .hero__pull-motto { font-style: italic; letter-spacing: -.028em; font-weight: 500; }

.hero__pull-divider {
  display: inline-block;
  color: var(--ink-mist);
  font-style: normal;
  font-family: var(--mono);
  font-size: clamp(10px, .9vw, 12px);
  letter-spacing: 0;
  opacity: .45;
  transform: translateY(-.06em);
}

.hero__pull-second {
  color: var(--mist);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.005em;
  opacity: .82;
}

@media (max-width: 540px) {
  .hero__pull {
    flex-wrap: wrap;
    gap: clamp(8px, 1vw, 12px);
  }

  .hero__pull-rule {
    flex: 0 0 36px;
    max-width: 36px;
  }

  .hero__pull-text {
    flex: 0 0 100%;
    order: 2;
    white-space: normal;
    line-height: 1.4;
  }

  .hero__pull-rule--end {
    order: 3;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero__pull { opacity: 1 !important; transform: none !important; transition: none !important; }
}

.hero__pull em {
  color: var(--paper);
  font-style: italic;
}

/* ────────────────────────────────────
   HERO FOLIO MARK · a single thin rule
   above the title carrying folio, voice,
   and set date. Replaces the wider
   eyebrow row, plate stamp, and edition
   mark.
   ──────────────────────────────────── */

.hero__folio-mark {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.1vw, 14px);
  width: min(100%, 720px);
  margin: 0 auto clamp(22px, 2.8vw, 42px);
  padding: 0;
  color: var(--folio-tone, var(--coral));
  opacity: 0;
  animation: traceFade .7s var(--ease-out) .08s forwards;
  transition: color .5s var(--ease);
}

.hero__folio-mark-rule {
  display: block;
  width: clamp(180px, 32vw, 340px);
  height: 6px;
  color: currentColor;
  opacity: .9;
}

.hero__folio-mark-stroke {
  stroke-dasharray: 220 220;
  stroke-dashoffset: 220;
  animation: heroFolioRuleDraw 1.4s var(--ease-out) .2s forwards;
}

@keyframes heroFolioRuleDraw {
  to { stroke-dashoffset: 0; }
}

.hero__folio-mark-row {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  justify-content: center;
  column-gap: clamp(10px, 1vw, 14px);
  row-gap: 4px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(11px, 1vw, 13px);
  font-style: italic;
  letter-spacing: -.005em;
  line-height: 1;
}

.hero__folio-mark-folio {
  color: var(--muted);
  font-family: var(--mono);
  font-style: normal;
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.hero__folio-mark-folio em {
  color: currentColor;
  font-style: italic;
  font-family: var(--serif);
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  margin-left: 2px;
}

.hero__folio-mark-bead {
  display: inline-block;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: currentColor;
  opacity: .55;
  align-self: center;
  flex: 0 0 auto;
}

.hero__folio-mark-title {
  color: var(--paper);
  font-style: italic;
}

.hero__folio-mark-voice {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  color: var(--mist);
  font-style: italic;
}

.hero__folio-mark-voice-letter {
  display: inline-grid;
  place-items: center;
  width: 13px;
  height: 13px;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: currentColor;
  font-family: var(--serif);
  font-style: italic;
  font-size: 9px;
  line-height: 1;
}

.hero__folio-mark-voice-name {
  color: var(--paper);
  font-family: var(--mono);
  font-style: normal;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.hero__folio-mark-date {
  color: var(--muted);
  font-family: var(--mono);
  font-style: normal;
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.hero__folio-mark-date em {
  color: var(--paper);
  font-style: italic;
  font-family: var(--serif);
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: -.005em;
