@media (max-width: 720px) {
  .hero__folio-mark-row {
    column-gap: 8px;
    font-size: 11px;
  }

  .hero__folio-mark-folio,
  .hero__folio-mark-voice-name,
  .hero__folio-mark-date {
    font-size: 8px;
  }
