@media (prefers-reduced-motion: reduce) {
  .hero__folio-mark-stroke {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }
}

/* ─────────────────────────────────────────────────────────────────
   PRESS MASTHEAD · the deliberate front-matter spread that opens
   the page above the title. Three tiers: a monospace topline of
   press identity tags, a centred italic display of "m³ press"
   flanked by fleurons, and a strip of four cells carrying folio,
   section, active voice, and set-today. The masthead is the first
   thing a reader sees; it earns the right to set the tone.
   ───────────────────────────────────────────────────────────────── */

.press-masthead {
  --masthead-tone: var(--coral);
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: clamp(10px, 1.2vw, 16px);
  margin: clamp(8px, 1.4vw, 18px) auto clamp(22px, 2.6vw, 38px);
  padding: clamp(14px, 1.8vw, 24px) clamp(16px, 3vw, 38px) clamp(14px, 1.6vw, 22px);
  max-width: 880px;
  color: var(--paper);
  border: 1px solid var(--line);
  background:
    radial-gradient(ellipse at 50% -10%, rgba(216, 240, 106, .05), transparent 62%),
    linear-gradient(180deg, rgba(20, 25, 38, .55), rgba(12, 16, 26, .62));
  opacity: 0;
  animation: pressMastheadIn .9s var(--ease-out) .05s forwards;
  transition: color .55s var(--ease), border-color .55s var(--ease);
}

.press-masthead--quiet { --masthead-tone: var(--blue); }
.press-masthead--human { --masthead-tone: var(--coral); }
.press-masthead--bold { --masthead-tone: var(--acid); }

@keyframes pressMastheadIn {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); }
}

.press-masthead__defs {
  position: absolute;
  inset: 0;
  width: 0;
  height: 0;
  pointer-events: none;
  visibility: hidden;
}

.press-masthead__crop {
  position: absolute;
  width: 10px;
  height: 10px;
  border-color: var(--masthead-tone);
  border-style: solid;
  border-width: 0;
  opacity: .7;
  pointer-events: none;
  transition: opacity .45s var(--ease);
}

.press-masthead__crop--tl {
  top: -1px;
  left: -1px;
  border-top-width: 1.5px;
  border-left-width: 1.5px;
}

.press-masthead__crop--tr {
  top: -1px;
  right: -1px;
  border-top-width: 1.5px;
  border-right-width: 1.5px;
}

.press-masthead__crop--bl {
  bottom: -1px;
  left: -1px;
  border-bottom-width: 1.5px;
  border-left-width: 1.5px;
}

.press-masthead__crop--br {
  bottom: -1px;
  right: -1px;
  border-bottom-width: 1.5px;
  border-right-width: 1.5px;
}

.press-masthead__topline {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  column-gap: clamp(8px, 1.1vw, 14px);
  row-gap: 6px;
  padding-bottom: clamp(6px, .9vw, 12px);
  border-bottom: 1px dashed rgba(243, 236, 214, .14);
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .82vw, 10.5px);
  font-weight: 500;
  letter-spacing: .24em;
  text-transform: uppercase;
  opacity: 0;
  animation: pressMastheadTopIn .7s var(--ease-out) .25s forwards;
}

@keyframes pressMastheadTopIn {
  from { opacity: 0; transform: translateY(-3px); }
  to { opacity: .92; }
}

.press-masthead__topline-tag {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  color: var(--mist);
  white-space: nowrap;
}

.press-masthead__topline-tag--lead,
.press-masthead__topline-tag--trail {
  color: var(--masthead-tone);
  font-weight: 600;
}

.press-masthead__topline-tag--lead em,
.press-masthead__topline-tag--trail em {
  color: inherit;
  font-style: normal;
}

.press-masthead__topline-tick {
  display: inline-block;
  width: 7px;
  height: 7px;
  border: 1px solid currentColor;
  transform: rotate(45deg);
  opacity: .8;
  flex: 0 0 auto;
}

.press-masthead__topline-tick--alt {
  margin-left: 2px;
}

.press-masthead__topline-rule {
  display: inline-block;
  width: clamp(16px, 3vw, 38px);
  height: 1px;
  background:
    linear-gradient(to right, transparent, var(--line), transparent);
  flex: 0 0 auto;
}

.press-masthead__topline-rule--mid {
  background:
    linear-gradient(to right, transparent, var(--masthead-tone), transparent);
  opacity: .55;
}

.press-masthead__plate {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.8vw, 24px);
  padding: clamp(6px, 1.4vw, 16px) 0 clamp(8px, 1.4vw, 18px);
}

.press-masthead__fleuron {
  display: inline-grid;
  place-items: center;
  width: clamp(28px, 3.4vw, 44px);
  height: clamp(28px, 3.4vw, 44px);
  color: var(--masthead-tone);
  font-family: Georgia, 'Iowan Old Style', serif;
  font-size: clamp(22px, 2.6vw, 32px);
  font-style: italic;
  line-height: 1;
  opacity: 0;
  transform: rotate(-12deg);
  transform-origin: center;
  animation: pressMastheadFleuronIn .75s var(--ease-out) .55s forwards;
  transition: color .55s var(--ease);
}

.press-masthead__fleuron--trail {
  transform: rotate(12deg);
}

@keyframes pressMastheadFleuronIn {
  from { opacity: 0; transform: rotate(-12deg) scale(.6); }
  to { opacity: .85; transform: rotate(-12deg) scale(1); }
}

.press-masthead__fleuron--trail {
  animation-name: pressMastheadFleuronInAlt;
}

@keyframes pressMastheadFleuronInAlt {
  from { opacity: 0; transform: rotate(12deg) scale(.6); }
  to { opacity: .85; transform: rotate(12deg) scale(1); }
}

.press-masthead__display {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(4px, .7vw, 8px);
  margin: 0;
  text-align: center;
}

.press-masthead__display-pre {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  color: var(--masthead-tone);
  font-family: var(--mono);
  font-size: clamp(8px, .8vw, 10px);
  font-weight: 600;
  letter-spacing: .34em;
  text-transform: uppercase;
  opacity: 0;
  animation: pressMastheadEyebrowIn .55s var(--ease-out) .75s forwards;
}

@keyframes pressMastheadEyebrowIn {
  from { opacity: 0; transform: translateY(-3px); }
  to { opacity: 1; transform: translateY(0); }
}

.press-masthead__display-pre-rule {
  display: inline-block;
  width: clamp(14px, 2.4vw, 32px);
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.press-masthead__display-pre-tag {
  white-space: nowrap;
}

.press-masthead__display-row {
  display: inline-flex;
  align-items: baseline;
  justify-content: center;
  gap: clamp(8px, 1.2vw, 18px);
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(38px, 5.4vw, 68px);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.035em;
  line-height: 1;
  opacity: 0;
  animation: pressMastheadDisplayIn .85s var(--ease-out) .9s forwards;
}

@keyframes pressMastheadDisplayIn {
  from { opacity: 0; transform: translateY(8px) scale(.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.press-masthead__display-em {
  font-style: italic;
  color: var(--paper);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .15);
}

.press-masthead__display-em--lead {
  color: var(--masthead-tone);
  font-feature-settings: 'kern' 1, 'liga' 1, 'dlig' 1;
}

.press-masthead__display-divider {
  display: inline-flex;
  align-items: center;
  gap: clamp(4px, .6vw, 8px);
  color: var(--masthead-tone);
  transform: translateY(-.14em);
}

.press-masthead__display-divider-rule {
  display: inline-block;
  width: clamp(10px, 1.4vw, 18px);
  height: 1px;
  background: currentColor;
  opacity: .6;
}

.press-masthead__display-divider-rule--alt {
  width: clamp(6px, .9vw, 10px);
  opacity: .35;
}

.press-masthead__display-divider-bead {
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  opacity: .8;
}

.press-masthead__display-sub {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(6px, .8vw, 10px);
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.18vw, 16px);
  letter-spacing: -.005em;
  line-height: 1.2;
  opacity: 0;
  animation: pressMastheadSubIn .65s var(--ease-out) 1.35s forwards;
}

@keyframes pressMastheadSubIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

.press-masthead__display-sub em {
  font-style: italic;
  color: var(--paper);
}

.press-masthead__display-sub-tag {
  color: var(--masthead-tone);
  opacity: .55;
  font-style: normal;
  font-family: var(--mono);
  font-size: .85em;
}

.press-masthead__rule {
  display: block;
  width: 100%;
  height: 8px;
  color: var(--masthead-tone);
  opacity: 0;
  animation: pressMastheadRuleIn .6s var(--ease-out) 1.55s forwards;
}

@keyframes pressMastheadRuleIn {
  from { opacity: 0; transform: scaleY(.4); }
  to { opacity: .9; transform: scaleY(1); }
}

.press-masthead__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: pressMastheadRuleDraw 1.4s var(--ease-out) 1.55s forwards;
}

@keyframes pressMastheadRuleDraw {
  to { stroke-dashoffset: 0; }
}

.press-masthead__cells {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  justify-content: center;
  gap: clamp(6px, .9vw, 12px);
  padding-top: clamp(6px, .8vw, 10px);
  opacity: 0;
  animation: pressMastheadCellsIn .65s var(--ease-out) 1.85s forwards;
}

@keyframes pressMastheadCellsIn {
  from { opacity: 0; transform: translateY(3px); }
  to { opacity: 1; transform: translateY(0); }
}

.press-masthead__cell {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: clamp(8px, 1vw, 12px) clamp(12px, 1.6vw, 18px);
  border: 1px solid rgba(243, 236, 214, .12);
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .025), rgba(243, 236, 214, .005));
  color: var(--paper);
  font-family: var(--serif);
  text-align: center;
  min-width: 0;
}

.press-masthead__cell--voice {
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .04), rgba(243, 236, 214, .01));
  border-color: var(--masthead-tone);
  box-shadow: inset 0 0 0 1px rgba(243, 236, 214, .04);
}

.press-masthead__cell-key {
  font-family: var(--mono);
  font-size: clamp(8px, .74vw, 9.5px);
  font-weight: 500;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: var(--muted);
}

.press-masthead__cell-value {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  font-family: var(--serif);
  font-size: clamp(15px, 1.4vw, 19px);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.012em;
  color: var(--paper);
}

.press-masthead__cell-value em {
  font-style: italic;
  color: var(--masthead-tone);
  font-weight: 500;
}

.press-masthead__cell-voice-letter {
  display: inline-grid;
  place-items: center;
  width: 17px;
  height: 17px;
  border: 1px solid currentColor;
  color: var(--masthead-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  line-height: 1;
}

.press-masthead__cell-voice-letter--quiet { color: var(--blue); }
.press-masthead__cell-voice-letter--human { color: var(--coral); }
.press-masthead__cell-voice-letter--bold { color: var(--acid); }

.press-masthead__cell-face {
  font-family: var(--mono);
  font-size: clamp(7.5px, .66vw, 8.5px);
  font-weight: 500;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--ink-mist);
}

.press-masthead__cell-rule {
  display: inline-block;
  width: 1px;
  align-self: stretch;
  background:
    linear-gradient(to bottom, transparent, var(--masthead-tone), transparent);
  opacity: .35;
}

.press-masthead__tagline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(8px, .9vw, 12px);
  margin: 4px 0 0;
  padding: clamp(6px, .8vw, 10px) 0 0;
  border-top: 1px dashed rgba(243, 236, 214, .12);
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.04vw, 14px);
  letter-spacing: -.005em;
  text-align: center;
  opacity: 0;
  animation: pressMastheadTaglineIn .55s var(--ease-out) 2.1s forwards;
}

@keyframes pressMastheadTaglineIn {
  from { opacity: 0; }
  to { opacity: .85; }
}

.press-masthead__tagline-mark {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  color: var(--masthead-tone);
  font-family: var(--serif);
  font-size: 16px;
  line-height: 1;
  opacity: .7;
}

.press-masthead__tagline-mark--alt {
  font-style: italic;
}

.press-masthead__tagline-sep {
  color: var(--masthead-tone);
  font-style: normal;
  opacity: .55;
}

@media (max-width: 720px) {
  .press-masthead {
    padding: clamp(12px, 3vw, 18px) clamp(12px, 3vw, 18px);
  }

  .press-masthead__plate {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    gap: clamp(6px, 2vw, 10px);
  }

  .press-masthead__fleuron {
    display: none;
  }

  .press-masthead__display-row {
    font-size: clamp(32px, 9vw, 48px);
    gap: clamp(6px, 2vw, 10px);
  }

  .press-masthead__topline {
    column-gap: 6px;
    row-gap: 4px;
    font-size: 8px;
  }

  .press-masthead__topline-rule {
    width: clamp(10px, 2.4vw, 18px);
  }

  .press-masthead__cell-rule {
    display: none;
  }

  .press-masthead__cells {
    gap: 4px;
  }

  .press-masthead__cell {
    flex: 1 1 calc(50% - 4px);
    min-width: 0;
    padding: 8px 10px;
  }
}

@media (max-width: 460px) {
  .press-masthead__display-row {
    font-size: clamp(28px, 11vw, 40px);
    gap: 6px;
  }

  .press-masthead__display-divider-rule {
    width: clamp(6px, 2vw, 12px);
  }

  .press-masthead__display-sub {
    font-size: 12px;
  }

  .press-masthead__cell {
    flex: 1 1 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-masthead {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }

  .press-masthead__topline,
  .press-masthead__fleuron,
  .press-masthead__display-pre,
  .press-masthead__display-row,
  .press-masthead__display-sub,
  .press-masthead__rule,
  .press-masthead__rule-stroke,
  .press-masthead__cells,
  .press-masthead__tagline {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }
}

/* ────────────────────────────────────
   HERO CHROME · the strip beneath the
   spread that holds the voice selector
   and the open-note button.
   ──────────────────────────────────── */

.hero__chrome {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: clamp(14px, 2vw, 24px);
  margin-top: clamp(8px, 1.4vw, 18px);
  padding: 0;
}

@media (max-width: 720px) {
  .hero__chrome {
    flex-direction: column;
    align-items: stretch;
  }
}

/* ────────────────────────────────────
   HERO NOTE LINK · the open-answer
   button, sitting on the right of the
   chrome strip.
   ──────────────────────────────────── */

.hero__note-link {
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  padding: clamp(10px, 1.2vw, 14px) clamp(14px, 1.6vw, 22px);
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .4), rgba(14, 20, 32, .55));
  color: var(--paper);
  text-align: left;
  transition:
    color .35s var(--ease),
    border-color .35s var(--ease),
    background .35s var(--ease),
    transform .35s var(--ease-out);
  min-height: 56px;
}

.hero__note-link-text {
  display: grid;
  gap: 4px;
}

.hero__note-link-mark {
  color: var(--coral);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9.5px);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.app--voice-quiet .hero__note-link-mark { color: var(--blue); }
.app--voice-human .hero__note-link-mark { color: var(--coral); }
.app--voice-bold .hero__note-link-mark { color: var(--acid); }

.hero__note-link-line {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.2vw, 17px);
  letter-spacing: -.005em;
  line-height: 1.15;
}

.hero__note-link-for {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: rgba(243, 236, 214, .55);
  animation: heroNoteLinkForIn .9s var(--ease-out) both;
}

.hero__note-link-for em {
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--coral);
}

.hero__note-link-for-rule {
  display: inline-block;
  width: clamp(20px, 2vw, 32px);
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.app--voice-quiet .hero__note-link-for em { color: var(--blue); }
.app--voice-bold .hero__note-link-for em { color: var(--acid); }

@keyframes heroNoteLinkForIn {
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .hero__note-link-for {
    animation: none !important;
  }
}

.hero__note-link-arrow {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  color: var(--coral);
  transition: transform .35s var(--ease-out), color .3s var(--ease);
}

.hero__note-link-arrow svg {
  width: 100%;
  height: 100%;
  display: block;
}

.app--voice-quiet .hero__note-link-arrow { color: var(--blue); }
.app--voice-human .hero__note-link-arrow { color: var(--coral); }
.app--voice-bold .hero__note-link-arrow { color: var(--acid); }

.hero__note-link:hover,
.hero__note-link:focus-visible {
  color: var(--paper);
  border-color: currentColor;
  transform: translateY(-1px);
}

.hero__note-link:hover .hero__note-link-arrow,
.hero__note-link:focus-visible .hero__note-link-arrow {
  transform: translateX(3px);
}

.hero__note-link.is-open {
  background:
    linear-gradient(180deg, rgba(216, 255, 106, .12), rgba(255, 118, 95, .04));
  border-color: currentColor;
}

.hero__note-link.is-open .hero__note-link-arrow {
  transform: rotate(90deg);
}

/* ────────────────────────────────────
   HERO VOICE LINE · a single elegant
   row that sets three voices as if they
   were a typesetter's note. Replaces
   the busy voice tab strip.
   ──────────────────────────────────── */

.hero__voice-line {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: clamp(12px, 1.6vw, 22px);
  padding: clamp(10px, 1.2vw, 14px) clamp(12px, 1.4vw, 20px);
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .36), rgba(14, 20, 32, .48));
  flex: 1;
  min-width: 280px;
  position: relative;
}

.hero__voice-line::before {
  position: absolute;
  inset: 5px;
  border: 1px dashed rgba(146, 186, 255, .05);
  pointer-events: none;
  content: '';
}

.hero__voice-line-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding-right: clamp(8px, 1vw, 14px);
  border-right: 1px solid var(--line);
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .8vw, 10.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
}

.hero__voice-line-eyebrow-mark {
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 118, 95, .14);
  animation: composePulse 2.4s var(--ease) infinite;
}

.app--voice-quiet .hero__voice-line-eyebrow-mark { background: var(--blue); box-shadow: 0 0 0 3px rgba(155, 188, 255, .14); }
.app--voice-human .hero__voice-line-eyebrow-mark { background: var(--coral); box-shadow: 0 0 0 3px rgba(255, 118, 95, .14); }
.app--voice-bold .hero__voice-line-eyebrow-mark { background: var(--acid); box-shadow: 0 0 0 3px rgba(216, 255, 106, .14); }

.hero__voice-line-list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: clamp(4px, .6vw, 10px);
  margin: 0;
  padding: 0;
  list-style: none;
}

.hero__voice-line-item {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  position: relative;
}

.hero__voice-line-item:not(.is-active) {
  opacity: .55;
  transition: opacity .35s var(--ease);
}

.hero__voice-line:hover .hero__voice-line-item {
  opacity: 1;
}

.hero__voice-line-item.is-active {
  opacity: 1;
}

.hero__voice-line-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  background: transparent;
  color: var(--paper);
  cursor: pointer;
  font-family: inherit;
  text-align: left;
}

.hero__voice-line-bullet {
  position: relative;
  display: inline-block;
  width: 10px;
  height: 10px;
  flex: 0 0 auto;
}

.hero__voice-line-bullet-dot {
  position: absolute;
  inset: 3px;
  border-radius: 50%;
  background: var(--muted);
  transition: background .35s var(--ease), transform .45s var(--ease-spring);
}

.hero__voice-line-bullet-ring {
  position: absolute;
  inset: 0;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: 0;
  transform: scale(.6);
  transition: opacity .35s var(--ease), transform .45s var(--ease-spring);
}

.hero__voice-line-button--quiet { color: var(--blue); }
.hero__voice-line-button--human { color: var(--coral); }
.hero__voice-line-button--bold { color: var(--acid); }

.hero__voice-line-item.is-active .hero__voice-line-bullet-dot {
  background: currentColor;
}

.hero__voice-line-item.is-active .hero__voice-line-bullet-ring {
  opacity: .55;
  transform: scale(1.4);
}

.hero__voice-line-letter {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: 0;
  color: var(--paper);
  transition: background .35s var(--ease), color .35s var(--ease), border-color .35s var(--ease);
  flex: 0 0 auto;
}

.hero__voice-line-item.is-active .hero__voice-line-letter {
  background: currentColor;
  color: var(--night);
  border-color: currentColor;
}

.hero__voice-line-name {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.2vw, 17px);
  letter-spacing: -.01em;
  line-height: 1.05;
  text-transform: none;
}

.hero__voice-line-button--bold .hero__voice-line-name {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 800;
  letter-spacing: -.04em;
  text-transform: uppercase;
  font-size: clamp(12px, 1.05vw, 14px);
}

.hero__voice-line-face {
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9.5px);
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--muted);
}

.hero__voice-line-divider {
  display: inline-block;
  width: 12px;
  height: 16px;
  color: var(--muted);
  opacity: .55;
}

.hero__voice-line-divider svg {
  width: 100%;
  height: 100%;
  display: block;
}

@media (max-width: 720px) {
  .hero__voice-line {
    padding: 10px 12px;
  }

  .hero__voice-line-eyebrow {
    width: 100%;
    padding-right: 0;
    border-right: 0;
    padding-bottom: 6px;
    border-bottom: 1px solid var(--line);
  }

  .hero__voice-line-face {
    display: none;
  }
}

@keyframes composeRuleIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes composeRuleDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes composeRuleBead {
  from { opacity: 0; transform: scale(.3); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes composeRuleRing {
  from { opacity: 0; transform: scale(.5); }
  to { opacity: .55; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .hero__compose-rule { opacity: .95 !important; animation: none !important; }
  .hero__compose-rule-stroke { stroke-dashoffset: 0 !important; animation: none !important; }
  .hero__compose-rule-bead,
  .hero__compose-rule-bead--ring,
  .hero__compose-rule-bead--ring-2 { opacity: 1 !important; animation: none !important; transform: none !important; }
  .hero__compose-rule-bead--ring { opacity: .55 !important; }
  .hero__compose-rule-bead--ring-2 { opacity: .35 !important; }
}

@keyframes lineIn {
  from {
    opacity: 0;
    transform: translateY(.18em);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* a quick ink wash that crosses the page when the lever is pulled,
   so the press action is felt across the title, not only inside the
   press bed. each strike re-mounts the overlay via a key change. */
.press-strike {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 4;
  pointer-events: none;
  color: var(--strike-color, rgba(216, 255, 106, .35));
}

.press-strike__wash {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 56%, currentColor 0%, transparent 58%);
  opacity: 0;
  mix-blend-mode: screen;
  animation: strikeWash 1.1s var(--ease-out) forwards;
}

.press-strike__rule {
  position: absolute;
  top: clamp(80px, 8vw, 130px);
  left: clamp(28px, 5vw, 80px);
  right: clamp(28px, 5vw, 80px);
  height: 1px;
  background: linear-gradient(to right, transparent 0%, currentColor 28%, currentColor 72%, transparent 100%);
  opacity: 0;
  transform-origin: center;
  animation: strikeRule .9s var(--ease-out) .05s forwards;
}

.press-strike__line {
  position: absolute;
  top: clamp(54px, 6vw, 92px);
  left: clamp(20px, 4vw, 80px);
  right: clamp(20px, 4vw, 80px);
  width: auto;
  height: clamp(36px, 4vw, 60px);
  color: inherit;
  opacity: 0;
  transform-origin: right center;
  animation: strikeLine .85s var(--ease-out) forwards;
}

.press-strike__line-path {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: strikeLineDraw .85s var(--ease-out) forwards;
}

.press-strike__ring {
  position: absolute;
  top: clamp(12px, 1.6vw, 22px);
  right: clamp(12px, 1.6vw, 22px);
  width: clamp(96px, 9vw, 124px);
  height: clamp(96px, 9vw, 124px);
  border-radius: 50%;
  border: 1px solid currentColor;
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: strikeRing .85s var(--ease-out) forwards;
}

.press-strike__spark {
  position: absolute;
  top: clamp(54px, 6vw, 80px);
  right: clamp(50px, 6vw, 80px);
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 4px rgba(14, 15, 21, .55), 0 0 14px currentColor;
  transform: translate(50%, -50%) scale(0);
  animation: strikeSpark .6s var(--ease-spring) forwards;
}

@keyframes strikeWash {
  0% { opacity: 0; transform: scale(.96); }
  20% { opacity: .22; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.06); }
}

@keyframes strikeRule {
  0% { opacity: 0; transform: scaleX(.4); }
  20% { opacity: .9; transform: scaleX(1); }
  100% { opacity: 0; transform: scaleX(1); }
}

@keyframes strikeLine {
  0% {
    opacity: 0;
  }
  25% {
    opacity: .85;
  }
  100% {
    opacity: 0;
  }
}

@keyframes strikeLineDraw {
  0% {
    stroke-dashoffset: 100;
  }
  100% {
    stroke-dashoffset: 0;
  }
}

@keyframes strikeRing {
  0% {
    opacity: 0;
    transform: scale(.4);
  }
  25% {
    opacity: .9;
  }
  100% {
    opacity: 0;
    transform: scale(2.4);
  }
}

@keyframes strikeSpark {
  0% {
    opacity: 0;
    transform: translate(50%, -50%) scale(0);
  }
  35% {
    opacity: 1;
    transform: translate(50%, -50%) scale(1.4);
  }
  100% {
    opacity: 0;
    transform: translate(50%, -50%) scale(.4);
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-strike,
  .press-strike__ring,
  .press-strike__line,
  .press-strike__line-path,
  .press-strike__spark {
    animation: none !important;
    opacity: 0 !important;
    display: none !important;
  }
}

/* a brief ink wash that pulses the hero spread when the press
   strikes; the spread gets a brief radial intensification in
   the voice's color, then settles back. the spread re-mounts
   on each strike via the strikeTick key on the press mark, so
   the entrance animation is what does the work here. */

/* when the title lines re-mount (on voice change), a brief
   text-shadow pulse makes the marked words ink-strike, not
   just fade in. the title is re-keyed on each strike, so the
   CSS animation fires on every press. */
.hero__title .title-token {
  animation: tokenStrike .8s var(--ease-out) .15s backwards;
}

@keyframes tokenStrike {
  0% { text-shadow: 0 0 0 transparent; }
  20% { text-shadow: 0 0 .9em currentColor; }
  60% { text-shadow: 0 0 .4em currentColor; }
  100% { text-shadow: 0 0 0 transparent; }
}

@media (prefers-reduced-motion: reduce) {
  .hero__title .title-token { animation: none !important; }
}


