  padding-top: clamp(28px, 3.6vw, 44px);
  border-top: 1px solid var(--line-soft);
  position: relative;
}

.hero__body::before {
  content: '';
  position: absolute;
  top: -1px;
  left: 50%;
  width: clamp(120px, 16vw, 220px);
  height: 1px;
  transform: translateX(-50%);
