/* ────────────────────────────────────────────────────────────
   IMPRINT PLATE · the page's "I am reading" plate, set
   between the editor's note and the brief lever. A single,
   confident artifact that captures the present moment —
   voice, marked word, set today, season, reader — with a
   small drawn seal, a seasonal glyph, and a hand-cut thread
   that exhales toward the next page. It is the front matter's
   memo: not the colophon (which closes the journey) but the
   press plate that confirms how the reader is set right now.
   ──────────────────────────────────────────────────────────── */

.imprint-plate {
  --imprint-tone: var(--coral);
  --imprint-word-tone: var(--acid);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(14px, 1.6vw, 22px);
  padding: clamp(28px, 3.4vw, 44px) clamp(24px, 3.2vw, 40px);
  margin: clamp(8px, 1vw, 14px) 0 0;
  border: 1px solid var(--line);
  border-radius: 2px;
  background:
    radial-gradient(ellipse at 100% 0%, color-mix(in srgb, var(--imprint-tone) 8%, transparent), transparent 56%),
    radial-gradient(ellipse at 0% 100%, color-mix(in srgb, var(--paper) 4%, transparent), transparent 56%),
    linear-gradient(180deg, rgba(20, 26, 38, .42), rgba(12, 16, 26, .6));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    inset 0 1px 0 rgba(243, 236, 214, .04),
    0 22px 48px -36px rgba(0, 0, 0, .42);
  opacity: 0;
  transform: translateY(10px);
  transition: opacity .85s var(--ease-out), transform .85s var(--ease-out);
  isolation: isolate;
}

.imprint-plate.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.imprint-plate::after {
  content: '';
  position: absolute;
  inset: 7px;
  border: 1px dashed color-mix(in srgb, var(--imprint-tone) 14%, transparent);
  border-radius: 1px;
  pointer-events: none;
  opacity: .55;
}

.app--voice-quiet .imprint-plate { --imprint-tone: var(--blue); }
.app--voice-human .imprint-plate { --imprint-tone: var(--coral); }
.app--voice-bold .imprint-plate { --imprint-tone: var(--acid); }

.imprint-plate__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  visibility: hidden;
}

.imprint-plate__rule {
  display: block;
  width: 100%;
  height: 6px;
  color: var(--imprint-tone);
}

.imprint-plate__rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.imprint-plate__rule-stroke {
  stroke-dashoffset: 100;
  animation: imprintPlateRuleDraw 1.4s var(--ease-out) .25s forwards;
}

@keyframes imprintPlateRuleDraw {
  to { stroke-dashoffset: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .imprint-plate__rule-stroke { animation: none !important; stroke-dashoffset: 0 !important; }
}

.imprint-plate__head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(14px, 2vw, 24px);
  padding-bottom: clamp(8px, 1vw, 14px);
  border-bottom: 1px dashed var(--line-soft);
}

.imprint-plate__head-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: clamp(38px, 3.6vw, 48px);
  height: clamp(38px, 3.6vw, 48px);
