  transition: color .55s var(--ease), transform .55s var(--ease-spring);
}

.imprint-plate:hover .imprint-plate__head-mark {
  transform: rotate(-6deg);
}

.imprint-plate__head-mark svg {
  width: 100%;
  height: 100%;
}

.imprint-plate__head-stack {
