.imprint-plate__grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) auto minmax(0, 1fr) auto minmax(0, 1.1fr);
  align-items: stretch;
  gap: clamp(10px, 1.4vw, 18px);
  padding: clamp(14px, 1.6vw, 22px) 0;
