  height: 1px;
  background: currentColor;
  opacity: .65;
}

.imprint-plate__cell-key-mark--alt { opacity: .85; }

.imprint-plate__cell-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  min-width: 0;
}

.imprint-plate__cell-letter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: clamp(38px, 3.6vw, 48px);
  height: clamp(38px, 3.6vw, 48px);
  border: 1px solid color-mix(in srgb, var(--imprint-tone) 36%, transparent);
  border-radius: 2px;
  color: var(--imprint-tone);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
