}

.imprint-plate__thread-stroke--trail {
  stroke-dashoffset: 100;
  animation: imprintPlateThreadDraw 1.9s var(--ease-out) .95s forwards;
}

@keyframes imprintPlateThreadDraw {
  to { stroke-dashoffset: 0; }
}

@media (prefers-reduced-motion: reduce) {
