/* the lever at the end of the brief — a deliberate turn-the-page
   gesture, replacing the previous thin continue link. */

.hero__brief-lever {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(18px, 2.2vw, 28px) clamp(20px, 2.6vw, 32px);
  margin: 0;
  border: 1px solid var(--line);
  border-radius: 2px;
  background:
    linear-gradient(135deg, rgba(216, 240, 106, .05), rgba(216, 240, 106, 0) 38%),
    linear-gradient(180deg, rgba(20, 26, 38, .42), rgba(12, 16, 26, .58));
  color: var(--paper);
  text-decoration: none;
  transition: border-color .35s var(--ease), background .55s var(--ease), color .35s var(--ease), transform .45s var(--ease-out);
}

.hero__brief-lever:hover,
.hero__brief-lever:focus-visible {
  border-color: var(--acid);
  color: var(--paper);
  transform: translateY(-1px);
}

.app--voice-quiet .hero__brief-lever:hover,
.app--voice-quiet .hero__brief-lever:focus-visible { border-color: var(--blue); }
.app--voice-human .hero__brief-lever:hover,
.app--voice-human .hero__brief-lever:focus-visible { border-color: var(--coral); }
.app--voice-bold .hero__brief-lever:hover,
.app--voice-bold .hero__brief-lever:focus-visible { border-color: var(--acid); }

.hero__brief-lever-tag {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
  transition: color .35s var(--ease);
}

.app--voice-quiet .hero__brief-lever-tag { color: var(--blue); }
.app--voice-human .hero__brief-lever-tag { color: var(--coral); }
.app--voice-bold .hero__brief-lever-tag { color: var(--acid); }

.hero__brief-lever-tag em {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
  text-transform: none;
}

.hero__brief-lever-tag-mark {
  display: inline-block;
  width: 14px;
  height: 1px;
  background: currentColor;
  opacity: .65;
}

.hero__brief-lever-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.hero__brief-lever-line {
  display: grid;
  gap: 2px;
}

.hero__brief-lever-eyebrow {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.hero__brief-lever-label {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(20px, 2.2vw, 28px);
  letter-spacing: -.022em;
  line-height: 1;
}

.hero__brief-lever-arrow {
  display: inline-grid;
  place-items: center;
  width: clamp(38px, 3.4vw, 48px);
  height: clamp(38px, 3.4vw, 48px);
  border: 1px solid var(--acid);
  border-radius: 50%;
  color: var(--acid);
  flex: 0 0 auto;
  transition: transform .4s var(--ease-out), border-color .35s var(--ease);
}

.app--voice-quiet .hero__brief-lever-arrow { border-color: var(--blue); color: var(--blue); }
.app--voice-human .hero__brief-lever-arrow { border-color: var(--coral); color: var(--coral); }
.app--voice-bold .hero__brief-lever-arrow { border-color: var(--acid); color: var(--acid); }

.hero__brief-lever-arrow svg {
  width: 60%;
  height: 60%;
}

.hero__brief-lever:hover .hero__brief-lever-arrow,
.hero__brief-lever:focus-visible .hero__brief-lever-arrow {
  transform: translateX(4px) rotate(-6deg);
}

.hero__brief-lever-hint {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .95vw, 13px);
  letter-spacing: -.005em;
}

.hero__brief-lever-hint-mark {
  display: inline-block;
  width: 14px;
  height: 1px;
  background: var(--line);
  opacity: .8;
}

@media (prefers-reduced-motion: reduce) {
  .hero__brief { animation: none !important; opacity: 1 !important; transform: none !important; transition: none !important; }
  .hero__brief-rule-stroke { animation: none !important; stroke-dashoffset: 0 !important; }
  .hero__brief-rule-bead { animation: none !important; opacity: 1 !important; transform: none !important; }
  .hero__key-cell-pin { animation: none !important; opacity: 1 !important; transform: none !important; }
}


.hero__continue {
