/* ────────────────────────────────────────────────────────────
   HERO PLATE · the title page: title at center, marginalia
   ribbon running alongside on the right. On mobile the ribbon
   slips below the title and reads as a stack of three proof
   notes pinned to the page.
   ──────────────────────────────────────────────────────────── */
.hero__plate {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(24px, 3.2vw, 48px);
  align-items: start;
  width: 100%;
  z-index: 1;
  perspective: 1200px;
  perspective-origin: 50% 0%;
}

.hero__plate > .hero__copy {
  max-width: none;
}


@media (min-width: 1180px) {
  .hero__plate {
    grid-template-columns: minmax(0, 1fr) clamp(280px, 28vw, 360px);
    column-gap: clamp(40px, 4.8vw, 80px);
    align-items: stretch;
  }

  .hero__plate > .hero__copy {
    align-self: center;
  }
}

@media (max-width: 1179px) {
  .hero__plate {
    grid-template-columns: minmax(0, 1fr);
    gap: clamp(36px, 5vw, 56px);
  }

  .hero__plate .hero__title {
    max-width: 1100px;
  }
}

/* the title now shares the spread with the margin gutter on wide screens;
   the gutter collapses below the title on narrower screens. */
@media (min-width: 1180px) {
  .hero__plate .hero__title {
    max-width: 1180px;
    font-size: clamp(4.2rem, 10.4vw, 12.4rem);
  }

  .hero__plate .hero__title--quiet {
    font-size: clamp(4rem, 9.8vw, 11.6rem);
  }

  .hero__plate .hero__title--bold {
    font-size: clamp(4.5rem, 11.2vw, 13.6rem);
  }
}

@media (min-width: 981px) and (max-width: 1179px) {
  .hero__plate .hero__title {
    max-width: 1180px;
    font-size: clamp(4.2rem, 10.6vw, 12.6rem);
  }

  .hero__plate .hero__title--quiet {
    font-size: clamp(4rem, 10vw, 11.8rem);
  }

  .hero__plate .hero__title--bold {
    font-size: clamp(4.5rem, 11.4vw, 13.8rem);
  }
}

/* ────────────────────────────────────────────────────────────
   READER'S NOTE · a single letterpress proof sheet that sits in
   the right gutter of the hero spread. The active marked word
   becomes a full prose note: title, gloss, body, prompt, and an
   editor's pencil mark. Below, a slim three-step index lets the
   reader switch the active mark without leaving the page.
   ──────────────────────────────────────────────────────────── */

.reader-note {
  --note-ink: var(--paper);
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(20px, 2.4vw, 32px) clamp(18px, 2.2vw, 28px) clamp(20px, 2.4vw, 28px);
  border: 1px solid var(--line);
  border-left: 1px solid color-mix(in srgb, var(--note-ink) 32%, transparent);
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .24), rgba(14, 20, 32, .4));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .03),
    0 22px 56px -28px rgba(0, 0, 0, .6);
  color: var(--paper);
  align-self: stretch;
  opacity: 0;
  animation: readerNoteIn .9s var(--ease-out) .7s forwards;
}

@keyframes readerNoteIn {
  0% { opacity: 0; transform: translateX(10px); }
  100% { opacity: 1; transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .reader-note {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

.reader-note__tape {
  display: block;
  position: absolute;
  left: clamp(18px, 2.2vw, 28px);
  right: clamp(18px, 2.2vw, 28px);
  height: 8px;
  color: color-mix(in srgb, var(--note-ink) 40%, transparent);
  opacity: .65;
  pointer-events: none;
}

.reader-note__tape--top {
  top: -3px;
}

.reader-note__tape svg {
  width: 100%;
  height: 100%;
}

.reader-note__head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding-bottom: 6px;
  border-bottom: 1px dashed color-mix(in srgb, var(--note-ink) 22%, transparent);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.reader-note__head-mark {
  color: var(--note-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  letter-spacing: 0;
  text-transform: none;
}

.reader-note__head-eyebrow {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.05vw, 15px);
  letter-spacing: -.005em;
  text-transform: none;
  white-space: nowrap;
}

.reader-note__head-folio {
  margin-left: auto;
  color: var(--muted);
  white-space: nowrap;
}

.reader-note__rule {
  display: block;
  width: 100%;
  height: 6px;
  color: var(--note-ink);
}

.reader-note__rule svg {
  width: 100%;
  height: 100%;
}

.reader-note__index {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(6px, .8vw, 10px);
  margin: 0;
  padding: 0;
  list-style: none;
}

.reader-note__index-item {
  margin: 0;
}

.reader-note__index-tick {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 2px;
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 1px;
  background: linear-gradient(180deg, rgba(28, 36, 52, .18), rgba(14, 20, 32, .3));
  color: var(--muted);
  text-align: left;
  cursor: pointer;
  transition:
    border-color .35s var(--ease),
    background .35s var(--ease),
    color .35s var(--ease),
    transform .35s var(--ease-out);
}

.reader-note__index-item--m3 { --note-mark: var(--acid); }
.reader-note__index-item--good { --note-mark: var(--coral); }
.reader-note__index-item--yet { --note-mark: var(--blue); }

.reader-note__index-tick:hover,
.reader-note__index-tick:focus-visible {
  border-color: color-mix(in srgb, var(--note-mark) 40%, var(--line));
  background: color-mix(in srgb, var(--note-mark) 8%, rgba(28, 36, 52, .36));
  color: var(--paper);
}

.reader-note__index-item.is-active .reader-note__index-tick {
  border-color: var(--note-mark);
  background: color-mix(in srgb, var(--note-mark) 14%, rgba(28, 36, 52, .4));
  color: var(--paper);
  transform: translateY(-1px);
}

.reader-note__index-mark {
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.reader-note__index-item.is-active .reader-note__index-mark {
  color: var(--note-mark);
}

.reader-note__index-word {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.05vw, 15.5px);
  letter-spacing: -.01em;
}

.reader-note__leaf {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(8px, 1vw, 14px);
  padding: clamp(8px, 1vw, 14px) 0;
  border-top: 1px solid color-mix(in srgb, var(--note-ink) 16%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--note-ink) 16%, transparent);
  animation: readerNoteLeafIn .55s var(--ease-out);
}

@keyframes readerNoteLeafIn {
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .reader-note__leaf { animation: none !important; transform: none !important; }
}

.reader-note__leaf-row {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.reader-note__leaf-mark {
  display: inline-grid;
  place-items: center;
  padding: 2px 8px 3px;
  border: 1px solid currentColor;
  border-radius: 1px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
  white-space: nowrap;
}

.reader-note__leaf-mark--m3 { color: var(--acid); }
.reader-note__leaf-mark--good { color: var(--coral); }
.reader-note__leaf-mark--yet { color: var(--blue); }

.reader-note__leaf-folio {
  color: var(--muted);
}

.reader-note__leaf-sep {
  opacity: .55;
}

.reader-note__leaf-word {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.05vw, 15px);
  letter-spacing: -.005em;
  text-transform: none;
}

.reader-note__title {
  position: relative;
  margin: 0;
  padding: 0 0 0 24px;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(22px, 2.2vw, 28px);
  font-weight: 400;
  line-height: 1.18;
  letter-spacing: -.018em;
  text-wrap: balance;
}

.reader-note__title-orn {
  position: absolute;
  left: 0;
  top: .15em;
  width: 18px;
  height: 18px;
  color: var(--note-ink);
}

.reader-note__gloss {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 0;
  color: var(--note-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.15vw, 16.5px);
  line-height: 1.4;
  letter-spacing: -.005em;
}

.reader-note__gloss-mark {
  color: var(--note-ink);
  font-style: normal;
  font-family: var(--mono);
  font-size: 11px;
  line-height: 1;
}

.reader-note__body {
  margin: 0;
  color: var(--lead-2);
  font-family: var(--serif);
  font-size: clamp(13.5px, 1.05vw, 15px);
  line-height: 1.6;
  letter-spacing: -.003em;
}

.reader-note__pull {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 4px 0 0;
  padding: 0;
}

.reader-note__pull-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--note-ink) 50%, transparent));
}

.reader-note__pull-rule--end {
  background: linear-gradient(to left, transparent, color-mix(in srgb, var(--note-ink) 50%, transparent));
}

.reader-note__pull em {
  flex: 0 0 auto;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13.5px, 1.05vw, 15px);
  letter-spacing: -.005em;
  white-space: nowrap;
}

.reader-note__editor {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 12px 12px;
  border: 1px dashed color-mix(in srgb, var(--note-ink) 22%, transparent);
  border-radius: 1px;
  background: color-mix(in srgb, var(--note-ink) 4%, transparent);
}

.reader-note__editor-tag {
  color: var(--note-ink);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.reader-note__editor-note {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12.5px, 1vw, 14px);
  letter-spacing: -.003em;
  line-height: 1.45;
}

.reader-note__foot {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 2px;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, .95vw, 13px);
  letter-spacing: -.002em;
}

.reader-note__foot-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line));
}

.reader-note__foot-rule--end {
  background: linear-gradient(to left, transparent, var(--line));
}

.reader-note__foot-text {
  white-space: nowrap;
}

.reader-note__foot-text em {
  color: var(--paper);
  font-style: italic;
}

.reader-note__foot-seen {
  font-family: var(--mono);
  font-style: normal;
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: .7;
}

@media (max-width: 1179px) {
  .reader-note {
    max-width: 1080px;
    margin: 0 auto;
    width: 100%;
  }

  .reader-note__title {
    font-size: clamp(20px, 2vw, 24px);
  }
}

@media (max-width: 720px) {
  .reader-note__head {
    flex-wrap: wrap;
    gap: 6px 12px;
  }

  .reader-note__head-folio {
    margin-left: 0;
  }

  .reader-note__title {
    font-size: 20px;
    padding-left: 22px;
  }

  .reader-note__title-orn {
    width: 16px;
    height: 16px;
    top: .1em;
  }

  .reader-note__pull em {
    white-space: normal;
  }
}


/* ────────────────────────────────────────────────────────────
   ANNOTATION RIBBON · the reader's marginalia column that runs
   alongside the title. Three proof-card slots stacked on top
   of each other, each keyed to a marked word in the title. A
   delicate connector leaves the active slot and reaches toward
   the title's marked word.
   ──────────────────────────────────────────────────────────── */

.annotation-ribbon {
  position: relative;
  display: grid;
  gap: clamp(16px, 2vw, 22px);
  align-self: stretch;
  color: var(--paper);
  opacity: 0;
  animation: ribbonIn 1s var(--ease-out) .85s forwards;
}

@keyframes ribbonIn {
  0% { opacity: 0; transform: translateX(14px); }
  100% { opacity: 1; transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .annotation-ribbon {
    animation: none !important;
    opacity: 1;
  }
}

.annotation-ribbon__head {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .28em;
  text-transform: uppercase;
}

.annotation-ribbon__head-line {
  display: block;
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor, transparent);
}

.annotation-ribbon__head-line:last-child {
  background: linear-gradient(to left, transparent, currentColor, transparent);
}

.annotation-ribbon__head-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.annotation-ribbon__head-dot {
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(255, 118, 95, .16);
  animation: composePulse 2.4s var(--ease) infinite;
}

.app--voice-quiet .annotation-ribbon__head,
.app--voice-quiet .annotation-ribbon__head-tag,
.app--voice-quiet .annotation-ribbon__head-dot {
  color: var(--blue);
}

.app--voice-bold .annotation-ribbon__head,
.app--voice-bold .annotation-ribbon__head-tag,
.app--voice-bold .annotation-ribbon__head-dot {
  color: var(--acid);
}

.annotation-ribbon__cap {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 0 2px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.annotation-ribbon__cap-folio {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: 0;
  text-transform: none;
}

.annotation-ribbon__cap-press {
  color: var(--muted);
}

.annotation-ribbon__list {
  display: grid;
  gap: clamp(12px, 1.4vw, 16px);
  margin: 0;
  padding: 0;
  list-style: none;
}

.annotation-ribbon__item {
  position: relative;
  margin: 0;
}

.annotation-ribbon__item::before {
  content: '';
  position: absolute;
  left: -16px;
  top: 50%;
  width: 8px;
  height: 1px;
  background: var(--line);
  opacity: .4;
  transform: translateY(-50%);
  transition: width .35s var(--ease), background .4s var(--ease), opacity .35s var(--ease);
}

.annotation-ribbon__item.is-active::before {
  width: 14px;
  background: var(--coral);
  opacity: .9;
}

.app--voice-quiet .annotation-ribbon__item.is-active::before { background: var(--blue); }
.app--voice-bold .annotation-ribbon__item.is-active::before { background: var(--acid); }

.annotation-ribbon__card {
  position: relative;
  display: grid;
  gap: 8px;
  width: 100%;
  padding: 14px 14px 13px;
  border: 1px solid var(--line);
  border-radius: 1px;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .52), rgba(14, 20, 32, .7));
  color: var(--paper);
  text-align: left;
  cursor: pointer;
  transition:
    border-color .4s var(--ease),
    background .45s var(--ease),
    transform .45s var(--ease-spring),
    box-shadow .45s var(--ease);
}

.annotation-ribbon__card--acid {
  border-left: 2px solid rgba(216, 255, 106, .55);
}

.annotation-ribbon__card--coral {
  border-left: 2px solid rgba(255, 118, 95, .55);
}

.annotation-ribbon__card--blue {
  border-left: 2px solid rgba(155, 188, 255, .55);
}

.annotation-ribbon__item:hover .annotation-ribbon__card,
.annotation-ribbon__item:focus-within .annotation-ribbon__card,
.annotation-ribbon__item.is-active .annotation-ribbon__card {
  border-color: var(--line);
  background:
    linear-gradient(180deg, rgba(36, 46, 66, .65), rgba(20, 28, 42, .8));
  box-shadow: 0 14px 32px -22px rgba(0, 0, 0, .6);
}

.annotation-ribbon__item.is-active .annotation-ribbon__card {
  transform: translateY(-1px);
  box-shadow:
    0 18px 38px -22px rgba(0, 0, 0, .65),
    inset 0 0 0 1px rgba(216, 255, 106, .08);
}

.annotation-ribbon__item--good.is-active .annotation-ribbon__card {
  box-shadow:
    0 18px 38px -22px rgba(0, 0, 0, .65),
    inset 0 0 0 1px rgba(255, 118, 95, .1);
}

.annotation-ribbon__item--yet.is-active .annotation-ribbon__card {
  box-shadow:
    0 18px 38px -22px rgba(0, 0, 0, .65),
    inset 0 0 0 1px rgba(155, 188, 255, .1);
}

.annotation-ribbon__rule {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 14px;
  height: 14px;
  color: var(--muted);
  opacity: .35;
}

.annotation-ribbon__rule::before,
.annotation-ribbon__rule::after {
  content: '';
  position: absolute;
  background: currentColor;
}

.annotation-ribbon__rule::before {
  top: 0;
  right: 0;
  width: 14px;
  height: 1px;
}

.annotation-ribbon__rule::after {
  top: 0;
  right: 0;
  width: 1px;
  height: 14px;
}

.annotation-ribbon__pin {
  position: absolute;
  top: -10px;
  left: 18px;
  width: 18px;
  height: 18px;
  filter: drop-shadow(0 1px 0 rgba(0, 0, 0, .4));
  transform: rotate(-6deg);
  transition: transform .5s var(--ease-spring);
}

.annotation-ribbon__item.is-active .annotation-ribbon__pin {
  transform: rotate(2deg) scale(1.05);
}

.annotation-ribbon__head-row {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.annotation-ribbon__num {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
  transition: background .35s var(--ease), color .35s var(--ease);
}

.annotation-ribbon__item.is-active .annotation-ribbon__num {
  background: currentColor;
  color: var(--night);
}

.annotation-ribbon__item--m3 .annotation-ribbon__num { color: var(--acid); }
.annotation-ribbon__item--good .annotation-ribbon__num { color: var(--coral); }
.annotation-ribbon__item--yet .annotation-ribbon__num { color: var(--blue); }

.annotation-ribbon__folio {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11.5px;
  letter-spacing: 0;
  text-transform: none;
}

.annotation-ribbon__divider {
  font-style: normal;
  opacity: .5;
}

.annotation-ribbon__mark {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  height: 22px;
  color: var(--coral);
  opacity: .9;
}

.annotation-ribbon__item--m3 .annotation-ribbon__mark { color: var(--acid); }
.annotation-ribbon__item--good .annotation-ribbon__mark { color: var(--coral); }
.annotation-ribbon__item--yet .annotation-ribbon__mark { color: var(--blue); }

.annotation-ribbon__mark-svg {
  display: block;
  height: 100%;
  width: auto;
  max-width: 72px;
}

.annotation-ribbon__mark-tag {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .18em;
  text-transform: uppercase;
  fill: currentColor;
  opacity: .8;
}

.annotation-ribbon__mark-tag--acid { fill: var(--acid); }
.annotation-ribbon__mark-tag--coral { fill: var(--coral); }
.annotation-ribbon__mark-tag--blue { fill: var(--blue); }

.annotation-ribbon__mark-stroke {
  opacity: .85;
  stroke-dashoffset: 160;
  transition: stroke-dashoffset 1.2s var(--ease-out);
}

.annotation-ribbon__item.is-active .annotation-ribbon__mark-stroke {
  stroke-dashoffset: 0;
}

.annotation-ribbon__mark-fill {
  opacity: 0;
  transform: scale(.5);
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .45s var(--ease), transform .65s var(--ease-spring);
}

.annotation-ribbon__item.is-active .annotation-ribbon__mark-fill {
  opacity: 1;
  transform: scale(1);
}

.annotation-ribbon__word {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(28px, 2.6vw, 38px);
  font-weight: 400;
  letter-spacing: -.04em;
  line-height: 1;
  transition: transform .45s var(--ease-spring);
}

.annotation-ribbon__word--acid { color: var(--acid); }
.annotation-ribbon__word--coral { color: var(--coral); }
.annotation-ribbon__word--blue { color: var(--blue); }

.annotation-ribbon__item.is-active .annotation-ribbon__word {
  transform: translateX(2px);
}

.annotation-ribbon__gloss {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 7px;
  padding: 4px 0 2px;
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.05vw, 15px);
  line-height: 1.45;
  letter-spacing: -.005em;
}

.annotation-ribbon__gloss-mark {
  font-family: var(--serif);
  font-style: normal;
  font-size: 14px;
  line-height: 1;
  opacity: .85;
}

.annotation-ribbon__gloss-mark--acid { color: var(--acid); }
.annotation-ribbon__gloss-mark--coral { color: var(--coral); }
.annotation-ribbon__gloss-mark--blue { color: var(--blue); }

.annotation-ribbon__meta {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  padding-top: 4px;
  border-top: 1px dashed rgba(146, 186, 255, .12);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.annotation-ribbon__meta-mark {
  color: var(--paper);
}

.annotation-ribbon__meta-sep {
  opacity: .5;
  font-style: normal;
}

.annotation-ribbon__meta-label {
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
}

.annotation-ribbon__scribble {
  display: block;
  width: 100%;
  height: 8px;
  margin-top: 4px;
  color: var(--muted);
  opacity: .35;
}

.annotation-ribbon__item.is-active .annotation-ribbon__scribble {
  opacity: 1;
  color: var(--coral);
}

.annotation-ribbon__item--m3.is-active .annotation-ribbon__scribble { color: var(--acid); }
.annotation-ribbon__item--good.is-active .annotation-ribbon__scribble { color: var(--coral); }
.annotation-ribbon__item--yet.is-active .annotation-ribbon__scribble { color: var(--blue); }

.annotation-ribbon__scribble-stroke {
  stroke-dasharray: 120 120;
  stroke-dashoffset: 120;
}

.annotation-ribbon__item.is-active .annotation-ribbon__scribble-stroke {
  animation: scribbleDraw 1.1s var(--ease-out) .12s forwards;
}

.annotation-ribbon__scribble-dot {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.annotation-ribbon__item.is-active .annotation-ribbon__scribble-dot {
  animation: scribbleDot .35s var(--ease-spring) 1.1s forwards;
}

@keyframes scribbleDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes scribbleDot {
  from { opacity: 0; transform: scale(.3); }
  to { opacity: 1; transform: scale(1); }
}

.annotation-ribbon__connector-slot {
  position: absolute;
  top: 50%;
  right: 100%;
  width: clamp(36px, 4vw, 56px);
  height: 80px;
  margin-right: 0;
  pointer-events: none;
  color: var(--coral);
  z-index: 1;
}

.annotation-ribbon__item--m3 .annotation-ribbon__connector-slot { color: var(--acid); }
.annotation-ribbon__item--good .annotation-ribbon__connector-slot { color: var(--coral); }
.annotation-ribbon__item--yet .annotation-ribbon__connector-slot { color: var(--blue); }

.annotation-ribbon__thread {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.annotation-ribbon__thread-path {
  stroke-dasharray: 1 3;
  stroke-dashoffset: 0;
  opacity: 0;
  animation: threadFade .45s var(--ease-out) .15s forwards;
}

.annotation-ribbon__thread-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: threadBead .35s var(--ease-spring) .55s forwards;
}

.annotation-ribbon__thread-tip {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: threadTip .35s var(--ease-spring) 1.05s forwards;
}

@keyframes threadFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes threadBead {
  from { opacity: 0; transform: scale(.3); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes threadTip {
  from { opacity: 0; transform: scale(.3); }
  to { opacity: 1; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .annotation-ribbon__thread-path,
  .annotation-ribbon__thread-bead,
  .annotation-ribbon__thread-tip,
  .annotation-ribbon__scribble-stroke,
  .annotation-ribbon__scribble-dot,
  .annotation-ribbon__mark-stroke,
  .annotation-ribbon__mark-fill {
    animation: none !important;
    stroke-dashoffset: 0 !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

.annotation-ribbon__foot {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  padding: 6px 4px 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.annotation-ribbon__foot-mark {
  color: var(--coral);
  font-family: var(--serif);
  font-style: normal;
  font-size: 14px;
  letter-spacing: 0;
}

.annotation-ribbon__foot-text {
  font-family: var(--serif);
  font-style: italic;
  font-size: 11.5px;
  letter-spacing: 0;
  text-transform: none;
  line-height: 1.45;
  color: var(--mist);
}

@media (max-width: 980px) {
  .annotation-ribbon {
    max-width: 640px;
    margin: 0 auto;
    width: 100%;
  }

  .annotation-ribbon__connector-slot {
    display: none;
  }
}

@media (max-width: 540px) {
  .annotation-ribbon {
    gap: 12px;
  }

  .annotation-ribbon__cap {
    flex-wrap: wrap;
  }

  .annotation-ribbon__card {
    padding: 12px 12px 11px;
  }

  .annotation-ribbon__word {
    font-size: clamp(24px, 8vw, 32px);
  }

  .annotation-ribbon__gloss {
    font-size: 13px;
  }
}


.title-token {
  position: relative;
  display: inline;
  padding: 0 .04em .06em;
  border-bottom: 1.5px solid rgba(216, 255, 106, .55);
  background: transparent;
  color: var(--acid);
  font-family: inherit;
  font-size: inherit;
  font-style: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  line-height: inherit;
  text-shadow: none;
  cursor: pointer;
  transition: color .3s var(--ease), background-color .35s var(--ease), border-color .3s var(--ease), text-shadow .4s var(--ease);
}

.title-token__set {
  position: absolute;
  right: 100%;
  bottom: .14em;
  width: 0;
  height: 1px;
  background: currentColor;
  margin-right: .18em;
  opacity: .7;
  transition: width .6s var(--ease-out);
}

.title-token:hover .title-token__set,
.title-token:focus-visible .title-token__set,
.title-token.is-selected .title-token__set {
  width: .44em;
}

.title-token::before {
  position: absolute;
  top: -.16em;
  right: -.12em;
  width: .18em;
  height: .18em;
  border: 1px solid currentColor;
  border-radius: 50%;
  content: '';
  opacity: 0;
  transform: scale(.3);
  transition: opacity .35s var(--ease), transform .55s var(--ease-out);
}


.title-token--good {
  color: var(--paper);
  border-bottom-color: rgba(255, 118, 95, .55);
}

.title-token--yet {
  color: var(--coral);
  border-bottom-color: rgba(255, 118, 95, .45);
}

.title-token:hover,
.title-token:focus-visible,
.title-token.is-selected {
  background: rgba(216, 255, 98, .1);
  border-bottom-color: var(--acid);
  color: var(--acid);
  text-shadow: 0 0 .55em rgba(216, 255, 98, .22);
}

.title-token:hover::before,
.title-token:focus-visible::before,
.title-token.is-selected::before {
  opacity: 1;
  transform: scale(1);
}

.hero__title--human .title-token--good,
.hero__title--human .title-token--yet {
  font-style: italic;
}

.hero__title--bold {
  font-family: var(--sans);
  font-size: clamp(3.9rem, 9.4vw, 11.2rem);
  font-weight: 850;
  letter-spacing: -.122em;
  line-height: .82;
  text-transform: uppercase;
}

.hero__title--bold .title-token {
  border-bottom-width: 3px;
  border-bottom-style: solid;
}

@keyframes titleRuleDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes titleRuleDot {
  from { opacity: 0; transform: scale(.3); }
  to { opacity: 1; transform: scale(1); }
}

.app--word-good .hero__summary-scrawl { color: var(--coral); }
.app--word-yet .hero__summary-scrawl { color: var(--blue); }
.app--word-m3 .hero__summary-scrawl { color: var(--acid); }

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-height: 52px;
  padding: 13px 17px 13px 21px;
  border: 1px solid var(--acid);
  background: var(--acid);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  transition: background .3s var(--ease), color .3s var(--ease), transform .3s var(--ease-out), box-shadow .3s var(--ease), border-color .3s var(--ease);
}

.button:hover,
.button:focus-visible {
  background: var(--paper);
  border-color: var(--paper);
  box-shadow: 5px 5px 0 rgba(255, 118, 95, .55);
  transform: translate(-2px, -2px);
}

.button.is-open {
  background: transparent;
  color: var(--coral);
  border-color: var(--coral);
  box-shadow: 4px 4px 0 rgba(255, 118, 95, .25);
}

.button.is-open:hover,
.button.is-open:focus-visible {
  background: var(--coral);
  color: var(--ink);
}

.arrow-icon {
  display: block;
  width: 21px;
  height: 21px;
  flex: 0 0 auto;
  transition: transform .4s var(--ease-out);
}

.button:hover .arrow-icon,
.button:focus-visible .arrow-icon,
.text-link:hover .arrow-icon,
.text-link:focus-visible .arrow-icon {
  transform: translateX(4px);
}

.button.is-open .arrow-icon {
  transform: rotate(180deg);
}

.button.is-open:hover .arrow-icon,
.button.is-open:focus-visible .arrow-icon {
  transform: rotate(180deg) translateX(-4px);
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--mist);
  font-family: var(--serif);
  font-size: 15px;
  font-style: italic;
  transition: color .25s var(--ease);
}

.text-link span {
  color: var(--coral);
  font-family: var(--sans);
  font-style: normal;
  font-size: 16px;
  transition: transform .3s var(--ease-out);
}

.text-link:hover,
.text-link:focus-visible {
  color: var(--paper);
}

.text-link:hover span,
.text-link:focus-visible span {
