}

.type-case {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: clamp(28px, 3.6vw, 48px);
  padding: 18px clamp(18px, 2.4vw, 28px) 14px;
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .55), rgba(14, 20, 32, .65));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 18px 40px -22px rgba(0, 0, 0, .55);
  color: var(--mist);
  transition: border-color .5s var(--ease), background .5s var(--ease);
}

.type-case::before {
  position: absolute;
  top: -1px;
  left: 24px;
  right: 24px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--acid) 30%, var(--coral) 70%, transparent);
  opacity: .35;
  content: '';
}

.type-case__caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin: 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.type-case__label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--coral);
}

.type-case__dot {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 118, 95, .15);
  animation: composePulse 2.4s var(--ease) infinite;
}

.type-case__face {
  color: var(--mist);
}

.type-case__meta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--acid);
}

.type-case__folio {
  color: var(--coral);
}

.type-case__rail {
  position: relative;
  display: flex;
  align-items: end;
  padding: 18px 4px 16px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  overflow-x: auto;
  scrollbar-width: none;
}

.type-case__rail::-webkit-scrollbar {
  display: none;
}

.type-case__line {
  display: flex;
  align-items: end;
  gap: 5px;
  flex-wrap: wrap;
}

.type-case__piece {
  position: relative;
  display: inline-block;
  padding: 5px 10px 7px;
  font-family: var(--serif);
  font-size: clamp(20px, 2.6vw, 32px);
  font-style: italic;
  font-weight: 400;
  line-height: 1;
  color: var(--ink);
  background: linear-gradient(180deg, var(--lead-1) 0%, var(--lead-2) 100%);
  box-shadow:
    inset 0 -2px 0 rgba(0, 0, 0, .35),
    inset 0 1px 0 rgba(255, 255, 255, .25),
    2px 3px 0 rgba(0, 0, 0, .35);
  transform: translateY(-2px);
  transition: transform .45s var(--ease-spring), box-shadow .45s var(--ease), background .45s var(--ease);
}

.type-case__piece::after {
  content: '';
  position: absolute;
  top: 4px;
  right: 3px;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--ink);
  opacity: .18;
  transition: opacity .35s var(--ease);
}

.type-case__piece.is-marked {
  background: linear-gradient(180deg, #e8f5c8 0%, #c8d8a0 100%);
}

.type-case__piece.is-active {
  transform: translateY(-9px) rotate(-1.4deg);
  box-shadow:
    inset 0 -2px 0 rgba(0, 0, 0, .35),
    inset 0 1px 0 rgba(255, 255, 255, .5),
    4px 9px 0 rgba(0, 0, 0, .55),
    0 16px 22px rgba(0, 0, 0, .35);
  z-index: 2;
}

.type-case__piece.is-active::after {
  opacity: .55;
}

.type-case__piece:nth-child(2).is-active {
  transform: translateY(-9px) rotate(1.2deg);
}

.type-case__piece:nth-child(3).is-active {
  transform: translateY(-9px) rotate(-.6deg);
}

.type-case__piece:nth-child(5).is-active {
  transform: translateY(-9px) rotate(.8deg);
}

.type-case__piece-kern {
  position: absolute;
  bottom: -6px;
  left: 50%;
  width: 1px;
  height: 4px;
  background: var(--ink);
  opacity: .25;
  transform: translate(-50%, 0);
}

.type-case--human .type-case__piece {
  background: linear-gradient(180deg, #f0d8c8 0%, #d4a890 100%);
}

.type-case--human .type-case__piece.is-marked {
  background: linear-gradient(180deg, #ffe0d0 0%, #e8b8a0 100%);
}

.type-case--bold .type-case__piece {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: -.04em;
  background: linear-gradient(180deg, var(--lead-1) 0%, var(--lead-3) 100%);
}

.type-case--bold .type-case__piece.is-marked {
  background: linear-gradient(180deg, #d8e8b0 0%, #a8c070 100%);
  color: var(--ink);
}

.type-case__foot {
  display: flex;
  align-items: center;
  gap: 16px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
}

.type-case__count {
  color: var(--coral);
}

.type-case__scale {
  flex: 1;
  display: flex;
  align-items: end;
  gap: 1px;
  height: 16px;
  position: relative;
  padding: 0 2px;
}

.type-case__scale span {
  flex: 1;
  height: 4px;
  background: var(--mist);
  opacity: .22;
  border-radius: 0;
  transition: opacity .3s var(--ease), background .3s var(--ease), height .3s var(--ease);
}

.type-case__scale span.is-major {
  height: 10px;
  background: var(--acid);
  opacity: .55;
}

.type-case__ink {
  color: var(--mist);
}


@keyframes composePulse {
  0%, 100% { box-shadow: 0 0 0 4px rgba(255, 118, 95, .12); }
  50% { box-shadow: 0 0 0 8px rgba(255, 118, 95, 0); }
}

/* ────────────────────────────────────────────────────────────
   COMPOSE FLOOR · the working spread between question and proof
   ──────────────────────────────────────────────────────────── */

.compose-floor {
  position: relative;
  padding: clamp(80px, 10vw, 130px) 0 clamp(40px, 6vw, 80px);
}

.compose-floor__sheet {
  position: relative;
  display: grid;
  gap: clamp(22px, 3vw, 36px);
  padding: clamp(36px, 5vw, 64px) clamp(26px, 4vw, 56px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 92% 4%, rgba(216, 255, 98, .06), transparent 50%),
    radial-gradient(circle at 6% 96%, rgba(255, 118, 95, .05), transparent 50%),
    linear-gradient(180deg, rgba(30, 38, 54, .5), rgba(14, 20, 32, .62));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 36px 90px -34px rgba(0, 0, 0, .55);
}

.compose-floor__sheet::before {
  position: absolute;
  inset: 9px;
  border: 1px dashed rgba(146, 186, 255, .07);
  pointer-events: none;
  content: '';
}

.compose-floor__plate {
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translate(-50%, -55%);
  padding: 4px 14px;
  border: 1px solid var(--line);
  border-top: 0;
  background: var(--night);
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
  white-space: nowrap;
  z-index: 2;
}

.compose-floor__crop {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 0 solid var(--acid);
  pointer-events: none;
  opacity: .55;
}

.compose-floor__crop--tl { top: -1px; left: -1px; border-top-width: 1px; border-left-width: 1px; }
.compose-floor__crop--tr { top: -1px; right: -1px; border-top-width: 1px; border-right-width: 1px; }
.compose-floor__crop--bl { bottom: -1px; left: -1px; border-bottom-width: 1px; border-left-width: 1px; }
.compose-floor__crop--br { bottom: -1px; right: -1px; border-bottom-width: 1px; border-right-width: 1px; }

.compose-floor__head {
