    radial-gradient(circle at 6% 0%, rgba(216, 255, 98, .05), transparent 50%),
    repeating-linear-gradient(92deg, rgba(255, 255, 255, .014) 0 1px, transparent 1px 8px),
    linear-gradient(180deg, rgba(28, 36, 52, .55), rgba(14, 20, 32, .68));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
