    0 18px 40px -22px rgba(0, 0, 0, .55);
  transition: border-color .5s var(--ease), background .5s var(--ease);
}

.compose-floor__case::before {
  position: absolute;
  top: -1px;
  left: 24px;
  right: 24px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--acid) 30%, var(--coral) 70%, transparent);
  opacity: .35;
  content: '';
}

.compose-floor__case-caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin: 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.compose-floor__case-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--coral);
}

.compose-floor__case-dot {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 118, 95, .15);
  animation: composePulse 2.4s var(--ease) infinite;
}

.compose-floor__case-face {
  color: var(--mist);
}

.compose-floor__case-ink {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--acid);
}

.compose-floor__case-ink-tone {
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: -.01em;
  text-transform: none;
}

.compose-floor__case-ink-tone--acid { color: var(--acid); }
.compose-floor__case-ink-tone--coral { color: var(--coral); }
.compose-floor__case-ink-tone--blue { color: var(--blue); }

.compose-floor__rail {
  position: relative;
  display: flex;
  align-items: end;
  padding: 22px 4px 18px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  overflow-x: auto;
  scrollbar-width: none;
}

.compose-floor__rail::-webkit-scrollbar {
  display: none;
}

.compose-floor__line {
  display: flex;
  align-items: end;
  gap: 6px;
  flex-wrap: wrap;
}

.compose-floor__piece {
  position: relative;
  display: inline-block;
  padding: 6px 12px 8px;
  font-family: var(--serif);
  font-size: clamp(20px, 2.6vw, 32px);
  font-style: italic;
  font-weight: 400;
  line-height: 1;
  color: var(--ink);
  background: linear-gradient(180deg, var(--lead-1) 0%, var(--lead-2) 100%);
  box-shadow:
    inset 0 -2px 0 rgba(0, 0, 0, .35),
    inset 0 1px 0 rgba(255, 255, 255, .3),
    inset 2px 0 0 rgba(255, 255, 255, .12),
    inset -2px 0 0 rgba(0, 0, 0, .12),
    2px 3px 0 rgba(0, 0, 0, .38);
  transform: translateY(-2px);
  transition: transform .45s var(--ease-spring), box-shadow .45s var(--ease), background .45s var(--ease);
}

.compose-floor__piece::after {
  content: '';
  position: absolute;
  top: 4px;
  right: 3px;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--ink);
  opacity: .18;
  transition: opacity .35s var(--ease);
}

.compose-floor__piece.is-marked {
  background: linear-gradient(180deg, #e8f5c8 0%, #c8d8a0 100%);
}

.compose-floor__piece.is-active {
  transform: translateY(-9px) rotate(-1.4deg);
  box-shadow:
    inset 0 -2px 0 rgba(0, 0, 0, .35),
    inset 0 1px 0 rgba(255, 255, 255, .55),
    inset 2px 0 0 rgba(255, 255, 255, .22),
    inset -2px 0 0 rgba(0, 0, 0, .22),
    4px 9px 0 rgba(0, 0, 0, .58),
    0 18px 26px rgba(0, 0, 0, .38);
  z-index: 2;
}

.compose-floor__piece.is-active::after {
  opacity: .55;
}

.compose-floor__piece:nth-child(2).is-active {
  transform: translateY(-9px) rotate(1.2deg);
}

.compose-floor__piece:nth-child(3).is-active {
  transform: translateY(-9px) rotate(-.6deg);
}

.compose-floor__piece:nth-child(5).is-active {
  transform: translateY(-9px) rotate(.8deg);
}

.compose-floor__piece-kern {
  position: absolute;
  bottom: -6px;
  left: 50%;
  width: 1px;
  height: 4px;
  background: var(--ink);
  opacity: .25;
  transform: translate(-50%, 0);
}

.compose-floor__case--human .compose-floor__piece {
  background: linear-gradient(180deg, #f0d8c8 0%, #d4a890 100%);
}

.compose-floor__case--human .compose-floor__piece.is-marked {
  background: linear-gradient(180deg, #ffe0d0 0%, #e8b8a0 100%);
}

.compose-floor__case--bold .compose-floor__piece {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: -.04em;
  background: linear-gradient(180deg, var(--lead-1) 0%, var(--lead-3) 100%);
}

.compose-floor__case--bold .compose-floor__piece.is-marked {
  background: linear-gradient(180deg, #d8e8b0 0%, #a8c070 100%);
  color: var(--ink);
}

.compose-floor__case-foot {
  display: flex;
  align-items: center;
  gap: 16px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
}

.compose-floor__case-count {
  color: var(--coral);
}

.compose-floor__case-rule {
  flex: 1;
  height: 1px;
  background: repeating-linear-gradient(to right, var(--line) 0 4px, transparent 4px 9px);
}

.compose-floor__case-jog {
  display: inline-flex;
  flex-direction: column;
  align-items: end;
  gap: 3px;
  color: var(--acid);
}

.compose-floor__case-jog-line {
  display: block;
  height: 1px;
  background: currentColor;
  opacity: .75;
}

.compose-floor__case-jog-line:nth-child(1) { width: 22px; }
.compose-floor__case-jog-line:nth-child(2) { width: 12px; opacity: .55; }
.compose-floor__case-jog-line:nth-child(3) { width: 18px; opacity: .85; }

.compose-floor__margin {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, auto) 1fr;
  align-items: stretch;
  gap: clamp(16px, 2.6vw, 36px);
  padding: clamp(18px, 2.6vw, 28px) clamp(18px, 2.6vw, 28px) clamp(18px, 2.6vw, 28px) 0;
  border: 1px solid var(--line);
  background:
    repeating-radial-gradient(circle at 0 0, rgba(146, 186, 255, .025) 0 1px, transparent 1px 4px),
    repeating-radial-gradient(circle at 2px 2px, rgba(216, 255, 98, .02) 0 1px, transparent 1px 5px),
    rgba(23, 30, 45, .55);
  isolation: isolate;
  overflow: hidden;
}

.compose-floor__margin::before {
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: var(--acid);
  opacity: .35;
  content: '';
  transition: background .45s var(--ease), opacity .45s var(--ease);
}

.compose-floor__margin--m3::before { background: var(--acid); opacity: .55; }
.compose-floor__margin--good::before { background: var(--coral); opacity: .55; }
.compose-floor__margin--yet::before { background: var(--blue); opacity: .55; }

.compose-floor__margin-rule {
  position: absolute;
  top: 14px;
  bottom: 14px;
  left: 38px;
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 8%, var(--line) 92%, transparent);
}

.compose-floor__margin-pin {
  position: relative;
  display: inline-flex;
  align-self: start;
  width: 38px;
  justify-content: center;
  padding-top: 6px;
  z-index: 1;
}

.compose-floor__pin {
  display: block;
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  transition: transform .55s var(--ease-spring);
}

.compose-floor__margin--m3 .compose-floor__pin { transform: rotate(-4deg); }
.compose-floor__margin--good .compose-floor__pin { transform: rotate(2deg); }
.compose-floor__margin--yet .compose-floor__pin { transform: rotate(-2deg); }

.compose-floor__margin-card {
  position: relative;
  display: grid;
  gap: clamp(12px, 1.6vw, 18px);
  padding: 0 clamp(2px, .4vw, 6px);
  animation: marginaliaIn .65s var(--ease-out);
}

.compose-floor__margin-head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: clamp(8px, 1.4vw, 18px);
  padding-bottom: clamp(8px, 1vw, 12px);
  border-bottom: 1px dotted var(--line);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.compose-floor__margin--m3 .compose-floor__margin-head { color: var(--acid); }
.compose-floor__margin--good .compose-floor__margin-head { color: var(--coral); }
.compose-floor__margin--yet .compose-floor__margin-head { color: var(--blue); }

.compose-floor__margin-num {
  font-weight: 700;
}

.compose-floor__margin-mark {
  font-weight: 700;
}

.compose-floor__margin-folio {
  margin-left: auto;
  color: var(--muted);
  font-weight: 500;
}

.compose-floor__margin-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1.4fr);
  gap: clamp(16px, 2.6vw, 36px);
  align-items: start;
}

.compose-floor__margin-title {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.compose-floor__margin-label {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.compose-floor__margin--m3 .compose-floor__margin-label { color: var(--acid); }
.compose-floor__margin--good .compose-floor__margin-label { color: var(--coral); }
.compose-floor__margin--yet .compose-floor__margin-label { color: var(--blue); }

.compose-floor__margin-title strong {
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(22px, 2.4vw, 32px);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.035em;
  line-height: 1;
}

.compose-floor__margin-text {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.compose-floor__margin-text em {
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(13px, 1.2vw, 15px);
  font-style: italic;
  letter-spacing: -.01em;
  line-height: 1.4;
}

.compose-floor__margin-text p {
  margin: 0;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: clamp(14px, 1.3vw, 16px);
  line-height: 1.55;
}

.compose-floor__margin-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px 18px;
  padding-top: clamp(8px, 1vw, 12px);
  border-top: 1px dotted var(--line);
}

.compose-floor__margin-prompt {
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(13px, 1.2vw, 15px);
  font-style: italic;
}

.compose-floor__margin-seen {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.compose-floor__margin-seen > span[aria-hidden] {
  color: var(--acid);
}

.compose-floor__margin--m3 .compose-floor__margin-seen > span[aria-hidden] { color: var(--acid); }
.compose-floor__margin--good .compose-floor__margin-seen > span[aria-hidden] { color: var(--coral); }
.compose-floor__margin--yet .compose-floor__margin-seen > span[aria-hidden] { color: var(--blue); }

.compose-floor__margin-dot {
  color: var(--ink-mist) !important;
  opacity: .6;
}

.compose-floor__caption {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  max-width: 64ch;
  margin: 4px 0 0;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  line-height: 1.55;
}

.compose-floor__caption-mark {
  color: var(--coral);
  font-style: normal;
  font-size: 16px;
}

@media (max-width: 880px) {
  .compose-floor__sheet {
    padding: clamp(28px, 5vw, 40px) clamp(20px, 4vw, 28px);
  }

  .compose-floor__case {
    padding: 14px 16px 12px;
  }

  .compose-floor__piece {
    font-size: 18px;
    padding: 4px 8px 6px;
  }

  .compose-floor__margin {
    grid-template-columns: 1fr;
    padding-left: 0;
    gap: 12px;
  }

  .compose-floor__margin-rule {
    left: 0;
    right: 0;
    top: 36px;
    bottom: auto;
    width: auto;
    height: 1px;
    background: linear-gradient(to right, transparent, var(--line) 8%, var(--line) 92%, transparent);
  }

  .compose-floor__margin-pin {
    flex-direction: row;
    align-self: start;
    width: 100%;
    justify-content: flex-start;
    padding: 0 0 6px 0;
  }

  .compose-floor__margin-grid {
    grid-template-columns: 1fr;
    gap: 14px;
  }
}

@media (max-width: 540px) {
  .compose-floor__sheet {
    padding: 26px 18px 22px;
  }

  .compose-floor__case-foot {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }

  .compose-floor__case-rule {
    width: 100%;
  }
}

/* ────────────────────────────────────────────────────────────
   SPECIMEN DRAWER · three pressings laid out at folio v
   ──────────────────────────────────────────────────────────── */

.specimen-spread {
  position: relative;
  padding: clamp(98px, 13vw, 180px) 0 clamp(80px, 9vw, 130px);
  border-top: 1px solid var(--line-soft);
}

.specimen-spread__header {
  max-width: 820px;
}

.specimen-spread__header h2 {
  max-width: 720px;
  margin: 22px 0 18px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5.2vw, 5.6rem);
  font-weight: 400;
  letter-spacing: -.068em;
  line-height: .92;
  text-wrap: balance;
}

.specimen-spread__header h2 i {
  color: var(--coral);
  font-style: italic;
}

.specimen-spread__header .section__lede {
  max-width: 60ch;
}

.specimen-drawer {
  position: relative;
  margin-top: clamp(48px, 6vw, 84px);
  padding: clamp(24px, 3vw, 40px) clamp(18px, 2.6vw, 36px) clamp(28px, 3.6vw, 48px);
  border: 1px solid var(--line);
  background:
    radial-gradient(ellipse at 50% -10%, rgba(216, 255, 98, .05), transparent 55%),
    radial-gradient(ellipse at 50% 110%, rgba(255, 118, 95, .04), transparent 60%),
    linear-gradient(180deg, rgba(20, 26, 38, .72), rgba(12, 16, 24, .88));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    inset 0 18px 32px -22px rgba(0, 0, 0, .5),
    0 36px 90px -34px rgba(0, 0, 0, .55);
}

.specimen-drawer::before {
  content: '';
  position: absolute;
  inset: 9px;
  border: 1px dashed rgba(146, 186, 255, .07);
  pointer-events: none;
}

.specimen-drawer__rail {
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  padding-bottom: clamp(14px, 2vw, 22px);
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.specimen-drawer__rail-handle {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px 5px;
  border: 1px solid var(--line);
  border-radius: 1px;
  background: rgba(28, 36, 52, .55);
  transition: border-color .4s var(--ease), background .4s var(--ease);
}

.specimen-drawer:hover .specimen-drawer__rail-handle {
  border-color: rgba(255, 118, 95, .35);
  background: rgba(28, 36, 52, .75);
}

.specimen-drawer__rail-dot {
  display: block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  border: 1px solid var(--coral);
  background: transparent;
  transition: background .35s var(--ease);
}

.specimen-drawer__rail-dot--mid {
  background: var(--coral);
  border-color: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 118, 95, .16);
  animation: composePulse 2.4s var(--ease) infinite;
}

.specimen-drawer__rail-line {
  flex: 1;
  height: 1px;
  background: repeating-linear-gradient(to right, var(--line) 0 4px, transparent 4px 8px);
}

.specimen-drawer__rail-text {
  color: var(--coral);
  white-space: nowrap;
}

.specimen-drawer__rail-tag {
  color: var(--muted);
  padding: 3px 8px;
  border: 1px solid var(--line);
  border-radius: 1px;
}

.specimen-drawer__stack {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(18px, 2.6vw, 36px);
  margin: clamp(28px, 4vw, 48px) 0 0;
  padding: 0;
  list-style: none;
  perspective: 1600px;
}

.specimen-drawer__slot {
  position: relative;
  display: flex;
  flex-direction: column;
  transition: transform .65s var(--ease-spring);
}

.specimen-drawer__slot:not(.is-active) {
  transform: translateY(14px) scale(.965);
  filter: saturate(.7) brightness(.78);
}

.specimen-drawer__slot:not(.is-active) .specimen-drawer__card {
  opacity: .82;
}

.specimen-drawer__slot.is-active {
  transform: translateY(-10px) scale(1.02);
}

.specimen-drawer__card {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  min-height: 100%;
  padding: clamp(24px, 2.8vw, 40px) clamp(20px, 2.4vw, 32px) clamp(20px, 2.4vw, 32px);
  border: 1px solid rgba(146, 186, 255, .14);
  background:
    radial-gradient(circle at 100% 0%, rgba(216, 255, 98, .05), transparent 60%),
    radial-gradient(circle at 0% 100%, rgba(255, 118, 95, .04), transparent 55%),
    var(--card-paper, rgba(23, 30, 45, .82));
  color: var(--card-ink, var(--paper));
  text-align: left;
  cursor: pointer;
  transition:
    transform .65s var(--ease-spring),
    box-shadow .55s var(--ease),
    border-color .5s var(--ease),
    background .55s var(--ease);
  isolation: isolate;
  overflow: hidden;
}

.specimen-drawer__card::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 0 0, rgba(146, 186, 255, .035) 0 1px, transparent 1px 4px),
    radial-gradient(circle at 2px 2px, rgba(216, 255, 98, .02) 0 1px, transparent 1px 5px);
  pointer-events: none;
  z-index: 0;
}

.specimen-drawer__card:hover,
.specimen-drawer__card:focus-visible {
  border-color: var(--coral);
  transform: translateY(-4px);
  box-shadow:
    0 18px 36px -18px rgba(0, 0, 0, .55),
    0 0 0 1px var(--coral);
}

.specimen-drawer__slot.is-active .specimen-drawer__card {
  border-color: var(--coral);
  box-shadow:
    0 30px 60px -22px rgba(0, 0, 0, .7),
    0 0 0 1px var(--coral),
    inset 0 0 0 1px rgba(255, 118, 95, .18);
  transform: translateY(-6px);
}

.specimen-drawer__corner {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 0 solid currentColor;
  opacity: .5;
  pointer-events: none;
  z-index: 2;
  transition: opacity .4s var(--ease), border-color .5s var(--ease);
}

.specimen-drawer__corner--tl { top: 6px; left: 6px; border-top-width: 1px; border-left-width: 1px; }
.specimen-drawer__corner--tr { top: 6px; right: 6px; border-top-width: 1px; border-right-width: 1px; }
.specimen-drawer__corner--bl { bottom: 6px; left: 6px; border-bottom-width: 1px; border-left-width: 1px; }
.specimen-drawer__corner--br { bottom: 6px; right: 6px; border-bottom-width: 1px; border-right-width: 1px; }

.specimen-drawer__slot.is-active .specimen-drawer__corner {
  opacity: 1;
  border-color: var(--coral);
}

.specimen-drawer__reg {
  position: absolute;
  width: 16px;
  height: 16px;
  color: var(--mist);
  opacity: .3;
  pointer-events: none;
  z-index: 2;
  transition: opacity .5s var(--ease), color .5s var(--ease);
}

.specimen-drawer__reg svg {
  display: block;
  width: 100%;
  height: 100%;
}

.specimen-drawer__reg--tl { top: -10px; left: -10px; }
.specimen-drawer__reg--tr { top: -10px; right: -10px; }
.specimen-drawer__reg--bl { bottom: -10px; left: -10px; }
.specimen-drawer__reg--br { bottom: -10px; right: -10px; }

.specimen-drawer__slot.is-active .specimen-drawer__reg {
  opacity: .9;
  color: var(--coral);
}

.specimen-drawer__head {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: baseline;
  gap: clamp(10px, 1.4vw, 16px);
  padding-bottom: clamp(14px, 1.8vw, 22px);
  border-bottom: 1px dashed var(--line);
}

.specimen-drawer__letter {
  display: grid;
  width: clamp(34px, 3vw, 40px);
  height: clamp(34px, 3vw, 40px);
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: var(--card-ink, var(--coral));
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(18px, 1.6vw, 22px);
  letter-spacing: -.02em;
  line-height: 1;
  transition: background .4s var(--ease), color .4s var(--ease);
}

.specimen-drawer__slot.is-active .specimen-drawer__letter {
  background: var(--card-ink, var(--coral));
  color: var(--night);
}

.specimen-drawer__copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.specimen-drawer__name {
  color: var(--card-ink, var(--paper));
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(20px, 1.9vw, 28px);
  letter-spacing: -.03em;
  line-height: 1;
}

.specimen-drawer__descriptor {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.specimen-drawer__stage {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: clamp(140px, 16vw, 220px);
  margin: clamp(18px, 2.4vw, 28px) 0 clamp(18px, 2.4vw, 28px);
  padding: clamp(14px, 1.8vw, 22px) clamp(8px, 1vw, 16px);
  border-top: 1px solid rgba(146, 186, 255, .12);
  border-bottom: 1px solid rgba(146, 186, 255, .12);
}

.specimen-drawer__guides {
  position: absolute;
  inset: 6px 6px 12px 6px;
  pointer-events: none;
  opacity: .45;
}

.specimen-drawer__guide {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor 12%, currentColor 88%, transparent);
  color: var(--card-ink, var(--paper));
  opacity: .35;
}

.specimen-drawer__guide--cap { top: 22%; }
.specimen-drawer__guide--x { top: 48%; }
.specimen-drawer__guide--base { top: 84%; opacity: .85; }

.specimen-drawer__specimen {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(2px, .3vw, 5px);
  color: var(--card-ink, var(--paper));
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(24px, 2.6vw, 40px);
  letter-spacing: -.055em;
  line-height: .96;
  z-index: 1;
}

.specimen-drawer__specimen span:nth-child(2) {
  color: var(--coral);
  margin-left: .25em;
}

.specimen-drawer__specimen span:nth-child(3) {
  color: var(--paper);
  margin-left: .85em;
}

.specimen-drawer__specimen--human span:nth-child(2) {
  color: var(--coral);
}

.specimen-drawer__specimen--human span:nth-child(3) {
  color: var(--paper);
}

.specimen-drawer__specimen--bold {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: -.07em;
  font-size: clamp(20px, 2.2vw, 34px);
  line-height: .92;
}

.specimen-drawer__specimen--bold span:nth-child(2),
.specimen-drawer__specimen--bold span:nth-child(3) {
  margin-left: .06em;
}

.specimen-drawer__specimen--bold span:nth-child(3) {
  color: var(--acid);
}

.specimen-drawer__foot {
  position: relative;
  z-index: 1;
  display: grid;
  gap: clamp(6px, .8vw, 10px);
  padding-top: clamp(12px, 1.6vw, 18px);
  border-top: 1px dashed var(--line);
  margin-top: auto;
}

.specimen-drawer__row {
  display: grid;
  grid-template-columns: 50px minmax(0, 1fr);
  gap: 12px;
  align-items: baseline;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.specimen-drawer__row-label {
  color: var(--coral);
  font-weight: 600;
}

.specimen-drawer__row-value {
  color: var(--card-ink, var(--paper));
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  letter-spacing: 0;
  text-transform: none;
}

.specimen-drawer__row-value--ink {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.specimen-drawer__swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, .45);
  box-shadow: 0 0 0 2px rgba(0, 0, 0, .25);
  flex: 0 0 auto;
}

.specimen-drawer__pulled {
  position: absolute;
  right: clamp(14px, 1.8vw, 24px);
  bottom: clamp(14px, 1.8vw, 24px);
  width: clamp(48px, 5vw, 64px);
  height: clamp(48px, 5vw, 64px);
  color: var(--card-ink, var(--coral));
  opacity: 0;
  transform: rotate(-10deg) scale(.7);
  transform-origin: center;
  pointer-events: none;
  transition: opacity .55s var(--ease) .1s, transform .7s var(--ease-spring) .1s;
  z-index: 3;
}

.specimen-drawer__slot.is-active .specimen-drawer__pulled {
  opacity: .85;
  transform: rotate(-3deg) scale(1);
}

.specimen-drawer__plate {
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.6vw, 22px);
  margin-top: clamp(20px, 2.6vw, 32px);
  padding-top: clamp(14px, 2vw, 20px);
  border-top: 1px dashed var(--line);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.specimen-drawer__plate-bar {
  flex: 1;
  height: 1px;
  background: repeating-linear-gradient(to right, var(--line) 0 4px, transparent 4px 8px);
}

.specimen-drawer__plate-text {
  color: var(--ink-mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: 0;
  text-transform: none;
  white-space: nowrap;
}

.specimen-drawer__foot-note {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  max-width: 60ch;
  margin: clamp(24px, 3.4vw, 40px) 0 0;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  line-height: 1.55;
}

.specimen-drawer__foot-note span[aria-hidden] {
  color: var(--coral);
  font-style: normal;
  font-size: 18px;
}

@media (max-width: 1080px) {
  .specimen-drawer__stack {
    gap: clamp(14px, 1.8vw, 22px);
  }

  .specimen-drawer__card {
    padding: 22px 18px 20px;
  }

  .specimen-drawer__head {
    gap: 10px;
  }

  .specimen-drawer__name {
    font-size: 18px;
  }

  .specimen-drawer__specimen {
    font-size: clamp(20px, 2.4vw, 28px);
  }

  .specimen-drawer__specimen--bold {
    font-size: clamp(18px, 2.1vw, 26px);
  }
}

@media (max-width: 880px) {
  .specimen-drawer__rail-text {
    display: none;
  }

  .specimen-drawer__rail-line:first-of-type {
    display: none;
  }

  .specimen-drawer__stack {
    grid-template-columns: 1fr;
    gap: 14px;
    margin-top: 24px;
  }

  .specimen-drawer__slot:not(.is-active) {
    transform: none;
    filter: saturate(.85) brightness(.88);
  }

  .specimen-drawer__slot:not(.is-active) .specimen-drawer__card {
    opacity: .82;
  }

  .specimen-drawer__slot.is-active {
    transform: none;
  }

  .specimen-drawer__card {
    min-height: 0;
  }

  .specimen-drawer__stage {
    min-height: 120px;
  }

  .specimen-drawer__pulled {
    width: 52px;
    height: 52px;
  }

  .specimen-drawer__plate-text {
    font-size: 11px;
  }
}

@media (max-width: 540px) {
  .specimen-drawer {
    padding: 22px 16px 24px;
  }

  .specimen-drawer__rail {
    padding-bottom: 12px;
  }

  .specimen-drawer__specimen {
    font-size: 22px;
  }

  .specimen-drawer__specimen--bold {
    font-size: 20px;
  }

  .specimen-drawer__row {
    grid-template-columns: 42px minmax(0, 1fr);
    font-size: 8px;
    gap: 10px;
  }

  .specimen-drawer__row-value {
    font-size: 12px;
  }

  .specimen-drawer__plate-text {
    font-size: 11px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .specimen-drawer__slot,
  .specimen-drawer__card,
  .specimen-drawer__pulled,
  .specimen-drawer__rail-dot--mid {
    transition: none !important;
    animation: none !important;
    transform: none !important;
  }

  .specimen-drawer__slot.is-active {
    transform: none !important;
  }

  .specimen-drawer__slot:not(.is-active) {
    transform: none !important;
    filter: none !important;
  }
}

/* ────────────────────────────────────────────────────────────
   ANSWER REVEAL · the tipped-in leaf
   ──────────────────────────────────────────────────────────── */

.answer-reveal {
  display: grid;
  grid-template-rows: 0fr;
  margin: clamp(28px, 4vw, 56px) 0 clamp(40px, 6vw, 80px);
  opacity: 0;
  visibility: hidden;
  transition: grid-template-rows .95s var(--ease-out), margin .95s var(--ease-out), opacity .35s var(--ease), visibility 0s linear .95s;
}

.answer-reveal.is-open {
  grid-template-rows: 1fr;
  margin: clamp(28px, 4vw, 56px) 0 clamp(40px, 6vw, 80px);
  opacity: 1;
  visibility: visible;
  transition: grid-template-rows .95s var(--ease-out), margin .95s var(--ease-out), opacity .65s var(--ease) .12s, visibility 0s linear 0s;
}

.answer-reveal__clip {
  min-height: 0;
  overflow: hidden;
  perspective: 1400px;
}

.answer-reveal__leaf {
  position: relative;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(255, 248, 230, .7), transparent 60%),
    radial-gradient(circle at 92% 8%, rgba(255, 118, 95, .14), transparent 60%),
    radial-gradient(circle at 6% 92%, rgba(216, 255, 98, .08), transparent 55%),
    linear-gradient(180deg, #f7f1e0 0%, #ece4cd 100%);
  box-shadow:
    18px 26px 0 -2px rgba(5, 8, 14, .36),
    0 36px 80px rgba(0, 0, 0, .28),
    inset 0 0 60px rgba(120, 90, 50, .04);
  color: var(--ink);
  transform: translateY(-36px) scale(.985) rotateX(-12deg);
  transform-origin: top center;
  transition:
    transform 1.15s var(--ease-out),
    box-shadow 1.15s var(--ease-out),
    filter 1.15s var(--ease-out);
  opacity: 0;
  filter: brightness(.92) saturate(.95);
}

.answer-reveal.is-open .answer-reveal__leaf {
  transform: translateY(0) scale(1) rotateX(0);
  opacity: 1;
  filter: brightness(1) saturate(1);
  transition:
    transform 1.15s var(--ease-out),
    opacity .7s var(--ease) .08s,
    box-shadow 1.15s var(--ease-out),
    filter 1.1s var(--ease-out) .15s;
}

.answer-reveal__leaf:hover {
  box-shadow:
    22px 32px 0 -2px rgba(5, 8, 14, .4),
    0 42px 96px rgba(0, 0, 0, .32);
}

.answer-reveal__leaf::before {
  position: absolute;
  top: 0;
  left: 0;
  width: 28px;
  height: 100%;
  background:
    linear-gradient(90deg, rgba(17, 21, 33, .14), transparent 60%),
    repeating-linear-gradient(90deg, rgba(17, 21, 33, .06) 0 1px, transparent 1px 6px);
  content: '';
  pointer-events: none;
}

.answer-reveal__leaf::after {
  position: absolute;
  top: 0;
  right: 0;
  width: 28px;
  height: 100%;
  background:
    linear-gradient(270deg, rgba(17, 21, 33, .12), transparent 60%),
    repeating-linear-gradient(90deg, rgba(17, 21, 33, .05) 0 1px, transparent 1px 6px);
  content: '';
  pointer-events: none;
}

/* Subtle paper grain that runs across the whole leaf surface. It
   is rendered from an SVG noise filter so the leaf reads as an actual
   sheet of paper rather than a printed panel. The grain sits below
   the inner copy and above the leaf surface gradient. */

.answer-reveal__leaf-grain {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 0;
  border-radius: inherit;
  opacity: 0;
  transition: opacity .8s var(--ease) .15s;
}

.answer-reveal.is-open .answer-reveal__leaf-grain {
  opacity: 1;
}

.answer-reveal__leaf-grain svg {
  width: 100%;
  height: 100%;
  display: block;
}

/* A small bleed of pigment that crosses from the leaf onto the
   surrounding page, so it reads as a freshly-tipped artifact rather
   than an inset panel. */

.answer-reveal__leaf-bleed {
  position: absolute;
  inset: -10px;
  pointer-events: none;
  z-index: 0;
  opacity: 0;
  transition: opacity .9s var(--ease) .35s;
}

.answer-reveal__leaf-bleed::before,
.answer-reveal__leaf-bleed::after {
  content: '';
  position: absolute;
  background:
    radial-gradient(ellipse at center, rgba(17, 21, 33, .22) 0%, transparent 70%);
  pointer-events: none;
}

.answer-reveal__leaf-bleed::before {
  left: -16px;
  top: 18%;
  width: 38px;
  height: 90px;
  transform: rotate(-5deg);
  filter: blur(2px);
}

.answer-reveal__leaf-bleed::after {
  right: -22px;
  bottom: 8%;
  width: 54px;
  height: 110px;
  transform: rotate(8deg);
  filter: blur(3px);
}

.answer-reveal.is-open .answer-reveal__leaf-bleed {
  opacity: 1;
}

/* A small dog-eared corner mark at the top-right that catches the
   eye and reinforces that this is a real folded leaf rather than
   a card. */

.answer-reveal__leaf-cornermark {
  position: absolute;
  top: -1px;
  right: -1px;
  width: 28px;
  height: 28px;
  pointer-events: none;
  z-index: 4;
  opacity: 0;
  transition: opacity .65s var(--ease) .55s, transform .9s cubic-bezier(.34, 1.32, .52, 1) .55s;
  transform: rotate(0deg);
}

.answer-reveal__leaf-cornermark::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(225deg, var(--paper-warm, #f3ecd6) 50%, transparent 50%);
  border-bottom: 1px solid rgba(170, 130, 80, .22);
  border-left: 1px solid rgba(170, 130, 80, .22);
}

.answer-reveal__leaf-cornermark::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 16px;
  height: 1px;
  background: linear-gradient(to right, transparent, rgba(120, 90, 60, .35), transparent);
  transform: translate(-50%, -50%) rotate(-45deg);
  transform-origin: center;
}

.answer-reveal.is-open .answer-reveal__leaf-cornermark {
  opacity: 1;
  transform: rotate(2deg);
}

@media (prefers-reduced-motion: reduce) {
  .answer-reveal__leaf-grain,
  .answer-reveal__leaf-bleed,
  .answer-reveal__leaf-cornermark {
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

.answer-reveal__gluetop {
  position: absolute;
  top: 0;
  left: 28px;
  right: 50%;
  height: 8px;
  background:
    linear-gradient(180deg, rgba(255, 230, 200, .7), rgba(255, 220, 180, .3));
  border-bottom: 1px solid rgba(180, 140, 90, .25);
  border-radius: 0 0 0 4px;
  transform: skewX(-22deg);
  transform-origin: top left;
  pointer-events: none;
  z-index: 3;
}

.answer-reveal__gluetop--right {
  left: 50%;
  right: 28px;
  border-radius: 0 0 4px 0;
  transform: skewX(22deg);
  transform-origin: top right;
}

.answer-reveal__tipped {
  position: absolute;
  top: 16px;
  left: 50%;
  transform: translate(-50%, -8px);
  padding: 4px 10px;
  border: 1px solid var(--line);
  border-radius: 1px;
  background: var(--night);
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0;
  transition: opacity .55s var(--ease) .25s, transform .55s var(--ease-spring) .25s;
  z-index: 4;
}

.answer-reveal.is-open .answer-reveal__tipped {
  opacity: 1;
  transform: translate(-50%, 0);
}

.answer-reveal__foldline {
  position: absolute;
  top: 38%;
  left: clamp(36px, 5vw, 76px);
  right: clamp(36px, 5vw, 76px);
  display: block;
  height: 24px;
  color: rgba(17, 21, 33, .25);
  opacity: 0;
  transform: scaleX(.85);
  transform-origin: left center;
  transition: opacity .85s var(--ease) .55s, transform 1.05s var(--ease-out) .55s;
  pointer-events: none;
  z-index: 1;
}

.answer-reveal.is-open .answer-reveal__foldline {
  opacity: 1;
  transform: scaleX(1);
}

@media (prefers-reduced-motion: reduce) {
  .answer-reveal__foldline {
    transition: none !important;
    transform: none !important;
  }
}

.answer-reveal__seal {
  position: absolute;
  top: 28px;
  right: clamp(22px, 4vw, 56px);
  width: 124px;
  height: 124px;
  color: var(--wax);
  pointer-events: none;
  opacity: 0;
  transform: rotate(-18deg) scale(1.35);
  transform-origin: center;
  transition: opacity .55s var(--ease) .35s, transform .9s cubic-bezier(.34, 1.5, .4, 1) .35s, filter .9s var(--ease) .35s;
  z-index: 2;
  filter: blur(2px);
}

.answer-reveal__seal::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 124px;
  height: 18px;
  transform: translate(-50%, -50%) scaleX(.4);
  border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(5, 8, 14, .35) 0%, transparent 70%);
  pointer-events: none;
  opacity: 0;
  transition: opacity .55s var(--ease) .95s, transform .9s var(--ease-out) .95s;
  z-index: -1;
}

.answer-reveal__seal .press-stamp {
  width: 100%;
  height: 100%;
  filter: drop-shadow(2px 3px 0 rgba(5, 8, 14, .22));
  transition: filter .9s var(--ease);
}

.answer-reveal.is-open .answer-reveal__seal {
  opacity: 1;
  transform: rotate(-3deg) scale(1);
  filter: blur(0);
}

.answer-reveal.is-open .answer-reveal__seal::after {
  opacity: 1;
  transform: translate(-50%, -50%) scaleX(1);
}

.answer-reveal__ink-drip {
  position: absolute;
  top: 124px;
  right: clamp(54px, 7vw, 92px);
  width: 40px;
  height: 110px;
  color: var(--wax);
  opacity: 0;
  pointer-events: none;
  transition: opacity .9s var(--ease) .85s;
  z-index: 2;
  transform: rotate(2deg);
}

.answer-reveal.is-open .answer-reveal__ink-drip {
  opacity: .62;
}

.answer-reveal__ink-drip-stroke {
  stroke-dasharray: 280 280;
  stroke-dashoffset: 280;
  transition: stroke-dashoffset 1.6s var(--ease-out) .95s;
}

.answer-reveal.is-open .answer-reveal__ink-drip-stroke {
  stroke-dashoffset: 0;
}

.answer-reveal__ink-drip-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .5s var(--ease), transform .6s var(--ease-spring);
  transform: translateY(-6px);
}

.answer-reveal.is-open .answer-reveal__ink-drip-bead {
  opacity: 1;
  transform: translateY(0);
  transition-delay: 1.7s;
}

.answer-reveal__ink-drip-splash {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .5s var(--ease) 1.85s, transform .7s var(--ease-spring) 1.85s;
  transform: scale(.3);
}

.answer-reveal.is-open .answer-reveal__ink-drip-splash {
  opacity: .8;
  transform: scale(1);
}

.answer-reveal__ink-drip-splash--alt {
  transition-delay: 1.95s;
}

.answer-reveal__press-used {
  position: absolute;
  right: clamp(28px, 4vw, 60px);
  bottom: clamp(20px, 3vw, 36px);
  display: inline-flex;
  align-items: center;
  gap: 14px;
  padding: 8px 12px 8px 10px;
  border: 1px solid rgba(17, 21, 33, .28);
  background: rgba(247, 240, 222, .6);
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
  pointer-events: none;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .6s var(--ease) .55s, transform .7s var(--ease-spring) .55s;
  z-index: 3;
  backdrop-filter: blur(2px);
}

.answer-reveal.is-open .answer-reveal__press-used {
  opacity: 1;
  transform: translateY(0);
}

.answer-reveal__press-used-mark {
  display: inline-flex;
  width: 32px;
  height: 32px;
  color: var(--coral);
  flex: 0 0 auto;
  opacity: .85;
  transition: transform .5s var(--ease-spring), color .45s var(--ease);
}

.answer-reveal.is-open .answer-reveal__press-used-mark {
  transform: rotate(-4deg);
}

.answer-reveal__press-used-text {
  max-width: 28ch;
  color: var(--ink);
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  letter-spacing: -.01em;
  text-transform: none;
  line-height: 1.35;
}

@media (max-width: 720px) {
  .answer-reveal__press-used {
    right: 16px;
    bottom: 16px;
    padding: 6px 10px;
    gap: 10px;
  }

  .answer-reveal__press-used-mark {
    width: 26px;
    height: 26px;
  }

  .answer-reveal__press-used-text {
    font-size: 10px;
    max-width: 18ch;
  }

  .answer-reveal__press-used-text strong { font-size: 11px; }
  .answer-reveal__press-used-text em { font-size: 7.5px; }

  .answer-reveal__ink-drip {
    left: 30%;
    height: 60px;
  }
}

.answer-reveal__inner {
  position: relative;
  padding: clamp(110px, 12vw, 170px) clamp(28px, 5vw, 80px) clamp(28px, 4vw, 48px);
}

.answer-reveal__leaf::before {
  z-index: 0;
}

.answer-reveal__inner::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(90deg, rgba(17, 21, 33, .04) 1px, transparent 1px),
    linear-gradient(0deg, rgba(17, 21, 33, .04) 1px, transparent 1px);
  background-size: 32px 32px;
  pointer-events: none;
  mask-image: linear-gradient(to bottom, transparent, black 14%, black 86%, transparent);
}

.answer-reveal__inner::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(rgba(17, 21, 33, .12) 1px, transparent 1px),
    radial-gradient(rgba(17, 21, 33, .05) 1px, transparent 1px);
  background-size: 3px 3px, 7px 7px;
