/* ────────────────────────────────────────────────────────────
   MARGINALIA · three slips pinned to a single reading rule
   ──────────────────────────────────────────────────────────── */

.section {
  padding: clamp(98px, 13vw, 180px) 0;
}

.section__header {
  max-width: 820px;
}

.section__header h2 {
  max-width: 720px;
  margin: 22px 0 18px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5.2vw, 5.6rem);
  font-weight: 400;
  letter-spacing: -.068em;
  line-height: .92;
  text-wrap: balance;
}

.section__header h2 i {
  color: var(--coral);
  font-style: italic;
}

.section__lede {
  max-width: 56ch;
  margin: 0;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.35vw, 18px);
  letter-spacing: -.005em;
  line-height: 1.55;
  text-wrap: pretty;
}

.marginalia-section {
  position: relative;
  border-top: 1px solid var(--line-soft);
}

.marginalia-section__header {
  position: relative;
}

.marginalia-section__thread {
  display: block;
  width: clamp(260px, 36vw, 460px);
  height: clamp(48px, 5vw, 80px);
  margin: clamp(20px, 2.4vw, 36px) 0 0 clamp(2px, .6vw, 12px);
  color: var(--coral);
  opacity: .75;
  pointer-events: none;
}

.marginalia-section__thread svg {
  display: block;
  width: 100%;
  height: 100%;
}

.marginalia-section__thread-stroke {
  stroke-dashoffset: 100;
  animation: slipThreadDraw 1.4s var(--ease-out) .35s forwards;
}

.marginalia-section__thread-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: slipThreadBead .35s var(--ease-spring) 1.7s forwards;
}

@keyframes slipThreadDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes slipThreadBead {
  from { opacity: 0; transform: scale(.3); }
  to { opacity: 1; transform: scale(1); }
}

.marginalia-section__rule {
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  width: min(100%, 1180px);
  margin: clamp(28px, 4vw, 52px) auto clamp(36px, 5vw, 64px);
  padding: 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8px, .74vw, 9.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.marginalia-section__rule-edge {
  display: inline-block;
  width: 14px;
  height: 1px;
  background: var(--coral);
  opacity: .65;
  flex: 0 0 auto;
}

.marginalia-section__rule-line {
  display: block;
  flex: 1;
  height: 1px;
  background: repeating-linear-gradient(to right, var(--line) 0 4px, transparent 4px 8px);
}

.marginalia-section__rule-tag {
  flex: 0 1 auto;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  white-space: nowrap;
  font-style: normal;
}

.marginalia-section__rail {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(18px, 2.6vw, 36px);
  width: min(100%, 1180px);
  margin: 0 auto;
  padding: clamp(20px, 3vw, 44px) 0 clamp(28px, 4vw, 56px);
  align-items: start;
}

.slip {
  --slip-rise: 0px;
  --slip-rotate: 0deg;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  padding: clamp(28px, 3vw, 44px) clamp(20px, 2.4vw, 30px) clamp(24px, 2.8vw, 36px);
  border: 1px solid rgba(146, 186, 255, .12);
  background:
    linear-gradient(180deg, rgba(34, 44, 64, .5), rgba(18, 24, 38, .62)),
    repeating-linear-gradient(0deg, rgba(146, 186, 255, .04) 0 1px, transparent 1px 28px);
  box-shadow:
    0 1px 0 rgba(146, 186, 255, .05) inset,
    0 24px 60px -34px rgba(0, 0, 0, .55);
  color: var(--paper);
  text-align: left;
  transform: translateY(var(--slip-rise)) rotate(var(--slip-rotate));
  transition:
    transform .65s var(--ease-spring),
    box-shadow .55s var(--ease),
    border-color .55s var(--ease),
    background .55s var(--ease),
    opacity .45s var(--ease);
  isolation: isolate;
  overflow: visible;
}

.slip::before {
  content: '';
  position: absolute;
  inset: 6px;
  border: 1px dashed rgba(146, 186, 255, .05);
  pointer-events: none;
  z-index: 0;
}

.slip--acid { --slip-tone: var(--acid); }
.slip--coral { --slip-tone: var(--coral); }
.slip--blue { --slip-tone: var(--blue); }

.slip__fold {
  position: absolute;
  top: 0;
  right: 0;
  width: 34px;
  height: 34px;
  color: var(--slip-tone);
  pointer-events: none;
  z-index: 2;
}

.slip__pin {
  position: absolute;
  top: -14px;
  left: 22px;
  width: 28px;
  height: 28px;
  display: inline-grid;
  place-items: center;
  pointer-events: none;
  z-index: 4;
  transform: rotate(-8deg);
  transition: transform .5s var(--ease-spring), filter .4s var(--ease);
  filter: drop-shadow(1px 2px 0 rgba(0, 0, 0, .35));
}

.slip--coral .slip__pin { transform: rotate(6deg); }
.slip--blue .slip__pin { transform: rotate(-3deg); }

.slip__wax {
  display: block;
  width: 100%;
  height: 100%;
  color: var(--slip-tone);
  transition: transform .5s var(--ease-spring), color .4s var(--ease);
}

.slip:hover .slip__pin,
.slip:focus-within .slip__pin,
.slip.is-selected .slip__pin {
  filter: drop-shadow(2px 3px 0 rgba(0, 0, 0, .45));
  animation: slipPinWobble .55s var(--ease-spring);
}

.slip--coral:hover .slip__pin,
.slip--coral:focus-within .slip__pin,
.slip--coral.is-selected .slip__pin { animation: slipPinWobbleAlt .55s var(--ease-spring); }

.slip--blue:hover .slip__pin,
.slip--blue:focus-within .slip__pin,
.slip--blue.is-selected .slip__pin { animation: slipPinWobbleThird .55s var(--ease-spring); }

@keyframes slipPinWobble {
  0% { transform: rotate(-8deg) scale(1); }
  40% { transform: rotate(-16deg) translateY(-2px) scale(1.08); }
  100% { transform: rotate(-8deg) scale(1); }
}

@keyframes slipPinWobbleAlt {
  0% { transform: rotate(6deg) scale(1); }
  40% { transform: rotate(14deg) translateY(-2px) scale(1.08); }
  100% { transform: rotate(6deg) scale(1); }
}

@keyframes slipPinWobbleThird {
  0% { transform: rotate(-3deg) scale(1); }
  40% { transform: rotate(-11deg) translateY(-2px) scale(1.08); }
  100% { transform: rotate(-3deg) scale(1); }
}

.slip__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  margin-bottom: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8px, .74vw, 9.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  z-index: 1;
}

.slip__index {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding: 0 4px;
  border: 1px solid currentColor;
  border-radius: 1px;
  color: var(--slip-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
  transition: background .35s var(--ease), color .35s var(--ease);
}

.slip.is-selected .slip__index {
  background: var(--slip-tone);
  color: var(--night);
}

.slip__folio {
  text-align: right;
  white-space: nowrap;
  opacity: .8;
}

.slip__rule {
  display: block;
  width: 100%;
  height: 1px;
  margin-bottom: clamp(14px, 1.6vw, 20px);
  background: linear-gradient(to right, var(--slip-tone) 0%, rgba(146, 186, 255, .12) 30%, transparent 100%);
  opacity: .85;
  z-index: 1;
}

.slip__label {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: clamp(10px, 1.2vw, 16px);
  z-index: 1;
}

.slip__label-eyebrow {
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8px, .74vw, 9.5px);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.slip__label-mark {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px 3px;
  border: 1px solid var(--slip-tone);
  border-radius: 1px;
  color: var(--slip-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: -.01em;
  text-transform: none;
  transition: background .35s var(--ease), color .35s var(--ease);
}

.slip.is-selected .slip__label-mark {
  background: var(--slip-tone);
  color: var(--night);
}

.slip__title {
  margin: 0 0 clamp(8px, 1vw, 12px);
  z-index: 1;
}

.slip__select {
  display: inline;
  padding: 0;
  background: transparent;
  border: 0;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.slip__title-text {
  font-family: var(--serif);
  font-size: clamp(22px, 2.2vw, 30px);
  font-weight: 400;
  letter-spacing: -.04em;
  line-height: 1.05;
  color: var(--paper);
  transition: color .35s var(--ease), text-shadow .5s var(--ease);
}

.slip:hover .slip__title-text,
.slip:focus-within .slip__title-text,
.slip.is-selected .slip__title-text {
  color: var(--slip-tone);
  text-shadow: 0 0 .5em color-mix(in srgb, var(--slip-tone) 35%, transparent);
}

.slip__gloss {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0 0 clamp(10px, 1.2vw, 14px);
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  line-height: 1.35;
  z-index: 1;
}

.slip__gloss em {
  color: var(--paper);
  font-style: italic;
}

.slip__gloss span {
  color: var(--muted);
  font-style: normal;
  opacity: .55;
}

.slip__gloss-editor {
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  color: var(--muted);
  opacity: .9;
}

.slip__body {
  margin: 0 0 clamp(14px, 1.8vw, 22px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: .02em;
  line-height: 1.75;
  z-index: 1;
}

.slip.is-dimmed .slip__body,
.slip.is-dimmed .slip__gloss {
  opacity: .55;
}

.slip__mark {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  margin: 0 0 clamp(12px, 1.4vw, 18px);
  color: var(--slip-tone);
  opacity: .85;
  z-index: 1;
}

.slip__glyph-svg {
  display: block;
  width: clamp(36px, 3vw, 48px);
  height: auto;
}

.slip__glyph-stroke {
  stroke-dashoffset: 100;
  animation: slipGlyphDraw 1s var(--ease-out) .6s forwards;
}

.slip__glyph-fill,
.slip__glyph-bead {
  opacity: 0;
  animation: slipGlyphAppear .4s var(--ease-spring) .9s forwards;
}

@keyframes slipGlyphDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes slipGlyphAppear {
  from { opacity: 0; transform: scale(.4); transform-box: fill-box; transform-origin: center; }
  to { opacity: 1; transform: scale(1); transform-box: fill-box; transform-origin: center; }
}

.slip__foot {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
  margin-top: auto;
  padding-top: clamp(10px, 1.2vw, 14px);
  border-top: 1px dashed rgba(146, 186, 255, .08);
  z-index: 1;
}

.slip__foot-rule {
  display: none;
}

.slip__flourish {
  display: block;
  width: 100%;
  height: 12px;
  color: var(--slip-tone);
  opacity: .65;
  transition: opacity .35s var(--ease);
}

.slip:hover .slip__flourish,
.slip:focus-within .slip__flourish,
.slip.is-selected .slip__flourish {
  opacity: 1;
}

.slip__flourish-stroke {
  stroke-dashoffset: 100;
  animation: slipFlourishDraw 1.2s var(--ease-out) .85s forwards;
}

.slip__flourish-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: slipFlourishBead .35s var(--ease-spring) 1.9s forwards;
}

@keyframes slipFlourishDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes slipFlourishBead {
  from { opacity: 0; transform: scale(.3); }
  to { opacity: 1; transform: scale(1); }
}

.slip__foot-prompt {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  line-height: 1.2;
}

.slip__foot-prompt-mark {
  color: var(--slip-tone);
  font-family: var(--sans);
  font-style: normal;
  font-size: 14px;
  transition: transform .35s var(--ease-out);
}

.slip:hover .slip__foot-prompt-mark,
.slip:focus-within .slip__foot-prompt-mark,
.slip.is-selected .slip__foot-prompt-mark {
  transform: translate(2px, -2px);
}

.slip__foot-seen {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: 0;
  opacity: .85;
}

.slip__tack {
  position: absolute;
  left: -1px;
  bottom: -1px;
  width: 14px;
  height: 14px;
  border-bottom: 1px solid currentColor;
  border-left: 1px solid currentColor;
  color: var(--slip-tone);
  opacity: .7;
  pointer-events: none;
}

.slip__tack-slip {
  position: absolute;
  right: -1px;
  top: -1px;
  width: 14px;
  height: 14px;
  border-top: 1px solid currentColor;
  border-right: 1px solid currentColor;
  color: var(--slip-tone);
  opacity: .35;
  pointer-events: none;
}

.slip:hover,
.slip:focus-within,
.slip.is-selected {
  border-color: var(--slip-tone);
  background:
    linear-gradient(180deg, rgba(40, 52, 76, .66), rgba(20, 28, 44, .78)),
    repeating-linear-gradient(0deg, rgba(146, 186, 255, .04) 0 1px, transparent 1px 28px);
  box-shadow:
    0 1px 0 rgba(146, 186, 255, .08) inset,
    0 36px 80px -34px rgba(0, 0, 0, .7);
}

.slip.is-selected {
  transform: translateY(calc(var(--slip-rise) - 8px)) rotate(0deg);
}

.slip.is-dimmed {
  opacity: .5;
}

.slip.is-kept {
  background:
    linear-gradient(180deg, rgba(255, 118, 95, .08), rgba(18, 24, 38, .62)),
    repeating-linear-gradient(0deg, rgba(255, 118, 95, .04) 0 1px, transparent 1px 28px);
  border-color: rgba(240, 110, 91, .32);
}

.slip.is-kept.is-selected {
  background:
    linear-gradient(180deg, rgba(255, 118, 95, .14), rgba(20, 28, 44, .78)),
    repeating-linear-gradient(0deg, rgba(255, 118, 95, .05) 0 1px, transparent 1px 28px);
}

.slip__seal-wrap {
  position: absolute;
  right: -22px;
  top: -22px;
  width: 72px;
  height: 72px;
  display: inline-grid;
  place-items: center;
  pointer-events: none;
  z-index: 5;
  transform: rotate(8deg);
  animation: slipSealIn .8s var(--ease-spring) 1s backwards;
}

.slip__seal {
  width: 100%;
  height: 100%;
  display: block;
}

.slip--coral .slip__seal { color: var(--coral); }

@keyframes slipSealIn {
  0% { opacity: 0; transform: rotate(-18deg) scale(1.4); }
  60% { opacity: 1; transform: rotate(2deg) scale(.95); }
  100% { opacity: 1; transform: rotate(8deg) scale(1); }
}

.marginalia-section__caption {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin: clamp(18px, 2.4vw, 32px) 0 0;
  padding: 0;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  line-height: 1.4;
  letter-spacing: 0;
}

.marginalia-section__caption span {
  color: var(--coral);
  font-family: var(--mono);
  font-style: normal;
  font-size: 11px;
  letter-spacing: .18em;
}

@media (max-width: 880px) {
  .marginalia-section__rail {
    grid-template-columns: 1fr;
    gap: clamp(22px, 3vw, 32px);
    padding: clamp(14px, 2vw, 24px) 0;
  }

  .slip {
    --slip-rise: 0px;
    --slip-rotate: 0deg;
  }

  .slip__seal-wrap {
    right: 6px;
    top: -18px;
    width: 56px;
    height: 56px;
  }
}

@media (max-width: 540px) {
  .marginalia-section__thread {
    width: 60%;
    height: 60px;
  }

  .slip {
    padding: clamp(24px, 5vw, 32px) clamp(18px, 4vw, 24px) clamp(22px, 4vw, 28px);
  }

  .slip__title-text {
    font-size: 22px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .marginalia-section__thread-stroke {
    stroke-dashoffset: 0 !important;
    animation: none !important;
  }
  .marginalia-section__thread-bead {
    opacity: 1 !important;
    transform: none !important;
    animation: none !important;
  }
  .slip__glyph-stroke,
  .slip__glyph-fill,
  .slip__glyph-bead,
  .slip__flourish-stroke,
  .slip__flourish-bead {
    animation: none !important;
    opacity: 1 !important;
    stroke-dashoffset: 0 !important;
    transform: none !important;
  }
  .slip:hover,
  .slip:focus-within,
  .slip.is-selected,
  .slip__pin,
  .slip.is-selected {
    transition: none !important;
    animation: none !important;
  }
  .slip__seal-wrap {
    animation: none !important;
    transform: rotate(8deg) !important;
    opacity: 1 !important;
  }
}

/* ────────────────────────────────────────────────────────────
   VOICES · triptych of typographic readings
   ──────────────────────────────────────────────────────────── */

.voices-section {
  margin-right: calc(var(--gutter) * -1);
  margin-left: calc(var(--gutter) * -1);
  padding-right: var(--gutter);
  padding-left: var(--gutter);
  background: var(--paper);
  color: var(--ink);
  border-top: 1px solid rgba(17, 21, 33, .14);
}

.voices-section__header h2 {
  color: var(--ink);
}

.voices-section__header h2 i {
  color: var(--coral);
}

.voices-section__header .section__lede {
  color: var(--ink-soft);
}

.voice-triptych {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  margin-top: clamp(46px, 6vw, 80px);
  border-top: 1px solid rgba(17, 21, 33, .22);
  border-bottom: 1px solid rgba(17, 21, 33, .22);
}

.voice-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 18px;
  padding: clamp(22px, 2.6vw, 36px) clamp(18px, 2vw, 28px);
  border-right: 1px solid rgba(17, 21, 33, .16);
  background: transparent;
  color: var(--ink-soft);
  text-align: left;
  cursor: pointer;
  transition: background .4s var(--ease), color .35s var(--ease);
}

.voice-tile:last-child {
  border-right: 0;
}

.voice-tile:hover,
.voice-tile:focus-visible {
  background: rgba(216, 255, 98, .08);
  color: var(--ink);
}

.voice-tile.is-active {
  background: var(--ink);
  color: var(--paper);
}

.voice-tile.is-active::before {
  position: absolute;
  top: -1px;
  right: 0;
  left: 0;
  height: 2px;
  background: var(--acid);
  content: '';
}

.voice-tile.is-active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  background: var(--acid);
  content: '';
}

.voice-tile__head {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 12px;
  align-items: baseline;
  row-gap: 4px;
}

.voice-tile__letter {
  grid-row: 1 / span 2;
  align-self: center;
  color: var(--coral);
  font-family: var(--mono);
  font-size: 12px;
}

.voice-tile.is-active .voice-tile__letter {
  color: var(--acid);
}

.voice-tile__name {
  font-family: var(--serif);
  font-size: clamp(20px, 2vw, 26px);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.02em;
  line-height: 1;
}

.voice-tile--bold .voice-tile__name {
  font-family: var(--sans);
  font-size: clamp(16px, 1.6vw, 20px);
  font-style: normal;
  font-weight: 800;
  letter-spacing: -.04em;
  text-transform: uppercase;
}

.voice-tile__descriptor {
  color: var(--ink-mist);
  font-family: var(--mono);
  font-size: 9px;
  font-style: normal;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.voice-tile.is-active .voice-tile__descriptor {
  color: var(--ink-mist);
}

.voice-tile__sample {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 4px 0;
  font-family: var(--serif);
  font-size: clamp(1.7rem, 2.6vw, 2.6rem);
  font-weight: 400;
  letter-spacing: -.05em;
  line-height: .88;
}

.voice-tile__sample span:nth-child(2) {
  margin-left: .2em;
  color: var(--ink);
}

.voice-tile__sample span:nth-child(3) {
  margin-left: .48em;
  color: var(--coral);
}

.voice-tile__sample--human {
  font-style: italic;
}

.voice-tile__sample--human span:nth-child(2) {
  color: var(--coral);
}

.voice-tile__sample--human span:nth-child(3) {
  color: var(--ink);
}

.voice-tile__sample--bold {
  font-family: var(--sans);
  font-size: clamp(1.6rem, 2.6vw, 2.5rem);
  font-style: normal;
  font-weight: 850;
  letter-spacing: -.07em;
  text-transform: uppercase;
}

.voice-tile__sample--bold span:nth-child(2),
.voice-tile__sample--bold span:nth-child(3) {
  color: var(--ink);
}

.voice-tile.is-active .voice-tile__sample span {
  color: var(--paper);
}

.voice-tile.is-active .voice-tile__sample--quiet span:nth-child(2) { color: var(--acid); }
.voice-tile.is-active .voice-tile__sample--quiet span:nth-child(3) { color: var(--coral); }
.voice-tile.is-active .voice-tile__sample--human span:nth-child(2) { color: var(--paper); }
.voice-tile.is-active .voice-tile__sample--human span:nth-child(3) { color: var(--coral); }
.voice-tile.is-active .voice-tile__sample--bold span:nth-child(2),
.voice-tile.is-active .voice-tile__sample--bold span:nth-child(3) { color: var(--acid); }

.voice-tile__foot {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 14px;
  align-items: end;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid rgba(17, 21, 33, .16);
}

.voice-tile.is-active .voice-tile__foot {
  border-top-color: rgba(242, 238, 229, .2);
}

.voice-tile__body {
  grid-column: 1;
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  line-height: 1.5;
}

.voice-tile.is-active .voice-tile__body {
  color: var(--mist);
}

.voice-tile__mark {
  grid-column: 2;
  align-self: end;
  color: var(--coral);
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1;
}

.voice-tile.is-active .voice-tile__mark {
  color: var(--acid);
}

.voice-tile__stamp {
  position: absolute;
  top: 12px;
  right: 12px;
  opacity: 0;
  transform: scale(.6) rotate(-12deg);
  transition: opacity .5s var(--ease) .1s, transform .6s var(--ease-spring) .1s;
  pointer-events: none;
}

.voice-tile.is-active .voice-tile__stamp,
.voice-tile:hover .voice-tile__stamp,
.voice-tile:focus-visible .voice-tile__stamp {
  opacity: .35;
  transform: scale(1) rotate(-4deg);
}

/* ────────────────────────────────────────────────────────────
   FOLIO LEDGER · press log & contents
   ──────────────────────────────────────────────────────────── */

.folio-ledger {
  padding: clamp(80px, 9vw, 130px) 0 clamp(40px, 5vw, 80px);
  border-top: 1px solid var(--line-soft);
}

.folio-ledger__head {
  max-width: 820px;
}

.folio-ledger__head h2 {
  max-width: 720px;
  margin: 22px 0 18px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5.2vw, 5.6rem);
  font-weight: 400;
  letter-spacing: -.068em;
  line-height: .92;
  text-wrap: balance;
}

.folio-ledger__head h2 i {
  color: var(--coral);
  font-style: italic;
}

.folio-ledger__list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  margin: clamp(46px, 6vw, 80px) 0 0;
  padding: 0;
  list-style: none;
  border-top: 1px solid var(--line);
  border-left: 1px solid var(--line);
}

.folio-ledger__item {
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.folio-ledger__item.is-closing {
  grid-column: 1 / -1;
  background: linear-gradient(90deg, rgba(216, 255, 98, .04), rgba(255, 118, 95, .03));
}

.folio-ledger__item.is-closing .folio-ledger__num {
  color: var(--coral);
}

.folio-ledger__item.is-closing .folio-ledger__title {
  font-family: var(--serif);
  font-size: clamp(22px, 2.2vw, 30px);
}

.folio-ledger__item.is-closing .folio-ledger__link::before {
  background: linear-gradient(180deg, var(--coral), var(--acid));
}

.folio-ledger__item.is-self {
  background:
    radial-gradient(circle at 0 0, rgba(216, 255, 98, .06), transparent 60%),
    radial-gradient(circle at 100% 100%, rgba(255, 118, 95, .04), transparent 60%);
}

.folio-ledger__item.is-self .folio-ledger__num {
  color: var(--acid);
}

.folio-ledger__here {
  display: inline-block;
  margin-left: 10px;
  color: var(--acid);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
  vertical-align: 2px;
  opacity: .65;
}

.folio-ledger__link {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(14px, 2.2vw, 28px);
  padding: clamp(22px, 2.6vw, 36px) clamp(20px, 2.8vw, 36px);
  color: var(--paper);
  transition: background .4s var(--ease), padding-left .4s var(--ease-out);
}

.folio-ledger__link::before {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: 0;
  background: linear-gradient(180deg, var(--acid), var(--coral));
  content: '';
  transition: width .5s var(--ease-out);
}

.folio-ledger__link:hover,
.folio-ledger__link:focus-visible {
  background: rgba(216, 255, 98, .05);
}

.folio-ledger__link:hover::before,
.folio-ledger__link:focus-visible::before {
  width: 3px;
}

.folio-ledger__num {
  font-family: var(--serif);
  font-size: clamp(30px, 3.6vw, 44px);
  font-style: italic;
  color: var(--coral);
  letter-spacing: -.04em;
  line-height: 1;
  transition: color .35s var(--ease), transform .5s var(--ease-spring);
}

.folio-ledger__link:hover .folio-ledger__num,
.folio-ledger__link:focus-visible .folio-ledger__num {
  color: var(--acid);
  transform: translateX(4px);
}

.folio-ledger__copy {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}

.folio-ledger__title {
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(20px, 2vw, 28px);
  font-style: italic;
  letter-spacing: -.025em;
  line-height: 1.1;
}

.folio-ledger__note {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.folio-ledger__arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--acid);
  opacity: .35;
  transition: opacity .3s var(--ease), transform .35s var(--ease-out), border-color .35s var(--ease);
}

.folio-ledger__arrow svg {
  width: 18px;
  height: 18px;
}

.folio-ledger__link:hover .folio-ledger__arrow,
.folio-ledger__link:focus-visible .folio-ledger__arrow {
  opacity: 1;
  transform: translateX(4px);
  border-color: var(--acid);
}

.folio-ledger__foot {
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: 60ch;
  margin: clamp(28px, 4vw, 44px) 0 0;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  line-height: 1.5;
}

.folio-ledger__foot span[aria-hidden] {
  color: var(--coral);
  font-style: normal;
  font-size: 18px;
}

@media (max-width: 880px) {
  .folio-ledger__list {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 540px) {
  .folio-ledger__link {
    padding: 22px 18px;
    gap: 14px;
  }

  .folio-ledger__num {
    font-size: 28px;
  }

  .folio-ledger__arrow {
    width: 32px;
    height: 32px;
  }
}

/* ────────────────────────────────────────────────────────────
   COLOPHON · imprint page
   ──────────────────────────────────────────────────────────── */

.colophon {
  position: relative;
  padding: clamp(60px, 8vw, 110px) 0 36px;
  margin-top: clamp(60px, 9vw, 120px);
  border-top: 1px solid var(--line-soft);
}

.colophon::before {
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translate(-50%, -50%);
  padding: 4px 14px;
  border: 1px solid var(--line);
  background: var(--night);
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
  content: 'colophon';
}

.colophon__plate {
  position: relative;
  display: grid;
  gap: clamp(20px, 3vw, 36px);
  padding: clamp(24px, 3.4vw, 44px) clamp(22px, 3.4vw, 48px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 92% 8%, rgba(255, 118, 95, .07), transparent 55%),
    radial-gradient(circle at 6% 96%, rgba(216, 255, 98, .04), transparent 50%),
    linear-gradient(180deg, rgba(28, 36, 52, .4), rgba(14, 20, 32, .55));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .05),
    0 30px 80px -40px rgba(0, 0, 0, .55);
}

.colophon__plate::before {
  position: absolute;
  inset: 7px;
  border: 1px dashed rgba(146, 186, 255, .08);
  pointer-events: none;
  content: '';
}

.colophon__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}

.colophon__identity {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.colophon__mark {
  display: inline-flex;
  color: var(--coral);
  transition: transform .5s var(--ease-spring);
}

.colophon__plate:hover .colophon__mark {
  transform: rotate(22deg);
}

.colophon__title {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.colophon__press {
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(22px, 2.2vw, 28px);
  font-style: italic;
  letter-spacing: -.02em;
  line-height: 1;
}

.colophon__title em {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
  font-style: normal;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.colophon__seal {
  position: relative;
  display: inline-flex;
  color: var(--coral);
  opacity: .9;
  transition: transform .55s var(--ease-spring);
}

.colophon__plate:hover .colophon__seal {
  transform: rotate(-6deg);
}

.colophon__seal-wax {
  position: absolute;
  top: 78%;
  left: -8px;
  width: 22px;
  height: 18px;
  pointer-events: none;
  color: var(--coral);
  opacity: 0;
  animation: colophonWaxDrop .55s var(--ease) .5s backwards;
}

.colophon__seal-wax-bead {
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 7px;
  height: 9px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  background: currentColor;
  transform: translate(-50%, 0) scale(.6);
  transform-origin: 50% 0;
  filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, .25));
}

.colophon__seal-wax-wisp {
  position: absolute;
  top: 0;
  left: 50%;
  width: 2px;
  height: 14px;
  background: linear-gradient(180deg, transparent, currentColor 60%);
  transform: translateX(-50%) scaleY(.4);
  transform-origin: 50% 0;
  opacity: .55;
}

@keyframes colophonWaxDrop {
  0% { opacity: 0; transform: translateY(-8px); }
  40% { opacity: 1; transform: translateY(0); }
  55% { transform: translateY(2px); }
  70% { transform: translateY(0); }
  100% { opacity: 1; transform: translateY(2px); }
}

.colophon__crease {
  position: absolute;
  left: 12px;
  right: 12px;
  top: 56px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--mist) 18%, var(--mist) 82%, transparent);
  opacity: .25;
  pointer-events: none;
}

.colophon__crease--v {
  top: auto;
  bottom: 12px;
  left: 50%;
  right: auto;
  width: 1px;
  height: auto;
  top: 60px;
  bottom: 60px;
  background: linear-gradient(to bottom, transparent, var(--mist) 18%, var(--mist) 82%, transparent);
  opacity: .12;
}

.colophon__flap {
  position: absolute;
  top: 0;
  left: 12px;
  right: 12px;
  height: 38px;
  pointer-events: none;
  color: var(--paper);
  opacity: .7;
}

.colophon__flap svg {
  width: 100%;
  height: 100%;
}

@media (prefers-reduced-motion: reduce) {
  .colophon__seal-wax,
  .colophon__seal-wax-bead,
  .colophon__seal-wax-wisp {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

.colophon__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(14px, 2vw, 28px) clamp(20px, 3vw, 36px);
}

.colophon__row {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.colophon__label {
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.colophon__value {
  color: var(--paper);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
}

.colophon__swatches {
  display: inline-flex;
  gap: 6px;
  align-items: center;
}

.colophon__swatch {
  display: block;
  width: 18px;
  height: 18px;
  border: 1px solid rgba(17, 21, 33, .5);
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(0, 0, 0, .25);
}

.colophon__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.colophon__line {
  margin: 0;
  max-width: 50ch;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(15px, 1.5vw, 19px);
  font-style: italic;
  letter-spacing: -.02em;
  line-height: 1.4;
}

.colophon__line i {
  color: var(--muted);
  font-style: italic;
}

.colophon__back {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 9px 14px;
  border: 1px solid var(--line);
  color: var(--acid);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
  transition: color .25s var(--ease), border-color .25s var(--ease), background .25s var(--ease);
}

.colophon__back .arrow-icon {
  width: 16px;
  height: 16px;
  transform: rotate(-90deg);
  transition: transform .35s var(--ease-out);
}

.colophon__back:hover,
.colophon__back:focus-visible {
  color: var(--paper);
  border-color: var(--acid);
  background: rgba(216, 255, 98, .08);
}

.colophon__back:hover .arrow-icon,
.colophon__back:focus-visible .arrow-icon {
  transform: rotate(-90deg) translateX(4px);
}

.colophon__signature {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding-top: 24px;
  border-top: 1px dashed var(--line);
}

.colophon__signature-mark-mono {
  display: inline-flex;
  width: 36px;
  height: 40px;
  color: var(--coral);
  opacity: .7;
  transform: translateY(2px);
  transition: transform .55s var(--ease-spring), color .4s var(--ease), opacity .4s var(--ease);
  animation: colophonMonoIn 1s var(--ease-spring) .15s backwards;
}

.colophon__signature-mark-mono svg {
  display: block;
  width: 100%;
  height: 100%;
}

.colophon__signature:hover .colophon__signature-mark-mono {
  transform: translateY(0) rotate(-6deg);
  color: var(--acid);
  opacity: .95;
}

@keyframes colophonMonoIn {
  0% { opacity: 0; transform: translateY(8px) scale(.85); }
  60% { opacity: .8; transform: translateY(0) scale(1.04); }
  100% { opacity: .7; transform: translateY(2px) scale(1); }
}

.colophon__signature-mark {
  width: clamp(240px, 34vw, 360px);
  height: auto;
  color: var(--coral);
  opacity: .65;
  animation: colophonTrace 1.4s var(--ease-out) .2s backwards;
}

.colophon__signature-wave {
  stroke-dasharray: 380 380;
  stroke-dashoffset: 380;
  animation: signatureDraw 1.7s var(--ease-out) .4s forwards;
}

.colophon__signature-flourish {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: translateX(-6px);
  animation: signatureFlourish 1.2s var(--ease-out) 1.6s forwards;
}

.colophon__signature-tail {
  opacity: 0;
  animation: signatureTail .9s var(--ease-out) .25s forwards;
}

@keyframes signatureDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes signatureFlourish {
  to { opacity: 1; transform: translateX(0); }
}

@keyframes signatureTail {
  to { opacity: 1; }
}

@keyframes colophonTrace {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: .65;
    transform: translateY(0);
  }
}

.colophon__signature:hover .colophon__signature-mark {
  opacity: .9;
  color: var(--acid);
}

.colophon__signature-tag {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.colophon__signature-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  max-width: 60ch;
  margin: clamp(28px, 4vw, 48px) auto 0;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  text-align: center;
  line-height: 1.55;
}

.colophon__signature-note span[aria-hidden] {
  color: var(--coral);
  font-style: normal;
  font-size: 16px;
}

/* ────────────────────────────────────────────────────────────
   LETTER TO THE READER · folded slip · between ii & iii
   ──────────────────────────────────────────────────────────── */

.letter {
  position: relative;
  padding: clamp(80px, 9vw, 130px) 0 clamp(100px, 11vw, 160px);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  background:
    radial-gradient(circle at 50% 12%, rgba(243, 236, 214, .04), transparent 58%),
    radial-gradient(circle at 50% 88%, rgba(255, 118, 95, .03), transparent 60%);
  isolation: isolate;
}

.letter__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  opacity: 0;
}

.letter__plate {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  width: fit-content;
  margin: 0 auto clamp(20px, 2.4vw, 34px);
  padding: 6px 14px;
  border: 1px solid var(--line);
  background: rgba(14, 15, 21, .6);
  backdrop-filter: blur(6px);
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
  white-space: nowrap;
}

.letter__plate-mark {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 8px rgba(240, 110, 91, .55);
}

.letter__plate-trail {
  display: inline-flex;
  align-items: center;
  width: clamp(36px, 6vw, 72px);
  opacity: .55;
}

.letter__plate-trail svg {
  display: block;
  width: 100%;
  height: auto;
}

.letter__plate-trail-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: letterPlateTrail 1.4s var(--ease-out) .3s forwards;
}

.letter.is-revealed .letter__plate-trail-stroke {
  animation-delay: .55s;
}

@keyframes letterPlateTrail {
  to { stroke-dashoffset: 0; }
}

.letter__stage {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(150px, 16vw, 200px);
  gap: clamp(20px, 2.4vw, 36px);
  max-width: 980px;
  margin: 0 auto;
  padding: 0 var(--gutter);
  align-items: start;
}

.letter__slip {
  position: relative;
  padding: clamp(40px, 5vw, 64px) clamp(28px, 4vw, 56px) clamp(36px, 4vw, 52px);
  background: #f3ecd6;
  color: var(--ink);
  box-shadow:
    14px 22px 0 -4px rgba(5, 8, 14, .42),
    0 38px 80px rgba(0, 0, 0, .35),
    inset 0 0 0 1px rgba(17, 21, 33, .06),
    inset 0 0 64px rgba(17, 21, 33, .06);
  transform: rotate(-.6deg);
  transform-origin: 50% 60%;
  opacity: 0;
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-spring);
}

.letter.is-revealed .letter__slip {
  opacity: 1;
  transform: rotate(-.6deg) translateY(0);
  animation: letterSlipIn 1.05s var(--ease-out) backwards;
}

@keyframes letterSlipIn {
  from {
    opacity: 0;
    transform: rotate(-1.4deg) translateY(-22px);
  }
  to {
    opacity: 1;
    transform: rotate(-.6deg) translateY(0);
  }
}

.letter__slip:hover {
  transform: rotate(-.3deg);
}

.letter__slip-paper {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
  border-radius: 1px;
}

.letter__slip-paper svg {
  display: block;
  width: 100%;
  height: 100%;
}

.letter__glue {
  position: absolute;
  left: 0;
  right: 0;
  height: 7px;
  pointer-events: none;
  z-index: 4;
}

.letter__glue--top {
  top: 0;
  background:
    linear-gradient(180deg, rgba(17, 21, 33, .14), rgba(17, 21, 33, 0) 100%),
    repeating-linear-gradient(90deg, rgba(17, 21, 33, .08) 0 1px, transparent 1px 9px);
}

.letter__glue--bottom {
  bottom: 0;
  background:
    linear-gradient(0deg, rgba(17, 21, 33, .14), rgba(17, 21, 33, 0) 100%),
    repeating-linear-gradient(90deg, rgba(17, 21, 33, .08) 0 1px, transparent 1px 9px);
}

.letter__tipped {
  position: absolute;
  top: -10px;
  right: clamp(20px, 4vw, 44px);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  background: var(--night);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
  box-shadow: 2px 4px 0 rgba(0, 0, 0, .35);
  transform: rotate(2deg);
  z-index: 5;
}

.letter__tipped-mark {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 6px rgba(240, 110, 91, .5);
}

.letter__corner {
  position: absolute;
  width: 14px;
  height: 14px;
  pointer-events: none;
  z-index: 3;
}

.letter__corner::before,
.letter__corner::after {
  content: '';
  position: absolute;
  background: rgba(17, 21, 33, .42);
}

.letter__corner--tl { top: 0; left: 0; }
.letter__corner--tl::before { top: 0; left: 0; width: 100%; height: 1px; }
.letter__corner--tl::after { top: 0; left: 0; width: 1px; height: 100%; }

.letter__corner--tr { top: 0; right: 0; }
.letter__corner--tr::before { top: 0; left: 0; width: 100%; height: 1px; }
.letter__corner--tr::after { top: 0; right: 0; width: 1px; height: 100%; }

.letter__corner--bl { bottom: 0; left: 0; }
.letter__corner--bl::before { bottom: 0; left: 0; width: 100%; height: 1px; }
.letter__corner--bl::after { bottom: 0; left: 0; width: 1px; height: 100%; }

.letter__corner--br { bottom: 0; right: 0; }
.letter__corner--br::before { bottom: 0; left: 0; width: 100%; height: 1px; }
.letter__corner--br::after { bottom: 0; right: 0; width: 1px; height: 100%; }

.letter__fold {
  position: absolute;
  left: 0;
  right: 0;
  pointer-events: none;
  z-index: 2;
  opacity: .85;
}

.letter__fold--top {
  top: 8px;
}

.letter__fold--top svg {
  display: block;
  width: 100%;
  height: auto;
}

.letter__rule {
  position: absolute;
  left: clamp(20px, 4vw, 32px);
  right: clamp(20px, 4vw, 32px);
  pointer-events: none;
  z-index: 1;
}

.letter__rule--head { top: 38px; }
.letter__rule--foot { bottom: 38px; }

.letter__rule svg {
  display: block;
  width: 100%;
  height: auto;
}

.letter__stamp {
  position: absolute;
  top: clamp(22px, 3.4vw, 38px);
  right: clamp(28px, 3.6vw, 44px);
  width: clamp(64px, 7vw, 96px);
  pointer-events: none;
  z-index: 2;
  transform: rotate(-3deg);
  color: var(--coral);
  opacity: .9;
  filter: drop-shadow(1px 2px 0 rgba(17, 21, 33, .15));
}

.letter__stamp-svg {
  display: block;
  width: 100%;
  height: auto;
}

.letter__cancellation {
  position: absolute;
  top: clamp(8px, 1.4vw, 18px);
  right: clamp(8px, 1.4vw, 18px);
  width: clamp(110px, 12vw, 168px);
  pointer-events: none;
  z-index: 3;
  transform: rotate(8deg);
  color: var(--ink);
  opacity: .82;
  mix-blend-mode: multiply;
}

.letter__cancellation-svg {
  display: block;
  width: 100%;
  height: auto;
}

.letter__seal {
  position: absolute;
  bottom: clamp(40px, 5vw, 60px);
  left: clamp(-32px, -3vw, -16px);
  width: clamp(76px, 9vw, 116px);
  pointer-events: none;
  z-index: 4;
  transform: rotate(-12deg);
  filter: drop-shadow(3px 4px 0 rgba(5, 8, 14, .35));
  animation: letterSealPress 1.1s var(--ease-spring) .4s backwards;
}

@keyframes letterSealPress {
  0% { opacity: 0; transform: scale(1.5) rotate(-32deg); }
  60% { opacity: 1; transform: scale(.94) rotate(-6deg); }
  100% { opacity: 1; transform: scale(1) rotate(-12deg); }
}

.letter__seal-svg {
  display: block;
  width: 100%;
  height: auto;
}

.letter__seal-wax {
  position: absolute;
  bottom: -8px;
  right: -10px;
  width: 26px;
  height: 16px;
  pointer-events: none;
}

.letter__seal-wax-bead {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, rgba(255, 148, 131, .9), rgba(179, 74, 58, 1) 60%, rgba(17, 21, 33, .9));
  box-shadow: 0 1px 2px rgba(0, 0, 0, .35);
}

.letter__seal-wax-wisp {
  position: absolute;
  bottom: 4px;
  right: 12px;
  width: 18px;
  height: 1.5px;
  background: linear-gradient(90deg, rgba(179, 74, 58, 0), rgba(179, 74, 58, .65));
  transform: rotate(-14deg);
  transform-origin: right center;
}

.letter__thread {
  position: absolute;
  pointer-events: none;
  z-index: 1;
}

.letter__thread--a {
  inset: 0;
  opacity: .35;
}

.letter__thread--a svg {
  display: block;
  width: 100%;
  height: 100%;
}

.letter__thread-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
}

.letter.is-revealed .letter__thread-stroke {
  animation: letterThreadDraw 1.8s var(--ease-out) .5s forwards;
}

@keyframes letterThreadDraw {
  to { stroke-dashoffset: 0; }
}

.letter__body {
  position: relative;
  z-index: 2;
}

.letter__address {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
  padding-bottom: clamp(18px, 2.4vw, 28px);
  margin-bottom: clamp(22px, 3vw, 32px);
  border-bottom: 1px solid rgba(17, 21, 33, .12);
}

.letter__address-row {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr);
  gap: 14px;
  align-items: baseline;
}

.letter__address-key {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: rgba(17, 21, 33, .55);
  align-self: baseline;
}

.letter__address-value {
  display: flex;
  flex-direction: column;
  gap: 1px;
  font-family: var(--serif);
}

.letter__address-value em {
  font-style: italic;
  font-size: clamp(1.05rem, 1.8vw, 1.4rem);
  letter-spacing: -.01em;
  color: var(--ink);
  line-height: 1.05;
}

.letter__address-row--to .letter__address-value em {
  color: var(--coral);
}

.letter__address-sub {
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: rgba(17, 21, 33, .55);
}

.letter__address-rule {
  width: 100%;
  height: 6px;
  display: flex;
  align-items: center;
}

.letter__address-rule svg {
  display: block;
  width: 100%;
  height: auto;
}

.letter__head {
  position: relative;
  margin-bottom: clamp(20px, 2.8vw, 32px);
}

.letter__head-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: rgba(17, 21, 33, .55);
  margin-bottom: 10px;
}

.letter__head-eyebrow-tick {
  width: 6px;
  height: 1px;
  background: rgba(17, 21, 33, .55);
}

.letter__head h2 {
  max-width: 520px;
  margin: 0 0 14px;
  color: var(--ink);
  font-family: var(--serif);
  font-size: clamp(1.85rem, 3.6vw, 2.9rem);
  font-weight: 400;
  letter-spacing: -.052em;
  line-height: 1;
  text-wrap: balance;
}

.letter__head h2 i {
  color: var(--coral);
  font-style: italic;
}

.letter__head-byline {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 10px;
  margin: 0;
  padding: 4px 0 0;
  border-top: 1px solid rgba(17, 21, 33, .16);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.letter__head-byline-key {
  color: rgba(17, 21, 33, .55);
  padding-top: 8px;
}

.letter__head-byline-voice {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  padding-top: 8px;
  font-style: normal;
}

.letter__head-byline-letter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: Georgia, serif;
  font-size: 11px;
  font-style: italic;
  letter-spacing: 0;
}

.letter__head-byline-voice--quiet { color: var(--blue); }
.letter__head-byline-voice--human { color: var(--coral); }
.letter__head-byline-voice--bold { color: var(--acid); }

.letter__head-byline-voice em {
  color: var(--ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11.5px;
  letter-spacing: .01em;
  text-transform: lowercase;
}

.letter__head-byline-face {
  padding-top: 8px;
  color: rgba(17, 21, 33, .55);
}

.letter__copy {
  position: relative;
  max-width: 540px;
  font-family: var(--serif);
  font-size: clamp(15px, 1.4vw, 17.5px);
  line-height: 1.66;
  color: var(--ink-soft);
}

.letter__copy p {
  margin: 0 0 1em;
}

.letter__copy em {
  color: var(--ink);
  font-style: italic;
}

.letter__salute {
  color: var(--ink);
  font-style: italic;
  font-size: 1.05em;
  margin-bottom: 1.05em;
}

.letter__sign {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  margin-top: clamp(22px, 2.6vw, 36px);
  font-family: var(--serif);
}

.letter__sign-mark {
  color: var(--coral);
  font-style: italic;
  font-size: 1.4em;
  line-height: .6;
  padding-top: 4px;
}

.letter__sign-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.letter__sign-flourish {
  display: block;
  width: clamp(160px, 18vw, 220px);
  height: 30px;
  color: var(--ink);
}

.letter__sign-flourish-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
}

.letter.is-revealed .letter__sign-flourish-stroke {
  animation: letterSignDraw 1.4s var(--ease-out) .8s forwards;
}

@keyframes letterSignDraw {
  to { stroke-dashoffset: 0; }
}

.letter__sign-flourish-bead {
  opacity: 0;
  transform-origin: 216px 18px;
  transform-box: fill-box;
}

.letter.is-revealed .letter__sign-flourish-bead {
  animation: letterSignBead .4s var(--ease-spring) 2.05s forwards;
}

@keyframes letterSignBead {
  from { opacity: 0; transform: scale(0); }
  to { opacity: 1; transform: scale(1); }
}

.letter__sign-name {
  font-style: italic;
  color: var(--ink);
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  letter-spacing: -.005em;
}

.letter__sign-meta {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: baseline;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: rgba(17, 21, 33, .55);
}

.letter__return {
  position: relative;
  margin-top: clamp(28px, 3.2vw, 42px);
  padding-top: clamp(18px, 2.2vw, 28px);
  border-top: 1px dashed rgba(17, 21, 33, .28);
}

.letter__return-rule {
  position: absolute;
  top: -1px;
  left: 0;
  width: 56px;
  height: 1px;
  background: var(--ink);
}

.letter__return-cta {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 14px 18px;
  border: 1px solid rgba(17, 21, 33, .22);
  background: rgba(255, 255, 255, .22);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .16em;
  text-transform: uppercase;
  transition: color .3s var(--ease), border-color .3s var(--ease), background .3s var(--ease), transform .35s var(--ease-spring);
  isolation: isolate;
}

.letter__return-cta::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(135deg, rgba(17, 21, 33, .04) 0 1px, transparent 1px 7px);
  pointer-events: none;
  z-index: -1;
}

.letter__return-cta:hover,
.letter__return-cta:focus-visible {
  border-color: var(--coral);
  color: var(--coral);
  background: rgba(255, 118, 95, .08);
  transform: translateY(-1px);
}

.letter__return-cta-line {
  display: flex;
  flex-direction: column;
  gap: 2px;
  align-items: flex-start;
}

.letter__return-cta-eyebrow {
  font-size: 9px;
  letter-spacing: .26em;
  color: rgba(17, 21, 33, .55);
}

.letter__return-cta-label {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--ink);
}

.letter__return-cta:hover .letter__return-cta-label,
.letter__return-cta:focus-visible .letter__return-cta-label {
  color: var(--coral);
}

.letter__return-cta-arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: 1px solid currentColor;
  border-radius: 50%;
  transition: transform .35s var(--ease-spring), background .25s var(--ease);
}

.letter__return-cta:hover .letter__return-cta-arrow,
.letter__return-cta:focus-visible .letter__return-cta-arrow {
  transform: translateX(4px);
  background: rgba(255, 118, 95, .12);
}

.letter__return-cta-arrow svg {
  width: 14px;
  height: 14px;
}

.letter__return-cta-tag {
  position: absolute;
  bottom: -10px;
  right: 16px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.letter__return-cta-tag-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--coral);
}

.letter__return-folio {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: clamp(14px, 2vw, 18px);
  padding-left: 4px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: rgba(17, 21, 33, .55);
}

.letter__return-folio-mark {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--coral);
}

.letter__dog-ear {
  position: absolute;
  right: 0;
  bottom: 0;
  width: clamp(36px, 6vw, 60px);
  height: clamp(36px, 6vw, 60px);
  pointer-events: none;
  z-index: 5;
  transition: transform .55s var(--ease-spring);
}

.letter__slip:hover .letter__dog-ear {
  transform: rotate(-3deg) scale(1.04);
}

.letter__dog-ear-svg {
  display: block;
  width: 100%;
  height: 100%;
}

.letter__hand-note {
  position: absolute;
  bottom: clamp(20px, 4vw, 36px);
  right: clamp(72px, 11vw, 132px);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 9px;
  background: rgba(255, 255, 255, .55);
  border: 1px dashed rgba(17, 21, 33, .32);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: -.005em;
  color: var(--ink);
  transform: rotate(-4deg);
  z-index: 3;
}

.letter__hand-note em {
  font-style: italic;
}

.letter__hand-note-tick {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--coral);
}

.letter__sidecar {
  position: sticky;
  top: clamp(80px, 9vw, 120px);
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px 14px;
  border: 1px solid var(--line);
  background: rgba(14, 15, 21, .55);
  backdrop-filter: blur(6px);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
  z-index: 1;
}

.letter__sidecar-mark {
  position: absolute;
  top: -1px;
  left: -1px;
  width: 8px;
  height: 8px;
  border-left: 1px solid var(--letter-tone);
  border-top: 1px solid var(--letter-tone);
}

.letter__sidecar-tag {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--letter-tone);
  font-size: 9.5px;
}

.letter__sidecar-tag::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--letter-tone);
  opacity: .55;
}

.letter__sidecar-stops {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.letter__sidecar-stop {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  padding: 6px 4px;
  border-bottom: 1px dashed rgba(243, 236, 214, .12);
  color: rgba(243, 236, 214, .7);
}

.letter__sidecar-stop.is-current {
  color: var(--paper);
  background: rgba(255, 118, 95, .12);
  border-left: 2px solid var(--coral);
  padding-left: 6px;
}

.letter__sidecar-stop-num {
  font-family: Georgia, serif;
  font-style: italic;
  font-size: 13px;
  text-transform: lowercase;
  letter-spacing: 0;
  color: var(--letter-tone);
}

.letter__sidecar-stop-name {
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: -.005em;
  text-transform: lowercase;
}

.letter__sidecar-stop-rule {
  display: flex;
  justify-content: center;
  padding: 2px 0;
  color: rgba(243, 236, 214, .3);
}

.letter__sidecar-stop-rule svg {
  width: 28px;
  height: 4px;
}

.letter__sidecar-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--line);
  color: rgba(243, 236, 214, .55);
  font-size: 8.5px;
  letter-spacing: .22em;
}

.letter__sidecar-foot-mark {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--letter-tone);
}

.press-folio--slip .press-folio__label {
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.press-folio--slip .press-folio__label::before {
  content: 'slip · ';
  color: var(--acid);
  margin-right: 4px;
}

@media (max-width: 1180px) {
  .stage-markers__hint {
    display: none;
  }
}

@media (max-width: 1080px) {
  .site-header__row {
    grid-template-columns: minmax(180px, 1fr) auto;
  }

  .site-header__note {
    display: none;
  }

  .hero__sheet {
    padding: clamp(46px, 6vw, 72px) clamp(28px, 4vw, 48px) clamp(40px, 5vw, 56px);
  }

  .marginalia-section__rail {
    gap: clamp(16px, 2.4vw, 24px);
  }

  .voice-tile__sample {
    font-size: clamp(1.5rem, 2.4vw, 2.1rem);
  }

  .colophon__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .letter__stage {
    grid-template-columns: minmax(0, 1fr);
