  }

  .letter__sidecar {
    position: relative;
    top: auto;
  }

  .letter__slip {
    transform: rotate(-.3deg);
    padding: clamp(40px, 6vw, 60px) clamp(24px, 5vw, 40px) clamp(28px, 5vw, 40px);
  }

  .letter.is-revealed .letter__slip {
    animation: letterSlipInTablet 1.05s var(--ease-out) backwards;
  }

  @keyframes letterSlipInTablet {
    from {
      opacity: 0;
      transform: rotate(-1deg) translateY(-18px);
    }
    to {
      opacity: 1;
      transform: rotate(-.3deg) translateY(0);
    }
  }

  .letter__seal {
    width: clamp(72px, 11vw, 100px);
  }
}

