  .letter__head h2 {
    font-size: clamp(1.95rem, 8.5vw, 2.7rem);
  }

  .letter__body {
    font-size: 16px;
  }

  .letter__foot {
    flex-direction: column;
    align-items: flex-start;
  }

  @keyframes letterTip {
    from {
      opacity: 0;
      transform: translateY(-12px) rotate(0);
    }
    to {
      opacity: 1;
      transform: translateY(0) rotate(0);
    }
  }
