  }

  .answer-reveal__copy h2 {
    font-size: clamp(2.2rem, 9.8vw, 3.6rem);
  }

  .answer-reveal__columns {
    grid-template-columns: 1fr;
    gap: 18px;
    font-size: 16px;
  }

  .answer-reveal__pull {
    gap: 12px;
    font-size: clamp(14px, 4.4vw, 17px);
    letter-spacing: -.008em;
  }

  .answer-reveal__pull-rule {
    flex: 0 0 28px;
  }

  .answer-reveal__colophon {
    gap: 6px;
    font-size: 8px;
  }

  .answer-reveal__close {
    font-size: 9px;
    padding: 8px 12px;
  }

  .section {
    padding: 86px 0;
  }

  .section__header h2 {
    font-size: clamp(2.45rem, 11.5vw, 3.9rem);
  }

  .marginalia-section__rail {
    margin-top: clamp(24px, 4vw, 36px);
  }

  .voices-section {
    margin-right: -18px;
    margin-left: -18px;
    padding-right: 18px;
    padding-left: 18px;
  }

  .voice-tile {
    padding: 18px 14px;
  }

  .voice-tile__sample {
    font-size: clamp(1.7rem, 7vw, 2.2rem);
  }

  .voice-tile__sample--bold {
    font-size: clamp(1.6rem, 6.8vw, 2.1rem);
  }

  .colophon {
    padding-top: 44px;
    margin-top: 44px;
  }

  .colophon__plate {
    padding: 18px;
  }

  .colophon__head {
    gap: 12px;
  }

  .colophon__line {
    font-size: 16px;
  }

  .colophon__colophon,
  .colophon__signature-note {
    font-size: 11px;
  }

  .pressings__tabs {
    gap: 10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .001ms !important;
  }

  .title__line,
  .specimen,
  .slip,
  .slip__pin,
  .slip__seal-wrap,
  .voice-tile,
  .compose-floor__margin-card,
  .compose-floor__piece,
  .header-ruler__line span,
  .hero__dropcap,
  .press-signature,
  .answer-reveal__stamp,
  .answer-reveal__seal,
  .answer-reveal__trail,
  .answer-reveal__tipped,
  .answer-reveal__leaf,
  .title-token__circle,
  .title-token__circle-stroke,
  .title-token__circle-tail,
  .title-token__circle-dot,
  .specimen__pin,
  .specimen__seal,
  .specimen__press,
  .type-case__piece,
  .colophon__mark,
  .colophon__seal,
  .hero__sheet,
  .pressings__guide,
  .letter__slip,
  .letter__seal,
  .letter__dog-ear,
  .letter__stamp,
  .letter__cancellation,
  .letter__sidecar {
    transform: none !important;
    animation: none !important;
    opacity: 1 !important;
  }

  .letter__plate-trail-stroke,
  .letter__sign-flourish-stroke,
  .letter__sign-flourish-bead {
    stroke-dashoffset: 0 !important;
    opacity: 1 !important;
    transform: none !important;
  }

  .specimen__trace-bar,
  .type-case__dot,
  .pressings__guide {
    opacity: 0 !important;
  }
}

/* ────────────────────────────────────────────────────────────
   TITLE TOKEN · hand-traced underline
   ──────────────────────────────────────────────────────────── */

.title-token__underline {
  position: absolute;
  right: -2%;
  bottom: -.18em;
  left: -2%;
  width: 104%;
  height: .42em;
  color: currentColor;
  pointer-events: none;
  opacity: 0;
  transform: translateY(.12em);
  transition: opacity .5s var(--ease), transform .7s var(--ease-out);
}

.title-token__underline-stroke {
  stroke-dashoffset: 100;
}

.title-token.is-selected .title-token__underline,
.title-token:hover .title-token__underline,
.title-token:focus-visible .title-token__underline {
  opacity: .85;
  transform: translateY(0);
}

.title-token.is-selected .title-token__underline-stroke {
  animation: underlineDraw 1.1s var(--ease-out) .1s forwards;
}

.title-token__spark {
  position: absolute;
  top: -.22em;
  right: -.1em;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 4px rgba(255, 255, 255, .04), 0 0 16px currentColor;
  opacity: 0;
  transform: scale(.3);
  transition: opacity .45s var(--ease), transform .65s var(--ease-spring);
}

.title-token.is-selected .title-token__spark,
.title-token:hover .title-token__spark,
.title-token:focus-visible .title-token__spark {
  opacity: 1;
  transform: scale(1);
}

@keyframes underlineDraw {
  to { stroke-dashoffset: 0; }
}

/* ────────────────────────────────────────────────────────────
   TYPE LADDER · three pressings beneath the title
   ──────────────────────────────────────────────────────────── */

.type-ladder {
  position: relative;
  display: grid;
  gap: clamp(16px, 2vw, 22px);
  margin: clamp(40px, 5vw, 64px) 0 clamp(28px, 3.6vw, 44px);
  padding: clamp(22px, 2.8vw, 32px) clamp(20px, 2.6vw, 32px) clamp(20px, 2.4vw, 28px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 92% 6%, rgba(216, 255, 98, .05), transparent 55%),
    radial-gradient(circle at 6% 96%, rgba(255, 118, 95, .04), transparent 55%),
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(14, 20, 32, .58));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 18px 50px -28px rgba(0, 0, 0, .55);
}

.type-ladder::before {
  position: absolute;
  inset: 7px;
  border: 1px dashed rgba(146, 186, 255, .07);
  pointer-events: none;
  content: '';
}

.type-ladder__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding-bottom: clamp(10px, 1.2vw, 14px);
  border-bottom: 1px solid var(--line-soft);
  flex-wrap: wrap;
}

.type-ladder__folio {
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
  white-space: nowrap;
}

.type-ladder__rows {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.type-ladder__cell {
  position: relative;
}

.type-ladder__now {
  position: absolute;
  top: -1px;
  right: clamp(8px, 1vw, 14px);
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px 4px 7px;
  border: 1px solid var(--acid);
  background: var(--night);
  color: var(--acid);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
  animation: traceFade .45s var(--ease-out) backwards;
}

.type-ladder__now-tick {
  display: block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 0 3px rgba(216, 255, 98, .15);
  animation: composePulse 2.4s var(--ease) infinite;
}

.type-ladder__cell--human .type-ladder__now { border-color: var(--coral); color: var(--coral); }
.type-ladder__cell--human .type-ladder__now-tick { background: var(--coral); box-shadow: 0 0 0 3px rgba(255, 118, 95, .15); }
.type-ladder__cell--bold .type-ladder__now { border-color: var(--acid); color: var(--acid); }
.type-ladder__cell--bold .type-ladder__now-tick { background: var(--acid); box-shadow: 0 0 0 3px rgba(216, 255, 98, .15); }

.type-ladder__cell:not(:last-child)::after {
  position: absolute;
  top: 12px;
  bottom: 12px;
  right: 0;
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 14%, var(--line) 86%, transparent);
  content: '';
  pointer-events: none;
}

.type-ladder__row {
  position: relative;
  display: grid;
  grid-template-rows: auto auto auto auto;
  align-items: start;
  width: 100%;
  padding: clamp(14px, 1.8vw, 22px) clamp(14px, 1.8vw, 22px) clamp(12px, 1.6vw, 18px);
  background: transparent;
  color: var(--muted);
  text-align: left;
  cursor: pointer;
  transition: background .4s var(--ease), color .35s var(--ease);
}

.type-ladder__row:hover,
.type-ladder__row:focus-visible {
  background: rgba(216, 255, 98, .04);
  color: var(--paper);
}

.type-ladder__cell.is-active .type-ladder__row {
  background:
    radial-gradient(circle at 50% 0%, rgba(216, 255, 98, .08), transparent 60%),
    linear-gradient(180deg, rgba(216, 255, 98, .04), rgba(255, 118, 95, .02));
  color: var(--paper);
}

.type-ladder__cell.is-active .type-ladder__row::before {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--acid);
  content: '';
  animation: ladderEdgeIn .45s var(--ease-out);
}

.type-ladder__cell.is-active .type-ladder__row::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 1px;
  background: var(--acid);
  content: '';
  opacity: .45;
}

@keyframes ladderEdgeIn {
  from { transform: scaleX(.3); transform-origin: left center; opacity: 0; }
  to { transform: scaleX(1); transform-origin: left center; opacity: 1; }
}

.type-ladder__letter {
  display: block;
  margin-bottom: clamp(10px, 1.2vw, 14px);
  color: var(--coral);
  font-family: var(--serif);
  font-style: italic;
  font-size: 18px;
  letter-spacing: -.02em;
  line-height: 1;
  transition: color .35s var(--ease), transform .5s var(--ease-spring);
}

.type-ladder__cell--quiet .type-ladder__letter { color: var(--blue); }
.type-ladder__cell--human .type-ladder__letter { color: var(--coral); }
.type-ladder__cell--bold .type-ladder__letter { color: var(--acid); }

.type-ladder__cell.is-active .type-ladder__letter {
  transform: translateX(2px);
}

.type-ladder__specimen {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: clamp(12px, 1.4vw, 16px);
  font-family: var(--serif);
  font-size: clamp(16px, 1.6vw, 21px);
  font-style: italic;
  letter-spacing: -.045em;
  line-height: 1.04;
  color: var(--paper);
  transition: transform .5s var(--ease-spring);
}

.type-ladder__specimen span:nth-child(2) {
  color: var(--acid);
}

.type-ladder__specimen span:nth-child(3) {
  color: var(--coral);
}

.type-ladder__specimen--human {
  font-style: italic;
}

.type-ladder__specimen--human span:nth-child(2) {
  color: var(--coral);
}

.type-ladder__specimen--human span:nth-child(3) {
  color: var(--paper);
}

.type-ladder__specimen--bold {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 850;
  font-size: clamp(13px, 1.4vw, 18px);
  text-transform: uppercase;
  letter-spacing: -.06em;
}

.type-ladder__specimen--bold span:nth-child(2),
.type-ladder__specimen--bold span:nth-child(3) {
  color: var(--paper);
}

.type-ladder__specimen--bold span:nth-child(3) {
  color: var(--acid);
}

.type-ladder__cell.is-active .type-ladder__specimen {
  transform: translateX(2px);
}

.type-ladder__meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: clamp(10px, 1.2vw, 14px);
}

.type-ladder__face {
  color: var(--paper);
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  letter-spacing: -.01em;
  text-transform: none;
}

.type-ladder__ink {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.type-ladder__swatch {
  display: block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, .35);
  box-shadow: 0 0 0 2px rgba(0, 0, 0, .2);
  flex: 0 0 auto;
}

.type-ladder__set {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  padding-top: 10px;
  border-top: 1px dashed var(--line-soft);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.type-ladder__cell.is-active .type-ladder__set {
  color: var(--acid);
}

.type-ladder__set-dot {
  display: block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1px solid currentColor;
  background: transparent;
  transition: background .35s var(--ease), transform .35s var(--ease-spring);
}

.type-ladder__cell.is-active .type-ladder__set-dot {
  background: currentColor;
  transform: scale(1.15);
}

@media (max-width: 880px) {
  .type-ladder__rows {
    grid-template-columns: 1fr;
  }

  .type-ladder__cell:not(:last-child)::after {
    top: auto;
    right: 12px;
    bottom: 0;
    left: 12px;
    width: auto;
    height: 1px;
    background: linear-gradient(to right, transparent, var(--line) 8%, var(--line) 92%, transparent);
  }

  .type-ladder__row {
    padding: 16px 16px 14px;
  }

  .type-ladder__specimen {
    font-size: 17px;
  }

  .type-ladder__specimen--bold {
    font-size: 15px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .type-ladder__cell.is-active .type-ladder__row::before {
    animation: none !important;
  }
  .type-ladder__specimen,
  .type-ladder__letter {
    transform: none !important;
  }
}

/* ────────────────────────────────────────────────────────────
   MARKED PROOF · second reading of the question
   ──────────────────────────────────────────────────────────── */

.marked-proof {
  position: relative;
  padding: clamp(98px, 13vw, 180px) 0 clamp(80px, 9vw, 130px);
  border-top: 1px solid var(--line-soft);
}

.marked-proof__sheet {
  position: relative;
  display: grid;
  gap: clamp(28px, 4vw, 48px);
  padding: clamp(36px, 5vw, 64px) clamp(24px, 4vw, 56px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 92% 6%, rgba(216, 255, 98, .06), transparent 50%),
    radial-gradient(circle at 6% 96%, rgba(255, 118, 95, .05), transparent 50%),
    linear-gradient(180deg, rgba(30, 38, 54, .5), rgba(14, 20, 32, .62));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 36px 90px -34px rgba(0, 0, 0, .55);
}

.marked-proof__sheet::before {
  position: absolute;
  inset: 9px;
  border: 1px dashed rgba(146, 186, 255, .08);
  pointer-events: none;
  content: '';
}

.marked-proof__crop {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 0 solid var(--acid);
  opacity: .55;
  pointer-events: none;
}

.marked-proof__crop--tl { top: -1px; left: -1px; border-top-width: 1px; border-left-width: 1px; }
.marked-proof__crop--tr { top: -1px; right: -1px; border-top-width: 1px; border-right-width: 1px; }
.marked-proof__crop--bl { bottom: -1px; left: -1px; border-bottom-width: 1px; border-left-width: 1px; }
.marked-proof__crop--br { bottom: -1px; right: -1px; border-bottom-width: 1px; border-right-width: 1px; }

.marked-proof__plate {
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translate(-50%, -55%);
  padding: 4px 14px;
  border: 1px solid var(--line);
  border-top: 0;
  background: var(--night);
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
  white-space: nowrap;
}

.marked-proof__head {
  max-width: 820px;
  padding-top: clamp(8px, 1.4vw, 18px);
}

.marked-proof__head h2 {
  max-width: 720px;
  margin: 22px 0 18px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5.2vw, 5.6rem);
  font-weight: 400;
  letter-spacing: -.068em;
  line-height: .92;
  text-wrap: balance;
}

.marked-proof__head h2 i {
  color: var(--coral);
  font-style: italic;
}

.marked-proof__head .section__lede {
  max-width: 60ch;
}

.marked-proof__body {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
  gap: clamp(28px, 4vw, 56px);
  align-items: stretch;
  padding: clamp(24px, 3.4vw, 44px) 0;
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
}

.marked-proof__lines {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(20px, 2.6vw, 36px);
  padding: clamp(4px, .6vw, 10px) clamp(4px, .8vw, 14px);
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(2.2rem, 5.2vw, 5.8rem);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.07em;
  line-height: 1.05;
}

.marked-proof__line {
  position: relative;
  display: grid;
  grid-template-columns: clamp(28px, 3vw, 44px) 1fr;
  align-items: baseline;
  gap: clamp(10px, 1.4vw, 22px);
}

.marked-proof__linenum {
  color: var(--muted);
  font-family: var(--mono);
  font-style: normal;
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
  align-self: start;
  padding-top: .9em;
}

.marked-proof__type {
  position: relative;
  display: inline;
}

.marked-proof__text {
  color: var(--paper);
}

.marked-proof__word {
  position: relative;
  display: inline-block;
  padding: 0 .14em .04em;
  border: 0;
  background: transparent;
  color: var(--paper);
  font: inherit;
  letter-spacing: inherit;
  cursor: pointer;
  transition: color .3s var(--ease), background-color .35s var(--ease);
}

.marked-proof__word--m3 {
  color: var(--acid);
}

.marked-proof__word--good {
  color: var(--coral);
}

.marked-proof__word--yet {
  color: var(--blue);
}

.marked-proof__word:hover,
.marked-proof__word:focus-visible,
.marked-proof__word.is-selected {
  color: var(--paper);
  background: rgba(216, 255, 98, .08);
}

.marked-proof__word--good:hover,
.marked-proof__word--good:focus-visible,
.marked-proof__word--good.is-selected {
  background: rgba(255, 118, 95, .1);
}

.marked-proof__word--yet:hover,
.marked-proof__word--yet:focus-visible,
.marked-proof__word--yet.is-selected {
  background: rgba(146, 186, 255, .1);
}

.marked-proof__mark-slot {
  position: absolute;
  right: 0;
  bottom: calc(100% - .08em);
  left: 0;
  display: block;
  height: clamp(34px, 3.4vw, 44px);
  color: currentColor;
  pointer-events: none;
  opacity: 0;
  transform: translateY(.18em);
  transition: opacity .5s var(--ease), transform .65s var(--ease-out);
}

.marked-proof__word.is-selected .marked-proof__mark-slot,
.marked-proof__word:hover .marked-proof__mark-slot,
.marked-proof__word:focus-visible .marked-proof__mark-slot {
  opacity: 1;
  transform: translateY(0);
}

.proof-mark {
  display: block;
  width: 100%;
  height: 100%;
  color: inherit;
}

.proof-mark__svg {
  display: block;
  width: 100%;
  height: 100%;
}

.proof-mark__label {
  font-family: var(--mono);
  font-style: normal;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .22em;
  text-transform: uppercase;
  fill: currentColor;
}

.proof-mark__label--acid { fill: var(--acid); }
.proof-mark__label--coral { fill: var(--coral); }
.proof-mark__label--blue { fill: var(--blue); }

.proof-mark--stet .proof-mark__svg path {
  stroke-dashoffset: 200;
  animation: stetDraw 1.2s var(--ease-out) .15s forwards;
}

.proof-mark--query .proof-mark__svg ellipse {
  stroke-dashoffset: 70;
  animation: stetDraw 1.1s var(--ease-out) .25s forwards;
}

@keyframes stetDraw {
  to { stroke-dashoffset: 0; }
}

.marked-proof__underline {
  position: absolute;
  right: -4%;
  bottom: -.04em;
  left: -4%;
  height: 2px;
  background: currentColor;
  opacity: .35;
  transform: scaleX(.3);
  transform-origin: left;
  transition: transform .6s var(--ease-out), opacity .4s var(--ease);
}

.marked-proof__word--good .marked-proof__underline {
  bottom: -.02em;
  height: 1px;
  background: repeating-linear-gradient(to right, currentColor 0 4px, transparent 4px 8px);
}

.marked-proof__word--yet .marked-proof__underline {
  background: repeating-linear-gradient(to right, currentColor 0 2px, transparent 2px 5px);
  height: 1px;
}

.marked-proof__word:hover .marked-proof__underline,
.marked-proof__word:focus-visible .marked-proof__underline,
.marked-proof__word.is-selected .marked-proof__underline {
  opacity: .85;
  transform: scaleX(1);
}

.marked-proof__caret {
  position: absolute;
  top: -.9em;
  left: 50%;
  width: clamp(16px, 1.6vw, 24px);
  height: clamp(14px, 1.4vw, 20px);
  transform: translate(-50%, -.3em);
  color: var(--coral);
  opacity: 0;
  transition: opacity .45s var(--ease) .2s, transform .6s var(--ease-spring) .2s;
  pointer-events: none;
}

.marked-proof__caret svg {
  display: block;
  width: 100%;
  height: 100%;
}

.marked-proof__word--good:hover .marked-proof__caret,
.marked-proof__word--good:focus-visible .marked-proof__caret,
.marked-proof__word--good.is-selected .marked-proof__caret {
  opacity: 1;
  transform: translate(-50%, 0);
}

.marked-proof__querycircle {
  position: absolute;
  top: 50%;
  right: -.32em;
  width: clamp(28px, 3vw, 40px);
  height: clamp(28px, 3vw, 40px);
  transform: translate(0, -50%) rotate(-6deg);
  color: var(--blue);
  opacity: 0;
  transition: opacity .5s var(--ease) .2s, transform .7s var(--ease-spring) .2s;
  pointer-events: none;
}

.marked-proof__querycircle svg {
  display: block;
  width: 100%;
  height: 100%;
}

.marked-proof__word--yet:hover .marked-proof__querycircle,
.marked-proof__word--yet:focus-visible .marked-proof__querycircle,
.marked-proof__word--yet.is-selected .marked-proof__querycircle {
  opacity: .85;
  transform: translate(0, -50%) rotate(0deg);
}

.marked-proof__margin {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(14px, 1.8vw, 20px);
  padding: 4px 4px 4px clamp(16px, 2vw, 28px);
}

.marked-proof__margin-rule {
  position: absolute;
  top: 6px;
  bottom: 6px;
  left: 0;
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 8%, var(--line) 92%, transparent);
}

.marked-proof__note {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  width: 100%;
  padding: 12px 14px 14px;
  border: 1px solid var(--line);
  background:
    repeating-radial-gradient(circle at 0 0, rgba(146, 186, 255, .025) 0 1px, transparent 1px 4px),
    repeating-radial-gradient(circle at 2px 2px, rgba(216, 255, 98, .02) 0 1px, transparent 1px 5px),
    rgba(23, 30, 45, .74);
  color: var(--paper);
  text-align: left;
  transition: background .45s var(--ease), border-color .45s var(--ease), transform .5s var(--ease-out), box-shadow .45s var(--ease);
}

.marked-proof__note::before {
  position: absolute;
  top: -1px;
  left: -1px;
  width: 14px;
  height: 14px;
  border-top: 1px solid currentColor;
  border-left: 1px solid currentColor;
  content: '';
  opacity: .65;
  transition: opacity .4s var(--ease);
}

.marked-proof__note--acid { color: var(--acid); }
.marked-proof__note--coral { color: var(--coral); }
.marked-proof__note--blue { color: var(--blue); }

.marked-proof__note:hover,
.marked-proof__note:focus-visible,
.marked-proof__note.is-active {
  background: rgba(31, 42, 65, .94);
  transform: translateX(4px);
  box-shadow: 4px 6px 0 rgba(6, 9, 16, .3);
}

.marked-proof__note--acid:hover,
.marked-proof__note--acid:focus-visible,
.marked-proof__note--acid.is-active {
  border-color: rgba(216, 255, 98, .5);
}

.marked-proof__note--coral:hover,
.marked-proof__note--coral:focus-visible,
.marked-proof__note--coral.is-active {
  border-color: rgba(255, 118, 95, .5);
}

.marked-proof__note--blue:hover,
.marked-proof__note--blue:focus-visible,
.marked-proof__note--blue.is-active {
  border-color: rgba(146, 186, 255, .5);
}

.marked-proof__note-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.marked-proof__note-symbol {
  color: inherit;
  font-weight: 700;
}

.marked-proof__note-folio {
  color: var(--muted);
  font-weight: 500;
}

.marked-proof__note-text {
  color: var(--paper);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  line-height: 1.5;
}

.marked-proof__note-thread {
  position: absolute;
  top: 50%;
  left: -18px;
  width: 14px;
  height: 1px;
  background: currentColor;
  opacity: .35;
  transform: translateY(-50%);
  transition: opacity .4s var(--ease), width .5s var(--ease-out);
}

.marked-proof__note:hover .marked-proof__note-thread,
.marked-proof__note:focus-visible .marked-proof__note-thread,
.marked-proof__note.is-active .marked-proof__note-thread {
  opacity: .9;
  width: 18px;
}

.marked-proof__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 18px;
  padding-top: 4px;
}

.marked-proof__stamp {
  display: inline-flex;
  width: 56px;
  height: 56px;
  color: var(--coral);
  opacity: .7;
  transition: transform .6s var(--ease-spring), opacity .4s var(--ease);
}

.marked-proof__sheet:hover .marked-proof__stamp {
  transform: rotate(-4deg);
  opacity: .9;
}

.marked-proof__caption {
  flex: 1;
  min-width: 240px;
  margin: 0;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  line-height: 1.5;
}

.marked-proof__caption span[aria-hidden] {
  color: var(--coral);
  font-style: normal;
  font-size: 18px;
  margin-right: 8px;
}

.marked-proof__pagecount {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

@media (max-width: 1080px) {
  .marked-proof__body {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .marked-proof__margin {
    padding-left: 0;
    padding-top: 18px;
  }

  .marked-proof__margin-rule {
    top: 0;
    left: 0;
    right: 0;
    bottom: auto;
    width: auto;
    height: 1px;
    background: linear-gradient(to right, transparent, var(--line) 8%, var(--line) 92%, transparent);
  }

  .marked-proof__note-thread {
    display: none;
  }
}

@media (max-width: 640px) {
  .marked-proof__sheet {
    padding: 28px 20px 24px;
  }

  .marked-proof__lines {
    font-size: clamp(1.9rem, 8.4vw, 3rem);
    gap: 16px;
  }

  .marked-proof__mark-slot {
    height: 28px;
  }

  .marked-proof__caption {
    font-size: 13px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .proof-mark--stet .proof-mark__svg path,
  .proof-mark--query .proof-mark__svg ellipse {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }

  .title-token__underline-stroke {
    stroke-dashoffset: 0 !important;
    animation: none !important;
  }

  .hero__summary-scrawl path {
    stroke-dashoffset: 0 !important;
    animation: none !important;
  }

  .hero__summary-scrawl circle {
    opacity: 1 !important;
    transform: none !important;
    animation: none !important;
  }
}

/* ────────────────────────────────────────────────────────────
   PRESS BAY · the composing press in the hero margin
   ──────────────────────────────────────────────────────────── */

.press-bay {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(14px, 1.4vw, 20px);
  padding: clamp(16px, 1.6vw, 22px) clamp(12px, 1.4vw, 18px) clamp(14px, 1.4vw, 18px) clamp(20px, 2.2vw, 32px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
  isolation: isolate;
}

.press-bay::before {
  position: absolute;
  top: 14px;
  bottom: 14px;
  left: 0;
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 14%, var(--line) 86%, transparent);
  content: '';
  z-index: 0;
}

.press-bay__head {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  z-index: 1;
}

.press-bay__tag {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--coral);
  font-size: 9px;
  letter-spacing: .22em;
}

.press-bay__tag-dot {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(255, 118, 95, .14);
  animation: composePulse 2.4s var(--ease) infinite;
}

.press-bay__tag-sep {
  color: var(--muted);
  opacity: .55;
  margin: 0 2px;
}

.press-bay__state {
  color: var(--acid);
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  letter-spacing: 0;
  text-transform: none;
  transition: color .45s var(--ease);
}

.press-bay--voice-quiet .press-bay__state { color: var(--blue); }
.press-bay--voice-human .press-bay__state { color: var(--coral); }
.press-bay--voice-bold .press-bay__state { color: var(--acid); }

.press-bay__now {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 0 12px;
  border-top: 1px dashed var(--line);
  border-bottom: 1px dashed var(--line);
  z-index: 1;
}

.press-bay__now-eyebrow {
  color: var(--ink-mist);
  font-size: 8.5px;
  letter-spacing: .24em;
}

.press-bay__now-name {
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(22px, 1.9vw, 30px);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.03em;
  line-height: 1;
  text-transform: none;
  transition: color .5s var(--ease);
}

.press-bay--voice-quiet .press-bay__now-name { color: var(--paper); }
.press-bay--voice-human .press-bay__now-name { color: var(--coral); }
.press-bay--voice-bold .press-bay__now-name { color: var(--acid); }

.press-bay__now-face {
  color: var(--muted);
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  letter-spacing: 0;
  text-transform: none;
}

.press-bay__now-letter {
  position: absolute;
  top: 8px;
  right: 0;
  color: var(--coral);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(28px, 2.6vw, 40px);
  line-height: 1;
  letter-spacing: -.04em;
  opacity: .18;
  transition: color .5s var(--ease), opacity .5s var(--ease);
}

.press-bay--voice-quiet .press-bay__now-letter { color: var(--blue); }
.press-bay--voice-human .press-bay__now-letter { color: var(--coral); }
.press-bay--voice-bold .press-bay__now-letter { color: var(--acid); }

.press-bay__now-count {
  display: inline-flex;
  align-items: center;
  gap: 0;
  margin-top: 6px;
}

.press-bay__now-pip {
  position: relative;
  display: inline-flex;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1px solid currentColor;
  background: transparent;
  transition: background .35s var(--ease), transform .4s var(--ease-spring), color .35s var(--ease);
  color: var(--mist);
}

.press-bay__now-pip.is-on {
  background: currentColor;
  transform: scale(1.2);
}

.press-bay--voice-quiet .press-bay__now-pip.is-on { color: var(--blue); }
.press-bay--voice-human .press-bay__now-pip.is-on { color: var(--coral); }
.press-bay--voice-bold .press-bay__now-pip.is-on { color: var(--acid); }

.press-bay__now-pip-line {
  display: block;
  width: 6px;
  height: 1px;
  background: var(--line);
  margin: 0 2px;
  align-self: center;
}

.press-bay__impression {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 1;
}

.press-bay__impression-bar {
  display: flex;
  align-items: center;
  gap: 8px;
}

.press-bay__impression-bar-line {
  flex: 1;
  height: 1px;
  background: var(--line);
}

.press-bay__impression-bar-text {
  color: var(--muted);
  font-size: 8.5px;
  letter-spacing: .22em;
  white-space: nowrap;
}

.press-bay__impression-card {
  position: relative;
  display: grid;
  grid-template-columns: 24px 1fr;
  grid-template-rows: auto auto;
  gap: 6px 10px;
  padding: 12px 12px 10px;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .55), rgba(14, 20, 32, .65));
  border: 1px solid var(--line);
  isolation: isolate;
  transition: border-color .45s var(--ease), transform .45s var(--ease-out);
}

.press-bay__impression-card:hover {
  border-color: rgba(216, 255, 98, .35);
  transform: translateX(2px);
}

.press-bay__impression-card-fold {
  position: absolute;
  top: 0;
  right: 0;
  width: 14px;
  height: 14px;
  background: linear-gradient(135deg, transparent 49%, var(--line) 49% 51%, transparent 51%);
  z-index: 1;
}

.press-bay__impression-card-corner {
  position: absolute;
  width: 5px;
  height: 5px;
  border: 0 solid currentColor;
  opacity: .5;
}

.press-bay__impression-card-corner--tl { top: -1px; left: -1px; border-top-width: 1px; border-left-width: 1px; }
.press-bay__impression-card-corner--tr { top: -1px; right: -1px; border-top-width: 1px; border-right-width: 1px; }
.press-bay__impression-card-corner--bl { bottom: -1px; left: -1px; border-bottom-width: 1px; border-left-width: 1px; }
.press-bay__impression-card-corner--br { bottom: -1px; right: -1px; border-bottom-width: 1px; border-right-width: 1px; }

.press-bay__impression-card--quiet .press-bay__impression-card-corner { color: var(--blue); }
.press-bay__impression-card--human .press-bay__impression-card-corner { color: var(--coral); }
.press-bay__impression-card--bold .press-bay__impression-card-corner { color: var(--acid); }

.press-bay__impression-letter {
  grid-column: 1;
  grid-row: 1 / span 2;
  align-self: center;
  color: var(--coral);
  font-family: var(--serif);
  font-style: italic;
  font-size: 24px;
  line-height: 1;
  letter-spacing: -.04em;
  transition: color .45s var(--ease);
}

.press-bay__impression-card--quiet .press-bay__impression-letter { color: var(--blue); }
.press-bay__impression-card--human .press-bay__impression-letter { color: var(--coral); }
.press-bay__impression-card--bold .press-bay__impression-letter { color: var(--acid); }

.press-bay__impression-type {
  grid-column: 2;
  grid-row: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  letter-spacing: -.045em;
  line-height: 1.1;
  color: var(--paper);
  text-transform: none;
}

.press-bay__impression-type span:nth-child(2) {
  color: var(--acid);
}

.press-bay__impression-type--human {
  font-style: italic;
}

.press-bay__impression-type--human span:nth-child(2) {
  color: var(--coral);
}

.press-bay__impression-type--bold {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: -.06em;
  font-size: 11.5px;
}

.press-bay__impression-type--bold span:nth-child(2),
.press-bay__impression-type--bold span:nth-child(3) {
  color: var(--paper);
}

.press-bay__impression-type--bold span:nth-child(3) {
  color: var(--acid);
}

.press-bay__impression-foot {
  grid-column: 1 / -1;
  grid-row: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px dashed var(--line);
}

.press-bay__impression-foot-meta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 8.5px;
  letter-spacing: .18em;
}

.press-bay__impression-foot-label {
  color: var(--ink-mist);
}

.press-bay__impression-foot-num {
  color: var(--coral);
  font-weight: 600;
}

.press-bay__impression-swap {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px 4px 6px;
  border: 0;
  background: transparent;
  color: var(--acid);
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
  transition: color .25s var(--ease), gap .3s var(--ease-out);
}

.press-bay__impression-swap svg {
  width: 12px;
  height: 12px;
  flex: 0 0 auto;
  transition: transform .3s var(--ease-out);
}

.press-bay__impression-swap:hover,
.press-bay__impression-swap:focus-visible {
  color: var(--paper);
  gap: 9px;
}

.press-bay__impression-swap:hover svg,
.press-bay__impression-swap:focus-visible svg {
  transform: translateX(2px);
}

.press-bay__lever-zone {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 4px 0 0;
  z-index: 1;
}

.press-bay__lever-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.press-bay__lever-eyebrow-line {
  display: block;
  width: 12px;
  height: 1px;
  background: var(--line);
}

.press-bay__lever-set {
  position: relative;
  width: 100%;
  height: 200px;
  margin: 2px 0 0;
}

.press-bay__lever {
  position: absolute;
  bottom: 4px;
  left: 50%;
  width: 80px;
  height: 180px;
  border: 0;
  background: transparent;
  cursor: pointer;
  padding: 0;
  z-index: 3;
  transform-origin: 50% 100%;
  transition: filter .3s var(--ease);
}

.press-bay__lever:hover {
  filter: drop-shadow(0 0 8px rgba(216, 255, 98, .25));
}

.press-bay__lever:focus {
  outline: none;
}

.press-bay__lever.is-pulling {
  animation: leverPull 0.6s var(--ease-spring);
}

@keyframes leverPull {
  0% { transform: translateX(-50%) rotate(0deg); }
  25% { transform: translateX(-50%) rotate(22deg); }
  55% { transform: translateX(-50%) rotate(-3deg); }
  78% { transform: translateX(-50%) rotate(2deg); }
  100% { transform: translateX(-50%) rotate(0deg); }
}

.press-bay__lever-stem {
  position: absolute;
  bottom: 46px;
  left: 50%;
  transform: translateX(-50%);
  width: 4px;
  height: 96px;
  border-radius: 1px;
  background: linear-gradient(180deg,
    rgba(146, 186, 255, .55) 0%,
    rgba(146, 186, 255, .85) 60%,
    rgba(91, 121, 203, .95) 100%);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, .45),
    inset 0 0 0 1px rgba(255, 255, 255, .18);
}

.press-bay__lever-stem-rail {
  position: absolute;
  top: 4px;
  left: 50%;
  transform: translateX(-50%);
  width: 1px;
  height: calc(100% - 8px);
  background: rgba(255, 255, 255, .35);
}

.press-bay__lever-stem-pin {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #ddd 0%, #888 50%, #2a2a2a 100%);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, .55),
    0 1px 0 rgba(255, 255, 255, .2);
}

.press-bay__lever-handle {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: radial-gradient(circle at 32% 30%,
    #f0d8c8 0%,
    #c9a888 35%,
    #6a4a30 80%,
    #2a1a10 100%);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, .55),
    0 4px 0 rgba(0, 0, 0, .5),
    0 8px 12px rgba(0, 0, 0, .45);
}

.press-bay__lever-knob {
  position: absolute;
  inset: 0;
  border-radius: 50%;
}

.press-bay__lever-knob-shadow {
  position: absolute;
  bottom: 2px;
  right: 4px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(0, 0, 0, .35);
  filter: blur(2px);
}

.press-bay__lever-knob-highlight {
  position: absolute;
  top: 6px;
  left: 9px;
  width: 9px;
  height: 7px;
  border-radius: 50%;
  background: rgba(255, 255, 255, .55);
  filter: blur(.5px);
}

.press-bay__lever-knob-band {
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 1px;
  background: rgba(0, 0, 0, .35);
  transform: translateY(-50%);
}

.press-bay__lever-knob-rivet {
  position: absolute;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, .55), rgba(0, 0, 0, .55) 80%);
  box-shadow: inset 0 -1px 0 rgba(0, 0, 0, .4);
  opacity: .7;
}

.press-bay__lever-knob-rivet--a {
  top: 28%;
  right: 26%;
}

.press-bay__lever-knob-rivet--b {
  bottom: 28%;
  left: 26%;
}

.press-bay__lever-pull {
  position: absolute;
  top: -20px;
  left: 50%;
  transform: translateX(-50%);
  padding: 2px 8px 3px;
  border: 1px solid var(--acid);
  background: var(--night);
  color: var(--acid);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .24em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0;
  transition: opacity .3s var(--ease), transform .35s var(--ease-spring);
  pointer-events: none;
}

.press-bay__lever:hover .press-bay__lever-pull,
.press-bay__lever:focus-visible .press-bay__lever-pull {
  opacity: .9;
  transform: translateX(-50%) translateY(2px);
}

.press-bay__lever.is-pulling .press-bay__lever-pull {
  opacity: 1;
  animation: pullLabel 0.6s var(--ease);
}

@keyframes pullLabel {
  0% { transform: translateX(-50%) translateY(2px); opacity: 0; }
  20% { transform: translateX(-50%) translateY(-4px); opacity: 1; }
  80% { transform: translateX(-50%) translateY(-8px); opacity: 1; }
  100% { transform: translateX(-50%) translateY(-12px); opacity: 0; }
}

.press-bay__lever-base {
  position: absolute;
  bottom: -8px;
  left: 50%;
  transform: translateX(-50%);
  width: 92px;
  height: 92px;
  z-index: 2;
  pointer-events: none;
  color: var(--coral);
  filter: drop-shadow(0 6px 10px rgba(0, 0, 0, .5));
  transition: transform .55s var(--ease-spring), color .45s var(--ease);
}

.press-bay--voice-quiet .press-bay__lever-base { color: var(--blue); }
.press-bay--voice-human .press-bay__lever-base { color: var(--coral); }
.press-bay--voice-bold .press-bay__lever-base { color: var(--acid); }

.press-bay:hover .press-bay__lever-base {
  transform: translateX(-50%) rotate(-3deg);
}

.press-bay__lever-cage {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 1;
  pointer-events: none;
}

.press-bay__lever-cage-rail {
  position: absolute;
  top: 8px;
  bottom: 80px;
  width: 1px;
  background: linear-gradient(to bottom, var(--line), transparent);
}

.press-bay__lever-cage-rail--left { left: 18%; }
.press-bay__lever-cage-rail--right { right: 18%; }

.press-bay__lever-cage-cap {
  position: absolute;
  top: 4px;
  left: 50%;
  transform: translateX(-50%);
  width: 24px;
  height: 1px;
  background: var(--line);
}

.press-bay__lever-cage-tick {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 8px;
  height: 1px;
  background: var(--line);
  opacity: .7;
}

.press-bay__lever-cage-tick--top {
  top: 22%;
}

.press-bay__lever-cage-tick--mid {
  top: 48%;
  width: 14px;
  background: linear-gradient(to right, transparent, var(--line) 20%, var(--line) 80%, transparent);
}

.press-bay__lever-shadow {
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  width: 100px;
  height: 16px;
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(0, 0, 0, .4), transparent 70%);
  z-index: 0;
  pointer-events: none;
}

.press-bay__lever-hint {
  color: var(--muted);
  font-family: var(--serif);
  font-size: 10.5px;
  font-style: italic;
  letter-spacing: 0;
  text-transform: none;
  text-align: center;
  opacity: .7;
}

.press-bay__lever-hint kbd {
  display: inline-block;
  padding: 1px 4px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: rgba(146, 186, 255, .06);
  color: var(--mist);
  font-family: var(--mono);
  font-size: 8.5px;
  font-style: normal;
  letter-spacing: 0;
  text-transform: uppercase;
  margin: 0 1px;
}

.press-bay__plate {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 0 0;
  z-index: 1;
}

.press-bay__plate-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 2px;
}

.press-bay__plate-bar-line {
  flex: 1;
  height: 1px;
  background: var(--line);
}

.press-bay__plate-bar-text {
  color: var(--muted);
  font-size: 8.5px;
  letter-spacing: .22em;
  white-space: nowrap;
}

.press-bay__plate-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}

.press-bay__plate-mark {
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .2em;
  text-transform: uppercase;
  transition: color .45s var(--ease);
}

.press-bay--word-m3 .press-bay__plate-mark { color: var(--acid); }
.press-bay--word-good .press-bay__plate-mark { color: var(--coral); }
.press-bay--word-yet .press-bay__plate-mark { color: var(--blue); }

.press-bay__plate-label {
  color: var(--paper);
  font-family: var(--serif);
  font-size: 18px;
  font-style: italic;
  letter-spacing: -.02em;
  text-transform: none;
}

.press-bay__plate-folio {
  margin-left: auto;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .18em;
}

.press-bay__plate-gloss {
  color: var(--mist);
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  letter-spacing: 0;
  line-height: 1.4;
  text-transform: none;
}

.press-bay__plate-prompt {
  color: var(--paper);
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  letter-spacing: -.01em;
  line-height: 1.4;
  text-transform: none;
  opacity: .65;
}

.press-bay__rule {
  position: relative;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 10px 2px 2px;
  border-top: 1px dashed var(--line);
  margin-top: 4px;
  z-index: 1;
}

.press-bay__rule-line {
  flex: 1;
  height: 1px;
  background: repeating-linear-gradient(to right, var(--line) 0 3px, transparent 3px 6px);
}

.press-bay__rule-node {
  position: relative;
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 50%;
  border: 1px solid currentColor;
  color: var(--mist);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .15em;
  background: rgba(12, 16, 25, .55);
  transition: background .4s var(--ease), color .4s var(--ease), transform .55s var(--ease-spring), box-shadow .4s var(--ease);
}

.press-bay__rule-node--m3 { color: var(--acid); }
.press-bay__rule-node--good { color: var(--coral); }
.press-bay__rule-node--yet { color: var(--blue); }

.press-bay__rule-pip {
  position: absolute;
  inset: 3px;
  border-radius: 50%;
  border: 1px solid currentColor;
  opacity: .55;
  transition: opacity .35s var(--ease), background .35s var(--ease), transform .4s var(--ease-spring);
}

.press-bay__rule-num {
  position: relative;
  z-index: 1;
  color: inherit;
  transition: color .4s var(--ease);
}

.press-bay__rule-node.is-active {
  background: currentColor;
  transform: scale(1.12);
  box-shadow: 0 0 0 4px rgba(255, 255, 255, .04);
}

.press-bay__rule-node.is-active .press-bay__rule-pip {
  background: var(--ink);
  border-color: var(--ink);
  opacity: 0;
  transform: scale(.55);
}

.press-bay__rule-node.is-active .press-bay__rule-num {
  color: var(--ink);
  font-weight: 700;
}

@media (max-width: 1080px) {
