  }
}

@media (max-width: 880px) {
  .hero__sheet {
    grid-template-columns: minmax(0, 1fr);
    gap: 22px;
  }

  .press-bay {
    padding: 18px 0 4px;
    margin-top: 4px;
    border-top: 1px solid var(--line);
  }

  .press-bay::before {
    display: none;
  }

  .press-bay__lever-set {
    height: 180px;
  }

  .press-bay__plate-row {
