    padding-top: 14px;
  }

  .press-bay__now-name {
    font-size: 22px;
  }

  .press-bay__now-letter {
    font-size: 28px;
  }

  .press-bay__impression-type {
    font-size: 12.5px;
  }

  .press-bay__impression-type--bold {
    font-size: 10.5px;
  }

  .press-bay__lever-set {
    height: 170px;
  }

  .press-bay__lever {
    width: 70px;
    height: 160px;
  }

  .press-bay__lever-base {
    width: 80px;
    height: 80px;
  }

  .press-bay__lever-handle {
    width: 32px;
    height: 32px;
  }

  .press-bay__plate-label {
    font-size: 16px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-bay__lever.is-pulling {
    animation: none !important;
    transform: translateX(-50%) !important;
  }

  .press-bay__lever.is-pulling .press-bay__lever-pull {
    animation: none !important;
    opacity: .9 !important;
    transform: translateX(-50%) !important;
  }

  .press-bay:hover .press-bay__lever-base {
    transform: translateX(-50%) !important;
  }
}

/* ────────────────────────────────────────────────────────────
   PRESS ROOM · the composing press earns its own folio
   ──────────────────────────────────────────────────────────── */

.press-room {
  position: relative;
  padding: clamp(80px, 10vw, 130px) 0 clamp(40px, 6vw, 80px);
  border-top: 1px solid var(--line-soft);
}

.press-room__sheet {
  position: relative;
  display: grid;
  gap: clamp(22px, 3vw, 36px);
  padding: clamp(36px, 5vw, 64px) clamp(26px, 4vw, 56px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 92% 4%, rgba(216, 255, 98, .06), transparent 50%),
    radial-gradient(circle at 6% 96%, rgba(255, 118, 95, .05), transparent 50%),
    linear-gradient(180deg, rgba(30, 38, 54, .5), rgba(14, 20, 32, .62));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 36px 90px -34px rgba(0, 0, 0, .55);
}

.press-room__sheet::before {
  position: absolute;
  inset: 9px;
  border: 1px dashed rgba(146, 186, 255, .07);
  pointer-events: none;
  content: '';
}

.press-room__plate {
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translate(-50%, -55%);
  padding: 4px 14px;
  border: 1px solid var(--line);
  border-top: 0;
  background: var(--night);
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
  white-space: nowrap;
  z-index: 2;
}

.press-room__crop {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 0 solid var(--acid);
  pointer-events: none;
  opacity: .55;
  transition: opacity .35s var(--ease);
}

.press-room__crop--tl { top: -1px; left: -1px; border-top-width: 1px; border-left-width: 1px; }
.press-room__crop--tr { top: -1px; right: -1px; border-top-width: 1px; border-right-width: 1px; }
.press-room__crop--bl { bottom: -1px; left: -1px; border-bottom-width: 1px; border-left-width: 1px; }
.press-room__crop--br { bottom: -1px; right: -1px; border-bottom-width: 1px; border-right-width: 1px; }

.press-room:hover .press-room__crop { opacity: 1; }

.press-room__head {
  position: relative;
  max-width: 820px;
  padding-top: clamp(8px, 1.4vw, 18px);
}

.press-room__head h2 {
  max-width: 720px;
  margin: 22px 0 18px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5.2vw, 5.6rem);
  font-weight: 400;
  letter-spacing: -.068em;
  line-height: .92;
  text-wrap: balance;
}

.press-room__head h2 i {
  color: var(--coral);
  font-style: italic;
}

.press-room__head .section__lede {
  max-width: 60ch;
}

.press-room__body {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 360px);
  gap: clamp(28px, 4vw, 56px);
  align-items: stretch;
  padding: clamp(22px, 3vw, 36px) 0;
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
}

.press-room__notes {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 14px;
  align-self: stretch;
  padding: 4px clamp(18px, 2.4vw, 32px) 4px 4px;
  color: var(--mist);
  font-family: var(--serif);
  font-size: 15px;
  font-style: italic;
  line-height: 1.55;
  border-right: 1px dashed var(--line);
}

.press-room__notes-eyebrow {
  display: inline-flex;
  align-self: flex-start;
  align-items: center;
  gap: 8px;
  padding: 3px 9px 4px;
  border: 1px solid var(--line);
  border-radius: 1px;
  color: var(--acid);
  font-family: var(--mono);
  font-size: 9px;
  font-style: normal;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press-room__notes-eyebrow::before {
  content: '';
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(216, 255, 98, .14);
}

.press-room__notes p {
  margin: 0;
  max-width: 44ch;
  color: var(--mist);
}

.press-room__voices {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 4px 0 0;
  padding: 14px 0 0;
  list-style: none;
  border-top: 1px dotted var(--line);
}

.press-room__voices-item {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 12px;
  align-items: baseline;
  padding: 6px 10px 7px;
  border: 1px solid transparent;
  border-radius: 1px;
  background: transparent;
  color: var(--ink-mist);
  transition: background .35s var(--ease), border-color .35s var(--ease), color .35s var(--ease), transform .45s var(--ease-out);
}

.press-room__voices-letter {
  font-family: var(--serif);
  font-style: italic;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -.04em;
  color: var(--coral);
  transition: color .35s var(--ease);
}

.press-room__voices-item--quiet .press-room__voices-letter { color: var(--blue); }
.press-room__voices-item--human .press-room__voices-letter { color: var(--coral); }
.press-room__voices-item--bold .press-room__voices-letter { color: var(--acid); }

.press-room__voices-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  line-height: 1.2;
}

.press-room__voices-copy strong {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: 16px;
  font-weight: 400;
  letter-spacing: -.01em;
  text-transform: none;
}

.press-room__voices-copy em {
  color: var(--ink-mist);
  font-family: var(--mono);
  font-size: 9px;
  font-style: normal;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.press-room__voices-item.is-current {
  background: rgba(216, 255, 98, .05);
  border-color: rgba(216, 255, 98, .25);
  transform: translateX(4px);
  box-shadow: -2px 2px 0 rgba(216, 255, 98, .12);
}

.press-room__voices-item--quiet.is-current {
  background: rgba(146, 186, 255, .06);
  border-color: rgba(146, 186, 255, .28);
  box-shadow: -2px 2px 0 rgba(146, 186, 255, .12);
}

.press-room__voices-item--human.is-current {
  background: rgba(255, 118, 95, .06);
  border-color: rgba(255, 118, 95, .3);
  box-shadow: -2px 2px 0 rgba(255, 118, 95, .14);
}

.press-room__voices-item.is-current .press-room__voices-copy strong {
  color: var(--paper);
}

.press-room__notes-hint {
  margin-top: auto !important;
  padding-top: 14px;
  border-top: 1px dotted var(--line);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  font-style: normal;
  letter-spacing: .18em;
  text-transform: uppercase;
  line-height: 1.5;
}

.press-room__notes-hint kbd {
  display: inline-block;
  padding: 1px 5px 2px;
  margin: 0 2px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: rgba(146, 186, 255, .06);
  color: var(--mist);
  font-family: var(--mono);
  font-size: 9px;
  font-style: normal;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.press-room__notes-hint span[aria-hidden] {
  color: var(--muted);
  margin: 0 1px;
}

.press-room__press {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  max-width: 380px;
  justify-self: end;
}

.press-room__press .press-bay {
  padding: 4px clamp(12px, 1.6vw, 20px) 4px clamp(18px, 2.2vw, 28px);
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  background:
    radial-gradient(circle at 50% 0%, rgba(216, 255, 98, .05), transparent 55%),
    linear-gradient(180deg, rgba(20, 28, 42, .6), rgba(14, 20, 32, .75));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 12px 36px -18px rgba(0, 0, 0, .55);
}

.press-room__press .press-bay::before {
  display: none;
}

.press-room__caption {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  max-width: 64ch;
  margin: 4px 0 0;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  line-height: 1.55;
}

.press-room__caption span[aria-hidden] {
  color: var(--coral);
  font-style: normal;
  font-size: 16px;
}

@media (max-width: 880px) {
  .press-room__body {
    grid-template-columns: 1fr;
    gap: 22px;
    padding: clamp(18px, 3vw, 28px) 0;
  }

  .press-room__notes {
    border-right: 0;
    border-bottom: 1px dashed var(--line);
    padding: 0 0 18px;
  }

  .press-room__press {
    max-width: 100%;
    justify-self: stretch;
  }
}

@media (max-width: 540px) {
  .press-room__sheet {
    padding: 28px 18px 22px;
  }

  .press-room__notes p {
    font-size: 14px;
  }

  .press-room__voices-item {
    padding: 5px 8px 6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-room__title-pip-mark {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

/* ────────────────────────────────────────────────────────────
   COMPOSE FLOOR · physical re-set when voice changes
   ──────────────────────────────────────────────────────────── */

.compose-floor__case.is-voice-changing .compose-floor__piece {
  animation: pieceReset .65s var(--ease-spring);
}

.compose-floor__case.is-voice-changing .compose-floor__piece:nth-child(1) { animation-delay: 0s; }
.compose-floor__case.is-voice-changing .compose-floor__piece:nth-child(2) { animation-delay: .05s; }
.compose-floor__case.is-voice-changing .compose-floor__piece:nth-child(3) { animation-delay: .1s; }
.compose-floor__case.is-voice-changing .compose-floor__piece:nth-child(4) { animation-delay: .15s; }
.compose-floor__case.is-voice-changing .compose-floor__piece:nth-child(5) { animation-delay: .2s; }

@keyframes pieceReset {
  0% { transform: translateY(0) rotate(0deg); }
  35% { transform: translateY(-22px) rotate(0deg); }
  65% { transform: translateY(2px) rotate(0deg); }
  100% { transform: translateY(0) rotate(0deg); }
}

.compose-floor__case.is-voice-changing .compose-floor__piece.is-active {
  animation: pieceResetActive .75s var(--ease-spring);
}

@keyframes pieceResetActive {
  0% { transform: translateY(-9px) rotate(-1.4deg); }
  35% { transform: translateY(-30px) rotate(-1.4deg) scale(1.05); }
  70% { transform: translateY(4px) rotate(-1.4deg); }
  100% { transform: translateY(-9px) rotate(-1.4deg); }
}

/* ────────────────────────────────────────────────────────────
   IMPRESSION · a pulled proof on the colophon
   ──────────────────────────────────────────────────────────── */

.colophon__impression {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: clamp(16px, 2.4vw, 28px);
  padding: clamp(16px, 2.2vw, 24px) clamp(20px, 2.6vw, 28px);
  border: 1px dashed rgba(146, 186, 255, .14);
  background:
    radial-gradient(circle at 8% 50%, rgba(216, 255, 98, .04), transparent 60%),
    radial-gradient(circle at 92% 50%, rgba(255, 118, 95, .04), transparent 60%);
}

.colophon__impression::before,
.colophon__impression::after {
  position: absolute;
  width: 10px;
  height: 10px;
  border: 0 solid var(--coral);
  opacity: .55;
  content: '';
}

.colophon__impression::before {
  top: -1px;
  left: -1px;
  border-top-width: 1px;
  border-left-width: 1px;
}

.colophon__impression::after {
  bottom: -1px;
  right: -1px;
  border-bottom-width: 1px;
  border-right-width: 1px;
}

.colophon__impression-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.colophon__impression-tag-dot {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 0 3px rgba(216, 255, 98, .12);
  animation: composePulse 2.4s var(--ease) infinite;
}

.colophon__impression-line {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.colophon__impression-head {
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(15px, 1.4vw, 18px);
  font-style: italic;
  letter-spacing: -.01em;
  text-transform: none;
  line-height: 1.35;
}

.colophon__impression-head em {
  color: var(--coral);
  font-style: italic;
}

.colophon__impression-meta {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.colophon__impression-meta em {
  font-style: normal;
  color: var(--coral);
}

.colophon__impression-mark-tag {
  margin-left: 6px;
  color: var(--muted);
  font-style: normal;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
