/* ────────────────────────────────────────────────────────────
   PRESS SIGNATURE · a tactile illustrated element that lives
   inside the hero, showing the active voice + active word
   together in a hand-set card
   ──────────────────────────────────────────────────────────── */

.hero__signature {
  position: relative;
  display: block;
  width: 100%;
  max-width: 880px;
  margin: clamp(8px, 1.4vw, 14px) auto 0;
  z-index: 2;
  opacity: 0;
  transform: translateY(8px);
  animation: traceFade .7s var(--ease-out) .55s forwards;
}

@keyframes traceFade {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ────────────────────────────────────────────────────────────
   HERO TITLE-PAGE SIGNATURE · the closing row that seals
   folio i as a printed broadside. A delicate lead rule, a
   small folio tag, a hand-set pencil stroke, a pulled line,
   and a pressed stamp — all in a single confident row.
   ──────────────────────────────────────────────────────────── */

.hero__body > .hero__signature:not(.hero__signature--press) {
  display: grid;
  grid-template-rows: auto auto auto;
  justify-items: center;
  gap: clamp(8px, 1vw, 12px);
  max-width: 760px;
  margin: clamp(28px, 4vw, 44px) auto 0;
  padding-top: clamp(20px, 2.4vw, 30px);
  border-top: 1px solid rgba(243, 236, 214, .12);
  color: var(--paper);
  opacity: 0;
  animation: traceFade .8s var(--ease-out) .35s forwards;
}

.hero__signature-rule {
  display: block;
  width: 100%;
  max-width: 540px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line), transparent);
}

.hero__signature-rule--lead {
  max-width: 320px;
  opacity: .65;
}

.hero__signature-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  width: 100%;
  padding: 0 clamp(8px, 1.4vw, 18px);
}

.hero__signature-folio {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  color: var(--mist);
  font-family: var(--serif);
  font-size: clamp(11px, .95vw, 13px);
  font-style: italic;
  letter-spacing: -.002em;
  white-space: nowrap;
}

.hero__signature-folio-letter {
  display: inline-grid;
  place-items: center;
  width: 1.5em;
  height: 1.5em;
  border-radius: 50%;
  border: 1px solid var(--coral);
  color: var(--coral);
  font-family: var(--serif);
  font-style: italic;
  font-size: .9em;
  line-height: 1;
  transition: color .5s var(--ease), border-color .5s var(--ease);
}

.app--voice-quiet .hero__signature-folio-letter { color: var(--blue); border-color: var(--blue); }
.app--voice-human .hero__signature-folio-letter { color: var(--coral); border-color: var(--coral); }
.app--voice-bold .hero__signature-folio-letter { color: var(--acid); border-color: var(--acid); }

.hero__signature-folio-tag {
  font-family: var(--mono);
  font-size: clamp(8.5px, .75vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  font-style: normal;
  opacity: .7;
}

.hero__signature-mark {
  display: block;
  width: 100%;
  height: 14px;
  color: var(--coral);
  transition: color .5s var(--ease);
}

.hero__signature-mark-stroke {
  animation: heroSignatureDraw 1.2s var(--ease-out) 1s forwards;
}

.hero__signature-mark-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: traceDot .35s var(--ease-spring) 2.1s forwards;
}

@keyframes heroSignatureDraw {
  to { stroke-dashoffset: 0; }
}

.app--voice-quiet .hero__signature-mark { color: var(--blue); }
.app--voice-human .hero__signature-mark { color: var(--coral); }
.app--voice-bold .hero__signature-mark { color: var(--acid); }

.hero__signature-pull {
  display: inline-grid;
  grid-template-columns: 1fr;
  gap: 2px;
  justify-items: end;
  text-align: right;
  white-space: nowrap;
}

.hero__signature-pull em {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.005em;
}

.hero__signature-pull-meta {
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8.5px, .75vw, 10px);
  letter-spacing: .18em;
  text-transform: uppercase;
  opacity: .75;
}

.hero__signature-stamp {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 56px;
  height: 56px;
  color: var(--wax);
  filter: drop-shadow(0 1px 0 rgba(5, 8, 14, .4));
  transform: rotate(-6deg);
  animation: heroSignatureStampIn .7s cubic-bezier(.34, 1.32, .52, 1) .8s backwards;
}

.hero__signature-stamp svg {
  width: 100%;
  height: 100%;
  display: block;
}

.hero__signature-stamp-wax {
  position: absolute;
  top: 56%;
  left: -8%;
  width: 14px;
  height: 14px;
  pointer-events: none;
}

.hero__signature-stamp-wax-bead {
  position: absolute;
  top: 0;
  left: 0;
  width: 9px;
  height: 9px;
  border-radius: 50% 60% 50% 60%;
  background:
    radial-gradient(circle at 30% 30%, #ee5e4d 0%, var(--wax) 60%, #6d1a14 100%);
  box-shadow: inset 0 1px 1px rgba(255, 200, 180, .35), 0 1px 1px rgba(0, 0, 0, .4);
  opacity: 0;
  animation: heroSignatureWaxBead .55s var(--ease-out) 1.25s forwards;
}

.hero__signature-stamp-wax-wisp {
  position: absolute;
  top: 7px;
  left: 8px;
  width: 16px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--wax), transparent);
  opacity: 0;
  animation: heroSignatureWaxWisp .55s var(--ease-out) 1.4s forwards;
}

@keyframes heroSignatureStampIn {
  0% { opacity: 0; transform: rotate(-6deg) scale(.4); }
  60% { opacity: 1; transform: rotate(-4deg) scale(1.08); }
  100% { opacity: 1; transform: rotate(-6deg) scale(1); }
}

@keyframes heroSignatureWaxBead {
  0% { opacity: 0; transform: translateY(-4px) scale(.6); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes heroSignatureWaxWisp {
  0% { opacity: 0; transform: scaleX(.4); }
  100% { opacity: .6; transform: scaleX(1); }
}

@media (prefers-reduced-motion: reduce) {
  .hero__body > .hero__signature:not(.hero__signature--press) {
    animation: none !important;
    opacity: 1;
  }
  .hero__signature-mark-stroke {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }
  .hero__signature-mark-bead {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .hero__signature-stamp,
  .hero__signature-stamp-wax-bead,
  .hero__signature-stamp-wax-wisp {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

@media (max-width: 720px) {
  .hero__signature-row {
    grid-template-columns: auto auto;
    grid-template-areas:
      "folio stamp"
      "mark mark"
      "pull pull";
    row-gap: clamp(10px, 2vw, 14px);
    justify-items: center;
  }
  .hero__signature-folio { grid-area: folio; }
  .hero__signature-mark { grid-area: mark; }
  .hero__signature-pull { grid-area: pull; justify-items: center; text-align: center; }
  .hero__signature-stamp { grid-area: stamp; }
  .hero__signature-stamp-wax { display: none; }
}

@media (max-width: 540px) {
  .hero__body > .hero__signature:not(.hero__signature--press) {
    padding-top: clamp(16px, 4vw, 22px);
  }
}

/* ────────────────────────────────────────────────────────────
   TITLE FOLIO · the closing signed imprint for folio i, set
   as a single composed plate: a ruled lead edge, a pressed
   folio tag, the inscription, a monogram stamp with wax, and
   a foot strip showing the press and the cycle key. Closes
   the title page with the weight of a real colophon.
   ──────────────────────────────────────────────────────────── */

.title-folio {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: clamp(10px, 1.2vw, 14px);
  width: min(100%, 880px);
  margin: clamp(36px, 4vw, 56px) auto 0;
  padding-top: clamp(22px, 2.6vw, 32px);
  color: var(--paper);
  opacity: 0;
  transform: translateY(8px);
  animation: traceFade .85s var(--ease-out) .35s forwards;
}

.title-folio__edge {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(14px, 2vw, 22px);
  width: 100%;
  color: var(--title-folio-tone);
  transition: color .55s var(--ease);
}

.title-folio__edge svg {
  display: block;
  width: 100%;
  height: 10px;
  opacity: .75;
}

.title-folio__edge-stroke {
  stroke-dashoffset: 100;
  animation: titleFolioEdgeDraw 1.1s var(--ease-out) .55s forwards;
}

@keyframes titleFolioEdgeDraw {
  to { stroke-dashoffset: 0; }
}

.title-folio__edge-tag {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 2px 4px;
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .68;
  white-space: nowrap;
}

.title-folio__edge-tag-glyph {
  color: var(--title-folio-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: .95em;
  letter-spacing: 0;
  opacity: .9;
}

.title-folio__plate {
  position: relative;
  display: grid;
  gap: clamp(14px, 1.6vw, 20px);
  width: 100%;
  padding: clamp(18px, 2.2vw, 28px) clamp(20px, 3vw, 36px);
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .04), rgba(243, 236, 214, .015)),
    linear-gradient(135deg, rgba(243, 236, 214, .025), rgba(243, 236, 214, 0) 60%);
  border: 1px solid rgba(243, 236, 214, .14);
  border-radius: 2px;
  box-shadow:
    0 0 0 1px rgba(14, 18, 28, .4) inset,
    0 14px 32px rgba(0, 0, 0, .32);
}

.title-folio__crop {
  position: absolute;
  width: 14px;
  height: 14px;
  color: var(--paper);
  opacity: .55;
  pointer-events: none;
}

.title-folio__crop::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(currentColor, currentColor) no-repeat;
  background-size: 100% 1px;
}

.title-folio__crop::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(currentColor, currentColor) no-repeat;
  background-size: 1px 100%;
}

.title-folio__crop--tl { top: -1px; left: -1px; }
.title-folio__crop--tl::before { background-position: top left; }
.title-folio__crop--tl::after { background-position: top left; }
.title-folio__crop--tr { top: -1px; right: -1px; }
.title-folio__crop--tr::before { background-position: top right; }
.title-folio__crop--tr::after { background-position: top right; }
.title-folio__crop--bl { bottom: -1px; left: -1px; }
.title-folio__crop--bl::before { background-position: bottom left; }
.title-folio__crop--bl::after { background-position: bottom left; }
.title-folio__crop--br { bottom: -1px; right: -1px; }
.title-folio__crop--br::before { background-position: bottom right; }
.title-folio__crop--br::after { background-position: bottom right; }

.title-folio__head {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .28em;
  text-transform: uppercase;
  opacity: .78;
  justify-self: center;
}

.title-folio__head-mark {
  color: var(--title-folio-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.2em;
  letter-spacing: 0;
  opacity: .9;
}

.title-folio__head-mark--alt {
  transform: scaleX(-1);
}

.title-folio__row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(16px, 2.2vw, 28px);
}

.title-folio__folio {
  position: relative;
  display: inline-grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.4vw, 16px);
  padding-right: clamp(10px, 1.4vw, 16px);
  border-right: 1px solid rgba(243, 236, 214, .14);
}

.title-folio__folio-letter {
  display: inline-grid;
  place-items: center;
  width: clamp(46px, 5vw, 60px);
  height: clamp(46px, 5vw, 60px);
  border-radius: 50%;
  border: 1px solid var(--title-folio-tone);
  color: var(--title-folio-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(28px, 2.8vw, 38px);
  line-height: 1;
  letter-spacing: -.04em;
  box-shadow: 0 0 0 4px rgba(243, 236, 214, .02);
  transition: color .55s var(--ease), border-color .55s var(--ease);
}

.title-folio__folio-stack {
  display: inline-grid;
  gap: 2px;
  text-align: left;
}

.title-folio__folio-num {
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: .82;
}

.title-folio__folio-name {
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: -.005em;
  opacity: .85;
}

.title-folio__folio-rule {
  display: none;
}

.title-folio__copy {
  display: grid;
  gap: clamp(6px, .7vw, 10px);
  min-width: 0;
  text-align: left;
}

.title-folio__line {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .24em;
  text-transform: uppercase;
  opacity: .8;
}

.title-folio__line-mark {
  display: inline-grid;
  place-items: center;
  color: var(--title-folio-tone);
}

.title-folio__line-mark svg {
  width: 12px;
  height: 12px;
  display: block;
}

.title-folio__inscription {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(18px, 1.7vw, 24px);
  letter-spacing: -.018em;
  line-height: 1.05;
  text-shadow: 0 0 .04em rgba(243, 236, 214, .12);
  transition: color .55s var(--ease), letter-spacing .6s var(--ease);
}

.app--voice-quiet .title-folio__inscription { letter-spacing: -.012em; }
.app--voice-human .title-folio__inscription { letter-spacing: -.018em; }
.app--voice-bold .title-folio__inscription {
  font-style: normal;
  font-weight: 500;
  letter-spacing: -.034em;
  text-transform: lowercase;
}

.title-folio__inscription-rule {
  display: block;
  width: min(100%, 220px);
  height: 6px;
  margin: 2px 0 -2px;
  color: var(--title-folio-tone);
  opacity: .78;
  transition: color .55s var(--ease);
}

.title-folio__inscription-rule-stroke {
  stroke-dasharray: 200 200;
  stroke-dashoffset: 200;
  animation: titleFolioInscriptionDraw 1.4s var(--ease-out) .9s forwards;
}

@keyframes titleFolioInscriptionDraw {
  to { stroke-dashoffset: 0; }
}

.title-folio__date {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  margin-top: clamp(2px, .4vw, 6px);
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.002em;
}

.title-folio__date-eyebrow {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .85;
}

.title-folio__date-value {
  color: var(--paper);
  font-style: italic;
  letter-spacing: -.005em;
}

.title-folio__stamp {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(64px, 6.4vw, 84px);
  height: clamp(64px, 6.4vw, 84px);
  color: var(--wax);
  filter: drop-shadow(0 1px 0 rgba(5, 8, 14, .4));
  transform: rotate(-6deg);
  animation: heroSignatureStampIn .8s cubic-bezier(.34, 1.32, .52, 1) .9s backwards;
}

.title-folio__stamp svg {
  width: 100%;
  height: 100%;
  display: block;
}

.title-folio__stamp-wax {
  position: absolute;
  top: 60%;
  left: -10%;
  width: 16px;
  height: 16px;
  pointer-events: none;
}

.title-folio__stamp-wax-bead {
  position: absolute;
  top: 0;
  left: 0;
  width: 10px;
  height: 10px;
  border-radius: 50% 60% 50% 60%;
  background:
    radial-gradient(circle at 30% 30%, #ee5e4d 0%, var(--wax) 60%, #6d1a14 100%);
  box-shadow:
    inset 0 1px 1px rgba(255, 200, 180, .35),
    0 1px 1px rgba(0, 0, 0, .4);
  opacity: 0;
  animation: heroSignatureWaxBead .55s var(--ease-out) 1.4s forwards;
}

.title-folio__stamp-wax-wisp {
  position: absolute;
  top: 8px;
  left: 9px;
  width: 18px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--wax), transparent);
  opacity: 0;
  animation: heroSignatureWaxWisp .55s var(--ease-out) 1.55s forwards;
}

.title-folio__foot {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: clamp(12px, 1.4vw, 18px);
  margin-top: clamp(2px, .4vw, 6px);
}

.title-folio__foot-rule {
  display: block;
  height: 1px;
  background: linear-gradient(to right, transparent, rgba(243, 236, 214, .22), transparent);
}

.title-folio__foot-rule--trail {
  background: linear-gradient(to left, transparent, rgba(243, 236, 214, .22), transparent);
}

.title-folio__foot-row {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.2vw, 16px);
}

.title-folio__foot-cell {
  display: inline-grid;
  gap: 2px;
  text-align: center;
}

.title-folio__foot-cell-key {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .24em;
  text-transform: uppercase;
  opacity: .78;
}

.title-folio__foot-cell-value {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
}

.title-folio__foot-cell--press .title-folio__foot-cell-value {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(14px, 1.3vw, 16px);
}

.title-folio__foot-cell--press sup {
  font-size: .6em;
  vertical-align: super;
  line-height: 0;
}

.title-folio__foot-cell-voice {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.title-folio__foot-cell-voice-glyph {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 1px solid var(--title-folio-tone);
  color: var(--title-folio-tone);
  font-family: var(--serif);
  font-size: 10px;
  line-height: 1;
  font-style: normal;
  letter-spacing: 0;
}

.title-folio__foot-cell-voice-glyph::before {
  content: var(--title-folio-glyph);
  font-size: .85em;
  line-height: 1;
}

.title-folio__foot-cell-kbd {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--mono);
  font-style: normal;
  font-size: 9.5px;
  letter-spacing: .14em;
  text-transform: uppercase;
  opacity: .9;
}

.title-folio__foot-cell-kbd kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  padding: 1px 5px;
  border: 1px solid rgba(243, 236, 214, .22);
  border-radius: 3px;
  background: rgba(243, 236, 214, .04);
  color: var(--paper);
  font-family: var(--mono);
  font-style: normal;
  font-size: 9px;
  letter-spacing: .04em;
  text-transform: none;
}

.title-folio__pencil {
  display: block;
  width: min(100%, 320px);
  height: 14px;
  margin: 0 auto;
  color: var(--title-folio-tone);
  opacity: .85;
  transition: color .55s var(--ease);
}

.title-folio__pencil-stroke {
  stroke-dashoffset: 100;
  animation: titleFolioPencilDraw 1.4s var(--ease-out) 1.1s forwards;
}

.title-folio__pencil-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: traceDot .35s var(--ease-spring) 2.4s forwards;
}

@keyframes titleFolioPencilDraw {
  to { stroke-dashoffset: 0; }
}

.title-folio__trail {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.4vw, 18px);
  width: 100%;
  margin-top: clamp(4px, .6vw, 8px);
  padding: 0 clamp(10px, 1.4vw, 18px);
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .7;
}

.title-folio__trail-cell {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  white-space: nowrap;
}

.title-folio__trail-cell--lead { justify-self: end; }
.title-folio__trail-cell { justify-self: start; }

.title-folio__trail-tag {
  color: var(--paper);
  font-style: italic;
  font-family: var(--serif);
  font-size: 1.05em;
  letter-spacing: -.005em;
  text-transform: none;
  opacity: .85;
}

.title-folio__trail-text {
  opacity: .78;
}

.title-folio__trail-mark {
  color: var(--title-folio-tone);
  font-family: var(--serif);
  font-style: normal;
  font-size: 14px;
  letter-spacing: 0;
  opacity: .9;
}

.app--voice-quiet .title-folio__crop { color: var(--blue); opacity: .55; }
.app--voice-quiet .title-folio__inscription-rule { color: var(--blue); }
.app--voice-human .title-folio__crop { color: var(--coral); opacity: .55; }
.app--voice-human .title-folio__inscription-rule { color: var(--coral); }
.app--voice-bold .title-folio__crop { color: var(--acid); opacity: .55; }
.app--voice-bold .title-folio__inscription-rule { color: var(--acid); }

@media (max-width: 720px) {
  .title-folio__plate {
    padding: clamp(16px, 4vw, 22px) clamp(16px, 4vw, 22px);
  }

  .title-folio__row {
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-areas:
      "folio copy"
      "stamp stamp";
    row-gap: clamp(12px, 2.4vw, 16px);
  }

  .title-folio__folio { grid-area: folio; padding-right: clamp(8px, 2vw, 12px); }
  .title-folio__copy { grid-area: copy; }
  .title-folio__stamp { grid-area: stamp; justify-self: center; }

  .title-folio__foot {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .title-folio__foot-rule { display: none; }

  .title-folio__trail {
    flex-wrap: wrap;
    gap: clamp(6px, 1.6vw, 10px);
  }

  .title-folio__trail-cell { white-space: normal; }
}

@media (max-width: 540px) {
  .title-folio {
    margin-top: clamp(28px, 6vw, 40px);
    padding-top: clamp(18px, 4vw, 24px);
  }

  .title-folio__edge {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .title-folio__edge-tag { justify-self: center; }

  .title-folio__plate {
    padding: clamp(14px, 4vw, 18px) clamp(14px, 4vw, 20px);
  }

  .title-folio__row {
    grid-template-columns: 1fr;
    grid-template-areas:
      "folio"
      "copy"
      "stamp";
    justify-items: center;
    text-align: center;
  }

  .title-folio__folio {
    grid-area: folio;
    border-right: 0;
    border-bottom: 1px solid rgba(243, 236, 214, .14);
    padding: 0 0 clamp(10px, 2vw, 14px);
    justify-items: center;
  }

  .title-folio__copy {
    grid-area: copy;
    justify-items: center;
    text-align: center;
  }

  .title-folio__stamp {
    grid-area: stamp;
  }

  .title-folio__inscription-rule { margin-left: auto; margin-right: auto; }

  .title-folio__foot-row {
    flex-wrap: wrap;
    gap: clamp(8px, 2vw, 14px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .title-folio {
    animation: none !important;
    opacity: 1;
    transform: none;
  }

  .title-folio__edge-stroke,
  .title-folio__inscription-rule-stroke,
  .title-folio__pencil-stroke {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }

  .title-folio__pencil-bead {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }

  .title-folio__stamp,
  .title-folio__stamp-wax-bead,
  .title-folio__stamp-wax-wisp {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

/* ────────────────────────────────────────────────────────────
   IMPRESSION RIBBON · a thin session-trace that lives between
   the hero and the press bay, recording voice pulls and word
   selections as marks on a tape
   ──────────────────────────────────────────────────────────── */

.hero-trace {
  position: relative;
  width: min(100%, 1440px);
  margin: 0 auto;
  padding: clamp(6px, 1vw, 12px) var(--gutter) clamp(10px, 1.6vw, 18px);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .022), rgba(243, 236, 214, .008)),
    linear-gradient(180deg, rgba(14, 18, 28, .2), rgba(14, 18, 28, 0));
  opacity: 0;
  transform: translateY(6px);
  animation: traceFade .7s var(--ease-out) .75s forwards;
}

.impression-ribbon {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(14px, 2vw, 24px);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.impression-ribbon__tag {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--coral);
  white-space: nowrap;
}

.impression-ribbon__tag-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  box-shadow:
    0 0 0 2px rgba(0, 0, 0, .35),
    0 0 0 4px rgba(255, 118, 95, .15),
    0 0 8px rgba(255, 118, 95, .35);
  animation: composePulse 2.6s var(--ease) infinite;
}

.impression-ribbon__tape {
  position: relative;
  height: 28px;
}

.impression-ribbon__line {
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(to right, transparent 0, var(--line) 6%, var(--line) 94%, transparent 100%);
  transform: translateY(-50%);
}

.impression-ribbon__line--in {
  background: linear-gradient(to right, transparent, var(--acid-soft) 20%, var(--coral-soft) 60%, var(--blue-soft) 100%);
  opacity: .35;
}

.impression-ribbon__marks {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.impression-ribbon__mark {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 14px;
  height: 14px;
  display: grid;
  place-items: center;
  animation: ribbonMarkIn .55s var(--ease-spring) backwards;
}

.impression-ribbon__mark-voice-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(14, 15, 21, .9);
  opacity: .9;
}

.impression-ribbon__mark-voice-letter {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translate(-50%, 4px);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .14em;
  color: currentColor;
  opacity: .7;
}

.impression-ribbon__mark--voice-quiet { color: var(--blue); }
.impression-ribbon__mark--voice-human { color: var(--coral); }
.impression-ribbon__mark--voice-bold { color: var(--acid); }

.impression-ribbon__mark-pull {
  position: relative;
  display: block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  background: var(--night);
}

.impression-ribbon__mark-pull-glow {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid currentColor;
  opacity: .35;
  animation: ribbonPullGlow 1.6s var(--ease) infinite;
}

.impression-ribbon__mark--pull.impression-ribbon__mark--voice-quiet { color: var(--blue); }
.impression-ribbon__mark--pull.impression-ribbon__mark--voice-human { color: var(--coral); }
.impression-ribbon__mark--pull.impression-ribbon__mark--voice-bold { color: var(--acid); }

.impression-ribbon__mark-word-glyph {
  display: inline-grid;
  place-items: center;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1px dashed currentColor;
  background: rgba(14, 15, 21, .85);
  color: currentColor;
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
}

.impression-ribbon__mark--word-m3 { color: var(--acid); }
.impression-ribbon__mark--word-good { color: var(--coral); }
.impression-ribbon__mark--word-yet { color: var(--blue); }

.impression-ribbon__now {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 14px;
  height: 14px;
  transition: left .55s var(--ease-spring);
}

.impression-ribbon__now-bead {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: var(--paper);
  box-shadow:
    0 0 0 2px var(--ink),
    0 0 0 4px rgba(243, 236, 214, .25),
    0 0 12px rgba(243, 236, 214, .35);
  animation: beadPulse 1.4s var(--ease) infinite;
}

.impression-ribbon__now--voice-quiet .impression-ribbon__now-bead { background: var(--blue); box-shadow: 0 0 0 2px var(--ink), 0 0 0 4px rgba(155, 188, 255, .2), 0 0 12px rgba(155, 188, 255, .35); }
.impression-ribbon__now--voice-human .impression-ribbon__now-bead { background: var(--coral); box-shadow: 0 0 0 2px var(--ink), 0 0 0 4px rgba(255, 118, 95, .2), 0 0 12px rgba(255, 118, 95, .35); }
.impression-ribbon__now--voice-bold .impression-ribbon__now-bead { background: var(--acid); box-shadow: 0 0 0 2px var(--ink), 0 0 0 4px rgba(216, 255, 106, .22), 0 0 12px rgba(216, 255, 106, .4); }
.impression-ribbon__now--word-m3 .impression-ribbon__now-bead { background: var(--acid); }
.impression-ribbon__now--word-good .impression-ribbon__now-bead { background: var(--coral); }
.impression-ribbon__now--word-yet .impression-ribbon__now-bead { background: var(--blue); }
.impression-ribbon__now--pull .impression-ribbon__now-bead { background: var(--paper); }
.impression-ribbon__now--idle .impression-ribbon__now-bead { background: var(--paper); }

.impression-ribbon__now-label {
  display: inline-grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 10px;
  white-space: nowrap;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  letter-spacing: 0;
  text-transform: none;
}

.impression-ribbon__now-label-tag {
  color: var(--muted);
  font-family: var(--mono);
  font-style: normal;
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  padding: 2px 6px 3px;
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  background: rgba(14, 18, 28, .45);
}

.impression-ribbon__now-label-text {
  font-size: clamp(13px, 1.2vw, 15px);
  color: var(--paper);
  font-style: italic;
  letter-spacing: -.005em;
  transition: color .4s var(--ease);
}

.app--voice-quiet .impression-ribbon__now-label-text { color: var(--blue); }
.app--voice-human .impression-ribbon__now-label-text { color: var(--coral); }
.app--voice-bold .impression-ribbon__now-label-text { color: var(--acid); }

.impression-ribbon__now-label-meta {
  color: var(--muted);
  font-family: var(--mono);
  font-style: normal;
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.impression-ribbon__now-label-meta::before {
  content: '';
  display: block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .65;
}

.app--voice-quiet .impression-ribbon__now-label-meta { color: var(--blue); }
.app--voice-human .impression-ribbon__now-label-meta { color: var(--coral); }
.app--voice-bold .impression-ribbon__now-label-meta { color: var(--acid); }

@keyframes ribbonMarkIn {
  from { opacity: 0; transform: translate(-50%, -50%) scale(.4); }
  to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

/* a small ink-burst ring that lands with the latest mark,
   re-mounted on each splashTick so it re-fires per mark. */
.impression-ribbon__mark-splash {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid currentColor;
  transform: translate(-50%, -50%) scale(.2);
  opacity: 0;
  pointer-events: none;
  animation: ribbonMarkSplash .8s var(--ease-out) forwards;
}

@keyframes ribbonMarkSplash {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.2); }
  20% { opacity: .9; transform: translate(-50%, -50%) scale(.9); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(2.4); }
}

@media (prefers-reduced-motion: reduce) {
  .impression-ribbon__mark-splash { animation: none !important; opacity: 0 !important; }
}

@keyframes ribbonPullGlow {
  0%, 100% { transform: scale(1); opacity: .35; }
  50% { transform: scale(1.6); opacity: 0; }
}

@keyframes beadPulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.18); }
}

@media (max-width: 760px) {
  .impression-ribbon {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .impression-ribbon__tag {
    justify-content: flex-start;
  }

  .impression-ribbon__now-label {
    justify-content: flex-start;
  }
}

@media (prefers-reduced-motion: reduce) {
  .impression-ribbon__tag-dot,
  .impression-ribbon__now-bead,
  .impression-ribbon__mark-pull-glow {
    animation: none !important;
  }

  .impression-ribbon__mark {
    animation: none !important;
    opacity: 1;
    transform: translate(-50%, -50%);
  }
}

/* ────────────────────────────────────────────────────────────
   NOTEBOOK MARGINALIA · old note-card styles removed for the
   refined slip composition
   ──────────────────────────────────────────────────────────── */


/* ────────────────────────────────────────────────────────────
   ITERATION 220 · "THE PAGE EARNS ITS VOICE"
   Hero deck · colophon set-today · wax-seal press ·
   impression-ribbon date · refined responsive hero
   ──────────────────────────────────────────────────────────── */

.hero__deck {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(14px, 1.8vw, 22px);
  max-width: 880px;
  margin: clamp(10px, 1.4vw, 18px) 0 clamp(14px, 1.8vw, 22px);
  padding: 0;
  color: var(--mist);
  font-family: var(--serif);
  font-size: clamp(16px, 1.55vw, 21px);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.012em;
  line-height: 1.45;
  text-align: left;
}

.hero__deck-rule {
  display: block;
  width: clamp(20px, 4vw, 64px);
  height: 1px;
  background: rgba(23, 22, 29, .28);
}

.hero__deck-text {
  font-style: italic;
  color: var(--ink-soft);
}

.hero__deck-text em {
  font-style: italic;
}

@media (max-width: 720px) {
  .hero__deck {
    grid-template-columns: 1fr;
    gap: 8px;
    font-size: 14px;
    margin-bottom: 14px;
  }

  .hero__deck-rule {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero__deck {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

/* ─── colophon date strip ─── */

.colophon__date {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: clamp(10px, 1.6vw, 18px);
  margin-bottom: clamp(14px, 2vw, 22px);
  padding-bottom: clamp(10px, 1.4vw, 16px);
  border-bottom: 1px dashed var(--line);
}

.colophon__date-rule {
  display: block;
  height: 1px;
  background: rgba(146, 186, 255, .18);
}

.colophon__date-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--acid);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0;
  animation: colophonDateIn .8s var(--ease-out) .2s forwards;
}

.colophon__date-dot {
  display: block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 0 3px rgba(216, 255, 106, .14);
  animation: composePulse 2.4s var(--ease) infinite;
}

@keyframes colophonDateIn {
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: .9; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .colophon__date-tag {
    animation: none !important;
    opacity: .9;
  }
}

/* ─── refined press-used stamp on the answer reveal ─── */

.answer-reveal__press-used-text strong {
  display: block;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(12px, 1.1vw, 13.5px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--ink);
  line-height: 1.3;
  margin-bottom: 3px;
}

.answer-reveal__press-used-text em {
  display: block;
  font-family: var(--mono);
  font-style: normal;
  font-size: 8.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--ink-soft);
  line-height: 1.4;
}

/* ─── a more decisive wax seal: re-time the press to feel
       like it actually stamps into the page ─── */

.answer-reveal__seal {
  animation: sealPressLoop 3.4s var(--ease-spring) 1.1s 1 backwards;
}

.answer-reveal__seal::after {
  content: '';
  position: absolute;
  inset: -12px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(179, 74, 58, .22), transparent 70%);
  opacity: 0;
  pointer-events: none;
  transform: scale(.7);
  animation: sealHalo 3.4s var(--ease-out) 1.1s 1 backwards;
}

@keyframes sealPressLoop {
  0% { transform: scale(1) rotate(-4deg); }
  6% { transform: scale(.92) rotate(-6deg); }
  14% { transform: scale(1.04) rotate(-3deg); }
  22% { transform: scale(.985) rotate(-4deg); }
  100% { transform: scale(1) rotate(-4deg); }
}

@keyframes sealHalo {
  0% { opacity: 0; transform: scale(.7); }
  20% { opacity: .9; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.18); }
}

@media (prefers-reduced-motion: reduce) {
  .answer-reveal__seal,
  .answer-reveal__seal::after {
    animation: none !important;
  }
  .answer-reveal__seal::after {
    opacity: 0 !important;
  }
}

/* ─── impression ribbon date + pull count ─── */

.impression-ribbon__tag-date {
  display: inline-block;
  margin-left: 10px;
  padding-left: 10px;
  border-left: 1px solid rgba(244, 237, 219, .18);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
  opacity: .75;
}

@media (max-width: 540px) {
  .impression-ribbon__tag-date {
    display: none;
  }
}

/* ────────────────────────────────────────────────────────────
   PRESS LOG · folio ii — a deliberate session log that runs
   between the title page and the press bed. Three shelves keep
   the recent pulls, word marks, and voice sets. A timeline
   tracks the session in reading order. The now-indicator lives
   at the foot of the page. Replaces a thin impression ribbon
   with one substantive working plate.
   ──────────────────────────────────────────────────────────── */

.hero-trace--log {
  padding: clamp(28px, 3.4vw, 48px) var(--gutter) clamp(38px, 4.4vw, 64px);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  background:
    radial-gradient(circle at 88% 18%, rgba(91, 121, 203, .08), transparent 38rem),
    radial-gradient(circle at 8% 86%, rgba(216, 255, 98, .04), transparent 32rem),
    linear-gradient(180deg, rgba(243, 236, 214, .028), rgba(243, 236, 214, .01)),
    linear-gradient(180deg, rgba(14, 18, 28, .32), rgba(14, 18, 28, 0));
  opacity: 0;
  transform: translateY(8px);
  animation: traceFade .9s var(--ease-out) .55s forwards;
}

.press-log {
  --press-log-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(18px, 2vw, 26px);
  width: min(100%, 1320px);
  margin: 0 auto;
  padding: clamp(20px, 2.4vw, 32px) clamp(22px, 2.8vw, 38px) clamp(22px, 2.6vw, 36px);
  border: 1px solid var(--line);
  border-radius: 2px;
  background:
    linear-gradient(180deg, rgba(28, 32, 46, .78), rgba(20, 24, 36, .68));
  color: var(--paper);
  font-family: var(--sans);
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .8s var(--ease-out), transform .8s var(--ease-out);
}

.press-log.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.press-log--quiet { --press-log-tone: var(--blue); }
.press-log--human { --press-log-tone: var(--coral); }
.press-log--bold { --press-log-tone: var(--acid); }

.press-log__defs {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  opacity: 0;
}

.press-log__crop {
  position: absolute;
  width: 14px;
  height: 14px;
  border: 1px solid currentColor;
  color: var(--press-log-tone);
  opacity: .5;
  transition: opacity .55s var(--ease);
  pointer-events: none;
}

.press-log__crop--tl { top: -1px; left: -1px; border-right: 0; border-bottom: 0; }
.press-log__crop--tr { top: -1px; right: -1px; border-left: 0; border-bottom: 0; }
.press-log__crop--bl { bottom: -1px; left: -1px; border-right: 0; border-top: 0; }
.press-log__crop--br { bottom: -1px; right: -1px; border-left: 0; border-top: 0; }

.press-log:hover .press-log__crop { opacity: .85; }

.press-log__head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  column-gap: clamp(10px, 1.4vw, 18px);
  font-family: var(--mono);
  font-size: clamp(9px, .82vw, 10.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
}

.press-log__head-rule {
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 22%, var(--line) 78%, transparent);
}

.press-log__head-rule--end {
  background: linear-gradient(to left, transparent, var(--line) 22%, var(--line) 78%, transparent);
}

.press-log__head-tag {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--press-log-tone);
  white-space: nowrap;
}

.press-log__head-tick {
  width: 8px;
  height: 8px;
  border: 1px solid currentColor;
  background: currentColor;
  border-radius: 1px;
  opacity: .85;
  transform: rotate(45deg);
}

.press-log__head-tick--alt { opacity: .55; }

.press-log__head-title {
  font-style: italic;
  font-family: Georgia, 'Iowan Old Style', serif;
  font-size: clamp(13px, 1.1vw, 15.5px);
  letter-spacing: .01em;
  text-transform: none;
}

.press-log__head-folio {
  color: var(--ink-mist);
  font-size: clamp(8px, .72vw, 9.5px);
}

.press-log__topline {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) auto minmax(0, 1.1fr) auto minmax(0, 1.1fr);
  align-items: stretch;
  gap: clamp(12px, 1.6vw, 20px);
  padding: clamp(10px, 1.4vw, 16px) clamp(14px, 1.8vw, 22px);
  border: 1px solid var(--line);
  border-left-width: 2px;
  border-left-color: var(--press-log-tone);
  background: rgba(14, 18, 28, .42);
}

.press-log__topline-cell {
  display: grid;
  grid-template-rows: auto auto auto;
  row-gap: 4px;
  min-width: 0;
}

.press-log__topline-key {
  font-family: var(--mono);
  font-size: clamp(7.5px, .68vw, 8.5px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--muted);
  opacity: .85;
}

.press-log__topline-voice,
.press-log__topline-mark {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.3vw, 17.5px);
  letter-spacing: -.005em;
  color: var(--paper);
  text-transform: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.press-log__topline-voice em { font-style: italic; }
.press-log__topline-mark em { font-style: italic; }

.press-log__topline-voice--quiet { color: var(--blue); }
.press-log__topline-voice--human { color: var(--coral); }
.press-log__topline-voice--bold { color: var(--acid); }

.press-log__topline-voice-letter {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: currentColor;
  font-style: normal;
  font-family: Georgia, serif;
  font-size: clamp(11px, .98vw, 13px);
  letter-spacing: 0;
  background: rgba(14, 18, 28, .55);
  transform: translateY(2px);
}

.press-log__topline-mark-glyph {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid var(--mark-tone, var(--coral));
  border-radius: 50%;
  color: var(--mark-tone, var(--coral));
  font-style: italic;
  font-family: Georgia, serif;
  font-size: clamp(12px, 1.05vw, 14px);
  background: rgba(14, 18, 28, .55);
  transform: translateY(2px);
}

.press-log__topline-face {
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9px);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
  opacity: .78;
}

.press-log__topline-date {
  font-style: italic;
  font-family: var(--serif);
  font-size: clamp(14px, 1.3vw, 17.5px);
  letter-spacing: -.005em;
  color: var(--paper);
  text-transform: none;
}

.press-log__topline-rule {
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 22%, var(--line) 78%, transparent);
  align-self: stretch;
}

.press-log__timeline {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  row-gap: 10px;
  padding: clamp(10px, 1.4vw, 16px) 0;
}

.press-log__timeline-rule {
  display: block;
  width: 100%;
  height: 8px;
  color: var(--press-log-tone);
  opacity: .65;
}

.press-log__timeline-rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.1s var(--ease-out);
}

.press-log.is-revealed .press-log__timeline-rule-stroke {
  stroke-dashoffset: 0;
}

.press-log__timeline-marks {
  position: relative;
  height: 22px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.press-log__timeline-mark {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  color: var(--press-log-tone);
  pointer-events: none;
}

.press-log__timeline-mark-bead {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 1.4px solid currentColor;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(14, 18, 28, .9);
  opacity: .85;
  transition: transform .55s var(--ease-spring);
}

.press-log__timeline-mark.is-latest .press-log__timeline-mark-bead {
  transform: scale(1.35);
  animation: ribbonBeadPulse 2.4s var(--ease) infinite;
}

.press-log__timeline-mark--pull {
  color: var(--paper);
}

.press-log__timeline-mark--voice-quiet { color: var(--blue); }
.press-log__timeline-mark--voice-human { color: var(--coral); }
.press-log__timeline-mark--voice-bold { color: var(--acid); }
.press-log__timeline-mark--word-m3 { color: var(--acid); }
.press-log__timeline-mark--word-good { color: var(--coral); }
.press-log__timeline-mark--word-yet { color: var(--blue); }

.press-log__timeline-mark-splash {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid currentColor;
  transform: translate(-50%, -50%) scale(.4);
  opacity: .8;
  animation: ribbonSplash 1.2s var(--ease-out) forwards;
  pointer-events: none;
}

@keyframes ribbonSplash {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.3); }
  20% { opacity: .9; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(2.4); }
}

@keyframes ribbonBeadPulse {
  0%, 100% { transform: scale(1.35); }
  50% { transform: scale(1.6); }
}

.press-log__timeline-now {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  pointer-events: none;
}

.press-log__timeline-now-bead {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--paper);
  box-shadow:
    0 0 0 2px var(--ink),
    0 0 0 4px rgba(243, 236, 214, .15),
    0 0 14px rgba(243, 236, 214, .32);
  animation: ribbonBeadPulse 2.2s var(--ease) infinite;
}

.press-log__timeline-now--pull .press-log__timeline-now-bead { background: var(--paper); }
.press-log__timeline-now--voice-quiet .press-log__timeline-now-bead { background: var(--blue); box-shadow: 0 0 0 2px var(--ink), 0 0 0 4px rgba(155, 188, 255, .25), 0 0 14px rgba(155, 188, 255, .4); }
.press-log__timeline-now--voice-human .press-log__timeline-now-bead { background: var(--coral); box-shadow: 0 0 0 2px var(--ink), 0 0 0 4px rgba(255, 118, 95, .25), 0 0 14px rgba(255, 118, 95, .4); }
.press-log__timeline-now--voice-bold .press-log__timeline-now-bead { background: var(--acid); box-shadow: 0 0 0 2px var(--ink), 0 0 0 4px rgba(216, 240, 106, .28), 0 0 14px rgba(216, 240, 106, .45); }
.press-log__timeline-now--word-m3 .press-log__timeline-now-bead { background: var(--acid); }
.press-log__timeline-now--word-good .press-log__timeline-now-bead { background: var(--coral); }
.press-log__timeline-now--word-yet .press-log__timeline-now-bead { background: var(--blue); }

.press-log__timeline-now-tail {
  position: absolute;
  left: 50%;
  bottom: -10px;
  width: 1px;
  height: 10px;
  background: currentColor;
  color: var(--press-log-tone);
  opacity: .35;
}

.press-log__timeline-meta {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.2vw, 14px);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9px);
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--muted);
}

.press-log__timeline-meta-cell {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.press-log__timeline-meta-cell--lead { justify-self: start; }
.press-log__timeline-meta-cell--trail { justify-self: end; }

.press-log__timeline-meta-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  opacity: .85;
}

.press-log__timeline-meta-dot--trail {
  background: var(--press-log-tone);
}

.press-log__timeline-meta-key { opacity: .8; }

.press-log__timeline-meta-tag {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
}

.press-log__timeline-meta-rule {
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 14%, var(--line) 86%, transparent);
  opacity: .65;
}

.press-log__shelves {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(14px, 1.8vw, 22px);
}

.press-log__shelf {
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  row-gap: clamp(8px, 1.2vw, 14px);
  padding: clamp(10px, 1.4vw, 14px) clamp(12px, 1.6vw, 18px);
  border: 1px solid var(--line-soft);
  border-top-width: 2px;
  background: rgba(14, 18, 28, .32);
}

.press-log__shelf--pull { border-top-color: var(--paper); }
.press-log__shelf--word { border-top-color: var(--coral); }
.press-log__shelf--voice { border-top-color: var(--blue); }

.press-log__shelf-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  column-gap: 8px;
}

.press-log__shelf-rule {
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 18%, var(--line) 82%, transparent);
}

.press-log__shelf-rule--end {
  background: linear-gradient(to left, transparent, var(--line) 18%, var(--line) 82%, transparent);
}

.press-log__shelf-tag {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  font-family: var(--mono);
  font-size: clamp(7.5px, .68vw, 8.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}

.press-log__shelf-eyebrow {
  font-style: italic;
  font-family: var(--serif);
  font-size: clamp(10.5px, .95vw, 12px);
  letter-spacing: .01em;
  text-transform: none;
  color: var(--paper);
  opacity: .9;
}

.press-log__shelf-label {
  font-style: normal;
  font-family: var(--mono);
  color: var(--paper);
  font-size: clamp(7.5px, .68vw, 8.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .85;
}

.press-log__shelf-count {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 9px;
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9px);
  color: var(--paper);
  background: rgba(14, 18, 28, .55);
  font-style: normal;
  letter-spacing: 0;
}

.press-log__shelf-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  row-gap: clamp(6px, .9vw, 10px);
}

.press-log__shelf-row {
  position: relative;
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  align-items: center;
  column-gap: clamp(8px, 1vw, 12px);
  padding: 6px 0;
  border-bottom: 1px dashed var(--line-soft);
  font-family: var(--serif);
  font-size: clamp(12.5px, 1.1vw, 14px);
  letter-spacing: -.005em;
  color: var(--paper);
  animation: ribbonRowIn .5s var(--ease-out) backwards;
}

.press-log__shelf-row:last-child { border-bottom: 0; }

.press-log__shelf-row--pull { color: var(--paper); }
.press-log__shelf-row--voice-quiet { color: var(--blue); }
.press-log__shelf-row--voice-human { color: var(--coral); }
.press-log__shelf-row--voice-bold { color: var(--acid); }
.press-log__shelf-row--word-m3 { color: var(--acid); }
.press-log__shelf-row--word-good { color: var(--coral); }
.press-log__shelf-row--word-yet { color: var(--blue); }

@keyframes ribbonRowIn {
  from { opacity: 0; transform: translateX(6px); }
  to { opacity: 1; transform: translateX(0); }
}

.press-log__shelf-index {
  font-family: var(--mono);
  font-size: clamp(7.5px, .7vw, 8.5px);
  letter-spacing: .18em;
  color: currentColor;
  opacity: .65;
}

.press-log__shelf-glyph {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  color: var(--shelf-tone, currentColor);
  opacity: .9;
}

.press-log__shelf-glyph svg { display: block; width: 100%; height: 100%; }

.press-log__shelf-copy {
  display: grid;
  row-gap: 2px;
  min-width: 0;
}

.press-log__shelf-line {
  font-style: italic;
  font-family: var(--serif);
  font-size: clamp(12.5px, 1.1vw, 14px);
  letter-spacing: -.005em;
  color: var(--paper);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.press-log__shelf-line em { font-style: italic; }

.press-log__shelf-letter {
  font-style: normal;
  font-family: Georgia, serif;
  font-size: clamp(13px, 1.18vw, 15px);
  letter-spacing: 0;
  color: currentColor;
  margin: 0 2px;
}

.press-log__shelf-from {
  font-family: var(--mono);
  font-size: clamp(7.5px, .68vw, 8.5px);
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--muted);
  opacity: .75;
}

.press-log__shelf-tail {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: currentColor;
}

.press-log__tail-rule {
  width: 18px;
  height: 1px;
  background: linear-gradient(to right, currentColor, transparent);
  opacity: .6;
}

.press-log__tail-bead {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .8;
}

.press-log__shelf-empty {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  margin: 0;
  padding: 4px 0;
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
  opacity: .78;
}

.press-log__empty-mark {
  font-style: italic;
  font-family: Georgia, serif;
  font-size: clamp(13px, 1.2vw, 15px);
  letter-spacing: 0;
  text-transform: none;
  color: var(--paper);
  opacity: .7;
}

.press-log__foot {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  row-gap: clamp(8px, 1.1vw, 12px);
  padding: clamp(10px, 1.4vw, 14px) 0 0;
  border-top: 1px dashed var(--line);
}

.press-log__foot-rule {
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 18%, var(--line) 82%, transparent);
}

.press-log__foot-rule--trail {
  background: linear-gradient(to left, transparent, var(--line) 18%, var(--line) 82%, transparent);
}

.press-log__foot-row {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) auto minmax(0, 1.4fr) auto minmax(0, 1fr);
  align-items: center;
  column-gap: clamp(10px, 1.2vw, 16px);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press-log__foot-cell {
  display: grid;
  row-gap: 4px;
  min-width: 0;
}

.press-log__foot-rule-cell {
  width: 1px;
  height: 22px;
  background: linear-gradient(to bottom, transparent, var(--line) 18%, var(--line) 82%, transparent);
  align-self: center;
}

.press-log__foot-cell-key {
  color: var(--muted);
  font-size: clamp(7.5px, .68vw, 8.5px);
  opacity: .85;
}

.press-log__foot-cell-value {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.18vw, 15px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.press-log__foot-num {
  font-style: normal;
  font-family: var(--mono);
  font-size: clamp(13px, 1.18vw, 15px);
  letter-spacing: 0;
  color: var(--press-log-tone);
}

.press-log__foot-num--soft { color: var(--paper); }

.press-log__foot-suffix {
  font-style: italic;
  font-family: var(--serif);
  font-size: clamp(12.5px, 1.1vw, 14px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
}

.press-log__foot-dot {
  color: var(--ink-mist);
  margin: 0 2px;
}

.press-log__pencil {
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  width: clamp(160px, 22vw, 260px);
  height: 18px;
  color: var(--press-log-tone);
  opacity: .6;
  pointer-events: none;
}

.press-log__pencil-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.4s var(--ease-out);
}

.press-log.is-revealed .press-log__pencil-stroke { stroke-dashoffset: 0; }

@media (max-width: 880px) {
  .press-log__shelves {
    grid-template-columns: minmax(0, 1fr);
  }

  .press-log__topline {
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    grid-template-rows: auto auto;
    row-gap: clamp(10px, 1.4vw, 14px);
  }

  .press-log__topline-rule {
    display: none;
  }

  .press-log__topline-cell--date {
    grid-column: 1 / -1;
  }

  .press-log__foot-row {
    grid-template-columns: minmax(0, 1fr);
    row-gap: clamp(8px, 1.2vw, 12px);
  }

  .press-log__foot-rule-cell {
    display: none;
  }
}

@media (max-width: 540px) {
  .press-log {
    padding: clamp(14px, 4vw, 22px) clamp(12px, 3.6vw, 18px);
  }

  .press-log__head-title {
    font-size: 12px;
  }

  .press-log__topline {
    padding: clamp(8px, 2vw, 12px) clamp(10px, 2.4vw, 14px);
  }

  .press-log__shelf-row {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .press-log__shelf-glyph {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-log,
  .press-log__shelf-row,
  .press-log__timeline-mark.is-latest .press-log__timeline-mark-bead,
  .press-log__timeline-now-bead {
    animation: none !important;
    transition: none !important;
    transform: none !important;
  }

  .press-log__timeline-mark-splash { display: none !important; }
  .press-log__timeline-rule-stroke,
  .press-log__pencil-stroke { stroke-dashoffset: 0 !important; }
}

/* ────────────────────────────────────────────────────────────
   DAY SHEET · folio iii· — a working almanac: a clock face,
   the week's calendar with today marked, the day's record on
   the press, and a quietly rotating pull quote from the page's
   own marginalia
   ──────────────────────────────────────────────────────────── */

.day-sheet {
  position: relative;
  padding: clamp(96px, 12vw, 150px) 0 clamp(48px, 7vw, 96px);
}

.day-sheet__sheet {
  position: relative;
  display: grid;
  gap: clamp(28px, 3.4vw, 44px);
  padding: clamp(40px, 5vw, 70px) clamp(28px, 4vw, 64px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 96% 6%, rgba(91, 121, 203, .12), transparent 32rem),
    radial-gradient(circle at 4% 96%, rgba(216, 255, 106, .05), transparent 28rem),
    linear-gradient(180deg, rgba(22, 26, 38, .55), rgba(12, 16, 26, .68));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .05),
    0 36px 96px -38px rgba(0, 0, 0, .6);
}

.day-sheet__sheet::before {
  position: absolute;
  inset: 9px;
  border: 1px dashed rgba(146, 186, 255, .07);
  pointer-events: none;
  content: '';
}

.day-sheet__plate {
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translate(-50%, -55%);
  padding: 4px 14px;
  border: 1px solid var(--line);
  border-top: 0;
  background: var(--night);
  color: var(--acid);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
  white-space: nowrap;
  z-index: 2;
}

.day-sheet__crop {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 0 solid var(--acid);
  pointer-events: none;
  opacity: .55;
}

.day-sheet__crop--tl { top: -1px; left: -1px; border-top-width: 1px; border-left-width: 1px; }
.day-sheet__crop--tr { top: -1px; right: -1px; border-top-width: 1px; border-right-width: 1px; }
.day-sheet__crop--bl { bottom: -1px; left: -1px; border-bottom-width: 1px; border-left-width: 1px; }
.day-sheet__crop--br { bottom: -1px; right: -1px; border-bottom-width: 1px; border-right-width: 1px; }

.day-sheet__rule {
  position: absolute;
  left: clamp(28px, 4vw, 64px);
  right: clamp(28px, 4vw, 64px);
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--line) 14%, var(--line) 86%, transparent);
  pointer-events: none;
}

.day-sheet__rule--top { top: clamp(70px, 9vw, 110px); opacity: .55; }
.day-sheet__rule--bottom { bottom: clamp(50px, 6vw, 80px); opacity: .35; }

.day-sheet__head {
  position: relative;
  max-width: 820px;
  padding-top: clamp(8px, 1.4vw, 18px);
}

.day-sheet__title {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: clamp(8px, 1.2vw, 16px);
  margin: 22px 0 18px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(2.4rem, 5.2vw, 5.4rem);
  font-weight: 400;
  font-style: italic;
  letter-spacing: -.06em;
  line-height: .94;
  text-wrap: balance;
}

.day-sheet__title-set {
  color: var(--muted);
  font-style: normal;
  font-family: var(--mono);
  font-size: clamp(10px, 1vw, 12px);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.day-sheet__title-date {
  font-style: italic;
  color: var(--paper);
}

.day-sheet__title-year {
  color: var(--coral);
  font-style: italic;
  font-size: clamp(1.4rem, 2.4vw, 2.6rem);
  letter-spacing: -.02em;
}

.day-sheet__lede {
  max-width: 56ch;
}

.day-sheet__layout {
  position: relative;
  display: grid;
  grid-template-columns: minmax(220px, 280px) minmax(0, 1fr) minmax(220px, 280px);
  grid-template-areas:
    'clock week record'
    'quote quote quote';
  gap: clamp(22px, 2.6vw, 36px);
  align-items: stretch;
}

@media (max-width: 980px) {
  .day-sheet__layout {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      'clock week'
      'record record'
      'quote quote';
  }
}

@media (max-width: 620px) {
  .day-sheet__layout {
    grid-template-columns: 1fr;
    grid-template-areas:
      'clock'
      'week'
      'record'
      'quote';
  }
}

.day-sheet__clock {
  grid-area: clock;
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin: 0;
  padding: 22px 18px 16px;
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 50% 18%, rgba(146, 186, 255, .08), transparent 60%),
    linear-gradient(180deg, rgba(28, 36, 52, .55), rgba(14, 20, 32, .72));
  align-items: center;
}

.day-sheet__clock-svg {
  width: clamp(160px, 14vw, 220px);
  height: auto;
  color: var(--paper);
}

.day-sheet__clock-hand {
  transform-origin: 100px 100px;
  transition: transform .6s var(--ease-out);
}

.day-sheet__clock-hand--second {
  transition: transform .15s linear;
}

.day-sheet__clock-caption {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
}

.day-sheet__clock-tag {
  color: var(--muted);
  font-family: var(--mono);
  font-style: normal;
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.day-sheet__clock-name {
  font-size: clamp(14px, 1.4vw, 17px);
  color: var(--paper);
}

.day-sheet__week {
  grid-area: week;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 22px clamp(16px, 2.2vw, 24px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 100% 0%, rgba(216, 255, 106, .04), transparent 60%),
    linear-gradient(180deg, rgba(28, 36, 52, .5), rgba(14, 20, 32, .7));
}

.day-sheet__week-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

.day-sheet__week-eyebrow {
  color: var(--acid);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.day-sheet__week-rule {
  flex: 1;
  height: 1px;
  background: var(--line);
}

.day-sheet__week-folio {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
