/* ────────────────────────────────────────────────────────────
   WATERMARK · a quiet printer's mark that lives behind the
   page, layered with an italic line that cycles the editor's
   whisper. Fades as the reader descends the page.
   ──────────────────────────────────────────────────────────── */

.watermark {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  display: grid;
  place-items: center;
  color: var(--paper);
  transition: opacity .4s linear;
}

.watermark__seal {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -52%);
  width: clamp(360px, 64vw, 880px);
  height: auto;
  opacity: .55;
  mix-blend-mode: screen;
}

.watermark__line {
  position: absolute;
  top: 78%;
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  gap: clamp(14px, 2vw, 24px);
  width: clamp(320px, 50vw, 540px);
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.2vw, 17px);
  letter-spacing: -.005em;
  line-height: 1;
  text-align: center;
  animation: watermarkFade 1.4s var(--ease-out);
}

.watermark__line-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor 30%, currentColor 70%, transparent);
  opacity: .5;
}

.watermark__line-text {
  white-space: nowrap;
  opacity: .85;
}

@keyframes watermarkFade {
  from { opacity: 0; transform: translate(-50%, -3px); }
  to { opacity: .85; transform: translate(-50%, 0); }
}

@media (prefers-reduced-motion: reduce) {
  .watermark__line { animation: none; }
}

@media (max-width: 720px) {
  .watermark__seal {
    width: clamp(280px, 110vw, 460px);
    opacity: .42;
  }

  .watermark__line {
    top: 82%;
    width: 80vw;
    font-size: 12px;
  }
}

/* ────────────────────────────────────────────────────────────
   PROOF CARD · the editor's note that unfurls beneath the
   hero title, keyed to the marked word currently in hand. The
   card transitions cleanly between selections.
   ──────────────────────────────────────────────────────────── */

.proof-card {
  --proof-ink: var(--coral);
  position: relative;
  display: grid;
  gap: 0;
  width: min(100%, 680px);
  margin: 6px auto 0;
  padding: clamp(18px, 2vw, 26px) clamp(20px, 2.4vw, 32px) clamp(20px, 2.4vw, 30px);
  border: 1px solid rgba(146, 186, 255, .14);
  background:
    radial-gradient(circle at 92% 0%, color-mix(in srgb, var(--proof-ink) 10%, transparent), transparent 50%),
    radial-gradient(circle at 4% 100%, color-mix(in srgb, var(--proof-ink) 6%, transparent), transparent 56%),
    linear-gradient(180deg, rgba(28, 36, 52, .6), rgba(14, 20, 32, .72));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .05),
    0 24px 60px -28px rgba(0, 0, 0, .55);
  color: var(--paper);
  text-align: left;
  isolation: isolate;
  animation: proofCardIn .65s var(--ease-out);
  transform-origin: top center;
}

.proof-card::before {
  position: absolute;
  inset: 6px;
  border: 1px dashed rgba(146, 186, 255, .07);
  pointer-events: none;
  content: '';
}

.proof-card__corner {
  position: absolute;
  width: 14px;
  height: 14px;
  border: 0 solid var(--proof-ink);
  opacity: .55;
  pointer-events: none;
}

.proof-card__corner--tl { top: -1px; left: -1px; border-top-width: 1px; border-left-width: 1px; }
.proof-card__corner--tr { top: -1px; right: -1px; border-top-width: 1px; border-right-width: 1px; }
.proof-card__corner--bl { bottom: -1px; left: -1px; border-bottom-width: 1px; border-left-width: 1px; }
.proof-card__corner--br { bottom: -1px; right: -1px; border-bottom-width: 1px; border-right-width: 1px; }

.proof-card__pin {
  position: absolute;
  top: -8px;
  right: clamp(28px, 4vw, 56px);
  width: 22px;
  height: 22px;
  color: var(--proof-ink);
  filter: drop-shadow(0 4px 6px rgba(0, 0, 0, .35));
  transform: rotate(-6deg);
  z-index: 2;
}

.proof-card__plate {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 0 0 clamp(12px, 1.4vw, 18px);
  color: var(--proof-ink);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.proof-card__plate-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor 28%, currentColor 72%, transparent);
  opacity: .55;
}

.proof-card__plate-tag {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
  opacity: .85;
}

.proof-card__plate-tag-mark {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--proof-ink) 18%, transparent);
}

.proof-card__inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, auto);
  grid-template-areas:
    'type glyph'
    'body body'
    'margin margin';
  column-gap: clamp(16px, 2vw, 24px);
  row-gap: clamp(14px, 1.6vw, 20px);
  align-items: start;
}

.proof-card__type {
  grid-area: type;
  display: flex;
  align-items: baseline;
  gap: clamp(10px, 1.4vw, 16px);
  color: var(--paper);
}

.proof-card__type-linenum {
  display: inline-grid;
  width: 26px;
  height: 26px;
  place-items: center;
  border: 1px solid var(--proof-ink);
  border-radius: 50%;
  color: var(--proof-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  letter-spacing: -.02em;
  opacity: .85;
}

.proof-card__type-word {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(28px, 3vw, 40px);
  letter-spacing: -.04em;
  line-height: 1;
  color: var(--paper);
  text-shadow:
    0 1px 0 rgba(0, 0, 0, .35),
    0 4px 16px rgba(0, 0, 0, .3);
}

.proof-card__type-glyph {
  grid-area: glyph;
  display: block;
  width: clamp(54px, 5vw, 72px);
  height: clamp(54px, 5vw, 72px);
  color: var(--proof-ink);
  opacity: .85;
  filter: drop-shadow(0 2px 0 rgba(0, 0, 0, .2));
}

.proof-card__body {
  grid-area: body;
  display: grid;
  gap: 8px;
  padding: clamp(10px, 1.2vw, 14px) 0 0;
  border-top: 1px solid rgba(146, 186, 255, .08);
}

.proof-card__hand {
  margin: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(14.5px, 1.4vw, 17px);
  font-style: italic;
  line-height: 1.45;
  text-wrap: pretty;
}

.proof-card__pencil {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin: 0;
  color: var(--proof-ink);
  font-family: var(--serif);
  font-size: clamp(13.5px, 1.25vw, 15.5px);
  font-style: italic;
  letter-spacing: -.005em;
  line-height: 1.35;
}

.proof-card__pencil-mark {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--mono);
  font-style: normal;
  font-size: 11px;
  flex: 0 0 auto;
  opacity: .8;
}

.proof-card__margin {
  grid-area: margin;
  display: grid;
  grid-template-columns: minmax(0, auto) minmax(0, 1fr);
  align-items: start;
  gap: 14px;
  padding-top: clamp(8px, 1vw, 12px);
  border-top: 1px dotted rgba(146, 186, 255, .12);
}

.proof-card__margin-thread {
  display: block;
  width: 6px;
  height: 100%;
  min-height: 36px;
  color: var(--proof-ink);
  opacity: .65;
}

.proof-card__margin-note {
  margin: 0;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12.5px, 1.15vw, 14px);
  line-height: 1.45;
  letter-spacing: -.005em;
  text-transform: lowercase;
}

.proof-card__foot {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  margin: clamp(14px, 1.6vw, 20px) 0 0;
  padding-top: clamp(10px, 1.2vw, 14px);
  border-top: 1px solid rgba(146, 186, 255, .08);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.proof-card__foot-mark {
  display: block;
  width: clamp(60px, 8vw, 90px);
  height: 12px;
  color: var(--proof-ink);
  opacity: .75;
}

.proof-card__foot-meta {
  color: var(--muted);
}

.proof-card__foot-meta em {
  color: var(--proof-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: -.01em;
  text-transform: lowercase;
}

.proof-card__foot-letter {
  display: inline-grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: var(--proof-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: 0;
  opacity: .9;
}

@keyframes proofCardIn {
  0% { opacity: 0; transform: rotateX(-3deg) translateY(8px); filter: brightness(.85); }
  60% { opacity: 1; filter: brightness(.95); }
  100% { opacity: 1; transform: rotateX(0) translateY(0); filter: brightness(1); }
}

@media (prefers-reduced-motion: reduce) {
  .proof-card { animation: none; }
}

@media (max-width: 720px) {
  .proof-card {
    padding: 16px 18px 18px;
    border-radius: 1px;
  }

  .proof-card__inner {
    grid-template-columns: 1fr;
    grid-template-areas:
      'type'
      'glyph'
      'body'
      'margin';
  }

  .proof-card__type-glyph {
    width: 48px;
    height: 48px;
    justify-self: end;
    margin-top: -36px;
  }

  .proof-card__type-word {
    font-size: 28px;
  }

  .proof-card__foot {
    grid-template-columns: 1fr auto;
  }

  .proof-card__foot-mark {
    display: none;
  }
}


/* ────────────────────────────────────────────────────────────
   FOLIO SEAL · the wax seal that anchors the broadside
   ──────────────────────────────────────────────────────────── */

.folio-seal {
  display: block;
  color: var(--coral);
  filter: drop-shadow(0 16px 28px rgba(0, 0, 0, .42));
  transition: color .55s var(--ease), transform .8s var(--ease-spring);
}

.app--voice-quiet .folio-seal { color: var(--blue); }
.app--voice-human .folio-seal { color: var(--coral); }
.app--voice-bold .folio-seal { color: var(--acid); }

.folio-seal__halo {
  transform-origin: center;
  animation: sealHaloSpin 60s linear infinite;
}

@keyframes sealHaloSpin {
  to { transform: rotate(360deg); }
}

.folio-seal__disc {
  transform-origin: center;
  animation: sealPressIn .9s var(--ease-spring) .25s backwards;
}

@keyframes sealPressIn {
  0% { opacity: 0; transform: scale(.5) rotate(-14deg); }
  60% { opacity: 1; transform: scale(1.04) rotate(2deg); }
  100% { opacity: 1; transform: scale(1) rotate(0); }
}

.folio-seal__arc-top,
.folio-seal__arc-bot {
  letter-spacing: .35em;
}

.folio-seal__folio {
  transition: opacity .55s var(--ease);
}

.folio-seal__drip {
  transform-origin: 158px 96px;
  animation: sealDripStretch 3.6s var(--ease) 1.5s infinite;
}

@keyframes sealDripStretch {
  0%, 100% { opacity: .65; transform: translateY(0); }
  50% { opacity: .9; transform: translateY(2px); }
}

.folio-seal__drip-bead {
  transform-origin: 160px 134px;
  animation: sealDripPulse 2.4s var(--ease) 1.6s infinite;
}

@keyframes sealDripPulse {
  0%, 100% { transform: scale(1); opacity: .85; }
  50% { transform: scale(1.18); opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .folio-seal__halo,
  .folio-seal__drip,
  .folio-seal__drip-bead {
    animation: none;
  }
  .folio-seal__disc {
    animation: none;
  }
}


/* ────────────────────────────────────────────────────────────
   HERO COMPOSITION · refined for iteration 227
   ──────────────────────────────────────────────────────────── */

.hero__seal {
  position: absolute;
  top: clamp(8px, 1.4vw, 26px);
  right: clamp(14px, 2.4vw, 56px);
  width: clamp(96px, 13vw, 168px);
  height: auto;
  z-index: 4;
  opacity: 0;
  animation: sealPressIn 1s var(--ease-spring) .15s backwards;
  pointer-events: none;
}

.hero__corner-tab {
  position: absolute;
  top: 32px;
  left: 38px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .26em;
  text-transform: uppercase;
  z-index: 3;
  opacity: 0;
  animation: regMarkIn .75s var(--ease-out) .55s forwards;
}

.hero__corner-tab-line {
  width: clamp(20px, 4vw, 56px);
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor);
  opacity: .65;
}

.hero__corner-tab-line:last-child {
  background: linear-gradient(to left, transparent, currentColor);
}

.hero__corner-tab-tag {
  white-space: nowrap;
}

.app--voice-quiet .hero__corner-tab { color: var(--blue); }
.app--voice-human .hero__corner-tab { color: var(--coral); }
.app--voice-bold .hero__corner-tab { color: var(--acid); }

.hero__slip {
  position: absolute;
  left: clamp(28px, 5vw, 88px);
  right: clamp(28px, 5vw, 88px);
  bottom: clamp(20px, 2.6vw, 38px);
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  z-index: 3;
  color: var(--ink-mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .9vw, 10px);
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: 0;
  animation: regMarkIn .85s var(--ease-out) 1s forwards;
  pointer-events: none;
}

.hero__slip-rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor 30%, currentColor 70%, transparent);
  opacity: .35;
}

.hero__slip-body {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  flex: 0 0 auto;
  white-space: nowrap;
}

.hero__slip-body em {
  color: var(--paper);
  font-style: normal;
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(10px, 1.05vw, 12px);
  letter-spacing: .08em;
  text-transform: lowercase;
}

.app--voice-quiet .hero__slip em { color: var(--blue); }
.app--voice-human .hero__slip em { color: var(--coral); }
.app--voice-bold .hero__slip em { color: var(--acid); }

.hero__slip-dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: currentColor;
  opacity: .55;
}

@media (max-width: 720px) {
  .hero__seal {
    top: 12px;
    right: 14px;
    width: 84px;
    opacity: .82;
  }

  .hero__corner-tab {
    top: 18px;
    left: 18px;
    font-size: 8px;
    letter-spacing: .22em;
  }

  .hero__corner-tab-line {
    width: 14px;
  }

  .hero__slip {
    font-size: 8px;
    letter-spacing: .16em;
    bottom: 18px;
    left: 18px;
    right: 18px;
    gap: 8px;
  }

  .hero__slip-body {
    flex-wrap: wrap;
    row-gap: 4px;
    justify-content: center;
  }
}

@media (max-width: 480px) {
  .hero__seal {
    width: 64px;
    top: 8px;
    right: 10px;
  }

  .hero__corner-tab-tag {
    display: none;
  }

  .hero__corner-tab-line {
    width: 28px;
  }
}


/* ────────────────────────────────────────────────────────────
   PRESS SIGNATURE · a single printer's mark that closes a folio
   and ties the page together. Two variants: inline (sits in the
   flow) and footer (lives at the page foot, before the colophon).
   ──────────────────────────────────────────────────────────── */

.press-signature {
  --sig-quiet: var(--blue);
  --sig-human: var(--coral);
  --sig-bold: var(--acid);
  --sig-voice: var(--sig-quiet);
  --sig-paper: rgba(243, 236, 214, .04);
  --sig-ink: var(--paper);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(16px, 2.4vw, 28px);
  width: min(100%, 1120px);
  margin: clamp(40px, 6vw, 80px) auto clamp(28px, 3.4vw, 44px);
  padding: 14px clamp(14px, 1.8vw, 22px);
  color: var(--sig-voice);
  isolation: isolate;
}

.press-signature--quiet { --sig-voice: var(--sig-quiet); }
.press-signature--human { --sig-voice: var(--sig-human); }
.press-signature--bold  { --sig-voice: var(--sig-bold); }

.press-signature::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: 2px;
  background:
    linear-gradient(180deg, transparent 0%, rgba(243, 236, 214, .02) 50%, transparent 100%);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  pointer-events: none;
}

.press-signature::after {
  content: '';
  position: absolute;
  left: clamp(14px, 1.8vw, 22px);
  right: clamp(14px, 1.8vw, 22px);
  top: 50%;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor 28%, currentColor 72%, transparent);
  opacity: .18;
  z-index: -1;
  pointer-events: none;
}

.press-signature__rule {
  display: block;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor);
  opacity: .35;
  transform-origin: left center;
  animation: sigRuleIn 1.1s var(--ease-out) .25s backwards;
}

.press-signature__rule--right {
  background: linear-gradient(to left, transparent, currentColor);
  transform-origin: right center;
}

@keyframes sigRuleIn {
  0% { opacity: 0; transform: scaleX(.4); }
  100% { opacity: .35; transform: scaleX(1); }
}

.press-signature__core {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(12px, 1.6vw, 18px);
  padding: 6px clamp(14px, 1.8vw, 22px);
  background: linear-gradient(180deg, rgba(243, 236, 214, .025), rgba(14, 18, 28, .35));
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  box-shadow:
    inset 0 0 0 1px rgba(14, 18, 28, .32),
    0 14px 30px -18px rgba(0, 0, 0, .55);
  animation: sigCoreIn 1.05s var(--ease-out) .05s backwards;
}

@keyframes sigCoreIn {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

.press-signature__seal {
  display: inline-grid;
  place-items: center;
  width: clamp(44px, 4.4vw, 56px);
  height: clamp(44px, 4.4vw, 56px);
  color: currentColor;
  filter: drop-shadow(0 6px 12px rgba(0, 0, 0, .32));
  animation: sigSealIn 1.15s var(--ease-spring) .2s backwards;
}

.press-signature__seal svg {
  display: block;
  width: 100%;
  height: 100%;
}

@keyframes sigSealIn {
  0% { opacity: 0; transform: rotate(-22deg) scale(.6); }
  60% { opacity: 1; transform: rotate(6deg) scale(1.06); }
  100% { opacity: 1; transform: rotate(0) scale(1); }
}

.press-signature__text {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.press-signature__row {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: clamp(6px, .8vw, 10px);
  font-family: var(--mono);
  font-size: clamp(8px, .78vw, 9.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  line-height: 1.25;
}

.press-signature__row--head {
  color: var(--paper);
  font-weight: 600;
  opacity: .88;
}

.press-signature__row--sub {
  color: var(--ink-mist);
  font-weight: 500;
  opacity: .82;
}

.press-signature__mark {
  color: var(--paper);
  letter-spacing: .32em;
  font-weight: 700;
}

.press-signature__folio {
  color: currentColor;
  letter-spacing: .28em;
}

.press-signature__title {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  letter-spacing: .02em;
  text-transform: none;
  font-size: clamp(11px, 1vw, 13px);
  opacity: .9;
}

.press-signature__dot {
  color: var(--ink-mist);
  opacity: .5;
}

.press-signature__voice,
.press-signature__word {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.press-signature__voice-letter {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  opacity: .95;
}

.press-signature__voice-name,
.press-signature__word-name {
  font-family: var(--serif);
  font-style: italic;
  letter-spacing: .04em;
  text-transform: none;
  font-size: clamp(11px, 1vw, 12.5px);
  color: var(--paper);
  opacity: .9;
}

.press-signature__word-mark {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .22em;
  font-weight: 700;
  padding: 2px 5px;
  border: 1px solid currentColor;
  border-radius: 1px;
  text-transform: uppercase;
}

.press-signature__date {
  font-family: var(--serif);
  font-style: italic;
  letter-spacing: .02em;
  text-transform: none;
  font-size: clamp(11px, 1vw, 12.5px);
  color: var(--paper);
  opacity: .82;
}

.press-signature__sweep {
  position: absolute;
  left: clamp(80px, 9vw, 130px);
  right: clamp(80px, 9vw, 130px);
  bottom: -8px;
  height: 22px;
  color: currentColor;
  opacity: 0;
  pointer-events: none;
  animation: sigSweepIn .9s var(--ease-out) .85s forwards;
}

@keyframes sigSweepIn {
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: .55; transform: translateY(0); }
}

.press-signature__sweep-stroke {
  stroke-dasharray: 360 360;
  animation: sigSweepDraw 1.4s var(--ease-out) .9s backwards;
}

@keyframes sigSweepDraw {
  0% { stroke-dashoffset: 360; }
  100% { stroke-dashoffset: 0; }
}

.press-signature__sweep-dot {
  opacity: 0;
  animation: sigSweepDotIn .55s var(--ease-out) 2.05s forwards;
}

@keyframes sigSweepDotIn {
  0% { opacity: 0; transform: scale(.4); }
  100% { opacity: .9; transform: scale(1); }
}

.press-signature--footer {
  margin: clamp(48px, 7vw, 96px) auto clamp(32px, 4vw, 56px);
  padding-top: 18px;
  padding-bottom: 18px;
}

.press-signature--footer .press-signature__core {
  padding: 8px clamp(18px, 2.4vw, 28px);
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .04), rgba(14, 18, 28, .55));
  box-shadow:
    inset 0 0 0 1px rgba(243, 236, 214, .05),
    0 22px 50px -28px rgba(0, 0, 0, .7);
}

.press-signature--footer .press-signature__seal {
  width: clamp(48px, 4.8vw, 64px);
  height: clamp(48px, 4.8vw, 64px);
}

.press-signature--footer .press-signature__row--head {
  font-size: clamp(9px, .85vw, 10.5px);
}

@media (max-width: 720px) {
  .press-signature {
    grid-template-columns: 1fr;
    gap: 14px;
    text-align: center;
    padding: 12px 14px;
  }

  .press-signature__rule {
    display: none;
  }

  .press-signature__core {
    padding: 8px 12px;
  }

  .press-signature__seal {
    width: 44px;
    height: 44px;
  }

  .press-signature__row {
    justify-content: center;
  }

  .press-signature__row--head,
  .press-signature__row--sub {
    gap: 6px;
    font-size: 8px;
    letter-spacing: .18em;
  }

  .press-signature__sweep {
    left: 20px;
    right: 20px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-signature,
  .press-signature__rule,
  .press-signature__core,
  .press-signature__seal,
  .press-signature__sweep,
  .press-signature__sweep-stroke,
  .press-signature__sweep-dot {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }
}


/* ────────────────────────────────────────────────────────────
   TYPE PLATE · folio v · a single specimen sheet
   ──────────────────────────────────────────────────────────── */

.specimen-plate-section {
  --plate-paper: rgba(243, 236, 214, .04);
}

.type-plate {
  position: relative;
  width: min(100%, 1080px);
  margin: clamp(28px, 4vw, 56px) auto 0;
  padding: clamp(20px, 2.4vw, 36px) clamp(20px, 2.8vw, 44px) clamp(28px, 3.4vw, 48px);
  border: 1px solid var(--line);
  background:
    radial-gradient(ellipse at 50% 0%, rgba(216, 255, 106, .05), transparent 56%),
    radial-gradient(ellipse at 50% 100%, rgba(255, 118, 95, .04), transparent 60%),
    linear-gradient(180deg, rgba(28, 36, 52, .36), rgba(14, 20, 32, .52));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 32px 80px -38px rgba(0, 0, 0, .5);
  overflow: hidden;
  isolation: isolate;
}

.type-plate::before {
  content: '';
  position: absolute;
  inset: 10px;
  border: 1px dashed rgba(146, 186, 255, .06);
  pointer-events: none;
}

.type-plate__head {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  margin: 0 0 clamp(18px, 2vw, 28px);
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.type-plate__head-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor 30%, currentColor 70%, transparent);
  opacity: .45;
}

.app--voice-quiet .type-plate__head,
.app--voice-quiet .type-plate__head-rule { color: var(--blue); }
.app--voice-human .type-plate__head,
.app--voice-human .type-plate__head-rule { color: var(--coral); }
.app--voice-bold .type-plate__head,
.app--voice-bold .type-plate__head-rule { color: var(--acid); }

.type-plate__stack {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: clamp(14px, 1.8vw, 24px);
}

.type-plate__cell {
  position: relative;
}

.type-plate__row {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(8px, 1vw, 14px);
  width: 100%;
  padding: clamp(16px, 2vw, 26px) clamp(16px, 2vw, 26px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 0 0%, rgba(216, 255, 98, .025), transparent 60%),
    var(--plate-paper, rgba(243, 236, 214, .04));
  text-align: left;
  cursor: pointer;
  transition: border-color .55s var(--ease), background .55s var(--ease), transform .55s var(--ease-spring);
  isolation: isolate;
}

.type-plate__row::before,
.type-plate__row::after {
  content: '';
  position: absolute;
  width: 12px;
  height: 12px;
  border: 1px solid currentColor;
  opacity: 0;
  transition: opacity .45s var(--ease);
  pointer-events: none;
}

.type-plate__row::before {
  top: -1px;
  left: -1px;
  border-right: 0;
  border-bottom: 0;
}

.type-plate__row::after {
  bottom: -1px;
  right: -1px;
  border-left: 0;
  border-top: 0;
}

.type-plate__row:hover,
.type-plate__row:focus-visible {
  border-color: currentColor;
  transform: translateY(-2px);
}

.type-plate__row:hover::before,
.type-plate__row:hover::after,
.type-plate__row:focus-visible::before,
.type-plate__row:focus-visible::after,
.type-plate__row.is-active::before,
.type-plate__row.is-active::after {
  opacity: .85;
}

.type-plate__row.is-active {
  border-color: currentColor;
  background:
    radial-gradient(circle at 0 0%, rgba(216, 255, 98, .045), transparent 60%),
    var(--plate-paper, rgba(243, 236, 214, .05));
}

.type-plate__bar {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.type-plate__bar-letter {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: 0;
  color: currentColor;
  transition: background .45s var(--ease), color .45s var(--ease);
}

.type-plate__row:hover .type-plate__bar-letter,
.type-plate__row:focus-visible .type-plate__bar-letter,
.type-plate__row.is-active .type-plate__bar-letter {
  background: currentColor;
  color: var(--night);
}

.type-plate__bar-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, currentColor, transparent);
  opacity: .55;
}

.type-plate__bar-name {
  white-space: nowrap;
}

.type-plate__bar-pip {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  opacity: .7;
  transition: transform .55s var(--ease-spring);
}

.type-plate__row:hover .type-plate__bar-pip,
.type-plate__row:focus-visible .type-plate__bar-pip,
.type-plate__row.is-active .type-plate__bar-pip {
  transform: scale(1.4);
}

.type-plate__display {
  display: block;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(38px, 5.4vw, 76px);
  line-height: .98;
  letter-spacing: -.025em;
  color: var(--plate-ink, var(--paper));
}

.type-plate__display--quiet { color: var(--paper); }
.type-plate__display--human { color: var(--coral); }
.type-plate__display--bold {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 900;
  font-size: clamp(42px, 5.6vw, 80px);
  letter-spacing: -.04em;
  color: var(--acid);
}

.type-plate__body {
  display: block;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(20px, 2.4vw, 32px);
  line-height: 1.04;
  letter-spacing: -.018em;
  color: var(--plate-ink, var(--paper));
  opacity: .9;
}

.type-plate__body--bold {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 900;
  font-size: clamp(22px, 2.6vw, 36px);
  letter-spacing: -.04em;
  color: var(--acid);
  opacity: 1;
}

.type-plate__micro-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: clamp(4px, .6vw, 8px);
}

.type-plate__micro {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(22px, 2.6vw, 36px);
  line-height: 1;
  letter-spacing: -.02em;
  color: var(--plate-ink, var(--paper));
}

.type-plate__micro--bold {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 900;
  font-size: clamp(20px, 2.4vw, 32px);
  letter-spacing: -.04em;
  color: var(--acid);
}

.type-plate__meta {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.type-plate__meta-face {
  font-style: italic;
  font-family: var(--serif);
  font-size: 12px;
  letter-spacing: -.01em;
  text-transform: none;
  color: var(--paper);
  opacity: .8;
}

.type-plate__meta-ink {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.type-plate__meta-swatch {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--plate-swatch);
  box-shadow: 0 0 0 2px rgba(0, 0, 0, .4);
}

.type-plate__rule {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) auto minmax(120px, 1fr);
  align-items: center;
  gap: 14px;
  margin-top: clamp(10px, 1.2vw, 16px);
  color: currentColor;
  opacity: .8;
}

.type-plate__rule svg {
  width: 100%;
  height: 8px;
}

.type-plate__rule-stroke {
  stroke-dashoffset: 100;
  animation: titleRuleDraw 1.4s var(--ease-out) .15s forwards;
}

.type-plate__rule em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.2vw, 16px);
  letter-spacing: -.01em;
  color: var(--paper);
  white-space: nowrap;
  text-transform: none;
}

.type-plate__rule-motto {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: currentColor;
  text-align: right;
  opacity: .7;
}

.type-plate__foot {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  margin: clamp(20px, 2.4vw, 30px) 0 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.type-plate__foot-mark {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor 30%, currentColor 70%, transparent);
  opacity: .45;
}

.type-plate__row--quiet { color: var(--blue); }
.type-plate__row--human { color: var(--coral); }
.type-plate__row--bold { color: var(--acid); }

@media (max-width: 720px) {
  .type-plate {
    padding: 18px 16px 22px;
  }

  .type-plate__display {
    font-size: clamp(32px, 9vw, 48px);
  }

  .type-plate__display--bold {
    font-size: clamp(36px, 9.6vw, 54px);
  }

  .type-plate__body {
    font-size: clamp(18px, 5.2vw, 24px);
  }

  .type-plate__micro {
    font-size: clamp(20px, 5.6vw, 28px);
  }

  .type-plate__rule {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .type-plate__rule-motto {
    text-align: center;
  }

  .type-plate__meta {
    flex-direction: row;
    align-items: center;
    gap: 12px;
  }
}

/* ────────────────────────────────────────────────────────────
   PRESS RIBBON · a typographic rule that binds the page.
   Lives beneath the hero and reappears at the foot of each
   chapter to keep the reader oriented. The line carries the
   title set in the active voice; the four tags show all three
   readings and which one is now.
   ──────────────────────────────────────────────────────────── */

.press-ribbon {
  --ribbon-voice: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(14px, 2.6vw, 32px);
  margin: clamp(20px, 2.4vw, 36px) auto;
  padding: clamp(12px, 1.6vw, 18px) clamp(16px, 2.4vw, 28px);
  max-width: 1200px;
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  color: var(--paper);
  isolation: isolate;
}

.press-ribbon::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% 50%, rgba(243, 236, 214, .025), transparent 65%);
  pointer-events: none;
  z-index: -1;
}

.press-ribbon__rule {
  display: flex;
  align-items: center;
  height: 14px;
  color: var(--paper);
  opacity: .55;
  transition: opacity .5s var(--ease), color .5s var(--ease);
}

.press-ribbon__rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.press-ribbon__rule-stroke {
  stroke-dasharray: 240 240;
  stroke-dashoffset: 240;
  animation: pressRibbonTrace 1.4s var(--ease-out) .25s forwards;
}

.press-ribbon__rule-dot {
  opacity: 0;
  animation: pressRibbonDot .4s var(--ease-spring) 1.5s forwards;
}

.press-ribbon--quiet .press-ribbon__rule { color: var(--blue); opacity: .7; }
.press-ribbon--human .press-ribbon__rule { color: var(--coral); opacity: .7; }
.press-ribbon--bold .press-ribbon__rule { color: var(--acid); opacity: .75; }

.press-ribbon--interlude {
  margin-block: clamp(40px, 5vw, 72px);
  max-width: 1180px;
  background:
    radial-gradient(ellipse at 50% 50%, rgba(243, 236, 214, .04), transparent 70%);
}

.press-ribbon--interlude::before {
  background:
    radial-gradient(ellipse at 50% 50%, rgba(243, 236, 214, .05), transparent 70%);
}

.press-ribbon__core {
  display: flex;
  align-items: center;
  gap: clamp(12px, 1.6vw, 20px);
}

.press-ribbon__slot {
  display: inline-flex;
  align-items: baseline;
  gap: 0;
  font-family: var(--serif);
  font-size: clamp(18px, 1.8vw, 22px);
  color: var(--paper);
  line-height: 1;
}

.press-ribbon__slot-letter {
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.04em;
}

.press-ribbon__slot-letter--sans {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 800;
  letter-spacing: -.07em;
}

.press-ribbon__title {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(15px, 1.45vw, 19px);
  line-height: 1.1;
  letter-spacing: -.018em;
  color: var(--paper);
  white-space: nowrap;
  transition: color .55s var(--ease), font-family .55s var(--ease), letter-spacing .55s var(--ease);
}

.press-ribbon--bold .press-ribbon__title {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 800;
  letter-spacing: -.05em;
  text-transform: uppercase;
  font-size: clamp(13px, 1.25vw, 16px);
}

.press-ribbon--quiet .press-ribbon__title {
  font-family: var(--serif);
  font-style: italic;
  letter-spacing: -.02em;
}

.press-ribbon__title-mark {
  display: inline-flex;
  width: clamp(28px, 3vw, 44px);
  height: 12px;
  color: var(--ribbon-voice);
  opacity: .7;
}

.press-ribbon__title-mark svg {
  width: 100%;
  height: 100%;
}

.press-ribbon__title-stroke {
  stroke-dasharray: 80 80;
  stroke-dashoffset: 80;
  animation: pressRibbonTitleStroke .9s var(--ease-out) .7s forwards;
}

.press-ribbon__title-text {
  position: relative;
  display: inline-block;
  opacity: 0;
  transform: translateY(2px);
  animation: pressRibbonTitleIn .8s var(--ease-out) .85s forwards;
}

.press-ribbon__tags {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .6vw, 8px);
}

.press-ribbon__tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px 3px 5px;
  border: 1px solid currentColor;
  border-radius: 1px;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .16em;
  text-transform: uppercase;
  opacity: .55;
  transition: opacity .4s var(--ease), background .4s var(--ease), color .4s var(--ease);
}

.press-ribbon__tag-letter {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: currentColor;
  color: var(--night);
  font-family: var(--serif);
  font-style: italic;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0;
}

.press-ribbon__tag-text {
  display: inline-block;
  color: currentColor;
  font-style: normal;
}

.press-ribbon__tag--quiet { color: var(--blue); }
.press-ribbon__tag--human { color: var(--coral); }
.press-ribbon__tag--bold { color: var(--acid); }

.press-ribbon__tag--now {
  background: var(--ribbon-voice);
  color: var(--night);
  opacity: 1;
  transform: translateY(-1px);
}

.press-ribbon__tag--now .press-ribbon__tag-letter {
  background: var(--night);
  color: var(--ribbon-voice);
}

.press-ribbon__tag--now .press-ribbon__tag-text {
  color: var(--night);
  font-weight: 700;
}

.press-ribbon__meta {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: clamp(6px, .8vw, 10px);
  border-top: 1px dashed var(--line-soft);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press-ribbon__meta-line {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.press-ribbon__meta-dot {
  display: inline-block;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: currentColor;
  opacity: .6;
}

.press-ribbon__meta-voice em {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: 10.5px;
  letter-spacing: 0;
  text-transform: none;
}

@keyframes pressRibbonTrace {
  to { stroke-dashoffset: 0; }
}

@keyframes pressRibbonDot {
  from { opacity: 0; transform: scale(.4); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes pressRibbonTitleStroke {
  to { stroke-dashoffset: 0; }
}

@keyframes pressRibbonTitleIn {
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .press-ribbon__rule-stroke,
  .press-ribbon__title-stroke {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }
  .press-ribbon__rule-dot,
  .press-ribbon__title-text {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

@media (max-width: 880px) {
  .press-ribbon {
    grid-template-columns: 1fr;
    gap: 10px;
    padding: 14px 16px;
  }
  .press-ribbon__rule {
    display: none;
  }
  .press-ribbon__core {
    justify-content: center;
    flex-wrap: wrap;
  }
  .press-ribbon__title-text {
    text-align: center;
  }
  .press-ribbon__meta {
    flex-direction: column;
    align-items: center;
    gap: 4px;
    text-align: center;
  }
}

@media (max-width: 520px) {
  .press-ribbon__slot {
    display: none;
  }
  .press-ribbon__tags {
    gap: 5px;
  }
  .press-ribbon__tag-text {
    display: none;
  }
}

/* ────────────────────────────────────────────────────────────
   SECOND READING · the second reading is the moment the line is
   read with the ear. Three voice readings sit side by side, each
   typeset in its own voice and scored with breath, measure, and
   tempo. The active reading is set forward, the others are held
   in reserve. A deliberate composition, not a tab strip.
   ──────────────────────────────────────────────────────────── */

.second-reading-section {
  margin-block: clamp(32px, 4vw, 56px);
}

.second-reading-section__header {
  max-width: 820px;
  margin-bottom: clamp(16px, 1.8vw, 24px);
}

.second-reading {
  position: relative;
  display: grid;
  gap: clamp(18px, 2vw, 26px);
  padding: clamp(28px, 3.6vw, 44px) clamp(22px, 3vw, 40px) clamp(24px, 3vw, 36px);
  border: 1px solid var(--line);
  background:
    radial-gradient(ellipse at 12% 0%, rgba(155, 188, 255, .05), transparent 58%),
    radial-gradient(ellipse at 88% 100%, rgba(216, 240, 106, .04), transparent 62%),
    linear-gradient(180deg, rgba(26, 34, 50, .34), rgba(12, 18, 28, .54));
  isolation: isolate;
  overflow: hidden;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-out);
}

.second-reading.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.second-reading::before {
  content: '';
  position: absolute;
  top: 14px;
  left: 14px;
  width: 12px;
  height: 12px;
  border-top: 1px solid var(--coral);
  border-left: 1px solid var(--coral);
  opacity: .55;
  pointer-events: none;
}

.second-reading::after {
  content: '';
  position: absolute;
  bottom: 14px;
  right: 14px;
  width: 12px;
  height: 12px;
  border-bottom: 1px solid var(--coral);
  border-right: 1px solid var(--coral);
  opacity: .55;
  pointer-events: none;
}

.second-reading--quiet::before,
.second-reading--quiet::after { border-color: var(--blue); }
.second-reading--bold::before,
.second-reading--bold::after { border-color: var(--acid); }

.second-reading__defs { position: absolute; inset: 0; width: 0; height: 0; pointer-events: none; }

.second-reading__crop {
  position: absolute;
  width: 14px;
  height: 14px;
  border-color: var(--coral);
  pointer-events: none;
  opacity: .85;
  transition: border-color .5s var(--ease);
}

.second-reading__crop--tl { top: 6px; left: 6px; border-top: 1.4px solid; border-left: 1.4px solid; }
.second-reading__crop--tr { top: 6px; right: 6px; border-top: 1.4px solid; border-right: 1.4px solid; }
.second-reading__crop--bl { bottom: 6px; left: 6px; border-bottom: 1.4px solid; border-left: 1.4px solid; }
.second-reading__crop--br { bottom: 6px; right: 6px; border-bottom: 1.4px solid; border-right: 1.4px solid; }

.second-reading--quiet .second-reading__crop { border-color: var(--blue); }
.second-reading--human .second-reading__crop { border-color: var(--coral); }
.second-reading--bold .second-reading__crop { border-color: var(--acid); }

.second-reading__head {
  position: relative;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
  padding-bottom: clamp(8px, 1vw, 14px);
  border-bottom: 1px dashed var(--line-soft);
}

.second-reading__head-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.second-reading__head-eyebrow-mark {
  display: inline-block;
  width: 18px;
  height: 1px;
  background: currentColor;
  opacity: .7;
}

.second-reading__head-eyebrow-mark--alt { opacity: .9; }

.second-reading__head-folio {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: 0;
  text-transform: none;
  opacity: .85;
}

.second-reading__head-folio-num {
  font-family: var(--mono);
  font-style: normal;
  font-size: 9.5px;
  letter-spacing: .22em;
  color: var(--coral);
}

.second-reading--quiet .second-reading__head-folio-num { color: var(--blue); }
.second-reading--bold .second-reading__head-folio-num { color: var(--acid); }

.second-reading__lede {
  margin: 0;
  max-width: 64ch;
  color: var(--lead-2);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15.5px, 1.3vw, 18px);
  line-height: 1.55;
  letter-spacing: -.002em;
  text-wrap: pretty;
}

.second-reading__lede em {
  color: var(--paper);
  font-style: italic;
  font-weight: inherit;
}

.second-reading__rule {
  display: block;
  width: 100%;
  height: 6px;
  color: var(--line);
  opacity: .85;
}

.second-reading__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: secondReadingRuleDraw 1.6s var(--ease-out) .35s forwards;
}

@keyframes secondReadingRuleDraw {
  to { stroke-dashoffset: 0; }
}

.second-reading__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: clamp(14px, 1.6vw, 20px);
}

.second-reading__item {
  --reading-tone: var(--paper);
  position: relative;
  display: grid;
  gap: clamp(10px, 1.2vw, 14px);
  padding: clamp(18px, 2.2vw, 26px) clamp(18px, 2.4vw, 30px);
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  background:
    linear-gradient(180deg, rgba(20, 26, 38, .4), rgba(12, 16, 26, .58));
  transition:
    opacity .5s var(--ease),
    border-color .5s var(--ease),
    background-color .5s var(--ease),
    transform .45s var(--ease-out),
    box-shadow .5s var(--ease);
}

.second-reading__item--quiet { --reading-tone: var(--blue); }
.second-reading__item--human { --reading-tone: var(--coral); }
.second-reading__item--bold { --reading-tone: var(--acid); }

.second-reading__item.is-active {
  border-color: var(--reading-tone);
  background:
    linear-gradient(180deg, rgba(34, 44, 64, .5), rgba(18, 24, 38, .68));
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .03),
    0 18px 36px -22px rgba(0, 0, 0, .45);
}

.second-reading__item.is-lifted {
  border-color: var(--reading-tone);
  transform: translateY(-2px);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .04),
    0 12px 26px -16px rgba(0, 0, 0, .4);
}

.second-reading__item.is-dimmed {
  opacity: .5;
}

.second-reading__item.is-dimmed.is-lifted {
  opacity: .85;
}

.second-reading__row {
  position: relative;
  display: grid;
  grid-template-columns: minmax(56px, 64px) minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  grid-template-areas:
    'marker meta'
    'marker typeset'
    'reading reading';
  gap: clamp(10px, 1.4vw, 18px) clamp(14px, 1.8vw, 22px);
  align-items: stretch;
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.second-reading__row-marker {
  grid-area: marker;
  display: grid;
  align-content: start;
  justify-items: center;
  gap: clamp(8px, 1vw, 12px);
  padding-right: clamp(8px, 1vw, 14px);
  border-right: 1px dashed var(--line-soft);
  color: var(--reading-tone);
  transition: color .5s var(--ease);
}

.second-reading__row-letter {
  display: inline-grid;
  place-items: center;
  width: clamp(34px, 3.6vw, 46px);
  height: clamp(34px, 3.6vw, 46px);
  border: 1.4px solid currentColor;
  border-radius: 50%;
  color: currentColor;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.3vw, 18px);
  font-weight: 500;
  letter-spacing: 0;
  background:
    radial-gradient(ellipse at 32% 32%, rgba(255, 255, 255, .05), transparent 60%),
    rgba(14, 19, 30, .55);
  transition:
    background .5s var(--ease),
    color .5s var(--ease),
    border-color .5s var(--ease),
    transform .45s var(--ease-spring);
}

.second-reading__item.is-active .second-reading__row-letter {
  background: currentColor;
  color: var(--night);
}

.second-reading__item.is-lifted:not(.is-active) .second-reading__row-letter {
  transform: scale(1.05);
}

.second-reading__row-letter-rule {
  display: block;
  width: 1px;
  flex: 1;
  background: currentColor;
  opacity: .25;
  min-height: clamp(20px, 3vw, 36px);
}

.second-reading__row-meta {
  grid-area: meta;
  display: grid;
  gap: clamp(4px, .5vw, 8px);
  align-content: start;
}

.second-reading__row-meta-head {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: clamp(8px, 1vw, 12px);
}

.second-reading__row-name {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.3vw, 18px);
  font-weight: 500;
  letter-spacing: -.01em;
}

.second-reading__row-face {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.second-reading__row-roman {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  color: var(--reading-tone);
  font-family: var(--serif);
  font-size: clamp(13px, 1.1vw, 15px);
  font-style: italic;
  letter-spacing: -.005em;
}

.second-reading__row-roman-mark {
  font-family: var(--serif);
  font-style: normal;
  font-size: 14px;
  opacity: .65;
}

.second-reading__row-scene {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, .95vw, 13px);
  letter-spacing: -.002em;
  opacity: .85;
}

.second-reading__row-scene-glyph {
  flex: 0 0 auto;
  width: 12px;
  height: 12px;
  color: var(--reading-tone);
  opacity: .65;
}

.second-reading__row-typeset {
  grid-area: typeset;
  display: grid;
  gap: clamp(2px, .4vw, 6px);
  padding: clamp(12px, 1.4vw, 18px) clamp(14px, 1.8vw, 22px);
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  background:
    linear-gradient(180deg, rgba(14, 19, 30, .42), rgba(14, 19, 30, .62));
  isolation: isolate;
  position: relative;
}

.second-reading__row-typeset::before {
  content: '';
  position: absolute;
  inset: 4px;
  border: 1px dashed rgba(255, 255, 255, .04);
  pointer-events: none;
  border-radius: 1px;
}

.second-reading__row-typeset-mark {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: clamp(4px, .5vw, 8px);
  color: var(--reading-tone);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.second-reading__row-typeset-mark em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: -.002em;
  text-transform: none;
  color: var(--paper);
  opacity: .85;
}

.second-reading__voice-glyph {
  font-family: var(--serif);
  font-size: 14px;
  line-height: 1;
  font-style: italic;
}

.second-reading__row-line {
  display: flex;
  align-items: baseline;
  gap: clamp(8px, 1vw, 14px);
  font-family: var(--reading-font, var(--serif));
  font-weight: var(--reading-weight, 400);
  font-style: var(--reading-style, normal);
  letter-spacing: var(--reading-track, -.022em);
  font-size: var(--reading-size);
  color: var(--paper);
  line-height: 1.04;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition:
    font-family .6s var(--ease),
    letter-spacing .6s var(--ease),
    font-weight .6s var(--ease),
    font-style .6s var(--ease),
    color .45s var(--ease);
}

@media (max-width: 720px) {
  .second-reading__row-line { font-size: var(--reading-size-mobile); }
}

.second-reading__row-line--0 { padding-left: 0; }
.second-reading__row-line--1 { padding-left: clamp(6px, 1.2vw, 18px); opacity: .95; }
.second-reading__row-line--2 { padding-left: clamp(12px, 2.4vw, 36px); opacity: .86; }

.second-reading__row-line-text {
  display: inline-block;
  position: relative;
}

.second-reading__row-line.sr-lift .second-reading__row-line-text::after {
  content: '';
  position: absolute;
  left: -0.06em;
  right: -0.06em;
  bottom: -0.04em;
  height: 1px;
  background: var(--reading-tone);
  opacity: .42;
}

.second-reading__row-line.sr-settle .second-reading__row-line-text {
  color: var(--paper);
}

.second-reading__row-line.sr-pull .second-reading__row-line-text::before {
  content: '';
  position: absolute;
  left: -0.12em;
  right: -0.12em;
  top: 50%;
  height: 1px;
  background: var(--reading-tone);
  opacity: .35;
}

.second-reading__row-reading {
  grid-area: reading;
  display: grid;
  grid-template-columns: minmax(0, auto) repeat(4, minmax(0, 1fr));
  align-items: center;
  gap: clamp(10px, 1.2vw, 18px);
  padding-top: clamp(4px, .6vw, 8px);
  border-top: 1px dashed var(--line-soft);
}

.second-reading__row-reading-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.second-reading__row-reading-eyebrow em {
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
  color: var(--paper);
  opacity: .85;
}

.second-reading__row-reading-eyebrow-mark {
  display: inline-block;
  width: 10px;
  height: 1px;
  background: currentColor;
  opacity: .6;
}

.second-reading__row-reading-eyebrow-mark--alt { opacity: .9; }

.second-reading__row-reading-tempo {
  color: var(--reading-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1vw, 14px);
  letter-spacing: -.002em;
}

.second-reading__row-reading-breath,
.second-reading__row-reading-measure,
.second-reading__row-reading-tension {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: clamp(11.5px, .95vw, 13px);
  font-style: italic;
  letter-spacing: -.002em;
}

.second-reading__row-reading-breath-key,
.second-reading__row-reading-measure-key,
.second-reading__row-reading-tension-key {
  color: var(--muted);
  font-family: var(--mono);
  font-style: normal;
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.second-reading__row-reading-breath em,
.second-reading__row-reading-measure em {
  color: var(--paper);
  font-style: italic;
  opacity: .85;
}

.second-reading__row-reading-tension {
  justify-self: end;
}

.second-reading__tension {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.second-reading__tension-cell {
  display: inline-block;
  width: 6px;
  height: 12px;
  border: 1px solid var(--reading-tone);
  opacity: .35;
  transition: opacity .4s var(--ease), background .4s var(--ease);
}

.second-reading__tension-cell.is-set {
  background: var(--reading-tone);
  opacity: .85;
}

.second-reading__row-mark {
  position: absolute;
  top: clamp(12px, 1.4vw, 18px);
  right: clamp(12px, 1.4vw, 18px);
  width: 24px;
  height: 24px;
  color: var(--reading-tone);
  opacity: .25;
  transition: opacity .5s var(--ease), transform .5s var(--ease-spring);
}

.second-reading__row-mark-core {
  transition: r .35s var(--ease-spring);
}

.second-reading__item.is-active .second-reading__row-mark {
  opacity: .9;
}

.second-reading__item.is-lifted:not(.is-active) .second-reading__row-mark {
  opacity: .6;
  transform: scale(1.08);
}

.second-reading__row-breather {
  position: absolute;
  bottom: -2px;
  left: 32px;
  right: 32px;
  height: 12px;
  color: var(--reading-tone);
  opacity: 0;
  transition: opacity .5s var(--ease);
  pointer-events: none;
}

.second-reading__item.is-lifted .second-reading__row-breather {
  opacity: .55;
}

.second-reading__breather-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: secondReadingBreathDraw 1.4s var(--ease-out) .15s forwards;
}

.second-reading__item.is-lifted .second-reading__breather-stroke {
  animation: secondReadingBreathDraw 1.4s var(--ease-out) 0s forwards;
}

@keyframes secondReadingBreathDraw {
  to { stroke-dashoffset: 0; }
}

.second-reading__breather-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: secondReadingBreathBead .4s var(--ease-spring) 1.4s forwards;
}

.second-reading__row-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--reading-tone);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.second-reading__row-tag em {
  font-family: var(--serif);
  font-style: italic;
  font-size: 11.5px;
  letter-spacing: -.002em;
  text-transform: none;
  color: var(--paper);
}

.second-reading__row-tag-line {
  display: inline-block;
  width: 14px;
  height: 1px;
  background: currentColor;
  opacity: .5;
}

.second-reading__row-tag-line--alt { opacity: .85; }

.second-reading__item-caption {
  margin: 0;
  max-width: 62ch;
  padding: 0 clamp(4px, .6vw, 10px);
  color: var(--ink-mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12.5px, 1.05vw, 14.5px);
  line-height: 1.55;
  letter-spacing: -.002em;
  text-wrap: pretty;
  transition: color .45s var(--ease);
}

.second-reading__item.is-active .second-reading__item-caption {
  color: var(--lead-2);
}

.second-reading__item.is-lifted:not(.is-active) .second-reading__item-caption {
  color: var(--lead-1);
}

.second-reading__item-caption-mark {
  display: inline-block;
  margin-right: 6px;
  color: var(--reading-tone);
  font-style: normal;
  opacity: .7;
}

.second-reading__foot {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  padding-top: clamp(12px, 1.4vw, 18px);
  border-top: 1px dashed var(--line-soft);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.second-reading__foot-cell {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.second-reading__foot-cell--now { justify-self: start; }
.second-reading__foot-cell--set { justify-self: center; }
.second-reading__foot-cell--hint { justify-self: end; }

.second-reading__foot-key {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.second-reading__foot-value {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1vw, 13.5px);
  letter-spacing: 0;
  text-transform: none;
  color: var(--paper);
  opacity: .9;
}

.second-reading__foot-letter {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1px solid var(--coral);
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  font-weight: 500;
  color: var(--coral);
  background: rgba(20, 26, 38, .5);
}

.second-reading--quiet .second-reading__foot-letter { border-color: var(--blue); color: var(--blue); }
.second-reading--human .second-reading__foot-letter { border-color: var(--coral); color: var(--coral); }
.second-reading--bold .second-reading__foot-letter { border-color: var(--acid); color: var(--acid); }

.second-reading__foot-name {
  color: var(--paper);
  font-style: italic;
}

.second-reading__foot-cell--hint .second-reading__foot-value kbd {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  padding: 1px 6px 2px;
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--paper);
  font-family: var(--mono);
  font-style: normal;
  font-size: 9px;
  letter-spacing: .14em;
  background: rgba(20, 26, 38, .55);
}

.second-reading__foot-rule {
  width: clamp(40px, 6vw, 80px);
  height: 6px;
  color: var(--line);
  opacity: .75;
}

@media (max-width: 920px) {
  .second-reading__row {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      'marker'
      'meta'
      'typeset'
      'reading';
  }
  .second-reading__row-marker {
    flex-direction: row;
    border-right: 0;
    border-bottom: 1px dashed var(--line-soft);
    padding-right: 0;
    padding-bottom: clamp(8px, 1vw, 14px);
    justify-content: flex-start;
    gap: clamp(10px, 1.4vw, 16px);
  }
  .second-reading__row-letter-rule {
    width: auto;
    height: 1px;
    flex: 1;
    min-height: 0;
  }
  .second-reading__row-reading {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .second-reading__row-reading-tension {
    grid-column: 1 / -1;
    justify-self: start;
  }
  .second-reading__foot {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .second-reading__foot-cell--now,
  .second-reading__foot-cell--set,
  .second-reading__foot-cell--hint { justify-self: start; }
  .second-reading__foot-rule { display: none; }
}

@media (max-width: 620px) {
  .second-reading {
    padding: clamp(20px, 6vw, 28px) clamp(16px, 5vw, 22px) clamp(18px, 5vw, 26px);
  }
  .second-reading__item {
    padding: clamp(16px, 5vw, 22px) clamp(14px, 4vw, 20px);
  }
  .second-reading__row-typeset {
    padding: clamp(10px, 3vw, 14px) clamp(12px, 3vw, 18px);
  }
  .second-reading__row-line { font-size: var(--reading-size-mobile); }
  .second-reading__row-line--1 { padding-left: 4px; }
  .second-reading__row-line--2 { padding-left: 8px; }
  .second-reading__row-reading {
    grid-template-columns: minmax(0, 1fr);
  }
  .second-reading__foot {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* ────────────────────────────────────────────────────────────
   ANSWER REVEAL · tighter, more confident composition. The leaf
   opens with a soft tip-in; the seal and ink arrive after; the
   colophon anchors the foot. The frame is more deliberate.
   ──────────────────────────────────────────────────────────── */

.answer-reveal__leaf {
  background:
    radial-gradient(ellipse at 50% 0%, rgba(255, 248, 230, .75), transparent 55%),
    radial-gradient(circle at 94% 6%, rgba(255, 118, 95, .16), transparent 55%),
    radial-gradient(circle at 6% 92%, rgba(216, 255, 98, .08), transparent 55%),
    linear-gradient(180deg, #f7f1e0 0%, #ece4cd 100%);
}

.answer-reveal__inner {
  position: relative;
  z-index: 2;
}

.answer-reveal__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 0 clamp(28px, 5vw, 56px);
  margin-bottom: clamp(14px, 2vw, 22px);
}

.answer-reveal__folio {
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--ink-soft);
  opacity: .8;
}

.answer-reveal__stamp {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 10px 5px;
  border: 1px solid var(--ink);
  border-radius: 1px;
  background: rgba(247, 240, 222, .55);
  color: var(--ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  letter-spacing: -.01em;
  transform: rotate(-2deg);
}

.answer-reveal__stamp span {
  display: inline-block;
}

.answer-reveal__stamp em {
  font-family: var(--mono);
  font-style: normal;
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .75;
}

.answer-reveal__trail {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 clamp(28px, 5vw, 56px);
  margin: 0 0 clamp(8px, 1.2vw, 14px);
}

.answer-reveal__trail-dot {
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: rgba(17, 21, 33, .35);
}

.answer-reveal__trail-dot--big {
  width: 9px;
  height: 9px;
  background: rgba(179, 74, 58, .75);
  box-shadow: 0 0 0 3px rgba(179, 74, 58, .12);
}

.answer-reveal__copy {
  padding: 0 clamp(28px, 5vw, 56px) clamp(28px, 4vw, 44px);
}

.answer-reveal__pull {
  display: flex;
  align-items: center;
  gap: clamp(14px, 1.6vw, 22px);
  margin: clamp(28px, 3vw, 40px) 0 clamp(20px, 2.4vw, 30px);
  padding: clamp(6px, 1vw, 10px) 0;
  color: var(--coral);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.4vw, 19px);
  letter-spacing: -.012em;
  line-height: 1;
}

.answer-reveal__pull-rule {
  display: block;
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor);
  opacity: .55;
}

.answer-reveal__pull-rule:last-of-type {
  background: linear-gradient(to left, transparent, currentColor);
}

.answer-reveal__pull em {
  font-family: var(--serif);
  font-size: inherit;
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.012em;
  text-transform: none;
  color: var(--ink);
}

.answer-reveal__colophon {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: clamp(16px, 2vw, 22px);
  padding-top: clamp(14px, 1.8vw, 20px);
  border-top: 1px dashed rgba(17, 21, 33, .18);
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.answer-reveal__colophon span[aria-hidden] {
  opacity: .5;
}

.answer-reveal__close {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-top: clamp(20px, 2.6vw, 30px);
  padding: 10px 14px;
  border: 1px solid var(--ink);
  border-radius: 1px;
  background: rgba(247, 240, 222, .55);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  transition: background .35s var(--ease), transform .35s var(--ease-spring);
}

.answer-reveal__close svg {
  width: 16px;
  height: 16px;
  color: currentColor;
}

.answer-reveal__close:hover,
.answer-reveal__close:focus-visible {
  background: rgba(17, 21, 33, .08);
  transform: translateY(-1px);
}

.answer-reveal__press-used-text strong {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
  color: var(--ink);
  margin-right: 6px;
}

.answer-reveal__press-used-text em {
  font-family: var(--mono);
  font-style: normal;
  font-size: 8.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

/* ────────────────────────────────────────────────────────────
   GLOBAL TIGHTENING · a few well-placed refinements that lift
   the reading rhythm across the page without changing layout.
   ──────────────────────────────────────────────────────────── */

.section {
  padding-block: clamp(56px, 8vw, 120px);
}

.section__lede {
  max-width: 64ch;
}

.section__header {
  margin-bottom: clamp(28px, 3.6vw, 44px);
}

@media (max-width: 720px) {
  .hero__spread {
    padding: clamp(64px, 12vw, 96px) clamp(18px, 4vw, 32px) clamp(48px, 8vw, 72px);
  }

  .hero__title {
    letter-spacing: -.06em;
  }

  .hero__voice-row {
    flex-direction: column;
    align-items: stretch;
  }

  .hero__voice-tabs {
    justify-content: stretch;
  }

  .hero__voice-tab {
    flex: 1 1 0;
    justify-content: center;
  }

  .site-nav {
    gap: 14px;
  }

  .site-nav a {
    font-size: 11px;
    padding: 4px 0;
  }

  .site-header__row {
    flex-wrap: wrap;
    gap: 14px;
  }

  .site-header__note {
    width: 100%;
    text-align: left;
  }

  .hero__continue {
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
  }
}

/* ────────────────────────────────────────────────────────────
READING TRACE · a delicate ink scroll-progress that lives as
the bottom row of the site header. It marks the reader's place
in the page without competing with the margin thread on the
right; it is horizontal, restrained, and turns the scroll into
a small act of typesetting.
──────────────────────────────────────────────────────────── */

.reading-trace--in-header {
  flex: 1;
  min-width: 0;
  padding: 0;
  border: 0;
}

.reading-trace {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  padding: 0 clamp(10px, 1.4vw, 18px);
  border-top: 0;
  color: var(--paper);
  opacity: 0;
  animation: readingTraceIn .8s var(--ease-out) .25s forwards;
}

.reading-trace__rule {
  position: relative;
  display: block;
  width: 100%;
  height: 1px;
  background: linear-gradient(to right, var(--line) 0%, var(--line-soft) 100%);
  border-radius: 1px;
  overflow: hidden;
  order: 2;
}

.reading-trace__fill {
  position: absolute;
  inset: 0 auto 0 0;
  background: linear-gradient(to right, var(--acid), var(--coral));
  width: 0;
  transition: width .25s linear;
  border-radius: 1px;
}

.app--voice-quiet .reading-trace__fill {
  background: linear-gradient(to right, var(--blue), var(--acid));
}

.app--voice-bold .reading-trace__fill {
  background: linear-gradient(to right, var(--acid), var(--coral));
}

.reading-trace__dots {
  position: absolute;
  inset: -3px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin: 0;
  padding: 0 4px;
  list-style: none;
}

.reading-trace__dot-wrap {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  pointer-events: auto;
  flex: 0 0 auto;
}

.reading-trace__dot {
  position: relative;
  display: grid;
  place-items: center;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--night);
  border: 1.2px solid var(--muted);
  transition: background .45s var(--ease), border-color .45s var(--ease), transform .55s var(--ease-spring), box-shadow .55s var(--ease);
}

.reading-trace__dot:hover,
.reading-trace__dot:focus-visible {
  border-color: var(--paper);
  background: rgba(243, 236, 214, .18);
  transform: scale(1.25);
}

.reading-trace__dot::before {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
}

.reading-trace__dot-num,
.reading-trace__dot-label {
  position: absolute;
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s var(--ease), transform .25s var(--ease);
}

.reading-trace__dot-num {
  top: -16px;
  left: 50%;
  transform: translate(-50%, 4px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .18em;
}

.reading-trace__dot-label {
  top: 26px;
  left: 50%;
  width: 90px;
  transform: translate(-50%, -4px);
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.reading-trace__dot-wrap:hover .reading-trace__dot-num,
.reading-trace__dot-wrap:focus-within .reading-trace__dot-num,
.reading-trace__dot-wrap.is-active .reading-trace__dot-num {
  opacity: 1;
  transform: translate(-50%, 0);
}

.reading-trace__dot-wrap:hover .reading-trace__dot-label,
.reading-trace__dot-wrap:focus-within .reading-trace__dot-label {
  opacity: 1;
  transform: translate(-50%, 0);
}

.reading-trace__dot.is-past {
  border-color: var(--coral);
  background: rgba(240, 110, 91, .2);
}

.reading-trace__dot.is-active {
  border-color: var(--coral);
  background: var(--coral);
  transform: scale(1.5);
  box-shadow: 0 0 0 4px rgba(240, 110, 91, .15), 0 0 14px rgba(240, 110, 91, .4);
}

.app--voice-quiet .reading-trace__dot.is-past,
.app--voice-quiet .reading-trace__dot.is-active {
  border-color: var(--blue);
}

.app--voice-quiet .reading-trace__dot.is-active {
  background: var(--blue);
  box-shadow: 0 0 0 4px rgba(155, 188, 255, .15), 0 0 14px rgba(155, 188, 255, .4);
}

.app--voice-bold .reading-trace__dot.is-past,
.app--voice-bold .reading-trace__dot.is-active {
  border-color: var(--acid);
}

.app--voice-bold .reading-trace__dot.is-active {
  background: var(--acid);
  box-shadow: 0 0 0 4px rgba(216, 240, 106, .15), 0 0 14px rgba(216, 240, 106, .4);
}

.reading-trace__readout {
  display: none;
}

@keyframes readingTraceIn {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .reading-trace {
    opacity: 1 !important;
    animation: none !important;
  }

  .reading-trace__fill {
    transition: none !important;
  }
}

@media (max-width: 720px) {
  .reading-trace {
    padding: 0;
    grid-template-columns: minmax(0, 1fr);
  }

  .reading-trace__rule {
    grid-column: 1 / -1;
  }

  .reading-trace__dot-label {
    display: none;
  }
}

@media (max-width: 540px) {
  .reading-trace__dot-wrap {
    width: 24px;
    height: 24px;
  }

  .reading-trace__dot {
    width: 6px;
    height: 6px;
  }

  .reading-trace__dot-num {
    font-size: 7.5px;
  }
}


/* ────────────────────────────────────────────────────────────
   PRESS MARK · a small stamped impression used to sign the hero
   ──────────────────────────────────────────────────────────── */

.press-mark {
  display: inline-block;
  width: clamp(80px, 9vw, 124px);
  height: clamp(80px, 9vw, 124px);
  color: var(--pm-tone, var(--coral));
  transform: rotate(-6deg);
  transition: color .55s var(--ease), transform .8s var(--ease-spring);
  filter: drop-shadow(0 8px 14px rgba(0, 0, 0, .45));
  pointer-events: none;
}

.press-mark svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.press-mark:hover {
  transform: rotate(2deg) scale(1.04);
}


/* ────────────────────────────────────────────────────────────
   HERO PRESS MARK · a stamped corner mark inside the title plate
   ──────────────────────────────────────────────────────────── */

.hero__press-mark {
  position: absolute;
  top: clamp(18px, 2.6vw, 32px);
  right: clamp(18px, 2.6vw, 36px);
  z-index: 3;
  opacity: 0;
  animation: heroPressMarkIn .75s var(--ease-out) forwards;
}

@keyframes heroPressMarkIn {
  0% { opacity: 0; transform: scale(1.4) rotate(-18deg); }
  60% { opacity: .92; transform: scale(.96) rotate(2deg); }
  100% { opacity: .92; transform: scale(1) rotate(-6deg); }
}

@media (prefers-reduced-motion: reduce) {
  .hero__press-mark {
    opacity: .9 !important;
    animation: none !important;
    transform: rotate(-4deg) !important;
  }
}

@media (max-width: 720px) {
  .hero__press-mark {
    top: 12px;
    right: 14px;
  }

  .press-mark {
    width: 64px;
    height: 64px;
  }
}

@media (max-width: 480px) {
  .hero__press-mark {
    top: 10px;
    right: 10px;
  }

  .press-mark {
    width: 54px;
    height: 54px;
  }
}


/* ────────────────────────────────────────────────────────────
   PRESS BED · a single unified folio replacing the press bay
   and the compose floor. The lever on the left, the composing
   stick in the middle, the pulled impression on the right.
   Pulling the lever pulls a fresh impression.
   ──────────────────────────────────────────────────────────── */

.press {
  display: block;
}

.press__sheet {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(22px, 2.4vw, 34px);
  padding: clamp(36px, 4vw, 60px) clamp(28px, 3.6vw, 56px) clamp(40px, 4.4vw, 68px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 18% 0%, rgba(146, 186, 255, .06), transparent 42%),
    radial-gradient(circle at 92% 100%, rgba(216, 255, 106, .04), transparent 50%),
    linear-gradient(180deg, rgba(28, 36, 52, .38), rgba(14, 20, 32, .58));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 28px 64px -34px rgba(0, 0, 0, .5);
  overflow: hidden;
  isolation: isolate;
  transition: background .6s var(--ease);
}

.press__sheet--quiet {
  background:
    radial-gradient(circle at 22% 8%, rgba(146, 186, 255, .08), transparent 50%),
    radial-gradient(circle at 84% 100%, rgba(216, 255, 106, .03), transparent 50%),
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(14, 20, 32, .6));
}

.press__sheet--human {
  background:
    radial-gradient(circle at 18% 6%, rgba(255, 118, 95, .08), transparent 48%),
    radial-gradient(circle at 88% 100%, rgba(146, 186, 255, .04), transparent 48%),
    linear-gradient(180deg, rgba(36, 26, 32, .42), rgba(14, 14, 22, .6));
}

.press__sheet--bold {
  background:
    radial-gradient(circle at 20% 4%, rgba(216, 255, 106, .09), transparent 48%),
    radial-gradient(circle at 86% 100%, rgba(255, 118, 95, .04), transparent 48%),
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(14, 20, 32, .62));
}

.press__plate {
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  display: inline-block;
  padding: 4px 12px;
  border: 1px solid var(--line);
  background: rgba(14, 20, 32, .65);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.press__crop {
  position: absolute;
  width: 18px;
  height: 18px;
  border-color: var(--paper);
  border-style: solid;
  border-width: 0;
  opacity: .6;
  pointer-events: none;
  transition: opacity .35s var(--ease);
}

.press__crop--tl { top: -1px; left: -1px; border-top-width: 1px; border-left-width: 1px; }
.press__crop--tr { top: -1px; right: -1px; border-top-width: 1px; border-right-width: 1px; }
.press__crop--bl { bottom: -1px; left: -1px; border-bottom-width: 1px; border-left-width: 1px; }
.press__crop--br { bottom: -1px; right: -1px; border-bottom-width: 1px; border-right-width: 1px; }

.press:hover .press__crop { opacity: 1; }

.press__head {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
  padding-bottom: clamp(18px, 2.4vw, 28px);
  border-bottom: 1px solid var(--line-soft);
  max-width: 920px;
  margin: 0 auto;
}

.press__head h2 {
  margin: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(2rem, 4vw, 3.4rem);
  letter-spacing: -.02em;
  line-height: 1.05;
}

.press__head h2 i {
  font-style: italic;
  color: var(--coral);
}

.app--voice-quiet .press__head h2 i { color: var(--blue); }
.app--voice-bold .press__head h2 i { color: var(--acid); }

.press__head .section__lede {
  margin: 0;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: clamp(15px, 1.4vw, 18px);
  font-style: italic;
  line-height: 1.55;
  max-width: 720px;
}

.press__spread {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1.25fr) minmax(0, 1fr);
  gap: clamp(18px, 2.4vw, 36px);
  align-items: stretch;
  position: relative;
}

.press__spread::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc((100% / 3) - 1px);
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 12%, var(--line) 88%, transparent);
  content: '';
  pointer-events: none;
}

.press__spread::after {
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(2 * (100% / 3) - 1px);
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 12%, var(--line) 88%, transparent);
  content: '';
  pointer-events: none;
}

/* ── LEVER ─────────────────────────────────────────────── */

.press__lever-zone {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(18px, 2vw, 26px) clamp(8px, 1vw, 18px);
  text-align: center;
}

.press__lever-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.press__lever-eyebrow::before,
.press__lever-eyebrow::after {
  content: '';
  display: block;
  width: 14px;
  height: 1px;
  background: currentColor;
  opacity: .65;
}

.press__lever {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  padding: 0;
  background: transparent;
  border: 0;
  cursor: pointer;
  isolation: isolate;
}

.press__lever-cage {
  position: relative;
  display: block;
  width: 44px;
  height: 110px;
}

.press__lever-cage-rail {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: linear-gradient(to bottom, transparent, var(--line) 8%, var(--line) 92%, transparent);
}

.press__lever-cage-rail--left { left: 6px; }
.press__lever-cage-rail--right { right: 6px; }

.press__lever-cage-cap {
  position: absolute;
  top: -1px;
  left: -2px;
  right: -2px;
  height: 1px;
  background: var(--line);
}

.press__lever-cage-tick {
  position: absolute;
  left: -8px;
  width: 8px;
  height: 1px;
  background: var(--muted);
  opacity: .55;
}

.press__lever-cage-tick--top { top: 22px; }
.press__lever-cage-tick--mid { top: 64px; }

.press__lever-pull {
  position: absolute;
  top: 6px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .24em;
  text-transform: uppercase;
  opacity: .55;
}

.press__lever-handle {
  position: relative;
  display: block;
  width: 76px;
  height: 76px;
  margin-top: 14px;
  transform-origin: 50% 100%;
  transition: transform .45s var(--ease-spring);
}

.press__lever.is-pulling .press__lever-handle {
  transform: translateY(36px) rotate(-2deg);
}

.press__lever-knob {
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 36% 30%, rgba(255, 255, 255, .45), transparent 38%),
    radial-gradient(circle at 64% 70%, rgba(0, 0, 0, .35), transparent 56%),
    var(--coral);
  box-shadow:
    inset 0 -3px 6px rgba(0, 0, 0, .4),
    0 10px 16px -8px rgba(0, 0, 0, .55),
    0 0 0 1px rgba(0, 0, 0, .45);
  transition: background .5s var(--ease), box-shadow .5s var(--ease);
}

.press__lever--quiet .press__lever-knob {
  background:
    radial-gradient(circle at 36% 30%, rgba(255, 255, 255, .5), transparent 38%),
    radial-gradient(circle at 64% 70%, rgba(0, 0, 0, .35), transparent 56%),
    var(--blue);
}

.press__lever--bold .press__lever-knob {
  background:
    radial-gradient(circle at 36% 30%, rgba(255, 255, 255, .5), transparent 38%),
    radial-gradient(circle at 64% 70%, rgba(0, 0, 0, .35), transparent 56%),
    var(--acid);
}

.press__lever-knob-shadow {
  position: absolute;
  left: 50%;
  bottom: -10px;
  width: 60%;
  height: 8px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: rgba(0, 0, 0, .5);
  filter: blur(6px);
}

.press__lever-knob-highlight {
  position: absolute;
  top: 14px;
  left: 18px;
  width: 14px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, .55);
  filter: blur(2px);
}

.press__lever-knob-band {
  position: absolute;
  top: 50%;
  left: 8px;
  right: 8px;
  height: 2px;
  transform: translateY(-50%);
  background: rgba(0, 0, 0, .35);
  opacity: .55;
  border-radius: 2px;
}

.press__lever-knob-rivet {
  position: absolute;
  top: 50%;
  width: 5px;
  height: 5px;
  margin-top: -2px;
  border-radius: 50%;
  background: rgba(0, 0, 0, .55);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .25);
}

.press__lever-knob-rivet--a { left: 16px; }
.press__lever-knob-rivet--b { right: 16px; }

.press__lever-stem {
  position: relative;
  display: block;
  width: 4px;
  height: 86px;
  margin-top: -10px;
  background: linear-gradient(to bottom, var(--muted), transparent);
  opacity: .65;
}

.press__lever-stem-rail {
  position: absolute;
  inset: 0;
  width: 4px;
  background: linear-gradient(to bottom, rgba(0, 0, 0, .55), transparent 88%);
}

.press__lever-stem-pin {
  position: absolute;
  left: 50%;
  bottom: 6px;
  width: 14px;
  height: 4px;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, .55);
  border-radius: 2px;
}

.press__lever-hint {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.press__lever-hint kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  padding: 2px 5px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: rgba(20, 26, 38, .55);
  font-family: var(--mono);
  font-size: 9px;
  color: var(--paper);
}

.press__lever-now {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
  width: 100%;
  padding-top: clamp(12px, 1.4vw, 18px);
  border-top: 1px solid var(--line-soft);
}

.press__lever-now-eyebrow {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.press__lever-now-row {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
}

.press__lever-now-letter {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 16px;
  line-height: 1;
  color: var(--coral);
  transition: color .5s var(--ease);
}

.press__lever-now-letter--quiet { color: var(--blue); }
.press__lever-now-letter--human { color: var(--coral); }
.press__lever-now-letter--bold { color: var(--acid); }

.press__lever-now-name {
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(16px, 1.4vw, 19px);
  font-style: italic;
  letter-spacing: -.01em;
  line-height: 1;
}

.press__lever-now-face {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.press__lever-next {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border: 1px dashed var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.press__lever-next-letter {
  display: inline-grid;
  place-items: center;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1px solid currentColor;
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  line-height: 1;
}

.press__lever-next-letter--quiet { color: var(--blue); }
.press__lever-next-letter--human { color: var(--coral); }
.press__lever-next-letter--bold { color: var(--acid); }

/* ── COMPOSING STICK ──────────────────────────────────── */

.press__stick-zone {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(18px, 2vw, 26px) clamp(8px, 1vw, 18px);
  text-align: center;
}

.press__stick-eyebrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.press__stick-eyebrow::before,
.press__stick-eyebrow::after {
  content: '';
  display: block;
  width: 14px;
  height: 1px;
  background: currentColor;
  opacity: .65;
}

.press__stick-rule {
  display: block;
  width: 100%;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 14%, var(--line) 86%, transparent);
}

.press__stick {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: clamp(14px, 1.6vw, 22px) clamp(12px, 1.6vw, 22px);
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .035), rgba(243, 236, 214, .015));
  box-shadow:
    inset 0 1px 0 rgba(146, 186, 255, .04),
    inset 0 -1px 0 rgba(0, 0, 0, .35);
  transition: border-color .5s var(--ease);
}

.press__stick::before,
.press__stick::after {
  position: absolute;
  left: 12px;
  right: 12px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--mist) 12%, var(--mist) 88%, transparent);
  opacity: .4;
  content: '';
}

.press__stick::before { top: 8px; }
.press__stick::after { bottom: 8px; }

.press__stick-line {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: clamp(6px, .8vw, 12px);
  flex-wrap: wrap;
  padding: clamp(6px, .8vw, 12px) 0;
}

.press__stick-piece {
  position: relative;
  display: inline-flex;
  align-items: baseline;
  padding: 2px 4px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(18px, 2.2vw, 30px);
  font-style: italic;
  letter-spacing: -.01em;
  line-height: 1.1;
  transition: color .5s var(--ease), transform .5s var(--ease), text-shadow .5s var(--ease);
}

.press__stick--bold .press__stick-piece {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 800;
  letter-spacing: -.04em;
  text-transform: uppercase;
}

.press__stick-piece.is-marked {
  color: var(--acid);
}

.press__stick-piece.is-active {
  transform: translateY(-3px);
  text-shadow:
    0 1px 0 rgba(0, 0, 0, .35),
    0 2px 0 rgba(0, 0, 0, .25),
    0 6px 14px rgba(0, 0, 0, .45);
}

.press__stick-piece.is-active::before {
  content: '';
  position: absolute;
  inset: auto 2px -2px 2px;
  height: 2px;
  background: currentColor;
  opacity: .65;
}

.press__stick-piece-kern {
  display: inline-block;
  width: 1px;
  align-self: stretch;
  background: var(--line);
  opacity: .45;
  margin: 0 2px;
}

.press__stick-callout {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(10px, 1.2vw, 14px) clamp(12px, 1.4vw, 18px);
  border: 1px solid var(--line);
  background: rgba(20, 26, 38, .55);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .2em;
  text-transform: uppercase;
  transition: border-color .5s var(--ease);
}

.press__stick-callout-mark {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  color: var(--acid);
}

.press__stick-callout-copy {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
}

.press__stick-callout-label {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press__stick-callout-copy strong {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(15px, 1.4vw, 18px);
  letter-spacing: -.01em;
  text-transform: none;
}

.press__stick-callout-meta {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
}

.press__stick-callout-folio {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .2em;
}

.press__stick-callout-mark-tag {
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press__stick-callout-mark-sub {
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: 0;
  text-transform: none;
}

.press__stick-active-rule {
  display: block;
  width: 60%;
  margin: 0 auto;
  height: 10px;
  color: var(--acid);
  opacity: .65;
}

.press__stick-active-rule svg {
  width: 100%;
  height: 100%;
}

/* ── IMPRESSION ────────────────────────────────────────── */

.press__impression-zone {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(18px, 2vw, 26px) clamp(8px, 1vw, 18px);
  text-align: center;
}

.press__impression-eyebrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.press__impression-eyebrow::before,
.press__impression-eyebrow::after {
  content: '';
  display: block;
  width: 14px;
  height: 1px;
  background: currentColor;
  opacity: .65;
}

.press__impression-frame {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(18px, 2vw, 28px);
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(20, 26, 38, .55), rgba(14, 20, 32, .65));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .03),
    0 14px 28px -20px rgba(0, 0, 0, .5);
  overflow: hidden;
  isolation: isolate;
}

.press__impression-corner {
  position: absolute;
  width: 16px;
  height: 16px;
  border-color: var(--paper);
  border-style: solid;
  border-width: 0;
  opacity: .55;
  pointer-events: none;
}

.press__impression-corner--tl { top: -1px; left: -1px; border-top-width: 1px; border-left-width: 1px; }
.press__impression-corner--tr { top: -1px; right: -1px; border-top-width: 1px; border-right-width: 1px; }
.press__impression-corner--bl { bottom: -1px; left: -1px; border-bottom-width: 1px; border-left-width: 1px; }
.press__impression-corner--br { bottom: -1px; right: -1px; border-bottom-width: 1px; border-right-width: 1px; }

.press__impression-bed {
  position: absolute;
  inset: 18px;
  color: var(--mist);
  pointer-events: none;
  opacity: .85;
}

.press__impression-bed svg {
  width: 100%;
  height: 100%;
}

.press__impression-colorbar {
  position: absolute;
  top: 14px;
  right: 14px;
  display: flex;
  gap: 2px;
  pointer-events: none;
}

.press__impression-colorbar span {
  display: block;
  width: 14px;
  height: 6px;
  border-radius: 1px;
}

.press__impression-sheet {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(20px, 2.4vw, 30px) clamp(16px, 2vw, 24px) clamp(14px, 1.6vw, 20px);
  width: 100%;
  max-width: 320px;
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .045), rgba(243, 236, 214, .02));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 18px 28px -16px rgba(0, 0, 0, .55),
    0 0 0 1px rgba(0, 0, 0, .35);
  opacity: 0;
  transform: translateY(8px) scale(.98);
  transition: opacity .45s var(--ease), transform .55s var(--ease);
  pointer-events: none;
}

.press__impression-sheet.is-active {
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}

.press__impression-sheet.is-past {
  opacity: .35;
  transform: translateY(-6px) scale(.96);
}

.press__impression-sheet-folio {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press__impression-title {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(6px, 1vw, 12px);
  width: 100%;
}

.press__impression-title--quiet,
.press__impression-title--human,
.press__impression-title--bold {
  color: var(--paper);
}

.press__impression-title--quiet .press__impression-line-text {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.018em;
}

.press__impression-title--human .press__impression-line-text {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  letter-spacing: -.012em;
  color: var(--coral);
}

.press__impression-title--bold .press__impression-line-text {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 800;
  letter-spacing: -.06em;
  text-transform: uppercase;
  color: var(--acid);
}

.press__impression-line {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  font-size: clamp(15px, 1.7vw, 22px);
  line-height: 1.1;
}

.press__impression-line.is-marked .press__impression-line-text {
  position: relative;
}

.press__impression-line.is-marked .press__impression-line-text::after {
  content: '';
  position: absolute;
  left: -2px;
  right: -2px;
  bottom: -2px;
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.press__impression-line-mark {
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: 16px;
  opacity: .85;
}

.press__impression-stamp {
  position: absolute;
  top: 8px;
  right: 10px;
  width: 36px;
  height: 36px;
  color: var(--muted);
  opacity: .55;
  transform: rotate(-6deg);
}

.press__impression-stamp svg {
  width: 100%;
  height: 100%;
}

.press__impression-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  padding-top: clamp(8px, 1vw, 12px);
  border-top: 1px dashed var(--line);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.press__impression-foot-mark {
  color: var(--coral);
}

.press__impression-foot-voice {
  color: var(--paper);
}

.press__impression-hint {
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.1vw, 14px);
  letter-spacing: -.005em;
  line-height: 1.5;
  text-transform: none;
}

.press__caption {
  margin: 0;
  padding-top: clamp(16px, 2vw, 22px);
  border-top: 1px solid var(--line-soft);
  color: var(--muted);
  font-family: var(--serif);
  font-size: clamp(13px, 1.2vw, 15px);
  font-style: italic;
  line-height: 1.55;
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.press__caption span[aria-hidden] {
  color: var(--coral);
  font-style: normal;
  font-size: 14px;
  line-height: 1.2;
}

.press.is-pulling .press__lever-knob {
  box-shadow:
    inset 0 -3px 6px rgba(0, 0, 0, .4),
    0 4px 8px -4px rgba(0, 0, 0, .35),
    0 0 0 1px rgba(0, 0, 0, .45);
}

.press.is-pulling .press__impression-sheet.is-active {
  animation: impressionPull .85s var(--ease-out) forwards;
}

@keyframes impressionPull {
  0% { opacity: 0; transform: translateY(18px) scale(.96); filter: blur(1.5px); }
  45% { opacity: .85; transform: translateY(-2px) scale(1.01); filter: blur(.3px); }
  100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}

@media (prefers-reduced-motion: reduce) {
  .press__impression-sheet {
    transition: opacity .25s linear;
    transform: none !important;
  }

  .press.is-pulling .press__impression-sheet.is-active {
    animation: none !important;
  }

  .press__lever.is-pulling .press__lever-handle {
    transform: none !important;
  }
}

@media (max-width: 1100px) {
  .press__spread {
    grid-template-columns: minmax(0, 1fr);
    gap: clamp(24px, 3vw, 36px);
  }

  .press__spread::before,
  .press__spread::after {
    left: 0;
    right: 0;
    top: auto;
    bottom: auto;
    width: auto;
    height: 1px;
    background: linear-gradient(to right, transparent, var(--line) 8%, var(--line) 92%, transparent);
  }

  .press__spread::before {
    top: calc((100% / 3) - 1px);
  }

  .press__spread::after {
    top: calc(2 * (100% / 3) - 1px);
  }
}

@media (max-width: 720px) {
  .press__sheet {
    padding: 28px 16px;
  }

  .press__stick-line {
    flex-wrap: wrap;
  }

  .press__stick-callout {
    flex-wrap: wrap;
    justify-content: center;
  }
}

@media (max-width: 540px) {
  .press__head h2 {
    font-size: 1.6rem;
  }

  .press__impression-sheet {
    max-width: 100%;
  }
}


/* ────────────────────────────────────────────────────────────
   MARGIN NOTES · a small left-edge notelet that surfaces a
   single editor's hand-written line for the current folio.
   ──────────────────────────────────────────────────────────── */

.margin-notes {
  position: fixed;
  top: 130px;
  left: clamp(14px, 2.4vw, 30px);
  z-index: 5;
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: clamp(168px, 17vw, 220px);
  padding: 14px 16px 12px;
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 0 0%, rgba(216, 255, 106, .04), transparent 60%),
    rgba(20, 26, 38, .6);
  color: var(--paper);
  pointer-events: none;
  transform-origin: 0 50%;
  opacity: 0;
  animation: marginNotesIn 1.1s var(--ease-out) .85s forwards;
  transition: border-color .45s var(--ease), color .45s var(--ease);
}

.margin-notes--acid { --mn-ink: var(--acid); }
.margin-notes--coral { --mn-ink: var(--coral); }
.margin-notes--blue { --mn-ink: var(--blue); }
.margin-notes--paper { --mn-ink: var(--paper); }

.margin-notes--idle { color: var(--muted); }
.margin-notes--idle .margin-notes__hand-mark--idle {
  color: var(--muted);
  border-color: var(--muted);
  opacity: .7;
}
.margin-notes--idle .margin-notes__hand-text {
  color: var(--muted);
  font-style: italic;
}

.margin-notes--voice-quiet { color: var(--blue); }
.margin-notes--voice-human { color: var(--coral); }
.margin-notes--voice-bold { color: var(--acid); }

.margin-notes__rule {
  display: block;
  width: 100%;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--mn-ink, var(--paper)) 18%, var(--mn-ink, var(--paper)) 82%, transparent);
  opacity: .55;
}

.margin-notes__hand {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.margin-notes__hand-mark {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 15px;
  line-height: 1;
  color: var(--mn-ink, var(--paper));
  flex: 0 0 auto;
}

.margin-notes__hand-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.margin-notes__hand-tag {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.margin-notes__hand-text {
  display: block;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.05vw, 15px);
  line-height: 1.45;
  letter-spacing: -.005em;
  transition: color .45s var(--ease);
}

.margin-notes--acid .margin-notes__hand-text { color: var(--paper); }
.margin-notes--coral .margin-notes__hand-text { color: var(--coral); }
.margin-notes--blue .margin-notes__hand-text { color: var(--blue); }

.margin-notes__hand-sig {
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: -.005em;
  line-height: 1.3;
}

.margin-notes__scroll {
  display: block;
  width: 60%;
  height: 12px;
  margin-left: auto;
  color: var(--mn-ink, var(--paper));
  opacity: .65;
}

.margin-notes__scroll svg {
  width: 100%;
  height: 100%;
}

.margin-notes__scroll-stroke {
  stroke-dasharray: 80 80;
  stroke-dashoffset: 80;
  animation: marginNotesScroll 1.4s var(--ease-out) 1.5s forwards;
}

@keyframes marginNotesScroll {
  to { stroke-dashoffset: 0; }
}

@keyframes marginNotesIn {
  0% { opacity: 0; transform: translateX(-8px); }
  100% { opacity: 1; transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .margin-notes {
    opacity: 1 !important;
    animation: none !important;
    transform: none !important;
  }

  .margin-notes__scroll-stroke {
    stroke-dashoffset: 0 !important;
    animation: none !important;
  }
}

@media (max-width: 1380px) {
  .margin-notes {
    display: none;
  }
}


/* ────────────────────────────────────────────────────────────
   ITERATION 238 · the page reads as a single letterpress proof.
   The title spread gains a paper plate frame with corner
   registration marks; a small plate stamp signs the impression;
   marked words in the title receive a refined editor's underline;
   the hero plate breathes with calmer spacing on every screen.
   ──────────────────────────────────────────────────────────── */

/* The four corner registration marks anchor the proof spread. They
   sit slightly inside the corners so they read as press-shop marks,
   not as browser crops. Each corner is a tiny L with a pip. */

.hero__corner {
  position: absolute;
  width: 22px;
  height: 22px;
  color: var(--paper);
  opacity: 0;
  pointer-events: none;
  animation: cornerMarkIn .9s var(--ease-out) 1.1s forwards;
  transition: color .55s var(--ease);
}

.hero__corner--tl { top: 12px; left: 12px; }
.hero__corner--tr { top: 12px; right: 12px; }
.hero__corner--bl { bottom: 12px; left: 12px; }
.hero__corner--br { bottom: 12px; right: 12px; }

.hero__corner svg {
  width: 100%;
  height: 100%;
  overflow: visible;
  opacity: .65;
}

.hero__corner--tl { animation-delay: 1.1s; }
.hero__corner--tr { animation-delay: 1.18s; }
.hero__corner--bl { animation-delay: 1.26s; }
.hero__corner--br { animation-delay: 1.34s; }

@keyframes cornerMarkIn {
  from { opacity: 0; transform: scale(.85); }
  to   { opacity: 1; transform: scale(1); }
}

.app--voice-quiet .hero__corner { color: var(--blue); }
.app--voice-human .hero__corner { color: var(--coral); }
.app--voice-bold  .hero__corner { color: var(--acid); }

/* The plate stamp signs the impression in a single quiet line,
   centred above the title. It reads as a pressman's note, not as
   a label. The rules that bracket the line are barely visible. */

.hero__plate-stamp {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.4vw, 18px);
  width: clamp(280px, 70%, 720px);
  margin: 0 auto clamp(2px, .4vw, 6px);
  opacity: 0;
  animation: plateStampIn .8s var(--ease-out) .9s forwards;
}

.hero__plate-stamp-rule {
  display: block;
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 80%);
  opacity: .7;
}

.hero__plate-stamp-rule:last-of-type {
  background: linear-gradient(to left, transparent, var(--line) 80%);
}

.hero__plate-stamp-core {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--paper);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: .72;
}

.hero__plate-stamp-line {
  display: inline-block;
  white-space: nowrap;
}

.hero__plate-stamp-line em {
  color: var(--coral);
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: -.005em;
  text-transform: none;
  transition: color .45s var(--ease);
}

.app--voice-quiet .hero__plate-stamp-line em { color: var(--blue); }
.app--voice-human .hero__plate-stamp-line em { color: var(--coral); }
.app--voice-bold  .hero__plate-stamp-line em { color: var(--acid); }

@keyframes plateStampIn {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: .72; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .hero__corner,
  .hero__plate-stamp {
    animation: none !important;
    opacity: .65 !important;
    transform: none !important;
  }
}

/* The plate frame is the gentle box that holds the proof. A
   single soft inset replaces the heavy ::before/::after stack
   so the title breathes inside an honest paper margin. */

.hero__spread {
  position: relative;
}

.hero__spread::before {
  inset: 6px;
  border-color: rgba(146, 186, 255, .075);
}

.hero__spread::after {
  inset: 14px;
  border-color: rgba(243, 236, 214, .03);
}

/* The title tokens now sit on the same baseline as the rest of
   the line and inherit the voice tone with restraint. The
   coloured underline reads as a printer's mark, not as a link. */

.title-token {
  position: relative;
  display: inline-block;
  padding: 0 .02em .04em;
  background: transparent;
  font-family: inherit;
  font-style: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  line-height: inherit;
  cursor: pointer;
  transition:
    color .35s var(--ease),
    background-color .35s var(--ease),
    border-color .35s var(--ease),
    text-shadow .45s var(--ease);
}

.title-token--m3,
.title-token--good,
.title-token--yet {
  color: var(--paper);
  border-bottom: 0;
  background-image: linear-gradient(
    to right,
    transparent 0%,
    currentColor 8%,
    currentColor 92%,
    transparent 100%
  );
  background-repeat: no-repeat;
  background-position: 0 100%;
  background-size: 100% 1.5px;
}

.title-token--m3 { background-image: linear-gradient(to right, transparent, var(--acid), transparent); }
.title-token--good { background-image: linear-gradient(to right, transparent, var(--coral), transparent); }
.title-token--yet { background-image: linear-gradient(to right, transparent, var(--blue), transparent); }

.app--word-m3 .title-token--m3,
.title-token--m3.is-selected {
  color: var(--acid);
}

.app--word-good .title-token--good,
.title-token--good.is-selected {
  color: var(--coral);
}

.app--word-yet .title-token--yet,
.title-token--yet.is-selected {
  color: var(--blue);
}

.title-token__halo {
  position: absolute;
  left: 50%;
  top: 52%;
  width: 1.4em;
  height: 1.4em;
  border-radius: 50%;
  background: var(--acid);
  opacity: 0;
  transform: translate(-50%, -50%) scale(.4);
  filter: blur(14px);
  pointer-events: none;
  transition: opacity .45s var(--ease), transform .75s var(--ease-spring);
  z-index: -1;
}

.title-token--good .title-token__halo { background: var(--coral); }
.title-token--yet  .title-token__halo { background: var(--blue); }

.title-token:hover .title-token__halo,
.title-token:focus-visible .title-token__halo,
.title-token.is-selected .title-token__halo {
  opacity: .18;
  transform: translate(-50%, -50%) scale(1);
}

.title-token:hover,
.title-token:focus-visible {
  color: var(--paper);
  text-shadow: 0 0 .55em rgba(216, 255, 106, .2);
}

.title-token--good:hover,
.title-token--good:focus-visible {
  color: var(--paper);
  text-shadow: 0 0 .55em rgba(255, 118, 95, .24);
}

.title-token--yet:hover,
.title-token--yet:focus-visible {
  color: var(--paper);
  text-shadow: 0 0 .55em rgba(155, 188, 255, .24);
}

@media (prefers-reduced-motion: reduce) {
  .title-token__halo { transition: none !important; }
}

/* The compose rule beneath the title is the press line. It now
   arrives with a slightly longer, calmer draw and the trailing
   bead feels like a settled ink drop rather than a target. */

.hero__compose-rule {
  width: clamp(360px, 88%, 1080px);
  margin: clamp(22px, 2.8vw, 38px) auto clamp(10px, 1.1vw, 16px);
  height: 18px;
  color: var(--coral);
  display: block;
}

.hero__compose-rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: composeRuleDraw 1.25s var(--ease-out) .5s forwards;
}

.hero__compose-rule-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: composeRuleBead .5s var(--ease-spring) 1.7s forwards;
}

.hero__compose-rule-bead--ring,
.hero__compose-rule-bead--ring-2 {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: composeRuleRing .6s var(--ease-out) 1.78s forwards;
}

.hero__compose-rule-bead--ring-2 {
  animation-delay: 1.95s;
}

/* The publication mark beneath the rule breathes with a wider
   reach. Its rules extend further into the gutters so the title
   sits between two long, quiet horizons. */

.publication-mark {
  margin-top: clamp(14px, 1.8vw, 22px);
}

/* The hero body summary gains a slightly longer leading and a
   gentler drop cap so the paragraph that sits below the title
   reads as a continuation, not as a caption. */

.hero__summary {
  font-size: clamp(15px, 1.15vw, 17px);
  line-height: 1.62;
  letter-spacing: -.003em;
  max-width: 56ch;
  color: var(--lead-2);
}

.hero__dropcap {
  font-size: clamp(3.4em, 4.6vw, 4.6em);
  line-height: .82;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  padding: .04em .12em .04em 0;
  text-shadow: 0 2px 0 rgba(0, 0, 0, .2);
}

/* The voice tabs beneath the title settle a little closer to the
   plate so the proof reads as one composed strip. */

.hero__voice-row {
  margin-top: clamp(20px, 2.6vw, 32px);
  padding-top: clamp(14px, 1.6vw, 22px);
  border-top: 1px dashed rgba(146, 186, 255, .12);
}

.hero__voice-tab {
  padding: 9px 14px 10px;
  letter-spacing: .02em;
}

.hero__voice-tab-name {
  letter-spacing: .01em;
}

/* The lead-in above the title now sits with a small, deliberate
   gap from the plate stamp so the two quiet lines do not crowd. */

.hero__lead-in {
  margin-bottom: clamp(2px, .4vw, 6px);
}

/* On wide screens the title sits inside a soft proof box. The
   plate frame is a single hairline border, slightly inside the
   spread's own frame. The result is a nested frame: outer spread
   frame, inner proof frame, title centred within both. */

@media (min-width: 980px) {
  .hero__plate {
    padding: clamp(36px, 4.2vw, 60px) clamp(28px, 3.6vw, 48px);
    border: 1px solid rgba(146, 186, 255, .07);
    background:
      linear-gradient(180deg, rgba(28, 36, 52, .08), rgba(14, 20, 32, .14));
    box-shadow: inset 0 0 0 1px rgba(146, 186, 255, .025);
  }
}

/* Mobile: the proof frame stays, the corners settle to the
   inside of the plate, the title sizes down a touch. The result
   is a tight, breathable single column. */

@media (max-width: 720px) {
  .hero__corner { width: 18px; height: 18px; }
  .hero__corner--tl { top: 8px; left: 8px; }
  .hero__corner--tr { top: 8px; right: 8px; }
  .hero__corner--bl { bottom: 8px; left: 8px; }
  .hero__corner--br { bottom: 8px; right: 8px; }

  .hero__plate-stamp-core {
    font-size: 8.5px;
    letter-spacing: .22em;
  }
}

@media (max-width: 540px) {
  .hero__plate-stamp-line em {
    font-size: 11px;
  }

  .hero__plate-stamp {
    width: clamp(240px, 92%, 360px);
  }
}

/* Reduced motion: the corner marks and plate stamp settle
   without their entrance so they read as part of the page. */

@media (prefers-reduced-motion: reduce) {
  .hero__compose-rule-stroke { stroke-dashoffset: 0 !important; animation: none !important; }
  .hero__compose-rule-bead,
  .hero__compose-rule-bead--ring,
  .hero__compose-rule-bead--ring-2 { opacity: 1 !important; animation: none !important; transform: none !important; }
  .hero__compose-rule-bead--ring { opacity: .55 !important; }
  .hero__compose-rule-bead--ring-2 { opacity: .35 !important; }
}

/* ─── title set in three voices ─────────────────────────────── */

/* The three voices inherit a confident rhythm. Quiet reads in a
   small serif italic that feels handwritten but composed. Human
   takes its warm coral ink from the original. Bold is the
   display voice; it answers the question in green. */

.app--voice-quiet .hero__title {
  color: var(--lead-1);
}

.app--voice-human .hero__title {
  color: var(--coral);
}

.app--voice-bold .hero__title {
  color: var(--acid);
}

/* The body copy below the title reads in a longer, calmer line
   that matches the page's prose rhythm. */

.hero__continue {
  margin-top: clamp(24px, 2.4vw, 32px);
  padding-top: clamp(18px, 1.8vw, 24px);
  border-top: 1px solid rgba(146, 186, 255, .08);
}

.hero__continue-imprint {
  letter-spacing: .02em;
  color: var(--muted);
}

.hero__continue-arrow {
  letter-spacing: .01em;
}

/* On narrow screens the lead-in settles into a single line. */

@media (max-width: 540px) {
  .hero__lead-in {
    gap: 10px;
    font-size: 9px;
    letter-spacing: .22em;
  }
}


/* ────────────────────────────────────────────────────────────
   ITERATION 241 · the singular question

   The page settles into a single, beautifully typeset broadsheet.
   - a refined paper-grain canvas drifts behind the page
   - the title seal replaces three competing chrome rows with one
   - the site-header loses its second row and the running map moves
     down to share the room with a thin set/folio meta
   - the press lever sits in a heavier, more confident armature
   - mobile typography gets tighter, more breathable space
   - the marked words wear a calmer halo and a hand-traced caret
   ──────────────────────────────────────────────────────────── */

/* Paper grain · a quiet canvas of slow drifting motes. */

.paper-grain {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  mix-blend-mode: soft-light;
  opacity: .42;
}

@media (prefers-reduced-motion: reduce) {
  .paper-grain {
    display: none;
  }
}

/* Site header · one row, not two. The reading map keeps its line
   but shares the room with a quiet set / folio meta strip. The
   back link replaces the second row's call-to-action. */

.site-header {
  padding: 10px var(--gutter) 0;
}

.site-header__row--primary {
  padding: 6px 0 12px;
  grid-template-columns: minmax(180px, 1fr) minmax(0, 2fr) minmax(140px, auto);
}

.site-header__row--map {
  padding: 10px 0 12px;
  gap: clamp(12px, 1.8vw, 22px);
}

.site-header__back {
  justify-self: end;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px 9px;
  border: 1px solid var(--line);
  border-radius: 1px;
  color: var(--paper);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .32), rgba(14, 20, 32, .42));
  transition: border-color .4s var(--ease), color .4s var(--ease), background .4s var(--ease);
}

.site-header__back svg {
  width: 12px;
  height: 12px;
  color: currentColor;
}

.site-header__back:hover,
.site-header__back:focus-visible {
  color: var(--acid);
  border-color: rgba(216, 255, 106, .3);
}

.app--voice-quiet .site-header__back:hover,
.app--voice-quiet .site-header__back:focus-visible {
  color: var(--blue);
  border-color: rgba(155, 188, 255, .3);
}

.app--voice-human .site-header__back:hover,
.app--voice-human .site-header__back:focus-visible {
  color: var(--coral);
  border-color: rgba(255, 118, 95, .3);
}

.app--voice-bold .site-header__back:hover,
.app--voice-bold .site-header__back:focus-visible {
  color: var(--acid);
  border-color: rgba(216, 255, 106, .3);
}

.site-header__map-meta {
  justify-self: end;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
}

@media (max-width: 880px) {
  .site-header__row--primary {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .site-header__running {
    display: none;
  }

  .site-header__back {
    justify-self: end;
  }
}

@media (max-width: 540px) {
  .site-header__back span {
    display: none;
  }

  .site-header__back {
    padding: 8px 10px;
  }

  .site-header__map-meta {
    font-size: 8px;
    letter-spacing: .18em;
  }
}

/* Hero spread · calmer, more breathable title page. */

.hero {
  padding-top: clamp(48px, 6vw, 84px);
}

.hero__spread {
  padding: clamp(60px, 7vw, 96px) clamp(20px, 3vw, 56px) clamp(36px, 4vw, 60px);
}

.hero__copy {
  gap: clamp(22px, 2.6vw, 36px);
}

.hero__title {
  font-size: clamp(2.6rem, 8vw, 7.4rem);
  line-height: .94;
  letter-spacing: -.054em;
  font-weight: 400;
}

.hero__title--quiet {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.04em;
  color: var(--lead-1);
}

.hero__title--human {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.048em;
  color: var(--coral);
}

.hero__title--bold {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 600;
  letter-spacing: -.08em;
  color: var(--acid);
  text-transform: none;
}

.hero__title .title__line {
  display: block;
}

.hero__title .title__line:nth-child(2) {
  padding-left: clamp(8px, 1.2vw, 18px);
}

.hero__title .title__line:last-child {
  padding-left: clamp(14px, 1.8vw, 28px);
}

@media (max-width: 720px) {
  .hero__title .title__line:nth-child(2),
  .hero__title .title__line:last-child {
    padding-left: 0;
  }
}

/* Title tokens · the marked words receive a hand-traced caret
   that appears beside the word when it is the active mark. The
   halo softens and a small caret-mark sits to the upper-left. */

.title-token {
  position: relative;
  display: inline-block;
}

.title-token::after {
  content: '';
  position: absolute;
  left: -0.42em;
  top: 0.16em;
  width: 0.18em;
  height: 0.4em;
  border: 1.2px solid currentColor;
  border-right: 0;
  border-bottom: 0;
  opacity: 0;
  transform: translateX(2px);
  transition: opacity .4s var(--ease), transform .55s var(--ease-out);
  pointer-events: none;
}

.title-token.is-selected::after,
.app--word-m3 .title-token--m3::after,
.app--word-good .title-token--good::after,
.app--word-yet .title-token--yet::after {
  opacity: .8;
  transform: translateX(0);
}

.title-token__halo {
  filter: blur(20px);
}

.title-token.is-selected .title-token__halo,
.app--word-m3 .title-token--m3 .title-token__halo,
.app--word-good .title-token--good .title-token__halo,
.app--word-yet .title-token--yet .title-token__halo {
  opacity: .22;
  transform: translate(-50%, -50%) scale(1.05);
}

/* The title seal · a single elegant mark beneath the title
   that closes the page with press, voice, mark, and date in
   one confident row. */

.title-seal {
  --seal-tone: var(--coral);
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(8px, 1vw, 12px);
  width: clamp(320px, 92%, 1040px);
  margin: clamp(2px, .4vw, 6px) auto 0;
  color: var(--seal-tone);
  opacity: 0;
  animation: titleSealIn .9s var(--ease-out) .55s forwards;
}

.title-seal__rule,
.title-seal__sweep {
  display: block;
  width: 100%;
  color: var(--seal-tone);
}

.title-seal__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1.15fr) auto minmax(0, 1fr);
  align-items: stretch;
  gap: clamp(8px, 1.2vw, 18px);
  padding: clamp(8px, 1.2vw, 14px) clamp(12px, 1.6vw, 20px);
  border: 1px solid var(--line);
  border-radius: 1px;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .22), rgba(14, 20, 32, .34)),
    radial-gradient(circle at 20% 50%, rgba(216, 255, 106, .025), transparent 50%);
  transition: border-color .55s var(--ease), background .55s var(--ease);
}

.app--voice-quiet .title-seal__row {
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .22), rgba(14, 20, 32, .34)),
    radial-gradient(circle at 20% 50%, rgba(155, 188, 255, .04), transparent 50%);
}

.app--voice-human .title-seal__row {
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .22), rgba(14, 20, 32, .34)),
    radial-gradient(circle at 20% 50%, rgba(255, 118, 95, .04), transparent 50%);
}

.app--voice-bold .title-seal__row {
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .22), rgba(14, 20, 32, .34)),
    radial-gradient(circle at 20% 50%, rgba(216, 255, 106, .06), transparent 50%);
}

.title-seal__row:hover {
  border-color: rgba(146, 186, 255, .14);
}

.title-seal__cell {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  min-width: 0;
}

.title-seal__cell-tag {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .26em;
  text-transform: uppercase;
  white-space: nowrap;
}

.title-seal__cell-main {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(13px, 1vw, 15px);
  font-style: italic;
  letter-spacing: -.005em;
  line-height: 1.1;
}

.title-seal__cell-foot {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
  white-space: nowrap;
}

.title-seal__divider {
  align-self: stretch;
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 14%, var(--line) 86%, transparent);
}

.title-seal__press-mark {
  width: 18px;
  height: 18px;
  color: var(--seal-tone);
  flex: 0 0 auto;
}

.title-seal__press-name {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: inherit;
  white-space: nowrap;
}

.title-seal__voice-letter {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid var(--seal-tone);
  border-radius: 50%;
  color: var(--seal-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  line-height: 1;
  letter-spacing: 0;
  text-transform: none;
  flex: 0 0 auto;
  transition: transform .4s var(--ease-spring);
}

.title-seal__voice-name {
  white-space: nowrap;
}

.title-seal__date-text {
  white-space: nowrap;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1vw, 15px);
  letter-spacing: -.005em;
}

.title-seal__sweep {
  height: 14px;
  opacity: .7;
}

.title-seal__sweep-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titleSealSweepDraw 1.1s var(--ease-out) 1.05s forwards;
}

.title-seal__sweep-dot {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: titleSealSweepDot .4s var(--ease-spring) 2.1s forwards;
}

@keyframes titleSealIn {
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes titleSealSweepDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes titleSealSweepDot {
  0% { opacity: 0; transform: scale(.4); }
  100% { opacity: 1; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .title-seal {
    animation: none !important;
    opacity: 1;
