/* ────────────────────────────────────────────────────────────
   ITERATION 242 · the marginal ledger

   A thin vertical pencil rule runs down the left edge of the
   hero plate. Three small proof-ticks sit beside the three
   marked words in the title, each carrying the mark an editor
   would set in the margin (stet, caret, query). The rule
   arrives with a quiet draw, the active tick grows and inks
   itself in its voice colour. On narrow screens the ledger
   collapses below the title and reads as a small proof tape.
   ──────────────────────────────────────────────────────────── */

.marginal-ledger {
  --ledger-tone: var(--paper);
  --ledger-ink: var(--paper);
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(14px, 1.6vw, 22px);
  width: clamp(58px, 8vw, 78px);
  min-width: 58px;
  padding: clamp(6px, .8vw, 10px) 0 clamp(6px, .8vw, 10px);
  align-self: stretch;
  opacity: 0;
  animation: marginalLedgerIn .9s var(--ease-out) .55s forwards;
  pointer-events: auto;
}

@keyframes marginalLedgerIn {
  0% { opacity: 0; transform: translateX(-6px); }
  100% { opacity: 1; transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .marginal-ledger { animation: none !important; opacity: 1 !important; transform: none !important; }
}

.marginal-ledger__head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid color-mix(in srgb, var(--ledger-tone) 18%, transparent);
}

.marginal-ledger__head-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, color-mix(in srgb, var(--ledger-tone) 60%, transparent), transparent);
}

.marginal-ledger__head-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: color-mix(in srgb, var(--ledger-tone) 78%, transparent);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .28em;
  text-transform: uppercase;
  white-space: nowrap;
}

.marginal-ledger__head-dot {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 18%, transparent);
  transition: background .45s var(--ease);
}

.app--voice-quiet .marginal-ledger__head-tag { color: var(--blue); }
.app--voice-human .marginal-ledger__head-tag { color: var(--coral); }
.app--voice-bold .marginal-ledger__head-tag { color: var(--acid); }

.marginal-ledger__list {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(20px, 2.6vw, 32px);
  margin: clamp(6px, .8vw, 10px) 0;
  padding: 0;
  list-style: none;
  z-index: 1;
}

.marginal-ledger__row {
  position: relative;
}

.marginal-ledger__row.is-active::after {
  content: '';
  position: absolute;
  right: -3px;
  top: 50%;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 22%, transparent);
  transform: translateY(-50%);
  z-index: 2;
  animation: ledgerPulse 2.4s var(--ease) infinite;
}

.marginal-ledger__row.is-active::after {
  color: var(--ledger-mark);
}

@keyframes ledgerPulse {
  0%, 100% { box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 22%, transparent), 0 0 0 6px transparent; }
  50% { box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 22%, transparent), 0 0 0 8px color-mix(in srgb, currentColor 12%, transparent); }
}

@media (prefers-reduced-motion: reduce) {
  .marginal-ledger__row.is-active::after { animation: none !important; }
}

.marginal-ledger__tick {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: end;
  align-content: start;
  gap: 3px;
  width: 100%;
  padding: 0;
  background: transparent;
  border: 0;
  cursor: pointer;
  color: var(--paper);
  opacity: .55;
  transition:
    opacity .4s var(--ease),
    color .45s var(--ease),
    transform .45s var(--ease-spring);
}

.marginal-ledger__tick--acid { --ledger-mark: var(--acid); }
.marginal-ledger__tick--coral { --ledger-mark: var(--coral); }
.marginal-ledger__tick--blue { --ledger-mark: var(--blue); }

.marginal-ledger__tick:hover,
.marginal-ledger__tick:focus-visible {
  opacity: 1;
  color: var(--ledger-mark);
}

.marginal-ledger__tick:hover .marginal-ledger__tick-glyph,
.marginal-ledger__tick:focus-visible .marginal-ledger__tick-glyph {
  border-color: currentColor;
  border-right-color: currentColor;
  background:
    linear-gradient(90deg, color-mix(in srgb, currentColor 18%, transparent), color-mix(in srgb, currentColor 4%, transparent));
}

.marginal-ledger__tick:hover .marginal-ledger__tick-glyph::after,
.marginal-ledger__tick:focus-visible .marginal-ledger__tick-glyph::after {
  width: 6px;
  opacity: .85;
}

.marginal-ledger__row.is-past .marginal-ledger__tick {
  opacity: .78;
  color: var(--ledger-mark);
}

.marginal-ledger__row.is-active .marginal-ledger__tick {
  opacity: 1;
  color: var(--ledger-mark);
  transform: translateX(-3px);
}

.marginal-ledger__tick-glyph {
  display: inline-grid;
  place-items: center;
  width: clamp(28px, 3vw, 36px);
  height: clamp(22px, 2.2vw, 26px);
  border: 1px solid color-mix(in srgb, currentColor 50%, transparent);
  border-right: 1px solid currentColor;
  border-radius: 1px 0 0 1px;
  background:
    linear-gradient(90deg, color-mix(in srgb, currentColor 14%, transparent), color-mix(in srgb, currentColor 4%, transparent));
  position: relative;
}

.marginal-ledger__tick-glyph::after {
  content: '';
  position: absolute;
  right: -1px;
  top: 50%;
  width: 4px;
  height: 1px;
  background: currentColor;
  transform: translateY(-50%);
