}

.marginal-ledger__row.is-past .marginal-ledger__tick-label,
.marginal-ledger__row.is-active .marginal-ledger__tick-label {
  color: var(--paper);
}

.marginal-ledger__row.is-active .marginal-ledger__tick-glyph {
  border-color: currentColor;
  border-right-color: currentColor;
  background:
    linear-gradient(90deg, color-mix(in srgb, currentColor 26%, transparent), color-mix(in srgb, currentColor 6%, transparent));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 26%, transparent);
}

.marginal-ledger__row.is-active .marginal-ledger__tick-glyph::after {
  width: 7px;
  opacity: 1;
}

.marginal-ledger__row.is-active .marginal-ledger__tick-label {
  color: var(--ledger-mark);
}

.marginal-ledger__rule {
  position: absolute;
  top: clamp(24px, 2.6vw, 32px);
  bottom: clamp(28px, 3.2vw, 40px);
  right: 0;
  width: 1px;
  z-index: 0;
  color: color-mix(in srgb, var(--ledger-tone) 40%, transparent);
  pointer-events: none;
}

.marginal-ledger__rule svg {
