}

@keyframes marginalLedgerDraw {
  0% { stroke-dashoffset: 240; opacity: 0; }
  100% { stroke-dashoffset: 0; opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .marginal-ledger__rule line { animation: none !important; stroke-dashoffset: 0 !important; }
