/* ────────────────────────────────────────────────────────────
   TITLE TRACE · a quiet horizontal rule that threads under
   the title and lands a small bead on each marked word. It
   becomes the hero's reading trace, replacing the heavier
   underline marks that previously sat under each token.
   ──────────────────────────────────────────────────────────── */

.title-trace {
  display: block;
  width: clamp(540px, 88%, 1180px);
  height: clamp(20px, 2.2vw, 28px);
  margin: clamp(2px, .4vw, 8px) auto clamp(8px, 1vw, 16px);
  color: var(--trace-tone, var(--coral));
  opacity: 0;
  transition: color .5s var(--ease);
  animation: titleTraceIn .55s var(--ease-out) .7s forwards;
}

.title-trace__rule {
  stroke-dasharray: 1200 1200;
  stroke-dashoffset: 1200;
  animation: titleTraceDraw 1.2s var(--ease-out) .85s forwards;
}

.title-trace__node {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: titleTraceNodeIn .5s var(--ease-spring) forwards;
}

.title-trace__node--m3 { animation-delay: 1.05s; }
.title-trace__node--good { animation-delay: 1.25s; }
.title-trace__node--yet { animation-delay: 1.45s; }

.title-trace__node-pulse {
  transform-box: fill-box;
  transform-origin: center;
  animation: titleTracePulse 3.4s var(--ease) infinite;
}

.title-trace__node--m3 .title-trace__node-pulse { animation-delay: 2.2s; }
.title-trace__node--good .title-trace__node-pulse { animation-delay: 2.4s; }
.title-trace__node--yet .title-trace__node-pulse { animation-delay: 2.6s; }

.title-trace__node--m3 .title-trace__node-bead,
.title-trace__node--m3 .title-trace__node-ring,
.title-trace__node--m3 .title-trace__node-pulse,
.title-trace__node--m3 .title-trace__label,
.title-trace__node--m3 line { color: var(--acid); }
.title-trace__node--good .title-trace__node-bead,
.title-trace__node--good .title-trace__node-ring,
.title-trace__node--good .title-trace__node-pulse,
.title-trace__node--good .title-trace__label,
.title-trace__node--good line { color: var(--coral); }
.title-trace__node--yet .title-trace__node-bead,
.title-trace__node--yet .title-trace__node-ring,
.title-trace__node--yet .title-trace__node-pulse,
.title-trace__node--yet .title-trace__label,
.title-trace__node--yet line { color: var(--blue); }

.title-trace__node.is-active .title-trace__node-ring {
  opacity: 1;
}

.title-trace__node.is-active .title-trace__node-bead {
  filter: drop-shadow(0 0 5px currentColor);
}

.title-trace__label {
  opacity: 0;
  animation: titleTraceLabel .4s var(--ease-out) forwards;
}

.title-trace__node--m3 .title-trace__label { animation-delay: 1.45s; }
.title-trace__node--good .title-trace__label { animation-delay: 1.65s; }
.title-trace__node--yet .title-trace__label { animation-delay: 1.85s; }

@keyframes titleTraceIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes titleTraceDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes titleTraceNodeIn {
  from { opacity: 0; transform: scale(.35); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes titleTracePulse {
  0%, 100% { transform: scale(1); opacity: 0; }
  50% { transform: scale(1.7); opacity: .35; }
}

@keyframes titleTraceLabel {
  from { opacity: 0; transform: translateY(-2px); }
  to { opacity: .8; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .title-trace__rule,
  .title-trace__node,
  .title-trace__node-pulse,
  .title-trace__label {
    animation: none !important;
    opacity: 1;
    stroke-dashoffset: 0;
  }
}

@media (max-width: 720px) {
  .title-trace {
    height: clamp(22px, 4vw, 32px);
    margin-bottom: 6px;
  }
}

/* ────────────────────────────────────────────────────────────
   COMPOSE PLATE · a single quiet signature that sits below
   the title in the hero spread. It carries the page's identity
   and replaces the previous kept-mark + pull combination, so
   the title has one confident signature instead of two.
   ──────────────────────────────────────────────────────────── */

.compose-plate {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.6vw, 22px);
  width: clamp(420px, 82%, 980px);
  margin: clamp(10px, 1.6vw, 22px) auto 0;
  padding: 6px 0 4px;
  color: var(--plate-tone, var(--coral));
  opacity: 0;
  animation: composePlateIn .7s var(--ease-out) 1.55s forwards;
}

.compose-plate__rule {
  position: absolute;
  inset: 0 0 auto 0;
  width: 100%;
  height: 2px;
  color: var(--line);
}

.compose-plate__edge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 14px;
  color: currentColor;
  opacity: .85;
}

.compose-plate__edge svg {
  display: block;
  width: 100%;
  height: 100%;
}

.compose-plate__cell {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.compose-plate__cell--left {
  justify-content: flex-end;
}

.compose-plate__cell--right {
  justify-content: flex-start;
}

.compose-plate__rule-soft {
  display: block;
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line), transparent);
  opacity: .85;
}

.compose-plate__cell--left .compose-plate__rule-soft {
  background: linear-gradient(to right, transparent, var(--line));
}

.compose-plate__cell--right .compose-plate__rule-soft {
  background: linear-gradient(to left, transparent, var(--line));
}

.compose-plate__tag {
  display: inline-block;
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 10px);
  letter-spacing: .24em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: .82;
}

.compose-plate__monogram {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: clamp(58px, 6vw, 78px);
  height: clamp(28px, 3vw, 38px);
  color: currentColor;
  flex: 0 0 auto;
}

.compose-plate__monogram svg {
  display: block;
  width: 100%;
  height: 100%;
  transition: transform .6s var(--ease-spring);
}

.compose-plate:hover .compose-plate__monogram svg {
  transform: rotate(-4deg);
}

.compose-plate__caption {
  grid-column: 1 / -1;
  display: flex;
  align-items: baseline;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(8px, 1vw, 14px) clamp(10px, 1.2vw, 18px);
  margin: 6px 0 0;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(13.5px, 1.15vw, 16px);
  font-style: italic;
  letter-spacing: -.005em;
  text-align: center;
  line-height: 1.2;
}

.compose-plate__caption-eyebrow {
  color: var(--muted);
  font-family: var(--mono);
  font-style: normal;
  font-size: 8.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.compose-plate__caption-mark {
  color: var(--muted);
  font-family: var(--serif);
  font-style: normal;
  font-size: clamp(14px, 1.2vw, 17px);
  opacity: .55;
}

.compose-plate__caption em {
  color: currentColor;
  font-style: italic;
  font-weight: 500;
}

.compose-plate__caption-meta {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, .8vw, 12px);
  font-family: var(--mono);
  font-style: normal;
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.compose-plate__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0;
}

.compose-plate__chip em {
  color: currentColor;
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
}

.compose-plate__chip-sep {
  color: var(--muted);
  opacity: .45;
}

.compose-plate__chip-letter {
  display: inline-grid;
  place-items: center;
  width: 12px;
  height: 12px;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: currentColor;
  font-family: var(--serif);
  font-style: italic;
  font-size: 8.5px;
}

@keyframes composePlateIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .compose-plate { animation: none !important; opacity: 1; }
}

@media (max-width: 720px) {
  .compose-plate {
    width: clamp(320px, 90%, 720px);
    gap: 8px 12px;
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .compose-plate__cell--right {
    grid-row: 2;
    grid-column: 2 / 3;
    justify-content: center;
  }

  .compose-plate__cell--left {
    grid-row: 2;
    grid-column: 1 / 3;
    justify-content: center;
    border-right: 0;
  }

  .compose-plate__monogram {
    grid-row: 1;
    grid-column: 2 / 3;
  }

  .compose-plate__edge--start {
    grid-row: 1;
    grid-column: 1;
  }

  .compose-plate__edge--end {
    grid-row: 1;
    grid-column: 3;
  }

  .compose-plate__cell--left .compose-plate__rule-soft,
  .compose-plate__cell--right .compose-plate__rule-soft {
    display: none;
  }

  .compose-plate__caption {
    font-size: 12.5px;
  }
}

@media (max-width: 540px) {
  .compose-plate__caption {
    font-size: 11.5px;
    gap: 6px 10px;
  }

  .compose-plate__caption-meta {
    font-size: 8px;
    letter-spacing: .18em;
  }
}

/* ────────────────────────────────────────────────────────────
   ITERATION 248 · an unmistakable opening.

   The hero's voice gets quieter confidence. The title's italic
   is more deliberate (a touch more letter-spacing and breathing
   room), the marginal ledger is further trimmed so the title
   carries the page, the compose plate earns a hand-set
   colophon rule, and the hero spread gets a single page-end
   ornament — a quiet bookplate that ties the title page to the
   body of the page. On narrow widths the ornament becomes a
   hairline that the eye follows into the next section.
   ──────────────────────────────────────────────────────────── */

.hero__title {
  font-feature-settings: 'kern' 1, 'liga' 1, 'dlig' 1, 'onum' 1, 'ss01' 1, 'salt' 1, 'calt' 1;
  letter-spacing: -.1em;
}

.hero__title--quiet,
.hero__title--human {
  letter-spacing: -.094em;
  line-height: .92;
  font-feature-settings: 'kern' 1, 'liga' 1, 'dlig' 1, 'onum' 1, 'swsh' 1, 'salt' 1, 'calt' 1, 'ss01' 1;
  font-style: italic;
  font-weight: 400;
  text-shadow:
    0 1px 0 rgba(0, 0, 0, .42),
    0 6px 22px rgba(0, 0, 0, .5),
    0 22px 60px rgba(0, 0, 0, .28);
}

.hero__title--quiet em,
.hero__title--human em {
  font-style: italic;
}

.app--voice-quiet .hero__title--quiet {
  text-shadow:
    0 1px 0 rgba(0, 0, 0, .4),
    0 6px 22px rgba(0, 0, 0, .46),
    0 22px 60px rgba(0, 0, 0, .24),
    0 0 60px rgba(146, 186, 255, .12);
}

.app--voice-human .hero__title--human {
  text-shadow:
    0 1px 0 rgba(0, 0, 0, .42),
    0 6px 22px rgba(60, 16, 10, .5),
    0 22px 60px rgba(60, 16, 10, .32),
    0 0 70px rgba(255, 118, 95, .14);
}

.hero__title .title__line {
  padding-left: .02em;
  text-wrap: balance;
}

.hero__title .title__line:nth-child(2) {
  padding-left: .04em;
  letter-spacing: -.002em;
}

/* the title's swash warmth is most felt on the second and third
   lines, where the italic letters can carry a faint tail. */

.hero__title--quiet .title__line:nth-child(3),
.hero__title--human .title__line:nth-child(3) {
  padding-left: 0;
}

@media (prefers-reduced-motion: reduce) {
  .hero__title,
  .hero__title--quiet,
  .hero__title--human,
  .hero__title--bold {
    text-shadow:
      0 1px 0 rgba(0, 0, 0, .42),
      0 6px 18px rgba(0, 0, 0, .5);
  }
}

/* ──── MARGINAL LEDGER · trimmed further ──── */

.marginal-ledger {
  opacity: .86;
  transition: opacity .45s var(--ease);
}

.marginal-ledger:hover,
.marginal-ledger:focus-within {
  opacity: 1;
}

.marginal-ledger__head {
  margin-bottom: clamp(4px, .6vw, 8px);
}

.marginal-ledger__head-eyebrow {
  font-size: 8.5px;
  letter-spacing: .28em;
}

.marginal-ledger__tick {
  padding: 3px 0;
  gap: 1px;
}

.marginal-ledger__tick-num {
  font-size: 7px;
  opacity: .5;
}

.marginal-ledger__tick-label {
  font-size: clamp(10px, .82vw, 11.5px);
  font-style: italic;
  font-family: var(--serif);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
  opacity: .85;
}

.marginal-ledger__row.is-active .marginal-ledger__tick-label {
  font-style: italic;
  opacity: 1;
  color: currentColor;
}

.marginal-ledger__rule {
  opacity: .22;
}

.marginal-ledger__foot {
  margin-top: clamp(8px, 1vw, 14px);
  padding-right: 4px;
  font-style: italic;
  font-family: var(--serif);
  font-size: clamp(9.5px, .78vw, 11px);
  letter-spacing: -.005em;
  text-transform: none;
  opacity: .68;
}

.marginal-ledger__foot em {
  color: var(--paper);
  font-style: italic;
}

.marginal-ledger__scribble {
  margin-top: clamp(6px, .8vw, 12px);
  opacity: .4;
}

/* ──── COMPOSE PLATE · a hand-set colophon rule ──── */

.compose-plate__caption {
  letter-spacing: -.002em;
}

.compose-plate__caption em {
  font-feature-settings: 'kern' 1, 'liga' 1, 'dlig' 1;
}

.compose-plate__caption-mark {
  display: inline-block;
  transform: translateY(2px);
  font-size: clamp(16px, 1.4vw, 20px);
  opacity: .4;
}

.compose-plate__monogram {
  transition: transform .6s var(--ease-spring);
}

.compose-plate__monogram svg text:first-of-type {
  letter-spacing: 2.4px;
  font-weight: 600;
}

.compose-plate:hover .compose-plate__monogram svg {
  transform: rotate(-5deg) scale(1.02);
}

/* ──── READER NOTE · more elegant typography ──── */

.reader-note__title {
  letter-spacing: -.018em;
  font-feature-settings: 'kern' 1, 'liga' 1, 'dlig' 1, 'onum' 1;
}

.reader-note__body {
  letter-spacing: -.002em;
}

.reader-note__pull em {
  letter-spacing: -.002em;
  font-feature-settings: 'kern' 1, 'liga' 1, 'dlig' 1;
}

/* ──── HERO PRESS FLOURISH · a single delicate rule + tag ──── */

.hero__press-flourish {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: min(100%, 540px);
  margin: clamp(18px, 2.4vw, 30px) auto 0;
  color: var(--lamp);
}

.app--voice-quiet .hero__press-flourish { color: var(--blue); }
.app--voice-human .hero__press-flourish { color: var(--coral); }
.app--voice-bold .hero__press-flourish { color: var(--acid); }

.hero__press-flourish-rule {
  display: block;
  width: clamp(220px, 32vw, 360px);
  height: 12px;
  opacity: .9;
}

.hero__press-flourish-stroke {
  stroke-dasharray: 720 720;
  stroke-dashoffset: 720;
  animation: heroFlourishDraw 1.4s var(--ease-out) 1.45s forwards;
}

@keyframes heroFlourishDraw {
  to { stroke-dashoffset: 0; }
}

.hero__press-flourish-dot {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: heroFlourishDot .4s var(--ease-spring) 2.7s forwards;
}

@keyframes heroFlourishDot {
  0% { opacity: 0; transform: scale(.3); }
  100% { opacity: 1; transform: scale(1); }
}

.hero__press-flourish-tag {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: .002em;
  line-height: 1;
  opacity: 0;
  animation: heroFlourishTagIn .6s var(--ease-out) 2.95s forwards;
}

@keyframes heroFlourishTagIn {
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: .9; transform: translateY(0); }
}

.hero__press-flourish-tag-mark {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .85;
}

.app--voice-quiet .hero__press-flourish-tag-mark { background: var(--blue); opacity: .7; }
.app--voice-human .hero__press-flourish-tag-mark { background: var(--coral); opacity: .7; }
.app--voice-bold .hero__press-flourish-tag-mark { background: var(--acid); opacity: .7; }

@media (prefers-reduced-motion: reduce) {
  .hero__press-flourish-stroke,
  .hero__press-flourish-dot,
  .hero__press-flourish-tag {
    animation: none !important;
    stroke-dashoffset: 0 !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

@media (max-width: 720px) {
  .hero__press-flourish {
    margin-top: clamp(14px, 2vw, 22px);
  }

  .hero__press-flourish-rule {
    width: clamp(180px, 56vw, 280px);
  }

  .hero__press-flourish-tag {
    font-size: 10.5px;
  }
}

@media (max-width: 540px) {
  .title__question-period {
    width: .52em;
    height: .52em;
  }
}

/* ──── TITLE QUESTION · a pair of glyphs with a press-period that
   appears beneath the question mark when the answer is tipped in.
   The mark is the page's signature of "this is where the answer lives". */

.title__question {
  position: relative;
  display: inline-block;
  margin-left: .04em;
  vertical-align: baseline;
  line-height: inherit;
  color: inherit;
}

.title__question-glyph {
  display: inline-block;
  font-family: inherit;
  font-style: inherit;
  font-weight: inherit;
  line-height: inherit;
  letter-spacing: inherit;
  transition: transform .55s var(--ease-spring), color .5s var(--ease), text-shadow .5s var(--ease);
}

.title__question-period {
  position: absolute;
  left: 50%;
  bottom: -0.18em;
  transform: translate(-50%, 0) scale(0);
  width: .42em;
  height: .42em;
  border-radius: 50%;
  background: var(--ink);
  box-shadow:
    0 0 0 1.5px var(--coral),
    0 0 0 3px rgba(240, 110, 91, .15),
    0 0 12px rgba(240, 110, 91, .35);
  opacity: 0;
  transition:
    opacity .55s var(--ease) .1s,
    transform .7s var(--ease-spring) .1s,
    box-shadow .65s var(--ease);
  pointer-events: none;
}

.app--voice-quiet .title__question-period {
  box-shadow:
    0 0 0 1.5px var(--blue),
    0 0 0 3px rgba(155, 188, 255, .15),
    0 0 12px rgba(155, 188, 255, .35);
}

.app--voice-bold .title__question-period {
  box-shadow:
    0 0 0 1.5px var(--acid),
    0 0 0 3px rgba(216, 240, 106, .15),
    0 0 12px rgba(216, 240, 106, .35);
}

.title__question.is-sealed .title__question-glyph {
  transform: translateY(-1px);
  text-shadow: 0 0 .5em rgba(240, 110, 91, .32);
}

.title__question.is-sealed .title__question-period {
  opacity: 1;
  transform: translate(-50%, 0) scale(1);
}

.app--voice-quiet .title__question.is-sealed .title__question-glyph {
  text-shadow: 0 0 .5em rgba(155, 188, 255, .32);
}

.app--voice-bold .title__question.is-sealed .title__question-glyph {
  text-shadow: 0 0 .5em rgba(216, 240, 106, .32);
}

@media (prefers-reduced-motion: reduce) {
  .title__question-period,
  .title__question-glyph {
    transition: none !important;
  }
}

/* ──── HERO SPREAD · overall composition refresh ──── */

.hero__spread {
  --hero-spread-tone: var(--coral);
}

.hero__spread > .hero__copy {
  gap: clamp(20px, 2.6vw, 36px);
}

.hero__title .title__line {
  animation-duration: .85s;
}

.hero__chrome {
  margin-top: clamp(24px, 3.4vw, 44px);
}

/* ──── PRESS STRIKE · a small breath when the lever pulls ──── */

.app--voice-quiet .hero__spread,
.app--voice-human .hero__spread,
.app--voice-bold .hero__spread {
  animation: heroSpreadBreath .9s var(--ease-out);
}

@keyframes heroSpreadBreath {
  0% { transform: scale(1.005); filter: brightness(1.04) saturate(1.06); }
  35% { transform: scale(1); filter: brightness(1) saturate(1); }
  100% { transform: scale(1); filter: brightness(1) saturate(1); }
}

@media (prefers-reduced-motion: reduce) {
  .app--voice-quiet .hero__spread,
  .app--voice-human .hero__spread,
  .app--voice-bold .hero__spread {
    animation: none !important;
  }
}

/* ──── MOBILE · hero composition polish ──── */

@media (max-width: 720px) {
  .hero {
    padding-top: clamp(28px, 4vw, 56px);
  }

  .hero__spread {
    padding: clamp(64px, 8vw, 96px) clamp(18px, 4vw, 36px) clamp(40px, 6vw, 56px);
  }

  .hero__chrome {
    gap: clamp(10px, 1.6vw, 16px);
  }

  .hero__body {
    margin-top: clamp(36px, 4.6vw, 56px);
  }
}

@media (max-width: 540px) {
  .hero__title,
  .hero__title--quiet,
  .hero__title--human,
  .hero__title--bold {
    letter-spacing: -.094em;
  }

  .hero__title--quiet,
  .hero__title--human {
    line-height: .94;
    letter-spacing: -.088em;
  }

  .hero__title--bold {
    letter-spacing: -.118em;
    line-height: .86;
  }
}


/* ────────────────────────────────────────────────────────────
   ITERATION 249 · A single quiet wayfinder
   The site header collapses to one row; the right-edge margin
   thread becomes a pressed seal that opens a folio index on
   demand. The mobile nav is folded into the same seal.
   ──────────────────────────────────────────────────────────── */

.site-header--single {
  padding: clamp(18px, 2.6vw, 28px) clamp(22px, 5vw, 96px) clamp(10px, 1.4vw, 16px);
  border-bottom: 1px solid transparent;
  transition: border-color .5s var(--ease);
}

.site-header--single::after {
  display: none;
}

.site-header--single .site-header__row--primary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: clamp(14px, 2vw, 28px);
  padding: 0;
}

.site-header__set {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  justify-self: end;
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(9px, .76vw, 10.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .8;
  white-space: nowrap;
}

.site-header__set em {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(11px, .92vw, 13px);
  letter-spacing: -.002em;
  text-transform: none;
  color: var(--paper);
  opacity: 1;
}

.site-header__set-mark {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .55;
}

.site-header__set-mark--alt {
  background: transparent;
  border: 1px solid currentColor;
  opacity: .35;
}

@media (max-width: 880px) {
  .site-header--single .site-header__row--primary {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .site-header__set {
    display: none;
  }
}

@media (max-width: 540px) {
  .site-header--single .site-header__row--primary {
    gap: clamp(10px, 2vw, 14px);
  }
}

/* Wayfinder · a pressed seal that opens a folio index panel. */

.wayfinder {
  --wayfinder-tone: var(--coral);
  position: relative;
  justify-self: end;
  display: inline-flex;
  align-items: center;
}

.wayfinder__seal {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: clamp(54px, 5vw, 68px);
  height: clamp(54px, 5vw, 68px);
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
  color: var(--wayfinder-tone);
  transition: transform .35s var(--ease-spring);
}

.wayfinder__seal:hover,
.wayfinder__seal:focus-visible {
  transform: translateY(-2px);
}

.wayfinder__seal:active {
  transform: translateY(0);
}

.wayfinder__seal-frame {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  transition: box-shadow .4s var(--ease);
}

.wayfinder__seal-svg {
  display: block;
  width: 100%;
  height: 100%;
  color: currentColor;
  transition: transform .5s var(--ease-spring);
}

.wayfinder__seal:hover .wayfinder__seal-svg,
.wayfinder__seal:focus-visible .wayfinder__seal-svg {
  transform: rotate(-6deg);
}

.wayfinder__seal-shine {
  position: absolute;
  inset: 6%;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 22%, rgba(255, 255, 255, .22), transparent 48%);
  pointer-events: none;
  mix-blend-mode: screen;
  opacity: .6;
}

.wayfinder__seal-cue {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgba(243, 236, 214, .06);
  border: 1px solid rgba(243, 236, 214, .14);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .28em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0;
  transform: translate(-50%, 4px);
  transition: opacity .35s var(--ease), transform .35s var(--ease);
  pointer-events: none;
}

.wayfinder__seal:hover .wayfinder__seal-cue,
.wayfinder__seal:focus-visible .wayfinder__seal-cue {
  opacity: .9;
  transform: translate(-50%, 0);
}

.wayfinder__seal-cue-dot {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .6;
}

.wayfinder__seal-cue-line {
  display: inline-block;
  width: 10px;
  height: 1px;
  background: currentColor;
  opacity: .4;
}

.wayfinder__seal-cue-folio {
  font-family: var(--serif);
  font-style: italic;
  font-size: 9.5px;
  letter-spacing: -.01em;
  text-transform: none;
  color: currentColor;
  opacity: .9;
}

.wayfinder.is-open .wayfinder__seal-frame {
  box-shadow:
    0 0 0 1px rgba(243, 236, 214, .12),
    0 12px 28px rgba(0, 0, 0, .42);
}

.wayfinder__panel {
  position: absolute;
  top: calc(100% + 12px);
  right: 0;
  width: clamp(280px, 28vw, 340px);
  padding: clamp(18px, 1.8vw, 22px) clamp(16px, 1.6vw, 20px) clamp(16px, 1.6vw, 20px);
  border: 1px solid rgba(243, 236, 214, .16);
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(28, 29, 39, .94), rgba(14, 15, 21, .96));
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  color: var(--paper);
  box-shadow:
    0 28px 60px -16px rgba(0, 0, 0, .6),
    0 8px 22px rgba(0, 0, 0, .34),
    inset 0 1px 0 rgba(243, 236, 214, .06);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-10px) scale(.97);
  transform-origin: top right;
  transition:
    opacity .34s var(--ease-out),
    transform .42s var(--ease-spring),
    visibility 0s linear .42s;
  z-index: 30;
}

.wayfinder.is-open .wayfinder__panel {
  opacity: 1;
  visibility: visible;
  transform: translateY(0) scale(1);
  transition:
    opacity .34s var(--ease-out),
    transform .42s var(--ease-spring),
    visibility 0s linear 0s;
}

.wayfinder__panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 10px;
  color: var(--paper);
}

.wayfinder__panel-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--wayfinder-tone);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .3em;
  text-transform: uppercase;
  white-space: nowrap;
}

.wayfinder__panel-eyebrow-mark {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .55;
}

.wayfinder__panel-set {
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: -.002em;
  color: var(--paper);
  opacity: .6;
  white-space: nowrap;
}

.wayfinder__panel-set em {
  font-style: italic;
  color: var(--wayfinder-tone);
  opacity: 1;
}

.wayfinder__panel-rule {
  display: block;
  width: 100%;
  height: 6px;
  color: var(--wayfinder-tone);
  opacity: .55;
  margin-bottom: 6px;
}

.wayfinder__panel-rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.wayfinder__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 1px;
}

.wayfinder__item {
  margin: 0;
}

.wayfinder__link {
  position: relative;
  display: grid;
  grid-template-columns: 24px 1px minmax(0, 1fr) 14px;
  align-items: center;
  gap: 10px;
  padding: 9px 4px 9px 2px;
  border-radius: 6px;
  color: var(--paper);
  text-decoration: none;
  transition: background .25s var(--ease), color .25s var(--ease);
}

.wayfinder__link:hover,
.wayfinder__link:focus-visible {
  background: rgba(243, 236, 214, .06);
  color: var(--paper);
}

.wayfinder__item-num {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: var(--wayfinder-tone);
  text-align: center;
  opacity: .85;
}

.wayfinder__item.is-active .wayfinder__item-num {
  color: var(--wayfinder-tone);
  opacity: 1;
}

.wayfinder__item-rule {
  display: block;
  width: 1px;
  height: 22px;
  background: currentColor;
  opacity: .22;
}

.wayfinder__item.is-active .wayfinder__item-rule {
  background: var(--wayfinder-tone);
  opacity: .85;
}

.wayfinder__item-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.wayfinder__item-label {
  font-family: var(--serif);
  font-size: clamp(12.5px, 1.05vw, 14px);
  letter-spacing: -.012em;
  color: var(--paper);
  opacity: .9;
  transition: opacity .25s var(--ease), color .25s var(--ease);
}

.wayfinder__item.is-active .wayfinder__item-label {
  color: var(--wayfinder-tone);
  opacity: 1;
  font-style: italic;
}

.wayfinder__link:hover .wayfinder__item-label,
.wayfinder__link:focus-visible .wayfinder__item-label {
  opacity: 1;
}

.wayfinder__item-hint {
  font-family: var(--serif);
  font-style: italic;
  font-size: 10.5px;
  letter-spacing: -.002em;
  color: var(--paper);
  opacity: .55;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.wayfinder__item-pip {
  position: relative;
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: transparent;
  border: 1px solid var(--wayfinder-tone);
  opacity: .55;
  transition: background .25s var(--ease), transform .25s var(--ease);
}

.wayfinder__item.is-active .wayfinder__item-pip {
  background: var(--wayfinder-tone);
  opacity: 1;
  transform: scale(1.1);
}

.wayfinder__panel-foot {
  margin-top: 10px;
  padding-top: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .28em;
  text-transform: uppercase;
  opacity: .65;
}

.wayfinder__panel-foot-mark {
  display: inline-block;
  width: 16px;
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.wayfinder__close {
  position: absolute;
  top: 10px;
  right: 10px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(243, 236, 214, .05);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: 0;
  transform: translateY(-2px);
  transition: opacity .25s var(--ease), transform .25s var(--ease), background .25s var(--ease);
  pointer-events: none;
}

.wayfinder.is-open .wayfinder__close {
  opacity: .8;
  transform: translateY(0);
  pointer-events: auto;
}

.wayfinder__close:hover,
.wayfinder__close:focus-visible {
  background: rgba(243, 236, 214, .12);
  opacity: 1;
}

.wayfinder__close svg {
  width: 10px;
  height: 10px;
}

@media (max-width: 540px) {
  .wayfinder__panel {
    width: min(320px, calc(100vw - 32px));
    right: -8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .wayfinder__seal,
  .wayfinder__seal-svg,
  .wayfinder__seal-cue,
  .wayfinder__panel {
    transition: none !important;
  }
}

/* The "fresh impression" detail that lands when the answer leaf opens. */

.answer-reveal__fresh {
  position: absolute;
  right: clamp(20px, 3.4vw, 44px);
  bottom: clamp(46px, 4.4vw, 72px);
  display: grid;
  justify-items: end;
  gap: 6px;
  color: var(--coral);
  opacity: 0;
  transform: translateY(6px) rotate(-4deg);
  transition: opacity .9s var(--ease-out) .55s, transform 1s var(--ease-spring) .55s;
  pointer-events: none;
  z-index: 1;
}

.app--voice-quiet .answer-reveal__fresh { color: var(--blue); }
.app--voice-human .answer-reveal__fresh { color: var(--coral); }
.app--voice-bold .answer-reveal__fresh { color: var(--acid); }

.answer-reveal.is-open .answer-reveal__fresh {
  opacity: 1;
  transform: translateY(0) rotate(-6deg);
}

.answer-reveal__fresh-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: currentColor;
  opacity: .85;
  white-space: nowrap;
}

.answer-reveal__fresh-tag::before {
  content: '';
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .7;
}

.answer-reveal__fresh-seal {
  display: block;
  width: clamp(72px, 7vw, 92px);
  height: clamp(72px, 7vw, 92px);
  filter: drop-shadow(0 6px 12px rgba(0, 0, 0, .35));
}

.answer-reveal__fresh-pencil {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(10px, .88vw, 12px);
  color: var(--paper);
  opacity: .65;
  white-space: nowrap;
}

.answer-reveal__fresh-pencil svg {
  display: block;
  width: 50px;
  height: 8px;
  color: currentColor;
  opacity: .7;
}

.answer-reveal__fresh-pencil em {
  font-style: italic;
  letter-spacing: -.002em;
}

@media (max-width: 720px) {
  .answer-reveal__fresh {
    right: 16px;
    bottom: 32px;
    transform: translateY(4px) rotate(-2deg);
  }

  .answer-reveal.is-open .answer-reveal__fresh {
    transform: translateY(0) rotate(-3deg);
  }

  .answer-reveal__fresh-seal {
    width: 64px;
    height: 64px;
  }

  .answer-reveal__fresh-pencil {
    font-size: 10px;
  }

  .answer-reveal__fresh-pencil svg {
    width: 36px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .answer-reveal__fresh {
    transition: none !important;
    transform: none !important;
  }
  .answer-reveal.is-open .answer-reveal__fresh {
    transform: rotate(-4deg) !important;
  }
}

/* ────────────────────────────────────────────────────────────
   ITERATION 251 · THE PRESSED TITLE PAGE

   The hero is reorganised around one idea: the title is the page,
   and the page is a single pressed sheet. The marginal ledger
   thins to a vertical column of three small marks. The horizontal
   title trace and the pressman's plate fuse into one hand-drawn
   "title rule" — three luminous beads strung along a delicate
   curve. A new sig-mark seal closes the hero body, signing the
   page in the active voice. The double border on the hero plate
   is reduced to one hairline, so the question breathes.
   ──────────────────────────────────────────────────────────── */

.hero__spread {
  padding: clamp(96px, 13vw, 184px) clamp(32px, 6vw, 104px) clamp(80px, 10vw, 144px);
  border-color: rgba(146, 186, 255, .07);
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .035),
    0 60px 140px -52px rgba(0, 0, 0, .68);
}

.hero__spread::before {
  inset: 14px;
  border-color: rgba(146, 186, 255, .045);
}

.hero__spread::after {
  inset: 28px;
  border-color: rgba(243, 236, 214, .018);
}

.hero__copy {
  gap: clamp(22px, 2.6vw, 38px);
  max-width: 1120px;
}

/* ── TITLE RULE ── */

.title-rule {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: clamp(10px, 1.1vw, 14px);
  width: min(100%, 1080px);
  margin: clamp(6px, .8vw, 12px) auto 0;
  color: var(--rule-tone, var(--coral));
  transition: color .55s var(--ease);
}

.title-rule__arc {
  display: block;
  width: 100%;
  height: clamp(38px, 4vw, 56px);
  overflow: visible;
}

.title-rule__arc-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titleRuleArcDraw 1.6s var(--ease-out) .65s forwards;
}

.title-rule__nub {
  opacity: 0;
  animation: titleRuleNub .55s var(--ease-spring) .65s forwards;
}

.title-rule__nub--end {
  animation-delay: 2.1s;
}

.title-rule__node {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: titleRuleNodeIn .55s var(--ease-spring) forwards;
}

.title-rule__node.is-active .title-rule__node-bead {
  filter: drop-shadow(0 0 4px currentColor);
}

.title-rule__node.is-active .title-rule__node-ring {
  opacity: 1;
}

.title-rule__node-pulse {
  transform-box: fill-box;
  transform-origin: center;
  opacity: 0;
  animation: titleRulePulse 3.4s var(--ease) infinite;
}

.title-rule__node--m3 .title-rule__node-pulse { animation-delay: 2.6s; }
.title-rule__node--good .title-rule__node-pulse { animation-delay: 2.8s; }
.title-rule__node--yet .title-rule__node-pulse { animation-delay: 3s; }

.title-rule__node-label {
  opacity: 0;
  animation: titleRuleLabel .55s var(--ease-out) forwards;
}

.title-rule__node--m3 .title-rule__node-label { animation-delay: 1.5s; }
.title-rule__node--good .title-rule__node-label { animation-delay: 1.65s; }
.title-rule__node--yet .title-rule__node-label { animation-delay: 1.8s; }

@keyframes titleRuleArcDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes titleRuleNub {
  0% { opacity: 0; transform: scale(.4); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes titleRuleNodeIn {
  0% { opacity: 0; transform: scale(.4); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes titleRulePulse {
  0%, 100% { opacity: .35; transform: scale(.85); }
  60% { opacity: 0; transform: scale(1.7); }
}

@keyframes titleRuleLabel {
  0% { opacity: 0; transform: translateY(2px); }
  100% { opacity: .72; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .title-rule__arc-stroke { stroke-dashoffset: 0 !important; animation: none !important; }
  .title-rule__node,
  .title-rule__node-label,
  .title-rule__nub { opacity: 1 !important; transform: none !important; animation: none !important; }
  .title-rule__node-pulse { animation: none !important; }
}

.title-rule__caption {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 0 auto;
  padding: 0;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12.5px, 1.1vw, 14.5px);
  letter-spacing: -.005em;
  line-height: 1.4;
  text-align: center;
  white-space: nowrap;
}

.title-rule__caption-text em {
  color: var(--rule-tone, var(--coral));
  font-style: italic;
  font-family: var(--serif);
  letter-spacing: -.005em;
  transition: color .45s var(--ease);
}

.title-rule__caption-mark {
  display: inline-grid;
  place-items: center;
  width: 12px;
  height: 12px;
  color: var(--rule-tone, var(--coral));
  opacity: .55;
  transition: color .45s var(--ease), opacity .35s var(--ease), transform .5s var(--ease-spring);
}

.title-rule__caption-mark svg {
  width: 100%;
  height: 100%;
  display: block;
}

.title-rule__caption-mark--alt {
  transform: scaleX(-1);
}

.title-rule:hover .title-rule__caption-mark {
  opacity: .85;
  transform: rotate(45deg);
}

.title-rule:hover .title-rule__caption-mark--alt {
  transform: scaleX(-1) rotate(-45deg);
}

@media (max-width: 720px) {
  .title-rule__caption {
    white-space: normal;
    font-size: 12px;
  }
}

@media (max-width: 540px) {
  .title-rule__arc {
    height: clamp(46px, 7vw, 60px);
  }

  .title-rule__node-label {
    font-size: 8px;
    letter-spacing: 1.5px;
  }
}

/* ── SIGNATURE MARK ── */

.sig-mark {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, .9vw, 12px);
  margin: clamp(8px, 1.4vw, 16px) auto 0;
  padding: 0;
  color: var(--sig-tone, var(--coral));
  transition: color .55s var(--ease);
  opacity: 0;
  animation: sigMarkIn .8s var(--ease-out) 1.2s forwards;
}

.sig-mark__seal {
  display: block;
  width: clamp(72px, 7vw, 96px);
  height: clamp(72px, 7vw, 96px);
  filter: drop-shadow(0 6px 14px rgba(0, 0, 0, .35));
  transform-box: fill-box;
  transform-origin: center;
  animation: sigMarkStamp 1.1s var(--ease-spring) .95s backwards;
}

.sig-mark__ring {
  transform-box: fill-box;
  transform-origin: center;
  animation: sigMarkRing 1.4s var(--ease-out) .95s backwards;
}

.sig-mark__ring-inner {
  transform-box: fill-box;
  transform-origin: center;
  animation: sigMarkRingInner 1.6s var(--ease-out) 1.1s backwards;
}

.sig-mark__flourish {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: sigMarkFlourish 1.3s var(--ease-out) 1.4s forwards;
}

.sig-mark__glyph {
  transform-box: fill-box;
  transform-origin: center;
  animation: sigMarkGlyph 1.2s var(--ease-spring) 1.05s backwards;
}

.sig-mark__bead {
  transform-box: fill-box;
  transform-origin: center;
  opacity: 0;
  animation: sigMarkBead .55s var(--ease-spring) 2.45s forwards;
}

.sig-mark__caption {
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1vw, 14px);
  margin: 0;
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 9.5px);
  letter-spacing: .22em;
  line-height: 1;
  text-align: center;
  text-transform: uppercase;
}

.sig-mark__caption-rule {
  display: block;
  width: clamp(28px, 5vw, 56px);
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor);
  flex: 0 0 auto;
  opacity: .55;
}

.sig-mark__caption-rule--alt {
  background: linear-gradient(to left, transparent, currentColor);
}

.sig-mark__caption-text {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}

.sig-mark__caption-text em {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: 0;
  text-transform: none;
  transition: color .4s var(--ease);
}

.sig-mark__caption-text > span[aria-hidden] {
  color: var(--muted);
  opacity: .55;
}

@keyframes sigMarkIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes sigMarkStamp {
  0% { opacity: 0; transform: scale(1.18) rotate(-6deg); }
  60% { opacity: .96; transform: scale(.96) rotate(2deg); }
  100% { opacity: 1; transform: scale(1) rotate(0); }
}

@keyframes sigMarkRing {
  from { opacity: 0; transform: scale(1.06); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes sigMarkRingInner {
  from { opacity: 0; transform: rotate(-22deg); }
  to { opacity: .55; transform: rotate(0); }
}

@keyframes sigMarkFlourish {
  to { stroke-dashoffset: 0; }
}

@keyframes sigMarkGlyph {
  from { opacity: 0; transform: scale(.6); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes sigMarkBead {
  from { opacity: 0; transform: scale(.3); }
  to { opacity: 1; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .sig-mark { animation: none !important; opacity: 1 !important; }
  .sig-mark__seal,
  .sig-mark__ring,
  .sig-mark__ring-inner,
  .sig-mark__glyph { animation: none !important; transform: none !important; }
  .sig-mark__flourish { stroke-dashoffset: 0 !important; animation: none !important; }
  .sig-mark__bead { opacity: 1 !important; transform: none !important; animation: none !important; }
}

/* ── MARGINAL LEDGER · refined as a thin vertical column ── */

.marginal-ledger {
  width: clamp(50px, 5.2vw, 70px);
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(4px, .6vw, 8px) 0 clamp(4px, .6vw, 8px);
}

.marginal-ledger__head {
  padding-bottom: 6px;
}

.marginal-ledger__head-tag {
  font-size: 7.5px;
  letter-spacing: .26em;
}

.marginal-ledger__list {
  gap: clamp(18px, 2.4vw, 30px);
  margin: 0;
}

.marginal-ledger__tick {
  gap: 1px;
}

.marginal-ledger__tick-glyph {
  width: clamp(22px, 2.2vw, 28px);
  height: clamp(16px, 1.6vw, 20px);
  background: transparent;
  border: 0;
  border-right: 1px solid color-mix(in srgb, currentColor 55%, transparent);
  border-radius: 0;
}

.marginal-ledger__tick-glyph::after {
  display: none;
}

.marginal-ledger__tick--acid { --ledger-mark: var(--acid); }
.marginal-ledger__tick--coral { --ledger-mark: var(--coral); }
.marginal-ledger__tick--blue { --ledger-mark: var(--blue); }

.marginal-ledger__tick-num {
  font-size: 7.5px;
  letter-spacing: .26em;
  padding-right: 4px;
  opacity: .55;
}

.marginal-ledger__tick-label {
  font-size: clamp(10px, .82vw, 11.5px);
  padding-right: 4px;
}

.marginal-ledger__tick:hover,
.marginal-ledger__tick:focus-visible {
  color: var(--ledger-mark);
  opacity: 1;
}

.marginal-ledger__tick:hover .marginal-ledger__tick-glyph,
.marginal-ledger__tick:focus-visible .marginal-ledger__tick-glyph {
  background: transparent;
  border-color: currentColor;
}

.marginal-ledger__row.is-past .marginal-ledger__tick { color: var(--ledger-mark); opacity: .72; }
.marginal-ledger__row.is-active .marginal-ledger__tick { color: var(--ledger-mark); opacity: 1; transform: translateX(-2px); }

.marginal-ledger__row.is-active .marginal-ledger__tick-glyph {
  background: transparent;
  border-color: currentColor;
  box-shadow: none;
}

.marginal-ledger__row.is-active::after {
  right: -2px;
  width: 6px;
  height: 6px;
}

.marginal-ledger__rule {
  top: clamp(20px, 2vw, 28px);
  bottom: clamp(20px, 2.4vw, 30px);
  right: 0;
  width: 1px;
}

.marginal-ledger__foot {
  font-size: 8px;
  letter-spacing: .18em;
  text-align: right;
  padding-right: 2px;
}

.marginal-ledger__foot-text em {
  text-transform: lowercase;
}

@media (max-width: 1179px) {
  .marginal-ledger {
    width: 100%;
    min-width: 0;
    flex-direction: row;
    align-items: stretch;
    gap: clamp(14px, 2vw, 20px);
    padding: clamp(8px, 1.1vw, 12px) clamp(10px, 1.4vw, 16px);
    border: 1px solid var(--line);
    background:
      linear-gradient(180deg, rgba(28, 36, 52, .16), rgba(14, 20, 32, .26));
    border-radius: 1px;
  }

  .marginal-ledger__head {
    border-bottom: 0;
    padding-bottom: 0;
    align-items: flex-start;
    flex: 0 0 auto;
    border-right: 1px solid color-mix(in srgb, var(--ledger-tone) 18%, transparent);
    padding-right: 10px;
  }

  .marginal-ledger__head-rule { display: none; }

  .marginal-ledger__list {
    flex-direction: row;
    gap: clamp(10px, 1.4vw, 14px);
    margin: 0;
    flex: 1;
  }

  .marginal-ledger__row {
    flex: 1;
    min-width: 0;
  }

  .marginal-ledger__tick {
    justify-items: start;
    align-content: start;
    gap: 1px;
  }

  .marginal-ledger__tick-glyph {
    border-right: 1px solid color-mix(in srgb, currentColor 50%, transparent);
    border-radius: 0;
  }

  .marginal-ledger__tick-num,
  .marginal-ledger__tick-label { padding-right: 0; }

  .marginal-ledger__rule { display: none; }

  .marginal-ledger__foot {
    border-top: 0;
    padding-top: 0;
    border-left: 1px solid color-mix(in srgb, var(--ledger-tone) 18%, transparent);
    padding-left: 10px;
    flex: 0 0 auto;
    align-items: center;
    text-align: left;
  }
}

@media (max-width: 720px) {
  .marginal-ledger {
    flex-direction: column;
    align-items: stretch;
  }

  .marginal-ledger__head {
    border-right: 0;
    border-bottom: 1px solid color-mix(in srgb, var(--ledger-tone) 18%, transparent);
    padding-right: 0;
    padding-bottom: 6px;
  }

  .marginal-ledger__list { flex-direction: row; }

  .marginal-ledger__foot {
    border-left: 0;
    border-top: 1px solid color-mix(in srgb, var(--ledger-tone) 18%, transparent);
    padding-left: 0;
    padding-top: 6px;
    text-align: right;
  }
}

/* ── HERO BODY · signature mark sits at the bottom of the body,
   the flourish becomes a single delicate line. ── */

.hero__body {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(16px, 2.2vw, 28px);
  margin-top: clamp(28px, 4vw, 48px);
  padding: 0;
  text-align: center;
}

.hero__summary {
  max-width: 720px;
  margin: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(15.5px, 1.5vw, 19px);
  font-style: italic;
  letter-spacing: -.005em;
  line-height: 1.55;
}

.hero__summary em {
  color: var(--paper);
  font-style: italic;
  text-shadow: 0 0 .4em rgba(216, 240, 106, .08);
}

.hero__press-flourish {
