  }

  .hero__copy { gap: clamp(16px, 2vw, 22px); }

  .hero__summary { font-size: 15px; line-height: 1.55; }

  .hero__spread { padding: clamp(64px, 9vw, 96px) clamp(22px, 4vw, 36px) clamp(48px, 7vw, 76px); }
}

@media (max-width: 480px) {
