/* ────────────────────────────────────────────────────────────
   ITERATION 254 · ONE COMPOSED SHEET, SIGNED ONCE

   The page earns a single decisive "fold" between the title
   page and the body that follows: a hairline that breaks at
   the centre for the page's own monogram seal, with a small
   editorial caption beneath. The hero continue CTA becomes
   a deliberate "turn the page" gesture — a hand-drawn arrow
   that arrives with confidence. Mobile keeps the rhythm.
   ──────────────────────────────────────────────────────────── */

.page-fold {
  --fold-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  column-gap: clamp(12px, 1.6vw, 22px);
  width: min(100%, 1320px);
  margin: clamp(36px, 5vw, 68px) auto clamp(28px, 3.4vw, 48px);
  padding: clamp(20px, 2.4vw, 32px) var(--gutter) clamp(22px, 2.6vw, 36px);
  color: var(--fold-tone);
  opacity: 0;
  animation: pageFoldIn .9s var(--ease-out) .15s forwards;
}

.page-fold::before,
.page-fold::after {
  content: '';
  position: absolute;
  left: var(--gutter);
  right: var(--gutter);
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor 12%, currentColor 88%, transparent);
  opacity: .5;
}

.page-fold::before { top: 0; }

.page-fold::after {
  top: auto;
  bottom: 0;
  opacity: .25;
}

.page-fold__hairline {
  display: block;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor 8%, currentColor 92%, transparent);
  opacity: .55;
  align-self: center;
}

.page-fold__hairline--left {
  background: linear-gradient(to right, transparent, currentColor 60%, currentColor 100%);
}

.page-fold__hairline--right {
  background: linear-gradient(to left, transparent, currentColor 60%, currentColor 100%);
}

.page-fold__seal {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(120px, 16vw, 168px);
  height: clamp(38px, 4.4vw, 48px);
  color: currentColor;
}

.page-fold__seal-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.page-fold__seal-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: pageFoldDraw 1.4s var(--ease-out) .55s forwards;
}

.page-fold__seal-bead {
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.4);
  opacity: 0;
  animation: pageFoldBead .55s var(--ease-spring) 1.85s forwards;
}

.page-fold__seal-ring {
  transform-box: fill-box;
  transform-origin: center;
  opacity: 0;
  transform: scale(.4);
  animation: pageFoldRing .65s var(--ease-spring) 1.7s forwards;
}

.page-fold__seal-orbit {
  transform-box: fill-box;
  transform-origin: center;
  opacity: 0;
  animation: pageFoldOrbit 1.4s var(--ease-out) 1.9s forwards;
}

.page-fold__seal-tick {
  opacity: 0;
  animation: pageFoldTick .55s var(--ease-out) forwards;
}

.page-fold__seal-tick--start { animation-delay: .35s; }
.page-fold__seal-tick--end { animation-delay: 1.95s; }

.page-fold__caption {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.4vw, 18px);
  margin: clamp(12px, 1.4vw, 18px) 0 0;
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12.5px, 1.1vw, 14.5px);
  letter-spacing: -.005em;
  line-height: 1.35;
  text-align: center;
  text-wrap: balance;
  opacity: 0;
  animation: pageFadeIn .85s var(--ease-out) 1.1s forwards;
}

.page-fold__caption em {
  font-style: italic;
  color: var(--paper);
}

.page-fold__caption-mark {
  display: inline-block;
  font-family: var(--serif);
  font-style: normal;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: 0;
  color: currentColor;
  opacity: .55;
  transform: scaleX(-1);
}

.page-fold__caption-mark--alt { transform: none; }

.page-fold__meta {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(14px, 1.8vw, 22px);
  margin: clamp(8px, 1vw, 14px) 0 0;
  flex-wrap: wrap;
  opacity: 0;
  animation: pageFadeIn .85s var(--ease-out) 1.3s forwards;
}

.page-fold__meta-cell {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(8px, 1vw, 12px);
}

.page-fold__meta-tag {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.page-fold__meta-text {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12.5px, 1.05vw, 14px);
  letter-spacing: -.005em;
}

.page-fold__meta-rule {
  display: block;
  width: clamp(20px, 3vw, 36px);
  height: 1px;
  background: currentColor;
  opacity: .35;
}

@keyframes pageFoldIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes pageFoldDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes pageFoldBead {
  to { opacity: 1; transform: scale(1); }
}

@keyframes pageFoldRing {
  to { opacity: .55; transform: scale(1); }
}

@keyframes pageFoldOrbit {
  to { opacity: .35; transform: scale(1); }
}

@keyframes pageFoldTick {
  to { opacity: .85; }
}

@keyframes pageFadeIn {
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .page-fold,
  .page-fold__seal-stroke,
  .page-fold__seal-bead,
  .page-fold__seal-ring,
  .page-fold__seal-orbit,
  .page-fold__seal-tick,
  .page-fold__caption,
  .page-fold__meta {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }
}

@media (max-width: 720px) {
  .page-fold {
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    padding: clamp(18px, 3vw, 26px) clamp(22px, 4vw, 36px);
    row-gap: 12px;
  }

  .page-fold__hairline {
    grid-row: 1;
  }

  .page-fold__seal {
    grid-row: 1;
    grid-column: 2;
    width: clamp(96px, 30vw, 132px);
    height: clamp(34px, 8vw, 42px);
  }

  .page-fold__caption {
    margin-top: 6px;
    grid-row: 2;
    font-size: 12.5px;
    line-height: 1.4;
  }

  .page-fold__meta {
    grid-row: 3;
    gap: 10px;
    font-size: 11px;
  }
}

@media (max-width: 480px) {
  .page-fold__hairline {
    display: none;
  }

  .page-fold {
    grid-template-columns: minmax(0, 1fr);
  }

  .page-fold__seal {
    grid-column: 1;
    justify-self: center;
    width: clamp(120px, 38vw, 168px);
  }

  .page-fold__caption {
    padding: 0 6px;
  }
}

/* ────────────────────────────────────────────────────────────
   HERO CONTINUE · the title page earns a deliberate "turn the
   page" gesture — a hand-drawn arrow arrives with confidence,
   not a default ↓ glyph. The link is a quiet press cue.
   ──────────────────────────────────────────────────────────── */

.hero__continue {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(16px, 2vw, 28px);
  padding: clamp(14px, 1.6vw, 22px) clamp(18px, 2.2vw, 28px);
  margin: clamp(8px, 1vw, 14px) auto 0;
  max-width: clamp(440px, 60%, 720px);
  color: var(--paper);
  border: 1px solid var(--line);
  border-radius: 1px;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .38), rgba(14, 20, 32, .58));
  text-decoration: none;
  transition: border-color .4s var(--ease), background .4s var(--ease), color .4s var(--ease), transform .55s var(--ease-spring);
}

.hero__continue:hover,
.hero__continue:focus-visible {
  border-color: rgba(216, 255, 106, .32);
  background:
    linear-gradient(180deg, rgba(36, 46, 66, .5), rgba(20, 28, 42, .68));
  transform: translateY(-1px);
}

.hero__continue-imprint {
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
}

.hero__continue-imprint em {
