}

@keyframes pressSignatureKnot {
  0% { opacity: 0; transform: scale(.2) rotate(-12deg); }
  70% { opacity: 1; transform: scale(1.18) rotate(4deg); }
  100% { opacity: 1; transform: scale(1) rotate(0); }
}

@keyframes pressSignatureRing {
  0% { opacity: 0; transform: scale(.5); }
  100% { opacity: .55; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .press-signature__stroke { stroke-dashoffset: 0 !important; animation: none !important; }
  .press-signature__bead,
  .press-signature__knot,
  .press-signature__knot-ring,
  .press-signature__caption { opacity: 1 !important; transform: none !important; animation: none !important; }
  .press-signature__knot-ring { opacity: .55 !important; }
}

@media (max-width: 540px) {
