}

.hero__dropcap {
  float: left;
  position: relative;
  margin: .08em .18em -.14em -.04em;
  padding-top: .04em;
  color: var(--coral);
  font-family: var(--serif);
  font-size: 3.4em;
  font-style: italic;
  font-weight: 400;
  line-height: .82;
  letter-spacing: -.045em;
  text-shadow:
    0 0 .04em rgba(240, 113, 96, .35),
    0 1px 0 rgba(23, 22, 29, .12);
  transition: color .45s var(--ease), transform .55s var(--ease-spring), text-shadow .5s var(--ease);
}

.hero__continue {
  justify-self: center;
  display: inline-flex;
  align-items: center;
  gap: clamp(16px, 2vw, 28px);
  padding: clamp(8px, 1vw, 12px) 0;
  color: var(--paper);
  text-decoration: none;
}

.hero__continue:hover .hero__continue-arrow,
.hero__continue:focus-visible .hero__continue-arrow {
  gap: clamp(12px, 1.4vw, 18px);
  color: var(--coral);
}

@media (max-width: 540px) {
  .hero__body { padding-top: 18px; gap: 22px; }
  .hero__summary { font-size: 16px; line-height: 1.55; }
}

/* The voice line (now the press's lever row) gets a more
   confident active state, with the active letter pressed into
   its circle. */

.hero__voice-line {
  border-color: rgba(146, 186, 255, .14);
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(14, 20, 32, .55));
  box-shadow: inset 0 0 0 1px rgba(146, 186, 255, .04);
}

.hero__voice-line-item.is-active .hero__voice-line-letter {
  background: currentColor;
  color: var(--night);
  border-color: currentColor;
}

/* A refined FolioMark: tighter rule, more delicate row.
   The existing rule gets a touch more presence at the top
   of the title plate. */

.hero__folio-mark-rule {
  height: 8px;
  opacity: 1;
}

.hero__folio-mark-row {
  font-size: clamp(10.5px, .96vw, 12.5px);
  column-gap: clamp(10px, 1.1vw, 14px);
}

.hero__folio-mark-folio {
  font-size: 8px;
  letter-spacing: .26em;
}

.hero__folio-mark-bead {
  width: 4px;
  height: 4px;
  opacity: .65;
}

/* The page-fold earns a single, decisive rule. The center
   ornament sits like a press seal pressed onto the fold. */

.page-fold__seal-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: pageFoldDraw 1.4s var(--ease-out) .15s forwards;
}

.page-fold__seal-bead { animation: pageFoldBead .4s var(--ease-spring) 1.55s backwards; }

@keyframes pageFoldDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes pageFoldBead {
  0% { opacity: 0; transform: scale(.4); }
  100% { opacity: 1; transform: scale(1); }
}

/* The reading folio footer settles into a single composed plate.
   The four cells become a horizontal state-row with one signature
   underneath. The status tags quiet down; the voice cell becomes
   the centerpiece. */

.reading-folio {
  border-top: 1px solid var(--line);
  background:
    radial-gradient(ellipse at 50% 0%, rgba(146, 186, 255, .04), transparent 70%),
    linear-gradient(180deg, rgba(20, 26, 38, .36), rgba(12, 16, 25, .58));
}

.reading-folio__plate {
  margin: 0 0 clamp(20px, 2.6vw, 32px);
}

.reading-folio__row {
  gap: clamp(10px, 1.2vw, 18px);
}

.reading-folio__cell {
  background:
    radial-gradient(ellipse at 0 0%, rgba(146, 186, 255, .04), transparent 60%),
    rgba(20, 26, 38, .55);
}

.reading-folio__cell-name {
  font-size: clamp(16px, 1.4vw, 19px);
}

/* A small "set today" stamp on the colophon picks up the
   warmer paper tone from the new palette. */

.colophon__date-tag {
  color: var(--paper-warm);
}

/* Mobile: the marginal caret hides. The marginalia strip becomes
   a more compact two-column row. The title drops to a confident
   single-line-per-row read. */

@media (max-width: 720px) {
  .hero__plate { padding: 8px 0; }

  .hero__plate .hero__title {
    font-size: clamp(3.4rem, 12.4vw, 5rem);
    line-height: .88;
    letter-spacing: -.09em;
  }

  .hero__plate .hero__title--quiet {
    font-size: clamp(3.2rem, 11.6vw, 4.8rem);
  }

  .hero__plate .hero__title--bold {
    font-size: clamp(3.6rem, 13.4vw, 5.4rem);
    line-height: .84;
  }

  .press-signature {
    margin: 14px auto 6px;
  }

  .press-signature__sweep { width: clamp(320px, 90%, 540px); }

  .marginalia {
    grid-template-columns: minmax(0, 1fr);
    padding: 14px 18px 16px;
    gap: 12px;
  }

  .marginalia__rule { display: none; }

  .marginalia__list {
    flex-wrap: wrap;
    gap: 8px;
  }

  .marginalia__row { flex: 1 1 calc(50% - 4px); min-width: 0; }

  .marginalia__tick {
    width: 100%;
    grid-template-columns: auto minmax(0, 1fr);
  }

  .marginalia__divider { display: none; }
}

@media (max-width: 420px) {
  .hero__plate .hero__title { letter-spacing: -.084em; }
  .hero__plate .hero__title--bold { letter-spacing: -.1em; }
}


/* ────────────────────────────────────────────────────────────
   ITERATION 257 · the title page earns a single editorial
   colophon. The hero body becomes a small folio epilogue: a
   hairline rule with a centered tag, a hand-drawn dropcap on
   the summary, an aside naming the current voice, and a
   "turn the page" gesture that lifts a real paper corner.
   The reveal is gated on the body entering the viewport so
   the page reads as composed, not assembled.
   ──────────────────────────────────────────────────────────── */

.hero__body {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: clamp(18px, 2.2vw, 32px);
  margin-top: clamp(24px, 3vw, 40px);
  padding-top: clamp(22px, 2.6vw, 32px);
  border-top: 1px solid var(--line-soft);
  text-align: center;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-out);
}

.hero__body.is-in-view {
  opacity: 1;
  transform: translateY(0);
}

.hero__body-plate {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  margin: 0 auto;
  max-width: min(620px, 92%);
  color: var(--coral);
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 9.5px);
  font-weight: 600;
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: 0;
  animation: heroBodyPlateIn .85s var(--ease-out) .15s forwards;
}

.hero__body-plate-rule {
  display: block;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 22%, var(--line) 78%, transparent);
  opacity: .85;
}

.hero__body-plate-tag {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 3px 0 4px;
  color: var(--coral);
  white-space: nowrap;
  transition: color .5s var(--ease);
}

.hero__body-plate-tag em {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(11.5px, 1.05vw, 14px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
  opacity: .85;
}

.app--voice-quiet .hero__body-plate-tag { color: var(--blue); }
.app--voice-human .hero__body-plate-tag { color: var(--coral); }
.app--voice-bold .hero__body-plate-tag { color: var(--acid); }

.hero__body-plate-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 2px rgba(240, 110, 91, .14);
}

.app--voice-quiet .hero__body-plate-dot { box-shadow: 0 0 0 2px rgba(155, 188, 255, .14); }
.app--voice-bold .hero__body-plate-dot { box-shadow: 0 0 0 2px rgba(216, 240, 106, .14); }

@keyframes heroBodyPlateIn {
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .hero__body { opacity: 1; transform: none; transition: none; }
  .hero__body-plate { animation: none !important; opacity: 1; }
}

.hero__body-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  align-items: start;
  justify-content: center;
  gap: clamp(28px, 3.6vw, 56px);
  max-width: 1080px;
  width: 100%;
  margin: 0 auto;
}

.hero__summary {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  column-gap: clamp(12px, 1.2vw, 16px);
  max-width: 60ch;
  margin: 0;
  color: var(--lead-2);
  font-family: var(--serif);
  font-size: clamp(17px, 1.5vw, 21px);
  line-height: 1.62;
  font-feature-settings: 'kern' 1, 'liga' 1, 'onum' 1;
  text-wrap: pretty;
  text-align: left;
  transition: font-style .5s var(--ease), letter-spacing .55s var(--ease);
}

.app--voice-quiet .hero__summary { font-style: italic; letter-spacing: -.005em; }
.app--voice-human .hero__summary { font-style: italic; letter-spacing: -.002em; }
.app--voice-bold .hero__summary { font-style: normal; letter-spacing: .002em; font-weight: 500; }

.hero__summary em {
  color: var(--paper);
  font-style: italic;
  font-weight: inherit;
}

.hero__summary-text {
  grid-column: 2;
  display: flex;
  flex-direction: column;
  gap: clamp(8px, .9vw, 12px);
}

.hero__summary-paragraph {
  display: block;
  margin: 0;
}

.hero__summary-paragraph + .hero__summary-paragraph {
  margin: 0;
}

.hero__summary-sign {
  display: inline-flex;
  align-self: flex-end;
  align-items: baseline;
  gap: clamp(6px, .7vw, 9px);
  margin-top: clamp(2px, .4vw, 6px);
  padding-top: clamp(4px, .55vw, 8px);
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.005em;
  line-height: 1;
  opacity: 0;
  transform: translateY(2px);
  transition: opacity .7s var(--ease-out) .9s, transform .7s var(--ease-out) .9s;
}

.hero__body.is-in-view .hero__summary-sign {
  opacity: 1;
  transform: translateY(0);
}

.hero__summary-sign-dash {
  color: var(--ink-mist);
  font-family: var(--serif);
  font-style: normal;
  font-size: clamp(15px, 1.25vw, 17px);
  letter-spacing: 0;
  transform: translateY(-.04em);
}

.hero__summary-sign-name {
  color: var(--paper);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -.005em;
}

@media (prefers-reduced-motion: reduce) {
  .hero__summary-sign { opacity: 1 !important; transform: none !important; transition: none !important; }
}

/* ────────────────────────────────────
   HERO SET RULE · a thin printer's
   ornament that bridges the body grid
   and the pull quote. Two fading rules
   with a hand-drawn bead in the middle —
   the page's own seam between the
   editorial note and the printer's motto.
   ──────────────────────────────────── */

.hero__set-rule {
  /* retired in 2020 */
  display: none;
}

.hero__summary-scrawl {
  grid-column: 1 / -1;
  display: block;
  width: clamp(120px, 16vw, 160px);
  height: 10px;
  margin: 6px 0 0;
  justify-self: start;
  color: var(--coral);
  opacity: 0;
  transition: color .5s var(--ease);
}

.hero__body.is-in-view .hero__summary-scrawl {
  opacity: .55;
}

.hero__summary-scrawl-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.1s var(--ease-out) .35s;
}

.hero__body.is-in-view .hero__summary-scrawl-stroke {
  stroke-dashoffset: 0;
}

.hero__summary-scrawl-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.4);
  transition: opacity .35s var(--ease) 1.35s, transform .55s var(--ease-spring) 1.35s;
}

.hero__body.is-in-view .hero__summary-scrawl-bead {
  opacity: 1;
  transform: scale(1);
}

.app--word-good .hero__summary-scrawl { color: var(--coral); }
.app--word-yet .hero__summary-scrawl { color: var(--blue); }
.app--word-m3 .hero__summary-scrawl { color: var(--acid); }

.hero__dropcap {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(58px, 5.6vw, 72px);
  height: clamp(58px, 5.6vw, 72px);
  flex: 0 0 auto;
  margin-top: .02em;
  color: var(--coral);
  transition: color .5s var(--ease), transform .55s var(--ease-spring);
}

.app--voice-quiet .hero__dropcap { color: var(--blue); }
.app--voice-human .hero__dropcap { color: var(--coral); }
.app--voice-bold .hero__dropcap { color: var(--acid); }

.hero__dropcap-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.hero__copy:hover ~ .hero__body .hero__dropcap,
.hero__body:hover .hero__dropcap {
  transform: rotate(-4deg);
}

@media (prefers-reduced-motion: reduce) {
  .hero__dropcap { transform: none !important; }
  .hero__summary-scrawl-stroke { stroke-dashoffset: 0 !important; transition: none !important; }
  .hero__summary-scrawl-bead { opacity: 1 !important; transform: none !important; transition: none !important; }
  .hero__summary-scrawl { opacity: .85 !important; }
}

.hero__voice-caption {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(8px, 1vw, 12px);
  padding: clamp(14px, 1.6vw, 20px) clamp(14px, 1.6vw, 20px);
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 0 0%, rgba(216, 240, 106, .04), transparent 60%),
    linear-gradient(180deg, rgba(28, 36, 52, .34), rgba(14, 20, 32, .5));
  text-align: left;
  align-self: start;
}

.hero__voice-caption-rule {
  display: block;
  width: 100%;
  height: 1px;
  background: linear-gradient(to right, var(--coral) 0%, transparent 60%);
  opacity: .45;
}

.app--voice-quiet .hero__voice-caption-rule { background: linear-gradient(to right, var(--blue) 0%, transparent 60%); }
.app--voice-human .hero__voice-caption-rule { background: linear-gradient(to right, var(--coral) 0%, transparent 60%); }
.app--voice-bold .hero__voice-caption-rule { background: linear-gradient(to right, var(--acid) 0%, transparent 60%); }

.hero__voice-caption-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.2vw, 14px);
}

.hero__voice-caption-letter {
  display: inline-grid;
  place-items: center;
  width: clamp(32px, 3vw, 38px);
  height: clamp(32px, 3vw, 38px);
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.3vw, 17px);
  letter-spacing: 0;
  color: var(--paper);
  background: rgba(0, 0, 0, .22);
  transition: background .5s var(--ease), color .5s var(--ease);
}

.hero__voice-caption-letter--quiet { color: var(--blue); }
.hero__voice-caption-letter--human { color: var(--coral); }
.hero__voice-caption-letter--bold { color: var(--acid); }

.app--voice-quiet .hero__voice-caption-letter--quiet,
.app--voice-human .hero__voice-caption-letter--human,
.app--voice-bold .hero__voice-caption-letter--bold {
  background: currentColor;
  color: var(--night);
  border-color: currentColor;
}

.hero__voice-caption-copy {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.hero__voice-caption-eyebrow {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.hero__voice-caption-name {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(16px, 1.4vw, 19px);
  letter-spacing: -.01em;
  text-transform: none;
}

.hero__voice-caption-mark {
  display: inline-grid;
  place-items: center;
  width: clamp(36px, 3vw, 42px);
  height: 14px;
  color: var(--coral);
  opacity: .7;
  transition: opacity .5s var(--ease), color .5s var(--ease);
}

.app--voice-quiet .hero__voice-caption-mark { color: var(--blue); }
.app--voice-human .hero__voice-caption-mark { color: var(--coral); }
.app--voice-bold .hero__voice-caption-mark { color: var(--acid); }

.hero__voice-caption-mark svg {
  width: 100%;
  height: 100%;
  display: block;
}

.hero__voice-caption-foot {
  display: block;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, .98vw, 13px);
  letter-spacing: 0;
  line-height: 1.45;
  opacity: .9;
}

.hero__voice-caption-foot kbd {
  display: inline-block;
  padding: 1px 5px 2px;
  margin: 0 1px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: rgba(0, 0, 0, .25);
  color: var(--paper);
  font-family: var(--mono);
  font-style: normal;
  font-size: 10px;
  letter-spacing: .08em;
  line-height: 1;
  vertical-align: .05em;
}

/* ────────────────────────────────────────────────────────────
   PRESS CERTIFICATE · a tactile replacement for the older
   voice-caption aside. The certificate reads as a printer's
   own receipt for the impression: set today, voice, and
   materials. Four cropped corners frame a small definition
   list so the aside feels distinct from the editor's note
   on the left and the press section below.
   ──────────────────────────────────────────────────────────── */

.hero__certificate {
  --cert-tone: var(--coral);
  position: relative;
  display: flex;
  flex-direction: column;
  gap: clamp(10px, 1.2vw, 14px);
  align-self: stretch;
  margin: 0;
  padding: clamp(18px, 2vw, 24px) clamp(16px, 1.8vw, 22px) clamp(14px, 1.6vw, 18px);
  border: 1px solid rgba(146, 186, 255, .12);
  border-top-color: var(--cert-tone);
  border-top-width: 2px;
  background:
    repeating-linear-gradient(180deg, transparent 0 26px, rgba(243, 236, 214, .018) 26px 27px),
    linear-gradient(180deg, rgba(28, 36, 52, .36), rgba(14, 20, 32, .55));
  box-shadow: inset 0 0 0 1px rgba(146, 186, 255, .04);
  text-align: left;
  transition: border-color .45s var(--ease);
}

.app--voice-quiet .hero__certificate { --cert-tone: var(--blue); }
.app--voice-human .hero__certificate { --cert-tone: var(--coral); }
.app--voice-bold .hero__certificate { --cert-tone: var(--acid); }

.hero__certificate-frame {
  position: absolute;
  inset: 6px;
  pointer-events: none;
}

.hero__certificate-frame-corner {
  position: absolute;
  width: 10px;
  height: 10px;
  border: 1px solid currentColor;
  color: var(--cert-tone);
  opacity: .85;
}

.hero__certificate-frame-corner--tl { top: -1px; left: -1px; border-right: 0; border-bottom: 0; }
.hero__certificate-frame-corner--tr { top: -1px; right: -1px; border-left: 0; border-bottom: 0; }
.hero__certificate-frame-corner--bl { bottom: -1px; left: -1px; border-right: 0; border-top: 0; }
.hero__certificate-frame-corner--br { bottom: -1px; right: -1px; border-left: 0; border-top: 0; }

.hero__certificate-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: clamp(6px, .8vw, 10px);
  border-bottom: 1px dashed var(--line);
}

.hero__certificate-head-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--cert-tone);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.hero__certificate-head-eyebrow::before {
  content: '';
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(255, 118, 95, .14);
  transition: background .4s var(--ease);
}

.app--voice-quiet .hero__certificate-head-eyebrow::before { box-shadow: 0 0 0 3px rgba(155, 188, 255, .14); }
.app--voice-bold .hero__certificate-head-eyebrow::before { box-shadow: 0 0 0 3px rgba(216, 240, 106, .14); }

.hero__certificate-head-folio {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .7;
}

.hero__certificate-list {
  display: flex;
  flex-direction: column;
  gap: clamp(8px, 1vw, 12px);
  margin: 0;
  padding: 0;
}

.hero__certificate-row {
  display: grid;
  grid-template-columns: minmax(58px, 84px) minmax(0, 1fr);
  align-items: baseline;
  gap: clamp(8px, 1.2vw, 14px);
  padding-bottom: clamp(6px, .8vw, 10px);
  border-bottom: 1px dotted rgba(146, 186, 255, .08);
}

.hero__certificate-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.hero__certificate-row dt {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
  margin: 0;
}

.hero__certificate-row dd {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
  margin: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.2vw, 16px);
  letter-spacing: -.005em;
  line-height: 1.25;
}

.hero__certificate-letter {
  display: inline-grid;
  place-items: center;
