  transition: transform .55s var(--ease-spring), color .35s var(--ease);
}

.app--voice-quiet .hero__continue-corner { color: var(--blue); }
.app--voice-human .hero__continue-corner { color: var(--coral); }
.app--voice-bold .hero__continue-corner { color: var(--acid); }

.hero__continue:hover .hero__continue-corner,
.hero__continue:focus-visible .hero__continue-corner {
