.app--voice-quiet .hero__continue-imprint em { color: var(--blue); }
.app--voice-human .hero__continue-imprint em { color: var(--coral); }
.app--voice-bold .hero__continue-imprint em { color: var(--acid); }

.hero__continue-arrow {
