}

.app--voice-quiet .hero__continue-hint-svg { color: var(--blue); }
.app--voice-human .hero__continue-hint-svg { color: var(--coral); }
.app--voice-bold .hero__continue-hint-svg { color: var(--acid); }

.hero__continue-hint-stroke {
