/* ────────────────────────────────────────────────────────────
   PRESS SPINE · a continuous binding thread running along
   the left edge of the page. Each folio leaves a knot at its
   section break; the active knot brightens, the past knots
   dim, and a hover brings the folio label into the gutter.
   The thread is what makes the page feel like one bound
   volume rather than a stack of separate artifacts.
   ──────────────────────────────────────────────────────────── */

.press-spine {
  --spine-tone: var(--coral);
  position: fixed;
  top: 0;
  bottom: 0;
  left: clamp(14px, 2.4vw, 28px);
  width: 38px;
  z-index: 3;
  pointer-events: none;
  color: var(--spine-tone);
  transition: color .55s var(--ease);
  animation: spineIn .9s var(--ease-out) .25s backwards;
}

@keyframes spineIn {
  from { opacity: 0; transform: translateX(-6px); }
  to { opacity: 1; transform: translateX(0); }
}

.press-spine--quiet { --spine-tone: var(--blue); }
.press-spine--human { --spine-tone: var(--coral); }
.press-spine--bold { --spine-tone: var(--acid); }

.press-spine__thread {
  position: absolute;
  top: clamp(80px, 12vh, 130px);
  bottom: clamp(80px, 12vh, 130px);
  left: 50%;
  transform: translateX(-50%);
  width: 1px;
  pointer-events: none;
  color: var(--spine-tone);
}

.press-spine__thread-line {
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      to bottom,
      currentColor 0 4px,
      transparent 4px 9px
    );
  opacity: .22;
  transition: opacity .55s var(--ease);
}

.press-spine__thread-cap {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 14px;
  height: 14px;
  color: currentColor;
  opacity: .6;
  transition: opacity .55s var(--ease);
}

.press-spine__thread-cap--top { top: -7px; }
.press-spine__thread-cap--bot { bottom: -7px; }

.press-spine__thread-cap svg {
  display: block;
  width: 100%;
  height: 100%;
}

.press-spine:hover .press-spine__thread-line,
.press-spine:focus-within .press-spine__thread-line {
  opacity: .35;
}

.press-spine__folios {
  position: absolute;
  inset: 0;
  margin: 0;
  padding: 0;
  list-style: none;
  pointer-events: none;
}

.press-spine__folio {
  position: absolute;
  top: calc(
    clamp(80px, 12vh, 130px) +
    (100vh - clamp(160px, 24vh, 260px)) * (var(--folio-i, 0) / 8)
  );
  left: 50%;
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  pointer-events: auto;
}

.press-spine__knot {
  display: inline-grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  color: var(--mist);
  background:
    radial-gradient(circle at 50% 50%, rgba(20, 24, 36, .92), rgba(14, 15, 21, .96));
  border: 1px solid var(--line);
  transition:
    color .45s var(--ease),
    border-color .45s var(--ease),
    transform .55s var(--ease-spring),
    box-shadow .55s var(--ease);
}

.press-spine__knot-svg {
  width: 16px;
  height: 16px;
  display: block;
  transition: transform .55s var(--ease);
}

.press-spine__knot:hover,
.press-spine__knot:focus-visible {
  border-color: currentColor;
  color: var(--spine-tone);
  transform: scale(1.08);
  box-shadow:
    0 0 0 4px rgba(255, 255, 255, .02),
    0 4px 16px -6px currentColor;
}

.press-spine__knot-core {
  transform-box: fill-box;
  transform-origin: center;
  transition: transform .45s var(--ease-spring);
}

.press-spine__knot-cross {
  opacity: 0;
  transition: opacity .35s var(--ease);
}

.press-spine__folio.is-past .press-spine__knot {
  color: var(--ink-mist);
  opacity: .55;
}

.press-spine__folio.is-active .press-spine__knot {
  color: var(--spine-tone);
  border-color: currentColor;
  transform: scale(1.2);
  box-shadow:
    0 0 0 4px rgba(255, 255, 255, .03),
    0 0 22px -4px currentColor,
    inset 0 0 0 1px rgba(255, 255, 255, .06);
}

.press-spine__folio.is-active .press-spine__knot-core {
  animation: spineCorePulse 2.4s var(--ease) infinite;
  transform-box: fill-box;
  transform-origin: center;
}

.press-spine__folio.is-active .press-spine__knot-cross {
  opacity: .55;
}

@keyframes spineCorePulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.35); }
}

.press-spine__caption {
  position: absolute;
  left: calc(100% + 14px);
  top: 50%;
  transform: translateY(-50%) translateX(-6px);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px 6px 4px;
  background: rgba(14, 15, 21, .86);
  border: 1px solid var(--line);
  border-left: 2px solid currentColor;
  color: var(--paper);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity .3s var(--ease), transform .35s var(--ease-out);
  z-index: 4;
  backdrop-filter: blur(8px);
}

.press-spine__caption.is-visible {
  opacity: 1;
  transform: translateY(-50%) translateX(0);
}

.press-spine__caption-index {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid currentColor;
  color: currentColor;
  font-size: 10px;
  font-style: italic;
  font-family: Georgia, serif;
  letter-spacing: 0;
  text-transform: lowercase;
}

.press-spine__caption-label {
  color: var(--paper);
  font-family: var(--serif);
  font-size: 11.5px;
  font-style: italic;
  letter-spacing: -.005em;
  text-transform: none;
}

@media (max-width: 720px) {
  .press-spine {
    left: 8px;
    width: 22px;
  }

  .press-spine__thread {
    top: 64px;
    bottom: 64px;
  }

  .press-spine__folio {
    top: calc(
      64px +
      (100% - 128px) * (var(--folio-i, 0) / 8)
    );
  }

  .press-spine__knot {
    width: 18px;
    height: 18px;
  }

  .press-spine__knot-svg {
    width: 12px;
    height: 12px;
  }

  .press-spine__caption {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-spine {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .press-spine__folio.is-active .press-spine__knot-core {
    animation: none !important;
    transform: none !important;
  }
  .press-spine__caption { transition: none !important; }
}

/* ────────────────────────────────────────────────────────────
   PLATE PROVENANCE · a deliberate press stamp at the top of
   the title page. It frames the page's identity (PLATE · i)
   and announces the date and the active voice. The stamp is
   drawn as if pulled fresh from the press: a faint grain
   pass, a settled frame, and a single line of monospace text
   that arrives last. Sets the title page's authority.
   ──────────────────────────────────────────────────────────── */

.plate-provenance {
  --provenance-tone: var(--coral);
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: clamp(6px, .8vw, 10px);
  margin: clamp(6px, 1.2vw, 14px) auto clamp(18px, 2.4vw, 28px);
  max-width: 720px;
  color: var(--provenance-tone);
  transition: color .55s var(--ease);
}

.plate-provenance--quiet { --provenance-tone: var(--blue); }
.plate-provenance--human { --provenance-tone: var(--coral); }
.plate-provenance--bold { --provenance-tone: var(--acid); }

.plate-provenance__stamp {
  display: block;
  width: 100%;
  height: clamp(56px, 6vw, 88px);
  color: inherit;
}

.plate-provenance__group {
  opacity: 0;
  animation: provenanceIn .85s var(--ease-out) .4s forwards;
}

.plate-provenance__rule {
  stroke-dasharray: 2 4;
  stroke-dashoffset: 0;
  transform-origin: left center;
  animation: provenanceRuleDraw .9s var(--ease-out) .65s backwards;
}

.plate-provenance__rule--bot {
  animation-delay: 1.05s;
  transform-origin: right center;
}

.plate-provenance__eyebrow {
  opacity: 0;
  animation: provenanceEyebrowIn .55s var(--ease-out) 1.15s forwards;
}

.plate-provenance__name {
  opacity: 0;
  animation: provenanceNameIn .75s var(--ease-out) 1.35s forwards;
}

.plate-provenance__name-rule {
  stroke-dasharray: .6 1.4;
  transform-origin: center;
  animation: provenanceRuleGrow .55s var(--ease-out) 1.95s backwards;
}

.plate-provenance__corner {
  opacity: 0;
  animation: provenanceCornerIn .35s var(--ease-out) backwards;
}

.plate-provenance__corner--tl { animation-delay: 1.5s; }
.plate-provenance__corner--tr { animation-delay: 1.6s; }
.plate-provenance__corner--bl { animation-delay: 1.7s; }
.plate-provenance__corner--br { animation-delay: 1.8s; }

.plate-provenance__seal {
  opacity: 0;
  animation: provenanceSealIn .55s var(--ease-out) 2s forwards;
}

@keyframes provenanceIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes provenanceRuleDraw {
  from { opacity: 0; stroke-dashoffset: 160; }
  to { opacity: .8; stroke-dashoffset: 0; }
}

@keyframes provenanceEyebrowIn {
  from { opacity: 0; }
  to { opacity: .82; }
}

@keyframes provenanceNameIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes provenanceRuleGrow {
  from { opacity: 0; transform: scaleX(0); }
  to { opacity: .55; transform: scaleX(1); }
}

@keyframes provenanceCornerIn {
  from { opacity: 0; }
  to { opacity: .9; }
}

@keyframes provenanceSealIn {
  from { opacity: 0; transform: scale(.6); }
  to { opacity: 1; transform: scale(1); }
}

.plate-provenance__caption {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: var(--ink-mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: 0;
  animation: provenanceCaptionIn .55s var(--ease-out) 2.1s forwards;
}

.plate-provenance__caption em {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
}

.plate-provenance__caption-divider {
  color: currentColor;
  opacity: .5;
}

.plate-provenance__caption-mark {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  color: currentColor;
  opacity: .75;
  transition: opacity .35s var(--ease);
}

.plate-provenance__caption-mark svg {
  display: block;
  width: 100%;
  height: 100%;
}

.plate-provenance:hover .plate-provenance__caption-mark {
  opacity: 1;
}

@keyframes provenanceCaptionIn {
  from { opacity: 0; }
  to { opacity: .9; }
}

@media (max-width: 720px) {
  .plate-provenance {
    margin: 4px auto 14px;
  }

  .plate-provenance__stamp {
    height: 64px;
  }

  .plate-provenance__caption {
    flex-wrap: wrap;
    gap: 6px;
    font-size: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .plate-provenance__group,
  .plate-provenance__rule,
  .plate-provenance__eyebrow,
  .plate-provenance__name,
  .plate-provenance__name-rule,
  .plate-provenance__corner,
  .plate-provenance__seal,
  .plate-provenance__caption {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    letter-spacing: 2.4px !important;
  }
}

/* ────────────────────────────────────────────────────────────
   ANSWER REVEAL · "FOLD HERE" · a small registration mark
   that lands at the spot where the leaf was folded. It is
   the kind of detail a real tipped-in artifact would carry:
   a delicate circle with crosshairs and a quiet "fold ·
   here" tag, plus a small trail leading back to the fold
   line. It rewards the reader who looks closely.
   ──────────────────────────────────────────────────────────── */

.answer-reveal__foldhere {
  position: absolute;
  top: calc(38% - 32px);
  right: clamp(60px, 8vw, 110px);
  width: 64px;
  height: 64px;
  display: grid;
  place-items: center;
  color: var(--wax);
  opacity: 0;
  pointer-events: none;
  transform-origin: center;
  transition:
    opacity .65s var(--ease) .85s,
    transform .85s var(--ease-spring) .85s;
  z-index: 3;
}

.answer-reveal__foldhere svg {
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 1px 0 rgba(0, 0, 0, .08));
}

.answer-reveal__foldhere-tag {
  position: absolute;
  top: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  color: var(--wax);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .3em;
  text-transform: uppercase;
  opacity: .85;
}

.answer-reveal__foldhere-trail {
  position: absolute;
  top: calc(100% + 22px);
  left: 50%;
  transform: translateX(-50%);
  width: 56px;
  height: 8px;
  color: var(--wax);
  opacity: .55;
}

.answer-reveal__foldhere-trail svg {
  width: 100%;
  height: 100%;
  display: block;
}

.answer-reveal.is-open .answer-reveal__foldhere {
  opacity: 1;
  transform: translateY(8px) rotate(-3deg);
}

@media (prefers-reduced-motion: reduce) {
  .answer-reveal__foldhere {
    transition: none !important;
    opacity: 1 !important;
    transform: translateY(8px) rotate(-3deg) !important;
  }
}

@media (max-width: 720px) {
  .answer-reveal__foldhere {
    width: 48px;
    height: 48px;
    right: 18px;
  }

  .answer-reveal__foldhere-tag {
    font-size: 7px;
  }
}

/* ────────────────────────────────────────────────────────────
   FIRST READING · a deliberate rule between the title and the
   colophon body. A thin horizontal line holds a single italic
   phrase — "read it once with the eye, then again with the
   ear" — flanked by two small registration marks. A hand-drawn
   stroke sits beneath, dated to today. It earns the page's own
   breathing room before the colophon begins.
   ──────────────────────────────────────────────────────────── */

.first-reading {
  --first-reading-tone: var(--coral);
  position: relative;
  display: grid;
  justify-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  margin: clamp(28px, 3.6vw, 52px) auto clamp(28px, 3.4vw, 46px);
  padding: 0 var(--gutter);
  max-width: 920px;
  width: 100%;
  color: var(--first-reading-tone);
  transition: color .55s var(--ease);
}

.first-reading--quiet { --first-reading-tone: var(--blue); }
.first-reading--human { --first-reading-tone: var(--coral); }
.first-reading--bold  { --first-reading-tone: var(--acid); }

.first-reading__crop {
  position: absolute;
  width: 14px;
  height: 14px;
  pointer-events: none;
  opacity: 0;
  color: var(--line);
  transition: opacity .6s var(--ease) 1.2s;
}

.first-reading.is-revealed .first-reading__crop {
  opacity: .55;
}

.first-reading__crop--tl {
  top: -6px;
  left: clamp(8px, 3vw, 28px);
  border-top: 1px solid currentColor;
  border-left: 1px solid currentColor;
}

.first-reading__crop--tr {
  top: -6px;
  right: clamp(8px, 3vw, 28px);
  border-top: 1px solid currentColor;
  border-right: 1px solid currentColor;
}

.first-reading__rule {
  display: block;
  width: min(100%, 760px);
  height: 14px;
  overflow: visible;
}

.first-reading__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.4s var(--ease-out);
}

.first-reading.is-revealed .first-reading__rule-stroke {
  stroke-dashoffset: 0;
}

.first-reading__rule-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.4);
  transition:
    opacity .35s var(--ease) 1.05s,
    transform .55s var(--ease-spring) 1.05s;
}

.first-reading.is-revealed .first-reading__rule-bead {
  opacity: 1;
  transform: scale(1);
}

.first-reading__inscription {
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.6vw, 19.5px);
  letter-spacing: -.005em;
  line-height: 1.2;
  text-align: left;
  opacity: 0;
  transform: translateY(4px);
  transition:
    opacity .9s var(--ease-out) .55s,
    transform .9s var(--ease-out) .55s;
}

.first-reading.is-revealed .first-reading__inscription {
  opacity: 1;
  transform: translateY(0);
}

.first-reading__inscription-mark {
  display: inline-grid;
  place-items: center;
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  color: var(--first-reading-tone);
  opacity: .85;
}

.first-reading__inscription-mark svg {
  width: 100%;
  height: 100%;
  display: block;
}

.first-reading__inscription-body {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.first-reading__inscription-line {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(4px, .5vw, 6px);
  white-space: nowrap;
}

.first-reading__inscription-line--alt {
  padding-left: clamp(10px, 1.4vw, 18px);
  font-style: italic;
  color: var(--mist);
}

.first-reading__inscription-em {
  color: var(--paper);
  font-style: italic;
  font-family: var(--serif);
}

.first-reading__inscription-em--alt {
  color: var(--mist);
  font-style: italic;
  font-size: clamp(13px, 1.3vw, 16.5px);
}

.first-reading__inscription-comma {
  color: var(--first-reading-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.05em;
  opacity: .8;
  margin: 0 2px;
}

.first-reading__sign {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .8vw, 10.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity .8s var(--ease-out) 1.4s;
}

.first-reading.is-revealed .first-reading__sign {
  opacity: .8;
}

.first-reading__sign-svg {
  display: block;
  width: clamp(72px, 9vw, 110px);
  height: 14px;
}

.first-reading__sign-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.1s var(--ease-out) .95s;
}

.first-reading.is-revealed .first-reading__sign-stroke {
  stroke-dashoffset: 0;
}

.first-reading__sign-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.4);
  transition:
    opacity .35s var(--ease) 1.85s,
    transform .55s var(--ease-spring) 1.85s;
}

.first-reading.is-revealed .first-reading__sign-bead {
  opacity: 1;
  transform: scale(1);
}

.first-reading__sign-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.first-reading__sign-tag em {
  color: var(--mist);
  font-style: normal;
  opacity: .55;
  font-family: var(--serif);
  font-size: 1.05em;
}

.first-reading__sign-tag-dot {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--first-reading-tone);
  opacity: .8;
}

@media (max-width: 720px) {
  .first-reading {
    margin: clamp(22px, 6vw, 32px) auto clamp(22px, 6vw, 32px);
  }

  .first-reading__inscription {
    font-size: clamp(13.5px, 4.2vw, 16px);
    gap: 8px;
  }

  .first-reading__inscription-line--alt {
    padding-left: 0;
  }

  .first-reading__inscription-em--alt {
    font-size: clamp(12px, 3.6vw, 14.5px);
  }

  .first-reading__rule {
    width: 100%;
  }

  .first-reading__sign-tag {
    font-size: 8px;
    letter-spacing: .18em;
  }
}

@media (prefers-reduced-motion: reduce) {
  .first-reading__crop,
  .first-reading__rule-stroke,
  .first-reading__rule-bead,
  .first-reading__inscription,
  .first-reading__sign,
  .first-reading__sign-stroke,
  .first-reading__sign-bead {
    transition: none !important;
    animation: none !important;
  }

  .first-reading__crop { opacity: .55; }
  .first-reading__rule-stroke { stroke-dashoffset: 0; }
  .first-reading__rule-bead { opacity: 1; transform: none; }
  .first-reading__inscription { opacity: 1; transform: none; }
  .first-reading__sign { opacity: .8; }
  .first-reading__sign-stroke { stroke-dashoffset: 0; }
  .first-reading__sign-bead { opacity: 1; transform: none; }
}


/* ────────────────────────────────────────────────────────────
   ITERATION 264 · THE READER'S BOOKPLATE

   A tipped slip sits between the letter to the reader and the
   day sheet. The reader types a name; a hand-set ink line draws
   itself beneath it and a wax seal lands on the corner of the
   plate. The signed name echoes in the colophon below.
   ──────────────────────────────────────────────────────────── */

.reader-plate {
  --reader-plate-tone: var(--coral);
  --reader-plate-ink: #16151c;
  --reader-plate-paper: #f3ecd6;
  --reader-plate-paper-2: #e6dec6;
  --reader-plate-paper-3: #d4c7a3;
  --reader-plate-shadow: rgba(14, 15, 21, .45);
  position: relative;
  padding-top: clamp(48px, 6vw, 88px);
  padding-bottom: clamp(64px, 8vw, 112px);
  color: var(--reader-plate-ink);
}

.reader-plate__paper {
  position: relative;
  margin: 0 auto;
  max-width: 760px;
  padding: clamp(36px, 4.4vw, 60px) clamp(28px, 4.6vw, 64px) clamp(40px, 5vw, 72px);
  background: var(--reader-plate-paper);
  color: var(--reader-plate-ink);
  border: 1px solid rgba(40, 32, 18, .12);
  border-radius: 2px;
  box-shadow:
    0 30px 60px -32px rgba(14, 15, 21, .55),
    0 2px 0 rgba(40, 32, 18, .08),
    inset 0 0 0 1px rgba(243, 236, 214, .6);
  transform: rotate(-.4deg);
  transition: transform .9s var(--ease-out), box-shadow .9s var(--ease-out);
}

.reader-plate.is-focused .reader-plate__paper,
.reader-plate.is-signed .reader-plate__paper {
  transform: rotate(-.15deg);
  box-shadow:
    0 38px 80px -32px rgba(14, 15, 21, .6),
    0 2px 0 rgba(40, 32, 18, .08),
    inset 0 0 0 1px rgba(243, 236, 214, .7);
}

.reader-plate__paper::before,
.reader-plate__paper::after {
  content: '';
  position: absolute;
  inset: 6px;
  pointer-events: none;
  border: 1px solid rgba(40, 32, 18, .12);
  border-radius: 2px;
}

.reader-plate__paper::after {
  inset: 11px;
  border-color: rgba(40, 32, 18, .06);
}

.reader-plate__paper-grain {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  mix-blend-mode: multiply;
  opacity: .85;
}

.reader-plate__plate-tag {
  position: absolute;
  top: clamp(-12px, -1vw, -16px);
  left: 50%;
  transform: translate(-50%, -50%) rotate(-.4deg);
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 4px 14px;
  background: var(--night);
  color: var(--paper);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .28em;
  text-transform: uppercase;
  border-radius: 999px;
  border: 1px solid rgba(243, 236, 214, .12);
  white-space: nowrap;
  transition: transform .9s var(--ease-out);
}

.reader-plate.is-focused .reader-plate__plate-tag,
.reader-plate.is-signed .reader-plate__plate-tag {
  transform: translate(-50%, -50%) rotate(.2deg);
}

.reader-plate__plate-tag::before,
.reader-plate__plate-tag::after {
  content: '※';
  color: var(--coral);
  font-size: 11px;
  opacity: .8;
}

.reader-plate__plate-tag::after { content: '※'; }

.reader-plate__corner {
  position: absolute;
  width: 18px;
  height: 18px;
  border-color: rgba(40, 32, 18, .35);
  border-style: solid;
  border-width: 0;
  pointer-events: none;
}

.reader-plate__corner--tl { top: 18px; left: 18px; border-top-width: 1.2px; border-left-width: 1.2px; }
.reader-plate__corner--tr { top: 18px; right: 18px; border-top-width: 1.2px; border-right-width: 1.2px; }
.reader-plate__corner--bl { bottom: 18px; left: 18px; border-bottom-width: 1.2px; border-left-width: 1.2px; }
.reader-plate__corner--br { bottom: 18px; right: 18px; border-bottom-width: 1.2px; border-right-width: 1.2px; }

.reader-plate__head {
  display: flex;
  flex-direction: column;
  gap: 14px;
  align-items: center;
  text-align: center;
  margin-bottom: clamp(28px, 3.4vw, 40px);
}

.reader-plate__head .eyebrow {
  color: rgba(40, 32, 18, .55);
}

.reader-plate__head .eyebrow em {
  color: var(--reader-plate-ink);
  opacity: .65;
}

.reader-plate__head h2 {
  font-family: var(--serif);
  font-weight: 400;
  font-style: italic;
  font-size: clamp(1.8rem, 3.4vw, 2.6rem);
  line-height: 1.06;
  letter-spacing: -.022em;
  color: var(--reader-plate-ink);
  margin: 0;
}

.reader-plate__head h2 i {
  font-style: normal;
  color: var(--reader-plate-tone);
}

.reader-plate__lede {
  max-width: 36em;
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(.94rem, 1.1vw, 1.05rem);
  line-height: 1.55;
  color: rgba(40, 32, 18, .75);
  letter-spacing: .005em;
}

.reader-plate__field {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 10px;
  margin: 0 auto;
  max-width: 460px;
  padding: 4px 0 clamp(20px, 2.4vw, 28px);
}

.reader-plate__field-label {
  display: flex;
  align-items: center;
  gap: 12px;
}

.reader-plate__field-label-mark {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .32em;
  text-transform: uppercase;
  color: rgba(40, 32, 18, .6);
  white-space: nowrap;
}

.reader-plate__field-label-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, rgba(40, 32, 18, .22), rgba(40, 32, 18, 0));
}

.reader-plate__field-row {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.reader-plate__input {
  width: 100%;
  padding: 14px 0 12px;
  background: transparent;
  border: 0;
  border-bottom: 1px dashed rgba(40, 32, 18, .28);
  outline: none;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  line-height: 1.2;
  letter-spacing: -.01em;
  color: var(--reader-plate-ink);
  caret-color: var(--reader-plate-tone);
  transition: border-color .35s var(--ease);
}

.reader-plate__input::placeholder {
  color: rgba(40, 32, 18, .25);
  font-style: italic;
}

.reader-plate__input:focus {
  border-bottom-color: var(--reader-plate-tone);
}

.reader-plate__input.has-value {
  color: var(--reader-plate-ink);
}

.reader-plate__stroke {
  display: block;
  width: 100%;
  height: 18px;
  margin-top: -2px;
  color: var(--reader-plate-ink);
}

.reader-plate__stroke-path {
  transition: stroke-dashoffset 1.3s var(--ease-out);
}

.reader-plate__stroke-bead {
  opacity: 0;
  transform: translateX(-6px);
  transition: opacity 1.3s var(--ease-out) .15s, transform 1.3s var(--ease-out) .15s;
}

.reader-plate.has-value .reader-plate__stroke-bead {
  opacity: .9;
  transform: translateX(0);
}

.reader-plate__hint {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: rgba(40, 32, 18, .55);
}

.reader-plate__hint-glyph {
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  letter-spacing: 0;
  text-transform: none;
  color: var(--reader-plate-tone);
}

.reader-plate__hint kbd {
  font-family: var(--mono);
  font-size: 9px;
  padding: 1px 5px;
  border: 1px solid rgba(40, 32, 18, .25);
  border-radius: 2px;
  background: rgba(40, 32, 18, .04);
  color: rgba(40, 32, 18, .7);
  letter-spacing: .05em;
  text-transform: none;
}

.reader-plate__plate-row {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  margin: clamp(22px, 3vw, 32px) auto 0;
  padding-top: clamp(20px, 2.4vw, 28px);
  border-top: 1px solid rgba(40, 32, 18, .14);
}

.reader-plate__plate-rule {
  height: 1px;
  background: linear-gradient(90deg, rgba(40, 32, 18, .35), rgba(40, 32, 18, 0));
}

.reader-plate__plate-rule--end {
  background: linear-gradient(90deg, rgba(40, 32, 18, 0), rgba(40, 32, 18, .35));
}

.reader-plate__plate-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
  text-align: center;
}

.reader-plate__plate-meta-row {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
}

.reader-plate__plate-meta-eyebrow {
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: rgba(40, 32, 18, .5);
}

.reader-plate__plate-meta-name {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(1rem, 1.4vw, 1.18rem);
  letter-spacing: -.005em;
  color: var(--reader-plate-ink);
  opacity: .35;
  transition: opacity .6s var(--ease);
}

.reader-plate.has-value .reader-plate__plate-meta-name {
  opacity: 1;
}

.reader-plate__plate-meta-date {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(.94rem, 1.2vw, 1.05rem);
  color: var(--reader-plate-ink);
}

.reader-plate__seal {
  position: absolute;
  top: clamp(-22px, -2vw, -28px);
  right: clamp(-18px, -1vw, -22px);
  width: clamp(82px, 8vw, 104px);
  height: clamp(82px, 8vw, 104px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--wax);
  transform: rotate(8deg) scale(.9);
  opacity: 0;
  transition: transform .9s var(--ease-spring), opacity .6s var(--ease);
  pointer-events: none;
  filter: drop-shadow(0 6px 10px rgba(40, 32, 18, .18));
}

.reader-plate__seal.is-pressed {
  transform: rotate(6deg) scale(1);
  opacity: 1;
}

.reader-plate__seal-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.reader-plate__seal-wax {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.reader-plate__seal-wax-bead {
  position: absolute;
  top: 78%;
  left: 12%;
  width: 7px;
  height: 7px;
  background: var(--wax);
  border-radius: 50%;
  opacity: 0;
  transform: scale(.4);
  box-shadow: 0 0 0 1px rgba(40, 32, 18, .08);
  transition: opacity .5s var(--ease) .55s, transform .55s var(--ease-spring) .55s;
}

.reader-plate__seal-wax-wisp {
  position: absolute;
  top: 84%;
  left: 16%;
  width: 12px;
  height: 2px;
  background: var(--wax);
  border-radius: 2px;
  opacity: 0;
  transform: translateX(-3px) rotate(28deg);
  transition: opacity .5s var(--ease) .7s, transform .55s var(--ease-out) .7s;
}

.reader-plate__seal-wax-drip {
  position: absolute;
  top: 88%;
  left: 20%;
  width: 3px;
  height: 9px;
  background: var(--wax);
  border-radius: 2px 2px 4px 4px;
  opacity: 0;
  transform: translateY(-2px);
  transition: opacity .5s var(--ease) .82s, transform .6s var(--ease-out) .82s;
}

.reader-plate.is-signed .reader-plate__seal-wax-bead {
  opacity: .85;
  transform: scale(1);
}

.reader-plate.is-signed .reader-plate__seal-wax-wisp {
  opacity: .65;
  transform: translateX(0) rotate(28deg);
}

.reader-plate.is-signed .reader-plate__seal-wax-drip {
  opacity: .7;
  transform: translateY(0);
}

.reader-plate__foot {
  margin-top: clamp(20px, 2.6vw, 32px);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.reader-plate__foot-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, rgba(40, 32, 18, 0), rgba(40, 32, 18, .22), rgba(40, 32, 18, 0));
}

.reader-plate__foot-text {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(.9rem, 1vw, 1rem);
  color: rgba(40, 32, 18, .7);
}

.reader-plate__foot-text em { font-style: italic; }

.reader-plate__scrawl {
  display: block;
  width: clamp(120px, 22%, 220px);
  height: 18px;
  margin: clamp(20px, 2.4vw, 28px) auto 0;
  color: rgba(40, 32, 18, .35);
}

.reader-plate__scrawl-svg {
  width: 100%;
  height: 100%;
}

.reader-plate__scrawl-stroke {
  transition: stroke-dashoffset 1.4s var(--ease-out);
}

.reader-plate__scrawl-bead {
  opacity: 0;
  transition: opacity 1.4s var(--ease-out) .2s;
}

.reader-plate.has-value .reader-plate__scrawl-bead {
  opacity: .8;
}

@media (max-width: 720px) {
  .reader-plate__paper {
    transform: rotate(-.15deg);
    padding: 32px 22px 40px;
  }
  .reader-plate.is-focused .reader-plate__paper,
  .reader-plate.is-signed .reader-plate__paper {
    transform: rotate(0deg);
  }
  .reader-plate__plate-row {
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    gap: 10px;
  }
  .reader-plate__seal {
    top: -22px;
    right: -10px;
    width: 78px;
    height: 78px;
  }
  .reader-plate__head h2 {
    font-size: clamp(1.6rem, 5vw, 2rem);
  }
}

@media (max-width: 540px) {
  .reader-plate__paper::before { inset: 5px; }
  .reader-plate__paper::after { inset: 9px; }
  .reader-plate__field-label-mark {
    font-size: 9px;
    letter-spacing: .24em;
  }
  .reader-plate__input {
    font-size: clamp(1.4rem, 6vw, 1.8rem);
  }
  .reader-plate__seal {
    width: 64px;
    height: 64px;
    top: -16px;
    right: -6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .reader-plate__paper,
  .reader-plate__plate-tag {
    transition: none !important;
  }
  .reader-plate__stroke-path,
  .reader-plate__scrawl-stroke,
  .reader-plate__stroke-bead,
  .reader-plate__scrawl-bead,
  .reader-plate__seal,
  .reader-plate__seal-wax-bead,
  .reader-plate__seal-wax-wisp,
  .reader-plate__seal-wax-drip {
    transition: none !important;
    animation: none !important;
  }
  .reader-plate__stroke-path,
  .reader-plate__scrawl-stroke {
    stroke-dashoffset: 0 !important;
  }
  .reader-plate.is-signed .reader-plate__seal,
  .reader-plate__seal.is-pressed {
    transform: rotate(6deg) scale(1) !important;
    opacity: 1 !important;
  }
  .reader-plate.is-signed .reader-plate__seal-wax-bead,
  .reader-plate.is-signed .reader-plate__seal-wax-wisp,
  .reader-plate.is-signed .reader-plate__seal-wax-drip {
    opacity: 1 !important;
    transform: none !important;
  }
}


/* ────────────────────────────────────────────────────────────
   ITERATION 264 · COLOPHON · the reader's name echoes here
   ──────────────────────────────────────────────────────────── */

.colophon.is-signed .colophon__reader-name {
  color: var(--coral);
}

.colophon__reader {
  position: relative;
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
}

.colophon__reader-name {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(1rem, 1.3vw, 1.15rem);
  color: var(--ink-mist);
  transition: color .6s var(--ease);
}

.colophon__reader.is-set .colophon__reader-name {
  color: var(--coral);
}

.colophon__reader-rule {
  display: inline-flex;
  align-items: center;
  width: clamp(40px, 6vw, 86px);
  height: 8px;
  color: var(--coral);
  opacity: 0;
  transform: translateX(-6px);
  transition: opacity .6s var(--ease) .2s, transform .7s var(--ease-out) .2s;
}

.colophon.is-signed .colophon__reader-rule {
  opacity: .85;
  transform: translateX(0);
}

.colophon__reader-rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset .9s var(--ease-out) .35s;
}

.colophon.is-signed .colophon__reader-rule-stroke {
  stroke-dashoffset: 0;
}

.colophon__reader-rule-bead {
  opacity: 0;
  transition: opacity .5s var(--ease) .6s;
}

.colophon.is-signed .colophon__reader-rule-bead {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .colophon__reader-name,
  .colophon__reader-rule,
  .colophon__reader-rule-stroke,
  .colophon__reader-rule-bead {
    transition: none !important;
  }
  .colophon__reader-rule-stroke { stroke-dashoffset: 0 !important; }
  .colophon__reader-rule { opacity: 1 !important; transform: none !important; }
  .colophon__reader-rule-bead { opacity: 1 !important; }
}


/* ────────────────────────────────────────────────────────────
   ITERATION 265 · unify the press chrome into a single
   "press plate" and replace the hero certificate with a
   three-readings ribbon. Trim ornamental noise so the
   title page reads as one confident composition.
   ──────────────────────────────────────────────────────────── */

.hero__chrome {
  display: block;
  margin-top: clamp(20px, 2.6vw, 36px);
  padding-top: clamp(20px, 2.4vw, 32px);
  border-top: 1px dashed var(--line-soft);
}

.hero__body-grid--single {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, .95fr);
  gap: clamp(28px, 3.6vw, 56px);
  align-items: start;
}

@media (max-width: 920px) {
  .hero__body-grid--single {
    grid-template-columns: minmax(0, 1fr);
    gap: clamp(22px, 3vw, 36px);
  }
}

.hero__summary {
  position: relative;
  display: grid;
  grid-template-columns: clamp(56px, 6vw, 84px) minmax(0, 1fr);
  column-gap: clamp(14px, 1.6vw, 22px);
  row-gap: 14px;
  align-items: start;
  padding: 4px 0 0;
}

.hero__summary-text {
  display: grid;
  gap: clamp(10px, 1.2vw, 14px);
  min-width: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(15.5px, 1.4vw, 19px);
  line-height: 1.55;
  letter-spacing: -.005em;
}

.hero__summary-paragraph em {
  color: var(--coral);
  font-style: italic;
  transition: color .45s var(--ease);
}

.app--voice-quiet .hero__summary-paragraph em { color: var(--blue); }
.app--voice-human .hero__summary-paragraph em { color: var(--coral); }
.app--voice-bold .hero__summary-paragraph em { color: var(--acid); }

.hero__summary-scrawl {
  grid-column: 2;
  display: block;
  width: clamp(160px, 26vw, 240px);
  height: 12px;
  margin-top: 2px;
  color: var(--coral);
  transition: color .45s var(--ease);
}

.app--voice-quiet .hero__summary-scrawl { color: var(--blue); }
.app--voice-human .hero__summary-scrawl { color: var(--coral); }
.app--voice-bold .hero__summary-scrawl { color: var(--acid); }

.hero__summary-scrawl-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.1s var(--ease-out) .4s;
}

.hero__body.is-in-view .hero__summary-scrawl-stroke { stroke-dashoffset: 0; }
.hero__body.is-in-view .hero__summary-scrawl-bead {
  animation: summaryScrawlBead .55s var(--ease-spring) 1.4s backwards;
}

@keyframes summaryScrawlBead {
  from { opacity: 0; transform: scale(.2); transform-box: fill-box; transform-origin: center; }
  to { opacity: 1; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .hero__summary-scrawl-stroke { stroke-dashoffset: 0 !important; transition: none !important; }
  .hero__summary-scrawl-bead { animation: none !important; opacity: 1 !important; }
}

/* Three-readings ribbon — replaces the certificate panel. */

.hero__readings {
  position: relative;
  display: grid;
  gap: clamp(14px, 1.4vw, 20px);
  padding: clamp(20px, 2.2vw, 28px) clamp(20px, 2.4vw, 30px);
  border: 1px solid var(--line-soft);
  border-radius: 2px;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .28), rgba(14, 20, 32, .44));
  box-shadow: none;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .7s var(--ease-out) .1s, transform .7s var(--ease-out) .1s;
}

.hero__body.is-in-view .hero__readings {
  opacity: 1;
  transform: translateY(0);
}

.hero__readings-rule {
  display: block;
  width: 64px;
  height: 1px;
  background: linear-gradient(to right, currentColor, transparent);
  opacity: .55;
  justify-self: start;
  transition: background .45s var(--ease);
}

.hero__readings-rule--trail {
  background: linear-gradient(to left, currentColor, transparent);
  justify-self: end;
}

.hero__readings-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  align-self: start;
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.hero__readings-eyebrow-mark {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 9px;
  letter-spacing: 0;
  text-transform: none;
}

.hero__readings-eyebrow-mark::before {
  content: 'iii';
}

.hero__readings-list {
  display: grid;
  gap: clamp(8px, 1vw, 12px);
  margin: 0;
  padding: 0;
  list-style: none;
}

.hero__readings-item {
  display: grid;
  grid-template-columns: clamp(28px, 2.4vw, 36px) minmax(0, 1fr) auto;
  column-gap: clamp(10px, 1.2vw, 14px);
  row-gap: 2px;
  align-items: center;
  padding: clamp(8px, 1vw, 12px) clamp(10px, 1.1vw, 14px);
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  background: rgba(20, 26, 38, .32);
  color: var(--muted);
  transition:
    border-color .45s var(--ease),
    background .45s var(--ease),
    color .45s var(--ease),
    transform .55s var(--ease-spring);
}

.hero__readings-item--quiet.is-active {
  border-color: rgba(155, 188, 255, .42);
  background: rgba(155, 188, 255, .08);
  color: var(--paper);
}

.hero__readings-item--human.is-active {
  border-color: rgba(255, 118, 95, .42);
  background: rgba(255, 118, 95, .08);
  color: var(--paper);
}

.hero__readings-item--bold.is-active {
  border-color: rgba(216, 240, 106, .42);
  background: rgba(216, 240, 106, .08);
  color: var(--paper);
}

.hero__readings-letter {
  display: inline-grid;
  place-items: center;
  width: clamp(26px, 2.4vw, 32px);
  height: clamp(26px, 2.4vw, 32px);
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: 0;
  transition: color .45s var(--ease), border-color .45s var(--ease);
}

.hero__readings-item.is-active .hero__readings-letter {
  color: var(--press-plate-tone, currentColor);
  border-color: var(--press-plate-tone, currentColor);
  background: rgba(255, 255, 255, .03);
}

.hero__readings-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.hero__readings-setting {
  color: inherit;
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .85;
}

.hero__readings-lines {
  display: grid;
  gap: 1px;
  color: inherit;
  font-family: var(--serif);
  font-size: clamp(13px, 1.1vw, 15.5px);
  line-height: 1.2;
}

.hero__readings-lines span em {
  color: inherit;
  font-style: italic;
  opacity: .85;
}

.hero__readings-item--bold .hero__readings-lines {
  font-family: var(--sans);
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: -.06em;
  font-size: clamp(12px, 1.05vw, 14px);
  opacity: .95;
}

.hero__readings-item--bold .hero__readings-lines em { font-style: normal; }

.hero__readings-face {
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(10.5px, .9vw, 12px);
  letter-spacing: -.01em;
  white-space: nowrap;
  justify-self: end;
  transition: color .45s var(--ease);
}

.hero__readings-item.is-active .hero__readings-face { color: var(--paper); }

.hero__readings-foot {
  display: block;
  color: var(--muted);
  font-family: var(--serif);
  font-size: clamp(11px, .9vw, 12px);
  font-style: italic;
  line-height: 1.4;
  text-align: center;
  opacity: .7;
}

/* ────────────────────────────────────────────────────────────
   SPECIMEN TRAY · three paper sheets fanned across the press
   tray. The active sheet stands forward, the others settle
   back with paper grain, crop marks, ink chip, and a subtle
   press-rule. Replaces the previous flat hero readings list
   so the hero body carries the same tactile weight as the
   press bed below it.
   ──────────────────────────────────────────────────────────── */

.specimen-tray {
  --tray-pad-x: clamp(16px, 2vw, 26px);
  --tray-pad-y: clamp(18px, 2.4vw, 30px);
  --tray-tilt: var(--specimen-tilt, 0deg);
  --tray-stack-x: var(--specimen-stack-x, 0px);
  --tray-stack-y: var(--specimen-stack-y, 0px);
  --tray-z: var(--specimen-z, 1);
  position: relative;
  display: grid;
  gap: clamp(10px, 1vw, 14px);
  padding: var(--tray-pad-y) var(--tray-pad-x) clamp(14px, 1.6vw, 22px);
  border: 1px solid var(--line);
  border-radius: 1px;
  background:
    linear-gradient(180deg, rgba(20, 28, 44, .42), rgba(10, 14, 22, .62));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .05),
    0 26px 60px -36px rgba(0, 0, 0, .65),
    0 8px 18px -14px rgba(0, 0, 0, .55);
  isolation: isolate;
  overflow: hidden;
}

.specimen-tray::before {
  content: '';
  position: absolute;
  inset: 8px;
  border: 1px dashed rgba(243, 236, 214, .08);
  border-radius: 1px;
  pointer-events: none;
  z-index: 0;
}

.specimen-tray__rail {
  position: absolute;
  inset: 14px 8px 14px 8px;
  color: var(--paper);
  opacity: .55;
  pointer-events: none;
  z-index: 0;
}

.specimen-tray__rail svg {
  width: 100%;
  height: 100%;
  display: block;
}

.specimen-tray__rail-tag {
  position: absolute;
  top: 6px;
  left: 50%;
  transform: translate(-50%, -50%);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 3px 11px;
  background: var(--night);
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--ink-mist);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  z-index: 1;
}

.specimen-tray__rail-tag-mark {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1px solid currentColor;
  position: relative;
}

.specimen-tray__rail-tag-mark::after {
  content: '';
  position: absolute;
  inset: 1.5px;
  border-radius: 50%;
  background: var(--paper);
  opacity: .65;
}

.specimen-tray__deck {
  position: relative;
  height: clamp(310px, 36vw, 380px);
  perspective: 1400px;
  z-index: 1;
}

.specimen-tray__sheet {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-rows: auto 1fr auto auto;
  gap: clamp(10px, 1.2vw, 14px);
  padding: clamp(18px, 2.2vw, 26px) clamp(20px, 2.4vw, 28px);
  text-align: left;
  border: 1px solid var(--specimen-edge);
  border-radius: 2px;
  background: var(--specimen-paper);
  color: var(--paper);
  font-family: var(--serif);
  cursor: pointer;
  transform-origin: center center;
  transition:
    transform .85s var(--ease-out),
    opacity .65s var(--ease),
    filter .65s var(--ease),
    box-shadow .85s var(--ease-out),
    z-index 0s linear .35s;
  z-index: var(--tray-z);
  opacity: .55;
  filter: saturate(.65) brightness(.82);
  box-shadow:
    0 22px 38px -22px rgba(0, 0, 0, .55),
    0 10px 14px -10px rgba(0, 0, 0, .35),
    inset 0 0 0 1px rgba(255, 255, 255, .02);
  will-change: transform, opacity;
}

.specimen-tray__sheet--quiet {
  --specimen-tilt: -3.2deg;
  --specimen-stack-x: -16px;
  --specimen-stack-y: -10px;
  --specimen-edge: rgba(155, 188, 255, .34);
  --specimen-ink: var(--paper);
  --specimen-paper: linear-gradient(180deg, #1a2030 0%, #0f1424 100%);
}

.specimen-tray__sheet--human {
  --specimen-tilt: 1.6deg;
  --specimen-stack-x: 6px;
  --specimen-stack-y: 8px;
  --specimen-edge: rgba(255, 118, 95, .42);
  --specimen-ink: var(--coral);
  --specimen-paper: linear-gradient(180deg, #21151c 0%, #160e15 100%);
}

.specimen-tray__sheet--bold {
  --specimen-tilt: -1.6deg;
  --specimen-stack-x: 18px;
  --specimen-stack-y: -4px;
  --specimen-edge: rgba(216, 240, 106, .4);
  --specimen-ink: var(--acid);
  --specimen-paper: linear-gradient(180deg, #11181f 0%, #0a0e14 100%);
}

.specimen-tray__sheet:not(.is-active):not(.is-hovered) {
  transform:
    translate(var(--specimen-stack-x), var(--specimen-stack-y))
    rotate(var(--specimen-tilt))
    scale(.94);
}

.specimen-tray__sheet.is-hovered {
  opacity: .88;
  filter: saturate(.95) brightness(.96);
  transform:
    translate(calc(var(--specimen-stack-x) * .5), calc(var(--specimen-stack-y) * .5))
    rotate(calc(var(--specimen-tilt) * .5))
    scale(.97);
  box-shadow:
    0 28px 44px -20px rgba(0, 0, 0, .55),
    0 12px 18px -12px rgba(0, 0, 0, .4),
    inset 0 0 0 1px rgba(255, 255, 255, .04);
}

.specimen-tray__sheet.is-active {
  cursor: default;
  opacity: 1;
  filter: none;
  z-index: 4;
  transform:
    translate(0, 0)
    rotate(0deg)
    scale(1);
  box-shadow:
    0 38px 64px -22px rgba(0, 0, 0, .7),
    0 18px 28px -16px rgba(0, 0, 0, .5),
    0 0 0 1px rgba(243, 236, 214, .04),
    inset 0 0 60px rgba(0, 0, 0, .25);
}

.specimen-tray__sheet:focus-visible {
  outline: 1px solid var(--acid);
  outline-offset: 6px;
}

.specimen-tray__paper {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .85;
  mix-blend-mode: multiply;
}

.specimen-tray__paper::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 18% 6%, rgba(243, 236, 214, .06), transparent 50%),
    radial-gradient(ellipse at 82% 92%, rgba(0, 0, 0, .28), transparent 60%);
  pointer-events: none;
}

.specimen-tray__grain {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: .55;
}

.specimen-tray__edge {
  position: absolute;
  left: 14px;
  right: 14px;
  height: 1px;
  background: var(--specimen-edge);
  opacity: .7;
  pointer-events: none;
}

.specimen-tray__edge--top { top: 6px; }
.specimen-tray__edge--bottom { bottom: 6px; }

.specimen-tray__corners {
  position: absolute;
  inset: 6px 6px 6px 6px;
  color: var(--specimen-edge);
  pointer-events: none;
}

.specimen-tray__crop {
  position: absolute;
  width: 16px;
  height: 16px;
}

.specimen-tray__crop--tl { top: 0; left: 0; }
.specimen-tray__crop--tr { top: 0; right: 0; }
.specimen-tray__crop--bl { bottom: 0; left: 0; }
.specimen-tray__crop--br { bottom: 0; right: 0; }

.specimen-tray__plate {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 9px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--muted);
  position: relative;
  z-index: 1;
}

.specimen-tray__plate-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--specimen-edge), transparent);
  opacity: .8;
}

.specimen-tray__plate-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.specimen-tray__plate-tag-dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--specimen-ink);
  opacity: .8;
}

.specimen-tray__chip-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.2vw, 14px);
  position: relative;
  z-index: 1;
}

.specimen-tray__chip {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
}

.specimen-tray__chip-disc {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(36px, 3.4vw, 46px);
  height: clamp(36px, 3.4vw, 46px);
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.4vw, 19px);
  letter-spacing: -.02em;
  box-shadow:
    inset 0 1px 2px rgba(255, 255, 255, .22),
    inset 0 -3px 6px rgba(0, 0, 0, .22),
    0 4px 10px rgba(0, 0, 0, .35);
}

.specimen-tray__chip-disc em {
  position: relative;
  z-index: 1;
}

.specimen-tray__chip-disc-ring {
  position: absolute;
  inset: 4px;
  border: 1px dashed currentColor;
  border-radius: 50%;
  opacity: .4;
}

.specimen-tray__chip-rule {
  width: clamp(20px, 2vw, 36px);
  height: 1px;
  background: var(--specimen-edge);
}

.specimen-tray__chip-meta {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.specimen-tray__chip-name {
  color: var(--specimen-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.35vw, 19px);
  font-weight: 500;
  letter-spacing: -.012em;
  line-height: 1.1;
}

.specimen-tray__chip-face {
  color: var(--ink-mist);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.specimen-tray__chip-swatch {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.specimen-tray__chip-swatch-ink {
  display: inline-block;
  width: clamp(14px, 1.4vw, 18px);
  height: clamp(14px, 1.4vw, 18px);
  border-radius: 50%;
  border: 1px solid rgba(243, 236, 214, .35);
  box-shadow:
    inset 0 -2px 4px rgba(0, 0, 0, .25),
    0 1px 2px rgba(0, 0, 0, .35);
}

.specimen-tray__chip-swatch-rule {
  display: none;
}

.specimen-tray__sample {
  display: grid;
  align-content: center;
  justify-items: start;
  gap: 2px;
  min-height: 0;
  position: relative;
  z-index: 1;
}

.specimen-tray__sample-display {
  color: var(--specimen-ink);
  font-size: clamp(2rem, 4.4vw, 3rem);
  line-height: 1;
}

.specimen-tray__sample-body {
  color: var(--paper);
  font-size: clamp(1.1rem, 1.9vw, 1.6rem);
  line-height: 1.1;
  opacity: .92;
}

.specimen-tray__sample-micro {
  color: var(--paper);
  font-size: clamp(.95rem, 1.55vw, 1.25rem);
  line-height: 1.1;
  opacity: .82;
}

.specimen-tray__sheet--bold .specimen-tray__sample-display,
.specimen-tray__sheet--bold .specimen-tray__sample-body,
.specimen-tray__sheet--bold .specimen-tray__sample-micro {
  font-family: var(--sans);
  font-weight: 800;
  letter-spacing: -.06em;
  text-transform: uppercase;
  color: var(--specimen-ink);
}

.specimen-tray__sheet--bold .specimen-tray__sample-body,
.specimen-tray__sheet--bold .specimen-tray__sample-micro {
  color: var(--paper);
  opacity: .96;
}

.specimen-tray__motto {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(10.5px, .9vw, 12px);
  letter-spacing: -.01em;
  line-height: 1.3;
  position: relative;
  z-index: 1;
}

.specimen-tray__motto-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--specimen-edge), transparent);
  opacity: .65;
}

.specimen-tray__motto em {
  white-space: nowrap;
  opacity: .85;
}

.specimen-tray__foot {
  display: grid;
  gap: 4px;
  position: relative;
  z-index: 1;
  padding-top: 8px;
  border-top: 1px solid rgba(243, 236, 214, .08);
}

.specimen-tray__foot-row {
  display: flex;
  align-items: baseline;
  gap: clamp(10px, 1.2vw, 14px);
  flex-wrap: wrap;
}

.specimen-tray__foot-tag {
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.specimen-tray__foot-value {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  color: var(--paper);
  letter-spacing: -.005em;
  opacity: .9;
}

.specimen-tray__foot-value span {
  margin: 0 6px;
  opacity: .55;
}

.specimen-tray__now {
  position: absolute;
  top: 8px;
  right: 12px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px;
  border-radius: 999px;
  background: rgba(15, 20, 32, .82);
  border: 1px solid var(--specimen-edge);
  color: var(--specimen-ink);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity .55s var(--ease);
  pointer-events: none;
  z-index: 2;
}

.specimen-tray__sheet.is-active .specimen-tray__now,
.specimen-tray__sheet.is-hovered .specimen-tray__now {
  opacity: 1;
}

.specimen-tray__now-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--specimen-ink);
  box-shadow: 0 0 0 2px rgba(255, 255, 255, .12);
  animation: specimenNowPulse 2.4s var(--ease-out) infinite;
}

.specimen-tray__sheet.is-active .specimen-tray__now-dot {
  animation: specimenNowPulse 1.6s var(--ease-out) infinite;
}

@keyframes specimenNowPulse {
  0%, 100% { transform: scale(1); opacity: .9; }
  50% { transform: scale(1.18); opacity: 1; }
}

.specimen-tray__hint {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 6px 10px;
  border-top: 1px dashed var(--line-soft);
  color: var(--ink-mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .9vw, 12.5px);
  letter-spacing: -.005em;
  text-align: center;
  position: relative;
  z-index: 1;
}

.specimen-tray__hint-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--paper);
  opacity: .55;
}

@media (max-width: 980px) {
  .specimen-tray__deck {
    height: clamp(330px, 56vw, 420px);
  }

  .specimen-tray__sheet:not(.is-active):not(.is-hovered) {
    transform:
      translate(calc(var(--specimen-stack-x) * .8), calc(var(--specimen-stack-y) * .8))
      rotate(calc(var(--specimen-tilt) * .8))
      scale(.94);
  }
}

@media (max-width: 720px) {
  .specimen-tray {
    --tray-pad-x: 14px;
    --tray-pad-y: 16px;
  }

  .specimen-tray__deck {
    height: 380px;
  }

  .specimen-tray__sheet {
    padding: 14px 16px;
  }

  .specimen-tray__sample-display {
    font-size: clamp(1.65rem, 6.4vw, 2.3rem);
  }

  .specimen-tray__sample-body {
    font-size: clamp(.95rem, 3.6vw, 1.15rem);
  }

  .specimen-tray__sample-micro {
    font-size: clamp(.85rem, 3vw, 1rem);
  }

  .specimen-tray__foot-value {
    font-size: 11px;
  }

  .specimen-tray__rail-tag {
    font-size: 8px;
    letter-spacing: .18em;
    padding: 2px 9px;
  }

  .specimen-tray__now {
    top: 6px;
    right: 8px;
    font-size: 8px;
  }
}

@media (max-width: 540px) {
  .specimen-tray__deck {
    height: 360px;
  }

  .specimen-tray__chip-name {
    font-size: 14px;
  }

  .specimen-tray__chip-face {
    font-size: 7.5px;
    letter-spacing: .18em;
  }

  .specimen-tray__hint {
    font-size: 10.5px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .specimen-tray,
  .specimen-tray__sheet,
  .specimen-tray__now-dot,
  .specimen-tray__grain {
    transition: none !important;
    animation: none !important;
    transform: none !important;
  }

  .specimen-tray__sheet.is-active {
    transform: translate(0, 0) !important;
  }

  .specimen-tray__sheet:not(.is-active):not(.is-hovered) {
    transform:
      translate(var(--specimen-stack-x), var(--specimen-stack-y))
      rotate(var(--specimen-tilt))
      scale(.94) !important;
  }
}

/* End hero body refinements: hide what's been removed. */

.hero__certificate,
.hero__certificate-frame,
.hero__certificate-frame-corner,
.hero__certificate-head,
.hero__certificate-head-eyebrow,
.hero__certificate-head-folio,
.hero__certificate-list,
.hero__certificate-row,
.hero__certificate-letter,
.hero__certificate-voice-name,
.hero__certificate-foot,
.hero__certificate-foot-hint,
.hero__certificate-foot-text {
  display: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .hero__readings,
  .hero__summary-scrawl-bead {
    transition: none !important;
    animation: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

/* ────────────────────────────────────────────────────────────
   PRESS PLATE · a single elegant card that owns the press
   chrome: three voice chips on the left, a centered hairline
   ornament, and the "open the editor's note" action on the
   right. A caption row above names it; a small footer row
   below records the current setting, the keyboard hint, and
   the date.
   ──────────────────────────────────────────────────────────── */

.press-plate {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(8px, 1vw, 12px);
  width: 100%;
  padding: clamp(14px, 1.6vw, 22px);
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--paper);
  background:
    radial-gradient(circle at 0 0%, rgba(216, 240, 106, .05), transparent 55%),
    radial-gradient(circle at 100% 100%, rgba(146, 186, 255, .05), transparent 55%),
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(14, 20, 32, .6));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 24px 48px -34px rgba(0, 0, 0, .7);
  opacity: 0;
  transform: translateY(8px);
  animation: pressPlateIn .65s var(--ease-out) .25s forwards;
}

@keyframes pressPlateIn {
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .press-plate { animation: none !important; opacity: 1 !important; transform: none !important; }
}

.press-plate__crop {
  position: absolute;
  width: 12px;
  height: 12px;
  border: 1px solid currentColor;
  color: var(--muted);
  opacity: .4;
  pointer-events: none;
  transition: color .45s var(--ease);
}

.press-plate__crop--tl { top: 6px; left: 6px; border-right: 0; border-bottom: 0; }
.press-plate__crop--tr { top: 6px; right: 6px; border-left: 0; border-bottom: 0; }
.press-plate__crop--bl { bottom: 6px; left: 6px; border-right: 0; border-top: 0; }
.press-plate__crop--br { bottom: 6px; right: 6px; border-left: 0; border-top: 0; }

.press-plate--quiet .press-plate__crop { color: var(--blue); }
.press-plate--human .press-plate__crop { color: var(--coral); }
.press-plate--bold .press-plate__crop { color: var(--acid); }

.press-plate__head {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, 1vw, 14px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .28em;
  text-transform: uppercase;
}

.press-plate__head-mark {
  display: inline-grid;
  place-items: center;
  width: 16px;
  height: 16px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
  opacity: .7;
}

.press-plate__head-mark--alt { transform: scaleX(-1); }

.press-plate__head-line {
  position: relative;
  padding-bottom: 2px;
  color: var(--muted);
}

.press-plate__head-line::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 30%, var(--line) 70%, transparent);
}

.press-plate__inner {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) auto minmax(0, 1fr);
  gap: clamp(10px, 1.4vw, 18px);
  align-items: stretch;
  padding-top: clamp(10px, 1.1vw, 14px);
  padding-bottom: clamp(10px, 1.1vw, 14px);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
}

@media (max-width: 920px) {
  .press-plate__inner {
    grid-template-columns: minmax(0, 1fr);
    gap: clamp(12px, 1.6vw, 20px);
  }
}

/* Voice chips */

.press-plate__voices {
  display: grid;
  gap: clamp(8px, .9vw, 12px);
  align-content: center;
  min-width: 0;
}

.press-plate__voices-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, .9vw, 12px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .6vw, 8px);
  letter-spacing: .26em;
  text-transform: uppercase;
}

.press-plate__voices-eyebrow-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 50%, var(--line));
  opacity: .55;
}

.press-plate__voices-eyebrow-rule:last-child {
  background: linear-gradient(to left, transparent, var(--line) 50%, var(--line));
}

.press-plate__voices-eyebrow-tag {
  flex: 0 0 auto;
  padding: 0 4px;
}

.press-plate__voices-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(8px, .9vw, 12px);
  margin: 0;
  padding: 0;
  list-style: none;
}

@media (max-width: 540px) {
  .press-plate__voices-list {
    grid-template-columns: 1fr;
  }
}

.press-plate__voice {
  position: relative;
  display: contents;
}

.press-plate__voice-divider {
  display: none;
}

.press-plate__voice-button {
  display: grid;
  grid-template-columns: clamp(18px, 1.6vw, 22px) minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: clamp(8px, .9vw, 12px);
  row-gap: 2px;
  align-items: center;
  width: 100%;
  padding: clamp(8px, .9vw, 12px) clamp(10px, 1.1vw, 14px);
  border: 1px solid var(--line);
  border-radius: 2px;
  background: rgba(20, 26, 38, .25);
  text-align: left;
  cursor: pointer;
  color: var(--muted);
  transition:
    border-color .45s var(--ease),
    color .45s var(--ease),
    background .45s var(--ease),
    transform .5s var(--ease-spring),
    box-shadow .55s var(--ease);
}

.press-plate__voice-button:hover,
.press-plate__voice-button:focus-visible {
  color: var(--paper);
  border-color: rgba(216, 240, 106, .25);
  transform: translateY(-1px);
}

.press-plate__voice-bullet {
  grid-row: 1;
  grid-column: 1;
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(18px, 1.6vw, 22px);
  height: clamp(18px, 1.6vw, 22px);
}

.press-plate__voice-bullet-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  opacity: .55;
  transition: opacity .45s var(--ease), background .45s var(--ease);
}

.press-plate__voice-bullet-ring {
  position: absolute;
  inset: 0;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: .35;
  transition: opacity .45s var(--ease), transform .55s var(--ease);
}

.press-plate__voice-letter {
  grid-row: 1;
  grid-column: 2;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: 0;
  line-height: 1;
  color: inherit;
}

.press-plate__voice-copy {
  grid-row: 2;
  grid-column: 2;
  display: grid;
  gap: 1px;
  min-width: 0;
}

.press-plate__voice-name {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.15vw, 15.5px);
  letter-spacing: -.012em;
  line-height: 1.1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.press-plate__voice-face {
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .18em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: .8;
}

.press-plate__voice-button--quiet { color: var(--blue); }
.press-plate__voice-button--human { color: var(--coral); }
.press-plate__voice-button--bold {
  color: var(--acid);
}

.press-plate__voice-button--bold .press-plate__voice-name {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 850;
  text-transform: uppercase;
  letter-spacing: -.04em;
  font-size: clamp(12px, 1.05vw, 14px);
}

.press-plate__voice.is-active .press-plate__voice-button--quiet {
  border-color: rgba(155, 188, 255, .55);
  background: linear-gradient(180deg, rgba(155, 188, 255, .14), rgba(155, 188, 255, .04));
  color: var(--paper);
  box-shadow: inset 0 0 0 1px rgba(155, 188, 255, .12), 0 10px 22px -16px rgba(155, 188, 255, .45);
}

.press-plate__voice.is-active .press-plate__voice-button--human {
  border-color: rgba(255, 118, 95, .55);
  background: linear-gradient(180deg, rgba(255, 118, 95, .14), rgba(255, 118, 95, .04));
  color: var(--paper);
  box-shadow: inset 0 0 0 1px rgba(255, 118, 95, .12), 0 10px 22px -16px rgba(255, 118, 95, .45);
}

.press-plate__voice.is-active .press-plate__voice-button--bold {
  border-color: rgba(216, 240, 106, .55);
  background: linear-gradient(180deg, rgba(216, 240, 106, .14), rgba(216, 240, 106, .04));
  color: var(--paper);
  box-shadow: inset 0 0 0 1px rgba(216, 240, 106, .12), 0 10px 22px -16px rgba(216, 240, 106, .45);
}

.press-plate__voice.is-active .press-plate__voice-bullet-dot {
  opacity: 1;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, .04), 0 0 8px currentColor;
}

.press-plate__voice.is-active .press-plate__voice-bullet-ring {
  opacity: 1;
  transform: scale(1.15);
}

/* Center ornament */

.press-plate__rule {
  display: grid;
  grid-template-rows: 1fr auto 1fr;
  align-items: center;
  gap: 8px;
  width: 56px;
  color: var(--press-plate-tone, var(--coral));
  transition: color .55s var(--ease);
}

@media (max-width: 920px) {
  .press-plate__rule {
    display: none;
  }
}

.press-plate__rule-line {
  display: block;
  height: 100%;
  width: 1px;
  background: currentColor;
  opacity: .45;
}

.press-plate__rule-line--a { background: linear-gradient(to bottom, transparent, currentColor 30%, currentColor 70%, transparent); }
.press-plate__rule-line--b { background: linear-gradient(to bottom, transparent, currentColor 30%, currentColor 70%, transparent); }

.press-plate__rule-mark {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  margin: 0 auto;
}

.press-plate__rule-mark svg { width: 100%; height: 100%; }

/* Action button */

.press-plate__action {
  display: grid;
  gap: clamp(8px, .9vw, 12px);
  align-content: center;
  min-width: 0;
}

.press-plate__action-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, .9vw, 12px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .6vw, 8px);
  letter-spacing: .26em;
  text-transform: uppercase;
}

.press-plate__action-eyebrow-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 50%, var(--line));
  opacity: .55;
}

.press-plate__action-eyebrow-rule:last-child {
  background: linear-gradient(to left, transparent, var(--line) 50%, var(--line));
}

.press-plate__action-eyebrow-tag {
  flex: 0 0 auto;
  padding: 0 4px;
}

.press-plate__action-button {
  display: grid;
  grid-template-columns: clamp(28px, 2.6vw, 36px) minmax(0, 1fr) clamp(22px, 2vw, 28px);
  column-gap: clamp(10px, 1.1vw, 14px);
  align-items: center;
  width: 100%;
  padding: clamp(10px, 1.1vw, 14px) clamp(12px, 1.4vw, 18px);
  border: 1px solid var(--line);
  border-radius: 2px;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .5), rgba(14, 20, 32, .6));
  color: var(--paper);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    border-color .45s var(--ease),
    color .45s var(--ease),
    background .45s var(--ease),
    transform .5s var(--ease-spring),
    box-shadow .55s var(--ease);
}

.press-plate__action-button:hover,
.press-plate__action-button:focus-visible {
  border-color: rgba(255, 118, 95, .45);
  transform: translateY(-1px);
  box-shadow: 0 14px 24px -18px rgba(255, 118, 95, .55);
}

.press-plate__action-button.is-open {
  border-color: rgba(216, 240, 106, .45);
  background:
    linear-gradient(180deg, rgba(216, 240, 106, .08), rgba(216, 240, 106, .02)),
    rgba(20, 26, 38, .42);
}

.press-plate__action-corner {
  display: inline-grid;
  place-items: center;
  width: clamp(28px, 2.6vw, 36px);
  height: clamp(28px, 2.6vw, 36px);
  color: var(--coral);
  transition: color .45s var(--ease), transform .5s var(--ease-spring);
}

.press-plate__action-button.is-open .press-plate__action-corner {
  color: var(--acid);
  transform: rotate(180deg);
}

.press-plate__action-corner svg { width: 100%; height: 100%; }

.press-plate__action-corner-crease,
.press-plate__action-corner-fold,
.press-plate__action-corner-bead {
  transition: stroke .45s var(--ease), fill .45s var(--ease);
}

.press-plate__action-button.is-open .press-plate__action-corner-crease {
  stroke-dasharray: 2 2;
  opacity: .55;
}

.press-plate__action-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.press-plate__action-eyebrow-2 {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .6vw, 8px);
  letter-spacing: .24em;
  text-transform: uppercase;
  opacity: .85;
}

.press-plate__action-line {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.4vw, 19px);
  letter-spacing: -.012em;
  line-height: 1.15;
}

.press-plate__action-for {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 2px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9.5px);
  letter-spacing: .12em;
}

.press-plate__action-for em {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1vw, 13.5px);
  text-transform: none;
  letter-spacing: -.01em;
}

.press-plate__action-for-rule {
  display: inline-block;
  width: 24px;
  height: 1px;
  background: linear-gradient(to right, var(--line), transparent);
}

.press-plate__action-arrow {
  display: inline-grid;
  place-items: center;
  width: clamp(22px, 2vw, 28px);
  height: clamp(22px, 2vw, 28px);
  color: var(--muted);
  transition: color .45s var(--ease), transform .45s var(--ease-out);
}

.press-plate__action-arrow svg { width: 100%; height: 100%; }

.press-plate__action-button:hover .press-plate__action-arrow,
.press-plate__action-button:focus-visible .press-plate__action-arrow {
  color: var(--paper);
  transform: translateX(3px);
}

.press-plate__action-button.is-open .press-plate__action-arrow {
  color: var(--acid);
  transform: translateX(3px) scaleX(-1);
}

/* Plate footer */

.press-plate__foot {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  color: var(--muted);
}

.press-plate__foot-rule {
  display: block;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 30%, var(--line) 70%, transparent);
  max-width: 110px;
}

.press-plate__foot-rule--a { background: linear-gradient(to right, transparent, var(--line)); justify-self: end; }
.press-plate__foot-rule--b { background: linear-gradient(to left, transparent, var(--line)); justify-self: start; }

.press-plate__foot-row {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(10px, 1.4vw, 18px);
}

.press-plate__foot-cell {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
}

.press-plate__foot-cell-key {
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press-plate__foot-cell-value {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1vw, 14px);
  letter-spacing: -.012em;
}

.app--voice-quiet .press-plate__foot-cell-value { color: var(--blue); }
.app--voice-human .press-plate__foot-cell-value { color: var(--coral); }
.app--voice-bold .press-plate__foot-cell-value { color: var(--acid); }

.press-plate__foot-cell-kbd {
  color: var(--paper);
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(8px, .72vw, 9.5px);
  letter-spacing: .14em;
  text-transform: uppercase;
}

.press-plate__foot-cell-kbd kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  padding: 1px 5px 2px;
  margin: 0 2px;
  border: 1px solid var(--line);
  border-bottom-width: 2px;
  border-radius: 2px;
  color: var(--paper);
  font-family: var(--mono);
  font-style: normal;
  font-size: inherit;
  letter-spacing: .06em;
  text-transform: uppercase;
  background: rgba(20, 26, 38, .5);
}

@media (max-width: 720px) {
  .press-plate__foot-row {
    gap: 8px;
  }

  .press-plate__foot-cell {
    flex: 0 0 calc(50% - 6px);
  }

  .press-plate__foot-rule {
    max-width: 40px;
  }
}

@media (max-width: 540px) {
  .press-plate {
    padding: 12px;
  }

  .press-plate__foot-row {
    flex-direction: column;
    align-items: stretch;
    gap: 6px;
  }

  .press-plate__foot-cell {
    justify-content: center;
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-plate__action-button,
  .press-plate__action-corner,
  .press-plate__action-arrow,
  .press-plate__voice-button,
  .press-plate__voice-bullet-ring {
    transition: none !important;
  }
}


