  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.005em;
  color: var(--paper);
}

.folio-ledger__signature-text em {
  font-style: italic;
  color: var(--paper);
}

.folio-ledger__signature-divider {
  color: var(--muted);
  font-style: normal;
  font-family: var(--serif);
  font-size: 18px;
  line-height: 0;
  opacity: .55;
}

.folio-ledger__map {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: clamp(14px, 2vw, 22px);
  padding: clamp(14px, 1.6vw, 18px) clamp(16px, 2vw, 24px);
  border: 1px solid rgba(244, 237, 219, .13);
  border-radius: 1px;
  background:
    radial-gradient(circle at 100% 50%, rgba(216, 255, 98, .05), transparent 60%),
    linear-gradient(180deg, rgba(28, 32, 44, .5), rgba(14, 18, 28, .6));
}

.folio-ledger__map-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.folio-ledger__map-eyebrow::before {
  content: '';
  display: inline-block;
  width: 12px;
  height: 1px;
  background: var(--muted);
  opacity: .7;
}

.folio-ledger__map-list {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
  border-left: 1px solid var(--line);
}

.folio-ledger__map-cell {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 4px 12px;
  border-right: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 10.5px;
}

.folio-ledger__map-num {
  color: var(--coral);
  font-style: italic;
  font-family: var(--serif);
  font-size: 12.5px;
  letter-spacing: -.02em;
}

.folio-ledger__map-label {
  color: var(--paper);
  letter-spacing: .14em;
  text-transform: uppercase;
  opacity: .85;
}

.folio-ledger__map-tick {
  display: none;
}

@media (max-width: 720px) {
  .folio-ledger__map {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .folio-ledger__signature {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .folio-ledger__signature-rule {
    display: none;
  }
}

.folio-ledger__note-foot {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  margin: 0;
  max-width: 64ch;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-size: clamp(13px, 1.05vw, 14px);
  font-style: italic;
  line-height: 1.55;
  letter-spacing: -.005em;
}

.folio-ledger__note-foot span[aria-hidden] {
  color: var(--coral);
  font-style: normal;
  font-size: 18px;
  line-height: 0;
}

@media (prefers-reduced-motion: reduce) {
  .folio-ledger__link,
  .folio-ledger__num,
  .folio-ledger__arrow,
  .folio-ledger__arrow-rule {
    transition: none !important;
  }
}

/* ───────────────────────────────────────────────────────────
   FOLIO LEDGER · gentle reveal on entering the viewport
   ─────────────────────────────────────────────────────────── */

.folio-ledger__head-row,
.folio-ledger__rule,
.folio-ledger__list,
.folio-ledger__foot {
  animation: flReveal .9s var(--ease-out) .05s both;
}

.folio-ledger__rule {
  animation-delay: .15s;
}

.folio-ledger__list {
  animation-delay: .25s;
}

.folio-ledger__foot {
  animation-delay: .35s;
}

@keyframes flReveal {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .folio-ledger__head-row,
  .folio-ledger__rule,
  .folio-ledger__list,
  .folio-ledger__foot {
    animation: none;
    opacity: 1;
    transform: none;
  }
}

/* ───────────────────────────────────────────────────────────
   FOLIO LEDGER · reveal only when the section enters view
   ─────────────────────────────────────────────────────────── */

.folio-ledger__head-row,
.folio-ledger__rule,
.folio-ledger__list,
.folio-ledger__foot {
  opacity: 0;
  transform: translateY(8px);
}

.folio-ledger.is-revealed .folio-ledger__head-row,
.folio-ledger.is-revealed .folio-ledger__rule,
.folio-ledger.is-revealed .folio-ledger__list,
.folio-ledger.is-revealed .folio-ledger__foot {
  animation: flReveal .9s var(--ease-out) both;
}

.folio-ledger.is-revealed .folio-ledger__rule {
  animation-delay: .12s;
}

.folio-ledger.is-revealed .folio-ledger__list {
  animation-delay: .22s;
}

.folio-ledger.is-revealed .folio-ledger__foot {
  animation-delay: .32s;
}

@keyframes flReveal {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .folio-ledger__head-row,
  .folio-ledger__rule,
  .folio-ledger__list,
  .folio-ledger__foot {
    opacity: 1;
    transform: none;
    animation: none;
  }
}

/* ────────────────────────────────────────────────────────────
   CLOSING PLATE · replaces the loose row-based folio footer
   with one deliberate, paper-backed press plate. A single
   signature flourish draws across the top, then a composed
   inscription lists the active voice, marked word, reader,
   and date as a single line of type. Three voice specimens
   sit beneath — a tiny type-table that names what was used.
   ──────────────────────────────────────────────────────────── */

.closing-plate {
  --closing-tone: var(--coral);
  --closing-word-ink: var(--coral);
  position: relative;
  display: grid;
  justify-items: center;
  gap: clamp(14px, 1.6vw, 20px);
  width: min(100%, 1180px);
  margin: clamp(54px, 7vw, 96px) auto 0;
  padding: 0 var(--gutter) clamp(20px, 3vw, 36px);
  color: var(--closing-tone);
}

.closing-plate__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.4vw, 16px);
  padding: 6px clamp(14px, 1.8vw, 22px) 7px;
  background: linear-gradient(180deg, rgba(20, 26, 38, .55), rgba(14, 18, 28, .7));
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--closing-tone);
  font-family: var(--mono);
  font-size: clamp(9px, .82vw, 10.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: 0;
  transform: translateY(6px);
  animation: closingPlateIn .8s var(--ease-out) .05s forwards;
}

.closing-plate__eyebrow-mark {
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.15em;
  letter-spacing: 0;
  text-transform: none;
  color: currentColor;
  opacity: .9;
}

.closing-plate__eyebrow-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding-left: clamp(8px, 1.2vw, 14px);
  margin-left: clamp(2px, .4vw, 6px);
  border-left: 1px solid var(--line);
  color: var(--mist);
  letter-spacing: .22em;
}

.closing-plate__eyebrow-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .6;
}

@keyframes closingPlateIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.closing-plate__frame {
  position: relative;
  display: grid;
  justify-items: center;
  gap: clamp(20px, 2.6vw, 32px);
  width: 100%;
  padding: clamp(34px, 5vw, 64px) clamp(22px, 4vw, 56px) clamp(34px, 5vw, 60px);
  border: 1px solid rgba(243, 236, 214, .12);
  border-radius: 2px;
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .045), rgba(243, 236, 214, .018) 50%, rgba(243, 236, 214, .025)),
    linear-gradient(135deg, rgba(146, 186, 255, .06), transparent 60%),
    linear-gradient(180deg, rgba(14, 18, 28, .58), rgba(14, 18, 28, .82));
  box-shadow:
    inset 0 0 0 1px rgba(14, 18, 28, .5),
    0 26px 60px -32px rgba(0, 0, 0, .55),
    0 4px 14px -6px rgba(0, 0, 0, .4);
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-out);
}

.closing-plate.is-revealed .closing-plate__frame {
  opacity: 1;
  transform: translateY(0);
}

.closing-plate__paper {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: .22;
  mix-blend-mode: soft-light;
  pointer-events: none;
}

.closing-plate__crop {
  position: absolute;
  width: 18px;
  height: 18px;
  color: var(--paper);
  opacity: .42;
  pointer-events: none;
}

.closing-plate__crop::before,
.closing-plate__crop::after {
  content: '';
  position: absolute;
  background: currentColor;
  opacity: .85;
}

.closing-plate__crop::before {
  top: 50%;
  left: 0;
  right: 0;
  height: 1px;
  transform: translateY(-50%);
}

.closing-plate__crop::after {
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  transform: translateX(-50%);
}

.closing-plate__crop--tl { top: 10px; left: 10px; }
.closing-plate__crop--tr { top: 10px; right: 10px; }
.closing-plate__crop--bl { bottom: 10px; left: 10px; }
.closing-plate__crop--br { bottom: 10px; right: 10px; }

.closing-plate__tipped {
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  background: var(--night);
  border: 1px solid var(--line);
  border-radius: 1px;
  color: var(--closing-tone);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
  white-space: nowrap;
  box-shadow: 0 4px 14px -6px rgba(0, 0, 0, .5);
}

.closing-plate__tipped-mark {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  opacity: .7;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, .04);
}

.closing-plate__bleed {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 28px;
  height: 28px;
  border-top: 1px solid rgba(243, 236, 214, .14);
  border-left: 1px solid rgba(243, 236, 214, .14);
  border-top-left-radius: 1px;
  pointer-events: none;
  opacity: .55;
}

.closing-plate__glue {
  position: absolute;
  left: 22%;
  right: 22%;
  height: 6px;
  background:
    radial-gradient(ellipse at center, rgba(243, 236, 214, .14) 0%, transparent 70%);
  pointer-events: none;
}

.closing-plate__glue--top { top: 6px; }
.closing-plate__glue--bottom { bottom: 6px; transform: scaleY(-1); }

.closing-plate__rule {
  display: block;
  width: min(100%, 720px);
  height: 8px;
  color: var(--closing-tone);
  opacity: .8;
}

.closing-plate__rule-stroke {
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.4s var(--ease-out) .25s;
}

.closing-plate.is-revealed .closing-plate__rule-stroke {
  stroke-dashoffset: 0;
}

.closing-plate__rule-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .35s var(--ease) 1.6s, transform .55s var(--ease-spring) 1.6s;
}

.closing-plate.is-revealed .closing-plate__rule-bead {
  opacity: 1;
  transform: scale(1);
}

.closing-plate__signature-wrap {
  display: grid;
  justify-items: center;
  width: min(100%, 720px);
  margin-top: clamp(-6px, -.6vw, -2px);
  color: var(--closing-tone);
  opacity: .88;
  transition: opacity .85s var(--ease-out) .45s;
}

.closing-plate.is-revealed .closing-plate__signature-wrap {
  opacity: 1;
}

.closing-plate__signature {
  display: block;
  width: 100%;
  height: clamp(38px, 5vw, 56px);
}

.closing-plate__signature-stroke {
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.7s var(--ease-out) .55s;
}

.closing-plate.is-revealed .closing-plate__signature-stroke {
  stroke-dashoffset: 0;
}

.closing-plate__signature-bead,
.closing-plate__signature-halo {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .4s var(--ease) 2.1s, transform .55s var(--ease-spring) 2.1s;
}

.closing-plate.is-revealed .closing-plate__signature-bead {
  opacity: 1;
  transform: scale(1);
}

.closing-plate.is-revealed .closing-plate__signature-halo {
  opacity: .6;
  transform: scale(1);
}

.closing-plate__inscription {
  display: grid;
  justify-items: center;
  gap: clamp(8px, 1vw, 12px);
  width: 100%;
  text-align: center;
}

.closing-plate__inscription-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 4px 0;
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .26em;
  text-transform: uppercase;
}

.closing-plate__inscription-eyebrow-mark {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--closing-tone);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, .05);
  opacity: .8;
}

.closing-plate__inscription-line {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: center;
  gap: clamp(8px, 1vw, 14px);
  margin: 0;
  padding: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(20px, 2.4vw, 32px);
  line-height: 1.2;
  letter-spacing: -.012em;
  text-wrap: balance;
}

.closing-plate__inscription-prelude {
  margin: 0 0 clamp(4px, .5vw, 8px);
  color: var(--closing-tone);
  font-family: var(--serif);
  font-size: clamp(13.5px, 1.2vw, 16px);
  font-style: italic;
  letter-spacing: -.005em;
  line-height: 1.5;
  text-align: center;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .8s var(--ease-out) .2s, transform .9s var(--ease-spring) .2s;
}

.closing-plate.is-revealed .closing-plate__inscription-prelude {
  opacity: 1;
  transform: translateY(0);
}

.closing-plate__inscription-prelude em {
  color: var(--paper);
  font-style: italic;
  font-weight: inherit;
}

.closing-plate__inscription-line--alt {
  font-size: clamp(17px, 1.9vw, 24px);
  color: var(--lead-1);
  font-style: italic;
  letter-spacing: -.006em;
}

.closing-plate__inscription-piece {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
}

.closing-plate__inscription-key {
  font-family: var(--mono);
  font-size: clamp(9px, .82vw, 11px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
  font-style: normal;
}

.closing-plate__inscription-line--alt .closing-plate__inscription-key {
  color: var(--mist);
}

.closing-plate__inscription-voice {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  color: var(--closing-tone);
  font-style: italic;
  font-weight: 500;
}

.closing-plate__inscription-voice-letter {
  display: inline-grid;
  place-items: center;
  width: 1.05em;
  height: 1.05em;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: .68em;
  font-weight: 400;
  letter-spacing: -.01em;
  color: currentColor;
  background: rgba(14, 18, 28, .55);
  transform: translateY(-.04em);
}

.closing-plate__inscription-voice--quiet { color: var(--blue); }
.closing-plate__inscription-voice--human { color: var(--coral); }
.closing-plate__inscription-voice--bold {
  color: var(--acid);
  font-style: normal;
  font-weight: 700;
  letter-spacing: -.02em;
}

.closing-plate__inscription-word {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  color: var(--closing-word-ink);
  font-style: italic;
  font-weight: 500;
}

.closing-plate__inscription-word--m3 { color: var(--acid); }
.closing-plate__inscription-word--good { color: var(--coral); }
.closing-plate__inscription-word--yet { color: var(--blue); }

.closing-plate__inscription-word-mark {
  display: inline-grid;
  place-items: center;
  padding: 1px 6px 2px;
  border: 1px solid currentColor;
  border-radius: 1px;
  font-family: var(--mono);
  font-size: .42em;
  letter-spacing: .22em;
  text-transform: uppercase;
  font-style: normal;
  font-weight: 600;
  transform: translateY(-.16em);
  opacity: .9;
}

.closing-plate__inscription-reader {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  color: var(--paper);
  font-style: italic;
}

.closing-plate__inscription-reader.is-set {
  color: var(--paper);
}

.closing-plate__inscription-reader-to {
  font-family: var(--mono);
  font-size: .55em;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--mist);
  font-style: normal;
  transform: translateY(-.16em);
}

.closing-plate__inscription-reader-name {
  font-weight: 500;
  font-style: italic;
  text-shadow: 0 0 .4em rgba(243, 236, 214, .12);
}

.closing-plate__inscription-reader-name--unset {
  color: var(--mist);
  opacity: .8;
  font-weight: 400;
}

.closing-plate__inscription-date {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
}

.closing-plate__inscription-sep {
  color: var(--muted);
  font-family: var(--serif);
  font-style: normal;
  font-size: .85em;
  opacity: .55;
  transform: translateY(-.16em);
}

.closing-plate__presslog {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  width: 100%;
  padding: 0 clamp(8px, 1.4vw, 18px);
  color: var(--paper);
}

.closing-plate__presslog-rule {
  flex: 1;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor, transparent);
  opacity: .4;
}

.closing-plate__presslog-mark {
  font-family: var(--serif);
  font-style: italic;
  font-size: 1em;
  color: var(--closing-tone);
  opacity: .85;
  flex: 0 0 auto;
}

.closing-plate__presslog-mark--alt {
  transform: scaleX(-1);
}

.closing-plate__presslog-body {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  flex: 0 1 auto;
  text-align: center;
}

.closing-plate__presslog-tag {
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--closing-tone);
  opacity: .75;
}

.closing-plate__presslog-row {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: center;
  gap: 6px;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.005em;
}

.closing-plate__presslog-key {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 1.05em;
  color: var(--closing-tone);
  font-variant-numeric: tabular-nums;
}

.closing-plate__presslog-suffix {
  color: var(--lead-2);
  font-style: normal;
  letter-spacing: 0;
  font-size: .92em;
}

.closing-plate__presslog-dot {
  color: var(--muted);
  font-style: normal;
  font-size: .8em;
  opacity: .55;
}

.closing-plate__presslog-now {
  color: var(--mist);
  font-style: italic;
  font-size: .94em;
}

.closing-plate__presslog-now em {
  color: var(--closing-tone);
  font-style: italic;
  font-weight: 500;
}

.closing-plate__voices {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(10px, 1.4vw, 18px);
  width: 100%;
  max-width: 880px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.closing-plate__voices-cell {
  position: relative;
  display: grid;
  grid-template-rows: auto auto auto;
  gap: 8px;
  padding: clamp(12px, 1.6vw, 18px) clamp(12px, 1.6vw, 18px) clamp(14px, 1.8vw, 20px);
  border: 1px solid var(--line);
  border-radius: 1px;
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .03), rgba(243, 236, 214, .01)),
    rgba(20, 26, 38, .4);
  color: var(--paper);
  transition: border-color .5s var(--ease), background .5s var(--ease), transform .55s var(--ease);
}

.closing-plate__voices-cell::before {
  content: '';
  position: absolute;
  top: 50%;
  bottom: 14%;
  right: calc(clamp(10px, 1.4vw, 18px) * -1 - 1px);
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--line) 14%, var(--line) 86%, transparent);
  pointer-events: none;
  opacity: .6;
}

.closing-plate__voices-cell:last-child::before {
  display: none;
}

.closing-plate__voices-cell--quiet { color: var(--blue); }
.closing-plate__voices-cell--human { color: var(--coral); }
.closing-plate__voices-cell--bold { color: var(--acid); }

.closing-plate__voices-cell.is-active {
  border-color: currentColor;
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .06), rgba(243, 236, 214, .015)),
    rgba(20, 26, 38, .55);
  box-shadow:
    inset 0 0 0 1px rgba(14, 18, 28, .4),
    0 8px 22px -12px currentColor;
  transform: translateY(-2px);
}

.closing-plate__voices-tag {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  color: currentColor;
}

.closing-plate__voices-letter {
  display: inline-grid;
  place-items: center;
  width: 1.4em;
  height: 1.4em;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: currentColor;
  font-family: var(--serif);
  font-style: italic;
  font-size: .78em;
  font-weight: 400;
  line-height: 1;
  background: rgba(14, 18, 28, .55);
}

.closing-plate__voices-name {
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .75;
}

.closing-plate__voices-sample {
  display: block;
  color: currentColor;
  font-size: clamp(22px, 2.4vw, 30px);
  line-height: 1.05;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: clip;
}

.closing-plate__voices-cell--quiet .closing-plate__voices-sample {
  font-style: italic;
}

.closing-plate__voices-cell--human .closing-plate__voices-sample {
  font-style: italic;
}

.closing-plate__voices-cell--bold .closing-plate__voices-sample {
  font-style: normal;
}

.closing-plate__voices-face {
  display: block;
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9.5px);
  letter-spacing: .18em;
  text-transform: uppercase;
  opacity: .7;
}

.closing-plate__voices-now {
  position: absolute;
  top: 8px;
  right: 10px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 7px;
  border: 1px solid currentColor;
  border-radius: 999px;
  color: currentColor;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  background: rgba(14, 18, 28, .6);
}

.closing-plate__voices-now::before {
  content: '';
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 2px currentColor;
  opacity: .9;
}

.closing-plate__stamp {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 6px;
  margin-top: clamp(-4px, -.4vw, -2px);
  color: var(--closing-tone);
  transition: transform .55s var(--ease-spring);
}

.closing-plate.is-revealed .closing-plate__stamp {
  animation: closingStampIn .8s cubic-bezier(.34, 1.32, .52, 1) 1.95s backwards;
}

@keyframes closingStampIn {
  0% { opacity: 0; transform: rotate(-9deg) scale(.7); }
  100% { opacity: 1; transform: rotate(-6deg) scale(1); }
}

.closing-plate__stamp-wax {
  position: absolute;
  top: 60%;
  left: 0;
  width: 14px;
  height: 14px;
  pointer-events: none;
}

.closing-plate__stamp-wax-bead {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, var(--wax), #6f261d 80%);
  box-shadow: 0 1px 0 rgba(0, 0, 0, .4), 0 4px 10px -3px rgba(179, 74, 58, .5);
}

.closing-plate__stamp-wax-wisp {
  position: absolute;
  top: 70%;
  left: 100%;
  width: 18px;
  height: 4px;
  background: radial-gradient(ellipse at center, var(--wax), transparent 70%);
  transform: rotate(8deg);
  opacity: .75;
}

.closing-plate__stamp-tag {
  color: var(--closing-tone);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: .7;
}

.closing-plate__foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.4vw, 18px);
  width: 100%;
  padding-top: clamp(14px, 1.8vw, 22px);
  border-top: 1px dashed var(--line);
  color: var(--mist);
  font-family: var(--serif);
  font-size: clamp(13px, 1.2vw, 15px);
}

.closing-plate__foot-rule {
  display: none;
}

.closing-plate__foot-line {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: center;
  gap: 8px;
  margin: 0;
  color: var(--mist);
  font-style: italic;
  letter-spacing: -.005em;
}

.closing-plate__foot-em {
  color: var(--lead-2);
  font-style: italic;
}

.closing-plate__foot-em--quiet {
  color: var(--muted);
  font-family: var(--mono);
  font-style: normal;
  font-size: .78em;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.closing-plate__foot-back {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px 7px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(9px, .82vw, 10.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  transition: color .35s var(--ease), border-color .35s var(--ease), background .35s var(--ease), gap .3s var(--ease-out);
}

.closing-plate__foot-farewell {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
  margin: 4px 0 0;
  color: var(--closing-tone);
  font-family: var(--serif);
  font-size: clamp(13.5px, 1.18vw, 15.5px);
  font-style: italic;
  letter-spacing: -.005em;
  line-height: 1.5;
  text-wrap: balance;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .85s var(--ease-out) .35s, transform .95s var(--ease-spring) .35s;
}

.closing-plate.is-revealed .closing-plate__foot-farewell {
  opacity: 1;
  transform: translateY(0);
}

.closing-plate__foot-farewell-mark {
  color: var(--closing-tone);
  font-family: 'Iowan Old Style', Georgia, serif;
  font-size: 1.1em;
  opacity: .75;
}

.closing-plate__foot-farewell em {
  color: var(--paper);
  font-style: italic;
  font-weight: inherit;
}

.closing-plate__foot-back svg {
  width: 14px;
  height: 14px;
  display: block;
}

.closing-plate__foot-back:hover,
.closing-plate__foot-back:focus-visible {
  color: var(--closing-tone);
  border-color: var(--closing-tone);
  gap: 12px;
  background: rgba(243, 236, 214, .03);
}

@media (max-width: 880px) {
  .closing-plate__inscription-line {
    font-size: clamp(20px, 4.6vw, 28px);
  }

  .closing-plate__inscription-line--alt {
    font-size: clamp(16px, 4vw, 22px);
  }

  .closing-plate__voices {
    grid-template-columns: 1fr;
    max-width: 460px;
  }

  .closing-plate__voices-cell::before {
    top: auto;
    right: 14%;
    bottom: calc(clamp(10px, 1.4vw, 18px) * -1 - 1px);
    left: 14%;
    width: auto;
    height: 1px;
    background: linear-gradient(to right, transparent, var(--line) 14%, var(--line) 86%, transparent);
  }

  .closing-plate__presslog {
    flex-wrap: wrap;
  }

  .closing-plate__presslog-body {
    flex: 1 1 100%;
  }

  .closing-plate__foot {
    justify-content: center;
  }
}

@media (max-width: 540px) {
  .closing-plate {
    padding: 0 16px 20px;
  }

  .closing-plate__frame {
    padding: 28px 18px 22px;
    gap: 18px;
  }

  .closing-plate__eyebrow {
    flex-wrap: wrap;
    justify-content: center;
    text-align: center;
  }

  .closing-plate__eyebrow-tag {
    flex: 1 1 100%;
    padding-left: 0;
    margin-left: 0;
    border-left: 0;
    padding-top: 6px;
    border-top: 1px solid var(--line);
    justify-content: center;
  }

  .closing-plate__inscription-line,
  .closing-plate__inscription-line--alt {
    flex-direction: column;
    align-items: center;
    gap: 6px;
  }

  .closing-plate__inscription-sep {
    display: none;
  }

  .closing-plate__foot {
    flex-direction: column;
    gap: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .closing-plate__eyebrow {
    animation: none !important;
    opacity: 1;
    transform: none;
  }

  .closing-plate__frame {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .closing-plate__rule-stroke,
  .closing-plate__signature-stroke {
    stroke-dashoffset: 0 !important;
    transition: none !important;
  }

  .closing-plate__rule-bead,
  .closing-plate__signature-bead,
  .closing-plate__signature-halo {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }

  .closing-plate__signature-wrap {
    opacity: 1 !important;
    transition: none !important;
  }

  .closing-plate__stamp {
    animation: none !important;
    transform: rotate(-6deg) !important;
    opacity: 1 !important;
  }
}

/* ────────────────────────────────────────────────────────────
   READING FLOOR · a deliberate centerpiece that sits between
   the second reading and the answer reveal. The question is
   set one last time in the active voice, framed by a thin
   plate, with three voice sigils below and a fold-here mark
   pointing down to the answer. Honours reduced-motion.
   ──────────────────────────────────────────────────────────── */

.reading-floor {
  --reading-floor-tone: var(--coral);
  --reading-floor-paper: rgba(243, 236, 214, .045);
  --reading-font: var(--serif);
  --reading-weight: 500;
  --reading-style: italic;
  --reading-track: -.018em;
  --reading-size: clamp(38px, 5.4vw, 74px);
  --reading-size-mobile: clamp(28px, 8vw, 40px);
  position: relative;
  display: grid;
  gap: clamp(18px, 2.2vw, 28px);
  max-width: 1180px;
  margin: clamp(48px, 6vw, 96px) auto clamp(48px, 6vw, 88px);
  padding: clamp(28px, 3.8vw, 56px) clamp(22px, 4vw, 64px) clamp(28px, 3.6vw, 50px);
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--paper);
  background:
    radial-gradient(ellipse at 50% 0%, var(--reading-floor-paper), transparent 65%),
    radial-gradient(ellipse at 50% 100%, rgba(17, 21, 33, .35), transparent 70%),
    linear-gradient(180deg, rgba(28, 36, 52, .18), rgba(14, 20, 32, .42));
  isolation: isolate;
  overflow: hidden;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-out);
}

.reading-floor::before {
  content: '';
  position: absolute;
  inset: 6px;
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  pointer-events: none;
}

.reading-floor.is-revealed {
  opacity: 1;
  transform: none;
}

.reading-floor--quiet { --reading-floor-tone: var(--blue); }
.reading-floor--human { --reading-floor-tone: var(--coral); }
.reading-floor--bold { --reading-floor-tone: var(--acid); }

.reading-floor__plate-tag {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  padding: 4px 14px;
  border: 1px solid var(--line);
  border-radius: 1px;
  background: rgba(14, 15, 21, .72);
  color: var(--reading-floor-tone);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
  white-space: nowrap;
}

.reading-floor__grain {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: .5;
  pointer-events: none;
  mix-blend-mode: overlay;
  z-index: 0;
}

.reading-floor__crop {
  position: absolute;
  width: 16px;
  height: 16px;
  border-color: var(--reading-floor-tone);
  opacity: .85;
  pointer-events: none;
}

.reading-floor__crop--tl { top: -1px; left: -1px; border-top: 1px solid; border-left: 1px solid; }
.reading-floor__crop--tr { top: -1px; right: -1px; border-top: 1px solid; border-right: 1px solid; }
.reading-floor__crop--bl { bottom: -1px; left: -1px; border-bottom: 1px solid; border-left: 1px solid; }
.reading-floor__crop--br { bottom: -1px; right: -1px; border-bottom: 1px solid; border-right: 1px solid; }

.reading-floor__dogeare {
  position: absolute;
  top: 0;
  right: 0;
  width: 36px;
  height: 36px;
  pointer-events: none;
  z-index: 1;
}

.reading-floor__dogeare svg { width: 100%; height: 100%; }

.reading-floor__head {
  position: relative;
  display: grid;
  gap: clamp(8px, 1vw, 14px);
  padding-top: clamp(8px, 1.2vw, 18px);
  z-index: 2;
}

.reading-floor__head-eyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  color: var(--reading-floor-tone);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.reading-floor__head-eyebrow em {
  color: var(--muted);
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
}

.reading-floor__head-eyebrow-line {
  display: block;
  width: 32px;
  height: 1px;
  background: currentColor;
  opacity: .65;
}

.reading-floor__head-eyebrow-line--alt {
  opacity: .35;
}

.reading-floor__head-eyebrow-sep {
  color: var(--muted);
  opacity: .6;
}

.reading-floor__head-lede {
  margin: 0 auto;
  max-width: 56ch;
  text-align: center;
  color: var(--paper-2);
  font-family: var(--serif);
  font-size: clamp(15px, 1.4vw, 18px);
  font-style: italic;
  line-height: 1.5;
  letter-spacing: -.005em;
}

.reading-floor__head-lede em {
  color: var(--reading-floor-tone);
  font-style: italic;
  font-weight: 500;
}

/* ── stage ── */

.reading-floor__stage {
  position: relative;
  display: grid;
  align-items: center;
  justify-items: center;
  gap: clamp(6px, .8vw, 12px);
  padding: clamp(20px, 3vw, 36px) clamp(16px, 2.6vw, 32px);
  isolation: isolate;
  z-index: 2;
}

.reading-floor__stage-frame {
  position: absolute;
  width: 12px;
  height: 12px;
  border-color: var(--reading-floor-tone);
  opacity: .7;
}

.reading-floor__stage-frame--tl { top: 0; left: 0; border-top: 1px solid; border-left: 1px solid; }
.reading-floor__stage-frame--tr { top: 0; right: 0; border-top: 1px solid; border-right: 1px solid; }
.reading-floor__stage-frame--bl { bottom: 0; left: 0; border-bottom: 1px solid; border-left: 1px solid; }
.reading-floor__stage-frame--br { bottom: 0; right: 0; border-bottom: 1px solid; border-right: 1px solid; }

.reading-floor__stage-mark {
  position: absolute;
  top: -10px;
  width: 18px;
  height: 18px;
  color: var(--reading-floor-tone);
  display: grid;
  place-items: center;
  z-index: 3;
}

.reading-floor__stage-mark--lead { left: 50%; transform: translateX(-50%); }
.reading-floor__stage-mark--trail {
  top: auto;
  bottom: -10px;
  left: 50%;
  transform: translateX(-50%);
}

.reading-floor__stage-mark svg {
  width: 100%;
  height: 100%;
  display: block;
  background: rgba(14, 15, 21, .85);
  border-radius: 50%;
  padding: 1px;
}

.reading-floor__stage-tag {
  position: absolute;
  top: -7px;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: var(--reading-floor-tone);
  opacity: .85;
  background: rgba(14, 15, 21, .85);
  padding: 2px 7px;
  border: 1px solid currentColor;
  border-radius: 1px;
}

.reading-floor__stage-tag--lead { left: clamp(18px, 4vw, 60px); }
.reading-floor__stage-tag--trail {
  top: auto;
  bottom: -7px;
  right: clamp(18px, 4vw, 60px);
}

.reading-floor__stage-tag em {
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
}

.reading-floor__specimen {
  position: relative;
  display: grid;
  gap: clamp(2px, .4vw, 6px);
  text-align: center;
  font-family: var(--reading-font);
  font-weight: var(--reading-weight);
  font-style: var(--reading-style);
  letter-spacing: var(--reading-track);
  font-size: var(--reading-size);
  line-height: 1.06;
  color: var(--paper);
  z-index: 1;
  padding: clamp(6px, 1vw, 14px) clamp(8px, 1.6vw, 24px);
}

.reading-floor__specimen-line {
  display: block;
  opacity: 0;
  transform: translateY(6px);
  animation: readingFloorLineIn .8s var(--ease-out) forwards;
}

.reading-floor__specimen-line:nth-child(1) { animation-delay: .08s; }
.reading-floor__specimen-line:nth-child(2) { animation-delay: .18s; }
.reading-floor__specimen-line:nth-child(3) { animation-delay: .28s; }

.reading-floor__specimen--quiet,
.reading-floor__specimen--human {
  font-family: var(--serif);
  font-style: italic;
}

.reading-floor__specimen--bold {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 800;
  text-transform: uppercase;
}

.reading-floor__stage-glyph {
  position: absolute;
  bottom: clamp(4px, 1vw, 14px);
  right: clamp(18px, 4vw, 60px);
  color: var(--reading-floor-tone);
  font-family: Georgia, serif;
  font-size: clamp(16px, 1.8vw, 22px);
  opacity: .8;
  z-index: 3;
}

.reading-floor__stage-rule {
  display: block;
  width: 100%;
  height: 8px;
  color: var(--reading-floor-tone);
  opacity: .65;
  position: relative;
}

.reading-floor__stage-rule svg { width: 100%; height: 100%; display: block; }

.reading-floor__stage-rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: readingFloorRuleIn 1.2s var(--ease-out) forwards;
}

.reading-floor__stage-rule-stroke--alt {
  animation-delay: .35s;
}

@keyframes readingFloorRuleIn {
  to { stroke-dashoffset: 0; }
}

@keyframes readingFloorLineIn {
  to { opacity: 1; transform: none; }
}

/* ── voices ── */

.reading-floor__voices {
  position: relative;
  display: grid;
  gap: clamp(10px, 1vw, 14px);
  z-index: 2;
}

.reading-floor__voices-eyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.reading-floor__voices-eyebrow-rule {
  display: block;
  width: 36px;
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.reading-floor__voice-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(10px, 1.4vw, 18px);
}

.reading-floor__voice {
  position: relative;
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  padding: clamp(10px, 1.2vw, 16px) clamp(12px, 1.4vw, 18px);
  border: 1px solid var(--line);
  border-radius: 1px;
  background: rgba(17, 21, 33, .35);
  transition: background .5s var(--ease), border-color .5s var(--ease);
}

.reading-floor__voice--quiet { --voice-color: var(--blue); }
.reading-floor__voice--human { --voice-color: var(--coral); }
.reading-floor__voice--bold { --voice-color: var(--acid); }

.reading-floor__voice.is-active {
  border-color: var(--voice-color);
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .04), rgba(243, 236, 214, .01)),
    rgba(17, 21, 33, .55);
}

.reading-floor__voice-mark {
  display: inline-grid;
  place-items: center;
  width: 16px;
  height: 16px;
  color: var(--voice-color);
  transition: transform .4s var(--ease-spring);
}

.reading-floor__voice.is-active .reading-floor__voice-mark {
  transform: scale(1.12);
}

.reading-floor__voice-mark svg { width: 100%; height: 100%; display: block; }

.reading-floor__voice-letter {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(20px, 2vw, 26px);
  color: var(--voice-color);
  line-height: 1;
}

.reading-floor__voice-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.reading-floor__voice-name {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.2vw, 15px);
  color: var(--paper);
  line-height: 1.1;
  letter-spacing: -.005em;
}

.reading-floor__voice-face {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--muted);
  line-height: 1.1;
}

.reading-floor__voice.is-active .reading-floor__voice-name {
  color: var(--voice-color);
}

.reading-floor__voice-now {
  position: absolute;
  top: -7px;
  right: clamp(10px, 1.2vw, 14px);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border: 1px solid var(--voice-color);
  border-radius: 1px;
  background: rgba(14, 15, 21, .85);
  color: var(--voice-color);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.reading-floor__voice-now::before {
  content: '';
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  animation: readingFloorNowPulse 1.6s ease-in-out infinite;
}

@keyframes readingFloorNowPulse {
  0%, 100% { opacity: .35; }
  50% { opacity: 1; }
}

/* ── foot ── */

.reading-floor__foot {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(12px, 1.4vw, 18px);
  z-index: 2;
}

.reading-floor__fold {
  position: relative;
  display: grid;
  place-items: center;
  height: 28px;
  color: var(--reading-floor-tone);
  opacity: .9;
}

.reading-floor__fold-svg {
  display: block;
  width: min(220px, 70%);
  height: 14px;
}

.reading-floor__fold-tag {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 10px;
  border-radius: 1px;
  background: rgba(14, 15, 21, .92);
  border: 1px solid var(--reading-floor-tone);
  color: var(--reading-floor-tone);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.reading-floor__fold-tag-mark {
  display: inline-grid;
  place-items: center;
  width: 12px;
  height: 12px;
  font-family: var(--mono);
  font-size: 12px;
  line-height: 1;
}

.reading-floor__meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(10px, 1.4vw, 20px);
  padding-top: clamp(8px, 1vw, 14px);
  border-top: 1px dashed var(--line-soft);
}

.reading-floor__meta-cell {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.reading-floor__meta-key {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.reading-floor__meta-value {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.2vw, 14px);
  color: var(--paper);
  letter-spacing: -.005em;
}

.reading-floor__meta-cell:last-child .reading-floor__meta-value {
  color: var(--reading-floor-tone);
}

/* ── responsive ── */

@media (max-width: 880px) {
  .reading-floor {
    margin: clamp(36px, 5vw, 64px) auto;
    padding: clamp(22px, 5vw, 32px) clamp(18px, 4vw, 24px);
  }

  .reading-floor__stage {
    padding: clamp(18px, 4vw, 26px) clamp(12px, 3vw, 18px);
  }

  .reading-floor__specimen {
    font-size: var(--reading-size-mobile);
  }

  .reading-floor__voice-list {
    grid-template-columns: 1fr;
  }

  .reading-floor__voice {
    grid-template-columns: auto auto minmax(0, 1fr);
  }

  .reading-floor__meta {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .reading-floor__meta-cell { justify-items: center; }

  .reading-floor__stage-tag--lead { left: 12px; }
  .reading-floor__stage-tag--trail { right: 12px; }
}

@media (max-width: 520px) {
  .reading-floor__head-eyebrow-line { width: 18px; }
  .reading-floor__stage-tag {
    font-size: 7.5px;
    letter-spacing: .2em;
    padding: 1px 6px;
  }
  .reading-floor__stage-tag em {
    font-size: 10px;
  }
  .reading-floor__voice {
    padding: 10px 12px;
  }
}

/* ── reduced motion ── */

@media (prefers-reduced-motion: reduce) {
  .reading-floor {
    transition: none !important;
    opacity: 1 !important;
    transform: none !important;
  }

  .reading-floor__stage-rule-stroke {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }

  .reading-floor__specimen-line {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }

  .reading-floor__voice-now::before {
    animation: none !important;
    opacity: 1;
  }
}

/* ────────────────────────────────────────────────────────────
   PRESS CABINET · the title page's type case, set just below
   the hero plate. three metal sorts sit shoulder to shoulder
   inside a wooden drawer; pick one and the title above answers
   with it. a smaller shelf beneath carries the marked words,
   so the reader can revise which word carries the marginalia.
   ──────────────────────────────────────────────────────────── */

.press-cabinet {
  --cabinet-tone: var(--blue);
  --cabinet-tone-soft: var(--blue);
  --cabinet-word-tone: var(--acid);
  position: relative;
  display: block;
  width: min(100%, 920px);
  margin: clamp(28px, 4vw, 64px) auto clamp(20px, 3vw, 36px);
  padding: clamp(16px, 2vw, 22px) clamp(18px, 2.4vw, 28px) clamp(18px, 2.2vw, 26px);
  color: var(--paper);
  font-family: var(--serif);
  isolation: isolate;
  transition: color .65s var(--ease);
  z-index: 1;
}

.press-cabinet::before {
  position: absolute;
  inset: clamp(8px, 1vw, 14px);
  border: 1px solid color-mix(in srgb, var(--cabinet-tone) 32%, var(--line));
  border-radius: 4px;
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .04) 0%, rgba(243, 236, 214, .015) 60%, transparent 100%),
    radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--cabinet-tone) 12%, transparent) 0%, transparent 60%);
  pointer-events: none;
  z-index: -1;
  opacity: .85;
  transition: border-color .55s var(--ease), background-color .55s var(--ease);
}

.press-cabinet::after {
  position: absolute;
  left: clamp(28px, 4vw, 56px);
  right: clamp(28px, 4vw, 56px);
  bottom: -1px;
  height: 8px;
  border-bottom: 1px solid color-mix(in srgb, var(--cabinet-tone) 38%, transparent);
  background:
    radial-gradient(ellipse at 50% 100%, color-mix(in srgb, var(--cabinet-tone) 22%, transparent) 0%, transparent 60%);
  content: '';
  pointer-events: none;
  z-index: -1;
  transition: border-color .55s var(--ease);
}

.press-cabinet__pulp {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: -1;
  opacity: .16;
  mix-blend-mode: soft-light;
}

.press-cabinet__crop {
  position: absolute;
  width: 18px;
  height: 18px;
  border: 1px solid color-mix(in srgb, var(--cabinet-tone) 60%, transparent);
  pointer-events: none;
  z-index: 2;
  opacity: .85;
}

.press-cabinet__crop--tl {
  top: -2px;
  left: -2px;
  border-right: 0;
  border-bottom: 0;
}

.press-cabinet__crop--tr {
  top: -2px;
  right: -2px;
  border-left: 0;
  border-bottom: 0;
}

.press-cabinet__crop--bl {
  bottom: -2px;
  left: -2px;
  border-right: 0;
  border-top: 0;
}

.press-cabinet__crop--br {
  bottom: -2px;
  right: -2px;
  border-left: 0;
  border-top: 0;
}

.press-cabinet__head {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.4vw, 18px);
  margin-bottom: clamp(14px, 1.6vw, 20px);
  font-family: var(--mono);
  font-size: clamp(9px, .82vw, 11px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--cabinet-tone);
  transition: color .55s var(--ease);
}

.press-cabinet__head-rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--cabinet-tone) 60%, transparent));
  max-width: 220px;
}

.press-cabinet__head-tag {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  white-space: nowrap;
  color: color-mix(in srgb, var(--cabinet-tone) 80%, var(--paper));
}

.press-cabinet__head-tag em {
  font-style: normal;
  color: var(--mist);
  opacity: .55;
}

.press-cabinet__head-tick {
  width: 6px;
  height: 6px;
  background: currentColor;
  border-radius: 50%;
  display: inline-block;
  box-shadow: 0 0 0 3px rgba(14, 15, 21, .55);
}

.press-cabinet__head-tick--alt {
  margin-left: clamp(6px, .8vw, 10px);
}

.press-cabinet__plate {
  position: absolute;
  top: clamp(6px, .8vw, 10px);
  right: clamp(20px, 2.6vw, 36px);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 9px;
  border: 1px solid color-mix(in srgb, var(--cabinet-tone) 38%, var(--line));
  border-radius: 999px;
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 10px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--cabinet-tone) 88%, var(--paper));
  background: rgba(14, 15, 21, .55);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  transition: color .55s var(--ease), border-color .55s var(--ease);
  z-index: 2;
}

.press-cabinet__plate-key {
  color: var(--paper);
  font-weight: 600;
}

.press-cabinet__plate-divider {
  opacity: .55;
}

.press-cabinet__plate-tag {
  color: color-mix(in srgb, var(--cabinet-tone) 78%, var(--paper));
}

.press-cabinet__plate-dot {
  width: 5px;
  height: 5px;
  background: currentColor;
  border-radius: 50%;
  margin-left: 4px;
}

.press-cabinet__drawer {
  position: relative;
  padding: clamp(24px, 3vw, 36px) clamp(14px, 1.8vw, 20px) clamp(18px, 2.4vw, 28px);
  border-radius: 6px;
  background:
    linear-gradient(180deg, var(--paper) 0%, var(--paper-2) 100%);
  color: var(--ink);
  box-shadow:
    inset 0 0 0 1px rgba(122, 109, 79, .35),
    inset 0 6px 14px rgba(122, 109, 79, .14),
    inset 0 -6px 12px rgba(122, 109, 79, .08),
    0 12px 22px -14px rgba(0, 0, 0, .45);
  overflow: hidden;
}

.press-cabinet__drawer::before {
  content: '';
  position: absolute;
  inset: 6px;
  border-radius: 4px;
  border: 1px solid rgba(122, 109, 79, .25);
  pointer-events: none;
}

.press-cabinet__drawer-edge {
  position: absolute;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(180deg, rgba(122, 109, 79, .35), rgba(122, 109, 79, 0));
  pointer-events: none;
}

.press-cabinet__drawer-edge--top { top: 0; }
.press-cabinet__drawer-edge--bottom { bottom: 0; transform: scaleY(-1); }

.press-cabinet__handle {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 22px;
  height: 36px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  z-index: 2;
}

.press-cabinet__handle--left { left: -10px; }
.press-cabinet__handle--right { right: -10px; }

.press-cabinet__handle-stud {
  width: 18px;
  height: 18px;
  background: radial-gradient(circle at 30% 30%, var(--lead-1) 0%, var(--lead-2) 60%, var(--lead-3) 100%);
  border-radius: 50%;
  box-shadow:
    inset 0 -2px 4px rgba(122, 109, 79, .6),
    inset 0 2px 2px rgba(255, 247, 220, .55),
    0 1px 0 rgba(0, 0, 0, .15);
}

.press-cabinet__handle-stem {
  width: 6px;
  height: 8px;
  background: var(--lead-3);
  border-radius: 1px;
  opacity: .8;
}

.press-cabinet__cabret {
  position: absolute;
  left: clamp(20px, 2.4vw, 32px);
  top: clamp(8px, 1vw, 14px);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9.5px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: rgba(60, 48, 24, .55);
  z-index: 2;
}

.press-cabinet__cabret-mark {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1.05vw, 14px);
  letter-spacing: -.04em;
  text-transform: none;
  color: rgba(60, 48, 24, .7);
}

.press-cabinet__cabret-stamp {
  width: 9px;
  height: 9px;
  border: 1px solid rgba(60, 48, 24, .55);
  border-radius: 50%;
  position: relative;
}

.press-cabinet__cabret-stamp::after {
  content: '';
  position: absolute;
  inset: 2px;
  border-radius: 50%;
  background: rgba(60, 48, 24, .35);
}

.press-cabinet__cabret-name {
  opacity: .85;
}

.press-cabinet__tray {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: end;
  gap: clamp(10px, 1.4vw, 18px);
  padding: clamp(6px, .8vw, 12px) clamp(8px, 1.2vw, 16px) clamp(12px, 1.4vw, 16px);
}

.press-cabinet__tray-rule {
  position: absolute;
  left: 6px;
  right: 6px;
  height: 6px;
  pointer-events: none;
  opacity: .8;
}

.press-cabinet__tray-rule--top { top: 0; }
.press-cabinet__tray-rule--bottom { bottom: 0; }

.press-cabinet__tray-cuts {
  position: absolute;
  inset: 8px 8px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: end;
  pointer-events: none;
  z-index: 0;
}

.press-cabinet__tray-cut {
  height: 4px;
  border-bottom: 1px dashed rgba(122, 109, 79, .35);
  margin: 0 4px;
}

.press-cabinet__sort {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: clamp(6px, .8vw, 10px);
  padding: 14px 10px 12px;
  background: transparent;
  border: 0;
  cursor: pointer;
  font: inherit;
  color: inherit;
  z-index: 1;
  transition: transform .45s var(--ease-out);
  --sort-tone: var(--blue);
  --sort-ink: rgba(155, 188, 255, .85);
}

.press-cabinet__sort:hover,
.press-cabinet__sort.is-lifted,
.press-cabinet__sort:focus-visible {
  transform: translateY(-10px);
  outline: none;
}

.press-cabinet__sort:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--sort-tone) 70%, white);
  outline-offset: 4px;
  border-radius: 4px;
}

.press-cabinet__sort.is-active {
  transform: translateY(-14px);
}

.press-cabinet__sort.is-active .press-cabinet__sort-form {
  filter: drop-shadow(0 2px 0 rgba(122, 109, 79, .35)) drop-shadow(0 14px 16px rgba(60, 48, 24, .35));
}

.press-cabinet__sort-form {
  position: relative;
  width: clamp(80px, 11vw, 132px);
  height: clamp(112px, 14vw, 168px);
  transition: filter .4s var(--ease-out), transform .4s var(--ease-out);
  transform: translateY(0);
}

.press-cabinet__sort.is-active .press-cabinet__sort-form {
  transform: translateY(-3px);
}

.press-cabinet__sort-title {
  position: absolute;
  inset: 14px 10px 18px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: clamp(2px, .2vw, 3px);
  pointer-events: none;
  z-index: 2;
  text-align: center;
  line-height: 1.04;
}

.press-cabinet__sort-title.is-lifted {
  filter: drop-shadow(0 1px 0 rgba(60, 48, 24, .4));
}

.press-cabinet__sort-title.is-set {
  filter: drop-shadow(0 1px 0 rgba(60, 48, 24, .45));
}

.press-cabinet__sort-title-lead,
.press-cabinet__sort-title-trail {
  width: 70%;
  height: 1px;
  background: linear-gradient(to right, transparent, rgba(60, 48, 24, .35), transparent);
}

.press-cabinet__sort-title-lead {
  margin-bottom: clamp(2px, .2vw, 3px);
}

.press-cabinet__sort-title-trail {
  margin-top: clamp(2px, .2vw, 3px);
}

.press-cabinet__sort-title-bead {
  display: inline-block;
  width: 3px;
  height: 3px;
  background: var(--sort-ink);
  border-radius: 50%;
  margin: 0 auto 2px;
}

.press-cabinet__sort-title-rows {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(1px, .15vw, 2px);
}

.press-cabinet__sort-title-row {
  display: block;
  color: rgba(28, 22, 12, .9);
  text-shadow: 0 .5px 0 rgba(255, 247, 220, .55);
  white-space: nowrap;
  line-height: 1.05;
  transition: color .35s var(--ease);
}

.press-cabinet__sort.is-active .press-cabinet__sort-title-row {
  color: rgba(28, 22, 12, .98);
}

.press-cabinet__sort-shadow {
  display: block;
  width: clamp(80px, 11vw, 132px);
  height: 8px;
  margin-top: -4px;
  opacity: .55;
  transition: opacity .4s var(--ease), transform .4s var(--ease);
}

.press-cabinet__sort.is-lifted .press-cabinet__sort-shadow,
.press-cabinet__sort.is-active .press-cabinet__sort-shadow {
  opacity: .85;
  transform: translateY(2px) scale(.92);
}

.press-cabinet__sort-foot {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  margin-top: 2px;
  text-align: center;
  font-family: var(--mono);
  font-size: clamp(8.5px, .8vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: rgba(60, 48, 24, .65);
}

.press-cabinet__sort-letter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  margin-bottom: 2px;
  border: 1px solid var(--sort-tone);
  border-radius: 50%;
  color: var(--sort-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
  background: rgba(243, 236, 214, .85);
  transition: background .35s var(--ease), color .35s var(--ease);
}

.press-cabinet__sort.is-active .press-cabinet__sort-letter {
  background: var(--sort-tone);
  color: var(--ink);
}

.press-cabinet__sort-name {
  color: rgba(28, 22, 12, .82);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, 1.1vw, 13px);
  letter-spacing: -.01em;
  text-transform: none;
}

.press-cabinet__sort-tag {
  display: inline-block;
  padding-top: 1px;
  opacity: .65;
}

.press-cabinet__sort-ink {
  position: absolute;
  top: clamp(6px, .8vw, 10px);
  right: clamp(6px, .8vw, 12px);
  width: 12px;
  height: 12px;
  pointer-events: none;
  z-index: 3;
  opacity: 0;
  transition: opacity .35s var(--ease);
}

.press-cabinet__sort.is-active .press-cabinet__sort-ink {
  opacity: 1;
  animation: cabinetInkBlot .9s var(--ease-out) .25s backwards;
}

.press-cabinet__sort-ink-blot {
  position: absolute;
  inset: 4px;
  background: var(--sort-ink);
  border-radius: 45% 55% 60% 40% / 50% 50% 60% 40%;
  box-shadow:
    inset 0 -1px 2px rgba(0, 0, 0, .25),
    0 0 6px var(--sort-ink);
}

.press-cabinet__sort-ink-bleed {
  position: absolute;
  inset: -2px;
  background: var(--sort-ink);
  border-radius: 50%;
  opacity: .14;
  filter: blur(2px);
}

@keyframes cabinetInkBlot {
  0% { transform: scale(.6); opacity: 0; }
  60% { transform: scale(1.1); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}

.press-cabinet__lever {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, 1vw, 14px);
  margin: clamp(2px, .3vw, 6px) auto 0;
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 10px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: rgba(60, 48, 24, .7);
}

.press-cabinet__lever-rule {
  flex: 0 0 auto;
  width: clamp(20px, 3vw, 40px);
  height: 1px;
  background: linear-gradient(to right, transparent, rgba(60, 48, 24, .35));
}

.press-cabinet__lever-rule:last-child {
  background: linear-gradient(to left, transparent, rgba(60, 48, 24, .35));
}

.press-cabinet__lever-row {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.press-cabinet__lever-tag {
  white-space: nowrap;
}

.press-cabinet__lever-dot {
  width: 5px;
  height: 5px;
  background: currentColor;
  border-radius: 50%;
  opacity: .55;
}

.press-cabinet__word-shelf {
  position: relative;
  margin-top: clamp(18px, 2.6vw, 28px);
  padding: clamp(12px, 1.6vw, 16px) clamp(10px, 1.4vw, 18px) clamp(14px, 1.6vw, 18px);
  border-top: 1px dashed rgba(122, 109, 79, .35);
  border-bottom: 1px dashed rgba(122, 109, 79, .35);
  display: grid;
  grid-template-columns: 1fr;
  gap: clamp(6px, .8vw, 10px);
}

.press-cabinet__word-shelf-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 10px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: rgba(60, 48, 24, .6);
}

.press-cabinet__word-shelf-eyebrow-mark {
  width: 4px;
  height: 4px;
  background: var(--cabinet-word-tone);
  border-radius: 50%;
  display: inline-block;
  transition: background-color .5s var(--ease);
}

.press-cabinet__word-shelf-eyebrow-rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(to right, rgba(60, 48, 24, .25), transparent);
}

.press-cabinet__word-shelf-rule {
  height: 4px;
  pointer-events: none;
  opacity: .6;
}

.press-cabinet__word-shelf-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(10px, 1.4vw, 18px);
  align-items: end;
}

.press-cabinet__word {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: clamp(4px, .5vw, 6px);
  padding: 8px 6px 6px;
  background: transparent;
  border: 0;
  cursor: pointer;
  font: inherit;
  color: inherit;
  --word-tone: var(--acid);
  transition: transform .35s var(--ease-out);
}

.press-cabinet__word:hover,
.press-cabinet__word.is-lifted,
.press-cabinet__word:focus-visible {
  transform: translateY(-5px);
  outline: none;
}

.press-cabinet__word:focus-visible {
  outline: 2px solid var(--word-tone);
  outline-offset: 4px;
  border-radius: 4px;
}

.press-cabinet__word.is-active {
  transform: translateY(-7px);
}

.press-cabinet__word-cap {
  display: block;
  width: 88%;
  height: 4px;
  border-bottom: 1px solid rgba(60, 48, 24, .35);
  border-radius: 1px;
  background: linear-gradient(180deg, var(--lead-1) 0%, var(--lead-2) 100%);
  position: relative;
}

.press-cabinet__word.is-active .press-cabinet__word-cap {
  background: linear-gradient(180deg, var(--word-tone) 0%, color-mix(in srgb, var(--word-tone) 60%, var(--lead-3)) 100%);
  border-bottom-color: color-mix(in srgb, var(--word-tone) 70%, var(--ink));
}

.press-cabinet__word-face {
  display: grid;
  grid-template-columns: auto auto;
  align-items: baseline;
  justify-content: center;
  gap: 8px;
  padding: 6px 10px;
  background: rgba(243, 236, 214, .92);
  border-radius: 2px;
  border: 1px solid rgba(122, 109, 79, .25);
  box-shadow:
    inset 0 0 0 1px rgba(255, 247, 220, .45),
    0 1px 0 rgba(122, 109, 79, .25);
  transition: border-color .35s var(--ease), box-shadow .35s var(--ease), background-color .35s var(--ease);
  min-height: 38px;
}

.press-cabinet__word.is-active .press-cabinet__word-face {
  border-color: var(--word-tone);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--word-tone) 35%, rgba(255, 247, 220, .55)),
    0 1px 0 color-mix(in srgb, var(--word-tone) 45%, rgba(122, 109, 79, .35));
}

.press-cabinet__word-glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--lead-2);
  color: var(--ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: 10px;
  letter-spacing: 0;
}

.press-cabinet__word.is-active .press-cabinet__word-glyph {
  background: var(--word-tone);
  color: var(--ink);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--word-tone) 30%, var(--paper));
}

.press-cabinet__word-name {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13.5px, 1.3vw, 15.5px);
  letter-spacing: -.01em;
  color: var(--ink);
}

.press-cabinet__word-mark {
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 10px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: rgba(60, 48, 24, .55);
}

.press-cabinet__word.is-active .press-cabinet__word-mark {
  color: var(--word-tone);
}

.press-cabinet__word-shadow {
  display: block;
  width: 76%;
  height: 6px;
  opacity: 0;
  transition: opacity .35s var(--ease);
}

.press-cabinet__word.is-active .press-cabinet__word-shadow,
.press-cabinet__word.is-lifted .press-cabinet__word-shadow {
  opacity: .65;
}

.press-cabinet__caption {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 10px clamp(8px, 1vw, 14px);
  margin: clamp(12px, 1.6vw, 18px) auto 0;
  font-family: var(--mono);
  font-size: clamp(9px, .82vw, 11px);
  letter-spacing: .2em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--paper) 70%, transparent);
}

.press-cabinet__caption-line {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.15vw, 14px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
  opacity: .78;
}

.press-cabinet__caption-mark {
  color: var(--cabinet-tone);
  font-family: var(--serif);
  font-style: normal;
  font-size: 16px;
  transition: color .55s var(--ease);
}

.press-cabinet__caption-mark--alt {
  opacity: .55;
}

.press-cabinet__caption-date {
  margin-left: auto;
  color: var(--mist);
  opacity: .7;
}

.press-cabinet__rising-arrow {
  position: absolute;
  top: -22px;
  left: 50%;
  transform: translateX(-50%);
  width: 24px;
  height: 30px;
  color: color-mix(in srgb, var(--cabinet-tone) 60%, transparent);
  pointer-events: none;
  z-index: 1;
  transition: color .55s var(--ease);
  opacity: .55;
}

.press-cabinet__rising-arrow svg {
  display: block;
  width: 100%;
  height: 100%;
}

/* responsive ────────────────────────────────────────────────── */

@media (max-width: 880px) {
  .press-cabinet {
    padding: clamp(14px, 3vw, 18px) clamp(12px, 2.4vw, 18px) clamp(14px, 2.4vw, 18px);
  }

  .press-cabinet__tray {
    gap: clamp(8px, 2vw, 12px);
  }

  .press-cabinet__sort-form {
    width: clamp(72px, 18vw, 110px);
    height: clamp(96px, 22vw, 142px);
  }

  .press-cabinet__sort-shadow {
    width: clamp(72px, 18vw, 110px);
  }

  .press-cabinet__word-face {
    min-height: 34px;
  }

  .press-cabinet__cabret {
    font-size: 8px;
  }
}

@media (max-width: 560px) {
  .press-cabinet__tray {
    grid-template-columns: 1fr;
    gap: clamp(10px, 4vw, 16px);
  }

  .press-cabinet__tray-cuts { display: none; }

  .press-cabinet__sort {
    flex-direction: row;
    align-items: center;
    gap: clamp(8px, 2.4vw, 12px);
    padding: 8px 10px;
  }

  .press-cabinet__sort-form {
    width: 64px;
    height: 90px;
  }

  .press-cabinet__sort-shadow {
    display: none;
  }

  .press-cabinet__sort-title {
    position: static;
    flex-direction: row;
    align-items: baseline;
    flex: 1;
    text-align: left;
  }

  .press-cabinet__sort-title-lead,
  .press-cabinet__sort-title-trail { display: none; }
  .press-cabinet__sort-title-rows {
    align-items: flex-start;
    flex: 1;
  }

  .press-cabinet__sort-title-row {
    white-space: normal;
    text-align: left;
  }

  .press-cabinet__sort-foot {
    align-items: flex-end;
    text-align: right;
    min-width: 84px;
  }

  .press-cabinet__word-shelf-row {
    gap: clamp(6px, 2vw, 10px);
  }

  .press-cabinet__word-face {
    padding: 4px 6px;
    min-height: 28px;
  }

  .press-cabinet__word-name {
    font-size: 12.5px;
  }

  .press-cabinet__caption {
    flex-direction: column;
    text-align: center;
    gap: 4px;
  }

  .press-cabinet__caption-date { margin-left: 0; }
}

/* reduced motion ─────────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  .press-cabinet,
  .press-cabinet__sort,
  .press-cabinet__word,
  .press-cabinet__sort-form,
  .press-cabinet__sort-shadow,
  .press-cabinet__sort-ink,
  .press-cabinet__sort-title-row {
    transition: none !important;
    animation: none !important;
    transform: none !important;
  }

  .press-cabinet__sort:hover,
  .press-cabinet__sort.is-lifted,
  .press-cabinet__sort.is-active,
  .press-cabinet__word:hover,
  .press-cabinet__word.is-lifted,
  .press-cabinet__word.is-active {
    transform: none !important;
  }

  .press-cabinet__sort-ink {
    animation: none !important;
    opacity: 1 !important;
  }
}

/* ─────────────────────────────────────────────────────────────
   PRESS LEVER · replaces the cramped hero press plate.
   One deliberate spread: a tall hand-set lever on the left,
   the editor's-note fold button in the middle, and a meta
   footer that names the active voice, the cycling keys, and
   the date. The lever is a real press metaphor — its knob
   rocks down when the answer is pulled open, and rests again
   when folded back. Voice selection is handled elsewhere
   (TitleSweep + SpecimenTray); this plate's only job is to
   open or fold the answer.
   ───────────────────────────────────────────────────────────── */

.press-lever {
  --press-lever-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(14px, 1.6vw, 20px);
  width: 100%;
  margin: 0;
  padding: clamp(18px, 2vw, 26px) clamp(18px, 2.4vw, 32px) clamp(20px, 2.4vw, 28px);
  border: 1px solid color-mix(in srgb, var(--press-lever-tone) 32%, var(--line));
  border-radius: 4px;
  color: var(--paper);
  background:
    radial-gradient(circle at 18% 0%, color-mix(in srgb, var(--press-lever-tone) 14%, transparent) 0%, transparent 42%),
    radial-gradient(circle at 88% 110%, color-mix(in srgb, var(--press-lever-tone) 10%, transparent) 0%, transparent 48%),
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(14, 20, 32, .62));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 30px 56px -34px rgba(0, 0, 0, .7);
  isolation: isolate;
  opacity: 0;
  transform: translateY(10px);
  animation: pressLeverIn .7s var(--ease-out) .3s forwards;
  transition:
    border-color .55s var(--ease),
    box-shadow .55s var(--ease),
    background .55s var(--ease);
}

@keyframes pressLeverIn {
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .press-lever { animation: none !important; opacity: 1 !important; transform: none !important; }
}

/* SVG defs sit invisibly inside the plate so we can reuse
   the grain filter and the tone-driven bloom gradient. */

/* Corner crops mirror printer's crop marks, drawn in the
   plate's tone so each voice marks the spread its own way. */

.press-lever__crop {
  position: absolute;
  width: 14px;
  height: 14px;
  border: 1px solid var(--press-lever-tone);
  pointer-events: none;
  opacity: .8;
  transition: opacity .45s var(--ease), border-color .55s var(--ease);
  z-index: 1;
}

.press-lever__crop--tl { top: 6px; left: 6px; border-right: 0; border-bottom: 0; }
.press-lever__crop--tr { top: 6px; right: 6px; border-left: 0; border-bottom: 0; }
.press-lever__crop--bl { bottom: 6px; left: 6px; border-right: 0; border-top: 0; }
.press-lever__crop--br { bottom: 6px; right: 6px; border-left: 0; border-top: 0; }

/* Soft tonal bloom glows from the lever side when the
   answer is open, reinforcing the "the lever has been
   pulled" gesture. */

.press-lever__bloom {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 18% 50%, color-mix(in srgb, var(--press-lever-tone) 14%, transparent) 0%, transparent 52%);
  pointer-events: none;
  opacity: .55;
  transition: opacity .55s var(--ease);
  z-index: 0;
}

.press-lever.is-open .press-lever__bloom { opacity: 1; }

/* Header band: rules and the small tag that names the plate. */

.press-lever__head {
  position: relative;
  display: grid;
  grid-template-columns: auto auto auto;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.4vw, 18px);
  color: color-mix(in srgb, var(--press-lever-tone) 84%, var(--paper));
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 10px);
  letter-spacing: .26em;
  text-transform: uppercase;
  z-index: 2;
  transition: color .55s var(--ease);
}

.press-lever__head-rule {
  display: block;
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--press-lever-tone) 56%, transparent) 60%, color-mix(in srgb, var(--press-lever-tone) 56%, transparent) 100%);
  max-width: 220px;
}

.press-lever__head-rule:last-child {
  background: linear-gradient(to left, transparent, color-mix(in srgb, var(--press-lever-tone) 56%, transparent) 60%, color-mix(in srgb, var(--press-lever-tone) 56%, transparent) 100%);
}

.press-lever__head-tag {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  white-space: nowrap;
  color: var(--paper);
}

.press-lever__head-mark {
  font-family: var(--serif);
  font-style: normal;
  font-size: clamp(13px, 1.15vw, 16px);
  letter-spacing: 0;
  text-transform: none;
  color: var(--press-lever-tone);
  opacity: .85;
}

.press-lever__head-mark--alt { transform: scaleX(-1); }

.press-lever__head-key {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border: 1px solid color-mix(in srgb, var(--press-lever-tone) 38%, var(--line));
  border-radius: 999px;
  color: color-mix(in srgb, var(--press-lever-tone) 78%, var(--paper));
  font-size: clamp(8px, .72vw, 9px);
  letter-spacing: .22em;
  background: rgba(14, 15, 21, .45);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

/* Main spread: the lever on the left, the action on the right. */

.press-lever__main {
  position: relative;
  display: grid;
  grid-template-columns: clamp(72px, 9vw, 116px) minmax(0, 1fr);
  gap: clamp(18px, 2.4vw, 32px);
  align-items: stretch;
  padding: clamp(14px, 1.6vw, 20px) 0 clamp(4px, .8vw, 10px);
  z-index: 1;
}

/* ── LEVER ─────────────────────────────────────────────────── */

.press-lever__lever {
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  height: clamp(180px, 22vw, 248px);
  padding: 4px;
  border: 1px solid color-mix(in srgb, var(--press-lever-tone) 32%, var(--line));
  border-radius: 4px;
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .045) 0%, rgba(243, 236, 214, .012) 50%, transparent 100%),
    rgba(14, 15, 21, .4);
  box-shadow: inset 0 0 0 1px rgba(146, 186, 255, .04);
  transition: border-color .45s var(--ease), background .45s var(--ease);
  overflow: visible;
}

.press-lever.is-open .press-lever__lever {
  border-color: color-mix(in srgb, var(--press-lever-tone) 56%, transparent);
}

/* Two faint vertical rules along the cage. */

.press-lever__lever-rule {
  position: absolute;
  top: 6px;
  bottom: 6px;
  width: 1px;
  background: linear-gradient(to bottom, transparent, color-mix(in srgb, var(--press-lever-tone) 28%, transparent), transparent);
  pointer-events: none;
  opacity: .65;
}

.press-lever__lever-rule { left: 18px; }
.press-lever__lever-rule--low { left: auto; right: 18px; }

/* SVG lever figure — shaft, pivot, knob, base. */

.press-lever__lever-svg {
  position: relative;
  display: block;
  width: clamp(56px, 6.4vw, 80px);
  height: 100%;
  color: var(--press-lever-tone);
  z-index: 1;
  transition: color .55s var(--ease);
}

.press-lever__lever-shaft-group {
  transform-box: fill-box;
  transform-origin: 40px 208px;
  transition: transform .55s var(--ease-spring);
}

.press-lever__lever.is-pulled .press-lever__lever-shaft-group {
  transform: rotate(28deg);
}

.press-lever__lever-knob {
  transform-box: fill-box;
  transform-origin: 40px 34px;
  transition: filter .55s var(--ease);
}

.press-lever__lever.is-pulled .press-lever__lever-knob {
  filter: drop-shadow(0 4px 0 rgba(0, 0, 0, .35));
}

.press-lever__lever-ink {
  position: absolute;
  inset: -8% -22% -22% -8%;
  pointer-events: none;
  opacity: 0;
  transition: opacity .65s var(--ease);
  color: var(--press-lever-tone);
}

.press-lever__lever.is-pulled .press-lever__lever-ink {
  opacity: 1;
}

.press-lever__lever.is-rippling .press-lever__lever-ink {
  animation: pressLeverRipple .9s var(--ease-out);
}

@keyframes pressLeverRipple {
  0%   { opacity: 0; transform: scale(.7); }
  35%  { opacity: 1; transform: scale(1); }
  100% { opacity: .85; transform: scale(1.05); }
}

/* ── LEVER FLOURISH · the press's exhale.
   A single drawn ink line that emerges from the lever's pivot
   when pulled and curls out to the right, landing on a small
   bead with a slow halo. The gesture is the middle beat of the
   page's drawn-arc — between the question mark's tail above
   and the answer's exhale below. */
.press-lever__flourish-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.press-lever__flourish-lead {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.1s var(--ease-out);
}

.press-lever__lever.is-pulled .press-lever__flourish-lead {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset 1.15s var(--ease-out) .15s;
}

.press-lever__flourish-trail {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  opacity: 0;
  transition: stroke-dashoffset 1.15s var(--ease-out), opacity .55s var(--ease);
}

.press-lever__lever.is-pulled .press-lever__flourish-trail {
  stroke-dashoffset: 0;
  opacity: .5;
  transition: stroke-dashoffset 1.15s var(--ease-out) .3s, opacity .55s var(--ease) .3s;
}

.press-lever__flourish-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.4);
  transition: opacity .5s var(--ease) 1.05s, transform .6s var(--ease-spring) 1.05s;
}

.press-lever__lever.is-pulled .press-lever__flourish-bead {
  opacity: 1;
  transform: scale(1);
}

.press-lever__flourish-halo {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .55s var(--ease) 1.2s;
}

.press-lever__lever.is-pulled .press-lever__flourish-halo {
  opacity: .55;
  animation: pressLeverFlourishPulse 4.6s var(--ease) infinite 1.85s;
}

@keyframes pressLeverFlourishPulse {
  0%   { transform: scale(.85); opacity: .55; }
  60%  { transform: scale(1.45); opacity: 0; }
  100% { transform: scale(1.45); opacity: 0; }
}

.press-lever__flourish-tag {
  position: absolute;
  right: -6%;
  bottom: -2%;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: 'Iowan Old Style', Georgia, serif;
  font-size: clamp(9px, .76vw, 10.5px);
  font-style: italic;
  letter-spacing: -.005em;
  color: var(--press-lever-tone);
  opacity: 0;
  transform: translateY(2px);
  transition: opacity .55s var(--ease) 1.25s, transform .65s var(--ease-out) 1.25s;
  white-space: nowrap;
  pointer-events: none;
  z-index: 2;
}

.press-lever__lever.is-pulled .press-lever__flourish-tag {
  opacity: .82;
  transform: translateY(0);
}

.press-lever__flourish-tag-mark {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .85;
}

@media (prefers-reduced-motion: reduce) {
  .press-lever__flourish-lead,
  .press-lever__flourish-trail,
  .press-lever__flourish-bead,
  .press-lever__flourish-halo,
  .press-lever__flourish-tag,
  .press-lever__lever-ink {
    transition: none !important;
    animation: none !important;
  }
  .press-lever__lever.is-pulled .press-lever__flourish-lead,
  .press-lever__lever.is-pulled .press-lever__flourish-trail {
    stroke-dashoffset: 0 !important;
    opacity: .5 !important;
  }
  .press-lever__lever.is-pulled .press-lever__flourish-bead {
    opacity: 1 !important;
    transform: none !important;
  }
  .press-lever__lever.is-pulled .press-lever__flourish-halo {
    opacity: .55 !important;
  }
  .press-lever__lever.is-pulled .press-lever__flourish-tag {
    opacity: .82 !important;
    transform: none !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-lever__lever-shaft-group,
  .press-lever__lever-knob {
    transition: none !important;
  }
  .press-lever__lever.is-pulled .press-lever__lever-shaft-group { transform: rotate(28deg); }
  .press-lever__lever.is-rippling .press-lever__lever-ink { animation: none !important; }
}

/* Tag & hint beneath the lever */

.press-lever__lever-tag,
.press-lever__lever-hint {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--press-lever-tone) 86%, var(--paper));
  pointer-events: none;
  z-index: 2;
}

.press-lever__lever-tag {
  top: 8px;
}

.press-lever__lever-tag-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  opacity: .8;
  box-shadow: 0 0 0 3px rgba(14, 15, 21, .55);
}

.press-lever__lever-hint {
  bottom: 6px;
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .22em;
  color: var(--muted);
  opacity: 0;
  transition: opacity .4s var(--ease);
}

.press-lever__lever:hover .press-lever__lever-hint,
.press-lever__lever:focus-visible .press-lever__lever-hint { opacity: .85; }

.press-lever__lever-hint-mark {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .55;
}

/* ── ACTION BUTTON ─────────────────────────────────────────── */

.press-lever__action {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-content: center;
  gap: clamp(10px, 1.2vw, 16px);
  min-width: 0;
}

.press-lever__action-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, .9vw, 12px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
}

.press-lever__action-eyebrow-rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 50%, var(--line));
  opacity: .55;
}

.press-lever__action-eyebrow-rule:last-child {
  background: linear-gradient(to left, transparent, var(--line) 50%, var(--line));
}

.press-lever__action-eyebrow-tag { flex: 0 0 auto; padding: 0 4px; }

.press-lever__action-button {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(28px, 2.6vw, 38px);
  align-items: center;
  column-gap: clamp(14px, 1.6vw, 22px);
  width: 100%;
  padding: clamp(18px, 2vw, 26px) clamp(18px, 2.2vw, 28px);
  border: 1px solid color-mix(in srgb, var(--press-lever-tone) 36%, var(--line));
  border-radius: 4px;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .56), rgba(14, 20, 32, .68));
  color: var(--paper);
  font: inherit;
  text-align: left;
  cursor: pointer;
  isolation: isolate;
  transition:
    border-color .5s var(--ease),
    color .5s var(--ease),
    background .5s var(--ease),
    transform .55s var(--ease-spring),
    box-shadow .6s var(--ease);
}

.press-lever__action-button:hover,
.press-lever__action-button:focus-visible {
  border-color: color-mix(in srgb, var(--press-lever-tone) 70%, transparent);
  transform: translateY(-2px);
  box-shadow: 0 22px 38px -22px color-mix(in srgb, var(--press-lever-tone) 60%, transparent);
  outline: none;
}

.press-lever__action-button:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--press-lever-tone) 70%, white);
  outline-offset: 4px;
}

.press-lever__action-button.is-open {
  border-color: color-mix(in srgb, var(--press-lever-tone) 72%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--press-lever-tone) 14%, transparent), color-mix(in srgb, var(--press-lever-tone) 4%, transparent)),
    rgba(14, 15, 21, .55);
}

.press-lever__action-button:active {
  transform: translateY(1px) scale(.998);
  transition-duration: .08s;
}

.press-lever__action-button::after {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 6px;
  background: radial-gradient(circle at 50% 60%, color-mix(in srgb, var(--press-lever-tone) 38%, transparent) 0%, transparent 65%);
  opacity: 0;
  pointer-events: none;
  z-index: -1;
  transition: opacity .55s var(--ease);
}

.press-lever__action-button.is-open::after,
.press-lever__action-button.is-stamping::after {
  opacity: 1;
}

@keyframes pressLeverStamp {
  0%   { transform: scale(.998); }
  35%  { transform: scale(1.012); }
  60%  { transform: scale(.997); }
  100% { transform: scale(1); }
}

.press-lever__action-button.is-stamping {
  animation: pressLeverStamp .55s var(--ease-spring);
}

.press-lever__action-corner {
  position: absolute;
  width: 11px;
  height: 11px;
  border: 1px solid var(--press-lever-tone);
  opacity: .65;
  pointer-events: none;
  transition: opacity .45s var(--ease);
}

.press-lever__action-corner--tl { top: 5px; left: 5px; border-right: 0; border-bottom: 0; }
.press-lever__action-corner--tr { top: 5px; right: 5px; border-left: 0; border-bottom: 0; }
.press-lever__action-corner--bl { bottom: 5px; left: 5px; border-right: 0; border-top: 0; }
.press-lever__action-corner--br { bottom: 5px; right: 5px; border-left: 0; border-top: 0; }

.press-lever__action-button:hover .press-lever__action-corner,
.press-lever__action-button:focus-visible .press-lever__action-corner,
.press-lever__action-button.is-open .press-lever__action-corner { opacity: 1; }

.press-lever__action-folio {
  grid-column: 1 / 2;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: color-mix(in srgb, var(--press-lever-tone) 84%, var(--paper));
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9.5px);
  letter-spacing: .24em;
  text-transform: uppercase;
  margin-bottom: 2px;
}

.press-lever__action-line {
  grid-column: 1 / 2;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(22px, 2.4vw, 32px);
  letter-spacing: -.022em;
  line-height: 1.1;
  transition: color .55s var(--ease), letter-spacing .55s var(--ease);
}

.press-lever--voice-bold .press-lever__action-line {
  font-style: normal;
  font-weight: 700;
  letter-spacing: -.04em;
  text-transform: uppercase;
  font-size: clamp(18px, 1.9vw, 26px);
}

.press-lever--voice-human .press-lever__action-line {
  font-weight: 500;
}

.press-lever__action-button.is-open .press-lever__action-line {
  color: color-mix(in srgb, var(--press-lever-tone) 88%, var(--paper));
}

.press-lever__action-for {
  grid-column: 1 / 2;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .14em;
  text-transform: uppercase;
}

.press-lever__action-for em {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13.5px, 1.2vw, 16px);
  text-transform: none;
  letter-spacing: -.005em;
  transition: color .45s var(--ease);
}

.press-lever__action-for[aria-hidden="true"] em {
  color: color-mix(in srgb, var(--paper) 60%, transparent);
}

.press-lever.is-signed .press-lever__action-for em {
  color: color-mix(in srgb, var(--press-lever-tone) 78%, var(--paper));
}

.press-lever__action-for-rule {
  display: inline-block;
  width: clamp(20px, 2vw, 28px);
  height: 1px;
  background: linear-gradient(to right, var(--line), transparent);
}

.press-lever__action-arrow {
  grid-column: 2;
  grid-row: 1 / span 3;
  align-self: center;
  display: inline-grid;
  place-items: center;
  width: clamp(28px, 2.6vw, 38px);
  height: clamp(28px, 2.6vw, 38px);
  color: var(--muted);
  transition: color .45s var(--ease), transform .55s var(--ease-out);
  justify-self: end;
}

.press-lever__action-arrow svg { width: 100%; height: 100%; }

.press-lever__action-button:hover .press-lever__action-arrow,
.press-lever__action-button:focus-visible .press-lever__action-arrow {
  color: var(--paper);
  transform: translateX(4px);
}

.press-lever__action-button.is-open .press-lever__action-arrow {
  color: color-mix(in srgb, var(--press-lever-tone) 84%, var(--paper));
  transform: translateX(4px) scaleX(-1);
}

.press-lever__action-foot {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1vw, 13.5px);
  letter-spacing: -.005em;
  line-height: 1.45;
  opacity: .85;
}

.press-lever__action-foot-bead {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--press-lever-tone);
  opacity: .55;
  flex-shrink: 0;
  box-shadow: 0 0 0 3px rgba(14, 15, 21, .55);
}

/* ── FOOTER ────────────────────────────────────────────────── */

.press-lever__foot {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  padding: clamp(10px, 1.2vw, 14px) clamp(8px, 1vw, 12px);
  border-top: 1px dashed color-mix(in srgb, var(--press-lever-tone) 28%, var(--line-soft));
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  z-index: 1;
}

.press-lever__foot-voice {
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.2vw, 14px);
  min-width: 0;
}

.press-lever__foot-voice-letter {
  display: inline-grid;
  place-items: center;
  width: clamp(22px, 2vw, 28px);
  height: clamp(22px, 2vw, 28px);
  border: 1px solid var(--press-lever-tone);
  border-radius: 50%;
  color: var(--press-lever-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1vw, 13.5px);
  letter-spacing: 0;
  text-transform: none;
  background: rgba(14, 15, 21, .45);
  transition: background .45s var(--ease), color .45s var(--ease);
  flex-shrink: 0;
}

.press-lever__foot-voice-meta {
  display: grid;
  gap: 1px;
  min-width: 0;
}

.press-lever__foot-voice-name {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12.5px, 1.1vw, 14.5px);
  letter-spacing: -.005em;
  text-transform: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.press-lever__foot-voice-name em {
  color: var(--press-lever-tone);
}

.press-lever__foot-voice-face {
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .2em;
  opacity: .8;
}

.press-lever__foot-key {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, .9vw, 12px);
  color: color-mix(in srgb, var(--paper) 70%, transparent);
  white-space: nowrap;
  justify-self: center;
}

.press-lever__foot-key-rule {
  flex: 0 0 auto;
  width: clamp(16px, 2vw, 32px);
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line));
  opacity: .65;
}

.press-lever__foot-key-rule:last-child {
  background: linear-gradient(to left, transparent, var(--line));
}

.press-lever__foot-key-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.press-lever__foot-key-kbd {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.press-lever__foot-key-kbd kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  padding: 1px 5px 2px;
  border: 1px solid var(--line);
  border-bottom-width: 2px;
  border-radius: 2px;
  color: var(--paper);
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .06em;
  text-transform: uppercase;
  background: rgba(20, 26, 38, .5);
}

.press-lever__foot-date {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: color-mix(in srgb, var(--paper) 80%, transparent);
  white-space: nowrap;
  justify-self: end;
}

.press-lever__foot-date-mark {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--press-lever-tone);
  opacity: .55;
  box-shadow: 0 0 0 3px rgba(14, 15, 21, .55);
}

/* ── RESPONSIVE ────────────────────────────────────────────── */

@media (max-width: 880px) {
  .press-lever__main {
    grid-template-columns: clamp(64px, 16vw, 92px) minmax(0, 1fr);
    gap: clamp(14px, 2.4vw, 22px);
  }

  .press-lever__lever { height: clamp(168px, 36vw, 220px); }

  .press-lever__foot {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      'voice key'
      'date date';
    row-gap: 8px;
  }

  .press-lever__foot-voice { grid-area: voice; }
  .press-lever__foot-key   { grid-area: key; }
  .press-lever__foot-date  { grid-area: date; justify-self: start; }
}

@media (max-width: 640px) {
  .press-lever {
    padding: 16px 14px 18px;
  }

  .press-lever__head {
    grid-template-columns: auto auto;
  }

  .press-lever__head-rule { display: none; }

  .press-lever__main {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
  }

  .press-lever__lever {
    height: 168px;
    width: min(100%, 220px);
  }

  .press-lever__action-button {
    padding: 16px 18px;
  }

  .press-lever__action-line {
    font-size: clamp(19px, 6vw, 26px);
  }

  .press-lever__action-arrow {
    grid-column: 1;
    grid-row: 2;
    justify-self: end;
    align-self: start;
    margin-top: -28px;
  }

  .press-lever__foot {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      'voice'
      'key'
      'date';
  }

  .press-lever__foot-voice,
  .press-lever__foot-key,
  .press-lever__foot-date { justify-self: start; }

  .press-lever__foot-key-rule { display: none; }
}

@media (max-width: 420px) {
  .press-lever__action-folio { font-size: 8px; letter-spacing: .18em; }
  .press-lever__action-for em { font-size: 12.5px; }
}

@media (prefers-reduced-motion: reduce) {
  .press-lever,
  .press-lever__bloom,
  .press-lever__action-button,
  .press-lever__action-arrow,
  .press-lever__lever {
    transition: none !important;
  }

  .press-lever__action-button:hover,
  .press-lever__action-button:focus-visible {
    transform: none !important;
  }
}


/* ────────────────────────────────────────────────────────────
   READING PROLOGUE · a small editorial prologue between the
   spread and the press lever. Two readings (eye, ear) are
   set as buttons so the reader can mark a word in passing;
   a vertical thread leads the eye down to the lever below.
   ──────────────────────────────────────────────────────────── */

.reading-prologue {
  --reading-prologue-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  column-gap: clamp(20px, 2.4vw, 32px);
  margin: clamp(40px, 5.2vw, 76px) auto clamp(20px, 2.4vw, 36px);
  padding: clamp(18px, 2.2vw, 28px) clamp(20px, 2.6vw, 36px) clamp(14px, 1.8vw, 22px);
  width: min(100%, 920px);
  border: 1px solid var(--line);
  border-radius: 2px;
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .4), rgba(14, 20, 32, .55));
  color: var(--paper);
  opacity: 0;
  transform: translateY(8px);
  transition:
    opacity .8s var(--ease-out),
    transform .8s var(--ease-out),
    border-color .5s var(--ease),
    background .5s var(--ease);
}

.reading-prologue--quiet { --reading-prologue-tone: var(--blue); }
.reading-prologue--human { --reading-prologue-tone: var(--coral); }
.reading-prologue--bold  { --reading-prologue-tone: var(--acid); }

.reading-prologue.is-revealed {
  opacity: 1;
  transform: none;
}

.reading-prologue__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  opacity: 0;
}

.reading-prologue__crop {
  position: absolute;
  width: 14px;
  height: 14px;
  pointer-events: none;
  color: var(--reading-prologue-tone);
  opacity: .8;
  transition: opacity .6s var(--ease);
}

.reading-prologue__crop--tl { top: -1px; left: -1px; border-top: 1px solid; border-left: 1px solid; }
.reading-prologue__crop--tr { top: -1px; right: -1px; border-top: 1px solid; border-right: 1px solid; }
.reading-prologue__crop--bl { bottom: -1px; left: -1px; border-bottom: 1px solid; border-left: 1px solid; }
.reading-prologue__crop--br { bottom: -1px; right: -1px; border-bottom: 1px solid; border-right: 1px solid; }

.reading-prologue__head {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 1.2vw, 16px);
  margin-bottom: clamp(12px, 1.4vw, 18px);
  color: var(--reading-prologue-tone);
}

.reading-prologue__head-rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor, transparent);
  opacity: .7;
}

.reading-prologue__head-tag {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(8px, .9vw, 12px);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .26em;
  text-transform: uppercase;
  white-space: nowrap;
}

.reading-prologue__head-glyph {
  font-family: var(--serif);
  font-size: 14px;
  letter-spacing: 0;
  text-transform: none;
  opacity: .8;
  transform: translateY(2px);
}

.reading-prologue__head-glyph--alt { transform: translateY(2px) scaleX(-1); }

.reading-prologue__head-text {
  font-family: var(--mono);
  letter-spacing: .26em;
}

.reading-prologue__head-folio {
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--mist);
}

.reading-prologue__plate {
  position: relative;
  display: grid;
  gap: clamp(12px, 1.4vw, 18px);
  min-width: 0;
}

.reading-prologue__lede {
  margin: 0;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14.5px, 1.32vw, 17.5px);
  line-height: 1.55;
  letter-spacing: -.005em;
  color: var(--lead-2);
  text-wrap: pretty;
  text-align: left;
}

.reading-prologue__lede em {
  color: var(--paper);
  font-style: italic;
  font-weight: inherit;
}

.reading-prologue__lede-mark {
  display: inline-block;
  margin-right: .35em;
  color: var(--reading-prologue-tone);
  font-style: normal;
  font-size: 1.05em;
  transform: translateY(.05em);
}

.reading-prologue__rule {
  display: block;
  width: 100%;
  height: 8px;
  color: var(--reading-prologue-tone);
  opacity: .85;
}

.reading-prologue__rule svg { width: 100%; height: 100%; display: block; }

.reading-prologue__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.4s var(--ease-out) .25s;
}

.reading-prologue.is-revealed .reading-prologue__rule-stroke { stroke-dashoffset: 0; }

.reading-prologue__rule-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.4);
  transition:
    opacity .35s var(--ease) 1.25s,
    transform .55s var(--ease-spring) 1.25s;
}

.reading-prologue.is-revealed .reading-prologue__rule-bead {
  opacity: 1;
  transform: scale(1);
}

.reading-prologue__readings {
  display: grid;
  gap: clamp(8px, .9vw, 12px);
  margin: 0;
  padding: 0;
  list-style: none;
}

.reading-prologue__reading {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  column-gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(8px, .9vw, 12px) clamp(12px, 1.4vw, 18px);
  border: 1px solid var(--line-soft);
  border-radius: 2px;
  background: linear-gradient(180deg, rgba(28, 36, 52, .18), rgba(14, 20, 32, .28));
  transition:
    border-color .4s var(--ease),
    background .4s var(--ease),
    transform .35s var(--ease-out);
}

.reading-prologue__reading.is-hover,
.reading-prologue__reading:hover,
.reading-prologue__reading:focus-within {
  border-color: var(--reading-prologue-tone);
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .3), rgba(14, 20, 32, .42));
}

.reading-prologue__reading.is-active {
  border-color: var(--reading-prologue-tone);
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .32), rgba(14, 20, 32, .45));
  box-shadow: inset 0 0 0 1px rgba(243, 236, 214, .04);
}

.reading-prologue__reading-rule {
  display: none;
}

.reading-prologue__reading-mark {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  color: var(--reading-prologue-tone);
  opacity: .85;
  transition: opacity .35s var(--ease), transform .35s var(--ease-spring);
}

.reading-prologue__reading-mark svg { width: 100%; height: 100%; display: block; }

.reading-prologue__reading.is-hover .reading-prologue__reading-mark,
.reading-prologue__reading:hover .reading-prologue__reading-mark,
.reading-prologue__reading.is-active .reading-prologue__reading-mark {
  opacity: 1;
  transform: scale(1.05);
}

.reading-prologue__reading-button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  column-gap: clamp(10px, 1.1vw, 14px);
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  width: 100%;
}

.reading-prologue__reading-button:focus-visible {
  outline: 2px solid var(--reading-prologue-tone);
  outline-offset: 3px;
  border-radius: 1px;
}

.reading-prologue__reading-index {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  color: var(--reading-prologue-tone);
  font-family: var(--mono);
  font-size: 12px;
  font-style: normal;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: .85;
  transition: opacity .35s var(--ease), color .35s var(--ease);
}

.reading-prologue__reading.is-active .reading-prologue__reading-index {
  background: var(--reading-prologue-tone);
  color: var(--night);
  opacity: 1;
}

.reading-prologue__reading-line {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: clamp(8px, .9vw, 12px);
  min-width: 0;
}

.reading-prologue__reading-em {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.5vw, 18.5px);
  font-weight: 400;
  letter-spacing: -.012em;
  line-height: 1.2;
}

.reading-prologue__reading.is-active .reading-prologue__reading-em {
  color: var(--paper);
}

.app--voice-quiet .reading-prologue__reading-em { font-style: italic; letter-spacing: -.01em; }
.app--voice-human .reading-prologue__reading-em { font-style: italic; letter-spacing: -.012em; }
.app--voice-bold  .reading-prologue__reading-em { font-style: normal; font-weight: 500; letter-spacing: -.022em; }

.reading-prologue__reading-echo {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(6px, .7vw, 10px);
  flex-basis: 100%;
  margin-top: clamp(4px, .55vw, 8px);
  padding-top: clamp(4px, .55vw, 8px);
  border-top: 1px dashed var(--line-soft);
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
  line-height: 1.4;
}

.reading-prologue__reading-echo-rule {
  display: inline-block;
  width: 18px;
  height: 1px;
  background: currentColor;
  opacity: .5;
}

.reading-prologue__reading-echo-text {
  font-style: italic;
}

.reading-prologue__reading-word {
  display: inline-flex;
  align-items: center;
  gap: clamp(4px, .5vw, 6px);
  margin-left: clamp(2px, .3vw, 4px);
  padding: 3px 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(14, 20, 32, .35);
  color: var(--mist);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
  white-space: nowrap;
  transition:
    color .35s var(--ease),
    border-color .35s var(--ease),
    background .35s var(--ease);
}

.reading-prologue__reading-word-key {
  color: var(--ink-mist);
  font-style: normal;
}

.reading-prologue__reading-word-tag {
  font-family: var(--serif);
  font-style: italic;
  font-size: 11.5px;
  letter-spacing: -.005em;
  text-transform: none;
}

.reading-prologue__reading-word-tag--m3   { color: var(--acid); }
.reading-prologue__reading-word-tag--good { color: var(--coral); }
.reading-prologue__reading-word-tag--yet  { color: var(--blue); }

.reading-prologue__reading.is-active .reading-prologue__reading-word {
  border-color: var(--reading-prologue-tone);
  background: rgba(14, 20, 32, .55);
}

.reading-prologue__reading.is-active .reading-prologue__reading-word-tag {
  color: var(--reading-prologue-tone);
}

.reading-prologue__reading-tick {
  position: absolute;
  bottom: -14px;
  left: 50%;
  transform: translateX(-50%);
  width: 16px;
  height: 16px;
  color: var(--reading-prologue-tone);
  opacity: .65;
}

.reading-prologue__reading-tick svg { width: 100%; height: 100%; display: block; }

.reading-prologue__sign {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(8.5px, .8vw, 10.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity .8s var(--ease-out) 1.05s;
}

.reading-prologue.is-revealed .reading-prologue__sign { opacity: .85; }

.reading-prologue__sign-svg,
.reading-prologue__sign svg { width: clamp(96px, 11vw, 140px); height: 12px; display: block; }

.reading-prologue__sign-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.1s var(--ease-out) .85s;
}

.reading-prologue.is-revealed .reading-prologue__sign-stroke { stroke-dashoffset: 0; }

.reading-prologue__sign-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.4);
  transition:
    opacity .35s var(--ease) 1.7s,
    transform .55s var(--ease-spring) 1.7s;
}

.reading-prologue.is-revealed .reading-prologue__sign-bead {
  opacity: 1;
  transform: scale(1);
}

.reading-prologue__sign-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.reading-prologue__sign-tag em {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.05em;
  letter-spacing: -.005em;
  text-transform: none;
}

.reading-prologue__sign-tag-dot {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--reading-prologue-tone);
  opacity: .85;
}

.reading-prologue__seal {
  position: relative;
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  margin: clamp(6px, 1vw, 14px) 0 clamp(2px, .4vw, 6px);
  padding: clamp(8px, 1.2vw, 14px) clamp(10px, 1.6vw, 18px);
  border: 1px dashed rgba(243, 236, 214, .14);
  border-radius: 2px;
  background:
    linear-gradient(180deg, rgba(216, 240, 106, .025), rgba(255, 118, 95, .02)),
    rgba(20, 26, 38, .35);
  color: var(--paper);
  transition: border-color .5s var(--ease), background .5s var(--ease);
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .8s var(--ease-out) 1.2s, transform .8s var(--ease-out) 1.2s;
}

.reading-prologue.is-revealed .reading-prologue__seal {
  opacity: 1;
  transform: none;
}

.reading-prologue__seal-disc {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(48px, 5vw, 64px);
  height: clamp(48px, 5vw, 64px);
  color: var(--reading-prologue-tone);
  flex: 0 0 auto;
}

.reading-prologue__seal-disc svg {
  width: 100%;
  height: 100%;
  display: block;
}

.reading-prologue__seal-wax {
  position: absolute;
  top: -3px;
  right: -3px;
  width: 14px;
  height: 18px;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity .5s var(--ease) 1.6s, transform .55s var(--ease-spring) 1.6s;
}

.reading-prologue.is-revealed .reading-prologue__seal-wax {
  opacity: 1;
  transform: translateY(0);
}

.reading-prologue__seal-wax-bead {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 5px;
  height: 6px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  background: var(--reading-prologue-tone);
  filter: drop-shadow(1px 1px 0 rgba(0, 0, 0, .25));
  transform-origin: 50% 0;
  animation: sealWaxSettle 1.4s var(--ease-spring) 1.9s backwards;
}

.reading-prologue__seal-wax-wisp {
  position: absolute;
  top: 0;
  right: 1px;
  width: 2px;
  height: 14px;
  background: linear-gradient(180deg, transparent, currentColor 60%);
  opacity: .55;
  transform-origin: 50% 0;
  animation: sealWispSettle 1.2s var(--ease) 1.9s backwards;
}

@keyframes sealWaxSettle {
  0%   { transform: translateY(-6px) scale(.4); }
  60%  { transform: translateY(1px) scale(1.08); }
  100% { transform: translateY(0) scale(1); }
}

@keyframes sealWispSettle {
  0%   { transform: scaleY(.3); opacity: 0; }
  60%  { transform: scaleY(1); opacity: .7; }
  100% { transform: scaleY(.6); opacity: .55; }
}

.reading-prologue__seal-line {
  display: block;
  width: clamp(56px, 7vw, 96px);
  height: 8px;
  color: var(--reading-prologue-tone);
  flex: 0 0 auto;
}

.reading-prologue__seal-line svg {
  display: block;
  width: 100%;
  height: 100%;
}

.reading-prologue__seal-tag {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.18vw, 16px);
  letter-spacing: -.005em;
  line-height: 1.3;
}

.reading-prologue__seal-tag em {
  font-style: italic;
  color: var(--paper);
  text-wrap: balance;
}

.reading-prologue__seal-mark {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  color: var(--reading-prologue-tone);
  font-family: Georgia, 'Iowan Old Style', serif;
  font-size: 14px;
  font-style: normal;
  line-height: 1;
  opacity: .8;
  transform: translateY(1px);
}

@media (prefers-reduced-motion: reduce) {
  .reading-prologue__seal,
  .reading-prologue__seal-wax {
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
  }

  .reading-prologue__seal-wax-bead,
  .reading-prologue__seal-wax-wisp {
    animation: none !important;
    transform: none !important;
  }
}

@media (max-width: 540px) {
  .reading-prologue__seal {
    padding: 8px 10px;
    gap: 10px;
  }

  .reading-prologue__seal-line { display: none; }

  .reading-prologue__seal-tag {
    font-size: 12.5px;
  }
}

.reading-prologue__thread {
  position: relative;
  display: grid;
  justify-items: center;
  align-self: stretch;
  align-content: end;
  gap: clamp(4px, .5vw, 8px);
  padding-bottom: clamp(8px, 1vw, 14px);
  color: var(--reading-prologue-tone);
  min-width: clamp(40px, 6vw, 64px);
  opacity: 0;
  transition: opacity .9s var(--ease-out) 1.5s;
}

.reading-prologue.is-revealed .reading-prologue__thread { opacity: 1; }

.reading-prologue__thread svg {
  display: block;
  width: clamp(36px, 4vw, 52px);
  height: clamp(56px, 6vw, 80px);
}

.reading-prologue__thread-stroke {
  stroke-dasharray: 80 80;
  stroke-dashoffset: 80;
  transition: stroke-dashoffset 1.6s var(--ease-out) 1.4s;
}

.reading-prologue.is-revealed .reading-prologue__thread-stroke { stroke-dashoffset: 0; }

.reading-prologue__thread-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.2);
  transition:
    opacity .35s var(--ease) 2.95s,
    transform .55s var(--ease-spring) 2.95s;
}

.reading-prologue.is-revealed .reading-prologue__thread-bead {
  opacity: 1;
  transform: scale(1);
}

.reading-prologue__thread-tag {
  display: grid;
  justify-items: center;
  gap: 4px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--reading-prologue-tone);
  opacity: .8;
}

.reading-prologue__thread-tag-rule {
  width: 18px;
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.reading-prologue__thread-tag-text { white-space: nowrap; }

.reading-prologue__thread-tag-mark {
  display: inline-block;
  font-family: var(--serif);
  font-style: normal;
  font-size: 14px;
  letter-spacing: 0;
  text-transform: none;
  animation: readingPrologueThreadBob 2.4s var(--ease) 3s infinite;
}

@keyframes readingPrologueThreadBob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(3px); }
}

.reading-prologue__foot {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  align-items: end;
  gap: clamp(14px, 1.6vw, 22px);
  margin-top: clamp(10px, 1.2vw, 16px);
  padding-top: clamp(10px, 1.2vw, 14px);
  border-top: 1px solid var(--line-soft);
}

.reading-prologue__foot-cell {
  display: grid;
  gap: 4px;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: default;
}

.reading-prologue__foot-cell--lever {
  cursor: pointer;
  text-align: right;
  justify-items: end;
  transition: color .35s var(--ease);
}

.reading-prologue__foot-cell--lever:hover,
.reading-prologue__foot-cell--lever:focus-visible {
  color: var(--reading-prologue-tone);
}

.reading-prologue__foot-cell--lever:focus-visible {
  outline: 2px solid var(--reading-prologue-tone);
  outline-offset: 4px;
  border-radius: 1px;
}

.reading-prologue__foot-key {
  color: var(--ink-mist);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.reading-prologue__foot-value {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(4px, .5vw, 6px);
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.15vw, 15px);
  letter-spacing: -.005em;
}

.reading-prologue__foot-cell--lever .reading-prologue__foot-value { justify-content: flex-end; }

.reading-prologue__foot-value svg {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  color: currentColor;
  transition: transform .35s var(--ease-out);
}

.reading-prologue__foot-cell--lever:hover .reading-prologue__foot-value svg,
.reading-prologue__foot-cell--lever:focus-visible .reading-prologue__foot-value svg {
  transform: translateX(3px);
}

.reading-prologue__foot-voice-letter {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: var(--reading-prologue-tone);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0;
}

.reading-prologue__foot-face {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
}

.reading-prologue__foot-cell--lever .reading-prologue__foot-face {
  color: var(--ink-mist);
}

@media (max-width: 720px) {
  .reading-prologue {
    grid-template-columns: minmax(0, 1fr);
    row-gap: clamp(14px, 2.2vw, 20px);
  }
  .reading-prologue__thread {
    grid-column: 1 / -1;
    justify-self: center;
    padding-bottom: 0;
  }
  .reading-prologue__reading {
    padding: 10px 12px;
  }
  .reading-prologue__reading-em {
    font-size: 14.5px;
  }
  .reading-prologue__reading-echo {
    font-size: 11.5px;
  }
  .reading-prologue__foot {
    grid-template-columns: 1fr;
    row-gap: 10px;
  }
  .reading-prologue__foot-cell--lever {
    text-align: left;
    justify-items: start;
  }
  .reading-prologue__foot-cell--lever .reading-prologue__foot-value { justify-content: flex-start; }
}

@media (prefers-reduced-motion: reduce) {
  .reading-prologue,
  .reading-prologue__thread,
  .reading-prologue__thread-tag-mark {
    transition: none !important;
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .reading-prologue__rule-stroke,
  .reading-prologue__sign-stroke,
  .reading-prologue__thread-stroke {
    stroke-dashoffset: 0 !important;
  }
  .reading-prologue__rule-bead,
  .reading-prologue__sign-bead,
  .reading-prologue__thread-bead {
    opacity: 1 !important;
    transform: none !important;
  }
}

/* ────────────────────────────────────────────────────────────
   TITLE PAGE · iteration 285 refines the opening composition
   into a single deliberate plate. Iteration 287 adds a small
   hand-drawn typesetter's mark (fleuron) between the title
   composition and the flourish, and tightens the gap between
   the four title rows so they read as one typeset piece. The
   plate still carries a running head, the question set in four
   rows, a thin annotation pointing at the marked word, the
   fleuron, a hand-drawn flourish, a single dedication, and a
   small voice-and-date footer.
   ──────────────────────────────────────────────────────────── */

.title-page {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(18px, 2vw, 28px);
  width: min(100%, 1080px);
  margin: clamp(48px, 6vw, 92px) auto clamp(36px, 4.4vw, 64px);
  padding: 0 var(--gutter);
  color: var(--title-page-tone, var(--coral));
  opacity: 0;
  transform: translateY(10px);
  animation: titlePageIn 1s var(--ease-out) .05s forwards;
}

@keyframes titlePageIn {
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .title-page {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

.title-page__plate-tag {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 9.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: 0;
  animation: titlePageRunningHeadIn .55s var(--ease-out) .2s forwards;
}

.title-page__plate-tag em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--title-page-tone, var(--coral));
}

.title-page__plate-tag-mark {
  display: inline-block;
  width: clamp(16px, 1.6vw, 24px);
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor);
  opacity: .6;
}

.title-page__plate-tag-mark--alt {
  background: linear-gradient(to left, transparent, currentColor);
}

@keyframes titlePageRunningHeadIn {
  to { opacity: .85; }
}

.title-page__plate {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: clamp(22px, 2.6vw, 36px);
  width: 100%;
  padding: clamp(56px, 6.4vw, 96px) clamp(48px, 6.6vw, 120px) clamp(44px, 4.6vw, 68px);
  border: 1px solid var(--line);
  border-radius: 2px;
  background:
