}

.folio-fold__tool.is-now {
  border-color: currentColor;
  background:
    linear-gradient(180deg, rgba(216, 240, 106, .04), rgba(216, 240, 106, 0)),
    linear-gradient(180deg, rgba(20, 28, 42, .55), rgba(14, 20, 32, .78));
}

.app--voice-quiet .folio-fold__tool.is-now {
  background:
    linear-gradient(180deg, rgba(155, 188, 255, .06), rgba(155, 188, 255, 0)),
    linear-gradient(180deg, rgba(20, 28, 42, .55), rgba(14, 20, 32, .78));
}

.app--voice-human .folio-fold__tool.is-now {
  background:
    linear-gradient(180deg, rgba(255, 118, 95, .06), rgba(255, 118, 95, 0)),
    linear-gradient(180deg, rgba(20, 28, 42, .55), rgba(14, 20, 32, .78));
}

.app--voice-bold .folio-fold__tool.is-now {
  background:
    linear-gradient(180deg, rgba(216, 240, 106, .08), rgba(216, 240, 106, 0)),
    linear-gradient(180deg, rgba(20, 28, 42, .55), rgba(14, 20, 32, .78));
}

.folio-fold__tool-frame {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}

.folio-fold__tool-corner {
  position: absolute;
  width: 8px;
  height: 8px;
  border: 1px solid currentColor;
  opacity: .55;
}

.folio-fold__tool-corner--tl { top: 6px; left: 6px; border-right: 0; border-bottom: 0; }
.folio-fold__tool-corner--tr { top: 6px; right: 6px; border-left: 0; border-bottom: 0; }
.folio-fold__tool-corner--bl { bottom: 6px; left: 6px; border-right: 0; border-top: 0; }
.folio-fold__tool-corner--br { bottom: 6px; right: 6px; border-left: 0; border-top: 0; }

.folio-fold__tool-rule {
  position: absolute;
  left: 12px;
  right: 12px;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 20%, var(--line) 80%, transparent);
  pointer-events: none;
}

.folio-fold__tool-rule--top { top: 22px; }
.folio-fold__tool-rule--bottom { bottom: 22px; }

.folio-fold__tool-mark {
  position: relative;
  z-index: 1;
  display: inline-block;
  margin: 0 auto;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: currentColor;
  opacity: .75;
}

.folio-fold__tool-glyph {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  height: clamp(56px, 6.4vw, 80px);
  color: currentColor;
}

.folio-fold__tool-svg {
  width: clamp(48px, 5vw, 64px);
  height: clamp(48px, 5vw, 64px);
  display: block;
}

.folio-fold__tool-counter-num {
  font-weight: 700;
  letter-spacing: .04em;
  fill: currentColor;
}

.folio-fold__tool-sort { transition: opacity .35s var(--ease); }

.folio-fold__tool-name {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 2px;
  justify-items: center;
}

.folio-fold__tool-name-line {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.4vw, 18px);
  letter-spacing: -.014em;
  color: var(--paper);
  line-height: 1.1;
}

.folio-fold__tool-name-note {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--muted);
}

.folio-fold__tool-ticks {
  position: relative;
  z-index: 1;
  display: inline-flex;
  gap: 5px;
  margin-top: 4px;
}

.folio-fold__tick {
  width: 14px;
  height: 4px;
  background: rgba(146, 186, 255, .14);
  border-radius: 1px;
  transition: background .35s var(--ease), transform .45s var(--ease-spring);
}

.folio-fold__tick.is-on { background: currentColor; }

.folio-fold__tick.is-now {
  background: currentColor;
  transform: scaleY(1.6);
  box-shadow: 0 0 0 2px rgba(216, 240, 106, .12);
}

.app--voice-quiet .folio-fold__tick.is-now { box-shadow: 0 0 0 2px rgba(155, 188, 255, .18); }
.app--voice-human .folio-fold__tick.is-now { box-shadow: 0 0 0 2px rgba(255, 118, 95, .18); }
.app--voice-bold .folio-fold__tick.is-now { box-shadow: 0 0 0 2px rgba(216, 240, 106, .18); }

/* ── Status / arm ─────────────────────────────────────────── */

.folio-fold__status {
  position: relative;
  display: grid;
  grid-template-columns: minmax(240px, 1.05fr) minmax(0, 2fr);
  align-items: stretch;
  gap: clamp(14px, 1.8vw, 22px);
  padding: clamp(14px, 1.6vw, 20px) clamp(16px, 2vw, 26px);
  margin: 0 0 clamp(20px, 2.6vw, 32px);
  background: rgba(20, 28, 42, .55);
  border: 1px solid var(--line);
  z-index: 1;
}

.folio-fold__status-tail {
  display: grid;
  grid-template-rows: auto auto;
  align-content: center;
  gap: clamp(10px, 1.2vw, 14px);
  min-width: 0;
}

.folio-fold__arm {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.4vw, 16px);
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
  transition: opacity .35s var(--ease);
}

.folio-fold__arm:hover .folio-fold__arm-ring-fill,
.folio-fold__arm:focus-visible .folio-fold__arm-ring-fill {
  opacity: .8;
}

.folio-fold__arm-ring {
  position: relative;
  width: clamp(34px, 3.2vw, 42px);
  height: clamp(34px, 3.2vw, 42px);
  display: inline-grid;
  place-items: center;
}

.folio-fold__arm-ring-track {
  position: absolute;
  inset: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  border-top-color: currentColor;
  opacity: .6;
}

.folio-fold__arm-ring-fill {
  position: absolute;
  inset: 4px;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: .25;
  transform: scale(.4);
  transition: transform .55s var(--ease-spring), opacity .35s var(--ease);
}

.folio-fold__arm.is-armed .folio-fold__arm-ring-fill {
  transform: scale(1);
  opacity: .85;
}

.folio-fold__arm.is-armed .folio-fold__arm-ring-track {
  border-color: currentColor;
  opacity: 1;
}

.folio-fold__arm.is-armed .folio-fold__arm-ring {
  animation: folioFoldPulse 1.8s var(--ease) infinite;
}

@keyframes folioFoldPulse {
  0%, 100% { filter: drop-shadow(0 0 0 currentColor); }
  50% { filter: drop-shadow(0 0 4px currentColor); }
}

.folio-fold__arm-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.folio-fold__arm-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.folio-fold__arm-eyebrow-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  opacity: .55;
}

.folio-fold__arm-state {
  display: grid;
  gap: 2px;
  font-family: var(--serif);
}

.folio-fold__arm-state em {
  font-style: italic;
  font-size: clamp(15px, 1.4vw, 19px);
  letter-spacing: -.014em;
  color: var(--paper);
  transition: color .35s var(--ease);
}

.folio-fold__arm.is-armed .folio-fold__arm-state em { color: currentColor; }

.folio-fold__arm-face {
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  color: var(--muted);
  letter-spacing: -.01em;
}

.folio-fold__arm-stamp {
  display: inline-grid;
  place-items: center;
  padding: 6px 10px;
  border: 1px solid currentColor;
  border-radius: 1px;
  color: currentColor;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
  opacity: .85;
  transform: rotate(-1.6deg);
  transform-origin: center;
  animation: folioFoldStamp .6s var(--ease-spring);
}

@keyframes folioFoldStamp {
  0% { opacity: 0; transform: rotate(-7deg) scale(1.18); }
  60% { opacity: .95; transform: rotate(-1deg) scale(.96); }
  100% { opacity: .85; transform: rotate(-1.6deg) scale(1); }
}

.folio-fold__status-rule {
  display: grid;
  align-items: center;
  min-width: 0;
}

.folio-fold__status-rule svg {
  width: 100%;
  height: 8px;
  display: block;
}

.folio-fold__status-rule-stroke {
  opacity: .55;
}

.folio-fold__ledger {
  display: grid;
  grid-template-columns: repeat(3, auto) minmax(0, 1fr);
  align-items: center;
  gap: clamp(14px, 1.6vw, 22px);
}

.folio-fold__ledger-cell {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(6px, .8vw, 10px);
}

.folio-fold__ledger-key {
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.folio-fold__ledger-value {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  font-family: var(--serif);
  font-style: italic;
  color: var(--paper);
}

.folio-fold__ledger-value em {
  font-style: italic;
  font-size: clamp(15px, 1.4vw, 19px);
  letter-spacing: -.014em;
  color: currentColor;
}

.folio-fold__ledger-suffix {
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  color: var(--muted);
}

.folio-fold__ledger-cell--date .folio-fold__ledger-value {
  grid-column: 4;
}

.folio-fold__ledger-date {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  color: var(--paper);
  letter-spacing: -.01em;
}

.folio-fold__status-kbd {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  align-self: center;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
}

.folio-fold__status-kbd kbd {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  padding: 2px 6px;
  border: 1px solid var(--line);
  background: rgba(0, 0, 0, .35);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .05em;
  color: var(--paper);
  border-radius: 2px;
}

.folio-fold__status-kbd-tag {
  display: inline-block;
  margin-left: 4px;
  color: var(--paper);
}

/* ── Hinge (fold) ─────────────────────────────────────────── */

.folio-fold__hinge {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  width: 100%;
  margin: 0;
  padding: clamp(12px, 1.6vw, 18px) clamp(12px, 1.4vw, 18px);
  background: transparent;
  border: 1px dashed var(--line);
  color: currentColor;
  cursor: pointer;
  font: inherit;
  text-align: center;
  transition: background .35s var(--ease), border-color .35s var(--ease), color .35s var(--ease);
}

.folio-fold__hinge:hover,
.folio-fold__hinge:focus-visible {
  background: rgba(20, 28, 42, .45);
  border-style: solid;
  border-color: currentColor;
  color: currentColor;
}

.folio-fold__hinge-rule svg {
  display: block;
  width: 100%;
  height: 6px;
}

.folio-fold__hinge-fold {
  display: inline-grid;
  place-items: center;
  width: clamp(60px, 6vw, 84px);
  height: clamp(28px, 3.2vw, 38px);
  color: currentColor;
}

.folio-fold__hinge-fold svg {
  width: 100%;
  height: 100%;
  display: block;
}

.folio-fold__hinge-fold-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1s var(--ease-out);
}

.folio-fold.is-revealed .folio-fold__hinge-fold-stroke {
  stroke-dashoffset: 0;
}

.folio-fold__hinge-fold-bead {
  animation: folioFoldBeadPulse 2.4s var(--ease) infinite;
}

@keyframes folioFoldBeadPulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.18); }
}

.folio-fold__hinge-fold-ring {
  opacity: .5;
  animation: folioFoldRingPulse 2.4s var(--ease) infinite;
}

@keyframes folioFoldRingPulse {
  0%, 100% { transform: scale(1); opacity: .55; }
  50% { transform: scale(1.4); opacity: .2; }
}

.folio-fold__hinge-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: currentColor;
}

.folio-fold__hinge-tag em {
  font-style: italic;
  letter-spacing: .14em;
  text-transform: none;
  font-family: var(--serif);
  font-size: clamp(13px, 1.2vw, 15px);
}

.folio-fold__hinge-tag-mark {
  font-size: 11px;
  letter-spacing: 0;
}

.folio-fold__hinge-foot {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .24em;
  text-transform: uppercase;
  justify-content: center;
}

.folio-fold__hinge-foot-rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--line) 20%, var(--line) 80%, transparent);
}

.folio-fold__hinge-foot-rule--alt { transform: scaleX(-1); }

.folio-fold__hinge-foot-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.folio-fold__hinge-foot-tag em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .95vw, 13px);
  letter-spacing: -.01em;
  text-transform: none;
  color: var(--paper);
}

.folio-fold__hinge-foot-letter {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: 10px;
  letter-spacing: 0;
  text-transform: none;
  color: currentColor;
  opacity: .85;
}

.folio-fold__hinge-wax {
  position: absolute;
  top: -8px;
  right: 22%;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-8px);
}

.folio-fold.is-revealed .folio-fold__hinge-wax {
  animation: folioFoldWaxDrop 1.4s var(--ease) .55s forwards;
}

@keyframes folioFoldWaxDrop {
  0% { opacity: 0; transform: translateY(-8px); }
  35% { opacity: 1; transform: translateY(0); }
  60% { transform: translateY(2px); }
  100% { opacity: 1; transform: translateY(0); }
}

.folio-fold__hinge-wax-drop {
  display: block;
  width: 22px;
  height: 28px;
  background:
    radial-gradient(circle at 30% 22%, rgba(255, 255, 255, .45), transparent 38%),
    radial-gradient(circle at 50% 70%, rgba(179, 74, 58, .95), rgba(120, 36, 30, 1));
  border-radius: 50% 50% 50% 50% / 38% 38% 62% 62%;
  box-shadow: 0 1px 0 rgba(0, 0, 0, .35);
}

.folio-fold__hinge-wax-bead {
  position: absolute;
  top: -3px;
  left: 50%;
  width: 4px;
  height: 6px;
  border-radius: 50%;
  background: rgba(179, 74, 58, 1);
  transform: translateX(-50%);
  opacity: .7;
}

/* ── Face print footer ────────────────────────────────────── */

.folio-fold__faceprint {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  margin-top: clamp(14px, 1.8vw, 22px);
  padding: 10px clamp(12px, 1.6vw, 18px);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.folio-fold__faceprint-cell {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  justify-content: center;
}

.folio-fold__faceprint-cell em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .98vw, 14px);
  letter-spacing: -.01em;
  text-transform: none;
  color: var(--paper);
}

.folio-fold__faceprint-key {
  color: var(--muted);
}

.folio-fold__faceprint-rule {
  width: 1px;
  height: 14px;
  background: var(--line);
}

@media (prefers-reduced-motion: reduce) {
  .folio-fold__tool,
  .folio-fold__arm-stamp,
  .folio-fold__hinge-wax,
  .folio-fold__hinge-fold-bead,
  .folio-fold__hinge-fold-ring {
    animation: none !important;
    transition: none !important;
    opacity: 1 !important;
    transform: none !important;
  }

  .folio-fold__hinge-fold-stroke { stroke-dashoffset: 0 !important; }
  .folio-fold__tool { transform: none !important; opacity: 1 !important; }
  .folio-fold__arm-ring-fill { transform: scale(1) !important; }
}

@media (max-width: 1180px) {
  .folio-fold__status {
    grid-template-columns: minmax(0, 1fr);
    gap: clamp(10px, 1.4vw, 16px);
  }

  .folio-fold__ledger {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 8px;
  }

  .folio-fold__status-rule { display: none; }

  .folio-fold__status-kbd { justify-self: start; }
}

@media (max-width: 880px) {
  .folio-fold__tools {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .folio-fold__faceprint {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .folio-fold__faceprint-rule { display: none; }
}

@media (max-width: 540px) {
  .folio-fold {
    padding: clamp(28px, 4vw, 44px) clamp(14px, 3vw, 22px) clamp(32px, 5vw, 48px);
  }

  .folio-fold__tools {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .folio-fold__title-line {
    font-size: clamp(24px, 7vw, 36px);
  }

  .folio-fold__ledger {
    grid-template-columns: 1fr;
  }

  .folio-fold__plate-tag {
    font-size: 8px;
    letter-spacing: .18em;
  }
}

/* ────────────────────────────────────────────────────────────
   PRESS HANDWHEEL · a three-cell dashboard for the press: a
   large voice handwheel on the left that sets the active voice
   on each pull, a marked-words plate in the middle that holds
   the active marginalium, and a vertical list of voice dials on
   the right that read like the press's type case. A lever arm
   underneath opens the editor's note. The whole board lives
   between the header and the press bed so the question lands
   on a working page.

   ITERATION 291
   ──────────────────────────────────────────────────────────── */

.press-handwheel {
  --handwheel-tone: var(--coral);
  --handwheel-word-ink: var(--coral);
  --handwheel-tone-soft: rgba(240, 110, 91, .18);
  --handwheel-tone-glow: rgba(240, 110, 91, .32);
  --press-dial-spin: 0deg;
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(10px, 1.4vw, 16px);
  width: 100%;
  max-width: 1180px;
  margin: clamp(20px, 2.6vw, 36px) auto clamp(4px, .6vw, 12px);
  padding: clamp(12px, 1.6vw, 20px) clamp(14px, 2vw, 26px) clamp(10px, 1.4vw, 18px);
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--paper);
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(14, 20, 32, .68)),
    radial-gradient(circle at 0 0, var(--handwheel-tone-soft), transparent 70%);
  font-family: var(--sans);
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 24px 64px -32px rgba(0, 0, 0, .45);
  transition: border-color .55s var(--ease), color .55s var(--ease), background .55s var(--ease);
  isolation: isolate;
  z-index: 1;
  opacity: 0;
  transform: translateY(8px);
  animation: pressHandwheelArrive .9s var(--ease-out) .1s forwards;
}

.press-handwheel.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.press-handwheel::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(120deg, var(--handwheel-tone-glow) 0 1px, transparent 1px 9px);
  opacity: .25;
  mix-blend-mode: screen;
  z-index: -1;
  border-radius: inherit;
}

.press-handwheel::after {
  content: '';
  position: absolute;
  inset: 6px;
  pointer-events: none;
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  opacity: .6;
  z-index: -1;
}

.press-handwheel--voice-quiet {
  --handwheel-tone: var(--blue);
  --handwheel-tone-soft: rgba(155, 188, 255, .16);
  --handwheel-tone-glow: rgba(155, 188, 255, .26);
}
.press-handwheel--voice-human {
  --handwheel-tone: var(--coral);
  --handwheel-tone-soft: rgba(240, 110, 91, .18);
  --handwheel-tone-glow: rgba(240, 110, 91, .32);
}
.press-handwheel--voice-bold {
  --handwheel-tone: var(--acid);
  --handwheel-tone-soft: rgba(214, 240, 106, .18);
  --handwheel-tone-glow: rgba(214, 240, 106, .32);
}
.press-handwheel--word-m3 { --handwheel-word-ink: var(--acid); }
.press-handwheel--word-good { --handwheel-word-ink: var(--coral); }
.press-handwheel--word-yet { --handwheel-word-ink: var(--blue); }

@keyframes pressHandwheelArrive {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

.press-handwheel__corner {
  position: absolute;
  width: 10px;
  height: 10px;
  border: 1px solid currentColor;
  pointer-events: none;
  opacity: .6;
  color: var(--handwheel-tone);
  transition: color .45s var(--ease);
}

.press-handwheel__corner--tl { top: 6px; left: 6px; border-right: 0; border-bottom: 0; }
.press-handwheel__corner--tr { top: 6px; right: 6px; border-left: 0; border-bottom: 0; }
.press-handwheel__corner--bl { bottom: 6px; left: 6px; border-right: 0; border-top: 0; }
.press-handwheel__corner--br { bottom: 6px; right: 6px; border-left: 0; border-top: 0; }

.press-handwheel__rule {
  position: absolute;
  left: clamp(16px, 2vw, 28px);
  right: clamp(16px, 2vw, 28px);
  height: 4px;
  color: var(--handwheel-tone);
  opacity: .35;
  pointer-events: none;
}

.press-handwheel__rule--top { top: 6px; }
.press-handwheel__rule--bottom { bottom: 6px; }

/* — Masthead (running head above the plate) — */

.press-handwheel__masthead {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  color: var(--handwheel-tone);
  transition: color .55s var(--ease);
}

.press-handwheel__masthead-rule {
  height: 1px;
  background:
    linear-gradient(90deg, transparent, currentColor 32%, currentColor 68%, transparent);
  opacity: .35;
}

.press-handwheel__masthead-rule--alt {
  background:
    linear-gradient(90deg, transparent, currentColor 32%, currentColor 68%, transparent);
}

.press-handwheel__masthead-tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, 1vw, 12px);
  padding: clamp(2px, .3vw, 4px) clamp(8px, 1vw, 14px);
  font-family: var(--mono);
  font-size: clamp(8.5px, .75vw, 9.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--paper);
}

.press-handwheel__masthead-glyph {
  font-family: var(--serif);
  font-size: clamp(13px, 1.05vw, 15px);
  letter-spacing: 0;
  text-transform: none;
  color: currentColor;
  opacity: .75;
}

.press-handwheel__masthead-glyph--alt { opacity: .55; }

.press-handwheel__masthead-eyebrow {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--handwheel-tone);
  transition: color .55s var(--ease);
}

.press-handwheel__masthead-mark {
  font-family: var(--mono);
  font-size: clamp(8px, .65vw, 9px);
  letter-spacing: .22em;
  color: var(--muted);
  padding-left: clamp(8px, 1vw, 12px);
  border-left: 1px solid var(--line-soft);
}

/* — Plate (the three-cell workspace) — */

.press-handwheel__plate {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) auto minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: stretch;
  gap: clamp(8px, 1.2vw, 18px);
  padding: clamp(6px, 1vw, 14px) 0;
}

.press-handwheel__rule--v {
  position: relative;
  inset: auto;
  left: auto;
  right: auto;
  width: 1px;
  height: auto;
  align-self: stretch;
  background: linear-gradient(180deg, transparent, var(--line) 28%, var(--line) 72%, transparent);
  opacity: .6;
}

/* — Voice handwheel (left cell) — */

.press-handwheel__dial {
  --press-dial-spin: 0deg;
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
  align-items: center;
  gap: clamp(14px, 1.8vw, 24px);
  padding: clamp(8px, 1.2vw, 16px) clamp(12px, 1.6vw, 22px);
  background:
    radial-gradient(circle at 26% 50%, var(--handwheel-tone-soft), transparent 68%),
    rgba(20, 28, 42, .55);
  border: 1px solid var(--line);
  border-radius: 2px;
  isolation: isolate;
  transition: border-color .45s var(--ease), background .45s var(--ease);
}

.press-handwheel__dial.is-hovered,
.press-handwheel__dial:focus-within {
  border-color: var(--handwheel-tone);
}

.press-handwheel__dial::before {
  content: '';
  position: absolute;
  inset: 4px;
  pointer-events: none;
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  opacity: .6;
  z-index: 0;
}

.press-handwheel__dial-flange {
  position: absolute;
  inset: -4px;
  border-radius: 2px;
  pointer-events: none;
  border: 1px dashed currentColor;
  color: var(--handwheel-tone);
  opacity: 0;
  transition: opacity .35s var(--ease);
  z-index: 0;
}

.press-handwheel__dial.is-hovered .press-handwheel__dial-flange,
.press-handwheel__dial:focus-within .press-handwheel__dial-flange {
  opacity: .4;
}

.press-handwheel__dial-button {
  position: relative;
  display: contents;
  font: inherit;
  color: inherit;
  cursor: pointer;
}

.press-handwheel__dial-face {
  position: relative;
  display: grid;
  place-items: center;
  aspect-ratio: 1 / 1;
  width: 100%;
  max-width: 100%;
  margin: 0;
  color: var(--handwheel-tone);
  transition: color .45s var(--ease);
  z-index: 1;
}

.press-handwheel__dial-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.press-handwheel__dial-rotate {
  transform-origin: 100px 100px;
  transform-box: view-box;
  transition: transform 1.15s var(--ease-spring);
  animation: pressHandwheelDialSettle 1.1s var(--ease-spring) .25s both;
}

.press-handwheel__dial-letter {
  transform-origin: 100px 100px;
  transform-box: view-box;
  animation: pressHandwheelLetterSet .65s var(--ease-spring);
}

@keyframes pressHandwheelLetterSet {
  0% { opacity: 0; transform: scale(.78); }
  60% { opacity: 1; transform: scale(1.04); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes pressHandwheelDialSettle {
  0% { opacity: 0; transform: rotate(-72deg) scale(.82); }
  60% { opacity: 1; transform: rotate(6deg) scale(1.03); }
  100% { opacity: 1; transform: rotate(0deg) scale(1); }
}

.press-handwheel__dial-pointer {
  transform-origin: 100px 100px;
  transform-box: view-box;
  transition: transform 1.15s var(--ease-spring);
}

.press-handwheel__dial-pip {
  transform-origin: 100px 30px;
  transform-box: view-box;
  transition: transform 1.15s var(--ease-spring);
}

.press-handwheel__dial-strike {
  transform-origin: 100px 100px;
  transform-box: view-box;
  animation: pressHandwheelDialStrike .85s var(--ease-out) both;
}

@keyframes pressHandwheelDialStrike {
  0% { opacity: 0; transform: scale(.5); }
  40% { opacity: .6; transform: scale(1.06); }
  100% { opacity: 0; transform: scale(1.4); }
}

.press-handwheel__dial-readout {
  position: relative;
  display: grid;
  gap: clamp(3px, .4vw, 5px);
  min-width: 0;
  z-index: 1;
}

.press-handwheel__dial-readout-row {
  display: flex;
  align-items: baseline;
  gap: clamp(6px, .8vw, 10px);
  min-width: 0;
  flex-wrap: wrap;
}

.press-handwheel__dial-readout-row--face {
  border-top: 1px dashed var(--line-soft);
  padding-top: clamp(4px, .6vw, 7px);
  margin-top: clamp(4px, .6vw, 6px);
}

.press-handwheel__dial-readout-key {
  flex: 0 0 auto;
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 9px);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.press-handwheel__dial-readout-state {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--handwheel-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.18vw, 17.5px);
  letter-spacing: -.012em;
  text-transform: lowercase;
  line-height: 1;
  transition: color .45s var(--ease);
}

.press-handwheel__dial-readout-state--standby { color: var(--muted); }
.press-handwheel__dial-readout-state--cold { color: var(--blue); }
.press-handwheel__dial-readout-state--warming { color: var(--coral); }
.press-handwheel__dial-readout-state--armed { color: var(--acid); }
.press-handwheel__dial-readout-state--hot { color: var(--coral); }

.press-handwheel__dial-readout-state-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, .04);
  animation: pressHandwheelStatePulse 1.6s var(--ease) infinite;
}

.press-handwheel__dial-readout-state--standby .press-handwheel__dial-readout-state-dot { animation: none; opacity: .55; }
.press-handwheel__dial-readout-state--cold .press-handwheel__dial-readout-state-dot { animation: pressHandwheelStatePulse 2.4s var(--ease) infinite; opacity: .7; }
.press-handwheel__dial-readout-state--warming .press-handwheel__dial-readout-state-dot { animation: pressHandwheelStatePulse 1.6s var(--ease) infinite; opacity: .85; }
.press-handwheel__dial-readout-state--armed .press-handwheel__dial-readout-state-dot { animation: pressHandwheelStatePulse 1.1s var(--ease) infinite; }
.press-handwheel__dial-readout-state--hot .press-handwheel__dial-readout-state-dot { animation: pressHandwheelStatePulse .8s var(--ease) infinite; }

@keyframes pressHandwheelStatePulse {
  0%, 100% { transform: scale(1); opacity: .95; }
  50% { transform: scale(.55); opacity: .4; }
}

.press-handwheel__dial-readout-voice {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14.5px, 1.15vw, 17px);
  letter-spacing: -.012em;
}

.press-handwheel__dial-readout-face {
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
}

.press-handwheel__dial-readout-hint {
  grid-column: 1 / -1;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: clamp(4px, .5vw, 8px);
  padding-top: clamp(4px, .6vw, 7px);
  border-top: 1px dashed var(--line-soft);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8px, .65vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press-handwheel__dial-readout-hint kbd {
  font-family: inherit;
  font-size: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  padding: 1px 5px;
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  color: var(--paper);
  background: rgba(20, 28, 42, .55);
}

.press-handwheel__dial-readout-hint em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(10px, .8vw, 11.5px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--mist);
  margin-right: 2px;
}

/* — Mark plate (middle cell) — */

.press-handwheel__mark {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(10px, 1.4vw, 18px);
  padding: clamp(8px, 1.2vw, 16px) clamp(12px, 1.6vw, 22px);
  background:
    radial-gradient(circle at 74% 50%, color-mix(in srgb, var(--handwheel-word-ink) 14%, transparent), transparent 68%),
    rgba(20, 28, 42, .55);
  border: 1px solid var(--line);
  border-radius: 2px;
  transition: border-color .45s var(--ease);
  isolation: isolate;
}

.press-handwheel__mark.is-hovered,
.press-handwheel__mark:focus-within {
  border-color: var(--handwheel-word-ink);
}

.press-handwheel__mark-button {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
  align-items: center;
  gap: clamp(14px, 1.8vw, 24px);
  font: inherit;
  color: inherit;
  cursor: pointer;
  background: transparent;
  border: 0;
  padding: 0;
  text-align: left;
}

.press-handwheel__mark-plate {
  position: relative;
  display: grid;
  place-items: center;
  aspect-ratio: 1 / 1;
  width: 100%;
  max-width: 100%;
  margin: 0;
  color: var(--handwheel-word-ink);
  transition: color .45s var(--ease), transform .55s var(--ease-spring);
  z-index: 1;
}

.press-handwheel__mark:hover .press-handwheel__mark-plate,
.press-handwheel__mark:focus-within .press-handwheel__mark-plate {
  transform: rotate(-3deg);
}

.press-handwheel__mark-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.press-handwheel__mark-glyph {
  transform-origin: 100px 100px;
  transform-box: view-box;
  animation: pressHandwheelMarkArrive .8s var(--ease-spring);
}

@keyframes pressHandwheelMarkArrive {
  0% { opacity: 0; transform: scale(.78); }
  60% { opacity: 1; transform: scale(1.04); }
  100% { opacity: 1; transform: scale(1); }
}

.press-handwheel__mark-strike {
  transform-origin: 100px 100px;
  transform-box: view-box;
  animation: pressHandwheelMarkStrike .8s var(--ease-out) both;
}

@keyframes pressHandwheelMarkStrike {
  0% { opacity: 0; transform: scale(.55); }
  40% { opacity: .55; transform: scale(1.06); }
  100% { opacity: 0; transform: scale(1.3); }
}

.press-handwheel__mark-readout {
  position: relative;
  display: grid;
  gap: clamp(3px, .4vw, 5px);
  min-width: 0;
  z-index: 1;
}

.press-handwheel__mark-readout-row {
  display: flex;
  align-items: baseline;
  gap: clamp(6px, .8vw, 10px);
  min-width: 0;
  flex-wrap: wrap;
}

.press-handwheel__mark-readout-row--note {
  border-top: 1px dashed var(--line-soft);
  padding-top: clamp(4px, .6vw, 7px);
  margin-top: clamp(2px, .3vw, 4px);
}

.press-handwheel__mark-readout-key {
  flex: 0 0 auto;
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 9px);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.press-handwheel__mark-readout-value {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14.5px, 1.15vw, 17px);
  letter-spacing: -.012em;
}

.press-handwheel__mark-readout-mark {
  flex: 0 0 auto;
  display: inline-grid;
  place-items: center;
  padding: 2px 8px;
  border: 1px solid currentColor;
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: currentColor;
  background: rgba(14, 20, 32, .55);
  transition: color .35s var(--ease), border-color .35s var(--ease);
}

.press-handwheel__mark-readout-note {
  flex: 1 1 auto;
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
}

.press-handwheel__mark-readout-tick {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: clamp(3px, .4vw, 5px);
  margin-top: clamp(6px, .8vw, 10px);
  padding-top: clamp(4px, .6vw, 6px);
  border-top: 1px dashed var(--line-soft);
}

.press-handwheel__mark-readout-tick-cell {
  flex: 1 1 auto;
  height: 4px;
  background: rgba(146, 186, 255, .14);
  border-radius: 1px;
  transition: background .35s var(--ease), transform .45s var(--ease-spring);
}

.press-handwheel__mark-readout-tick-cell.is-on {
  background: var(--handwheel-word-ink);
}

.press-handwheel__mark-readout-tick-cell.is-just-set {
  transform: scaleY(1.8);
  box-shadow: 0 0 0 2px rgba(255, 255, 255, .05);
}

.press-handwheel__mark-readout-hint {
  grid-column: 1 / -1;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: clamp(4px, .5vw, 6px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8px, .65vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press-handwheel__mark-readout-hint kbd {
  font-family: inherit;
  font-size: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  padding: 1px 5px;
  border: 1px solid var(--line-soft);
  border-radius: 1px;
  color: var(--paper);
  background: rgba(20, 28, 42, .55);
}

.press-handwheel__mark-readout-hint em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(10px, .8vw, 11.5px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--mist);
  margin-right: 2px;
}

/* — Voice list (right cell, the type case) — */

.press-handwheel__voice-list {
  display: grid;
  grid-template-rows: repeat(3, minmax(0, 1fr));
  gap: clamp(6px, .8vw, 10px);
  align-self: stretch;
}

.press-handwheel__voice-cell {
  display: grid;
  grid-template-columns: clamp(48px, 4vw, 64px) minmax(0, 1fr);
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  padding: clamp(6px, .8vw, 10px) clamp(8px, 1vw, 14px);
  background: rgba(20, 28, 42, .55);
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--muted);
  font: inherit;
  cursor: pointer;
  text-align: left;
  transition: border-color .4s var(--ease), background .4s var(--ease), color .4s var(--ease);
}

.press-handwheel__voice-cell:hover,
.press-handwheel__voice-cell:focus-visible {
  border-color: var(--handwheel-tone);
  color: var(--handwheel-tone);
  outline: none;
}

.press-handwheel__voice-cell--quiet.is-active,
.press-handwheel__voice-cell--quiet.is-active:hover {
  border-color: var(--blue);
  color: var(--blue);
  background: rgba(155, 188, 255, .08);
}
.press-handwheel__voice-cell--human.is-active,
.press-handwheel__voice-cell--human.is-active:hover {
  border-color: var(--coral);
  color: var(--coral);
  background: rgba(240, 110, 91, .08);
}
.press-handwheel__voice-cell--bold.is-active,
.press-handwheel__voice-cell--bold.is-active:hover {
  border-color: var(--acid);
  color: var(--acid);
  background: rgba(214, 240, 106, .08);
}

.press-handwheel__voice-cell-pip {
  display: grid;
  place-items: center;
  width: 100%;
  aspect-ratio: 1 / 1;
  color: inherit;
}

.press-handwheel__voice-cell-pip svg {
  display: block;
  width: 100%;
  height: 100%;
}

.press-handwheel__voice-cell-readout {
  display: grid;
  gap: clamp(1px, .2vw, 2px);
  min-width: 0;
}

.press-handwheel__voice-cell-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}

.press-handwheel__voice-cell-letter {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.15vw, 17px);
  letter-spacing: -.012em;
  color: inherit;
}

.press-handwheel__voice-cell-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, .96vw, 14px);
  letter-spacing: -.005em;
  color: inherit;
}

.press-handwheel__voice-cell-now {
  flex: 0 0 auto;
  margin-left: auto;
  padding: 1px 6px;
  border: 1px solid currentColor;
  border-radius: 999px;
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.press-handwheel__voice-cell-face {
  color: var(--mist);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

/* — The lever arm underneath — */

.press-handwheel__arm {
  position: relative;
  display: grid;
  grid-template-columns: clamp(56px, 5vw, 72px) minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.4vw, 16px);
  padding: clamp(8px, 1.2vw, 14px) clamp(10px, 1.4vw, 14px);
  background:
    linear-gradient(180deg, rgba(20, 28, 42, .55), rgba(14, 20, 32, .7));
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--paper);
  cursor: pointer;
  font: inherit;
  text-align: left;
  transition: border-color .4s var(--ease), color .4s var(--ease);
  overflow: hidden;
}

.press-handwheel__arm:hover,
.press-handwheel__arm:focus-visible {
  border-color: var(--coral);
  color: var(--coral);
  outline: none;
}

.press-handwheel__arm:hover .press-handwheel__arm-arrow,
.press-handwheel__arm:focus-visible .press-handwheel__arm-arrow {
  transform: translateX(3px);
  color: var(--coral);
}

.press-handwheel__arm-arm {
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  height: clamp(54px, 5vw, 70px);
  aspect-ratio: 1 / 1;
  border: 1px solid currentColor;
  border-radius: 1px;
  background: rgba(14, 20, 32, .55);
  transition: transform .55s var(--ease-spring);
}

.press-handwheel__arm:hover .press-handwheel__arm-arm,
.press-handwheel__arm:focus-visible .press-handwheel__arm-arm {
  transform: rotate(8deg);
}

.press-handwheel__arm-pivot {
  position: absolute;
  bottom: 8px;
  left: 50%;
  width: 8px;
  height: 8px;
  border: 1px solid currentColor;
  border-radius: 50%;
  background: var(--night);
  transform: translateX(-50%);
  opacity: .55;
}

.press-handwheel__arm-bar {
  position: absolute;
  bottom: 10px;
  left: 50%;
  width: 2px;
  height: 64%;
  background: currentColor;
  transform: translateX(-50%);
  transform-origin: 50% 100%;
  transition: transform .55s var(--ease-spring);
}

.press-handwheel__arm:hover .press-handwheel__arm-bar,
.press-handwheel__arm:focus-visible .press-handwheel__arm-bar {
  transform: translateX(-50%) rotate(-22deg);
}

.press-handwheel__arm-knob {
  position: absolute;
  top: 12%;
  left: 50%;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: currentColor;
  transform: translateX(-50%);
  box-shadow:
    0 0 0 3px var(--night),
    0 0 0 4px currentColor;
  transition: transform .55s var(--ease-spring);
}

.press-handwheel__arm:hover .press-handwheel__arm-knob,
.press-handwheel__arm:focus-visible .press-handwheel__arm-knob {
  transform: translateX(-50%) translateY(-3px);
}

.press-handwheel__arm-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.press-handwheel__arm-eyebrow {
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 9px);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.press-handwheel__arm-headline {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13.5px, 1.1vw, 16px);
  color: inherit;
  letter-spacing: -.012em;
  line-height: 1.2;
}

.press-handwheel__arm-headline em {
  font-style: italic;
  color: var(--handwheel-tone);
  margin: 0 .18em;
}

.press-handwheel__arm-arrow {
  display: inline-grid;
  place-items: center;
  width: clamp(22px, 2vw, 28px);
  height: clamp(22px, 2vw, 28px);
  color: var(--muted);
  transition: color .4s var(--ease), transform .55s var(--ease-spring);
}

.press-handwheel__arm-arrow svg {
  width: 60%;
  height: 60%;
}

/* — Date row — */

.press-handwheel__date {
  grid-column: 1 / -1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(6px, .8vw, 12px);
  margin-top: 0;
  padding: 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: .85;
}

.press-handwheel__date em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .92vw, 13px);
  color: var(--paper);
  text-transform: none;
  letter-spacing: -.005em;
}

.press-handwheel__date-mark {
  display: inline-block;
  width: 5px;
  height: 5px;
  border: 1px solid currentColor;
  background: transparent;
  border-radius: 50%;
  opacity: .55;
}

.press-handwheel__date-mark--alt {
  background: currentColor;
}

/* — Reduced motion & responsive — */

@media (prefers-reduced-motion: reduce) {
  .press-handwheel { animation: none !important; opacity: 1 !important; transform: none !important; }
  .press-handwheel__dial-rotate,
  .press-handwheel__dial-pointer,
  .press-handwheel__dial-pip,
  .press-handwheel__dial-letter,
  .press-handwheel__dial-strike,
  .press-handwheel__mark-glyph,
  .press-handwheel__mark-strike { animation: none !important; transition: none !important; transform: none !important; }
  .press-handwheel__dial-readout-state-dot { animation: none !important; }
  .press-handwheel__arm-bar,
  .press-handwheel__arm-knob,
  .press-handwheel__arm-arm,
  .press-handwheel__mark-plate { transition: none !important; }
}

@media (max-width: 1180px) {
  .press-handwheel__plate {
    grid-template-columns: minmax(0, 1.2fr) auto minmax(0, 1fr);
  }
  .press-handwheel__voice-list {
    grid-column: 1 / -1;
    grid-template-rows: none;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    margin-top: clamp(2px, .3vw, 4px);
  }
}

@media (max-width: 880px) {
  .press-handwheel__plate {
    grid-template-columns: minmax(0, 1fr);
  }
  .press-handwheel__rule--v { display: none; }
  .press-handwheel__dial,
  .press-handwheel__mark {
    grid-template-columns: minmax(0, 1fr);
  }
  .press-handwheel__dial {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);
  }
  .press-handwheel__mark-button {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);
  }
  .press-handwheel__voice-list {
    grid-template-rows: repeat(3, minmax(0, 1fr));
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 540px) {
  .press-handwheel {
    padding: 12px 14px 10px;
  }
  .press-handwheel__masthead-mark { display: none; }
  .press-handwheel__dial,
  .press-handwheel__mark-button {
    grid-template-columns: minmax(0, 1fr);
  }
  .press-handwheel__dial-readout-row--face {
    padding-top: 4px;
    margin-top: 4px;
  }
  .press-handwheel__mark-readout-row--note { padding-top: 4px; }
}

/* ────────────────────────────────────────────────────────────
   PRESSINGS TRIPTYCH · the centerpiece of the title spread.
   A vertical stack of three pressings: the active voice is
   expanded in the middle, the other two sit as compact ghost
   cards above and below. Click any pressing to set the voice.
   Click any word in the active pressing to mark it.
   ──────────────────────────────────────────────────────────── */

.pressings-triptych {
  --pt-tone: var(--paper);
  --pt-frame: rgba(243, 236, 214, .18);
  --pt-frame-soft: rgba(243, 236, 214, .08);
  --pt-paper: #1a1d29;
  --pt-paper-2: #232636;
  --pt-paper-edge: rgba(243, 236, 214, .14);
  --pt-paper-shadow: rgba(0, 0, 0, .55);
  --pt-ghost-bg: #14161f;
  --pt-ghost-bg-2: #1a1d29;
  --pt-ghost-opacity: .58;
  --pt-rule: rgba(243, 236, 214, .22);
  --pt-glyph: '⌇';
  position: relative;
  display: grid;
  gap: clamp(18px, 2.6vw, 32px);
  width: 100%;
  max-width: 1080px;
  margin: 0 auto;
  padding: 0;
  font-family: var(--sans);
  color: var(--paper);
}

.pressings-triptych__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

.pressings-triptych__caption {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  color: var(--paper);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .28em;
  text-transform: uppercase;
  opacity: .55;
}

.pressings-triptych__caption-mark {
  width: 28px;
  height: 1px;
  background: linear-gradient(to right, var(--pt-tone), transparent);
}

.pressings-triptych__caption-mark--alt {
  background: linear-gradient(to left, var(--pt-tone), transparent);
}

.app--voice-quiet .pressings-triptych { --pt-tone: var(--blue); }
.app--voice-human .pressings-triptych { --pt-tone: var(--coral); }
.app--voice-bold .pressings-triptych { --pt-tone: var(--acid); }

.pressings-triptych__headline {
  display: grid;
  gap: clamp(8px, 1vw, 14px);
  margin: 0;
  text-align: center;
}

.pressings-triptych__headline-text {
  margin: 0;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(24px, 3.6vw, 40px);
  line-height: 1.1;
  letter-spacing: -.024em;
  color: var(--paper);
}

.pressings-triptych__headline-text i {
  font-style: italic;
  color: var(--pt-tone);
  margin-left: .14em;
}

.pressings-triptych__headline-lede {
  margin: 0 auto;
  max-width: 56ch;
  color: var(--ink-mist);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(13px, 1.1vw, 15.5px);
  line-height: 1.55;
}

.pressings-triptych__case {
  position: relative;
  display: grid;
  gap: clamp(16px, 2.2vw, 26px);
  padding: clamp(28px, 3.4vw, 44px) clamp(24px, 3vw, 42px) clamp(26px, 3.2vw, 40px);
  border: 1px solid var(--pt-frame);
  background:
    radial-gradient(ellipse at 50% 0%, rgba(216, 255, 106, .04), transparent 56%),
    radial-gradient(ellipse at 50% 100%, rgba(255, 118, 95, .03), transparent 60%),
    linear-gradient(180deg, rgba(20, 24, 36, .55), rgba(14, 18, 28, .72));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 36px 96px -32px rgba(0, 0, 0, .62);
}

.pressings-triptych__case::before,
.pressings-triptych__case::after {
  content: '';
  position: absolute;
  pointer-events: none;
}

.pressings-triptych__case::before {
  inset: 6px;
  border: 1px dashed rgba(146, 186, 255, .08);
}

.pressings-triptych__case::after {
  inset: 14px;
  border: 1px solid rgba(243, 236, 214, .03);
}

.pressings-triptych__case-plate {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
}

.pressings-triptych__case-plate-rule {
  height: 1px;
  background: linear-gradient(to right, transparent, var(--pt-rule), transparent);
}

.pressings-triptych__case-plate-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: var(--pt-tone);
  opacity: .8;
}

.pressings-triptych__case-plate-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(216, 255, 106, .07);
}

.app--voice-quiet .pressings-triptych__case-plate-dot { box-shadow: 0 0 0 3px rgba(155, 188, 255, .1); }
.app--voice-human .pressings-triptych__case-plate-dot { box-shadow: 0 0 0 3px rgba(240, 110, 91, .1); }
.app--voice-bold .pressings-triptych__case-plate-dot { box-shadow: 0 0 0 3px rgba(216, 240, 106, .12); }

.pressings-triptych__case-rule {
  display: block;
  width: 100%;
  height: 6px;
  color: var(--pt-rule);
}

.pressings-triptych__case-rule svg {
  width: 100%;
  height: 100%;
  display: block;
}

.pressings-triptych__rows {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(8px, 1.2vw, 14px);
  position: relative;
  z-index: 1;
}

.pressings-triptych__case-foot {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--ink-mist);
  opacity: .7;
}

.pressings-triptych__case-foot-mark {
  width: 16px;
  height: 1px;
  background: linear-gradient(to right, currentColor, transparent);
}

.pressings-triptych__case-foot-mark--alt {
  background: linear-gradient(to left, currentColor, transparent);
}

/* The single pressing card. Three of these live in the stack: one expanded
   (active) and two compressed (ghosts). Position is dictated by the order
   in the DOM, which we re-order via the .is-active class. */

/* Each pressing is now a single horizontal row in the case.
   Three rows stacked vertically; the active row is full width and
   full-color; the inactive rows are muted and slightly compressed. */

.pressing-row {
  --r-tone: var(--paper);
  --r-edge: rgba(243, 236, 214, .12);
  --r-shadow: rgba(0, 0, 0, .35);
  --r-paper: #1a1d29;
  --r-paper-2: #232636;
  position: relative;
  display: grid;
  grid-template-columns: minmax(150px, 1.05fr) minmax(0, 2.6fr) minmax(96px, .8fr);
  align-items: center;
  gap: clamp(16px, 2.2vw, 32px);
  width: 100%;
  padding: clamp(22px, 2.6vw, 34px) clamp(20px, 2.6vw, 36px);
  border: 1px solid var(--r-edge);
  border-radius: 1px;
  background:
    linear-gradient(180deg, var(--r-paper), var(--r-paper-2));
  box-shadow:
    inset 0 0 0 1px rgba(243, 236, 214, .02),
    0 12px 28px -16px var(--r-shadow);
  color: var(--paper);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    transform .55s var(--ease-out),
    opacity .45s var(--ease-out),
    box-shadow .55s var(--ease-out),
    border-color .45s var(--ease-out),
    filter .45s var(--ease-out);
  -webkit-tap-highlight-color: transparent;
  isolation: isolate;
}

.pressing-row:hover,
.pressing-row:focus-visible {
  outline: none;
}

.pressing-row::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 0% 0%, var(--r-tone), transparent 36%),
    radial-gradient(ellipse at 100% 100%, var(--r-tone), transparent 42%);
  opacity: 0;
  transition: opacity .5s var(--ease-out);
  pointer-events: none;
  mix-blend-mode: screen;
  z-index: 0;
}

.pressing-row:hover::before {
  opacity: .08;
}

.pressing-row__head {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
}

.pressing-row__head-letter {
  display: inline-grid;
  place-items: center;
  width: clamp(28px, 2.6vw, 34px);
  height: clamp(28px, 2.6vw, 34px);
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.2vw, 16px);
  letter-spacing: 0;
  color: var(--r-tone);
  grid-row: span 2;
}

.pressing-row__head-name {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(17px, 1.6vw, 21px);
  letter-spacing: -.014em;
  text-transform: none;
  color: var(--paper);
  line-height: 1.05;
  white-space: nowrap;
}

.pressing-row__head-rule {
  display: block;
  width: 100%;
  height: 1px;
  background: currentColor;
  opacity: .35;
  grid-column: 2;
}

.pressing-row__head-tag {
  font-family: var(--mono);
  font-size: clamp(9px, .8vw, 10.5px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--ink-mist);
  grid-column: 2;
  line-height: 1.15;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: .85;
}

.pressing-row__line {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: clamp(4px, .8vw, 12px);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  line-height: 1.02;
  color: var(--paper);
  letter-spacing: -.014em;
  text-align: left;
}

.pressing-row__line em {
  font-style: inherit;
  font-weight: inherit;
  color: inherit;
}

.pressing-row__line.is-upper {
  text-transform: uppercase;
  font-family: var(--sans);
  font-style: normal;
  font-weight: 850;
  letter-spacing: -.05em;
}

.pressing-row__phrase {
  display: inline-block;
  font-style: inherit;
  font-weight: inherit;
  color: inherit;
  font-size: clamp(22px, 3.2vw, 38px);
  line-height: 1.02;
}

.pressing-row__phrase.is-upper {
  font-size: clamp(20px, 3vw, 36px);
}

.pressing-row__phrase--ghost {
  font-size: clamp(20px, 2.8vw, 32px);
  color: var(--mist);
}

.pressing-row__question {
  display: inline-block;
  font-family: inherit;
  font-style: inherit;
  font-weight: inherit;
  color: var(--r-tone);
  margin-left: .04em;
}

.pressing-row__question.is-upper {
  color: inherit;
}

.pressing-row__now {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  color: var(--ink-mist);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
  white-space: nowrap;
}

.pressing-row.is-active .pressing-row__now {
  color: var(--r-tone);
}

.pressing-row__now-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, .05);
  animation: pressingsRowPulse 2.4s ease-in-out infinite;
}

.pressing-row:not(.is-active) .pressing-row__now-dot { display: none; }

.pressing-row__now-tag {
  display: inline-block;
  padding: 4px 10px;
  border: 1px solid currentColor;
  border-radius: 999px;
  opacity: .65;
  transition: opacity .35s var(--ease), color .35s var(--ease);
}

.pressing-row:hover .pressing-row__now-tag,
.pressing-row:focus-visible .pressing-row__now-tag {
  opacity: 1;
}

@keyframes pressingsRowPulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: .55; transform: scale(.82); }
}

/* Active pressing: full color, lifted */

.pressing-row.is-active {
  --r-paper: #1f2230;
  --r-paper-2: #161926;
  --r-edge: rgba(216, 240, 106, .24);
  --r-shadow: rgba(0, 0, 0, .55);
  cursor: default;
  border-color: rgba(243, 236, 214, .22);
  box-shadow:
    inset 0 0 0 1px rgba(243, 236, 214, .04),
    0 24px 48px -22px rgba(0, 0, 0, .55),
    0 0 0 1px rgba(255, 255, 255, .015);
}

.app--voice-quiet .pressing-row.is-active { --r-edge: rgba(155, 188, 255, .38); }
.app--voice-human .pressing-row.is-active { --r-edge: rgba(240, 110, 91, .42); }
.app--voice-bold .pressing-row.is-active { --r-edge: rgba(216, 240, 106, .44); }

.pressing-row.is-active::before {
  opacity: .04;
}

/* Inactive (ghost) pressings: muted, slightly compressed */

.pressing-row:not(.is-active) {
  --r-paper: #14161f;
  --r-paper-2: #181a25;
  --r-edge: rgba(243, 236, 214, .06);
  --r-shadow: rgba(0, 0, 0, .25);
  opacity: .62;
  filter: saturate(.7) brightness(.94);
}

.pressing-row:not(.is-active):hover,
.pressing-row:not(.is-active):focus-visible {
  opacity: 1;
  filter: saturate(1) brightness(1.02);
  border-color: rgba(243, 236, 214, .22);
}

.pressing-row:not(.is-active) .pressing-row__line {
  color: var(--mist);
}

/* Voice tone */

.pressing-row--quiet { --r-tone: var(--blue); }
.pressing-row--human { --r-tone: var(--coral); }
.pressing-row--bold { --r-tone: var(--acid); }
/* The interactive word tokens live inside the active pressing.
   Each token is a real button with a hand-drawn caret beneath. */

.pressings-token {
  position: relative;
  display: inline-flex;
  align-items: baseline;
  gap: .04em;
  padding: 0 .04em .12em;
  font-family: inherit;
  font-style: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  color: inherit;
  background: transparent;
  cursor: pointer;
  transition: color .35s var(--ease), transform .35s var(--ease);
}

.pressings-token__text {
  position: relative;
  z-index: 1;
}

.pressings-token__caret {
  position: absolute;
  left: -.04em;
  right: -.04em;
  bottom: -.1em;
  height: 10px;
  width: calc(100% + .08em);
  color: var(--s-tone);
  pointer-events: none;
  opacity: 0;
  transform: translateY(2px);
  transition: opacity .4s var(--ease), transform .45s var(--ease);
}

.pressings-token__caret svg {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}

.pressings-token.is-hover .pressings-token__caret,
.pressings-token.is-selected .pressings-token__caret {
  opacity: 1;
  transform: translateY(0);
}

.pressings-token.is-hover {
  color: var(--s-tone);
}

.pressings-token.is-selected {
  color: var(--s-tone);
}

.pressings-token.is-selected::after {
  content: '';
  position: absolute;
  left: -.04em;
  right: -.04em;
  bottom: -.16em;
  height: 1px;
  background: currentColor;
  opacity: .35;
}

.pressings-token:focus-visible {
  outline: 2px solid var(--s-tone);
  outline-offset: 4px;
  border-radius: 1px;
}

/* Each row slides in on mount. Stagger so they read as a
   sequence being set down, not a flash of three rows. */

.pressings-triptych .pressing-row {
  animation: pressingsRowIn .65s var(--ease-out) backwards;
}

.pressings-triptych .pressing-row--quiet { animation-delay: .05s; }
.pressings-triptych .pressing-row--human { animation-delay: .18s; }
.pressings-triptych .pressing-row--bold { animation-delay: .31s; }

@keyframes pressingsRowIn {
  0% { opacity: 0; transform: translateX(-12px); filter: blur(2px); }
  100% { opacity: 1; transform: translateX(0); filter: blur(0); }
}

.pressings-triptych .pressing-row.is-active {
  animation: pressingsRowInActive .75s var(--ease-out) backwards;
}

@keyframes pressingsRowInActive {
  0% { opacity: 0; transform: translateX(-16px); filter: blur(2px); }
  60% { opacity: 1; filter: brightness(1.05); }
  100% { opacity: 1; transform: translateX(0); filter: brightness(1); }
}

/* When voice changes, the previously active pressing recedes and the
   newly active pressing steps forward. */

.app--voice-quiet .pressing-row.is-active,
.app--voice-human .pressing-row.is-active,
.app--voice-bold .pressing-row.is-active {
  animation: pressingsRowActiveSettle .55s var(--ease-out);
}

@keyframes pressingsRowActiveSettle {
  0% { transform: scale(.985); filter: brightness(1.05); }
