.hero__brief-keymark:hover,
.hero__brief-keymark:focus-visible {
  border-color: var(--line);
  background: rgba(20, 28, 42, .55);
  outline: none;
}

.hero__brief-keymark:hover::before,
.hero__brief-keymark:focus-visible::before {
  opacity: .08;
}

.hero__brief-keymark.is-hover::before {
  opacity: .12;
}

.hero__brief-keymark.is-active {
  border-color: color-mix(in srgb, var(--key-tone) 38%, transparent);
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--key-tone) 9%, transparent),
      color-mix(in srgb, var(--key-tone) 4%, transparent));
  transform: translateX(2px);
}

.hero__brief-keymark.is-active::before {
  opacity: .14;
}

.hero__brief-keymark-glyph {
  display: inline-grid;
  place-items: center;
