}

.hero__brief-keymark-caret {
  display: inline-grid;
  place-items: center;
  width: clamp(56px, 5.4vw, 80px);
  height: 8px;
  color: var(--line);
  opacity: 0;
  transform: translateY(-2px);
  transition: opacity .45s var(--ease), transform .5s var(--ease-spring), color .4s var(--ease);
}

.hero__brief-keymark-caret svg {
