/* ────────────────────────────────────────────────────────────
   ITERATION 292 · SPREAD RIBBON · A BROADSIDE FRONTISPIECE THAT
   ANCHORS THE PAGE.

   The page opens with the sticky header and then dives directly
   into the press handwheel. There is no single, calm identifier
   that names the broadside as one composed object. This ribbon
   gives the page a frontispiece: a thin hand-set identifier
   (m³ press · an open folio, set in three voices), a delicate
   fleuron, and a quiet reading trace that maps where the reader
   is across the folios.

   The whole thing reads as one printed sheet — not a header
   stack — and ties the broadside together at a glance.
   ──────────────────────────────────────────────────────────── */

.spread-ribbon {
  --ribbon-tone: var(--coral);
  --ribbon-grain: none;
  --ribbon-rule: currentColor;
  --ribbon-track-count: 11;
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: stretch;
  gap: clamp(10px, 1.4vw, 16px);
  width: min(100%, 1180px);
  margin: clamp(28px, 3.6vw, 52px) auto clamp(8px, 1vw, 14px);
  padding: clamp(14px, 1.8vw, 22px) clamp(18px, 2.4vw, 30px) clamp(14px, 1.8vw, 20px);
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--paper);
  background:
    linear-gradient(180deg, rgba(28, 36, 52, .38), rgba(14, 20, 32, .6)),
    radial-gradient(circle at 50% 0%, rgba(146, 186, 255, .06), transparent 70%);
  font-family: var(--sans);
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 22px 60px -34px rgba(0, 0, 0, .4);
  transition: border-color .55s var(--ease), color .55s var(--ease), background .55s var(--ease);
  isolation: isolate;
  opacity: 0;
  transform: translateY(8px);
  animation: spreadRibbonArrive .9s var(--ease-out) .05s forwards;
}

.spread-ribbon--quiet { --ribbon-tone: var(--blue); }
.spread-ribbon--human { --ribbon-tone: var(--coral); }
.spread-ribbon--bold { --ribbon-tone: var(--acid); }

.spread-ribbon::before {
  content: '';
  position: absolute;
  inset: 5px;
  border: 1px dashed rgba(146, 186, 255, .08);
  border-radius: 1px;
  pointer-events: none;
  opacity: .65;
  z-index: 0;
}

.spread-ribbon__defs {
  position: absolute;
  inset: 0;
  width: 0;
  height: 0;
  pointer-events: none;
  visibility: hidden;
}

.spread-ribbon__crop {
  position: absolute;
  width: 12px;
  height: 12px;
  color: var(--ribbon-tone);
  pointer-events: none;
  opacity: .55;
  z-index: 1;
}

.spread-ribbon__crop::before,
.spread-ribbon__crop::after {
  content: '';
  position: absolute;
  background: currentColor;
}

.spread-ribbon__crop::before { width: 8px; height: 1px; }
.spread-ribbon__crop::after { width: 1px; height: 8px; }

.spread-ribbon__crop--tl { top: 6px; left: 6px; }
.spread-ribbon__crop--tl::before { top: 0; left: 0; }
.spread-ribbon__crop--tl::after { top: 0; left: 0; }

.spread-ribbon__crop--tr { top: 6px; right: 6px; }
.spread-ribbon__crop--tr::before { top: 0; right: 0; }
.spread-ribbon__crop--tr::after { top: 0; right: 0; }

.spread-ribbon__crop--bl { bottom: 6px; left: 6px; }
.spread-ribbon__crop--bl::before { bottom: 0; left: 0; }
.spread-ribbon__crop--bl::after { bottom: 0; left: 0; }

.spread-ribbon__crop--br { bottom: 6px; right: 6px; }
.spread-ribbon__crop--br::before { bottom: 0; right: 0; }
.spread-ribbon__crop--br::after { bottom: 0; right: 0; }

.spread-ribbon__rule {
  position: relative;
  display: block;
  height: 5px;
  color: var(--ribbon-tone);
  z-index: 1;
}

.spread-ribbon__rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.spread-ribbon__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: spreadRibbonRuleDraw 1.1s var(--ease-out) .35s forwards;
}

.spread-ribbon__rule-bead {
  opacity: 0;
  animation: spreadRibbonBeadFade .5s var(--ease-out) 1.05s forwards;
}

.spread-ribbon__row {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(10px, 1.4vw, 18px);
  width: 100%;
  padding: clamp(6px, .8vw, 12px) 0;
  z-index: 1;
}

.spread-ribbon__cell {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  color: var(--paper);
  opacity: 0;
  animation: spreadRibbonFade .55s var(--ease-out) .5s forwards;
}

.spread-ribbon__cell--press {
  color: var(--paper);
  animation-delay: .45s;
}

.spread-ribbon__cell--voice {
  animation-delay: .55s;
}

.spread-ribbon__cell--word {
  animation-delay: .65s;
}

.spread-ribbon__cell--date {
  animation-delay: .75s;
}

.spread-ribbon__cell--mark {
  color: var(--ribbon-tone);
  font-family: var(--serif);
  font-size: clamp(18px, 1.6vw, 22px);
  opacity: .6;
  animation-delay: .8s;
  letter-spacing: 0;
}

.spread-ribbon__cell-mark {
  display: inline-block;
  color: var(--ribbon-tone);
  font-family: var(--serif);
  font-size: clamp(18px, 1.6vw, 22px);
  letter-spacing: 0;
  line-height: 1;
  transform: translateY(-1px);
  opacity: .65;
}

.spread-ribbon__cell-stack {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  min-width: 0;
}

.spread-ribbon__cell-key {
  font-family: var(--mono);
  font-size: clamp(7.5px, .68vw, 8.5px);
  font-weight: 600;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: var(--muted);
}

.spread-ribbon__cell em {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(12.5px, 1.08vw, 14.5px);
  letter-spacing: -.005em;
  color: var(--paper);
  text-transform: none;
  line-height: 1.05;
}

.spread-ribbon__cell-letter {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .92vw, 13px);
  font-weight: 600;
  letter-spacing: 0;
  line-height: 1;
  text-transform: none;
}

.spread-ribbon__cell-letter--quiet { color: var(--blue); }
.spread-ribbon__cell-letter--human { color: var(--coral); }
.spread-ribbon__cell-letter--bold  { color: var(--acid); }

.spread-ribbon__cell-mark-tag {
  display: inline-block;
  padding: 1px 5px 2px;
  border: 1px solid color-mix(in srgb, var(--ribbon-tone) 40%, transparent);
  border-radius: 1px;
  color: var(--ribbon-tone);
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(7.5px, .68vw, 8.5px);
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.spread-ribbon__cell-sep {
  color: var(--ribbon-tone);
  opacity: .55;
}

.spread-ribbon__fleuron {
  display: block;
  width: clamp(60px, 6vw, 84px);
  color: var(--ribbon-tone);
  opacity: 0;
  animation: spreadRibbonFade .55s var(--ease-out) .6s forwards;
}

.spread-ribbon__fleuron--alt {
  animation-delay: .7s;
}

.spread-ribbon__fleuron svg {
  display: block;
  width: 100%;
  height: auto;
}

.spread-ribbon__trace {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  justify-items: stretch;
  gap: clamp(6px, .8vw, 10px);
  width: 100%;
  padding: clamp(6px, .8vw, 10px) clamp(10px, 1.4vw, 18px);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  opacity: 0;
  animation: spreadRibbonFade .55s var(--ease-out) 1s forwards;
}

.spread-ribbon__trace-eyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, 1vw, 12px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(9px, .76vw, 10.5px);
  font-weight: 600;
  letter-spacing: .2em;
  text-transform: uppercase;
}

.spread-ribbon__trace-eyebrow-mark {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--ribbon-tone);
  opacity: .85;
}

.spread-ribbon__trace-eyebrow em {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(11px, .92vw, 13px);
  letter-spacing: 0;
  text-transform: none;
  color: var(--paper);
  opacity: .9;
}

.spread-ribbon__trace-eyebrow-folio {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border: 1px solid var(--line);
  border-radius: 99px;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .92vw, 13px);
  letter-spacing: 0;
  text-transform: none;
  transition: color .5s var(--ease), border-color .5s var(--ease);
}

.spread-ribbon__trace-eyebrow-num {
  color: var(--ribbon-tone);
  font-style: italic;
}

.spread-ribbon__trace-track {
  position: relative;
  display: grid;
  grid-template-columns: repeat(var(--ribbon-track-count, 10), minmax(0, 1fr));
  align-items: center;
  gap: 4px;
  margin: 0;
  padding: clamp(8px, 1vw, 12px) 0 clamp(6px, .8vw, 10px);
  list-style: none;
  width: 100%;
  background-image: linear-gradient(to right, transparent 0, var(--line) 4%, var(--line) 96%, transparent 100%);
  background-position: 0 50%;
  background-size: 100% 1px;
  background-repeat: no-repeat;
}

.spread-ribbon__trace-cell {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  color: var(--ink-mist);
  transition: color .5s var(--ease);
}

.spread-ribbon__trace-bead {
  position: relative;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 1px solid currentColor;
  background: var(--night);
  transition: background .55s var(--ease), border-color .55s var(--ease), transform .55s var(--ease-spring), box-shadow .55s var(--ease);
}

.spread-ribbon__trace-cell.is-passed .spread-ribbon__trace-bead {
  background: var(--ribbon-tone);
  border-color: var(--ribbon-tone);
  box-shadow: 0 0 0 3px rgba(146, 186, 255, .06);
}

.spread-ribbon__trace-cell.is-current .spread-ribbon__trace-bead {
  background: var(--ribbon-tone);
  border-color: var(--ribbon-tone);
  transform: scale(1.4);
  box-shadow: 0 0 0 5px rgba(216, 240, 106, .14);
}

.spread-ribbon--quiet .spread-ribbon__trace-cell.is-current .spread-ribbon__trace-bead {
  box-shadow: 0 0 0 5px rgba(155, 188, 255, .14);
}

.spread-ribbon--human .spread-ribbon__trace-cell.is-current .spread-ribbon__trace-bead {
  box-shadow: 0 0 0 5px rgba(240, 110, 91, .14);
}

.spread-ribbon__trace-tick {
  display: block;
  width: 1px;
  height: 6px;
  background: currentColor;
  opacity: .25;
  margin-top: 3px;
  transition: background .5s var(--ease), opacity .5s var(--ease);
}

.spread-ribbon__trace-cell.is-passed .spread-ribbon__trace-tick,
.spread-ribbon__trace-cell.is-current .spread-ribbon__trace-tick {
  background: var(--ribbon-tone);
  opacity: .7;
}

.spread-ribbon__trace-label {
  position: absolute;
  top: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  color: var(--muted);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(9px, .76vw, 11px);
  letter-spacing: -.002em;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity .35s var(--ease), color .35s var(--ease);
}

.spread-ribbon__trace-cell:hover .spread-ribbon__trace-label,
.spread-ribbon__trace-cell.is-current .spread-ribbon__trace-label {
  opacity: 1;
}

.spread-ribbon__trace-cell.is-current .spread-ribbon__trace-label {
  color: var(--paper);
}

.spread-ribbon__trace-now {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.1vw, 14.5px);
  letter-spacing: -.005em;
}

.spread-ribbon__trace-now-tag {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9.5px;
  font-style: normal;
  letter-spacing: .22em;
  text-transform: uppercase;
  font-weight: 600;
}

.spread-ribbon__trace-now-text {
  color: var(--paper);
  font-style: italic;
}

.spread-ribbon__trace-now-count {
  color: var(--ribbon-tone);
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(10.5px, .92vw, 12px);
  letter-spacing: .1em;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 1px;
}

.spread-ribbon__trace-now-count span[aria-hidden] {
  opacity: .55;
  margin: 0 1px;
}

@keyframes spreadRibbonArrive {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes spreadRibbonRuleDraw {
  0% { stroke-dashoffset: 100; opacity: 0; }
  12% { opacity: .85; }
  100% { stroke-dashoffset: 0; opacity: .85; }
}

@keyframes spreadRibbonBeadFade {
  0% { opacity: 0; transform: translateY(1px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes spreadRibbonFade {
  0% { opacity: 0; transform: translateY(2px); }
  100% { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .spread-ribbon {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .spread-ribbon__rule-stroke,
  .spread-ribbon__rule-bead,
  .spread-ribbon__cell,
  .spread-ribbon__cell--mark,
  .spread-ribbon__fleuron,
  .spread-ribbon__trace {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }
}

@media (max-width: 880px) {
  .spread-ribbon {
    padding: clamp(12px, 1.6vw, 18px) clamp(14px, 2vw, 22px) clamp(10px, 1.4vw, 16px);
  }
  .spread-ribbon__row {
    grid-template-columns: auto minmax(0, 1fr) auto minmax(0, 1fr) auto;
    row-gap: clamp(6px, .8vw, 10px);
  }
  .spread-ribbon__cell--word,
  .spread-ribbon__cell--date,
  .spread-ribbon__cell--mark,
  .spread-ribbon__fleuron--alt {
    display: none;
  }
  .spread-ribbon__trace-label { display: none; }
}

@media (max-width: 720px) {
  .spread-ribbon__row {
    grid-template-columns: minmax(0, 1fr);
    row-gap: clamp(6px, .8vw, 10px);
  }
  .spread-ribbon__fleuron { display: none; }
  .spread-ribbon__cell { justify-content: center; }
  .spread-ribbon__cell-stack { align-items: center; }
}

@media (max-width: 540px) {
  .spread-ribbon__trace-now-text {
    font-size: 12px;
  }
}

/* ────────────────────────────────────────────────────────────
   ITERATION 290 · FOLIO OPENING · A THIN, DECISIVE BAND BETWEEN
   THE TITLE PAGE AND THE PRESSINGS TRIPTYCH.

   The title page and the triptych were two confident elements
   stacked without a clear connection. This opening band sits
   between them as a single hand-printed divider: a folio marker,
   a typesetting ornament, and three voice / word / date cells
   laid out as one calm sheet. It makes the two pieces above
   and below it feel like the same spread.

   It arrives quietly (a brief settle) and the rule draws from
   the center outward. Reduced motion holds it still.
   ──────────────────────────────────────────────────────────── */

/* ────────────────────────────────────────────────────────────
   ITERATION 295 · FOLIO OPENING AS A PRESS INSCRIPTION.

   The old FolioOpening was a busy 3-cell plate (set in / marked
   at / set today) that competed with the title page above. It
   has been re-authored as a single, deliberate press inscription:
   a typesetter's asterism, one composed italic sentence, and a
   quiet signature line. The composition reads as a continuation
   of the broadside above — a hand-set passage that hands the
   reader off to the title line below.
   ──────────────────────────────────────────────────────────── */

.folio-opening {
  --opening-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: clamp(10px, 1.1vw, 16px);
  width: min(100%, 920px);
  margin: clamp(14px, 1.6vw, 28px) auto clamp(28px, 3.4vw, 48px);
  padding: clamp(24px, 2.6vw, 38px) clamp(28px, 4vw, 56px) clamp(22px, 2.4vw, 34px);
  color: var(--paper);
  isolation: isolate;
  opacity: 0;
  transform: translateY(6px);
  animation: folioOpeningIn .9s var(--ease-out) .25s forwards;
}

.folio-opening::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: clamp(240px, 60%, 540px);
  height: 1px;
  background:
    linear-gradient(to right,
      transparent 0%,
      color-mix(in srgb, var(--opening-tone) 28%, transparent) 50%,
      transparent 100%);
  transform: translate(-50%, -50%) scaleX(.5);
  opacity: .6;
  pointer-events: none;
  z-index: -1;
}

@keyframes folioOpeningIn {
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .folio-opening {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

.folio-opening__asterism {
  display: grid;
  justify-items: center;
  gap: clamp(4px, .4vw, 6px);
  color: var(--opening-tone);
  opacity: .85;
}

.folio-opening__asterism svg {
  display: block;
  width: clamp(72px, 8vw, 108px);
  height: auto;
  color: inherit;
}

.folio-opening__asterism-cluster {
  opacity: .9;
  transition: transform .55s var(--ease-spring);
}

.folio-opening__asterism-cluster--a { transform-origin: 14px 16px; }
.folio-opening__asterism-cluster--b { transform-origin: 60px 16px; }
.folio-opening__asterism-cluster--c { transform-origin: 106px 16px; }

.folio-opening--word-m3 .folio-opening__asterism-cluster--a { transform: scale(1.18); }
.folio-opening--word-good .folio-opening__asterism-cluster--b { transform: scale(1.22); }
.folio-opening--word-yet .folio-opening__asterism-cluster--c { transform: scale(1.18); }

.folio-opening__asterism-tag {
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9.5px);
  letter-spacing: .32em;
  text-transform: uppercase;
  color: var(--mist);
  opacity: .8;
  white-space: nowrap;
}

.folio-opening__inscription {
  position: relative;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: clamp(10px, 1.2vw, 18px);
  margin: 0;
  max-width: 56ch;
  text-align: center;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(21px, 2.1vw, 30px);
  line-height: 1.3;
  letter-spacing: -.014em;
  color: var(--paper);
  font-feature-settings: 'kern' 1, 'liga' 1, 'onum' 1, 'dlig' 1;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .12);
}

.app--voice-quiet .folio-opening__inscription {
  font-style: italic;
  font-weight: 400;
}

.app--voice-human .folio-opening__inscription {
  font-style: italic;
  font-weight: 500;
}

.app--voice-bold .folio-opening__inscription {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 800;
  letter-spacing: -.018em;
  text-transform: uppercase;
  font-size: clamp(18px, 1.7vw, 24px);
}

.folio-opening__inscription em {
  font-style: inherit;
}

.folio-opening__inscription-mark {
  position: relative;
  top: -.12em;
  font-family: var(--serif);
  font-style: normal;
  font-size: clamp(20px, 1.7vw, 26px);
  color: var(--opening-tone);
  opacity: .55;
  transition: color .55s var(--ease), opacity .55s var(--ease), transform .55s var(--ease-spring);
}

.folio-opening__inscription-mark--trail {
  top: -.12em;
}

.folio-opening__inscription:hover .folio-opening__inscription-mark {
  opacity: .9;
  color: var(--opening-tone);
}

.folio-opening__inscription-mark--lead { transform: translateX(0); }
.folio-opening__inscription-mark--trail { transform: translateX(0); }

.folio-opening__inscription:hover .folio-opening__inscription-mark--lead { transform: translateX(-2px); }
.folio-opening__inscription:hover .folio-opening__inscription-mark--trail { transform: translateX(2px); }

.folio-opening__inscription-line {
  font-style: inherit;
  color: var(--paper);
  text-wrap: balance;
}

.folio-opening__inscription-wait {
  position: relative;
  color: var(--opening-tone);
  font-style: inherit;
  white-space: nowrap;
}

.folio-opening__inscription-wait::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -.18em;
  height: 1px;
  background:
    linear-gradient(to right,
      transparent 0%,
      color-mix(in srgb, var(--opening-tone) 55%, transparent) 30%,
      color-mix(in srgb, var(--opening-tone) 55%, transparent) 70%,
      transparent 100%);
  opacity: .5;
  transform: scaleX(0);
  transform-origin: center;
  transition: transform .65s var(--ease-out) .15s;
}

.folio-opening__inscription:hover .folio-opening__inscription-wait::after,
.folio-opening.is-in-view .folio-opening__inscription-wait::after {
  transform: scaleX(1);
}

.folio-opening__signature {
  display: grid;
  justify-items: center;
  gap: clamp(6px, .6vw, 10px);
  width: min(100%, 420px);
  margin-top: clamp(2px, .4vw, 6px);
  color: var(--mist);
}

.folio-opening__signature-stroke {
  display: block;
  width: 100%;
  height: 14px;
  color: var(--opening-tone);
  opacity: .55;
}

.folio-opening__signature-path {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: folioOpeningSigDraw 1.1s var(--ease-out) .55s forwards;
}

.folio-opening__signature-bead {
  opacity: 0;
  animation: folioOpeningBeadIn .35s var(--ease-spring) 1.45s forwards;
}

@keyframes folioOpeningSigDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes folioOpeningBeadIn {
  0% { opacity: 0; transform: scale(0); }
  100% { opacity: 1; transform: scale(1); }
}

.folio-opening__signature-meta {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: center;
  gap: clamp(4px, .5vw, 8px);
  font-family: var(--mono);
  font-size: clamp(9px, .8vw, 10.5px);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}

.folio-opening__signature-meta em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
  text-transform: lowercase;
  color: var(--mist);
}

.folio-opening__signature-voice {
  color: var(--opening-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
  text-transform: lowercase;
  transition: color .45s var(--ease);
}

.folio-opening__signature-word {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
  text-transform: lowercase;
}

@media (prefers-reduced-motion: reduce) {
  .folio-opening__signature-path {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }
  .folio-opening__signature-bead {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .folio-opening__inscription-wait::after {
    transition: none !important;
    transform: scaleX(1) !important;
  }
}

@media (max-width: 720px) {
  .folio-opening {
    padding: clamp(16px, 2vw, 22px) clamp(18px, 2.4vw, 28px);
    gap: clamp(8px, 1vw, 12px);
  }

  .folio-opening__inscription {
    font-size: clamp(18px, 5.4vw, 24px);
    line-height: 1.34;
  }

  .folio-opening__signature-meta {
    font-size: clamp(8.5px, 2.4vw, 10px);
  }
}

@media (max-width: 480px) {
  .folio-opening__inscription {
    flex-wrap: wrap;
    gap: clamp(6px, 2vw, 12px);
  }

  .folio-opening__inscription-mark {
    font-size: clamp(16px, 4vw, 20px);
  }

  .folio-opening__signature-meta {
    white-space: normal;
  }
}

/* ────────────────────────────────────────────────────────────
   ITERATION 295 · MARGINALIUM PRESS · A HAND-WRITTEN EDITORIAL
   NOTE.

   The editor's note now closes with a small hand-written
   marginalium — a pinned, hand-set note from the press that
   speaks directly to the reader about how to read the page.
   It uses a single tiny pin ornament, a leading quote glyph,
   a quiet pencil line, and a small signature. The whole
   composition reads as a note tucked into the margin, not
   as another UI card.
   ──────────────────────────────────────────────────────────── */

.marginalium-press {
  --marginalium-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-areas:
    'pin note'
    'tack pencil';
  align-items: start;
  column-gap: clamp(12px, 1.4vw, 22px);
  row-gap: clamp(4px, .6vw, 10px);
  max-width: 880px;
  margin: clamp(8px, 1.2vw, 16px) auto clamp(4px, .6vw, 8px);
  padding: clamp(18px, 2vw, 28px) clamp(18px, 2vw, 26px) clamp(12px, 1.4vw, 18px) clamp(8px, 1vw, 14px);
  color: var(--paper);
  isolation: isolate;
  opacity: 0;
  transform: translateY(6px) rotate(-.45deg);
  transform-origin: 50% 50%;
  animation: marginaliumPressIn .85s var(--ease-out) .4s forwards;
}

.marginalium-press::before {
  content: '';
  position: absolute;
  inset: 4px;
  border: 1px dashed color-mix(in srgb, var(--marginalium-tone) 22%, transparent);
  border-radius: 1px;
  pointer-events: none;
  opacity: .55;
  z-index: -1;
}

.marginalium-press::after {
  content: '';
  position: absolute;
  top: -8px;
  left: 8%;
  right: 8%;
  height: 14px;
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--paper) 6%, transparent) 0%,
      transparent 100%);
  border-radius: 50% 50% 0 0;
  pointer-events: none;
  opacity: .35;
  z-index: -1;
}

@keyframes marginaliumPressIn {
  0% { opacity: 0; transform: translateY(10px) rotate(-.45deg); }
  100% { opacity: 1; transform: translateY(0) rotate(-.45deg); }
}

@media (prefers-reduced-motion: reduce) {
  .marginalium-press {
    animation: none !important;
    opacity: 1 !important;
    transform: rotate(-.45deg) !important;
  }
}

.marginalium-press__pin {
  grid-area: pin;
  display: grid;
  place-items: center;
  width: clamp(22px, 2.2vw, 30px);
  height: clamp(22px, 2.2vw, 30px);
  margin-top: clamp(2px, .3vw, 4px);
  color: var(--marginalium-tone);
  filter: drop-shadow(0 2px 1px rgba(0, 0, 0, .3));
  transform: rotate(8deg);
  transition: transform .55s var(--ease-spring);
}

.marginalium-press:hover .marginalium-press__pin {
  transform: rotate(14deg) translateY(-1px);
}

.marginalium-press__pin svg {
  display: block;
  width: 100%;
  height: 100%;
  color: inherit;
}

.marginalium-press__tack {
  grid-area: tack;
  display: grid;
  align-self: end;
  width: clamp(40px, 5vw, 80px);
  height: 10px;
  color: var(--marginalium-tone);
  opacity: .55;
  transform: rotate(8deg);
  transform-origin: 0% 100%;
}

.marginalium-press__tack svg {
  width: 100%;
  height: 100%;
  color: inherit;
}

.marginalium-press__tack-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: marginaliumPressTackDraw 1.1s var(--ease-out) .7s forwards;
}

@keyframes marginaliumPressTackDraw {
  to { stroke-dashoffset: 0; }
}

.marginalium-press__note {
  grid-area: note;
  display: grid;
  grid-template-columns: clamp(18px, 1.6vw, 22px) minmax(0, 1fr);
  column-gap: clamp(8px, 1vw, 14px);
  align-items: start;
  margin: 0;
  padding: 0;
}

.marginalium-press__quote {
  display: grid;
  place-items: start center;
  padding-top: clamp(2px, .3vw, 6px);
  color: var(--marginalium-tone);
  opacity: .75;
}

.marginalium-press__quote svg {
  display: block;
  width: clamp(18px, 1.6vw, 22px);
  height: auto;
  color: inherit;
}

.marginalium-press__body {
  margin: 0;
  padding: 0;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.25vw, 17.5px);
  line-height: 1.5;
  letter-spacing: -.005em;
  color: var(--lead-2);
  font-feature-settings: 'kern' 1, 'liga' 1, 'onum' 1;
  text-wrap: pretty;
}

.marginalium-press__body p {
  margin: 0;
}

.marginalium-press__body em {
  color: var(--paper);
  font-style: italic;
  text-shadow: 0 0 .04em color-mix(in srgb, var(--marginalium-tone) 24%, transparent);
}

.marginalium-press__sign {
  grid-column: 1 / -1;
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: clamp(6px, .8vw, 12px);
  margin-top: clamp(8px, 1vw, 14px);
  padding-top: clamp(6px, .8vw, 10px);
  border-top: 1px dashed var(--line-soft);
  font-family: var(--mono);
  font-size: clamp(8.5px, .75vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.marginalium-press__sign-mark {
  color: var(--marginalium-tone);
  font-family: var(--serif);
  font-size: clamp(15px, 1.3vw, 17px);
  opacity: .75;
}

.marginalium-press__sign-name {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.2vw, 16px);
  letter-spacing: -.005em;
  text-transform: lowercase;
  color: var(--paper);
}

.marginalium-press__sign-rule {
  display: block;
  width: clamp(40px, 5vw, 80px);
  height: 6px;
  color: var(--marginalium-tone);
  opacity: .55;
}

.marginalium-press__sign-rule svg {
  width: 100%;
  height: 100%;
}

.marginalium-press__sign-note {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, .95vw, 13px);
  letter-spacing: -.002em;
  text-transform: lowercase;
  color: var(--mist);
  opacity: .85;
}

.marginalium-press__pencil {
  grid-area: pencil;
  display: grid;
  align-items: center;
  gap: clamp(2px, .3vw, 4px);
  margin-left: clamp(28px, 3vw, 44px);
  color: var(--marginalium-tone);
}

.marginalium-press__pencil svg {
  width: clamp(100px, 14vw, 140px);
  height: 14px;
  color: inherit;
}

.marginalium-press__pencil-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: marginaliumPressPencilDraw 1.2s var(--ease-out) 1s forwards;
}

@keyframes marginaliumPressPencilDraw {
  to { stroke-dashoffset: 0; }
}

.marginalium-press__pencil-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: marginaliumPressPencilBead .35s var(--ease-spring) 2.1s forwards;
}

@keyframes marginaliumPressPencilBead {
  0% { opacity: 0; transform: scale(0); }
  100% { opacity: 1; transform: scale(1); }
}

.marginalium-press__pencil-tag {
  font-family: var(--mono);
  font-size: clamp(8.5px, .75vw, 9.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
  opacity: .85;
  white-space: nowrap;
}

.marginalium-press__pencil-tag span {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .95vw, 13px);
  letter-spacing: -.002em;
  text-transform: lowercase;
  color: var(--mist);
}

.marginalium-press--voice-quiet .marginalium-press__pencil-tag span { color: var(--blue); }
.marginalium-press--voice-human .marginalium-press__pencil-tag span { color: var(--coral); }
.marginalium-press--voice-bold .marginalium-press__pencil-tag span { color: var(--acid); }

@media (prefers-reduced-motion: reduce) {
  .marginalium-press__tack-stroke,
  .marginalium-press__pencil-stroke {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }
  .marginalium-press__pencil-bead {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

@media (max-width: 640px) {
  .marginalium-press {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      'pin'
      'note'
      'pencil';
    padding: clamp(16px, 2vw, 22px) clamp(14px, 2vw, 18px);
  }

  .marginalium-press__tack {
    display: none;
  }

  .marginalium-press__pencil {
    margin-left: 0;
    justify-items: start;
  }
}

/* ────────────────────────────────────────────────────────────
   ITERATION 290 · FOLIO THUMBPRINT · A SMALL DISTINCTIVE
   SIGNATURE AT THE CLOSE OF THE EDITOR'S NOTE.

   The press-imprint-mount used to be a quiet, decorative stamp
   that read like a generic press emblem. The FolioThumbprint
   is a hand-written marginalium — a single line that names the
   voice, the marked word, and the reader (or "the next
   reader"), set beside a small seal that shows the active
   voice-tone. It makes the editorial close feel authored, not
   stamped.

   The seal's rule draws on view; reduced motion holds it.
   ──────────────────────────────────────────────────────────── */

.folio-thumbprint {
  --thumbprint-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(8px, .8vw, 12px);
  margin: clamp(6px, .6vw, 10px) 0 0;
  padding: clamp(14px, 1.6vw, 22px) clamp(18px, 2.2vw, 30px);
  border: 1px solid color-mix(in srgb, var(--thumbprint-tone) 30%, var(--line));
  border-radius: 1px;
  background:
    radial-gradient(ellipse 60% 80% at 8% 50%, color-mix(in srgb, var(--thumbprint-tone) 6%, transparent), transparent 70%),
    linear-gradient(180deg, rgba(20, 26, 38, .32), rgba(12, 16, 26, .5));
  color: var(--paper);
  isolation: isolate;
  opacity: 0;
  transform: translateY(4px);
  animation: folioThumbprintIn .7s var(--ease-out) .25s forwards;
}

.folio-thumbprint::before {
  content: '';
  position: absolute;
  inset: 4px;
  border: 1px dashed color-mix(in srgb, var(--thumbprint-tone) 22%, transparent);
  pointer-events: none;
  opacity: .55;
  z-index: -1;
}

@keyframes folioThumbprintIn {
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .folio-thumbprint {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

.folio-thumbprint__rule {
  position: relative;
  display: block;
  height: 12px;
  color: var(--thumbprint-tone);
  opacity: .85;
}

.folio-thumbprint__rule--lead {
  margin-bottom: clamp(4px, .4vw, 8px);
}

.folio-thumbprint__rule--trail {
  margin-top: clamp(4px, .4vw, 8px);
  opacity: .55;
}

.folio-thumbprint__rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.folio-thumbprint__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: folioThumbprintRuleDraw 1.3s var(--ease-out) .3s forwards;
}

@keyframes folioThumbprintRuleDraw {
  to { stroke-dashoffset: 0; }
}

.folio-thumbprint__rule-bead {
  opacity: 0;
  animation: folioThumbprintBeadIn .35s var(--ease-spring) 1.45s forwards;
}

@keyframes folioThumbprintBeadIn {
  from { opacity: 0; transform: scale(.4); }
  to { opacity: 1; transform: scale(1); }
}

.folio-thumbprint__rule-tag {
  position: absolute;
  inset: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(6px, .8vw, 10px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8.5px, .75vw, 10px);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.folio-thumbprint__rule-tag-text {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, .95vw, 13.5px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--mist);
  opacity: .9;
}

.folio-thumbprint__rule-tag-text em {
  color: var(--thumbprint-tone);
  font-style: italic;
}

.folio-thumbprint__rule-tag-mark {
  display: inline-block;
  width: clamp(18px, 2vw, 28px);
  height: 1px;
  background: currentColor;
  opacity: .65;
}

.folio-thumbprint__rule-tag-mark--alt {
  background: linear-gradient(to left, transparent, currentColor);
}

.folio-thumbprint__body {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(14px, 2vw, 22px);
  padding: clamp(2px, .2vw, 4px) 0;
}

.folio-thumbprint__seal {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(78px, 8vw, 104px);
  height: clamp(78px, 8vw, 104px);
  color: var(--thumbprint-tone);
  flex-shrink: 0;
  transform: rotate(-5deg);
  transition: transform .55s var(--ease-spring), color .5s var(--ease);
}

.folio-thumbprint__seal::after {
  content: '';
  position: absolute;
  inset: clamp(4px, .5vw, 8px);
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: .35;
  pointer-events: none;
}

.folio-thumbprint__seal:hover,
.folio-thumbprint.is-signed .folio-thumbprint__seal {
  transform: rotate(-3deg);
}

.folio-thumbprint__seal svg {
  width: 100%;
  height: 100%;
  display: block;
}

.folio-thumbprint__seal-glyph {
  position: absolute;
  bottom: -6px;
  right: -8px;
  display: inline-grid;
  place-items: center;
  width: clamp(22px, 2.2vw, 28px);
  height: clamp(22px, 2.2vw, 28px);
  border-radius: 999px;
  background: var(--night);
  border: 1px solid currentColor;
  color: var(--thumbprint-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: 0;
  transform: rotate(8deg);
  transition: transform .55s var(--ease-spring), color .5s var(--ease);
}

.folio-thumbprint--word-m3 .folio-thumbprint__seal-glyph { color: var(--acid); }
.folio-thumbprint--word-good .folio-thumbprint__seal-glyph { color: var(--coral); }
.folio-thumbprint--word-yet .folio-thumbprint__seal-glyph { color: var(--blue); }

.folio-thumbprint__copy {
