  letter-spacing: .24em;
  text-transform: uppercase;
}

.folio-thumbprint__copy-eyebrow em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14.5px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--thumbprint-tone);
}

.folio-thumbprint__copy-eyebrow-mark {
  display: inline-block;
  width: 14px;
  height: 1px;
  background: currentColor;
  opacity: .65;
}

.folio-thumbprint__copy-eyebrow-mark--alt {
  background: linear-gradient(to left, transparent, currentColor);
  opacity: .85;
}

.folio-thumbprint__copy-line {
  margin: 0;
  color: var(--lead-2);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.3vw, 18px);
  line-height: 1.55;
  letter-spacing: -.005em;
  text-wrap: pretty;
}

.folio-thumbprint__copy-line em {
  font-style: italic;
  color: var(--paper);
  letter-spacing: -.005em;
}

.folio-thumbprint__copy-voice {
  color: var(--thumbprint-tone);
}

.folio-thumbprint--word-m3 .folio-thumbprint__copy-word { color: var(--acid); }
.folio-thumbprint--word-good .folio-thumbprint__copy-word { color: var(--coral); }
.folio-thumbprint--word-yet .folio-thumbprint__copy-word { color: var(--blue); }

.folio-thumbprint__copy-reader {
