}

.folio-thumbprint__copy-foot {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8.5px, .75vw, 10px);
