/* ────────────────────────────────────────────────────────────
   TITLE LINE · iteration 294
   The headline set as one confident act. A single line of type
   that is the page's central typographic moment: the question
   itself, rendered large in the active voice, with a hand-drawn
   proof mark that travels to the marked word. Three voice tabs
   underneath cycle the headline between quiet cut, human hand,
   and bold signal. Click any word to mark it; click the open
   space to cycle the voice.
   ──────────────────────────────────────────────────────────── */

.titleline {
  --titleline-tone: var(--coral);
  --titleline-ghost: rgba(243, 236, 214, .28);
  --titleline-ghost-strong: rgba(243, 236, 214, .5);
  --titleline-rule: rgba(243, 236, 214, .14);
  --titleline-rule-soft: rgba(243, 236, 214, .06);
  position: relative;
  display: grid;
  gap: clamp(14px, 1.6vw, 22px);
  width: 100%;
  max-width: 1080px;
  margin: 0 auto;
  padding: clamp(20px, 2.6vw, 34px) clamp(22px, 3vw, 44px) clamp(20px, 2.6vw, 30px);
  border: 1px solid rgba(243, 236, 214, .1);
  border-radius: 2px;
  background:
    radial-gradient(ellipse at 50% -10%, color-mix(in srgb, var(--titleline-tone) 18%, transparent), transparent 60%),
    radial-gradient(ellipse at 50% 110%, color-mix(in srgb, var(--titleline-tone) 10%, transparent), transparent 65%),
    linear-gradient(180deg, rgba(28, 30, 42, .62), rgba(14, 16, 24, .78));
  color: var(--paper);
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 38px 92px -42px rgba(0, 0, 0, .62);
  isolation: isolate;
  transition: border-color .55s var(--ease), box-shadow .55s var(--ease);
  animation: titlelineArrive .9s var(--ease-out) .15s backwards;
}

.app--voice-quiet .titleline { --titleline-tone: var(--blue); }
.app--voice-human .titleline { --titleline-tone: var(--coral); }
.app--voice-bold .titleline { --titleline-tone: var(--acid); }

.titleline::before {
  content: '';
  position: absolute;
  inset: 8px;
  border: 1px dashed color-mix(in srgb, var(--titleline-tone) 22%, transparent);
  border-radius: 1px;
  pointer-events: none;
  z-index: 0;
  transition: border-color .55s var(--ease);
}

.titleline__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

@keyframes titlelineArrive {
  0% { opacity: 0; transform: translateY(8px); filter: blur(4px); }
  100% { opacity: 1; transform: translateY(0); filter: blur(0); }
}

@media (prefers-reduced-motion: reduce) {
  .titleline { animation: none !important; opacity: 1 !important; transform: none !important; filter: none !important; }
}

/* — Eyebrow running head above the headline — */

.titleline__eyebrow {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--titleline-ghost-strong);
  opacity: 0;
  animation: titlelineEyebrowIn .6s var(--ease-out) .35s forwards;
}

.titleline__eyebrow-mark {
  display: inline-block;
  width: 5px;
  height: 5px;
  background: var(--titleline-tone);
  transform: rotate(45deg);
  opacity: .75;
}

.titleline__eyebrow-mark--alt { opacity: .4; }

.titleline__eyebrow-cell {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(6px, .7vw, 10px);
}

.titleline__eyebrow-cell em {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
}

.titleline__eyebrow-rule {
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--titleline-tone) 35%, transparent), transparent);
  opacity: .7;
}

.titleline__eyebrow-rule--alt {
  background: linear-gradient(to left, transparent, color-mix(in srgb, var(--titleline-tone) 35%, transparent), transparent);
}

.titleline__eyebrow-voice {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.titleline__eyebrow-voice-letter {
  display: inline-grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .92vw, 12.5px);
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  line-height: 1;
  transition: color .5s var(--ease), border-color .5s var(--ease);
}

.titleline__eyebrow-voice-letter--quiet { color: var(--blue); }
.titleline__eyebrow-voice-letter--human { color: var(--coral); }
.titleline__eyebrow-voice-letter--bold  { color: var(--acid); }

.titleline__eyebrow-voice-stack {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  line-height: 1.05;
}

.titleline__eyebrow-voice-name {
  color: var(--paper);
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  transition: color .5s var(--ease);
}

.titleline__eyebrow-voice-face {
  color: var(--titleline-tone);
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(7.5px, .7vw, 8.5px);
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
  transition: color .5s var(--ease);
}

@keyframes titlelineEyebrowIn {
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* — Stage: the headline + the proof mark — */

.titleline__stage {
  position: relative;
  z-index: 2;
  display: grid;
  gap: clamp(8px, 1.2vw, 18px);
  padding: clamp(8px, 1.4vw, 18px) 0;
  cursor: pointer;
}

.titleline__strike {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--titleline-tone) 20%, transparent), transparent 60%);
  opacity: 0;
  animation: titlelineStrike .65s var(--ease-out);
  mix-blend-mode: screen;
  z-index: -1;
}

@keyframes titlelineStrike {
  0% { opacity: 0; transform: scale(.92); filter: blur(4px); }
  35% { opacity: .8; filter: blur(0); }
  100% { opacity: 0; transform: scale(1.04); filter: blur(0); }
}

@media (prefers-reduced-motion: reduce) {
  .titleline__strike { animation: none !important; opacity: 0 !important; }
}

/* — The headline itself — */

.titleline__headline {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: center;
  gap: clamp(6px, .9vw, 14px);
  margin: 0;
  padding: clamp(14px, 1.8vw, 26px) clamp(6px, 1vw, 18px) clamp(16px, 2vw, 30px);
  text-align: center;
  line-height: .98;
  letter-spacing: -.026em;
  font-size: clamp(48px, 9.2vw, 124px);
  font-weight: 400;
  color: var(--paper);
  position: relative;
  isolation: isolate;
  animation: titlelineHeadlineIn .9s var(--ease-out) .45s backwards;
}

@keyframes titlelineHeadlineIn {
  0% { opacity: 0; transform: translateY(10px); filter: blur(6px); }
  60% { opacity: 1; filter: blur(0); }
  100% { opacity: 1; transform: translateY(0); filter: blur(0); }
}

@media (prefers-reduced-motion: reduce) {
  .titleline__headline { animation: none !important; opacity: 1 !important; transform: none !important; filter: none !important; }
}

.titleline__headline-fragment {
  display: inline-block;
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-weight: 400;
  color: var(--paper);
  opacity: .82;
  transition: opacity .55s var(--ease), color .55s var(--ease);
}

.titleline__headline-sep {
  display: inline-block;
  width: clamp(10px, 1.4vw, 22px);
  height: 1px;
  align-self: center;
  background: linear-gradient(to right, transparent, var(--titleline-ghost), transparent);
  opacity: .8;
}

.titleline__headline-sep--alt {
  background: linear-gradient(to right, transparent, var(--titleline-tone), transparent);
  opacity: .55;
}

.titleline--voice-bold .titleline__headline-fragment {
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-style: normal;
  font-weight: 700;
  letter-spacing: -.04em;
  text-transform: uppercase;
  font-size: .84em;
  opacity: .9;
}

.titleline--voice-human .titleline__headline-fragment {
  font-style: italic;
  font-weight: 500;
  opacity: .88;
}

.titleline--voice-quiet .titleline__headline-fragment {
  font-style: italic;
  opacity: .7;
}

/* — The marked words (tokens) — */

.titleline__token {
  position: relative;
  display: inline-block;
  cursor: pointer;
  outline: none;
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-weight: 400;
  color: var(--paper);
  padding: 0 .04em;
  border-radius: 1px;
  transition: color .45s var(--ease), transform .55s var(--ease-spring);
  isolation: isolate;
}

.titleline__token::before {
  content: '';
  position: absolute;
  inset: clamp(4px, .6vw, 8px) clamp(-6px, -.6vw, -2px);
  border-top: 1px solid transparent;
  border-bottom: 1px solid transparent;
  border-radius: 1px;
  pointer-events: none;
  transition: border-color .45s var(--ease), inset .55s var(--ease-spring);
  z-index: -1;
}

.titleline__token:hover::before,
.titleline__token:focus-visible::before,
.titleline__token.is-hover::before {
  border-top-color: color-mix(in srgb, var(--titleline-tone) 40%, transparent);
  border-bottom-color: color-mix(in srgb, var(--titleline-tone) 40%, transparent);
}

.titleline__token.is-marked {
  color: var(--titleline-tone);
}

.titleline__token.is-marked::before {
  inset: clamp(2px, .4vw, 6px) clamp(-10px, -.9vw, -4px);
  border-top-color: color-mix(in srgb, var(--titleline-tone) 60%, transparent);
  border-bottom-color: color-mix(in srgb, var(--titleline-tone) 60%, transparent);
}

.titleline__token:hover,
.titleline__token:focus-visible,
.titleline__token.is-hover {
  transform: translateY(-1px);
}

.titleline__token:active {
  transform: translateY(0) scale(.98);
}

.titleline__token-text {
  position: relative;
  z-index: 1;
}

.titleline--voice-bold .titleline__token {
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-style: normal;
  font-weight: 800;
  letter-spacing: -.04em;
}

.titleline--voice-bold .titleline__token-text {
  text-transform: uppercase;
  font-size: .88em;
}

/* — Trail beneath the headline — */

.titleline__trail {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  color: var(--paper);
  font-family: 'Iowan Old Style', Georgia, serif;
  font-size: clamp(12px, 1.05vw, 13.5px);
  font-style: italic;
  letter-spacing: -.005em;
}

.titleline__trail-rule {
  display: block;
  width: clamp(30px, 4vw, 60px);
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--titleline-tone) 45%, transparent), transparent);
  opacity: .7;
}

.titleline__trail-rule--lead {
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--titleline-tone) 45%, transparent));
}

.titleline__trail-bead {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--titleline-tone);
  opacity: .8;
}

.titleline__trail-tag {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(6px, .8vw, 10px);
}

.titleline__trail-tag em {
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(7.5px, .7vw, 8.5px);
  font-weight: 600;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--muted);
}

.titleline__trail-sep {
  color: var(--titleline-tone);
  opacity: .45;
}

/* — Proof mark — */

.titleline__proof {
  display: grid;
  gap: clamp(4px, .6vw, 8px);
  justify-items: center;
  margin-top: clamp(2px, .4vw, 6px);
  min-height: clamp(34px, 4vw, 48px);
  color: var(--titleline-tone);
  transition: color .55s var(--ease);
  position: relative;
}

.titleline__proof::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to right, transparent calc(50% - 130px), color-mix(in srgb, var(--titleline-tone) 30%, transparent) 50%, transparent calc(50% + 130px));
  height: 1px;
  top: -.5em;
  opacity: .35;
  pointer-events: none;
}

.titleline__proof-tag {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  font-family: var(--mono);
  font-size: clamp(9px, .75vw, 10.5px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--paper);
  opacity: .65;
}

.titleline__proof-tag em {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(12px, 1vw, 14px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--titleline-tone);
  transition: color .5s var(--ease);
}

.titleline__proof-tag-dot {
  width: 4px;
  height: 4px;
  background: currentColor;
  border-radius: 50%;
  opacity: .8;
}

.titleline__proof-tag-dot--alt { opacity: .55; }

.titleline__proof-svg {
  display: block;
  width: clamp(180px, 22vw, 280px);
  height: clamp(28px, 3.2vw, 38px);
  animation: titlelineProofIn .55s var(--ease-out);
}

@keyframes titlelineProofIn {
  0% { opacity: 0; transform: translateY(4px) scale(.96); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .titleline__proof-svg { animation: none !important; opacity: 1 !important; transform: none !important; }
}

/* Stet — draw the line, then dot */
.titleline__proof-stet {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titlelineStetDraw .55s var(--ease-out) forwards;
}

.titleline__proof-arrow {
  opacity: 0;
  animation: titlelineStetArrow .35s var(--ease-out) .55s forwards;
}

.titleline__proof-bead--lead {
  opacity: 0;
  animation: titlelineProofBead .35s var(--ease-out) .25s forwards;
}

.titleline__proof-bead--trail {
  opacity: 0;
  animation: titlelineProofBead .35s var(--ease-out) .5s forwards;
}

@keyframes titlelineStetDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes titlelineStetArrow {
  to { opacity: .85; }
}

@keyframes titlelineProofBead {
  to { opacity: 1; }
}

/* Caret — draw the curve */
.titleline__proof-caret-curve {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titlelineCaretDraw .55s var(--ease-out) forwards;
}

.titleline__proof-caret-point {
  opacity: 0;
  animation: titlelineCaretPoint .3s var(--ease-spring) .55s forwards;
}

@keyframes titlelineCaretDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes titlelineCaretPoint {
  to { opacity: 1; }
}

/* Query — draw the ring + hook */
.titleline__proof-query-ring {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titlelineQueryRing .65s var(--ease-out) forwards;
  transform-box: fill-box;
  transform-origin: center;
}

.titleline__proof-query-hook {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titlelineQueryHook .55s var(--ease-out) .35s forwards;
}

.titleline__proof-query-dot {
  opacity: 0;
  animation: titlelineProofBead .35s var(--ease-out) .9s forwards;
}

@keyframes titlelineQueryRing {
  to { stroke-dashoffset: 0; }
}

@keyframes titlelineQueryHook {
  to { stroke-dashoffset: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .titleline__proof-stet,
  .titleline__proof-arrow,
  .titleline__proof-caret-curve,
  .titleline__proof-caret-point,
  .titleline__proof-query-ring,
  .titleline__proof-query-hook,
  .titleline__proof-query-dot,
  .titleline__proof-bead {
    animation: none !important;
    opacity: 1 !important;
    stroke-dashoffset: 0 !important;
  }
  .titleline__proof-arrow { opacity: .85 !important; }
}

/* — Caption (colophon-style rows below) — */

.titleline__caption {
  display: grid;
  gap: clamp(4px, .5vw, 7px);
  padding: clamp(10px, 1.4vw, 16px) clamp(14px, 2vw, 22px);
  border-top: 1px solid var(--titleline-rule);
  border-bottom: 1px solid var(--titleline-rule);
  font-family: var(--mono);
  font-size: clamp(9.5px, .78vw, 11px);
  letter-spacing: .04em;
  color: var(--paper);
}

.titleline__caption-row {
  display: grid;
  grid-template-columns: minmax(86px, auto) minmax(0, 1fr);
  gap: clamp(10px, 1.4vw, 18px);
  align-items: baseline;
}

.titleline__caption-row--lead .titleline__caption-value {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(13.5px, 1.18vw, 16px);
  letter-spacing: -.005em;
  color: var(--paper);
}

.titleline__caption-row--soft .titleline__caption-value {
  color: var(--ink-mist);
}

.titleline__caption-key {
  font-family: var(--mono);
  font-size: clamp(9px, .72vw, 10.5px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--titleline-ghost-strong);
}

.titleline__caption-value {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(12.5px, 1.05vw, 14.5px);
  letter-spacing: -.002em;
  color: var(--paper);
}

.titleline__caption-value em {
  color: var(--titleline-tone);
  font-style: italic;
  transition: color .5s var(--ease);
}

/* — Rule beneath — */

.titleline__rule {
  display: block;
  width: 100%;
  height: clamp(4px, .5vw, 6px);
  color: var(--titleline-tone);
  opacity: .55;
  transition: opacity .55s var(--ease), color .55s var(--ease);
}

.titleline__rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.titleline__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titlelineRuleDraw 1.1s var(--ease-out) .8s forwards;
}

.titleline__rule-bead--lead { opacity: 0; animation: titlelineProofBead .4s var(--ease-out) .9s forwards; }
.titleline__rule-bead--trail { opacity: 0; animation: titlelineProofBead .4s var(--ease-out) 1.7s forwards; }

@keyframes titlelineRuleDraw {
  to { stroke-dashoffset: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .titleline__rule-stroke { animation: none !important; stroke-dashoffset: 0 !important; }
  .titleline__rule-bead--lead,
  .titleline__rule-bead--trail { animation: none !important; opacity: 1 !important; }
}

/* — Voice tabs — */

.titleline__voices {
  display: grid;
  gap: clamp(8px, 1vw, 12px);
}

.titleline__voices-tag {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  font-family: var(--mono);
  font-size: clamp(9px, .72vw, 10px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--titleline-ghost-strong);
  justify-self: center;
}

.titleline__voices-tag-mark {
  width: clamp(16px, 2vw, 28px);
  height: 1px;
  background: linear-gradient(to right, transparent, var(--titleline-tone));
  opacity: .7;
}

.titleline__voices-tag-mark--alt {
  background: linear-gradient(to left, transparent, var(--titleline-tone));
}

.titleline__voices-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(8px, 1vw, 12px);
}

.titleline__voice {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(10px, 1.4vw, 16px) clamp(12px, 1.6vw, 18px);
  border: 1px solid rgba(243, 236, 214, .14);
  border-radius: 2px;
  background:
    linear-gradient(180deg, rgba(28, 30, 42, .4), rgba(14, 16, 24, .6));
  color: var(--paper);
  font-family: var(--sans);
  text-align: left;
  cursor: pointer;
  transition:
    border-color .45s var(--ease),
    background .45s var(--ease),
    transform .55s var(--ease-spring),
    color .45s var(--ease),
    box-shadow .55s var(--ease);
  position: relative;
}

.titleline__voice::before {
  content: '';
  position: absolute;
  inset: 4px;
  border: 1px solid transparent;
  border-radius: 1px;
  pointer-events: none;
  transition: border-color .45s var(--ease);
}

.titleline__voice:hover,
.titleline__voice:focus-visible {
  border-color: color-mix(in srgb, var(--titleline-tone) 40%, transparent);
  transform: translateY(-1px);
  box-shadow: 0 12px 28px -16px color-mix(in srgb, var(--titleline-tone) 50%, transparent);
}

.titleline__voice.is-active {
  border-color: var(--titleline-tone);
  background:
    radial-gradient(circle at 0 0, color-mix(in srgb, var(--titleline-tone) 18%, transparent), transparent 60%),
    linear-gradient(180deg, color-mix(in srgb, var(--titleline-tone) 10%, rgba(28, 30, 42, .5)), rgba(14, 16, 24, .7));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--titleline-tone) 25%, transparent),
    0 16px 36px -18px color-mix(in srgb, var(--titleline-tone) 45%, transparent);
}

.titleline__voice.is-active::before {
  border-color: color-mix(in srgb, var(--titleline-tone) 30%, transparent);
}

.titleline__voice-letter {
  display: grid;
  place-items: center;
  width: clamp(34px, 3.2vw, 40px);
  height: clamp(34px, 3.2vw, 40px);
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(17px, 1.4vw, 19px);
  letter-spacing: -.02em;
  color: var(--titleline-ghost-strong);
  transition: color .45s var(--ease), border-color .45s var(--ease), background .45s var(--ease);
}

.titleline__voice.is-active .titleline__voice-letter {
  color: var(--titleline-tone);
  background: color-mix(in srgb, var(--titleline-tone) 14%, transparent);
  border-color: var(--titleline-tone);
}

.titleline__voice:hover .titleline__voice-letter,
.titleline__voice:focus-visible .titleline__voice-letter {
  color: var(--titleline-tone);
  border-color: var(--titleline-tone);
}

.titleline__voice-stack {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.titleline__voice-name {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(13.5px, 1.15vw, 15.5px);
  letter-spacing: -.005em;
  color: var(--paper);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.titleline__voice-face {
  font-family: var(--mono);
  font-size: clamp(8.5px, .68vw, 9.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--titleline-ghost-strong);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.titleline__voice.is-active .titleline__voice-face {
  color: var(--titleline-tone);
  opacity: .9;
}

.titleline__voice-now {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: clamp(8.5px, .7vw, 10px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--titleline-ghost-strong);
  white-space: nowrap;
}

.titleline__voice-now-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--titleline-tone);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--titleline-tone) 25%, transparent);
  animation: titlelineNowPulse 2s var(--ease) infinite;
}

@keyframes titlelineNowPulse {
  0%, 100% { box-shadow: 0 0 0 3px color-mix(in srgb, var(--titleline-tone) 25%, transparent); }
  50% { box-shadow: 0 0 0 6px color-mix(in srgb, var(--titleline-tone) 8%, transparent); }
}

.titleline__voice-now-tag {
  border: 1px solid currentColor;
  padding: 2px 6px;
  border-radius: 1px;
  font-size: clamp(7.5px, .62vw, 8.5px);
  letter-spacing: .28em;
}

@media (prefers-reduced-motion: reduce) {
  .titleline__voice-now-dot { animation: none !important; box-shadow: 0 0 0 3px color-mix(in srgb, var(--titleline-tone) 25%, transparent) !important; }
}

/* — Hint line — */

.titleline__hint {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, 1vw, 12px);
  justify-self: center;
  font-family: var(--mono);
  font-size: clamp(8.5px, .7vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--titleline-ghost-strong);
}

.titleline__hint em {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11px, .9vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
  opacity: .7;
}

.titleline__hint-rule {
  flex: 1;
  min-width: clamp(14px, 2vw, 28px);
  height: 1px;
  background: linear-gradient(to right, transparent, var(--titleline-rule), transparent);
  opacity: .7;
}

.titleline__hint-rule--alt {
  background: linear-gradient(to left, transparent, var(--titleline-rule), transparent);
}

/* — Responsive — */

@media (max-width: 720px) {
  .titleline {
    padding: clamp(16px, 4vw, 22px) clamp(14px, 4vw, 20px);
    gap: clamp(10px, 2.6vw, 16px);
  }

  .titleline__eyebrow {
    grid-template-columns: auto minmax(0, 1fr) auto;
    font-size: 8.5px;
    letter-spacing: .2em;
    row-gap: 6px;
  }

  .titleline__eyebrow-rule,
  .titleline__eyebrow-mark {
    display: none;
  }

  .titleline__eyebrow-eyebrow {
    grid-column: 1 / 3;
    font-size: 11px;
  }

  .titleline__eyebrow-voice {
    grid-column: 1 / 4;
    justify-self: center;
  }

  .titleline__headline {
    font-size: clamp(32px, 9vw, 60px);
    gap: clamp(3px, 1.5vw, 6px);
  }

  .titleline__headline-sep {
    width: clamp(6px, 2vw, 12px);
  }

  .titleline__proof-svg {
    width: clamp(150px, 46vw, 240px);
  }

  .titleline__caption-row {
    grid-template-columns: minmax(72px, auto) minmax(0, 1fr);
    gap: clamp(8px, 2vw, 12px);
  }

  .titleline__voices-row {
    grid-template-columns: minmax(0, 1fr);
  }

  .titleline__voice {
    padding: clamp(8px, 2.6vw, 12px) clamp(10px, 2.6vw, 14px);
  }

  .titleline__voice-letter {
    width: clamp(28px, 8vw, 34px);
    height: clamp(28px, 8vw, 34px);
    font-size: clamp(14px, 4vw, 16px);
  }
}

/* ────────────────────────────────────────────────────────────
   HERO HEADLINE WRAPPER · the headline centerpiece sits inside
   the spread, centered, with generous paper space. The wrapper
   itself stays out of the way so the title line becomes the
   visual focus of the spread.
   ──────────────────────────────────────────────────────────── */

.hero__headline {
  position: relative;
  display: grid;
  width: 100%;
  max-width: 1080px;
  margin: 0 auto;
  z-index: 1;
  animation: heroHeadlineArrive .9s var(--ease-out) .05s backwards;
}

@keyframes heroHeadlineArrive {
  0% { opacity: 0; transform: translateY(12px); filter: blur(4px); }
  100% { opacity: 1; transform: translateY(0); filter: blur(0); }
}

@media (prefers-reduced-motion: reduce) {
  .hero__headline { animation: none !important; opacity: 1 !important; transform: none !important; filter: none !important; }
}

@media (max-width: 720px) {
  .hero__headline {
    max-width: 100%;
  }
}

/* ────────────────────────────────────────────────────────────
   ITERATION 296 · PRESS SIGNATURE LINE.
   A small, distinctive flourish that sits between the
   FolioOpening inscription and the question line. It signs
   the front matter as one composed broadside and hands the
   reader off from the press inscription to the title.
   ──────────────────────────────────────────────────────────── */

.press-sigline {
  --sigline-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  justify-items: center;
  column-gap: clamp(14px, 2vw, 26px);
  row-gap: clamp(6px, .8vw, 10px);
  width: min(100%, 720px);
  margin: clamp(10px, 1.4vw, 22px) auto clamp(20px, 2.4vw, 36px);
  padding: 0 clamp(10px, 1.6vw, 22px);
  color: var(--sigline-tone);
  isolation: isolate;
  opacity: 0;
  transform: translateY(4px);
  animation: pressSiglineIn .9s var(--ease-out) .45s forwards;
}

.press-sigline--quiet { --sigline-tone: var(--blue); }
.press-sigline--human { --sigline-tone: var(--coral); }
.press-sigline--bold { --sigline-tone: var(--acid); }

.press-sigline__defs {
  position: absolute;
  inset: 0;
  width: 0;
  height: 0;
  pointer-events: none;
  visibility: hidden;
}

.press-sigline__rule {
  display: block;
  width: 100%;
  height: 12px;
  color: inherit;
  opacity: .85;
}

.press-sigline__rule--trail {
  opacity: .5;
}

.press-sigline__rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.press-sigline__rule-path {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: pressSiglineRuleDraw 1.1s var(--ease-out) .55s forwards;
}

.press-sigline__rule-bead {
  opacity: 0;
  animation: pressSiglineBeadIn .35s var(--ease-spring) 1.55s forwards;
}

.press-sigline__seal {
  display: inline-grid;
  place-items: center;
  width: clamp(44px, 4.6vw, 64px);
  height: clamp(44px, 4.6vw, 64px);
  color: var(--sigline-tone);
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, .35));
  transition: color .5s var(--ease);
}

.press-sigline__seal svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.press-sigline__copy {
  grid-column: 1 / -1;
  display: grid;
  gap: clamp(4px, .5vw, 8px);
  justify-items: center;
  text-align: center;
  color: var(--paper);
  font-family: var(--serif);
}

.press-sigline__kept {
  font-style: italic;
  font-size: clamp(13px, 1.18vw, 15.5px);
  letter-spacing: -.005em;
  line-height: 1.35;
  color: var(--paper);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .15);
}

.press-sigline__date {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 9.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--muted);
}

.press-sigline__date em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, 1.05vw, 14px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
}

.press-sigline__date-mark {
  display: inline-block;
  width: clamp(10px, 1vw, 14px);
  height: 1px;
  background: currentColor;
  opacity: .6;
}

.press-sigline__date-mark--alt {
  background: linear-gradient(to left, currentColor, transparent);
  opacity: .85;
}

@keyframes pressSiglineIn {
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes pressSiglineRuleDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes pressSiglineBeadIn {
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .press-sigline,
  .press-sigline__rule-path,
  .press-sigline__rule-bead {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }
}

@media (max-width: 720px) {
  .press-sigline {
    grid-template-columns: minmax(0, 1fr);
    row-gap: clamp(8px, 1vw, 12px);
    margin: clamp(8px, 1.2vw, 16px) auto clamp(16px, 2vw, 24px);
  }

  .press-sigline__rule {
    display: none;
  }

  .press-sigline__seal {
    width: clamp(40px, 12vw, 52px);
    height: clamp(40px, 12vw, 52px);
  }
}

/* ────────────────────────────────────────────────────────────
   TITLE FOLD · a single paper-folded opening that frames the
   headline. The fold mark draws itself beneath the title; the
   legend hangs below as a quiet record of voice, word, and
   date. Reduced-motion users see the settled state.
   ──────────────────────────────────────────────────────────── */

.title-fold {
  --title-fold-tone: var(--coral);
  --title-fold-hint: rgba(243, 236, 214, .55);
  --title-fold-rule: rgba(243, 236, 214, .14);
  --title-fold-rule-soft: rgba(243, 236, 214, .06);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  justify-items: center;
  gap: clamp(16px, 2vw, 28px);
  width: min(100%, 1180px);
  margin: clamp(28px, 3.4vw, 48px) auto clamp(32px, 3.8vw, 56px);
  padding: clamp(28px, 3.4vw, 48px) clamp(28px, 4vw, 64px) clamp(24px, 3vw, 40px);
  isolation: isolate;
  overflow: visible;
  border: 1px solid var(--line);
  background:
    radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--title-fold-tone) 8%, transparent), transparent 56%),
    radial-gradient(ellipse at 50% 100%, color-mix(in srgb, var(--title-fold-tone) 5%, transparent), transparent 60%),
    linear-gradient(180deg, rgba(28, 36, 52, .36), rgba(14, 20, 32, .58));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    inset 0 1px 0 rgba(243, 236, 214, .04),
    0 36px 96px -40px rgba(0, 0, 0, .5);
  opacity: 0;
  transform: translateY(10px);
  animation: titleFoldArrive 1.1s var(--ease-out) .15s forwards;
}

@keyframes titleFoldArrive {
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .title-fold { animation: none !important; opacity: 1 !important; transform: none !important; }
}

.title-fold::before {
  content: '';
  position: absolute;
  inset: 6px;
  border: 1px dashed color-mix(in srgb, var(--title-fold-tone) 18%, transparent);
  pointer-events: none;
  opacity: .65;
  z-index: 0;
}

.title-fold::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(0deg, transparent 0 26px, color-mix(in srgb, var(--title-fold-tone) 3%, transparent) 26px 27px);
  mask-image: linear-gradient(180deg, transparent, black 12%, black 88%, transparent);
  opacity: .25;
  z-index: 0;
}

.title-fold__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

.title-fold__paper {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.title-fold__paper svg {
  display: block;
  width: 100%;
  height: 100%;
}

.title-fold__grain {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  opacity: .55;
  mix-blend-mode: overlay;
}

.title-fold__grain svg {
  display: block;
  width: 100%;
  height: 100%;
}

.title-fold__corner {
  position: absolute;
  width: 16px;
  height: 16px;
  pointer-events: none;
  z-index: 3;
  border-color: color-mix(in srgb, var(--title-fold-tone) 55%, transparent);
  border-style: solid;
  border-width: 0;
}

.title-fold__corner--tl { top: 14px; left: 14px; border-top-width: 1px; border-left-width: 1px; }
.title-fold__corner--tr { top: 14px; right: 14px; border-top-width: 1px; border-right-width: 1px; }
.title-fold__corner--bl { bottom: 14px; left: 14px; border-bottom-width: 1px; border-left-width: 1px; }
.title-fold__corner--br { bottom: 14px; right: 14px; border-bottom-width: 1px; border-right-width: 1px; }

.title-fold__edge {
  position: absolute;
  top: 14px;
  bottom: 14px;
  width: 1px;
  pointer-events: none;
  background: linear-gradient(to bottom, transparent, color-mix(in srgb, var(--title-fold-tone) 32%, transparent) 14%, color-mix(in srgb, var(--title-fold-tone) 32%, transparent) 86%, transparent);
  opacity: .65;
  z-index: 2;
}

.title-fold__edge--lead { left: 50%; transform: translateX(-50%); }
.title-fold__edge--trail { display: none; }

.title-fold__masthead {
  position: relative;
  z-index: 3;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(12px, 1.6vw, 22px);
  width: 100%;
  color: var(--paper);
  opacity: 0;
  animation: titleFoldFadeIn .6s var(--ease-out) .25s forwards;
}

@keyframes titleFoldFadeIn {
  to { opacity: 1; }
}

.title-fold__masthead-rule {
  display: block;
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--title-fold-tone) 40%, transparent), transparent);
}

.title-fold__masthead-tag {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 9.5px);
  font-weight: 600;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: var(--paper);
}

.title-fold__masthead-mark {
  display: inline-block;
  width: 5px;
  height: 5px;
  background: var(--title-fold-tone);
  transform: rotate(45deg);
  opacity: .75;
}

.title-fold__masthead-mark--alt { opacity: .4; }

.title-fold__masthead-sep {
  color: var(--title-fold-tone);
  opacity: .5;
}

.title-fold__masthead em {
  font-family: var(--serif);
  font-style: italic;
  text-transform: none;
  letter-spacing: .02em;
  font-size: clamp(11px, .95vw, 12.5px);
  color: var(--title-fold-tone);
  font-weight: 400;
}

.title-fold__seal {
  position: absolute;
  top: clamp(-22px, -2vw, -14px);
  right: clamp(14px, 2.4vw, 32px);
  z-index: 5;
  display: grid;
  justify-items: center;
  gap: 6px;
  width: clamp(58px, 5.4vw, 76px);
  color: var(--title-fold-tone);
  opacity: 0;
  transform: translateY(-6px) rotate(8deg);
  animation: titleFoldSealIn .9s var(--ease-spring) 1.4s forwards;
  pointer-events: none;
  transition: color .55s var(--ease), transform .55s var(--ease-spring);
}

.title-fold__seal svg {
  display: block;
  width: 100%;
  height: auto;
}

.title-fold__seal-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px 3px;
  background: rgba(14, 20, 32, .78);
  border: 1px solid color-mix(in srgb, var(--title-fold-tone) 45%, transparent);
  border-radius: 1px;
  font-family: var(--mono);
  font-size: clamp(7.5px, .7vw, 8.5px);
  font-weight: 600;
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--title-fold-tone);
}

.title-fold__seal-tag em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .92vw, 12.5px);
  letter-spacing: -.005em;
  text-transform: none;
  font-weight: 600;
  color: var(--paper);
}

.title-fold:hover .title-fold__seal,
.title-fold:focus-within .title-fold__seal {
  transform: translateY(0) rotate(4deg);
}

@keyframes titleFoldSealIn {
  to { opacity: 1; transform: translateY(0) rotate(8deg); }
}

.title-fold__stage {
  position: relative;
  z-index: 4;
  width: 100%;
  display: grid;
  place-items: center;
  padding: clamp(8px, 1.2vw, 18px) 0;
}

.title-fold__crease {
  position: relative;
  z-index: 4;
  display: grid;
  justify-items: center;
  gap: 8px;
  color: var(--title-fold-tone);
  opacity: 0;
  animation: titleFoldCreaseIn .55s var(--ease-out) 1.85s forwards;
  padding-top: clamp(4px, .8vw, 10px);
}

.title-fold__crease svg {
  display: block;
  width: clamp(160px, 16vw, 220px);
  height: clamp(12px, 1.1vw, 16px);
}

@keyframes titleFoldCreaseIn {
  to { opacity: .9; }
}

.title-fold__crease-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--title-fold-tone);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9px);
  font-weight: 600;
  letter-spacing: .28em;
  text-transform: uppercase;
}

.title-fold__crease-tag em {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11px, 1vw, 12.5px);
  font-weight: 400;
  letter-spacing: -.005em;
  text-transform: none;
}

.title-fold__crease-tag-rule {
  display: inline-block;
  width: clamp(18px, 2vw, 30px);
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor);
  opacity: .55;
}

.title-fold__crease-tag-rule--alt {
  background: linear-gradient(to left, transparent, currentColor);
}

.title-fold__signature {
  position: relative;
  z-index: 4;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(12px, 1.6vw, 20px);
  padding: clamp(6px, 1vw, 12px) clamp(8px, 1.2vw, 18px);
  border-top: 1px dashed color-mix(in srgb, var(--title-fold-tone) 24%, transparent);
  color: var(--paper);
  opacity: 0;
  animation: titleFoldFadeIn .6s var(--ease-out) 2.1s forwards;
  width: 100%;
}

.title-fold__signature-mark {
  color: var(--title-fold-tone);
  display: inline-flex;
  align-items: center;
}

.title-fold__signature-mark svg {
  display: block;
  width: clamp(28px, 3vw, 36px);
  height: 12px;
}

.title-fold__signature-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titleFoldSignatureDraw 1.2s var(--ease-out) 2.1s forwards;
}

@keyframes titleFoldSignatureDraw {
  to { stroke-dashoffset: 0; }
}

.title-fold__signature-row {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(10px, 1.2vw, 16px);
}

.title-fold__signature-cell {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(6px, .7vw, 10px);
  font-family: 'Iowan Old Style', Georgia, serif;
}

.title-fold__signature-key {
  font-family: var(--mono);
  font-size: clamp(7.5px, .68vw, 8.5px);
  font-weight: 600;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--muted);
}

.title-fold__signature-cell em {
  font-style: italic;
  font-size: clamp(13px, 1.18vw, 15px);
  letter-spacing: -.005em;
  color: var(--paper);
}

.title-fold__signature-mark-tag {
  display: inline-block;
  padding: 2px 6px 3px;
  border: 1px solid color-mix(in srgb, var(--title-fold-tone) 45%, transparent);
  border-radius: 1px;
  color: var(--title-fold-tone);
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(7.5px, .68vw, 8.5px);
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.title-fold__signature-bead {
  display: inline-block;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--title-fold-tone);
  opacity: .5;
}

.title-fold__rehearsing {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--title-fold-tone);
  font-family: var(--mono);
  font-size: clamp(7.5px, .68vw, 8.5px);
  font-weight: 600;
  letter-spacing: .24em;
  text-transform: uppercase;
}

.title-fold__rehearsing em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .92vw, 12.5px);
  letter-spacing: -.005em;
  text-transform: none;
}

.title-fold__rehearsing-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  animation: titleFoldPulse 1.4s ease-in-out infinite;
}

@keyframes titleFoldPulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.4); opacity: .5; }
}

.app--voice-quiet .title-fold { --title-fold-tone: var(--blue); }
.app--voice-human .title-fold { --title-fold-tone: var(--coral); }
.app--voice-bold .title-fold { --title-fold-tone: var(--acid); }

@media (prefers-reduced-motion: reduce) {
  .title-fold { animation: none !important; transform: none !important; opacity: 1 !important; }
  .title-fold__seal,
  .title-fold__crease,
  .title-fold__masthead,
  .title-fold__signature {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }
  .title-fold__signature-stroke { animation: none !important; stroke-dashoffset: 0 !important; }
  .title-fold__rehearsing-dot { animation: none !important; }
}

@media (max-width: 720px) {
  .title-fold {
    padding: clamp(20px, 3vw, 28px) clamp(16px, 2.4vw, 24px) clamp(18px, 2.6vw, 26px);
    gap: clamp(12px, 1.8vw, 18px);
  }

  .title-fold__seal {
    width: 50px;
    top: -10px;
    right: 12px;
  }

  .title-fold__signature {
    grid-template-columns: minmax(0, 1fr);
    row-gap: clamp(6px, 1vw, 10px);
  }

  .title-fold__signature-row {
    gap: clamp(8px, 1vw, 12px);
  }

  .title-fold__signature-bead {
    display: none;
  }

  .title-fold__crease-tag {
    font-size: 8px;
  }
}

@media (max-width: 480px) {
  .title-fold__seal {
    width: 42px;
    top: -8px;
    right: 8px;
  }

  .title-fold__crease svg {
    width: 130px;
    height: 10px;
  }
}

/* ────────────────────────────────────────────────────────────
/* ────────────────────────────────────────────────────────────
   VOICE TRIAL · a single composed press rehearsal. The pip row
   is gone; voices are set elsewhere. The wheel and the pull
   are the page's one rehearsal affordance.
   ──────────────────────────────────────────────────────────── */

.voice-trial {
  --voice-trial-tone: var(--coral);
  --voice-trial-rule: rgba(243, 236, 214, .14);
  --voice-trial-ghost: rgba(243, 236, 214, .4);
  --voice-trial-ghost-soft: rgba(243, 236, 214, .22);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: clamp(14px, 1.6vw, 22px);
  width: min(100%, 1080px);
  margin: clamp(20px, 2.4vw, 30px) auto clamp(30px, 3.2vw, 46px);
  padding: clamp(18px, 2.2vw, 30px) clamp(22px, 2.8vw, 40px);
  border: 1px solid var(--voice-trial-rule);
  border-radius: 2px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--voice-trial-tone) 6%, transparent), transparent 60%),
    linear-gradient(180deg, rgba(20, 24, 36, .62), rgba(10, 14, 24, .82));
  color: var(--paper);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--voice-trial-tone) 10%, transparent),
    0 24px 80px -32px rgba(0, 0, 0, .55);
  isolation: isolate;
  opacity: 0;
  transform: translateY(8px);
  animation: voiceTrialIn .9s var(--ease-out) .1s forwards;
}

.voice-trial--voice-quiet { --voice-trial-tone: var(--blue); }
.voice-trial--voice-human { --voice-trial-tone: var(--coral); }
.voice-trial--voice-bold { --voice-trial-tone: var(--acid); }

.voice-trial::before {
  content: '';
  position: absolute;
  inset: 6px;
  border: 1px dashed color-mix(in srgb, var(--voice-trial-tone) 16%, transparent);
  border-radius: 1px;
  pointer-events: none;
  z-index: 0;
}

.voice-trial::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(0deg, transparent 0 22px, color-mix(in srgb, var(--voice-trial-tone) 4%, transparent) 22px 23px);
  mask-image: linear-gradient(180deg, transparent, black 14%, black 86%, transparent);
  pointer-events: none;
  opacity: .35;
  z-index: -1;
}

.voice-trial__defs {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}

.voice-trial__paper {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--voice-trial-tone) 14%, transparent), transparent 60%);
  opacity: .55;
  z-index: -1;
}

@keyframes voiceTrialIn {
  0% { opacity: 0; transform: translateY(10px); filter: blur(2px); }
  100% { opacity: 1; transform: translateY(0); filter: blur(0); }
}

@media (prefers-reduced-motion: reduce) {
  .voice-trial { animation: none !important; opacity: 1 !important; transform: none !important; }
}

/* — Masthead — */

.voice-trial__masthead {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  width: 100%;
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 9.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--voice-trial-ghost);
}

.voice-trial__masthead-rule {
  display: block;
  height: 1px;
  background: linear-gradient(to right, transparent, var(--voice-trial-rule), transparent);
  width: clamp(20px, 4vw, 60px);
}

.voice-trial__masthead-rule--lead {
  background: linear-gradient(to right, var(--voice-trial-tone), transparent);
  opacity: .55;
}

.voice-trial__masthead-rule--trail {
  background: linear-gradient(to left, var(--voice-trial-tone), transparent);
  opacity: .55;
}

.voice-trial__masthead-tag {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  color: var(--paper);
  opacity: .9;
}

.voice-trial__masthead-mark {
  display: inline-block;
  width: clamp(8px, .8vw, 12px);
  height: 1px;
  background: var(--voice-trial-tone);
  opacity: .75;
}

.voice-trial__masthead-mark--alt {
  background: var(--voice-trial-ghost-soft);
}

.voice-trial__masthead-set {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(6px, .8vw, 10px);
  justify-self: end;
  text-align: right;
  color: var(--voice-trial-ghost);
  letter-spacing: .22em;
}

.voice-trial__masthead-set em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--voice-trial-tone);
}

/* — Press bed: the wheel — */

.voice-trial__bed {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(16px, 2.4vw, 28px);
  width: 100%;
  padding: clamp(10px, 1.2vw, 16px) clamp(14px, 1.8vw, 26px);
  border: 1px solid color-mix(in srgb, var(--voice-trial-tone) 16%, transparent);
  border-radius: 2px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--voice-trial-tone) 4%, transparent), transparent 70%),
    rgba(14, 18, 28, .55);
}

.voice-trial__bed-rule {
  position: absolute;
  left: 14px;
  right: 14px;
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--voice-trial-tone) 35%, transparent), transparent);
  pointer-events: none;
  opacity: .55;
}

.voice-trial__bed-rule--top { top: 6px; }
.voice-trial__bed-rule--bottom { bottom: 6px; }

.voice-trial__wheel-button {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: clamp(14px, 1.6vw, 22px);
  align-items: center;
  padding: clamp(6px, 1vw, 10px) clamp(10px, 1.4vw, 16px);
  border: 1px dashed color-mix(in srgb, var(--voice-trial-tone) 30%, transparent);
  border-radius: 999px;
  background: rgba(20, 24, 36, .55);
  color: var(--voice-trial-tone);
  font: inherit;
  cursor: pointer;
  text-align: left;
  isolation: isolate;
  transition: transform .55s var(--ease-spring), border-color .5s var(--ease), box-shadow .55s var(--ease);
}

.voice-trial__wheel-button:hover,
.voice-trial__wheel-button:focus-visible {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--voice-trial-tone) 55%, transparent);
  box-shadow: 0 16px 36px -24px color-mix(in srgb, var(--voice-trial-tone) 70%, transparent);
}

.voice-trial__wheel-button:active {
  transform: translateY(0) scale(.99);
}

.voice-trial.is-rehearsing .voice-trial__wheel-button {
  border-color: color-mix(in srgb, var(--voice-trial-tone) 65%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--voice-trial-tone) 22%, transparent),
    0 16px 36px -22px color-mix(in srgb, var(--voice-trial-tone) 60%, transparent);
}

.voice-trial__wheel {
  display: block;
  width: clamp(54px, 5.6vw, 78px);
  height: clamp(54px, 5.6vw, 78px);
  color: var(--voice-trial-tone);
}

.voice-trial.is-rehearsing .voice-trial__wheel-bearings {
  animation: voiceTrialWheelSpin 1.1s linear infinite;
  transform-origin: 32px 32px;
}

.voice-trial.is-rehearsing .voice-trial__wheel-rings {
  animation: voiceTrialWheelSpin 6s linear infinite;
  transform-origin: 32px 32px;
}

@keyframes voiceTrialWheelSpin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes voiceTrialWheelSpinReverse {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(-360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .voice-trial.is-rehearsing .voice-trial__wheel-bearings,
  .voice-trial.is-rehearsing .voice-trial__wheel-rings { animation: none !important; }
}

.voice-trial__wheel-letter {
  transition: opacity .45s var(--ease), font-size .45s var(--ease);
}

.voice-trial__wheel-letter.is-active {
  font-weight: 700;
}

.voice-trial__wheel-core {
  animation: voiceTrialWheelCorePulse 1.4s ease-in-out infinite;
}

@keyframes voiceTrialWheelCorePulse {
  0%, 100% { r: 2.6; }
  50% { r: 3.2; }
}

@media (prefers-reduced-motion: reduce) {
  .voice-trial__wheel-core { animation: none !important; }
}

.voice-trial__wheel-halo {
  transition: opacity .55s var(--ease);
}

.voice-trial.is-rehearsing .voice-trial__wheel-halo {
  opacity: 1;
  animation: voiceTrialWheelHalo 1.1s ease-in-out infinite;
}

@keyframes voiceTrialWheelHalo {
  0%, 100% { opacity: .35; }
  50% { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .voice-trial.is-rehearsing .voice-trial__wheel-halo { animation: none !important; opacity: .65 !important; }
}

.voice-trial__wheel-readout {
  display: grid;
  gap: 2px;
  min-width: 0;
  color: var(--paper);
}

.voice-trial__wheel-readout-row {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
}

.voice-trial__wheel-readout-key {
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--voice-trial-ghost);
}

.voice-trial__wheel-readout-voice {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.3vw, 18px);
  letter-spacing: -.005em;
  color: var(--voice-trial-tone);
  transition: color .45s var(--ease);
}

.voice-trial__wheel-readout-face {
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--voice-trial-ghost-soft);
}

/* — Press bed — track (voice proof tape) — */

.voice-trial__bed-track {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  min-width: 0;
  color: var(--voice-trial-ghost);
}

.voice-trial__bed-track svg {
  display: block;
  width: 100%;
  height: clamp(4px, .5vw, 6px);
}

.voice-trial__bed-track-progress {
  transition: x .55s var(--ease);
}

.voice-trial__bed-track-cell {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.voice-trial__bed-track-cell-letter {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.01em;
  color: var(--paper);
  text-transform: none;
}

.voice-trial__bed-track-cell-name {
  color: var(--voice-trial-ghost-soft);
  text-align: center;
  max-width: 7.5em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* — Pull row (rehearsal pull affordance) — */

.voice-trial__pull-row {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: clamp(14px, 1.6vw, 22px);
  align-items: center;
  width: 100%;
}

.voice-trial__pull {
  --voice-trial-pull-tone: var(--voice-trial-tone);
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: clamp(12px, 1.2vw, 18px);
  align-items: center;
  padding: clamp(10px, 1.2vw, 14px) clamp(14px, 1.6vw, 22px);
  border: 1px solid color-mix(in srgb, var(--voice-trial-pull-tone) 50%, transparent);
  border-radius: 2px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--voice-trial-pull-tone) 8%, transparent), transparent 70%),
    linear-gradient(180deg, rgba(34, 38, 52, .6), rgba(14, 18, 28, .78));
  color: var(--paper);
  font: inherit;
  cursor: pointer;
  text-align: left;
  isolation: isolate;
  transition: transform .55s var(--ease-spring), border-color .5s var(--ease), background .55s var(--ease);
}

.voice-trial__pull::before {
  content: '';
  position: absolute;
  inset: 4px;
  border: 1px solid color-mix(in srgb, var(--voice-trial-pull-tone) 22%, transparent);
  border-radius: 1px;
  pointer-events: none;
  opacity: .65;
}

.voice-trial__pull::after {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 3px;
  background: radial-gradient(ellipse at 0% 50%, color-mix(in srgb, var(--voice-trial-pull-tone) 40%, transparent), transparent 60%);
  pointer-events: none;
  opacity: 0;
  transition: opacity .5s var(--ease);
}

.voice-trial.is-rehearsing .voice-trial__pull {
  background:
    radial-gradient(ellipse at 50% 50%, color-mix(in srgb, var(--voice-trial-pull-tone) 22%, transparent), transparent 70%),
    linear-gradient(180deg, rgba(46, 50, 66, .68), rgba(14, 18, 28, .78));
  border-color: color-mix(in srgb, var(--voice-trial-pull-tone) 70%, transparent);
}

.voice-trial.is-rehearsing .voice-trial__pull::after {
  opacity: 1;
}

.voice-trial__pull:hover,
.voice-trial__pull:focus-visible {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--voice-trial-pull-tone) 75%, transparent);
}

.voice-trial__pull:active {
  transform: translateY(0) scale(.99);
}

.voice-trial__pull-pad {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: clamp(38px, 3.6vw, 50px);
  height: clamp(38px, 3.6vw, 50px);
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, color-mix(in srgb, var(--voice-trial-pull-tone) 30%, transparent), color-mix(in srgb, var(--voice-trial-pull-tone) 5%, transparent));
  color: var(--voice-trial-pull-tone);
  border: 1px solid color-mix(in srgb, var(--voice-trial-pull-tone) 50%, transparent);
}

.voice-trial__pull-glyph {
  display: block;
  width: 60%;
  height: 60%;
}

.voice-trial.is-rehearsing .voice-trial__pull-bar {
  animation: voiceTrialPullBar 1.1s var(--ease-out) infinite;
}

.voice-trial.is-rehearsing .voice-trial__pull-arrow {
  animation: voiceTrialPullArrow 1.1s var(--ease-out) infinite;
}

.voice-trial.is-rehearsing .voice-trial__pull-bead--lead {
  animation: voiceTrialPullBead 1.1s var(--ease-out) infinite;
}

.voice-trial.is-rehearsing .voice-trial__pull-bead--trail {
  animation: voiceTrialPullBeadTrail 1.1s var(--ease-out) infinite;
}

@keyframes voiceTrialPullBar {
  0% { stroke-dasharray: 100 100; stroke-dashoffset: 100; }
  40%, 100% { stroke-dasharray: 100 100; stroke-dashoffset: 0; }
}

@keyframes voiceTrialPullArrow {
  0%, 50% { transform: translateX(-4px); opacity: .5; }
  80%, 100% { transform: translateX(0); opacity: 1; }
}

@keyframes voiceTrialPullBead {
  0%, 50% { transform: translateX(-3px); opacity: .5; }
  80%, 100% { transform: translateX(0); opacity: 1; }
}

@keyframes voiceTrialPullBeadTrail {
  0%, 80% { transform: scale(.8); opacity: .4; }
  100% { transform: scale(1); opacity: 1; }
}

.voice-trial__pull-stack {
  display: grid;
  gap: 2px;
}

.voice-trial__pull-eyebrow {
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 9.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--voice-trial-pull-tone);
}

.voice-trial__pull-headline {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.2vw, 16px);
  letter-spacing: -.005em;
  color: var(--paper);
}

.voice-trial__pull-sub {
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--voice-trial-ghost-soft);
}

/* — Counter — */

.voice-trial__counter {
  position: relative;
  display: grid;
  gap: 4px;
  justify-items: end;
  min-width: clamp(120px, 14vw, 180px);
  padding: clamp(8px, 1.1vw, 12px) clamp(12px, 1.4vw, 18px);
  border: 1px solid color-mix(in srgb, var(--voice-trial-tone) 24%, transparent);
  border-radius: 2px;
  background: rgba(20, 24, 36, .5);
  color: var(--paper);
}

.voice-trial__counter-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--voice-trial-ghost);
}

.voice-trial__counter-tag-mark {
  display: inline-block;
  width: 8px;
  height: 1px;
  background: var(--voice-trial-tone);
  opacity: .75;
}

.voice-trial__counter-row {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
}

.voice-trial__counter-num {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(22px, 1.9vw, 28px);
  font-variant-numeric: tabular-nums;
  letter-spacing: -.01em;
  color: var(--voice-trial-tone);
  line-height: 1;
}

.voice-trial__counter-suffix {
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--voice-trial-ghost-soft);
}

/* — Hint — */

.voice-trial__hint {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--voice-trial-ghost);
  text-align: center;
  justify-self: center;
}

.voice-trial__hint-mark {
  display: inline-block;
  width: clamp(20px, 2.6vw, 38px);
  height: 1px;
  background: linear-gradient(to right, transparent, var(--voice-trial-tone), transparent);
  opacity: .65;
}

.voice-trial__hint-mark--alt {
  background: linear-gradient(to left, transparent, var(--voice-trial-tone), transparent);
}

@media (prefers-reduced-motion: reduce) {
  .voice-trial.is-rehearsing .voice-trial__pull-bar,
  .voice-trial.is-rehearsing .voice-trial__pull-arrow,
  .voice-trial.is-rehearsing .voice-trial__pull-bead--lead,
  .voice-trial.is-rehearsing .voice-trial__pull-bead--trail {
    animation: none !important;
  }
}

@media (max-width: 920px) {
  .voice-trial__bed {
    grid-template-columns: minmax(0, 1fr);
    gap: 14px;
  }

  .voice-trial__pull-row {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .voice-trial__counter {
    justify-self: stretch;
    justify-items: start;
    min-width: 0;
  }
}

@media (max-width: 560px) {
  .voice-trial {
    padding: clamp(14px, 2vw, 18px) clamp(14px, 2vw, 20px);
  }

  .voice-trial__masthead-set {
    display: none;
  }

  .voice-trial__masthead {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .voice-trial__wheel-button {
    grid-template-columns: auto;
    justify-items: center;
  }

  .voice-trial__wheel-readout {
    justify-items: center;
    text-align: center;
  }

  .voice-trial__bed-track-cell-name {
    display: none;
  }
}


/* ────────────────────────────────────────────────────────────
   LETTERPRESS CATCH · a single composed press signature that
   sits in the body of the broadside. Three voices are set on
   one word across a single row; the active voice steps forward.
   A press seal anchors the composition, and a small footer
   states the rule that the three voices share. The component
   tightens the page into one composed "press signature" moment.
   ──────────────────────────────────────────────────────────── */

.catch-section {
  position: relative;
  padding: clamp(56px, 7vw, 112px) var(--gutter) clamp(72px, 8vw, 128px);
  isolation: isolate;
}

.catch-section__header {
  position: relative;
  max-width: 1080px;
  margin: 0 auto clamp(28px, 3.4vw, 44px);
  display: grid;
  gap: clamp(10px, 1.2vw, 18px);
  text-align: center;
}

.catch-section__header .eyebrow {
  justify-content: center;
}

.catch-section__header h2 {
  margin: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-weight: 400;
  font-size: clamp(2rem, 4.4vw, 3.6rem);
  line-height: 1.04;
  letter-spacing: -.04em;
  text-wrap: balance;
}

.catch-section__header h2 i {
  font-style: italic;
  color: color-mix(in srgb, var(--paper) 78%, transparent);
  text-shadow: 0 0 .04em rgba(243, 236, 214, .12);
}

.catch-section__lede {
  margin: 0 auto;
  max-width: 56ch;
  color: var(--lead-2);
  font-family: var(--serif);
  font-size: clamp(15.5px, 1.4vw, 18px);
  line-height: 1.55;
  font-style: italic;
  letter-spacing: -.005em;
  text-wrap: pretty;
}

.catch {
  --catch-tone: var(--coral);
  --catch-rhythm: clamp(20px, 2.6vw, 36px);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(20px, 2.4vw, 32px);
  max-width: 1240px;
  margin: 0 auto;
  padding: clamp(28px, 3.4vw, 56px) clamp(22px, 3vw, 56px);
  border: 1px solid var(--line);
  border-radius: 2px;
  background:
    radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--catch-tone) 12%, transparent), transparent 56%),
    radial-gradient(ellipse at 0% 100%, rgba(155, 188, 255, .04), transparent 60%),
    linear-gradient(180deg, rgba(20, 26, 38, .42), rgba(12, 16, 26, .58));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    inset 0 1px 0 rgba(243, 236, 214, .04),
    0 32px 72px -42px rgba(0, 0, 0, .55);
  isolation: isolate;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-out);
}

.catch.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.catch::before {
  content: '';
  position: absolute;
  inset: 8px;
  border: 1px dashed color-mix(in srgb, var(--catch-tone) 14%, transparent);
  border-radius: 1px;
  pointer-events: none;
  opacity: .55;
}

.catch__defs,
.catch__sheet {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}

.catch__sheet { opacity: .35; }

.catch__crop {
  position: absolute;
  width: 14px;
  height: 14px;
  pointer-events: none;
  color: color-mix(in srgb, var(--catch-tone) 50%, var(--paper));
  opacity: .75;
}

.catch__crop::before,
.catch__crop::after {
  content: '';
  position: absolute;
  background: currentColor;
}

.catch__crop::before { width: 9px; height: 1px; }
.catch__crop::after { width: 1px; height: 9px; }

.catch__crop--tl { top: 14px; left: 14px; }
.catch__crop--tl::before { top: 0; left: 0; }
.catch__crop--tl::after { top: 0; left: 0; }

.catch__crop--tr { top: 14px; right: 14px; }
.catch__crop--tr::before { top: 0; right: 0; }
.catch__crop--tr::after { top: 0; right: 0; }

.catch__crop--bl { bottom: 14px; left: 14px; }
.catch__crop--bl::before { bottom: 0; left: 0; }
.catch__crop--bl::after { bottom: 0; left: 0; }

.catch__crop--br { bottom: 14px; right: 14px; }
.catch__crop--br::before { bottom: 0; right: 0; }
.catch__crop--br::after { bottom: 0; right: 0; }

.catch__head {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  z-index: 1;
}

.catch__head-mark {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: currentColor;
  color: var(--catch-tone);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--catch-tone) 22%, transparent);
  opacity: .9;
}

.catch__head-mark--alt {
  box-shadow: 0 0 0 3px rgba(243, 236, 214, .08);
}

.catch__head-rule {
  height: 1px;
  background: linear-gradient(
    to right,
    transparent,
    color-mix(in srgb, var(--catch-tone) 56%, transparent),
    transparent
  );
  opacity: .85;
}

.catch__head-rule--alt {
  background: linear-gradient(
    to left,
    transparent,
    color-mix(in srgb, var(--paper) 22%, transparent),
    transparent
  );
}

.catch__head-stack {
  display: grid;
  gap: 2px;
  text-align: center;
}

.catch__head-eyebrow {
  color: var(--catch-tone);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .32em;
  text-transform: uppercase;
}

.catch__head-title {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(14px, 1.4vw, 18px);
  letter-spacing: -.012em;
  color: var(--paper);
  text-wrap: balance;
}

.catch__strip {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(14px, 1.8vw, 26px);
  z-index: 1;
}

.catch__voice {
  position: relative;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  gap: clamp(10px, 1.2vw, 18px);
  padding: clamp(22px, 2.6vw, 36px) clamp(18px, 2vw, 28px) clamp(18px, 2vw, 24px);
  border: 1px solid var(--line-soft);
  border-radius: 2px;
  background:
    linear-gradient(180deg, rgba(243, 236, 214, .025), rgba(243, 236, 214, 0) 60%),
    rgba(12, 16, 26, .38);
  transition:
    border-color .55s var(--ease),
    transform .65s var(--ease-spring),
    box-shadow .65s var(--ease),
    background .65s var(--ease);
  isolation: isolate;
}

.catch__voice::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 2px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--voice-tone, var(--paper)) 8%, transparent), transparent 56%);
  opacity: 0;
  transition: opacity .55s var(--ease);
  pointer-events: none;
  z-index: -1;
}

.catch__voice--quiet { --voice-tone: var(--blue); }
.catch__voice--human { --voice-tone: var(--coral); }
.catch__voice--bold { --voice-tone: var(--acid); }

.catch__voice.is-active {
  border-color: color-mix(in srgb, var(--voice-tone) 56%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--voice-tone) 14%, transparent), transparent 64%),
    rgba(12, 16, 26, .38);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--voice-tone) 24%, transparent),
    0 18px 36px -28px color-mix(in srgb, var(--voice-tone) 50%, transparent);
  transform: translateY(-4px);
}

.catch__voice.is-active::before { opacity: 1; }

.catch__voice-corner {
  position: absolute;
  width: 10px;
  height: 10px;
  pointer-events: none;
  color: var(--voice-tone);
  opacity: .7;
  transition: opacity .5s var(--ease);
}

.catch__voice.is-active .catch__voice-corner { opacity: 1; }

.catch__voice-corner::before,
.catch__voice-corner::after {
  content: '';
  position: absolute;
  background: currentColor;
}

.catch__voice-corner::before { width: 6px; height: 1px; }
.catch__voice-corner::after { width: 1px; height: 6px; }

.catch__voice-corner--tl { top: 6px; left: 6px; }
.catch__voice-corner--tl::before { top: 0; left: 0; }
.catch__voice-corner--tl::after { top: 0; left: 0; }

.catch__voice-corner--tr { top: 6px; right: 6px; }
.catch__voice-corner--tr::before { top: 0; right: 0; }
.catch__voice-corner--tr::after { top: 0; right: 0; }

.catch__voice-corner--bl { bottom: 6px; left: 6px; }
.catch__voice-corner--bl::before { bottom: 0; left: 0; }
.catch__voice-corner--bl::after { bottom: 0; left: 0; }

.catch__voice-corner--br { bottom: 6px; right: 6px; }
.catch__voice-corner--br::before { bottom: 0; right: 0; }
.catch__voice-corner--br::after { bottom: 0; right: 0; }

.catch__voice-head {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: clamp(10px, 1.2vw, 14px);
  padding-bottom: clamp(8px, 1vw, 12px);
  border-bottom: 1px dashed var(--line-soft);
}

.catch__voice-letter {
  display: grid;
  place-items: center;
  width: clamp(28px, 3vw, 36px);
  height: clamp(28px, 3vw, 36px);
  border: 1px solid color-mix(in srgb, var(--voice-tone) 36%, transparent);
  border-radius: 50%;
  color: var(--voice-tone);
  font-family: var(--mono);
  font-size: clamp(11px, 1.1vw, 13px);
  letter-spacing: .04em;
  background: color-mix(in srgb, var(--voice-tone) 8%, transparent);
}

.catch__voice-stack {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.catch__voice-name {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(15px, 1.4vw, 18px);
  letter-spacing: -.018em;
  color: var(--paper);
}

.catch__voice-face {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--lead-3);
  opacity: .8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.catch__voice-now {
  position: absolute;
  top: -2px;
  right: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 18px;
  padding: 0 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--voice-tone) 18%, transparent);
  border: 1px solid color-mix(in srgb, var(--voice-tone) 40%, transparent);
  color: var(--voice-tone);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .28em;
  text-transform: uppercase;
}

.catch__voice-now::before {
  content: '';
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--voice-tone) 18%, transparent);
}

.catch__voice-pull {
  display: block;
  color: var(--voice-tone);
  opacity: .55;
  transition: opacity .5s var(--ease);
}

.catch__voice.is-active .catch__voice-pull { opacity: .95; }

.catch__voice-sample {
  display: grid;
  place-items: center;
  min-height: clamp(72px, 7vw, 108px);
  padding: clamp(8px, 1.2vw, 14px) 6px;
  text-align: center;
  color: var(--paper);
  font-size: clamp(1.65rem, 3.4vw, 2.6rem);
  line-height: 1;
  text-shadow: 0 1px 0 rgba(0, 0, 0, .2);
  transition: color .5s var(--ease);
}

.catch__voice--quiet .catch__voice-sample {
  color: color-mix(in srgb, var(--paper) 86%, var(--blue));
}

.catch__voice--human .catch__voice-sample {
  color: color-mix(in srgb, var(--paper) 78%, var(--coral));
}

.catch__voice--bold .catch__voice-sample {
  color: color-mix(in srgb, var(--paper) 60%, var(--acid));
  letter-spacing: -.05em;
}

.catch__voice.is-active .catch__voice-sample {
  color: var(--voice-tone);
}

.catch__voice-base {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding-top: clamp(8px, 1vw, 12px);
  border-top: 1px solid var(--line-soft);
  color: var(--lead-3);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.catch__voice-base-rule {
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--voice-tone) 38%, transparent), transparent);
  opacity: .65;
}

.catch__voice-base-rule--alt {
  background: linear-gradient(to left, transparent, color-mix(in srgb, var(--voice-tone) 38%, transparent), transparent);
}

.catch__voice-base-text {
  color: var(--voice-tone);
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
}

.catch__press-seal {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(14px, 1.8vw, 22px);
  padding: clamp(10px, 1.4vw, 18px) clamp(14px, 1.8vw, 24px);
  border: 1px solid var(--line);
  border-radius: 2px;
  background:
    radial-gradient(ellipse at 0% 50%, color-mix(in srgb, var(--catch-tone) 14%, transparent), transparent 60%),
    rgba(8, 12, 22, .42);
  z-index: 1;
}

.catch__press-seal svg {
  width: clamp(64px, 7vw, 96px);
  height: clamp(64px, 7vw, 96px);
  color: var(--catch-tone);
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--catch-tone) 18%, transparent));
}

.catch__press-seal-tag {
  display: grid;
  gap: 4px;
}

.catch__press-seal-tag-rule {
  height: 1px;
  background: linear-gradient(to right, color-mix(in srgb, var(--catch-tone) 60%, transparent), transparent);
  opacity: .55;
}

.catch__press-seal-tag-rule--alt {
  background: linear-gradient(to left, color-mix(in srgb, var(--catch-tone) 60%, transparent), transparent);
}

.catch__press-seal-tag em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.3vw, 17px);
  letter-spacing: -.012em;
  color: var(--paper);
}

.catch__foot {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  padding: clamp(10px, 1.2vw, 14px) clamp(12px, 1.4vw, 18px);
  border: 1px dashed var(--line-soft);
  border-radius: 1px;
  background: rgba(8, 12, 22, .28);
  z-index: 1;
}

.catch__foot-cell {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: baseline;
  gap: clamp(6px, .8vw, 10px);
}

.catch__foot-bead {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--catch-tone) 56%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--catch-tone) 14%, transparent);
  justify-self: center;
}

.catch__foot-key {
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--lead-3);
  opacity: .8;
  white-space: nowrap;
}

.catch__foot-value {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(12.5px, 1.15vw, 15px);
  letter-spacing: -.012em;
  color: var(--paper);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.catch__foot-mark {
  justify-self: start;
  margin-left: 4px;
  padding: 1px 7px;
  border: 1px solid color-mix(in srgb, var(--catch-tone) 40%, transparent);
  border-radius: 999px;
  color: var(--catch-tone);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .26em;
  text-transform: uppercase;
}

.catch__foot-cell--rule .catch__foot-value {
