/* ────────────────────────────────────────────────────────────
   TITLE LINE · the question gets to be the page. A single
   composed editorial moment: a slim running head, the headline
   set across three deliberate lines, three press marks drawn
   beneath, a clean voice strip, and a quiet footer. The
   question mark rides its own rule.
   ──────────────────────────────────────────────────────────── */

.titleline {
  position: relative;
  display: grid;
  gap: clamp(14px, 1.6vw, 22px);
  width: min(100%, 1080px);
  margin: clamp(6px, .8vw, 12px) auto clamp(20px, 2.4vw, 32px);
  padding: clamp(18px, 2.4vw, 32px) clamp(18px, 3vw, 40px) clamp(18px, 2.2vw, 28px);
  border: 1px solid color-mix(in srgb, var(--titleline-tone) 22%, transparent);
  border-radius: 2px;
  color: var(--paper);
  background:
    radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--titleline-tone) 14%, transparent), transparent 62%),
    radial-gradient(ellipse at 50% 100%, color-mix(in srgb, var(--titleline-tone) 8%, transparent), transparent 65%),
    linear-gradient(180deg, rgba(28, 30, 42, .62), rgba(14, 16, 24, .78));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .04),
    0 36px 88px -42px rgba(0, 0, 0, .62);
  isolation: isolate;
  transition: border-color .55s var(--ease), box-shadow .55s var(--ease);
  animation: titlelinePlateIn .9s var(--ease-out) .12s backwards;
}

.titleline::before {
  content: '';
  position: absolute;
  inset: 8px;
  border: 1px dashed color-mix(in srgb, var(--titleline-tone) 16%, transparent);
  border-radius: 1px;
  pointer-events: none;
  z-index: 0;
  transition: border-color .55s var(--ease);
}

.titleline > * { position: relative; z-index: 1; }

@keyframes titlelinePlateIn {
  0% { opacity: 0; transform: translateY(8px); filter: blur(4px); }
  100% { opacity: 1; transform: translateY(0); filter: blur(0); }
}

@media (prefers-reduced-motion: reduce) {
