}

.titleline__running-cell--voice {
  color: var(--paper);
}

.titleline__running-voice-letter {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(10.5px, .9vw, 12px);
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  line-height: 1;
  color: var(--titleline-tone);
  transition: color .5s var(--ease);
}

.titleline__running-voice-name {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
