  background: linear-gradient(180deg, rgba(28, 30, 42, .35), rgba(14, 16, 24, .55));
  color: var(--paper);
  font-family: var(--sans);
  text-align: left;
  cursor: pointer;
  transition: border-color .5s var(--ease), background .5s var(--ease), transform .55s var(--ease-spring), color .5s var(--ease);
  -webkit-tap-highlight-color: transparent;
}

.titleline__proof:hover,
.titleline__proof:focus-visible,
.titleline__proof.is-hover {
  border-color: color-mix(in srgb, var(--titleline-tone) 50%, transparent);
  transform: translateY(-1px);
  outline: none;
}

.titleline__proof:focus-visible {
  border-color: var(--acid);
}

.titleline__proof.is-active {
  border-color: var(--titleline-tone);
  background:
    radial-gradient(circle at 0 0, color-mix(in srgb, var(--titleline-tone) 16%, transparent), transparent 60%),
    linear-gradient(180deg, color-mix(in srgb, var(--titleline-tone) 8%, rgba(28, 30, 42, .5)), rgba(14, 16, 24, .65));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--titleline-tone) 22%, transparent),
    0 14px 32px -18px color-mix(in srgb, var(--titleline-tone) 45%, transparent);
}

.titleline__proof:active {
  transform: translateY(0) scale(.985);
  transition-duration: .12s;
}

.titleline__proof--m3 { --local-tone: var(--acid); }
.titleline__proof--good { --local-tone: var(--coral); }
.titleline__proof--yet { --local-tone: var(--blue); }

.titleline__proof-key {
  display: grid;
  grid-template-columns: auto;
  align-items: center;
  gap: 2px;
  text-align: center;
}

.titleline__proof-key-letter {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid color-mix(in srgb, var(--local-tone, var(--titleline-tone)) 50%, transparent);
  border-radius: 50%;
  color: var(--local-tone, var(--titleline-tone));
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11px, .9vw, 12px);
  letter-spacing: 0;
  line-height: 1;
  opacity: .9;
}

.titleline__proof:not(.is-active):not(.is-hover) .titleline__proof-key-letter {
  opacity: .5;
}

.titleline__proof-key-mark {
  display: inline-block;
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(7.5px, .68vw, 8.5px);
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
}

.titleline__proof.is-active .titleline__proof-key-mark {
  color: var(--local-tone, var(--titleline-tone));
}

.titleline__proof-glyph {
  display: grid;
  place-items: center;
  width: clamp(54px, 6vw, 78px);
  height: clamp(22px, 2.4vw, 30px);
  color: var(--local-tone, var(--titleline-tone));
}

.titleline__proof-svg {
  display: block;
  width: 100%;
  height: 100%;
  transition: opacity .5s var(--ease);
}

.titleline__proof-svg.is-quiet { opacity: .28; }
.titleline__proof-svg.is-active { opacity: 1; }

.titleline__proof-meta {
  display: grid;
  gap: 1px;
  min-width: 0;
  line-height: 1.05;
}

.titleline__proof-word {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(14px, 1.2vw, 17px);
  font-weight: 400;
  letter-spacing: -.012em;
  color: var(--paper);
  transition: color .5s var(--ease);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.titleline__proof.is-active .titleline__proof-word {
  color: var(--local-tone, var(--titleline-tone));
}

.titleline--voice-bold .titleline__proof-word {
  font-style: normal;
  font-weight: 600;
  letter-spacing: -.02em;
}

.titleline__proof-kind {
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(7.5px, .68vw, 8.5px);
  font-weight: 500;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.titleline__proof-active {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: var(--mono);
  font-size: clamp(7.5px, .68vw, 8.5px);
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
  align-self: center;
}

.titleline__proof.is-active .titleline__proof-active {
  color: var(--local-tone, var(--titleline-tone));
}

.titleline__proof-active-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 18%, transparent);
}

.titleline__proof:not(.is-active) .titleline__proof-active-dot {
  background: transparent;
  box-shadow: 0 0 0 1px currentColor;
}

/* — Proof-glyph strokes — */

.titleline__proof-stet-stroke,
.titleline__proof-arrow,
.titleline__proof-bead {
  opacity: 0;
}

.titleline__proof.is-active .titleline__proof-stet-stroke {
  opacity: 1;
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titlelineProofStetDraw .55s var(--ease-out) forwards;
}

.titleline__proof.is-active .titleline__proof-arrow {
  opacity: .85;
  animation: titlelineProofFade .35s var(--ease-out) .55s forwards;
}

.titleline__proof.is-active .titleline__proof-bead--lead {
  opacity: 1;
  animation: titlelineProofFade .35s var(--ease-out) .25s forwards;
}

.titleline__proof.is-active .titleline__proof-bead--trail {
  opacity: 1;
  animation: titlelineProofFade .35s var(--ease-out) .5s forwards;
}

.titleline__proof.is-active .titleline__proof-caret-curve {
  opacity: 1;
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titlelineProofCaretDraw .55s var(--ease-out) forwards;
}

.titleline__proof.is-active .titleline__proof-caret-point {
  opacity: 1;
  animation: titlelineProofFade .3s var(--ease-spring) .55s forwards;
}

.titleline__proof.is-active .titleline__proof-query-ring {
  opacity: 1;
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titlelineProofQueryRing .65s var(--ease-out) forwards;
}

.titleline__proof.is-active .titleline__proof-query-hook {
  opacity: 1;
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titlelineProofQueryHook .55s var(--ease-out) .35s forwards;
}

.titleline__proof.is-active .titleline__proof-query-dot {
  opacity: 1;
  animation: titlelineProofFade .35s var(--ease-out) .9s forwards;
}

.titleline__proof:not(.is-active) .titleline__proof-stet-stroke,
.titleline__proof:not(.is-active) .titleline__proof-arrow,
.titleline__proof:not(.is-active) .titleline__proof-caret-curve,
.titleline__proof:not(.is-active) .titleline__proof-caret-point,
.titleline__proof:not(.is-active) .titleline__proof-query-ring,
.titleline__proof:not(.is-active) .titleline__proof-query-hook,
.titleline__proof:not(.is-active) .titleline__proof-query-dot,
.titleline__proof:not(.is-active) .titleline__proof-bead {
  opacity: 0;
  animation: none;
}

.titleline__proof.is-quiet .titleline__proof-stet-stroke,
.titleline__proof.is-quiet .titleline__proof-arrow,
.titleline__proof.is-quiet .titleline__proof-caret-curve,
.titleline__proof.is-quiet .titleline__proof-caret-point,
.titleline__proof.is-quiet .titleline__proof-query-ring,
.titleline__proof.is-quiet .titleline__proof-query-hook,
.titleline__proof.is-quiet .titleline__proof-query-dot,
.titleline__proof.is-quiet .titleline__proof-bead {
  opacity: 1;
  animation: none;
}

@keyframes titlelineProofStetDraw { to { stroke-dashoffset: 0; } }
@keyframes titlelineProofCaretDraw { to { stroke-dashoffset: 0; } }
@keyframes titlelineProofQueryRing { to { stroke-dashoffset: 0; } }
@keyframes titlelineProofQueryHook { to { stroke-dashoffset: 0; } }
@keyframes titlelineProofFade { to { opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  .titleline__proof-stet-stroke,
  .titleline__proof-arrow,
  .titleline__proof-caret-curve,
  .titleline__proof-caret-point,
  .titleline__proof-query-ring,
  .titleline__proof-query-hook,
  .titleline__proof-query-dot,
  .titleline__proof-bead {
    animation: none !important;
    stroke-dashoffset: 0 !important;
    opacity: 1 !important;
  }
  .titleline__proof-arrow { opacity: .85 !important; }
  .titleline__proof:not(.is-active) .titleline__proof-stet-stroke,
  .titleline__proof:not(.is-active) .titleline__proof-arrow,
  .titleline__proof:not(.is-active) .titleline__proof-caret-curve,
  .titleline__proof:not(.is-active) .titleline__proof-caret-point,
  .titleline__proof:not(.is-active) .titleline__proof-query-ring,
  .titleline__proof:not(.is-active) .titleline__proof-query-hook,
  .titleline__proof:not(.is-active) .titleline__proof-query-dot,
  .titleline__proof:not(.is-active) .titleline__proof-bead { opacity: .18 !important; }
}

/* — Footer · folio, marked at, set today — */

.titleline__footer {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(8px, 1vw, 14px);
  padding-top: clamp(8px, 1vw, 12px);
  border-top: 1px dashed color-mix(in srgb, var(--titleline-tone) 18%, transparent);
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 10px);
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--muted);
}

.titleline__footer-cell {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(6px, .7vw, 10px);
  white-space: nowrap;
}

.titleline__footer-key {
  color: var(--muted);
  opacity: .7;
}

.titleline__footer-value {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
}

.titleline__footer-value:first-of-type {
  color: var(--titleline-tone);
}

.titleline__footer-sep {
  display: inline-grid;
  place-items: center;
  width: 16px;
  height: 16px;
}

.titleline__footer-sep-bead {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--titleline-tone);
  opacity: .4;
}

/* — Voice strip · tighter, anchored below the proof marks — */

.titleline__voices {
  margin-top: clamp(4px, .6vw, 10px);
}

/* — Mobile tuning — */

@media (max-width: 820px) {
  .titleline {
    padding: clamp(14px, 3vw, 22px) clamp(14px, 3vw, 20px);
  }

  .titleline__running {
    grid-template-columns: 1fr;
