/* Inside the opening, the press-lever's button corners are
   redundant with the opening's own quiet frame. Hide them so the
   action button reads as a single quiet chip. */
.opening .press-lever__action-corner {
  display: none;
}

/* Inside the opening, the title-fold's seal stays — it is the
   signature mark of the headline itself, not of the broadside. */

.opening .title-fold__seal {
  top: clamp(-18px, -1.4vw, -10px);
  right: clamp(8px, 1.8vw, 22px);
}

/* ────────────────────────────────────────────────────────────
   QUESTION MONUMENT · folio i · the page's namesake statement,
   set as a single confident broadside. The question
   "is Minimax M3 good at frontend yet?" is the headline — a
   large, well-paced typographic lockup that takes the room
   the previous stacked frontmatter used to fill. Three
   clickable tokens (one per marked word), a single voice
   lockup beneath, and a quiet "this impression" footer close
   the composition. The decoration flatters (carries the
   voice, the kind, and the date) without competing with the
   line itself.
   ──────────────────────────────────────────────────────────── */

.question-monument {
  --qm-tone: var(--coral);
  --qm-tone-soft: color-mix(in srgb, var(--qm-tone) 14%, transparent);
  --qm-tone-line: color-mix(in srgb, var(--qm-tone) 38%, transparent);
  --qm-paper: rgba(243, 236, 214, .03);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  justify-items: center;
  row-gap: clamp(18px, 2vw, 28px);
  width: min(100%, 1100px);
  margin: clamp(22px, 2.8vw, 44px) auto clamp(36px, 4vw, 64px);
  padding: clamp(28px, 3.2vw, 48px) clamp(20px, 3vw, 56px) clamp(20px, 2.6vw, 36px);
  isolation: isolate;
  border: 1px solid color-mix(in srgb, var(--qm-tone) 14%, transparent);
  border-radius: 2px;
  background:
    radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--qm-tone) 12%, transparent), transparent 56%),
    radial-gradient(ellipse at 50% 100%, color-mix(in srgb, var(--qm-tone) 6%, transparent), transparent 62%),
    linear-gradient(180deg, rgba(20, 28, 40, .42), rgba(12, 16, 26, .6));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .035),
    inset 0 1px 0 rgba(243, 236, 214, .04),
    0 32px 80px -38px rgba(0, 0, 0, .55);
  opacity: 0;
  transform: translateY(10px);
  animation: qmArrive 1.05s var(--ease-out) .2s forwards;
}

@keyframes qmArrive {
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .question-monument {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .question-monument.is-impressing .question-monument__statement {
    transform: none !important;
    opacity: 1 !important;
  }
}

.question-monument__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

.question-monument__paper {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  opacity: .55;
  mix-blend-mode: overlay;
}

.question-monument__paper svg {
  display: block;
  width: 100%;
  height: 100%;
}

/* — Top cap: "the headline" · voice letter · rule — */

.question-monument__cap {
  position: relative;
  z-index: 3;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.4vw, 18px);
  width: 100%;
  color: var(--paper);
  font-family: var(--mono);
}

.question-monument__cap-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 3px 10px 4px;
  border: 1px solid var(--qm-tone-line);
  border-radius: 999px;
  background: rgba(14, 20, 32, .55);
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(7.5px, .72vw, 9px);
  font-weight: 600;
  letter-spacing: .28em;
  text-transform: uppercase;
}

.question-monument__cap-eyebrow-text {
  color: var(--qm-tone);
}

.question-monument__cap-eyebrow-mark {
  display: inline-block;
  width: 5px;
  height: 5px;
  background: var(--qm-tone);
  transform: rotate(45deg);
  opacity: .75;
}

.question-monument__cap-eyebrow-mark--alt { opacity: .4; }

.question-monument__cap-rule {
  display: block;
  width: 100%;
  height: clamp(8px, 1vw, 12px);
  color: var(--qm-tone);
}

.question-monument__cap-rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.question-monument__cap-rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: qmRuleDraw 1.2s var(--ease-out) .35s forwards;
}

@keyframes qmRuleDraw {
  to { stroke-dashoffset: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .question-monument__cap-rule-stroke { animation: none !important; stroke-dashoffset: 0 !important; }
}

.question-monument__cap-voice {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px 4px;
  border: 1px solid var(--qm-tone-line);
  border-radius: 999px;
  background: rgba(14, 20, 32, .55);
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(7.5px, .72vw, 9px);
  font-weight: 600;
  letter-spacing: .28em;
  text-transform: uppercase;
}

.question-monument__cap-voice-letter {
  display: inline-grid;
  place-items: center;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--qm-tone);
  color: var(--night);
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: 11px;
  letter-spacing: 0;
}

.question-monument__cap-voice-name {
  color: var(--paper);
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  font-weight: 500;
}

/* — Statement: the headline itself — */

.question-monument__statement {
  position: relative;
  z-index: 4;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  row-gap: clamp(2px, .4vw, 6px);
  width: 100%;
  margin: 0;
  text-align: center;
  font-feature-settings: 'kern' 1, 'liga' 1, 'calt' 1, 'ss01' 1;
  color: var(--paper);
  transition: opacity .35s var(--ease), transform .35s var(--ease);
}

.question-monument.is-impressing .question-monument__statement {
  opacity: .42;
  transform: translateY(3px);
}

.question-monument.is-impressing .question-monument__statement::after {
  content: '';
  position: absolute;
  inset: clamp(-8px, -1vw, -12px) clamp(-12px, -2vw, -24px);
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(90deg,
      transparent 0%,
      color-mix(in srgb, var(--qm-tone) 18%, transparent) 18%,
      color-mix(in srgb, var(--qm-tone) 32%, transparent) 50%,
      color-mix(in srgb, var(--qm-tone) 18%, transparent) 82%,
      transparent 100%);
  filter: blur(8px);
  animation: qmImpressBreath .82s var(--ease-out) forwards;
  opacity: .85;
}

@keyframes qmImpressBreath {
  0% { opacity: 0; transform: translateY(-4px); }
  35% { opacity: .85; }
  100% { opacity: 0; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .question-monument.is-impressing .question-monument__statement::after {
    animation: none !important;
    opacity: 0 !important;
  }
}

.question-monument__pressmark {
  display: block;
  width: clamp(140px, 16vw, 220px);
  height: clamp(6px, .8vw, 10px);
  margin: 0 auto clamp(10px, 1.2vw, 18px);
  color: var(--qm-tone);
  opacity: .65;
}

.question-monument__pressmark svg {
  display: block;
  width: 100%;
  height: 100%;
}

.question-monument__pressmark-stroke {
  stroke-dasharray: 220 60;
  stroke-dashoffset: 220;
  animation: questionMonumentPressmarkDraw 1.4s var(--ease-out) .4s forwards;
}

@keyframes questionMonumentPressmarkDraw {
  to { stroke-dashoffset: 0; }
}

.question-monument__pressmark-bead {
  opacity: 0;
  transform-origin: 276px 3px;
  animation: questionMonumentPressmarkBead .6s var(--ease-spring) 1.6s forwards;
}

@keyframes questionMonumentPressmarkBead {
  to { opacity: 1; transform: scale(1.2); }
}

@media (prefers-reduced-motion: reduce) {
  .question-monument__pressmark-stroke {
    stroke-dashoffset: 0 !important;
    animation: none !important;
  }
  .question-monument__pressmark-bead {
    opacity: 1 !important;
    animation: none !important;
    transform: none !important;
  }
}

.question-monument__line {
  display: inline-flex;
  align-items: baseline;
  justify-content: center;
  flex-wrap: wrap;
  column-gap: clamp(10px, 1.6vw, 22px);
  row-gap: clamp(2px, .4vw, 6px);
  font-size: clamp(2.4rem, 7.4vw, 6.4rem);
  line-height: 0.98;
  letter-spacing: inherit;
}

.question-monument__line-lead,
.question-monument__line-mid {
  display: inline-block;
  font-size: .84em;
  color: var(--paper);
  opacity: .82;
  font-style: inherit;
  letter-spacing: -.01em;
}

.question-monument__line-lead {
  margin-right: clamp(-2px, -.3vw, -1px);
}

.question-monument__line-mid {
  margin-left: clamp(-2px, -.3vw, -1px);
}

.question-monument--voice-bold .question-monument__line-lead,
.question-monument--voice-bold .question-monument__line-mid {
  font-style: normal;
  letter-spacing: -.062em;
  opacity: .9;
}

/* — Tokens (clickable marked words) — */

.question-monument__token {
