}

.question-monument__meta-value {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(12px, 1.04vw, 13.5px);
