}

.question-monument__meta-bead svg {
  display: block;
  width: 100%;
  height: 100%;
}

.question-monument__meta-cell--cycle .question-monument__meta-value {
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(7.5px, .68vw, 8.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--paper);
  align-items: center;
  gap: 4px;
}

.question-monument__meta-cell--cycle kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  padding: 1px 4px 2px;
  border: 1px solid color-mix(in srgb, var(--paper) 28%, transparent);
  border-radius: 2px;
  background: rgba(243, 236, 214, .06);
  font-family: var(--mono);
  font-size: clamp(7px, .62vw, 8px);
  letter-spacing: 0;
  text-transform: uppercase;
  color: var(--paper);
