/* — Voice tones (one per active voice) — */

.app--voice-quiet .question-monument { --qm-tone: var(--blue); }
.app--voice-human .question-monument { --qm-tone: var(--coral); }
.app--voice-bold .question-monument { --qm-tone: var(--acid); }

/* — Mobile tuning — */

@media (max-width: 820px) {
  .question-monument {
    padding: clamp(20px, 3vw, 28px) clamp(16px, 3vw, 22px) clamp(16px, 2.4vw, 22px);
