  }

  .question-monument__plate-stations {
    column-gap: clamp(6px, 1.2vw, 12px);
  }

  .question-monument__plate-wax { display: none; }

  .question-monument__station-face { display: none; }

  .question-monument__station.is-active .question-monument__station-face {
    display: block;
  }

  .question-monument__meta {
    justify-content: flex-start;
  }
