@media (max-width: 520px) {
  .question-monument__line {
    font-size: clamp(1.45rem, 8.4vw, 2rem);
  }

  .question-monument__query {
    font-size: 1em;
  }

  .question-monument__voice-face {
    display: none;
  }

  .question-monument__voice-now {
    display: none;
  }

  .question-monument__plate-eyebrow em { font-size: 11.5px; }

  .question-monument__station-letter {
    width: clamp(24px, 6.4vw, 32px);
