  }

  .question-monument__seal {
    top: -10px;
    right: 8px;
    width: 44px;
  }
}

/* ────────────────────────────────────────────────────────────
   EXHALATION PLATE · a single, hand-pressed plate that takes
   one breath between the reading floor and the answer. A
   centered quote restates the line in the active voice, three
   short breaths sit beneath it, and one decisive button hands
   the reader to folio viii. The whole thing reads as one
   composed card: top hairline, eyebrow, quote, breaths, sign,
   action, footer cells, bottom rule.
   ──────────────────────────────────────────────────────────── */

.exhalation {
  --exhalation-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(18px, 2.2vw, 28px);
  align-items: start;
  max-width: 920px;
  margin: clamp(40px, 5vw, 84px) auto;
  padding: clamp(28px, 3.6vw, 48px) clamp(22px, 3.4vw, 56px) clamp(24px, 3.2vw, 40px);
  border: 1px solid var(--line-soft);
  border-radius: 2px;
  isolation: isolate;
  background:
    radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--exhalation-tone) 9%, transparent), transparent 60%),
    radial-gradient(ellipse at 50% 100%, rgba(155, 188, 255, .03), transparent 64%),
    linear-gradient(180deg, rgba(20, 26, 38, .32), rgba(12, 16, 26, .52));
  box-shadow:
    inset 0 0 0 1px rgba(146, 186, 255, .03),
    inset 0 1px 0 rgba(243, 236, 214, .035),
    0 24px 56px -34px rgba(0, 0, 0, .45);
  color: var(--paper);
  opacity: 0;
  transform: translateY(12px);
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-out), border-color .5s var(--ease), background .5s var(--ease);
}

.exhalation.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.exhalation.is-stamping {
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--exhalation-tone) 26%, transparent),
    inset 0 1px 0 rgba(243, 236, 214, .045),
    0 0 0 1px color-mix(in srgb, var(--exhalation-tone) 20%, transparent),
    0 24px 56px -34px rgba(0, 0, 0, .45);
}

@media (prefers-reduced-motion: reduce) {
  .exhalation {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

.exhalation__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

.exhalation__rule {
  position: relative;
  display: block;
  width: 100%;
  height: 6px;
  margin: 0;
  color: var(--exhalation-tone);
  opacity: .85;
}

.exhalation__rule--bottom {
  opacity: .5;
  margin-top: clamp(2px, .3vw, 4px);
}

.exhalation__rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.exhalation__eyebrow {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.1vw, 14px);
  justify-self: center;
  color: var(--exhalation-tone);
  font-family: var(--mono);
  font-size: clamp(8.5px, .74vw, 9.5px);
  font-weight: 600;
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: .9;
}

.exhalation__eyebrow-mark {
  display: inline-block;
  width: clamp(14px, 1.4vw, 22px);
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.exhalation__eyebrow-mark--alt {
  background: linear-gradient(to right, currentColor, transparent);
}

.exhalation__eyebrow-key {
  color: var(--paper);
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-weight: 400;
  font-size: clamp(11.5px, 1.02vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
}

.exhalation__eyebrow-folio {
  opacity: .75;
}

.exhalation__quote {
  position: relative;
  display: grid;
  gap: clamp(8px, .9vw, 12px);
  justify-items: center;
  margin: 0;
  padding: clamp(8px, 1vw, 14px) 0 clamp(6px, .8vw, 10px);
