.exhalation--bold .exhalation__breath-line { font-style: normal; letter-spacing: .001em; font-weight: 500; }

.exhalation__sign {
  position: relative;
  display: block;
  width: clamp(160px, 28%, 240px);
  height: 14px;
  margin: clamp(-2px, -.2vw, -4px) auto clamp(2px, .2vw, 4px);
  color: var(--exhalation-tone);
  opacity: .8;
}

.exhalation__sign svg {
  display: block;
