.exhalation__sign-bead {
  opacity: 0;
  animation: traceDot .35s var(--ease-spring) 1.45s forwards;
}

.exhalation__action {
  position: relative;
  display: grid;
  gap: clamp(8px, 1vw, 14px);
  justify-items: center;
  padding-top: clamp(8px, 1vw, 14px);
  border-top: 1px solid color-mix(in srgb, var(--exhalation-tone) 22%, transparent);
}

.exhalation__action-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, .9vw, 12px);
  color: var(--exhalation-tone);
  font-family: var(--mono);
  font-size: clamp(8.5px, .74vw, 9.5px);
  font-weight: 600;
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: .85;
}

.exhalation__action-eyebrow-mark {
  display: inline-block;
  width: clamp(14px, 1.4vw, 20px);
