.exhalation__action-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  padding: clamp(11px, 1.3vw, 16px) clamp(18px, 2.2vw, 26px);
  border: 1px solid color-mix(in srgb, var(--exhalation-tone) 50%, transparent);
  border-radius: 1px;
  background:
    radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--exhalation-tone) 12%, transparent), transparent 70%),
