  .exhalation__foot-rule { display: none; }
  .exhalation__eyebrow { flex-wrap: wrap; justify-content: center; }
  .exhalation__quote-mark { right: 0; }
}

/* ──────────────────────────────────────────────────────────────────
   ITERATION 309 · THE QUESTION LINE
   A single hand-drawn inkline that threads the three marked words of
   the headline. The line is not a series of underlines beneath each
   word — it is one continuous stroke that visits all three, the way
   a pen would read the line aloud. Beads at each marked word carry
   the proof mark and label, and the active word draws the brightest.
   ────────────────────────────────────────────────────────────────── */

.question-line {
  display: block;
  width: min(100%, 1080px);
  margin: clamp(2px, .2vw, 6px) auto clamp(10px, 1.2vw, 18px);
  color: var(--question-line-tone, var(--coral));
  opacity: 0;
  transform: translateY(6px);
  animation: questionLineIn .85s var(--ease-out) 1.6s forwards;
  transition: color .5s var(--ease);
}

.app--voice-quiet .question-line { color: var(--blue); }
.app--voice-human .question-line { color: var(--coral); }
.app--voice-bold .question-line { color: var(--acid); }

.question-line__svg {
  display: block;
  width: 100%;
  height: clamp(40px, 4.4vw, 60px);
}

.question-line__wash {
  animation: questionLineWash 1.2s var(--ease-out) 1.4s forwards;
}

.question-line__stroke {
  animation: questionLineDraw 1.1s var(--ease-out) 1.45s forwards;
}

.question-line__rail {
  animation: questionLineRail 1.6s var(--ease) 2.6s forwards;
}

.question-line__halo-dot {
  transition: r .45s var(--ease-spring);
}

.question-line__bead-group {
  transform-box: fill-box;
  transform-origin: center;
  opacity: 0;
  animation: questionLineBead .55s var(--ease-spring) forwards;
}

.question-line__bead-group--m3 { animation-delay: 1.6s; }
.question-line__bead-group--good { animation-delay: 1.75s; }
.question-line__bead-group--yet { animation-delay: 1.9s; }

.question-line__bead-group.is-active.question-line__bead-group--m3 { animation-delay: 1.7s; }
.question-line__bead-group.is-active.question-line__bead-group--good { animation-delay: 1.85s; }
.question-line__bead-group.is-active.question-line__bead-group--yet { animation-delay: 2s; }

.question-line__bead-core,
.question-line__bead-glow,
.question-line__bead-ring {
  transition: r .45s var(--ease-spring), stroke-width .4s var(--ease);
}

.question-line__bead-group.is-active .question-line__bead-ring--outer {
  animation: questionLinePulse 3s var(--ease) infinite 2.4s;
}

.question-line__mark {
  opacity: 0;
  transform: translateY(4px);
  animation: questionLineMark .5s var(--ease-out) forwards;
}

.question-line__mark--m3 { animation-delay: 1.85s; }
.question-line__mark--good { animation-delay: 2s; }
.question-line__mark--yet { animation-delay: 2.15s; }

.question-line__mark.is-active,
.question-line__mark.is-hover {
  font-weight: 700;
  letter-spacing: .26em;
}

.question-line__mark.is-active text:last-child,
.question-line__mark.is-hover text:last-child {
  letter-spacing: .32em;
  opacity: 1;
}

.question-line__tail {
  animation: questionLineDraw .85s var(--ease-out) 2.45s forwards;
}

.question-line__tail-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  animation: questionLineTailBead .45s var(--ease-spring) 3.2s forwards;
}

@keyframes questionLineIn {
  to { opacity: 1; transform: translateY(0); }
}

@keyframes questionLineDraw {
  to { stroke-dashoffset: 0; }
}

@keyframes questionLineWash {
  0% { opacity: 0; }
  60% { opacity: .22; }
  100% { opacity: 0; }
}

@keyframes questionLineRail {
  to { opacity: .55; }
}

@keyframes questionLineBead {
  0% { opacity: 0; transform: scale(.4); }
  60% { opacity: 1; transform: scale(1.18); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes questionLineMark {
  to { opacity: 1; transform: translateY(0); }
}

@keyframes questionLinePulse {
  0% { transform: scale(.85); opacity: .35; }
  60% { transform: scale(1.4); opacity: 0; }
  100% { transform: scale(1.4); opacity: 0; }
}

@keyframes questionLineTailBead {
  0% { opacity: 0; transform: scale(.4); }
  60% { opacity: 1; transform: scale(1.6); }
  100% { opacity: 1; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .question-line,
  .question-line__stroke,
  .question-line__rail,
  .question-line__wash,
  .question-line__bead-group,
  .question-line__mark,
  .question-line__tail,
  .question-line__tail-bead {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }

  .question-line__bead-group.is-active .question-line__bead-ring--outer {
    animation: none !important;
  }
}

@media (max-width: 540px) {
  .question-line {
    margin-top: 0;
  }
  .question-line__svg {
    height: clamp(34px, 6vw, 48px);
  }
}

/* ────────────────────────────────────────────────────────────
   PAGE RETURN · the page's closing breath.
   A small, deliberate moment at the very end of the page that
   closes the drawn-arc narrative. After three outward exhalations
   (title question mark, lever pivot, answer period), this curl
   turns back inward — the answer has been received, the page
   can rest. A hand-drawn line spirals in from the right margin
   and settles on a small bead. Below it, a return-to-question
   anchor and a quiet closing signature.
   ──────────────────────────────────────────────────────────── */

.page-return {
  --page-return-tone: var(--paper);
  position: relative;
  display: grid;
  justify-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  width: min(100%, 640px);
  margin: clamp(56px, 8vw, 112px) auto clamp(40px, 5vw, 80px);
  padding: clamp(22px, 3.4vw, 36px) clamp(22px, 4vw, 52px) clamp(28px, 4vw, 44px);
  text-align: center;
  color: var(--paper);
}

.page-return--quiet { --page-return-tone: var(--blue); }
.page-return--human { --page-return-tone: var(--coral); }
.page-return--bold { --page-return-tone: var(--acid); }

.page-return__rule {
  display: block;
  width: clamp(120px, 22vw, 220px);
  height: 1px;
  background: linear-gradient(to right, transparent, var(--page-return-tone), transparent);
  opacity: .42;
}

.page-return__rule--trail { opacity: .32; }

.page-return__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
  color: var(--page-return-tone);
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .65s var(--ease) .15s, transform .85s var(--ease-out) .15s;
}

.page-return.is-revealed .page-return__eyebrow {
  opacity: .9;
  transform: translateY(0);
}

.page-return__eyebrow em {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: .04em;
  text-transform: lowercase;
  color: var(--paper);
  opacity: .85;
}

.page-return__eyebrow-mark {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  opacity: .7;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--page-return-tone) 14%, transparent);
}

.page-return__eyebrow-mark--alt { opacity: .55; }

.page-return__title {
  margin: 0;
  font-family: 'Iowan Old Style', 'Palatino Linotype', Georgia, serif;
  font-weight: 400;
  font-size: clamp(28px, 3.6vw, 44px);
  line-height: 1.05;
  letter-spacing: -.025em;
  color: var(--paper);
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .85s var(--ease) .35s, transform 1.05s var(--ease-out) .35s;
}

.page-return.is-revealed .page-return__title {
  opacity: 1;
  transform: translateY(0);
}

.page-return__title-em {
  font-style: italic;
  color: var(--page-return-tone);
  position: relative;
  padding: 0 .08em;
}

.page-return__curl-wrap {
  position: relative;
  display: grid;
  justify-items: center;
  width: clamp(220px, 30vw, 320px);
  margin: clamp(4px, .8vw, 10px) 0 clamp(2px, .4vw, 6px);
  color: var(--page-return-tone);
}

.page-return__curl-svg {
  display: block;
  width: 100%;
  height: clamp(76px, 8vw, 116px);
  overflow: visible;
}

.page-return__curl-tail {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  opacity: 0;
  transition: stroke-dashoffset .9s var(--ease-out) .65s, opacity .35s var(--ease) .65s;
}

.page-return.is-revealed .page-return__curl-tail {
  stroke-dashoffset: 0;
  opacity: .55;
}

.page-return__curl-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.6s var(--ease-out) .85s;
}

.page-return.is-revealed .page-return__curl-stroke {
  stroke-dashoffset: 0;
}

.page-return__curl-stroke-trail {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.55s var(--ease-out) 1.05s, opacity .55s var(--ease) 1.05s;
  opacity: 0;
}

.page-return.is-revealed .page-return__curl-stroke-trail {
  stroke-dashoffset: 0;
  opacity: .5;
}

.page-return__curl-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.4);
  transition: opacity .5s var(--ease) 2.35s, transform .6s var(--ease-spring) 2.35s;
}

.page-return.is-revealed .page-return__curl-bead {
  opacity: 1;
  transform: scale(1);
}

.page-return__curl-halo {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .55s var(--ease) 2.5s;
}

.page-return.is-revealed .page-return__curl-halo {
  opacity: .7;
  animation: pageReturnCurlPulse 4.8s var(--ease) infinite 2.95s;
}

.page-return__curl-seed {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.4);
  transition: opacity .4s var(--ease) .75s, transform .5s var(--ease-spring) .75s;
}

.page-return.is-revealed .page-return__curl-seed {
  opacity: .85;
  transform: scale(1);
}

@keyframes pageReturnCurlPulse {
  0%   { transform: scale(.85); opacity: .7; }
  60%  { transform: scale(1.5);  opacity: 0; }
  100% { transform: scale(1.5);  opacity: 0; }
}

.page-return__curl-caption {
  position: absolute;
  right: clamp(-12px, -1vw, 4px);
  top: 18%;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(9.5px, .78vw, 11px);
  color: var(--page-return-tone);
  letter-spacing: .04em;
  opacity: 0;
  transform: translateY(-3px);
  transition: opacity .55s var(--ease) 2.55s, transform .7s var(--ease-out) 2.55s;
  pointer-events: none;
  white-space: nowrap;
}

.page-return.is-revealed .page-return__curl-caption {
  opacity: .78;
  transform: translateY(0);
}

.page-return__curl-caption-rule {
  display: inline-block;
  width: clamp(8px, 1.4vw, 14px);
  height: 1px;
  background: currentColor;
  opacity: .65;
}

.page-return__curl-caption-mark {
  display: inline-block;
  font-size: 90%;
  opacity: .55;
}

.page-return__caption {
  margin: 0;
  max-width: 36em;
  font-family: 'Iowan Old Style', Georgia, serif;
  font-size: clamp(13.5px, 1.18vw, 16px);
  line-height: 1.55;
  letter-spacing: .005em;
  color: color-mix(in srgb, var(--paper) 84%, transparent);
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .75s var(--ease) 1.35s, transform .95s var(--ease-out) 1.35s;
}

.page-return__caption em {
  font-style: italic;
  color: var(--page-return-tone);
}

.page-return.is-revealed .page-return__caption {
  opacity: 1;
  transform: translateY(0);
}

.page-return__caption--quiet {
  margin-top: -2px;
  font-size: clamp(11.5px, .95vw, 13px);
  color: var(--muted);
  letter-spacing: .04em;
  transition-delay: 1.55s;
}

.page-return__caption--quiet em {
  font-style: italic;
  color: color-mix(in srgb, var(--paper) 78%, transparent);
}

.page-return__back {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: clamp(4px, .6vw, 10px);
  padding: 6px 14px 6px 12px;
  font-family: var(--mono);
  font-size: clamp(9.5px, .85vw, 11px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--page-return-tone);
  border: 1px solid color-mix(in srgb, var(--page-return-tone) 36%, transparent);
  border-radius: 999px;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .65s var(--ease) 1.75s, transform .85s var(--ease-out) 1.75s, gap .3s var(--ease-out), border-color .35s var(--ease), color .35s var(--ease);
}

.page-return.is-revealed .page-return__back {
  opacity: 1;
  transform: translateY(0);
}

.page-return__back:hover,
.page-return__back:focus-visible {
  gap: 12px;
  border-color: var(--page-return-tone);
  color: var(--paper);
}

.page-return__back svg {
  width: 12px;
  height: 12px;
  transition: transform .3s var(--ease-out);
}

.page-return__back:hover svg,
.page-return__back:focus-visible svg {
  transform: translateX(-2px);
}

.page-return__signature {
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  margin-top: clamp(8px, 1vw, 14px);
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(10.5px, .88vw, 12px);
  letter-spacing: .06em;
  color: var(--muted);
  opacity: 0;
  transition: opacity .65s var(--ease) 2.05s;
}

.page-return.is-revealed .page-return__signature {
  opacity: .8;
}

.page-return__signature-rule {
  width: clamp(28px, 4vw, 48px);
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor, transparent);
  opacity: .55;
}

.page-return__signature-rule--trail {
  background: linear-gradient(to left, transparent, currentColor, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .page-return__eyebrow,
  .page-return__title,
  .page-return__caption,
  .page-return__back,
  .page-return__signature {
    transition: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .page-return__eyebrow { opacity: .9 !important; }
  .page-return__curl-stroke,
  .page-return__curl-stroke-trail,
  .page-return__curl-tail {
    stroke-dashoffset: 0 !important;
    transition: none !important;
  }
  .page-return__curl-stroke-trail { opacity: .5 !important; }
  .page-return__curl-tail { opacity: .55 !important; }
  .page-return__curl-bead,
  .page-return__curl-halo,
  .page-return__curl-seed {
    transition: none !important;
    animation: none !important;
  }
  .page-return__curl-bead,
  .page-return__curl-seed { opacity: 1 !important; transform: none !important; }
  .page-return__curl-halo { opacity: .7 !important; }
  .page-return__back { opacity: 1 !important; transform: none !important; }
}

@media (max-width: 720px) {
  .page-return {
    margin: clamp(48px, 9vw, 80px) auto clamp(36px, 6vw, 60px);
    padding-left: clamp(18px, 5vw, 32px);
    padding-right: clamp(18px, 5vw, 32px);
  }
  .page-return__title {
    font-size: clamp(26px, 7vw, 36px);
  }
  .page-return__curl-svg {
    height: clamp(70px, 18vw, 100px);
  }
  .page-return__curl-caption {
    right: -2px;
    top: 22%;
  }
}

@media (max-width: 480px) {
  .page-return__signature-rule {
    width: 22px;
  }
  .page-return__caption {
    font-size: clamp(12.5px, 3.6vw, 14px);
  }
}

/* ────────────────────────────────────────────────────────────
   ARRIVAL MARK · a top-of-page press masthead.
   The page announces itself before the question arrives —
   a hairline drawn rule either side of a small seed that
   names the press, sets the date, and shows the three
   voice dots as a quiet row of switches. After four outward
   exhalations (title question mark, lever pivot, answer
   period, return curl) this becomes the first inward
   gesture: the page, set today.
   ──────────────────────────────────────────────────────────── */

.arrival-mark {
  --arrival-tone: var(--paper);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  align-items: center;
  row-gap: clamp(10px, 1.2vw, 16px);
  column-gap: clamp(14px, 1.6vw, 24px);
  width: min(100%, 920px);
  margin: clamp(18px, 2.6vw, 36px) auto clamp(8px, 1.2vw, 18px);
  padding: 0 clamp(8px, 1.4vw, 22px);
  color: var(--paper);
  text-align: center;
  isolation: isolate;
  opacity: 0;
  transform: translateY(4px);
  animation: arrivalMarkIn 1.05s var(--ease-out) .2s forwards;
}

.app--voice-quiet .arrival-mark { --arrival-tone: var(--blue); }
.app--voice-human .arrival-mark { --arrival-tone: var(--coral); }
.app--voice-bold .arrival-mark { --arrival-tone: var(--acid); }

.arrival-mark::before {
  content: '';
  position: absolute;
  inset: 50% 0 auto 0;
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--arrival-tone) 26%, transparent) 18%, color-mix(in srgb, var(--arrival-tone) 26%, transparent) 82%, transparent);
  opacity: .35;
  pointer-events: none;
  z-index: 0;
}

.arrival-mark__defs {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
}

.arrival-mark__greeting {
  grid-column: 1 / -1;
  grid-row: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, .9vw, 12px);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, 1.05vw, 13.5px);
  letter-spacing: -.005em;
  color: color-mix(in srgb, var(--paper) 74%, transparent);
  opacity: 0;
  transform: translateY(3px);
  animation: arrivalGreetingIn 1s var(--ease-out) .42s forwards;
}

.arrival-mark__greeting em {
  font-style: italic;
  font-family: var(--serif);
  letter-spacing: -.005em;
  color: var(--paper);
}

.arrival-mark__greeting-mark {
  display: inline-block;
  width: clamp(14px, 1.8vw, 26px);
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--arrival-tone) 50%, transparent));
  transform: translateY(-1px);
}

.arrival-mark__greeting-mark--alt {
  background: linear-gradient(to left, transparent, color-mix(in srgb, var(--arrival-tone) 50%, transparent));
}

@keyframes arrivalGreetingIn {
  to { opacity: 1; transform: translateY(0); }
}

.arrival-mark__descent {
  grid-column: 1 / -1;
  grid-row: 3;
  position: relative;
  display: grid;
  place-items: center;
  height: clamp(46px, 5.2vw, 78px);
  color: var(--arrival-tone);
  margin-top: clamp(2px, .3vw, 6px);
}

.arrival-mark__descent-svg {
  display: block;
  width: clamp(12px, 1.3vw, 18px);
  height: 100%;
  overflow: visible;
}

.arrival-mark__descent-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  opacity: 0;
  animation: arrivalDescentDraw 1.35s var(--ease-out) 1.95s forwards;
}

.arrival-mark__descent-stroke--trail {
  animation: arrivalDescentDraw 1.35s var(--ease-out) 2.15s forwards;
}

@keyframes arrivalDescentDraw {
  0% { stroke-dashoffset: 100; opacity: 0; }
  55% { opacity: 1; }
  100% { stroke-dashoffset: 0; opacity: 1; }
}

.arrival-mark__descent-bead {
  opacity: 0;
  transform: scale(.4);
  transform-origin: 50% 50%;
  animation: arrivalDescentBeadIn .55s var(--ease-spring) 3.05s forwards;
}

.arrival-mark__descent-halo {
  opacity: 0;
  animation: arrivalDescentHaloIn .7s var(--ease) 3.1s forwards;
}

@keyframes arrivalDescentBeadIn {
  to { opacity: 1; transform: scale(1); }
}

@keyframes arrivalDescentHaloIn {
  to { opacity: .6; }
}

.arrival-mark__descent-tag {
  position: absolute;
  bottom: calc(100% - 2px);
  left: 50%;
  transform: translate(-50%, -4px);
  display: inline-flex;
  align-items: center;
  gap: clamp(5px, .6vw, 8px);
  padding: 2px clamp(6px, .8vw, 10px);
  border-radius: 999px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--arrival-tone) 8%, transparent), transparent);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(9.5px, .82vw, 11px);
  letter-spacing: .04em;
  color: color-mix(in srgb, var(--paper) 70%, transparent);
  text-transform: lowercase;
  white-space: nowrap;
  opacity: 0;
  animation: arrivalDescentTagIn .7s var(--ease-out) 2.55s forwards;
}

.arrival-mark__descent-tag em {
  font-style: italic;
  color: var(--paper);
}

.arrival-mark__descent-tag-rule {
  display: inline-block;
  width: clamp(8px, 1vw, 14px);
  height: 1px;
  background: color-mix(in srgb, var(--arrival-tone) 38%, transparent);
}

.arrival-mark__descent-tag-rule--alt {
  opacity: .75;
}

@keyframes arrivalDescentTagIn {
  to { opacity: 1; transform: translate(-50%, 0); }
}

@keyframes arrivalMarkIn {
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0); }
}

.arrival-mark__rule {
  display: grid;
  align-items: center;
  height: 12px;
  color: color-mix(in srgb, var(--arrival-tone) 70%, transparent);
  position: relative;
  z-index: 1;
}

.arrival-mark__rule svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.arrival-mark__rule-stroke {
  animation: arrivalRuleDraw 1.35s var(--ease-out) .55s backwards;
}

.arrival-mark__rule-stroke--alt {
  animation: arrivalRuleDraw 1.35s var(--ease-out) .75s backwards;
  stroke-dasharray: 100 100;
}

@keyframes arrivalRuleDraw {
  0% { stroke-dashoffset: 100; opacity: 0; }
  60% { opacity: 1; }
  100% { stroke-dashoffset: 0; opacity: 1; }
}

.arrival-mark__rule-bead {
  opacity: 0;
  animation: arrivalBeadIn .5s var(--ease) 1.6s forwards;
}

.arrival-mark__rule-bead--end {
  animation-delay: 1.85s;
}

@keyframes arrivalBeadIn {
  to { opacity: 1; }
}

.arrival-mark__seed {
  display: inline-flex;
  align-items: center;
  gap: clamp(10px, 1.1vw, 16px);
  padding: clamp(6px, .8vw, 10px) clamp(14px, 1.6vw, 22px);
  border-radius: 999px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--arrival-tone) 6%, transparent), transparent);
  position: relative;
  z-index: 2;
}

.arrival-mark__seed-mark {
  display: inline-grid;
  place-items: center;
  width: clamp(22px, 2.2vw, 28px);
  height: clamp(22px, 2.2vw, 28px);
  color: var(--arrival-tone);
  opacity: 0;
  transform: scale(.4);
  animation: arrivalSeedMarkIn .6s var(--ease-spring) .8s forwards;
}

.arrival-mark__seed-mark svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.arrival-mark__seed-mark::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--arrival-tone) 22%, transparent), transparent 70%);
  z-index: -1;
  opacity: .7;
}

@keyframes arrivalSeedMarkIn {
  to { opacity: 1; transform: scale(1); }
}

.arrival-mark__seed-stack {
  display: grid;
  gap: 2px;
  text-align: left;
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--paper) 78%, transparent);
  opacity: 0;
  animation: arrivalSeedFade .8s var(--ease) 1.05s forwards;
}

@keyframes arrivalSeedFade {
  to { opacity: 1; }
}

.arrival-mark__seed-line {
  display: inline-flex;
  align-items: center;
  gap: clamp(4px, .5vw, 7px);
  white-space: nowrap;
}

.arrival-mark__seed-line--alt {
  color: color-mix(in srgb, var(--paper) 62%, transparent);
}

.arrival-mark__seed-em {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(10.5px, 1vw, 12.5px);
  letter-spacing: .04em;
  text-transform: lowercase;
  color: var(--paper);
  opacity: .92;
}

.arrival-mark__seed-key {
  color: color-mix(in srgb, var(--paper) 64%, transparent);
}

.arrival-mark__seed-sep {
  color: color-mix(in srgb, var(--arrival-tone) 70%, transparent);
  opacity: .75;
}

.arrival-mark__seed-voice {
  font-style: italic;
  text-transform: lowercase;
  letter-spacing: .04em;
  color: var(--arrival-tone);
  font-family: 'Iowan Old Style', Georgia, serif;
  font-size: clamp(10px, .94vw, 11.5px);
}

.arrival-mark__seed-voice-dots {
  display: inline-flex;
  align-items: center;
  gap: clamp(4px, .5vw, 6px);
  padding-left: clamp(6px, .8vw, 10px);
  border-left: 1px solid color-mix(in srgb, var(--arrival-tone) 32%, transparent);
  margin-left: clamp(2px, .3vw, 4px);
}

.arrival-mark__seed-voice-dot {
  display: grid;
  place-items: center;
  width: clamp(18px, 1.7vw, 22px);
  height: clamp(18px, 1.7vw, 22px);
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--paper) 28%, transparent);
  color: color-mix(in srgb, var(--paper) 56%, transparent);
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(10px, .9vw, 11.5px);
  letter-spacing: 0;
  text-transform: lowercase;
  transition: color .35s var(--ease), border-color .35s var(--ease), background .35s var(--ease), transform .45s var(--ease-spring), box-shadow .45s var(--ease);
  opacity: 0;
  transform: scale(.4);
}

.arrival-mark__seed-voice-dot:nth-child(1) { animation: arrivalDotIn .55s var(--ease-spring) 1.25s forwards; }
.arrival-mark__seed-voice-dot:nth-child(2) { animation: arrivalDotIn .55s var(--ease-spring) 1.4s forwards; }
.arrival-mark__seed-voice-dot:nth-child(3) { animation: arrivalDotIn .55s var(--ease-spring) 1.55s forwards; }

@keyframes arrivalDotIn {
  to { opacity: 1; transform: scale(1); }
}

.arrival-mark__seed-voice-dot.is-on {
  color: var(--arrival-tone);
  border-color: var(--arrival-tone);
  background: color-mix(in srgb, var(--arrival-tone) 18%, transparent);
  transform: scale(1.08);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--arrival-tone) 14%, transparent);
}

.arrival-mark__seed-voice-letter {
  line-height: 1;
}

@media (prefers-reduced-motion: reduce) {
  .arrival-mark,
  .arrival-mark__rule-stroke,
  .arrival-mark__rule-stroke--alt,
  .arrival-mark__rule-bead,
  .arrival-mark__seed-mark,
  .arrival-mark__seed-stack,
  .arrival-mark__seed-voice-dot,
  .arrival-mark__greeting,
  .arrival-mark__descent-stroke,
  .arrival-mark__descent-stroke--trail,
  .arrival-mark__descent-bead,
  .arrival-mark__descent-halo,
  .arrival-mark__descent-tag {
    animation: none !important;
    transition: none !important;
    opacity: 1 !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }
  .arrival-mark__rule-stroke--alt { opacity: .7 !important; }
  .arrival-mark__seed-voice-dot.is-on { transform: scale(1.08) !important; }
  .arrival-mark__descent-halo { opacity: .6 !important; }
}

@media (max-width: 720px) {
  .arrival-mark {
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    row-gap: clamp(8px, 1.4vw, 12px);
    column-gap: clamp(10px, 2vw, 16px);
    margin: clamp(14px, 3vw, 22px) auto clamp(6px, 1.4vw, 12px);
  }
  .arrival-mark__seed-stack {
    font-size: 8px;
    letter-spacing: .18em;
  }
  .arrival-mark__seed-em {
    font-size: 10px;
  }
  .arrival-mark__greeting {
    font-size: clamp(11px, 1.4vw, 12.5px);
  }
  .arrival-mark__descent {
    height: clamp(38px, 5.2vw, 56px);
  }
}

@media (max-width: 560px) {
  .arrival-mark {
    grid-template-columns: minmax(0, 1fr);
    row-gap: clamp(6px, 1.6vw, 10px);
    column-gap: clamp(6px, 1.6vw, 10px);
  }
  .arrival-mark__rule { display: none; }
  .arrival-mark__seed {
    flex-wrap: wrap;
    justify-content: center;
    gap: 6px 10px;
    padding: 8px 12px;
  }
  .arrival-mark__seed-stack {
    text-align: center;
    width: 100%;
    justify-items: center;
  }
  .arrival-mark__seed-line {
    justify-content: center;
    flex-wrap: wrap;
  }
  .arrival-mark__seed-voice-dots {
    border-left: 0;
    padding-left: 0;
    margin-left: 0;
  }
  .arrival-mark__greeting {
    font-size: 11px;
    letter-spacing: -.002em;
  }
  .arrival-mark__descent-tag {
    font-size: 9px;
  }
}

@media (max-width: 380px) {
  .arrival-mark__seed-voice-dots {
    display: none;
  }
  .arrival-mark__descent-tag {
    display: none;
  }
}

/* ──────────────────────────────────────────────────────────────────
   BROADSIDE RULE · a single, hand-drawn printer's device that closes
   the title page. Two hand-drawn rules draw inward from either side,
   meeting at a small press flower in the middle. Below the rule a
   single italic caption reads "and so the title page, set · turn the
   leaf", and a small footer carries the press identity. The device
   earns its place as the title page's maker's mark.
   ────────────────────────────────────────────────────────────────── */

.broadside-rule {
  --broadside-rule-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  column-gap: clamp(14px, 2vw, 28px);
  row-gap: clamp(10px, 1.4vw, 16px);
  padding: clamp(18px, 2.4vw, 32px) clamp(8px, 1.6vw, 22px) clamp(6px, 1vw, 14px);
  margin: clamp(20px, 3vw, 38px) auto 0;
  max-width: 88ch;
  color: var(--broadside-rule-tone);
  isolation: isolate;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 1s var(--ease-out) .05s, transform 1s var(--ease-out) .05s;
}

.broadside-rule.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.broadside-rule--quiet { --broadside-rule-tone: var(--blue); }
.broadside-rule--human { --broadside-rule-tone: var(--coral); }
.broadside-rule--bold { --broadside-rule-tone: var(--acid); }

.broadside-rule__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  visibility: hidden;
}

.broadside-rule__line {
  position: relative;
  display: block;
  width: 100%;
  height: clamp(10px, 1.2vw, 14px);
  color: var(--broadside-rule-tone);
}

.broadside-rule__line svg {
  width: 100%;
  height: 100%;
  display: block;
}

.broadside-rule__line-stroke {
  color: var(--broadside-rule-tone);
  stroke-dashoffset: 100;
  animation: broadsideRuleDraw 1.6s var(--ease-out) .15s forwards;
}

.broadside-rule__line-stroke--lead {
  transform-origin: left center;
}

.broadside-rule__line-stroke--trail {
  transform-origin: right center;
  animation-delay: .25s;
}

@keyframes broadsideRuleDraw {
  to { stroke-dashoffset: 0; }
}

.broadside-rule__line-bead {
  opacity: 0;
  animation: broadsideRuleBead .6s var(--ease-spring) 1.55s forwards;
}

.broadside-rule__line-bead--end {
  animation-delay: 1.7s;
}

@keyframes broadsideRuleBead {
  to { opacity: 1; }
}

.broadside-rule__device {
  position: relative;
  display: grid;
  place-items: center;
  width: clamp(64px, 7vw, 96px);
  height: clamp(64px, 7vw, 96px);
  color: var(--broadside-rule-tone);
}

.broadside-rule__device svg {
  width: 100%;
  height: 100%;
  display: block;
}

.broadside-rule__device-halo {
  transform-box: fill-box;
  transform-origin: center;
  animation: broadsideDeviceSpin 36s linear infinite;
  opacity: 0;
  animation: broadsideDeviceSpin 36s linear 1.6s infinite, broadsideHaloIn .8s var(--ease) 1.6s forwards;
}

@keyframes broadsideDeviceSpin {
  to { transform: rotate(360deg); }
}

@keyframes broadsideHaloIn {
  to { opacity: .5; }
}

.broadside-rule__device-spark {
  opacity: 0;
  animation: broadsideSparkIn .5s var(--ease) forwards;
}

.broadside-rule__device-spark--a { animation-delay: 1.4s; }
.broadside-rule__device-spark--b { animation-delay: 1.55s; }
.broadside-rule__device-spark--c { animation-delay: 1.7s; }
.broadside-rule__device-spark--d { animation-delay: 1.85s; }

@keyframes broadsideSparkIn {
  to { opacity: 1; }
}

.broadside-rule__device-mono {
  fill: var(--paper);
  opacity: .9;
}

.broadside-rule__caption {
  grid-column: 1 / -1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(6px, .8vw, 12px);
  margin: 0;
  padding: 0;
  color: var(--paper);
  font-family: 'Iowan Old Style', 'Palatino Linotype', Georgia, serif;
  font-style: italic;
  font-size: clamp(14.5px, 1.32vw, 18.5px);
  line-height: 1.4;
  letter-spacing: -.005em;
  text-align: center;
  text-wrap: balance;
}

.broadside-rule__caption-mark {
  display: inline-grid;
  place-items: center;
  color: var(--broadside-rule-tone);
  font-family: var(--mono);
  font-size: clamp(12px, 1.1vw, 14px);
  font-style: normal;
  letter-spacing: 0;
  opacity: .7;
}

.broadside-rule__caption-line {
  color: var(--paper);
}

.broadside-rule__caption-sep {
  color: color-mix(in srgb, var(--broadside-rule-tone) 65%, var(--paper));
  font-style: normal;
  opacity: .75;
}

.broadside-rule__caption-turn {
  color: color-mix(in srgb, var(--broadside-rule-tone) 78%, var(--paper));
  letter-spacing: .01em;
}

.broadside-rule__footer {
  grid-column: 1 / -1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(6px, .8vw, 12px);
  margin: clamp(2px, .4vw, 6px) 0 0;
  padding: clamp(8px, 1vw, 12px) clamp(10px, 1.4vw, 18px);
  border-top: 1px solid color-mix(in srgb, var(--broadside-rule-tone) 24%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--broadside-rule-tone) 24%, transparent);
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(9.5px, .9vw, 11px);
  letter-spacing: .18em;
  text-transform: uppercase;
  text-align: center;
}

.broadside-rule__footer-cell {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(4px, .5vw, 8px);
}

.broadside-rule__footer-key {
  color: color-mix(in srgb, var(--paper) 58%, transparent);
}

.broadside-rule__footer-value {
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11px, 1.05vw, 12.5px);
  letter-spacing: .04em;
  text-transform: lowercase;
  color: var(--broadside-rule-tone);
}

.broadside-rule__footer-bead {
  display: inline-grid;
  place-items: center;
  width: clamp(10px, 1vw, 12px);
  height: clamp(10px, 1vw, 12px);
  color: var(--broadside-rule-tone);
  opacity: .85;
}

.broadside-rule__footer-bead svg {
  width: 100%;
  height: 100%;
  display: block;
}

@media (prefers-reduced-motion: reduce) {
  .broadside-rule,
  .broadside-rule__line-stroke,
  .broadside-rule__line-bead,
  .broadside-rule__device-halo,
  .broadside-rule__device-spark,
  .broadside-rule__device-mono {
    animation: none !important;
    transition: none !important;
    opacity: 1 !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }
  .broadside-rule__device-halo { opacity: .5 !important; }
  .broadside-rule__device-spark { opacity: 1 !important; }
  .broadside-rule__device-spark--b,
  .broadside-rule__device-spark--d { opacity: .55 !important; }
}

@media (max-width: 720px) {
  .broadside-rule {
    padding: clamp(14px, 2.6vw, 22px) 4px clamp(4px, .8vw, 10px);
    column-gap: clamp(10px, 2.4vw, 18px);
  }
  .broadside-rule__device {
    width: clamp(54px, 9vw, 78px);
    height: clamp(54px, 9vw, 78px);
  }
  .broadside-rule__caption {
    font-size: 14px;
    letter-spacing: -.002em;
  }
  .broadside-rule__footer {
    font-size: 9.5px;
    letter-spacing: .14em;
    padding: clamp(6px, 1.2vw, 10px) clamp(8px, 1.6vw, 14px);
  }
}

@media (max-width: 480px) {
  .broadside-rule {
    grid-template-columns: minmax(0, 1fr);
    row-gap: clamp(10px, 2.4vw, 16px);
    text-align: center;
  }
  .broadside-rule__line {
    height: clamp(8px, 1.6vw, 12px);
  }
  .broadside-rule__device {
    margin: 0 auto;
  }
  .broadside-rule__footer-bead {
    display: none;
  }
}

/* ────────────────────────────────────
   PRESS PROVENANCE · a refined single-line
   imprint that sits above the title spread
   and declares the page's maker, volume,
   date, and voice in one editorial breath.
   Two drawn rules either side anchor it;
   a tiny m³ seal opens the line.
   ──────────────────────────────────── */

.press-provenance {
  --provenance-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(10px, 1.3vw, 18px);
  width: min(100%, 1080px);
  margin: clamp(6px, 1vw, 14px) auto clamp(14px, 1.8vw, 24px);
  padding: clamp(6px, .9vw, 12px) clamp(14px, 2vw, 26px);
  color: var(--provenance-tone);
  font-family: var(--serif);
  font-style: italic;
  isolation: isolate;
  opacity: 0;
  animation: pressProvenanceIn .85s var(--ease-out) .15s forwards;
}

.app--voice-quiet .press-provenance { --provenance-tone: var(--blue); }
.app--voice-human .press-provenance { --provenance-tone: var(--coral); }
.app--voice-bold .press-provenance { --provenance-tone: var(--acid); }

@keyframes pressProvenanceIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

.press-provenance__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  visibility: hidden;
}

.press-provenance__paper {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}

.press-provenance__rule {
  position: relative;
  display: block;
  flex: 0 0 auto;
  width: clamp(64px, 12vw, 180px);
  color: currentColor;
  opacity: 0;
  transform-origin: center;
  animation: pressProvenanceRuleDraw .9s var(--ease-out) .35s forwards;
  z-index: 1;
}

.press-provenance__rule--lead { transform-origin: right center; }
.press-provenance__rule--trail { transform-origin: left center; }

.press-provenance__rule-stroke {
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1s var(--ease-out);
}

.press-provenance.is-revealed .press-provenance__rule-stroke,
.press-provenance__rule-stroke {
  stroke-dashoffset: 0;
}

.press-provenance__rule-bead {
  opacity: 0;
  animation: pressProvenanceBead .4s var(--ease-spring) 1.1s forwards;
}

.press-provenance__rule--lead .press-provenance__rule-bead {
  transform-origin: right center;
}

.press-provenance__rule--trail .press-provenance__rule-bead {
  transform-origin: left center;
}

@keyframes pressProvenanceRuleDraw {
  from { opacity: 0; transform: scaleX(.4); }
  to { opacity: .85; transform: scaleX(1); }
}

@keyframes pressProvenanceBead {
  from { opacity: 0; transform: scale(.2); }
  to { opacity: 1; transform: scale(1); }
}

.press-provenance__seal {
  position: relative;
  flex: 0 0 auto;
  display: inline-grid;
  place-items: center;
  width: clamp(28px, 3vw, 40px);
  height: clamp(28px, 3vw, 40px);
  color: currentColor;
  opacity: 0;
  transform: rotate(-8deg) scale(.6);
  transform-origin: center;
  animation: pressProvenanceSealIn .65s var(--ease-spring) .5s forwards;
  z-index: 1;
}

@keyframes pressProvenanceSealIn {
  from { opacity: 0; transform: rotate(-22deg) scale(.4); }
  60% { opacity: 1; transform: rotate(2deg) scale(1.05); }
  to { opacity: 1; transform: rotate(-3deg) scale(1); }
}

.press-provenance__core {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  column-gap: clamp(8px, 1.1vw, 14px);
  row-gap: 4px;
  min-width: 0;
  z-index: 1;
}

.press-provenance__cell {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  color: var(--paper);
  font-size: clamp(12px, 1.05vw, 14.5px);
  letter-spacing: -.005em;
  line-height: 1.1;
  white-space: nowrap;
  font-style: italic;
}

.press-provenance__cell--press {
  position: relative;
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  color: var(--provenance-tone);
  font-family: var(--mono);
  font-style: normal;
  font-weight: 600;
  font-size: clamp(9.5px, .85vw, 11px);
  letter-spacing: .28em;
  text-transform: uppercase;
}

.press-provenance__press-mark {
  display: inline-grid;
  place-items: center;
  width: 12px;
  height: 12px;
  color: currentColor;
}

.press-provenance__press-mark svg {
  width: 100%;
  height: 100%;
  display: block;
}

.press-provenance__key {
  color: color-mix(in srgb, var(--paper) 55%, transparent);
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  font-weight: 500;
}

.press-provenance__em {
  color: var(--paper);
  font-style: italic;
  font-weight: 500;
  font-size: clamp(13px, 1.18vw, 16px);
  letter-spacing: -.012em;
