/* ────────────────────────────────────────────────────────────
   TITLE LAMP · a single hand-drawn lamp mark that hangs above
   the title fold. The press lights once, the page is lit, and
   the question can be read. A short italic line and a soft
   halo give the moment a quiet, deliberate arrival.
   ──────────────────────────────────────────────────────────── */

.title-lamp {
  --title-lamp-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  column-gap: clamp(16px, 2.4vw, 36px);
  row-gap: clamp(8px, 1vw, 14px);
  padding: clamp(28px, 3.2vw, 56px) clamp(14px, 2.4vw, 36px) clamp(14px, 1.8vw, 26px);
  margin: clamp(20px, 2.6vw, 42px) auto clamp(8px, 1vw, 16px);
  max-width: min(94ch, 92vw);
  color: var(--title-lamp-tone);
  isolation: isolate;
  opacity: 0;
  transform: translateY(8px);
  animation: titleLampIn 1.1s var(--ease-out) .25s forwards;
}

.title-lamp--quiet { --title-lamp-tone: var(--blue); }
.title-lamp--human { --title-lamp-tone: var(--coral); }
.title-lamp--bold { --title-lamp-tone: var(--acid); }

@keyframes titleLampIn {
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .title-lamp { animation: none !important; opacity: 1 !important; transform: none !important; }
}

.title-lamp__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  visibility: hidden;
}

.title-lamp__rule {
  position: relative;
  display: block;
  width: 100%;
  height: clamp(8px, 1vw, 12px);
  color: var(--title-lamp-tone);
}

.title-lamp__rule--lead {
  grid-column: 1;
  grid-row: 1;
}

.title-lamp__rule--trail {
  grid-column: 3;
  grid-row: 1;
}

.title-lamp__rule svg {
  width: 100%;
  height: 100%;
  display: block;
}

.title-lamp__rule-stroke {
  stroke-dashoffset: 100;
  animation: titleLampRuleDraw 1.6s var(--ease-out) .35s forwards;
}

.title-lamp__rule-stroke--lead {
  transform-origin: right center;
}

.title-lamp__rule-stroke--trail {
  transform-origin: left center;
  animation-delay: .5s;
}

@keyframes titleLampRuleDraw {
  to { stroke-dashoffset: 0; }
}

.title-lamp__halo {
  position: absolute;
  top: 50%;
  left: 50%;
  width: clamp(220px, 28vw, 360px);
  height: clamp(140px, 18vw, 220px);
  transform: translate(-50%, -50%);
  pointer-events: none;
  color: var(--title-lamp-tone);
  opacity: 0;
  animation: titleLampHaloIn 1.4s var(--ease-out) .6s forwards;
  z-index: 0;
}

.title-lamp__halo svg {
  width: 100%;
  height: 100%;
  display: block;
}

.title-lamp__halo-fill {
  transform-origin: center;
  animation: titleLampHaloPulse 6s var(--ease) 2s infinite;
}

@keyframes titleLampHaloIn {
  to { opacity: .9; }
}

@keyframes titleLampHaloPulse {
  0%, 100% { transform: scale(1); opacity: .85; }
  50% { transform: scale(1.06); opacity: 1; }
}

.title-lamp__cage {
  position: relative;
  display: grid;
  place-items: center;
  width: clamp(72px, 8vw, 112px);
  height: clamp(96px, 11vw, 132px);
  color: var(--title-lamp-tone);
  z-index: 1;
  grid-column: 2;
  grid-row: 1;
}

.title-lamp__cage svg {
  width: 100%;
  height: 100%;
  display: block;
}

.title-lamp__ray {
  stroke-dashoffset: 100;
  animation: titleLampRayDraw .9s var(--ease-out) .8s forwards;
}

.title-lamp__ray--b { animation-delay: .92s; }
.title-lamp__ray--c { animation-delay: 1.04s; }
.title-lamp__ray--d { animation-delay: 1.16s; }
.title-lamp__ray--e { animation-delay: 1.28s; }

@keyframes titleLampRayDraw {
  to { stroke-dashoffset: 0; }
}

.title-lamp__flame {
  transform-origin: center;
  transform-box: fill-box;
  animation: titleLampFlame 2.4s var(--ease) 1.4s infinite;
}

.title-lamp__flame-ring {
  transform-origin: center;
  transform-box: fill-box;
  animation: titleLampFlame 3.2s var(--ease) 1.6s infinite reverse;
}

.title-lamp__flame-tip {
  animation: titleLampFlameTip 1.8s var(--ease) 1.4s infinite;
  transform-origin: center;
  transform-box: fill-box;
}

@keyframes titleLampFlame {
  0%, 100% { transform: scale(1); opacity: 1; }
  35% { transform: scale(1.12, 1.18); opacity: .92; }
  60% { transform: scale(.94, .9); opacity: 1; }
}

@keyframes titleLampFlameTip {
  0%, 100% { transform: scale(1); opacity: .7; }
  50% { transform: scale(1.2, 1.05); opacity: 1; }
}

.title-lamp__glow {
  transform-origin: center;
  transform-box: fill-box;
  animation: titleLampGlow 4.5s var(--ease) 2s infinite;
}

@keyframes titleLampGlow {
  0%, 100% { opacity: .22; }
  50% { opacity: .42; }
}

.title-lamp__copy {
  grid-column: 1 / -1;
  position: relative;
  z-index: 1;
  margin: 0;
  padding: clamp(4px, .6vw, 10px) 0 0;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(8px, .9vw, 14px);
  color: var(--paper);
  font-family: 'Iowan Old Style', 'Palatino Linotype', Palatino, 'Book Antiqua', Georgia, serif;
  font-style: italic;
  font-size: clamp(15px, 1.5vw, 21px);
  line-height: 1.36;
  letter-spacing: -.005em;
  text-align: center;
  text-wrap: balance;
}

.title-lamp__copy-mark {
  display: inline-grid;
  place-items: center;
  width: 1.4em;
  height: 1.4em;
  color: var(--title-lamp-tone);
  font-style: normal;
  font-family: var(--serif);
  font-size: .92em;
  opacity: .85;
}

.title-lamp__copy-line {
  color: var(--paper);
  max-width: 30em;
}

.title-lamp__copy-tag {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 12px);
  padding: clamp(4px, .5vw, 8px) clamp(10px, 1.4vw, 16px);
  border: 1px solid color-mix(in srgb, var(--title-lamp-tone) 32%, transparent);
  border-radius: 999px;
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(10px, .9vw, 12px);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--paper) 88%, transparent);
}

.title-lamp__copy-tag em {
  color: var(--title-lamp-tone);
  font-style: normal;
  font-weight: 600;
  letter-spacing: .16em;
}

.title-lamp__copy-tag-mark {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--title-lamp-tone);
  opacity: .85;
}

.title-lamp__copy-tag-mark--alt { opacity: .35; }

.title-lamp__corner {
  position: absolute;
  width: clamp(12px, 1.4vw, 18px);
  height: clamp(12px, 1.4vw, 18px);
  border: 1px solid color-mix(in srgb, var(--title-lamp-tone) 42%, transparent);
  pointer-events: none;
  opacity: 0;
  animation: titleLampBeadIn .5s var(--ease) 1.4s forwards;
}

.title-lamp__corner--tl {
  top: 6px;
  left: 6px;
  border-right: 0;
  border-bottom: 0;
}

.title-lamp__corner--tr {
  top: 6px;
  right: 6px;
  border-left: 0;
  border-bottom: 0;
}

.title-lamp__corner--bl {
  bottom: 6px;
  left: 6px;
  border-right: 0;
  border-top: 0;
}

.title-lamp__corner--br {
  bottom: 6px;
  right: 6px;
  border-left: 0;
  border-top: 0;
}

@media (max-width: 720px) {
  .title-lamp {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto auto auto;
    text-align: center;
  }

  .title-lamp__rule {
    grid-column: 1;
    grid-row: auto;
  }

  .title-lamp__rule--lead { grid-row: 1; }
  .title-lamp__cage { grid-column: 1; grid-row: 2; margin: clamp(4px, 1vw, 8px) auto; }
  .title-lamp__rule--trail { grid-row: 3; }

  .title-lamp__copy {
    grid-row: 4;
    padding: clamp(6px, 1vw, 10px) clamp(6px, 2vw, 14px) 0;
  }
}

@keyframes titleLampBeadIn {
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .title-lamp__rule-stroke {
    stroke-dashoffset: 0 !important;
    animation: none !important;
  }

  .title-lamp__ray {
    stroke-dashoffset: 0 !important;
    animation: none !important;
  }

  .title-lamp__halo,
  .title-lamp__halo-fill,
  .title-lamp__flame,
  .title-lamp__flame-ring,
  .title-lamp__flame-tip,
  .title-lamp__glow,
  .title-lamp__corner {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

/* ────────────────────────────────────────────────────────────
   TITLE SIGIL · a single, hand-drawn octagonal seal that sits
   between the press provenance and the title lamp. Anchors
   the title page as an authored artifact: a confident device
   with the press mark at its center, eight cardinal petals,
   a soft tone halo, and a short italic undersong that changes
   with the active voice. A deliberate, restrained gesture.
   ──────────────────────────────────────────────────────────── */

.title-sigil {
  --title-sigil-tone: var(--blue);
  position: relative;
  display: grid;
  grid-template-columns: minmax(60px, 1fr) auto minmax(160px, 2fr) auto minmax(60px, 1fr);
  grid-template-areas: 'lead rule copy rule-trail trail';
  align-items: center;
  gap: clamp(10px, 1.6vw, 22px);
  width: min(100%, 880px);
  margin: clamp(14px, 2.4vw, 28px) auto clamp(10px, 1.6vw, 22px);
  padding: clamp(6px, 1vw, 12px) clamp(14px, 2vw, 28px);
  color: var(--title-sigil-tone);
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 1s var(--ease-out), transform 1s var(--ease-out);
  isolation: isolate;
}

.title-sigil.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.app--voice-quiet .title-sigil { --title-sigil-tone: var(--blue); }
.app--voice-human .title-sigil { --title-sigil-tone: var(--coral); }
.app--voice-bold .title-sigil  { --title-sigil-tone: var(--acid); }

.title-sigil__defs {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}

.title-sigil__rule {
  display: flex;
  align-items: center;
  color: currentColor;
  height: 10px;
  opacity: .85;
}

.title-sigil__rule--lead {
  grid-area: rule;
}

.title-sigil__rule--trail {
  grid-area: rule-trail;
}

.title-sigil__rule svg { width: 100%; height: 100%; display: block; }

.title-sigil__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.6s var(--ease-out) .25s;
}

.title-sigil.is-revealed .title-sigil__rule-stroke { stroke-dashoffset: 0; }

.title-sigil__rule-bead {
  opacity: 0;
  transition: opacity .9s var(--ease-out) 1.4s;
}

.title-sigil.is-revealed .title-sigil__rule-bead { opacity: 1; }

.title-sigil__device {
  grid-area: copy;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  width: clamp(78px, 9.4vw, 124px);
  height: clamp(78px, 9.4vw, 124px);
  margin: 0 auto;
  color: currentColor;
  isolation: isolate;
}

.title-sigil__device svg { width: 100%; height: 100%; display: block; }

.title-sigil__halo {
  opacity: 0;
  transform-origin: center;
  transform-box: fill-box;
  animation: titleSigilHaloIn 1.4s var(--ease-out) .2s forwards;
}

.title-sigil__octagon {
  opacity: 0;
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: titleSigilOctagonDraw 1.4s var(--ease-out) .15s forwards;
}

.title-sigil__octagon-inner {
  opacity: 0;
  animation: titleSigilOctagonIn 1.2s var(--ease-out) .65s forwards;
}

.title-sigil__octagon-ghost {
  opacity: 0;
  animation: titleSigilOctagonIn 1.4s var(--ease-out) .95s forwards;
}

.title-sigil__petal {
  opacity: 0;
  transform-origin: 120px 120px;
  transform-box: view-box;
  animation: titleSigilPetalIn .9s var(--ease-out) 1.05s forwards;
}

.title-sigil__petal--0 { animation-delay: 1.05s; }
.title-sigil__petal--1 { animation-delay: 1.12s; }
.title-sigil__petal--2 { animation-delay: 1.19s; }
.title-sigil__petal--3 { animation-delay: 1.26s; }
.title-sigil__petal--4 { animation-delay: 1.33s; }
.title-sigil__petal--5 { animation-delay: 1.4s; }
.title-sigil__petal--6 { animation-delay: 1.47s; }
.title-sigil__petal--7 { animation-delay: 1.54s; }

.title-sigil__spark {
  opacity: 0;
  animation: titleSigilSparkIn .9s var(--ease-out) 1.3s forwards;
}

.title-sigil__spark--a { animation-delay: 1.3s; }
.title-sigil__spark--b { animation-delay: 1.4s; }
.title-sigil__spark--c { animation-delay: 1.5s; }
.title-sigil__spark--d { animation-delay: 1.6s; }

@keyframes titleSigilHaloIn {
  0% { opacity: 0; transform: scale(.86); }
  60% { opacity: 1; }
  100% { opacity: .55; transform: scale(1); }
}

@keyframes titleSigilOctagonDraw {
  0% { opacity: 0; stroke-dashoffset: 100; }
  20% { opacity: 1; }
  100% { opacity: 1; stroke-dashoffset: 0; }
}

@keyframes titleSigilOctagonIn {
  0% { opacity: 0; }
  100% { opacity: .42; }
}

@keyframes titleSigilPetalIn {
  0% { opacity: 0; transform: scale(.4); }
  100% { opacity: .7; transform: scale(1); }
}

@keyframes titleSigilSparkIn {
  0% { opacity: 0; }
  100% { opacity: .6; }
}

.title-sigil__glyph {
  grid-area: trail;
  display: flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(10px, 1.05vw, 12px);
  letter-spacing: -.005em;
  color: currentColor;
  opacity: 0;
  transition: opacity .9s var(--ease-out) 1.6s;
}

.title-sigil.is-revealed .title-sigil__glyph { opacity: .92; }

.title-sigil__glyph-mark {
  font-family: var(--serif);
  font-size: clamp(14px, 1.4vw, 18px);
  font-style: normal;
  color: currentColor;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: clamp(20px, 2vw, 26px);
  height: clamp(20px, 2vw, 26px);
}

.title-sigil__glyph-line {
  width: clamp(14px, 1.6vw, 24px);
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.title-sigil__glyph-name {
  font-style: italic;
  letter-spacing: -.005em;
}

.title-sigil__copy {
  grid-area: lead;
  margin: 0;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1.1vw, 13px);
  line-height: 1.4;
  letter-spacing: -.005em;
  color: currentColor;
  opacity: 0;
  transition: opacity 1s var(--ease-out) 1.45s;
}

.title-sigil.is-revealed .title-sigil__copy { opacity: .85; }

.title-sigil__copy-line {
  display: block;
  font-style: italic;
}

@media (max-width: 720px) {
  .title-sigil {
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    grid-template-areas: 'copy device glyph';
    gap: clamp(8px, 2vw, 14px);
    text-align: left;
  }

  .title-sigil__rule { display: none; }

  .title-sigil__copy {
    font-size: clamp(10px, 2.6vw, 12px);
    line-height: 1.35;
  }

  .title-sigil__glyph {
    justify-content: flex-end;
    font-size: clamp(10px, 2.4vw, 12px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .title-sigil,
  .title-sigil__copy,
  .title-sigil__glyph {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }

  .title-sigil__rule-stroke {
    stroke-dashoffset: 0 !important;
    animation: none !important;
  }

  .title-sigil__halo,
  .title-sigil__octagon,
  .title-sigil__octagon-inner,
  .title-sigil__octagon-ghost,
  .title-sigil__petal,
  .title-sigil__spark {
    opacity: 1 !important;
    animation: none !important;
    transform: none !important;
    stroke-dashoffset: 0 !important;
  }
}

/* ────────────────────────────────────────────────────────────
   FIRST IMPRESSION · a single, hand-pressed mark that sits at
   the top of the title plate between the running-head caption
   and the headline. It replaces the prior TitleSigil + TitleLamp
   stack with one decisive gesture: a wax-stamped circular seal,
   a hand-drawn arrow and signature rule, a brief italic line,
   and a halo. The seal carries the page's own imprint ("FIRST ·
   IMPRESSION") and the active voice letter; the inscription
   states what was done. The piece reads as a single composition
   rather than two stacked ornaments.
   ──────────────────────────────────────────────────────────── */

.first-impression {
  --first-impression-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  grid-template-areas:
    'rule-lead seal rule-trail'
    'copy       copy  copy'
    'signature  signature signature';
  align-items: center;
  column-gap: clamp(14px, 2vw, 28px);
  row-gap: clamp(6px, .8vw, 12px);
  width: min(100%, 940px);
