  border: 1px solid color-mix(in srgb, var(--qm-tone) 14%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--paper) 8%, transparent),
    inset 0 -1px 0 color-mix(in srgb, var(--qm-tone) 10%, transparent);
  opacity: .95;
}

.question-monument::after {
  content: '';
  position: absolute;
  left: clamp(8px, 1.4vw, 18px);
  right: clamp(8px, 1.4vw, 18px);
  top: clamp(8px, 1.4vw, 18px);
  height: clamp(3px, .4vw, 6px);
  z-index: 0;
  pointer-events: none;
  background: linear-gradient(to bottom, color-mix(in srgb, var(--qm-tone) 18%, transparent), transparent);
  opacity: .55;
}

@media (max-width: 720px) {
  .question-monument::before {
    inset: clamp(6px, 1.6vw, 12px);
  }
  .question-monument::after {
    left: clamp(6px, 1.6vw, 12px);
    right: clamp(6px, 1.6vw, 12px);
    top: clamp(6px, 1.6vw, 12px);
  }
}

/* ────────────────────────────────────────────────────────────
   iteration 328 · TITLE CODA · strengthened to be the single
   considered closing mark of the title page. The coda now
   stands alone inside a thin plate, with no overlapping
   broadside rule behind it. A delicate pressed rule
   underwrites the gesture so the title page reads as closed.
   ──────────────────────────────────────────────────────────── */

.title-coda {
  margin: clamp(20px, 2.6vw, 32px) auto clamp(8px, 1vw, 14px);
  width: min(100%, 880px);
  padding: clamp(14px, 1.8vw, 22px) clamp(20px, 3vw, 36px);
  border: 1px solid color-mix(in srgb, var(--title-coda-tone) 18%, transparent);
  border-radius: 2px;
  background:
    radial-gradient(ellipse at 50% 50%, color-mix(in srgb, var(--title-coda-tone) 6%, transparent), transparent 70%),
    linear-gradient(180deg, rgba(20, 28, 42, .36), rgba(12, 16, 26, .5));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--title-coda-tone) 6%, transparent),
    inset 0 1px 0 rgba(243, 236, 214, .04);
}

.title-coda__copy {
  font-size: clamp(13.5px, 1.2vw, 16px);
  color: var(--paper);
}

.title-coda__copy-line {
  font-style: italic;
  letter-spacing: -.005em;
  color: var(--paper);
}

.title-coda__signature {
  margin-top: clamp(8px, 1vw, 14px);
}

/* ─────────────────────────────────────────────────────────────
   iteration 330 · READING HINGE · a single, hand-pressed line
   that sits between the headline (Question Monument) and the
   reading prologue. It earns its place by giving the question
   a graceful close and cueing the reader toward the next
   gesture on the page. One italic line, one small flourish,
   one wax drop — nothing more.
   ───────────────────────────────────────────────────────────── */

.reading-hinge {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: clamp(8px, 1vw, 14px);
  width: min(100%, 640px);
  margin: clamp(24px, 3vw, 42px) auto clamp(16px, 2vw, 28px);
  padding: clamp(14px, 1.8vw, 22px) clamp(20px, 3vw, 36px);
  color: var(--reading-hinge-tone, var(--coral));
  text-align: center;
  isolation: isolate;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-out);
}

.reading-hinge.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  .reading-hinge {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
}

.reading-hinge__rule {
  display: block;
  width: min(100%, 320px);
  height: 6px;
  position: relative;
}

.reading-hinge__rule svg {
  width: 100%;
  height: 100%;
  display: block;
}

.reading-hinge__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: readingHingeRuleIn 1.2s var(--ease-out) .25s forwards;
}

@keyframes readingHingeRuleIn {
  to { stroke-dashoffset: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .reading-hinge__rule-stroke {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }
}

.reading-hinge__copy {
  position: relative;
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(15px, 1.5vw, 19px);
  font-style: italic;
  letter-spacing: -.005em;
  line-height: 1.25;
}

.reading-hinge__copy-mark {
  display: inline-block;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  color: var(--reading-hinge-tone, var(--coral));
  opacity: .6;
  transform: translateY(-1px);
}

.reading-hinge__copy-mark--alt {
  transform: translateY(-1px) scaleX(-1);
}

.reading-hinge__copy-line {
  font-style: italic;
  color: var(--paper);
}

.reading-hinge__copy-em {
  font-style: italic;
  color: var(--reading-hinge-tone, var(--coral));
  font-weight: 500;
  position: relative;
  padding: 0 .15em;
}

.reading-hinge__copy-em::before,
.reading-hinge__copy-em::after {
  content: '';
  position: absolute;
  top: 60%;
  width: .35em;
  height: 1px;
  background: currentColor;
  opacity: .35;
}

.reading-hinge__copy-em::before {
  left: -.05em;
  transform: rotate(-12deg);
}

.reading-hinge__copy-em::after {
  right: -.05em;
  transform: rotate(12deg);
}

.reading-hinge__flourish {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  color: var(--reading-hinge-tone, var(--coral));
  opacity: .85;
}

.reading-hinge__flourish svg {
  width: clamp(72px, 8vw, 110px);
  height: clamp(8px, 1vw, 12px);
  display: block;
}

.reading-hinge__flourish-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: readingHingeRuleIn 1.4s var(--ease-out) .55s forwards;
}

@media (prefers-reduced-motion: reduce) {
  .reading-hinge__flourish-stroke {
    animation: none !important;
    stroke-dashoffset: 0 !important;
  }
}

.reading-hinge__flourish-tag {
  display: inline-flex;
