  letter-spacing: -.005em;
  text-transform: none;
  color: var(--reading-hinge-tone, var(--coral));
}

.reading-hinge__flourish-tag-mark {
  display: inline-block;
  width: clamp(8px, 1vw, 12px);
  height: 1px;
  background: currentColor;
