.reading-hinge__wax-bead {
  position: absolute;
  inset: 1px;
  border-radius: 50%;
  background: var(--reading-hinge-tone, var(--coral));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--reading-hinge-tone, var(--coral)) 35%, transparent);
}

.reading-hinge__wax-wisp {
  position: absolute;
  top: 100%;
  left: 50%;
  width: 1.4px;
  height: 8px;
  background: linear-gradient(to bottom, color-mix(in srgb, var(--reading-hinge-tone, var(--coral)) 70%, transparent), transparent);
  transform: translateX(-50%);
  border-radius: 1px;
}

@keyframes readingHingeWaxIn {
  0% { opacity: 0; transform: scale(.4) rotate(-12deg); }
