/* ─────────────────────────────────────────────────────────────
   iteration 332 · TITLE BROADSIDE — a single, confident
   frontispiece that absorbs the title page, the headline, and
   the voice selector into one composed moment. The page
   opens with a quiet eyebrow, a single press seal, the
   question typeset large in the active voice, an italic
   operator's note, an exhale pencil line, and the three
   voice stations reading like a single set of press plates.
   ───────────────────────────────────────────────────────────── */

.tb {
  --tb-tone-quiet: var(--blue);
  --tb-tone-human: var(--coral);
  --tb-tone-bold: var(--acid);
  --tb-tone: var(--tb-tone-quiet);
  --tb-rule: color-mix(in srgb, var(--tb-tone) 60%, transparent);
  --tb-ink: var(--paper);
  --tb-ink-soft: color-mix(in srgb, var(--paper) 70%, transparent);
  --tb-ink-mist: color-mix(in srgb, var(--paper) 38%, transparent);
  position: relative;
  isolation: isolate;
  display: grid;
  justify-items: center;
  row-gap: clamp(18px, 2.4vw, 32px);
  width: min(100%, 1080px);
  margin: clamp(36px, 5vw, 72px) auto clamp(34px, 4.4vw, 56px);
  padding: clamp(40px, 5.4vw, 80px) clamp(20px, 4vw, 56px) clamp(28px, 4vw, 56px);
  text-align: center;
  color: var(--tb-ink);
  opacity: 0;
  transform: translateY(14px);
  transition: background .6s var(--ease), opacity .9s var(--ease-out), transform .9s var(--ease-out);
}

.tb.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  .tb {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
  .tb.is-stamping .tb__statement,
  .tb.is-stamping .tb__seal {
    animation: none !important;
  }
}

.tb::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -2;
  border-radius: 2px;
  background:
    radial-gradient(ellipse 72% 50% at 50% 8%, color-mix(in srgb, var(--tb-tone) 14%, transparent), transparent 62%),
    radial-gradient(ellipse 60% 30% at 50% 100%, color-mix(in srgb, var(--tb-tone) 8%, transparent), transparent 68%),
    linear-gradient(180deg, color-mix(in srgb, var(--tb-tone) 4%, transparent), transparent 30%, transparent 70%, color-mix(in srgb, var(--tb-tone) 3%, transparent));
  pointer-events: none;
  opacity: 0;
  transition: opacity 1s var(--ease);
}

.tb.is-revealed::before { opacity: 1; }

.tb__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

.tb__paper {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: 2px;
  overflow: hidden;
  opacity: .55;
  mix-blend-mode: overlay;
}

.tb__paper svg {
  width: 100%;
  height: 100%;
  display: block;
}

/* plate corner marks */
.tb__plate {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}

.tb__plate-corner {
  position: absolute;
  width: 18px;
  height: 18px;
  color: var(--tb-tone);
  opacity: .7;
  transition: opacity .5s var(--ease), color .5s var(--ease);
}

.tb__plate-corner::before,
.tb__plate-corner::after {
  content: '';
  position: absolute;
  background: currentColor;
  border-radius: .5px;
}

.tb__plate-corner::before { width: 12px; height: 1px; }
.tb__plate-corner::after { width: 1px; height: 12px; }

.tb__plate-corner--tl { top: -2px; left: -2px; }
.tb__plate-corner--tl::before { top: 0; left: 0; }
.tb__plate-corner--tl::after { top: 0; left: 0; }

.tb__plate-corner--tr { top: -2px; right: -2px; }
.tb__plate-corner--tr::before { top: 0; right: 0; }
.tb__plate-corner--tr::after { top: 0; right: 0; }

.tb__plate-corner--bl { bottom: -2px; left: -2px; }
.tb__plate-corner--bl::before { bottom: 0; left: 0; }
.tb__plate-corner--bl::after { bottom: 0; left: 0; }

.tb__plate-corner--br { bottom: -2px; right: -2px; }
.tb__plate-corner--br::before { bottom: 0; right: 0; }
.tb__plate-corner--br::after { bottom: 0; right: 0; }

/* eyebrow / running head */
.tb__head {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  width: 100%;
  z-index: 2;
}

.tb__eyebrow {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(6px, .7vw, 10px);
  width: 100%;
  max-width: 760px;
  margin: 0;
  padding: 0;
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .28em;
  text-transform: uppercase;
  opacity: 0;
  animation: tbEyebrowIn .7s var(--ease-out) .25s forwards;
}

.tb__eyebrow em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--tb-tone);
  transition: color .5s var(--ease);
}

.tb__eyebrow-key {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  opacity: .82;
  transition: color .4s var(--ease);
}

.tb__eyebrow-key--set {
  margin-left: clamp(2px, .4vw, 6px);
}

.tb__eyebrow-sep {
  color: var(--ink-mist);
  opacity: .5;
}

.tb__eyebrow-mark {
  display: inline-block;
  width: clamp(16px, 1.6vw, 24px);
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor);
  opacity: .55;
  color: var(--tb-tone);
}

.tb__eyebrow-rule {
  display: block;
  flex: 1 1 auto;
  min-width: clamp(48px, 8vw, 120px);
  max-width: clamp(120px, 18vw, 200px);
  height: 4px;
  color: var(--tb-rule);
}

.tb__eyebrow-rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.tb__eyebrow-rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: tbRuleDraw 1.5s var(--ease-out) .55s forwards;
}

.tb__eyebrow-date {
  color: var(--tb-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
}

@keyframes tbEyebrowIn {
  to { opacity: 1; }
}

@keyframes tbRuleDraw {
  to { stroke-dashoffset: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .tb__eyebrow { animation: none !important; opacity: 1 !important; }
  .tb__eyebrow-rule-stroke { animation: none !important; stroke-dashoffset: 0 !important; }
}

/* seal */
.tb__seal {
  position: relative;
  display: grid;
  place-items: center;
  width: clamp(96px, 8.4vw, 124px);
  height: clamp(96px, 8.4vw, 124px);
  margin-top: clamp(4px, .6vw, 10px);
  color: var(--tb-tone);
  z-index: 2;
  opacity: 0;
  transform: rotate(-4deg) scale(.85);
  animation: tbSealIn 1.05s var(--ease-spring) .4s forwards;
  transition: color .5s var(--ease);
}

.tb__seal-halo {
  position: absolute;
  inset: -16px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--tb-tone) 28%, transparent), transparent 64%);
  opacity: .8;
  pointer-events: none;
  animation: tbSealHalo 3.6s var(--ease-soft) infinite;
}

@keyframes tbSealHalo {
  0%, 100% { transform: scale(1); opacity: .6; }
  50% { transform: scale(1.08); opacity: .85; }
}

.tb__seal-disc {
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 2px 0 color-mix(in srgb, var(--tb-tone) 18%, transparent));
}

.tb__seal-disc svg {
  width: 100%;
  height: 100%;
  display: block;
}

.tb__seal-tag {
  position: absolute;
  bottom: clamp(-4px, -.2vw, -2px);
  right: clamp(-4px, -.2vw, -2px);
  display: inline-grid;
  grid-auto-flow: column;
  align-items: center;
  gap: 4px;
  padding: 4px clamp(8px, .8vw, 11px);
  border-radius: 999px;
  background: color-mix(in srgb, var(--tb-tone) 92%, transparent);
  color: var(--night);
  font-family: var(--mono);
  font-size: clamp(8.5px, .75vw, 10px);
  font-weight: 700;
  letter-spacing: .18em;
  text-transform: uppercase;
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--tb-tone) 28%, transparent);
}

.tb__seal-tag-key {
  font-size: clamp(7px, .6vw, 8px);
  opacity: .85;
}

.tb__seal-tag-letter {
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: 0;
}

@keyframes tbSealIn {
  0% { opacity: 0; transform: rotate(-9deg) scale(.55); }
  60% { opacity: 1; transform: rotate(-1deg) scale(1.06); }
  100% { opacity: 1; transform: rotate(-3deg) scale(1); }
}

.tb.is-stamping .tb__seal-disc {
  animation: tbSealStamp .76s var(--ease-spring) both;
}

.tb.is-stamping .tb__seal-halo {
  animation: tbSealHaloBurst .76s var(--ease) both, tbSealHalo 3.6s var(--ease-soft) infinite;
}

@keyframes tbSealStamp {
  0% { transform: scale(1) rotate(0); }
  35% { transform: scale(1.18) rotate(-2deg); filter: drop-shadow(0 4px 0 color-mix(in srgb, var(--tb-tone) 28%, transparent)); }
  100% { transform: scale(1) rotate(0); }
}

@keyframes tbSealHaloBurst {
  0% { transform: scale(1); opacity: .6; }
  40% { transform: scale(1.6); opacity: 1; }
  100% { transform: scale(1); opacity: .6; }
}

@media (prefers-reduced-motion: reduce) {
  .tb__seal { animation: none !important; opacity: 1 !important; transform: rotate(-3deg) scale(1); }
  .tb__seal-halo { animation: none !important; }
}

/* statement (the headline) */
.tb__statement {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(6px, .8vw, 12px);
  width: 100%;
  margin: 0;
  padding: 0;
  z-index: 2;
}

.tb__statement-lead {
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  color: var(--tb-ink-soft);
  font-style: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  margin-right: clamp(4px, .6vw, 12px);
  opacity: 0;
  animation: tbLeadIn .55s var(--ease-out) .55s forwards;
}

@keyframes tbLeadIn {
  to { opacity: .78; }
}

.tb__statement-lines {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(2px, .3vw, 6px);
  margin: 0;
  padding: 0;
  font-size: clamp(38px, 7vw, 92px);
  line-height: 1;
  color: var(--tb-ink);
}

.tb__statement-static {
  font-size: inherit;
  line-height: inherit;
  color: inherit;
  font-style: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  margin-left: clamp(6px, .8vw, 14px);
}

.tb__line {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(8px, 1vw, 16px);
  opacity: 0;
  transform: translateY(8px);
  animation: tbLineIn .65s var(--ease-out) forwards;
}

.tb__line--a { animation-delay: .7s; }
.tb__line--b { animation-delay: .9s; }
.tb__line--c { animation-delay: 1.1s; }

.tb.is-stamping .tb__line {
  animation: tbLineStamp .8s var(--ease) both;
}

@keyframes tbLineIn {
  to { opacity: 1; transform: translateY(0); }
}

@keyframes tbLineStamp {
  0% { opacity: 1; transform: translateY(0); }
  35% { opacity: .55; transform: translateY(2px) scale(.998); }
  100% { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .tb__line { animation: none !important; opacity: 1 !important; transform: none !important; }
  .tb__statement-lead { animation: none !important; opacity: .85 !important; }
}

/* marked word tokens */
.tb__token {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  padding: clamp(2px, .3vw, 4px) clamp(2px, .3vw, 4px) clamp(8px, 1vw, 12px);
  background: transparent;
  border: 0;
  cursor: pointer;
  color: inherit;
  font: inherit;
  line-height: inherit;
  font-feature-settings: 'kern' 1, 'liga' 1;
}

.tb__token-text {
  position: relative;
  display: inline-block;
  padding: 0 clamp(2px, .3vw, 6px);
  transition: color .35s var(--ease), transform .35s var(--ease);
}

.tb__token-text::before {
  content: '';
  position: absolute;
  left: 4%;
  right: 4%;
  bottom: -.06em;
  height: .04em;
  background: currentColor;
  opacity: 0;
  transform: scaleX(.4);
  transform-origin: left center;
  transition: opacity .35s var(--ease), transform .5s var(--ease-out);
}

.tb__token:hover .tb__token-text,
.tb__token.is-hover .tb__token-text {
  color: var(--tb-tone);
}

.tb__token.is-marked .tb__token-text {
  color: var(--tb-tone);
}

.tb__token.is-marked .tb__token-text::before {
  opacity: .9;
  transform: scaleX(1);
}

.tb__token-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: clamp(6px, .6vw, 8px);
  height: clamp(16px, 1.6vw, 20px);
  padding: 0 clamp(6px, .6vw, 9px);
  border: 1px solid color-mix(in srgb, var(--tb-tone) 30%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--tb-tone) 7%, transparent);
  color: var(--tb-tone);
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9.5px);
  letter-spacing: .12em;
  text-transform: uppercase;
  opacity: .55;
  transition: opacity .35s var(--ease), background .35s var(--ease), border-color .35s var(--ease);
}

.tb__token.is-marked .tb__token-mark {
  opacity: 1;
  background: color-mix(in srgb, var(--tb-tone) 14%, transparent);
}

.tb__token:hover .tb__token-mark {
  opacity: .9;
}

.tb__token-mark-rule {
  display: none;
}

.tb__token-mark-glyph {
  display: inline-block;
  font-family: 'Iowan Old Style', Georgia, serif;
  font-style: italic;
  font-size: clamp(11px, .9vw, 13px);
  letter-spacing: 0;
  text-transform: none;
  line-height: 1;
}

.tb__token--good .tb__token-mark-glyph,
.tb__token--yet .tb__token-mark-glyph {
  font-family: var(--serif);
  font-style: italic;
}

.tb__token-mark-name {
  letter-spacing: .14em;
}

.tb__token:focus-visible {
  outline: none;
}

.tb__token:focus-visible .tb__token-mark {
  outline: 2px solid var(--tb-tone);
  outline-offset: 3px;
}

/* operator's note */
.tb__operator {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  justify-content: center;
  column-gap: clamp(8px, 1vw, 14px);
  row-gap: 4px;
  margin: clamp(2px, .4vw, 6px) 0 0;
  color: var(--tb-ink-soft);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.18vw, 15.5px);
  letter-spacing: -.005em;
  line-height: 1.4;
  z-index: 2;
  opacity: 0;
  animation: tbOperatorIn .85s var(--ease-out) 1.35s forwards;
}

.tb__operator em {
  font-style: italic;
  color: var(--tb-ink);
}

.tb__operator-mark {
  display: inline-block;
  color: var(--tb-tone);
  font-style: normal;
  font-family: var(--serif);
  font-size: 1.05em;
  opacity: .8;
}

.tb__operator-mark--alt {
  transform: scaleX(-1);
  display: inline-block;
}

@keyframes tbOperatorIn {
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .tb__operator { animation: none !important; opacity: 1 !important; }
}

/* exhale pencil line */
.tb__exhale {
  position: relative;
  display: grid;
  justify-items: center;
  gap: clamp(6px, .8vw, 10px);
  width: 100%;
  max-width: 480px;
  height: clamp(18px, 2.2vw, 28px);
  color: var(--tb-tone);
  opacity: 0;
  animation: tbExhaleIn .8s var(--ease-out) 1.55s forwards;
  z-index: 2;
}

.tb__exhale svg {
  display: block;
  width: 100%;
  height: 8px;
}

.tb__exhale-lead {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: tbRuleDraw 1.6s var(--ease-out) 1.7s forwards;
}

.tb__exhale-trail {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: tbRuleDraw 1.8s var(--ease-out) 1.9s forwards;
}

.tb__exhale-bead {
  opacity: 0;
  animation: tbExhaleBead .5s var(--ease-spring) 3.5s forwards;
}

.tb__exhale-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--tb-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(10.5px, .9vw, 12px);
  letter-spacing: -.002em;
  opacity: .82;
}

.tb__exhale-tag-mark {
  display: inline-block;
  width: clamp(10px, 1vw, 14px);
  height: 1px;
  background: currentColor;
  opacity: .6;
}

.tb__exhale-tag em {
  font-style: italic;
}

@keyframes tbExhaleIn {
  to { opacity: 1; }
}

@keyframes tbExhaleBead {
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .tb__exhale,
  .tb__exhale-lead,
  .tb__exhale-trail,
  .tb__exhale-bead {
    animation: none !important;
    opacity: 1 !important;
    stroke-dashoffset: 0 !important;
  }
}

/* voice selector */
.tb__voices {
  position: relative;
  display: grid;
  justify-items: center;
  gap: clamp(8px, 1vw, 14px);
  width: 100%;
  max-width: 760px;
  padding: clamp(12px, 1.6vw, 18px) clamp(14px, 1.8vw, 22px) clamp(14px, 1.8vw, 22px);
  border: 1px solid color-mix(in srgb, var(--tb-tone) 22%, transparent);
  border-radius: 2px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--tb-tone) 6%, transparent), transparent 86%),
    linear-gradient(180deg, rgba(20, 26, 38, .32), rgba(12, 16, 26, .48));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--tb-tone) 6%, transparent),
    inset 0 1px 0 rgba(243, 236, 214, .04);
  z-index: 2;
  opacity: 0;
  animation: tbVoicesIn .8s var(--ease-out) 1.7s forwards;
}

.tb__voices::before,
.tb__voices::after {
  content: '';
  position: absolute;
  width: 8px;
  height: 8px;
  color: var(--tb-tone);
  pointer-events: none;
  opacity: .65;
}

.tb__voices::before {
  top: 3px;
  left: 3px;
  border-top: 1px solid currentColor;
  border-left: 1px solid currentColor;
}

.tb__voices::after {
  bottom: 3px;
  right: 3px;
  border-bottom: 1px solid currentColor;
  border-right: 1px solid currentColor;
}

.tb__voices-key {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .6vw, 10px);
  color: var(--tb-ink-soft);
  font-family: var(--mono);
  font-size: clamp(8px, .72vw, 9.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
}

.tb__voices-key::before,
.tb__voices-key::after {
  content: '';
  display: inline-block;
  width: clamp(16px, 1.6vw, 24px);
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.tb__voices-stations {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(6px, .8vw, 12px);
  width: 100%;
}

.tb__voice {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: clamp(8px, .8vw, 12px);
  padding: clamp(10px, 1.2vw, 14px) clamp(10px, 1.2vw, 16px);
  border: 1px solid color-mix(in srgb, var(--tb-tone) 16%, transparent);
  border-radius: 2px;
  background: rgba(20, 28, 42, .36);
  color: var(--tb-ink);
  cursor: pointer;
  text-align: left;
  transition: background .35s var(--ease), border-color .35s var(--ease), color .35s var(--ease), transform .35s var(--ease);
}

.tb__voice:hover {
  background: rgba(28, 36, 52, .58);
  border-color: color-mix(in srgb, var(--tb-tone) 36%, transparent);
}

.tb__voice.is-active {
  background: color-mix(in srgb, var(--tb-tone) 12%, rgba(20, 28, 42, .42));
  border-color: color-mix(in srgb, var(--tb-tone) 50%, transparent);
  color: var(--tb-ink);
}

.tb__voice:focus-visible {
  outline: 2px solid var(--tb-tone);
  outline-offset: 3px;
}

.tb__voice-letter {
  display: inline-grid;
  place-items: center;
  width: clamp(26px, 2.2vw, 30px);
  height: clamp(26px, 2.2vw, 30px);
  border-radius: 50%;
  border: 1px solid currentColor;
  color: var(--tb-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.01em;
  background: color-mix(in srgb, var(--tb-tone) 8%, transparent);
  transition: background .35s var(--ease), color .35s var(--ease);
}

.tb__voice.is-active .tb__voice-letter {
  background: color-mix(in srgb, var(--tb-tone) 92%, transparent);
  color: var(--night);
}

.tb__voice-stack {
  display: grid;
  row-gap: 2px;
  min-width: 0;
}

.tb__voice-name {
  display: block;
  color: var(--tb-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.005em;
  line-height: 1.1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tb__voice.is-active .tb__voice-name {
  color: var(--tb-tone);
}

.tb__voice-face {
  display: block;
  color: var(--tb-ink-mist);
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .18em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tb__voice-pip {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(14px, 1.2vw, 16px);
  height: clamp(14px, 1.2vw, 16px);
}

.tb__voice-pip-ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--tb-tone) 30%, transparent);
  opacity: .6;
  transition: opacity .35s var(--ease), border-color .35s var(--ease);
}

.tb__voice.is-active .tb__voice-pip-ring {
  opacity: 1;
  border-color: var(--tb-tone);
}

.tb__voice-pip-bead {
  width: clamp(5px, .5vw, 7px);
  height: clamp(5px, .5vw, 7px);
  border-radius: 50%;
  background: var(--tb-tone);
  opacity: 0;
  transform: scale(.6);
  transition: opacity .35s var(--ease), transform .35s var(--ease-spring);
}

.tb__voice.is-active .tb__voice-pip-bead {
  opacity: 1;
  transform: scale(1);
}

.tb__voice-wax {
  position: absolute;
  top: -10px;
  width: 14px;
  height: 14px;
  transform: translateX(-50%);
  pointer-events: none;
  transition: left .55s var(--ease-spring);
}

.tb__voice-wax-bead {
  display: block;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--tb-tone);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--tb-tone) 20%, transparent), 0 0 18px color-mix(in srgb, var(--tb-tone) 40%, transparent);
}

.tb__voices-hint {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .6vw, 10px);
  color: var(--tb-ink-mist);
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .18em;
  text-transform: uppercase;
}

.tb__voices-hint kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  padding: 2px 5px;
  border: 1px solid color-mix(in srgb, var(--tb-tone) 35%, transparent);
  border-radius: 2px;
  color: var(--tb-tone);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0;
  background: color-mix(in srgb, var(--tb-tone) 8%, transparent);
}

.tb__voices-hint-tag {
  color: var(--tb-ink-mist);
  font-style: normal;
}

@keyframes tbVoicesIn {
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .tb__voices { animation: none !important; opacity: 1 !important; }
  .tb__voice-wax { transition: none !important; }
}

/* footer */
.tb__foot {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(8px, 1vw, 16px);
  width: 100%;
  max-width: 880px;
  padding: clamp(10px, 1.4vw, 18px) clamp(14px, 1.8vw, 22px);
  border-top: 1px solid color-mix(in srgb, var(--tb-tone) 18%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--tb-tone) 18%, transparent);
  z-index: 2;
  opacity: 0;
  animation: tbFootIn .85s var(--ease-out) 1.95s forwards;
}

.tb__foot-cell {
  display: grid;
  row-gap: clamp(2px, .3vw, 4px);
  min-width: 0;
}

.tb__foot-key {
  color: var(--tb-ink-mist);
  font-family: var(--mono);
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: .9;
}

.tb__foot-value {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(4px, .4vw, 8px);
  color: var(--tb-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.005em;
  line-height: 1.1;
  flex-wrap: wrap;
}

.tb__foot-value em {
  font-style: italic;
  color: var(--tb-tone);
}

.tb__foot-mark-tag {
  display: inline-grid;
  place-items: center;
  min-width: clamp(16px, 1.4vw, 18px);
  height: clamp(14px, 1.4vw, 18px);
  padding: 0 clamp(4px, .4vw, 6px);
  border: 1px solid color-mix(in srgb, var(--tb-tone) 36%, transparent);
  border-radius: 999px;
  color: var(--tb-tone);
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(7.5px, .65vw, 8.5px);
  letter-spacing: .04em;
  text-transform: lowercase;
  opacity: .9;
}

.tb__foot-gloss {
  color: var(--tb-ink-mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(10.5px, .9vw, 12px);
  letter-spacing: -.002em;
}

.tb__foot-gloss em {
  font-style: italic;
  color: var(--tb-tone);
  font-family: var(--mono);
  font-style: normal;
  font-size: .9em;
  letter-spacing: .1em;
}

.tb__foot-bead {
  display: inline-grid;
  place-items: center;
  width: clamp(8px, .8vw, 12px);
  height: clamp(8px, .8vw, 12px);
  color: var(--tb-tone);
  opacity: .5;
}

.tb__foot-bead svg {
  display: block;
  width: 100%;
  height: 100%;
}

@keyframes tbFootIn {
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .tb__foot { animation: none !important; opacity: 1 !important; }
}

