    height: 18px;
    padding: 0 6px;
    font-size: 8px;
  }
  .tb__operator {
    font-size: clamp(12.5px, 3.4vw, 15px);
  }
}

@media (max-width: 480px) {
  .tb__statement-lines {
    font-size: clamp(28px, 11vw, 46px);
  }
  .tb__statement-static {
    margin-left: 0;
  }
  .tb__voice-name {
    font-size: 12px;
  }
  .tb__voice-face {
    font-size: 7.5px;
  }
  .tb__voice-letter {
    width: 24px;
    height: 24px;
    font-size: 12px;
  }
}

/* dark plate anchoring — keeps the broadside cohesive */
.hero--title-page {
  position: relative;
  z-index: 1;
}

@media (max-width: 720px) {
  .hero--title-page {
    padding: 0;
  }
}


/* ──────────────────────────────────────────────────────────────────
   READER'S NOTE · a single composed frontmatter that absorbs the
   editor's note, voice specimen, and imprint plate into one read.
   folio i· · sits between the title and the press bed
   ────────────────────────────────────────────────────────────────── */

.rn {
  --rn-tone-quiet: var(--blue);
  --rn-tone-human: var(--coral);
  --rn-tone-bold: var(--acid);
  --rn-tone: var(--rn-tone-quiet);
  --rn-rule: color-mix(in srgb, var(--rn-tone) 60%, transparent);
  --rn-ink: var(--paper);
  --rn-ink-soft: color-mix(in srgb, var(--paper) 70%, transparent);
  --rn-ink-mist: color-mix(in srgb, var(--paper) 38%, transparent);
  position: relative;
  isolation: isolate;
  display: grid;
  justify-items: stretch;
  row-gap: clamp(18px, 2.4vw, 28px);
  width: min(100%, 1080px);
  margin: clamp(34px, 4.6vw, 60px) auto;
  padding: clamp(28px, 3.8vw, 56px) clamp(22px, 4vw, 56px) clamp(22px, 3.4vw, 44px);
  border-radius: 2px;
  background:
    radial-gradient(ellipse 70% 46% at 50% 0%, color-mix(in srgb, var(--rn-tone) 10%, transparent), transparent 62%),
    radial-gradient(ellipse 64% 30% at 50% 100%, color-mix(in srgb, var(--rn-tone) 6%, transparent), transparent 68%),
    linear-gradient(180deg, color-mix(in srgb, var(--rn-tone) 3%, transparent), transparent 26%, transparent 74%, color-mix(in srgb, var(--rn-tone) 2%, transparent)),
    linear-gradient(180deg, rgba(20, 26, 38, .22), rgba(12, 16, 26, .36));
  border: 1px solid color-mix(in srgb, var(--rn-tone) 18%, transparent);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--rn-tone) 4%, transparent),
    inset 0 1px 0 rgba(243, 236, 214, .04);
  text-align: left;
  color: var(--rn-ink);
  opacity: 0;
  transform: translateY(12px);
  transition: opacity .9s var(--ease-out), transform .9s var(--ease-out), border-color .5s var(--ease);
}

.rn.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.app--voice-quiet .rn { --rn-tone: var(--blue); }
.app--voice-human .rn { --rn-tone: var(--coral); }
.app--voice-bold .rn { --rn-tone: var(--acid); }

@media (prefers-reduced-motion: reduce) {
  .rn { opacity: 1 !important; transform: none !important; transition: none !important; }
  .rn__eyebrow-rule-stroke,
  .rn__word-rule-stroke,
  .rn__pull-rule-stroke--lead,
  .rn__pull-rule-stroke--trail { animation: none !important; stroke-dashoffset: 0 !important; }
}

.rn__defs { position: absolute; width: 0; height: 0; pointer-events: none; overflow: hidden; }

/* corner crops */
.rn__plate {
  position: absolute;
  inset: 6px;
  pointer-events: none;
  z-index: 0;
}

.rn__plate-corner {
  position: absolute;
  width: 14px;
  height: 14px;
  color: var(--rn-tone);
  opacity: .65;
}

.rn__plate-corner::before,
.rn__plate-corner::after {
  content: '';
  position: absolute;
  background: currentColor;
  border-radius: .5px;
}

.rn__plate-corner::before { width: 10px; height: 1px; }
.rn__plate-corner::after { width: 1px; height: 10px; }

.rn__plate-corner--tl { top: 0; left: 0; }
.rn__plate-corner--tl::before { top: 0; left: 0; }
.rn__plate-corner--tl::after { top: 0; left: 0; }
.rn__plate-corner--tr { top: 0; right: 0; }
.rn__plate-corner--tr::before { top: 0; right: 0; }
.rn__plate-corner--tr::after { top: 0; right: 0; }
.rn__plate-corner--bl { bottom: 0; left: 0; }
.rn__plate-corner--bl::before { bottom: 0; left: 0; }
.rn__plate-corner--bl::after { bottom: 0; left: 0; }
.rn__plate-corner--br { bottom: 0; right: 0; }
.rn__plate-corner--br::before { bottom: 0; right: 0; }
.rn__plate-corner--br::after { bottom: 0; right: 0; }

/* eyebrow */
.rn__head {
  display: flex;
  justify-content: center;
  width: 100%;
  z-index: 1;
}

.rn__eyebrow {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(6px, .7vw, 10px);
  width: 100%;
  max-width: 760px;
  margin: 0;
  padding: 0;
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(8.5px, .78vw, 10px);
  letter-spacing: .28em;
  text-transform: uppercase;
  opacity: 0;
  animation: rnEyebrowIn .7s var(--ease-out) .15s forwards;
}

.rn__eyebrow em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1.05vw, 14px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--rn-tone);
}

.rn__eyebrow-key {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  opacity: .82;
}

.rn__eyebrow-key--date { margin-left: clamp(2px, .4vw, 6px); }

.rn__eyebrow-sep {
  color: var(--ink-mist);
  opacity: .5;
}

.rn__eyebrow-mark {
  display: inline-block;
  width: clamp(16px, 1.6vw, 24px);
  height: 1px;
  background: linear-gradient(to right, transparent, var(--rn-tone));
  opacity: .55;
}

.rn__eyebrow-rule {
  display: block;
  flex: 1 1 auto;
  min-width: clamp(48px, 8vw, 120px);
  max-width: clamp(120px, 18vw, 200px);
  height: 4px;
  color: var(--rn-rule);
}

.rn__eyebrow-rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.rn__eyebrow-rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: rnRuleDraw 1.5s var(--ease-out) .45s forwards;
}

.rn__eyebrow-date {
  color: var(--rn-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, 1vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
}

@keyframes rnEyebrowIn {
  to { opacity: 1; }
}

@keyframes rnRuleDraw {
  to { stroke-dashoffset: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .rn__eyebrow { animation: none !important; opacity: 1 !important; }
}

/* lead headline */
.rn__lead {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  justify-content: center;
  column-gap: clamp(10px, 1.2vw, 18px);
  row-gap: 6px;
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
  z-index: 1;
  opacity: 0;
  animation: rnLeadIn .9s var(--ease-out) .35s forwards;
}

.rn__lead-mark {
  display: inline-block;
  color: var(--rn-tone);
  font-family: var(--serif);
  font-size: 1.1em;
  opacity: .8;
  transform: translateY(-.04em);
}

.rn__lead-mark--alt {
  transform: scaleX(-1) translateY(-.04em);
}

.rn__lead-title {
  margin: 0;
  padding: 0;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(17px, 1.7vw, 22px);
  letter-spacing: -.012em;
  line-height: 1.34;
  color: var(--rn-ink);
  max-width: 36ch;
}

.app--voice-bold .rn__lead-title { font-family: var(--sans); font-style: normal; letter-spacing: -.02em; font-weight: 700; }

@keyframes rnLeadIn {
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .rn__lead { animation: none !important; opacity: 1 !important; }
}

/* rows (words + voices) */
.rn__rows {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(22px, 2.6vw, 32px);
  width: 100%;
  z-index: 1;
}

.rn__row {
  display: grid;
  row-gap: clamp(10px, 1.4vw, 16px);
}

.rn__row-head {
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.2vw, 16px);
  width: 100%;
}

.rn__row-rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--rn-tone) 35%, transparent), transparent);
  min-width: clamp(20px, 4vw, 60px);
}

.rn__row-rule--lead { background: linear-gradient(to right, transparent, color-mix(in srgb, var(--rn-tone) 38%, transparent)); }
.rn__row-rule--trail { background: linear-gradient(to left, transparent, color-mix(in srgb, var(--rn-tone) 38%, transparent)); }

.rn__row-tag {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: clamp(6px, .7vw, 10px);
  padding: 4px clamp(8px, 1vw, 12px);
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--rn-tone) 22%, transparent);
  background: color-mix(in srgb, var(--rn-tone) 6%, transparent);
  color: var(--rn-tone);
  font-family: var(--mono);
  font-size: clamp(8.5px, .75vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
}

.rn__row-tag em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12.5px, 1.1vw, 14.5px);
  letter-spacing: -.005em;
  text-transform: none;
}

.rn__row-tag-key {
  color: var(--rn-ink-mist);
  letter-spacing: .16em;
}

.rn__row-tag-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .8;
}

.rn__row-tag-dot--alt { opacity: .55; }

/* word row */
.rn__words {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  justify-content: center;
  gap: clamp(6px, 1vw, 14px);
  margin: 0;
  padding: 0;
  list-style: none;
  width: 100%;
}

.rn__word-cell {
  display: inline-flex;
  align-items: stretch;
  flex: 1 1 0;
  min-width: clamp(150px, 22vw, 220px);
  max-width: 320px;
}

.rn__word-cell--m3 { --word-tone: var(--acid); }
.rn__word-cell--good { --word-tone: var(--coral); }
.rn__word-cell--yet { --word-tone: var(--blue); }

.rn__word {
  position: relative;
  display: grid;
  grid-template-columns: auto auto 1fr;
  grid-template-rows: auto auto auto;
  column-gap: clamp(8px, 1vw, 12px);
  row-gap: 4px;
  align-items: center;
  width: 100%;
  padding: clamp(10px, 1.2vw, 14px) clamp(12px, 1.4vw, 16px);
  border: 1px solid color-mix(in srgb, var(--word-tone) 22%, transparent);
  border-radius: 2px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--word-tone) 6%, transparent), transparent 80%),
    rgba(20, 28, 42, .28);
  color: var(--rn-ink);
  font: inherit;
  cursor: pointer;
  text-align: left;
  transition: background .35s var(--ease), border-color .35s var(--ease), transform .35s var(--ease);
}

.rn__word:hover {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--word-tone) 11%, transparent), transparent 80%),
    rgba(28, 36, 52, .42);
  border-color: color-mix(in srgb, var(--word-tone) 46%, transparent);
}

.rn__word.is-active {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--word-tone) 18%, transparent), transparent 80%),
    rgba(28, 36, 52, .5);
  border-color: color-mix(in srgb, var(--word-tone) 60%, transparent);
}

.rn__word:focus-visible {
  outline: 2px solid var(--word-tone);
  outline-offset: 3px;
}

.rn__word-mark {
  grid-row: 1 / span 2;
  align-self: center;
  display: inline-grid;
  place-items: center;
  min-width: clamp(36px, 3.2vw, 44px);
  height: clamp(28px, 2.6vw, 34px);
  padding: 0 clamp(6px, .7vw, 10px);
  border: 1px solid color-mix(in srgb, var(--word-tone) 36%, transparent);
  border-radius: 2px;
  color: var(--word-tone);
  font-family: var(--mono);
  font-size: clamp(9px, .8vw, 10.5px);
  letter-spacing: .16em;
  text-transform: uppercase;
  background: color-mix(in srgb, var(--word-tone) 12%, transparent);
  transition: background .35s var(--ease), border-color .35s var(--ease);
}

.rn__word.is-active .rn__word-mark {
  background: color-mix(in srgb, var(--word-tone) 86%, transparent);
  color: var(--night);
  border-color: color-mix(in srgb, var(--word-tone) 70%, transparent);
}

.rn__word-glyph {
  grid-row: 1 / span 2;
  align-self: center;
  display: inline-grid;
  place-items: center;
  width: clamp(28px, 2.4vw, 32px);
  height: clamp(28px, 2.4vw, 32px);
  color: var(--word-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(20px, 1.6vw, 24px);
  line-height: 1;
  border: 1px solid color-mix(in srgb, var(--word-tone) 24%, transparent);
  border-radius: 50%;
  background: color-mix(in srgb, var(--word-tone) 6%, transparent);
}

.rn__word-label {
  grid-column: 3;
  grid-row: 1;
  color: var(--rn-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14.5px, 1.25vw, 17px);
  letter-spacing: -.006em;
  line-height: 1.1;
}

.rn__word-gloss {
  grid-column: 3;
  grid-row: 2;
  color: var(--rn-ink-mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .95vw, 12.5px);
  letter-spacing: -.002em;
}

.rn__word-rule {
  grid-column: 1 / -1;
  grid-row: 3;
  display: block;
  width: 100%;
  height: 6px;
  color: color-mix(in srgb, var(--word-tone) 40%, transparent);
  margin-top: 4px;
}

.rn__word-rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.rn__word-rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset .6s var(--ease-out);
}

.rn__word.is-active .rn__word-rule-stroke,
.rn__word.is-hover .rn__word-rule-stroke {
  stroke-dashoffset: 0;
}

.rn__word-sep {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  .rn__word-rule-stroke { animation: none !important; stroke-dashoffset: 0 !important; }
}

/* voice row */
.rn__voices {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(8px, 1vw, 12px);
  width: 100%;
}

.rn__voice {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  padding: clamp(10px, 1.2vw, 14px) clamp(10px, 1.2vw, 16px);
  border: 1px solid color-mix(in srgb, var(--rn-tone) 18%, transparent);
  border-radius: 2px;
  background: rgba(20, 28, 42, .36);
  color: var(--rn-ink);
  cursor: pointer;
  text-align: left;
  transition: background .35s var(--ease), border-color .35s var(--ease), color .35s var(--ease);
}

.rn__voice:hover {
  background: rgba(28, 36, 52, .58);
  border-color: color-mix(in srgb, var(--rn-tone) 36%, transparent);
}

.rn__voice.is-active {
  background: color-mix(in srgb, var(--rn-tone) 12%, rgba(20, 28, 42, .42));
  border-color: color-mix(in srgb, var(--rn-tone) 50%, transparent);
}

.rn__voice:focus-visible {
  outline: 2px solid var(--rn-tone);
  outline-offset: 3px;
}

.rn__voice-letter {
  display: inline-grid;
  place-items: center;
  width: clamp(26px, 2.2vw, 30px);
  height: clamp(26px, 2.2vw, 30px);
  border-radius: 50%;
  border: 1px solid currentColor;
  color: var(--rn-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.01em;
  background: color-mix(in srgb, var(--rn-tone) 8%, transparent);
}

.rn__voice.is-active .rn__voice-letter {
  background: color-mix(in srgb, var(--rn-tone) 92%, transparent);
  color: var(--night);
}

.rn__voice-stack {
  display: grid;
  row-gap: 2px;
  min-width: 0;
}

.rn__voice-name {
  display: block;
  color: var(--rn-ink);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.1vw, 15px);
  letter-spacing: -.005em;
  line-height: 1.1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rn__voice.is-active .rn__voice-name {
  color: var(--rn-tone);
}

.rn__voice-face {
  display: block;
  color: var(--rn-ink-mist);
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .18em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rn__voice-pip {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(14px, 1.2vw, 16px);
  height: clamp(14px, 1.2vw, 16px);
}

.rn__voice-pip-ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--rn-tone) 30%, transparent);
  opacity: .6;
  transition: opacity .35s var(--ease), border-color .35s var(--ease);
}

.rn__voice.is-active .rn__voice-pip-ring {
  opacity: 1;
  border-color: var(--rn-tone);
}

.rn__voice-pip-bead {
  width: clamp(5px, .5vw, 7px);
  height: clamp(5px, .5vw, 7px);
  border-radius: 50%;
  background: var(--rn-tone);
  opacity: 0;
  transform: scale(.6);
  transition: opacity .35s var(--ease), transform .35s var(--ease-spring);
}

.rn__voice.is-active .rn__voice-pip-bead {
  opacity: 1;
  transform: scale(1);
}

.rn__voice-wax {
  position: absolute;
  top: -10px;
  width: 14px;
  height: 14px;
  transform: translateX(-50%);
  pointer-events: none;
  transition: left .55s var(--ease-spring);
}

.rn__voice-wax-bead {
  display: block;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--rn-tone);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--rn-tone) 20%, transparent), 0 0 18px color-mix(in srgb, var(--rn-tone) 40%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  .rn__voice-wax { transition: none !important; }
}

.rn__voices-hint {
  display: inline-flex;
  align-items: center;
  justify-self: center;
  gap: clamp(6px, .6vw, 10px);
  color: var(--rn-ink-mist);
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .18em;
  text-transform: uppercase;
}

.rn__voices-hint kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  padding: 2px 5px;
  border: 1px solid color-mix(in srgb, var(--rn-tone) 35%, transparent);
  border-radius: 2px;
  color: var(--rn-tone);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0;
  background: color-mix(in srgb, var(--rn-tone) 8%, transparent);
}

.rn__voices-hint-tag {
  color: var(--rn-ink-mist);
}

/* pull quote */
.rn__pull {
  display: grid;
  justify-items: center;
  row-gap: clamp(6px, .8vw, 10px);
  width: 100%;
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
  z-index: 1;
  opacity: 0;
  animation: rnPullIn .85s var(--ease-out) 1s forwards;
}

.rn__pull-rule {
  display: block;
  width: 100%;
  max-width: 220px;
  height: 6px;
  color: var(--rn-tone);
  opacity: .8;
}

.rn__pull-rule svg { display: block; width: 100%; height: 100%; }

.rn__pull-rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
}

.rn__pull-rule-stroke--lead { animation: rnRuleDraw 1.4s var(--ease-out) 1.1s forwards; }
.rn__pull-rule-stroke--trail { animation: rnRuleDraw 1.4s var(--ease-out) 1.3s forwards; }

.rn__pull-body {
  position: relative;
  margin: 0;
  padding: 0;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(20px, 2.2vw, 28px);
  letter-spacing: -.012em;
  line-height: 1.2;
  color: var(--rn-ink);
}

.app--voice-bold .rn__pull-body {
  font-family: var(--sans);
  font-style: normal;
  font-weight: 700;
  letter-spacing: -.022em;
  text-transform: uppercase;
}

.rn__pull-quote {
  display: inline-block;
  color: var(--rn-tone);
  font-style: normal;
  margin-right: 4px;
}

.rn__pull-quote--alt {
  margin-right: 0;
  margin-left: 4px;
  transform: scaleX(-1);
