/* ────────────────────────────────────────────────────────────
   iteration 334 · THE COLOPHON AS A HAND-PRESSED DEDICATION
   The closing plate (ClosingPlate), the sign-off FolioImprint
   plinth, and the small seal header of the colophon are absorbed
   into one composed dedication. The plate earns its place as the
   page's final impression: a slim folio strip at the top, a
   large central wax seal flanked by a hand-pressed italic
   dedication, three quiet meta rows (voice, mark, date), the
   kept-mark signature underneath, and a single back-to-question
   link. PageReturn remains as the gentle gesture after the
   dedication — "the page rests".
   ──────────────────────────────────────────────────────────── */

.colophon.is-signed {
  --colophon-tone: var(--coral);
}
.app--voice-quiet .colophon.is-signed { --colophon-tone: var(--blue); }
.app--voice-human .colophon.is-signed { --colophon-tone: var(--coral); }
.app--voice-bold .colophon.is-signed { --colophon-tone: var(--acid); }

.colophon {
  position: relative;
  padding: clamp(70px, 9vw, 130px) 0 clamp(40px, 5vw, 70px);
  margin-top: clamp(80px, 10vw, 140px);
  border-top: 1px solid var(--line-soft);
  isolation: isolate;
}

.colophon::before {
  position: absolute;
  top: -1px;
  left: 50%;
  transform: translate(-50%, -50%);
  padding: 4px 14px;
  border: 1px solid var(--line);
  background: var(--night);
  color: var(--coral);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  text-transform: uppercase;
  content: 'colophon';
  z-index: 2;
}

.app--voice-quiet .colophon::before { color: var(--blue); }
.app--voice-human .colophon::before { color: var(--coral); }
.app--voice-bold .colophon::before { color: var(--acid); }

.colophon__plate {
  position: relative;
  display: grid;
  row-gap: clamp(22px, 3vw, 38px);
  padding: clamp(28px, 4vw, 56px) clamp(24px, 4vw, 56px) clamp(26px, 3.6vw, 44px);
  border: 1px solid color-mix(in srgb, var(--colophon-tone, var(--coral)) 22%, transparent);
  background:
    radial-gradient(ellipse 70% 38% at 50% 0%, color-mix(in srgb, var(--colophon-tone, var(--coral)) 10%, transparent), transparent 64%),
    radial-gradient(ellipse 60% 30% at 50% 100%, color-mix(in srgb, var(--colophon-tone, var(--coral)) 6%, transparent), transparent 68%),
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(14, 20, 32, .58));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--colophon-tone, var(--coral)) 6%, transparent),
    inset 0 1px 0 rgba(243, 236, 214, .04),
    0 30px 80px -40px rgba(0, 0, 0, .55);
}

.colophon__plate::before {
  position: absolute;
  inset: 7px;
  border: 1px dashed color-mix(in srgb, var(--colophon-tone, var(--coral)) 14%, transparent);
  pointer-events: none;
  content: '';
  z-index: 0;
}

/* corner crops — printer's registration marks */
.colophon__corner {
  position: absolute;
  width: 16px;
  height: 16px;
  color: var(--colophon-tone, var(--coral));
  pointer-events: none;
  z-index: 1;
  opacity: .85;
  transition: opacity .4s var(--ease), color .4s var(--ease);
}

.colophon__corner::before,
.colophon__corner::after {
  content: '';
