  background: currentColor;
}

.colophon__corner::before { width: 11px; height: 1px; }
.colophon__corner::after { width: 1px; height: 11px; }

.colophon__corner--tl { top: 12px; left: 12px; }
.colophon__corner--tl::before { top: 0; left: 0; }
.colophon__corner--tl::after { top: 0; left: 0; }

.colophon__corner--tr { top: 12px; right: 12px; }
.colophon__corner--tr::before { top: 0; right: 0; }
.colophon__corner--tr::after { top: 0; right: 0; }

.colophon__corner--bl { bottom: 12px; left: 12px; }
.colophon__corner--bl::before { bottom: 0; left: 0; }
.colophon__corner--bl::after { bottom: 0; left: 0; }

.colophon__corner--br { bottom: 12px; right: 12px; }
.colophon__corner--br::before { bottom: 0; right: 0; }
.colophon__corner--br::after { bottom: 0; right: 0; }

