  height: clamp(16px, 1.4vw, 20px);
  padding: 0 clamp(5px, .5vw, 8px);
  border: 1px solid color-mix(in srgb, var(--colophon-tone, var(--coral)) 38%, transparent);
  border-radius: 999px;
  color: var(--colophon-tone, var(--coral));
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(8px, .65vw, 9.5px);
  letter-spacing: .04em;
  text-transform: lowercase;
}

.colophon__row-sub {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--mist);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11.5px, .9vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  opacity: .8;
}

.colophon__voice-cell {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  flex-wrap: wrap;
}

.colophon__voice-letter {
  display: inline-grid;
  place-items: center;
  width: clamp(24px, 2vw, 28px);
  height: clamp(24px, 2vw, 28px);
  border-radius: 50%;
  border: 1px solid currentColor;
  color: var(--colophon-tone, var(--coral));
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(12px, 1vw, 14.5px);
  letter-spacing: -.01em;
  background: color-mix(in srgb, var(--colophon-tone, var(--coral)) 10%, transparent);
  flex: 0 0 auto;
}

.colophon__voice-tag {
  display: inline-flex;
  align-items: center;
  padding: 2px clamp(5px, .5vw, 8px) 3px;
  border: 1px solid color-mix(in srgb, var(--colophon-tone, var(--coral)) 32%, transparent);
  border-radius: 1px;
  color: var(--colophon-tone, var(--coral));
  font-family: var(--mono);
  font-style: normal;
  font-size: clamp(8px, .65vw, 9.5px);
  letter-spacing: .18em;
  text-transform: uppercase;
  opacity: .85;
}

/* signature — kept-mark at larger size */
.colophon__signature {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(8px, 1vw, 14px) 0 0;
  border-top: 1px dashed color-mix(in srgb, var(--colophon-tone, var(--coral)) 14%, transparent);
  z-index: 1;
}

.colophon__signature .kept-mark {
  --kept-tone: var(--colophon-tone, var(--coral));
}

.colophon__signature-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  max-width: 56ch;
  margin: clamp(20px, 2.4vw, 32px) auto 0;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  text-align: center;
  line-height: 1.55;
}

.colophon__signature-note span[aria-hidden] {
  color: var(--coral);
  font-style: normal;
  font-size: 16px;
}

.app--voice-quiet .colophon__signature-note span[aria-hidden] { color: var(--blue); }
.app--voice-human .colophon__signature-note span[aria-hidden] { color: var(--coral); }
.app--voice-bold .colophon__signature-note span[aria-hidden] { color: var(--acid); }

/* foot — line + back link */
.colophon__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
  padding-top: clamp(14px, 1.8vw, 22px);
  z-index: 1;
}

.colophon__line {
  margin: 0;
  max-width: 50ch;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(14.5px, 1.4vw, 18px);
  font-style: italic;
  letter-spacing: -.014em;
  line-height: 1.4;
}

.colophon__line i {
  color: var(--mist);
  font-style: italic;
}

.colophon__back {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px 11px;
  border: 1px solid color-mix(in srgb, var(--colophon-tone, var(--coral)) 38%, transparent);
  color: var(--colophon-tone, var(--coral));
  font-family: var(--mono);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: .2em;
  text-transform: uppercase;
  background: color-mix(in srgb, var(--colophon-tone, var(--coral)) 6%, transparent);
  transition:
    color .3s var(--ease),
    border-color .3s var(--ease),
    background .3s var(--ease),
    transform .35s var(--ease-spring);
}

.colophon__back .arrow-icon {
  width: 16px;
  height: 16px;
  transform: rotate(90deg);
  transition: transform .4s var(--ease-out);
}

.colophon__back:hover,
.colophon__back:focus-visible {
  color: var(--night);
  background: var(--colophon-tone, var(--coral));
  border-color: var(--colophon-tone, var(--coral));
  transform: translateY(-1px);
}

.colophon__back:hover .arrow-icon,
.colophon__back:focus-visible .arrow-icon {
  transform: rotate(90deg) translateX(3px);
}

@media (max-width: 540px) {
  .colophon__back {
    width: 100%;
    justify-content: center;
  }
}

@media (max-width: 720px) {
  .colophon__plate {
    padding: clamp(20px, 5vw, 32px) clamp(16px, 4vw, 22px) clamp(20px, 4vw, 30px);
  }
  .colophon__dedication-name {
    font-size: clamp(26px, 7vw, 38px);
  }
  .colophon__value {
    font-size: clamp(14px, 4vw, 17px);
  }
  .colophon__voice-letter {
    width: 22px;
    height: 22px;
    font-size: 12px;
  }
}

/* suppress now-unused colophon chrome from earlier passes so
   nothing leaks into the new composition */
.colophon__head,
.colophon__identity,
.colophon__mark,
.colophon__title,
.colophon__press,
.colophon__date,
.colophon__date-rule,
.colophon__date-tag,
.colophon__date-dot,
.colophon__crease,
.colophon__crease--v,
.colophon__flap,
.colophon__impression,
.colophon__impression-tag,
.colophon__impression-tag-dot,
.colophon__impression-line,
.colophon__impression-head,
.colophon__impression-mark-tag,
.colophon__impression-meta,
.colophon__impression-mark,
.colophon__reader,
.colophon__reader-name,
.colophon__reader-rule,
.colophon__reader-rule-stroke,
.colophon__reader-rule-bead,
.colophon__grid,
.colophon__swatches,
.colophon__swatch {
  display: none;
}

/* ────────────────────────────────────────────────────────────
   iteration 335 · THE PRESS REGISTER
   A single, persistent ribbon beneath the site header that
   holds the page's active state in one composed strip. The
   voice letter on the left, the marked word glyph on the
   right, and a continuous thread of pressed marks between
   them. The ribbon sticks with the header, replaces several
   duplicated state displays, and reads as one breath across
   the page.
   ──────────────────────────────────────────────────────────── */

.press-register {
  --pr-tone: var(--coral);
  --pr-word-tone: var(--acid);
  --pr-h: clamp(38px, 4.4vw, 50px);

  position: relative;
  z-index: 4;
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    auto
    minmax(0, 2fr)
    auto
    minmax(0, 1fr)
    auto;
  align-items: center;
  gap: clamp(10px, 1.6vw, 22px);
  width: 100%;
  margin-top: clamp(8px, 1vw, 14px);
  padding: clamp(4px, .6vw, 7px) 0;
  border-top: 1px solid transparent;
  border-bottom: 1px solid var(--line-soft);
  background:
    linear-gradient(180deg, rgba(12, 16, 25, .42) 0%, rgba(14, 17, 26, .72) 100%);
  color: var(--paper);
  font-family: var(--serif);
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity .7s var(--ease), transform .7s var(--ease);
}

.press-register.is-revealed {
  opacity: 1;
  transform: translateY(0);
  transition-delay: .35s;
}

.press-register__hairline {
  position: absolute;
  left: clamp(22px, 5vw, 96px);
  right: clamp(22px, 5vw, 96px);
  height: 1px;
  pointer-events: none;
  background: linear-gradient(
    to right,
    transparent 0%,
    color-mix(in srgb, var(--pr-tone) 50%, transparent) 18%,
    color-mix(in srgb, var(--pr-tone) 70%, transparent) 50%,
    color-mix(in srgb, var(--pr-tone) 50%, transparent) 82%,
    transparent 100%
  );
  opacity: .55;
}

.press-register__hairline--top {
  top: 0;
}

.press-register__hairline--bottom {
  bottom: -1px;
  opacity: .25;
}

.press-register__crop {
  position: absolute;
  width: 8px;
  height: 8px;
  border-color: color-mix(in srgb, var(--pr-tone) 55%, transparent);
  pointer-events: none;
}

.press-register__crop--tl {
  top: -1px;
  left: -1px;
  border-top: 1px solid;
  border-left: 1px solid;
}

.press-register__crop--tr {
  top: -1px;
  right: -1px;
  border-top: 1px solid;
  border-right: 1px solid;
}

.press-register__crop--bl {
  bottom: -1px;
  left: -1px;
  border-bottom: 1px solid;
  border-left: 1px solid;
}

.press-register__crop--br {
  bottom: -1px;
  right: -1px;
  border-bottom: 1px solid;
  border-right: 1px solid;
}

.press-register__cell {
  display: inline-grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  min-width: 0;
  padding: 4px 0;
}

.press-register__cell-key {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .26em;
  text-transform: uppercase;
  white-space: nowrap;
}

.press-register__cell-key-mark {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--pr-tone);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--pr-tone) 18%, transparent);
}

.press-register__cell-key-mark--alt {
  background: transparent;
  border: 1px solid var(--pr-tone);
  box-shadow: none;
  opacity: .55;
}

.press-register__voice,
.press-register__word {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(26px, 2.4vw, 32px);
  height: clamp(26px, 2.4vw, 32px);
  border: 1px solid color-mix(in srgb, var(--pr-tone) 60%, transparent);
  border-radius: 1px;
  background:
    radial-gradient(circle at 32% 28%, color-mix(in srgb, var(--pr-tone) 22%, transparent), transparent 60%),
    linear-gradient(180deg, rgba(28, 36, 52, .32), rgba(14, 20, 32, .42));
  color: var(--pr-tone);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.4vw, 19px);
  line-height: 1;
  transition: color .35s var(--ease), border-color .35s var(--ease), box-shadow .45s var(--ease);
}

.press-register__word {
  color: var(--pr-word-tone);
  border-color: color-mix(in srgb, var(--pr-word-tone) 60%, transparent);
  background:
    radial-gradient(circle at 32% 28%, color-mix(in srgb, var(--pr-word-tone) 22%, transparent), transparent 60%),
    linear-gradient(180deg, rgba(28, 36, 52, .32), rgba(14, 20, 32, .42));
}

.press-register__voice-letter,
.press-register__word-glyph {
  display: inline-block;
  transition: transform .35s var(--ease-spring);
}

.press-register__voice-glow,
.press-register__word-glow {
  position: absolute;
  inset: -2px;
  border: 1px solid currentColor;
  border-radius: 1px;
  opacity: 0;
  pointer-events: none;
  transition: opacity .35s var(--ease), transform .55s var(--ease);
}

.press-register.is-revealed .press-register__voice-letter,
.press-register.is-revealed .press-register__word-glyph {
  animation: pr-press-letter 1.6s var(--ease-out) .8s 1 both;
}

.press-register__cell-name {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  min-width: 0;
  line-height: 1.1;
}

.press-register__cell-name em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(13px, 1.05vw, 15.5px);
  letter-spacing: -.01em;
}

.press-register__cell-face {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

.press-register__rule {
  display: inline-flex;
  align-items: center;
  width: clamp(36px, 4vw, 64px);
  color: color-mix(in srgb, var(--pr-tone) 60%, transparent);
  opacity: .85;
}

.press-register__rule svg {
  display: block;
  width: 100%;
  height: 8px;
}

.press-register__rule-stroke {
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  animation: pr-rule-draw 1.4s var(--ease-out) .4s forwards;
}

.press-register__rule-bead {
  opacity: 0;
  animation: pr-bead-in .5s var(--ease-out) 1.5s forwards;
}

.press-register__rule-stroke--trail {
  animation-delay: .55s;
  opacity: .7;
}

.press-register__rule-bead--trail {
  animation-delay: 1.65s;
}

.press-register__thread {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  height: 22px;
  min-width: 0;
}

.press-register__thread-rail {
  position: absolute;
  inset: 50% 0 auto 0;
  height: 1px;
  margin-top: -.5px;
  background: linear-gradient(
    to right,
    transparent 0%,
    color-mix(in srgb, var(--pr-tone) 32%, transparent) 12%,
    color-mix(in srgb, var(--pr-tone) 52%, transparent) 50%,
    color-mix(in srgb, var(--pr-tone) 32%, transparent) 88%,
    transparent 100%
  );
  opacity: .8;
}

.press-register__thread-rail--in {
  inset: calc(50% + 5px) 0 auto 0;
  height: 1px;
  margin-top: -.5px;
  background: linear-gradient(
    to right,
    transparent 0%,
    color-mix(in srgb, var(--pr-tone) 18%, transparent) 12%,
    color-mix(in srgb, var(--pr-tone) 28%, transparent) 50%,
    color-mix(in srgb, var(--pr-tone) 18%, transparent) 88%,
    transparent 100%
  );
  opacity: .55;
}

.press-register__thread-marks {
  position: absolute;
  inset: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.press-register__thread-mark {
  position: absolute;
  top: 50%;
  width: 8px;
  height: 8px;
  margin: -4px 0 0 -4px;
  display: grid;
  place-items: center;
  color: var(--pr-tone);
  transform-origin: center;
  animation: pr-mark-in .55s var(--ease-spring) both;
}

.press-register__thread-mark.is-latest {
  z-index: 1;
}

.press-register__thread-mark-bead {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 2px color-mix(in srgb, currentColor 16%, transparent);
  transition: transform .35s var(--ease);
}

.press-register__thread-mark-letter {
  position: absolute;
  top: -16px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--serif);
  font-style: italic;
  font-size: 9.5px;
  color: currentColor;
  line-height: 1;
  opacity: .8;
}

.press-register__thread-mark-glyph {
  position: absolute;
  top: -15px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--serif);
  font-style: italic;
  font-size: 13px;
  color: currentColor;
  line-height: 1;
}

.press-register__thread-mark-pull {
  position: absolute;
  top: -14px;
  left: 50%;
  width: 6px;
  height: 9px;
  transform: translateX(-50%);
  background: currentColor;
  border-radius: 1px 1px 50% 50% / 1px 1px 100% 100%;
  box-shadow: 0 0 0 2px color-mix(in srgb, currentColor 16%, transparent);
}

.press-register__thread-mark--word {
  color: var(--pr-word-tone);
}

.press-register__thread-mark--pull {
  color: var(--coral);
}

.press-register__thread-mark--voice-quiet {
  color: var(--blue);
}

.press-register__thread-mark--voice-human {
  color: var(--coral);
}

.press-register__thread-mark--voice-bold {
  color: var(--acid);
}

.press-register__thread-mark-splash {
  position: absolute;
  inset: -8px;
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: 0;
  animation: pr-splash .9s var(--ease-out) forwards;
  pointer-events: none;
}

.press-register__thread-now {
  position: absolute;
  top: 50%;
  width: 12px;
  height: 12px;
  margin: -6px 0 0 -6px;
  pointer-events: none;
  animation: pr-mark-in .45s var(--ease-spring) both;
}

.press-register__thread-now-bead {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: var(--pr-tone);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--pr-tone) 22%, transparent),
    0 0 0 1px color-mix(in srgb, var(--pr-tone) 60%, transparent);
  animation: pr-now-pulse 2.4s var(--ease) infinite;
}

.press-register__thread-now-tail {
  position: absolute;
  top: 50%;
  right: 100%;
  width: 16px;
  height: 1px;
  margin-top: -.5px;
  margin-right: 2px;
  background: linear-gradient(to left, var(--pr-tone), transparent);
  opacity: .75;
}

.press-register__thread-now--idle .press-register__thread-now-bead {
  background: var(--muted);
  box-shadow: 0 0 0 3px rgba(123, 118, 130, .15);
  animation: none;
}

.press-register__thread-now--word-m3 { --pr-tone: var(--acid); }
.press-register__thread-now--word-good { --pr-tone: var(--coral); }
.press-register__thread-now--word-yet { --pr-tone: var(--blue); }

.press-register__set {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  justify-self: end;
  color: var(--paper);
  font-family: var(--mono);
  font-size: clamp(9px, .76vw, 10.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: .8;
}

.press-register__set em {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(11px, .92vw, 13px);
  letter-spacing: -.002em;
  text-transform: none;
  color: var(--paper);
}

.press-register__set-mark {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  opacity: .55;
}

.press-register__set-mark--alt {
  background: transparent;
  border: 1px solid currentColor;
  opacity: .35;
}

@keyframes pr-press-letter {
  0% { transform: scale(.6); opacity: 0; }
  60% { transform: scale(1.08); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}

@keyframes pr-rule-draw {
  to { stroke-dashoffset: 0; }
}

@keyframes pr-bead-in {
  to { opacity: 1; }
}

@keyframes pr-mark-in {
  0% { transform: translateY(-2px) scale(.4); opacity: 0; }
  60% { transform: translateY(0) scale(1.18); opacity: 1; }
  100% { transform: translateY(0) scale(1); opacity: 1; }
}

@keyframes pr-splash {
  0% { transform: scale(.6); opacity: .85; }
  100% { transform: scale(2.4); opacity: 0; }
}

@keyframes pr-now-pulse {
  0%, 100% {
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--pr-tone) 22%, transparent),
      0 0 0 1px color-mix(in srgb, var(--pr-tone) 60%, transparent);
  }
  50% {
    box-shadow: 0 0 0 6px color-mix(in srgb, var(--pr-tone) 12%, transparent),
      0 0 0 1px color-mix(in srgb, var(--pr-tone) 60%, transparent);
  }
}

@media (max-width: 1080px) {
  .press-register {
    grid-template-columns:
      auto
      minmax(0, 1fr)
      auto;
    gap: clamp(10px, 1.6vw, 18px);
  }
  .press-register__cell--word {
    display: none;
  }
  .press-register__rule--trail {
    display: none;
  }
}

@media (max-width: 720px) {
  .press-register {
    --pr-h: 44px;
    margin-top: 6px;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 10px;
  }
  .press-register__rule--lead {
    display: none;
  }
  .press-register__cell--voice .press-register__cell-name {
    display: none;
  }
  .press-register__cell-key {
    display: none;
  }
  .press-register__set {
    display: none;
  }
  .press-register__thread {
    height: 18px;
  }
}

@media (max-width: 420px) {
  .press-register {
    gap: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .press-register,
  .press-register.is-revealed {
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
  .press-register__voice-letter,
  .press-register__word-glyph,
  .press-register__rule-stroke,
  .press-register__rule-bead,
  .press-register__thread-mark,
  .press-register__thread-mark-splash,
  .press-register__thread-now {
    animation: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
  .press-register__thread-mark-splash {
    display: none !important;
  }
  .press-register__thread-now-bead {
    animation: none !important;
  }
  .press-register__rule-stroke {
    stroke-dashoffset: 0 !important;
  }
}

/* ────────────────────────────────────────────────────────────
   iteration 336 · PRESS SIGNAL
   A single composed connector that descends from the title
   broadside into the reading prologue. One hand-drawn thread,
   one pressed mark, and a short caption. The signal is the
   visual breath between the question and the guide.
   ──────────────────────────────────────────────────────────── */

.press-signal {
  --press-signal-tone: var(--coral);
  --press-signal-h: clamp(150px, 18vw, 200px);

  position: relative;
  display: grid;
  grid-template-rows: auto 1fr auto auto;
  align-items: center;
  justify-items: center;
  width: min(100%, 540px);
  height: var(--press-signal-h);
  margin: clamp(22px, 3vw, 44px) auto clamp(18px, 2.4vw, 36px);
  padding: 0 clamp(12px, 2vw, 24px);
  color: var(--press-signal-tone);
  isolation: isolate;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 1.1s var(--ease-out) .1s, transform 1.1s var(--ease-out) .1s, color .5s var(--ease);
}

.press-signal.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.app--voice-quiet .press-signal { --press-signal-tone: var(--blue); }
.app--voice-human .press-signal { --press-signal-tone: var(--coral); }
.app--voice-bold .press-signal { --press-signal-tone: var(--acid); }

@media (prefers-reduced-motion: reduce) {
  .press-signal { opacity: 1 !important; transform: none !important; transition: none !important; }
  .press-signal__rule-stroke,
  .press-signal__strike,
  .press-signal__strike-disc,
  .press-signal__tag,
  .press-signal__strike-splash-stroke { animation: none !important; opacity: 1 !important; stroke-dashoffset: 0 !important; transform: none !important; }
}

.press-signal__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

/* Lead rule — a quiet hand-drawn line above the strike */

.press-signal__rule {
  position: relative;
  display: block;
  width: min(100%, 360px);
  height: 4px;
  color: inherit;
  pointer-events: none;
}

.press-signal__rule--lead {
  margin-bottom: clamp(4px, .8vw, 10px);
  opacity: 0;
  animation: pressSignalRuleIn .9s var(--ease-out) .25s forwards;
}

.press-signal__rule--trail {
  margin-top: clamp(6px, .8vw, 10px);
  opacity: 0;
  animation: pressSignalRuleIn .9s var(--ease-out) 1.85s forwards;
}

.press-signal__rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.press-signal__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: pressSignalDraw 1.2s var(--ease-out) .4s forwards;
}

.press-signal__rule-stroke--alt {
  animation-delay: 1.95s;
}

@keyframes pressSignalRuleIn {
  to { opacity: .85; }
}

@keyframes pressSignalDraw {
  to { stroke-dashoffset: 0; }
}

/* The strike — a single hand-pressed mark at the center */

.press-signal__strike {
  position: relative;
  display: grid;
  place-items: center;
  width: clamp(72px, 7.4vw, 96px);
  height: clamp(72px, 7.4vw, 96px);
  margin: 0;
  z-index: 1;
  opacity: 0;
  animation: pressSignalStrikeIn .95s var(--ease-spring) .75s forwards;
}

@keyframes pressSignalStrikeIn {
  0% { opacity: 0; transform: scale(.55) rotate(-10deg); }
  55% { opacity: 1; transform: scale(1.12) rotate(3deg); }
  100% { opacity: 1; transform: scale(1) rotate(0); }
}

.press-signal__strike-flash {
  position: absolute;
  inset: -32px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, currentColor 28%, transparent) 0%, transparent 62%);
  pointer-events: none;
  opacity: 0;
  animation: pressSignalFlash 1.6s var(--ease-out) .75s forwards;
}

@keyframes pressSignalFlash {
  0% { opacity: 0; transform: scale(.6); }
  30% { opacity: .9; transform: scale(1.05); }
  100% { opacity: 0; transform: scale(1.25); }
}

.press-signal__strike-disc {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  color: inherit;
  z-index: 1;
  filter: drop-shadow(0 1px 0 rgba(0, 0, 0, .35));
}

.press-signal__strike-disc svg {
  display: block;
  width: 100%;
  height: 100%;
}

.press-signal__strike-wisp {
  position: absolute;
  top: 92%;
  left: 50%;
  width: 22px;
  height: 10px;
  transform: translate(-50%, 0) rotate(-8deg);
  background: radial-gradient(ellipse, color-mix(in srgb, currentColor 65%, transparent) 0%, transparent 70%);
  filter: blur(.5px);
  pointer-events: none;
  opacity: .75;
}

.press-signal__strike-splash {
  position: absolute;
  top: 100%;
  left: 50%;
  width: clamp(140px, 18vw, 220px);
  height: 32px;
  transform: translate(-50%, 8px);
  pointer-events: none;
  opacity: 0;
  animation: pressSignalSplashIn .9s var(--ease-out) 1.35s forwards;
}

.press-signal__strike-splash svg {
  display: block;
  width: 100%;
  height: 100%;
}

.press-signal__strike-splash-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: pressSignalDraw 1s var(--ease-out) 1.45s forwards;
}

@keyframes pressSignalSplashIn {
  to { opacity: 1; }
}

/* The caption — a single line beneath the strike */

.press-signal__tag {
  margin-top: clamp(10px, 1.6vw, 18px);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  opacity: 0;
  animation: pressSignalTagIn .8s var(--ease-out) 1.7s forwards;
}

@keyframes pressSignalTagIn {
  to { opacity: .9; }
}

.press-signal__tag-line {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1.05vw, 13px);
  color: color-mix(in srgb, currentColor 88%, var(--paper));
  letter-spacing: -.002em;
  white-space: nowrap;
  opacity: .92;
}

.press-signal__tag-sep {
  display: inline-block;
  margin: 0 .35em;
  font-style: normal;
  opacity: .55;
}

/* Responsive */

@media (max-width: 720px) {
  .press-signal {
    --press-signal-h: clamp(140px, 36vw, 180px);
  }
  .press-signal__strike { width: 64px; height: 64px; }
  .press-signal__rule { width: min(100%, 260px); }
}

@media (max-width: 480px) {
  .press-signal__tag-line { font-size: 10.5px; }
  .press-signal__strike { width: 56px; height: 56px; }
  .press-signal__strike-splash { width: 140px; }
}

/* ────────────────────────────────────────────────────────────
   iteration 339 · FOLIO HINGE
   A single hand-pressed fold plate that lives between folio i
   and folio ii. The plate does one thing — it folds the page.
   Two short rules run out of a pressed seal, an italic caption
   names the next folio, and the whole plate scrolls to the
   press bed. Quiet by design; earns its place in the breath
   between the front matter and the press work.
   ──────────────────────────────────────────────────────────── */

.folio-hinge {
  --folio-hinge-tone: var(--coral);

  position: relative;
  display: grid;
  justify-items: center;
  width: min(100%, 760px);
  margin: clamp(40px, 5.4vw, 76px) auto clamp(36px, 4.8vw, 64px);
  padding: 0 clamp(16px, 2.4vw, 28px);
  isolation: isolate;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 1s var(--ease-out) .05s, transform 1s var(--ease-out) .05s, color .5s var(--ease);
  color: var(--folio-hinge-tone);
}

.folio-hinge.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.app--voice-quiet .folio-hinge { --folio-hinge-tone: var(--blue); }
.app--voice-human .folio-hinge { --folio-hinge-tone: var(--coral); }
.app--voice-bold .folio-hinge { --folio-hinge-tone: var(--acid); }

@media (prefers-reduced-motion: reduce) {
  .folio-hinge { opacity: 1 !important; transform: none !important; transition: none !important; }
  .folio-hinge__rule-stroke { animation: none !important; stroke-dashoffset: 0 !important; }
  .folio-hinge__seal,
  .folio-hinge__seal-halo { animation: none !important; opacity: 1 !important; transform: none !important; }
  .folio-hinge__eyebrow-tag,
  .folio-hinge__caption,
  .folio-hinge__hint { animation: none !important; opacity: 1 !important; transform: none !important; }
}

.folio-hinge__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

/* the plate itself — a single composed button */
.folio-hinge__plate {
  position: relative;
  display: grid;
  grid-template-rows: auto auto auto auto;
  justify-items: center;
  row-gap: clamp(12px, 1.4vw, 18px);
  width: 100%;
  padding: clamp(20px, 2.6vw, 30px) clamp(24px, 3.4vw, 42px) clamp(22px, 2.8vw, 34px);
  border: 1px solid color-mix(in srgb, var(--folio-hinge-tone) 22%, transparent);
  border-radius: 2px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--folio-hinge-tone) 6%, transparent), transparent 86%),
    linear-gradient(180deg, rgba(20, 26, 38, .28), rgba(12, 16, 26, .44));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--folio-hinge-tone) 6%, transparent),
    inset 0 1px 0 rgba(243, 236, 214, .04);
  cursor: pointer;
  color: inherit;
  font: inherit;
  text-align: center;
  transition:
    background .4s var(--ease),
    border-color .4s var(--ease),
    transform .4s var(--ease);
}

.folio-hinge__plate:hover,
.folio-hinge__plate:focus-visible {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--folio-hinge-tone) 10%, transparent), transparent 86%),
    linear-gradient(180deg, rgba(28, 36, 52, .42), rgba(16, 22, 32, .5));
  border-color: color-mix(in srgb, var(--folio-hinge-tone) 46%, transparent);
}

.folio-hinge__plate:focus-visible {
  outline: 2px solid var(--folio-hinge-tone);
  outline-offset: 4px;
}

.folio-hinge__plate:active {
  transform: translateY(1px);
}

/* corner crops */
.folio-hinge__corner {
  position: absolute;
  width: 14px;
  height: 14px;
  color: var(--folio-hinge-tone);
  opacity: .65;
  pointer-events: none;
}

.folio-hinge__corner::before,
.folio-hinge__corner::after {
  content: '';
  position: absolute;
  background: currentColor;
  border-radius: .5px;
}

.folio-hinge__corner::before { width: 10px; height: 1px; }
.folio-hinge__corner::after { width: 1px; height: 10px; }

.folio-hinge__corner--tl { top: 4px; left: 4px; }
.folio-hinge__corner--tl::before { top: 0; left: 0; }
.folio-hinge__corner--tl::after { top: 0; left: 0; }

.folio-hinge__corner--tr { top: 4px; right: 4px; }
.folio-hinge__corner--tr::before { top: 0; right: 0; }
.folio-hinge__corner--tr::after { top: 0; right: 0; }

.folio-hinge__corner--bl { bottom: 4px; left: 4px; }
.folio-hinge__corner--bl::before { bottom: 0; left: 0; }
.folio-hinge__corner--bl::after { bottom: 0; left: 0; }

.folio-hinge__corner--br { bottom: 4px; right: 4px; }
.folio-hinge__corner--br::before { bottom: 0; right: 0; }
.folio-hinge__corner--br::after { bottom: 0; right: 0; }

/* eyebrow */
.folio-hinge__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 12px);
  width: 100%;
  justify-content: center;
  max-width: 620px;
}

.folio-hinge__eyebrow-rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(to right, transparent, color-mix(in srgb, var(--folio-hinge-tone) 35%, transparent));
  min-width: clamp(20px, 4vw, 48px);
  max-width: clamp(80px, 14vw, 200px);
}

.folio-hinge__eyebrow-rule--alt {
  background: linear-gradient(to left, transparent, color-mix(in srgb, var(--folio-hinge-tone) 35%, transparent));
}

.folio-hinge__eyebrow-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--folio-hinge-tone);
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 10px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: 0;
  animation: folioHingeEyebrowIn .7s var(--ease-out) .15s forwards;
  white-space: nowrap;
}

.folio-hinge__eyebrow-tag em {
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.05em;
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--folio-hinge-tone);
}

.folio-hinge__eyebrow-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
}

.folio-hinge__eyebrow-sep {
  opacity: .5;
  color: var(--ink-mist);
  font-family: var(--mono);
}

@keyframes folioHingeEyebrowIn { to { opacity: 1; } }

/* seam — rule + seal + rule */
.folio-hinge__seam {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: clamp(8px, 1vw, 18px);
  width: 100%;
  max-width: 600px;
  margin: clamp(2px, .3vw, 6px) auto 0;
}

.folio-hinge__rule {
  display: block;
  width: 100%;
  height: 6px;
  color: var(--folio-hinge-tone);
}

.folio-hinge__rule svg {
  display: block;
  width: 100%;
  height: 100%;
}

.folio-hinge__rule-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  animation: folioHingeRuleDraw 1.4s var(--ease-out) .35s forwards;
}

.folio-hinge__rule-stroke--alt {
  animation-delay: .55s;
}

@keyframes folioHingeRuleDraw { to { stroke-dashoffset: 0; } }

.folio-hinge__seal {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(54px, 5.4vw, 72px);
  height: clamp(54px, 5.4vw, 72px);
  color: var(--folio-hinge-tone);
  transform: rotate(-4deg);
  opacity: 0;
  animation: folioHingeSealIn .9s var(--ease-spring) .7s forwards;
  transition: transform .55s var(--ease-spring);
  filter: drop-shadow(0 1px 0 color-mix(in srgb, var(--folio-hinge-tone) 30%, transparent));
}

.folio-hinge__seal svg {
  display: block;
  width: 100%;
  height: 100%;
}

.folio-hinge__seal-wax {
  position: absolute;
  bottom: -2px;
  right: -2px;
  width: 14px;
  height: 10px;
  pointer-events: none;
  opacity: .85;
}

.folio-hinge__seal-wax-bead {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--folio-hinge-tone);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--folio-hinge-tone) 22%, transparent);
}

.folio-hinge__seal-wax-wisp {
  position: absolute;
  top: 100%;
  left: 50%;
  width: 16px;
  height: 6px;
  transform: translate(-50%, -2px);
  background: radial-gradient(ellipse, color-mix(in srgb, var(--folio-hinge-tone) 60%, transparent), transparent 70%);
  filter: blur(.5px);
  opacity: .8;
}

.folio-hinge__plate:hover .folio-hinge__seal,
.folio-hinge__plate:focus-visible .folio-hinge__seal {
  transform: rotate(-2deg) scale(1.05);
}

@keyframes folioHingeSealIn {
  0% { opacity: 0; transform: rotate(-12deg) scale(.55); }
  60% { opacity: 1; transform: rotate(0deg) scale(1.08); }
  100% { opacity: 1; transform: rotate(-4deg) scale(1); }
}

/* caption */
.folio-hinge__caption {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  justify-content: center;
  column-gap: clamp(8px, 1vw, 12px);
  row-gap: 4px;
  margin: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(14px, 1.25vw, 16.5px);
  letter-spacing: -.002em;
  line-height: 1.35;
  opacity: 0;
  animation: folioHingeCaptionIn .85s var(--ease-out) 1.1s forwards;
  max-width: 38ch;
}

.folio-hinge__caption em {
  color: var(--folio-hinge-tone);
  font-style: italic;
}

.folio-hinge__caption-mark {
  font-style: normal;
  font-family: var(--serif);
  font-size: 1.05em;
  opacity: .8;
  color: var(--folio-hinge-tone);
}

.folio-hinge__caption-mark--alt {
  transform: scaleX(-1);
  display: inline-block;
}

@keyframes folioHingeCaptionIn { to { opacity: 1; } }

/* hint */
.folio-hinge__hint {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .8vw, 10px);
  color: var(--ink-mist);
  font-family: var(--mono);
  font-size: clamp(8px, .7vw, 9px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: 0;
  animation: folioHingeHintIn .7s var(--ease-out) 1.35s forwards;
  white-space: nowrap;
}

.folio-hinge__hint em {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .9vw, 12px);
  letter-spacing: -.002em;
  text-transform: none;
  color: var(--ink-mist);
}

.folio-hinge__hint-rule {
  display: inline-block;
  width: clamp(20px, 2.4vw, 36px);
  height: 1px;
  background: currentColor;
  opacity: .5;
}

@keyframes folioHingeHintIn { to { opacity: 1; } }

/* arrow — bottom right, signals the scroll forward */
.folio-hinge__arrow {
  position: absolute;
  bottom: clamp(14px, 2vw, 22px);
  right: clamp(18px, 2.6vw, 32px);
  width: clamp(18px, 1.6vw, 22px);
  height: clamp(18px, 1.6vw, 22px);
  color: var(--folio-hinge-tone);
  opacity: .55;
  transition: transform .45s var(--ease-spring), opacity .35s var(--ease);
  pointer-events: none;
}

.folio-hinge__plate:hover .folio-hinge__arrow,
.folio-hinge__plate:focus-visible .folio-hinge__arrow {
  transform: translateX(4px);
  opacity: 1;
}

.folio-hinge__arrow svg {
  display: block;
  width: 100%;
  height: 100%;
}

/* responsive */
@media (max-width: 720px) {
  .folio-hinge {
    margin: clamp(30px, 4.4vw, 44px) auto clamp(28px, 4vw, 40px);
  }
  .folio-hinge__plate {
    padding: clamp(16px, 3vw, 22px) clamp(18px, 3vw, 28px) clamp(18px, 3vw, 24px);
  }
  .folio-hinge__seal {
    width: 50px;
    height: 50px;
  }
  .folio-hinge__caption {
    font-size: clamp(13px, 3vw, 15px);
  }
}

@media (max-width: 480px) {
  .folio-hinge__seam {
    gap: 6px;
  }
  .folio-hinge__seal {
    width: 44px;
    height: 44px;
  }
  .folio-hinge__arrow {
    position: static;
    transform: none;
    margin-top: 4px;
  }
  .folio-hinge__plate {
    padding-bottom: clamp(20px, 5vw, 28px);
  }
  .folio-hinge__hint {
    font-size: 8px;
  }
}

/* ────────────────────────────────────────────────────────────
   ITERATION 340 · "the press breath" · a single composed
   flourish that ties the lever moment to the page. Refines
   the title-page rhythm, polishes the title broadside, and
   makes the press-lever pull feel consequential.
   ──────────────────────────────────────────────────────────── */

/* PRESS BREATH · the page's quiet exhale that draws across the
   title-page edge once revealed, and re-draws brightly the moment
   the lever is pulled. Two lines, a small mark, a fading halo. */

.press-breath {
  --press-breath-tone: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  row-gap: clamp(8px, 1vw, 12px);
  width: min(100%, 720px);
  margin: clamp(16px, 2.4vw, 28px) auto clamp(20px, 2.8vw, 36px);
  color: var(--press-breath-tone);
  isolation: isolate;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .9s var(--ease-out) .15s, transform .9s var(--ease-out) .15s;
}

.press-breath.is-revealed {
  opacity: 1;
  transform: none;
}

.app--voice-quiet .press-breath { --press-breath-tone: var(--blue); }
.app--voice-human .press-breath { --press-breath-tone: var(--coral); }
.app--voice-bold .press-breath { --press-breath-tone: var(--acid); }

@media (prefers-reduced-motion: reduce) {
  .press-breath { opacity: 1 !important; transform: none !important; transition: none !important; }
  .press-breath__rule-stroke,
  .press-breath__rule-bead,
  .press-breath__rule-halo,
  .press-breath__mark-line,
  .press-breath__mark-bead { animation: none !important; transition: none !important; }
  .press-breath__rule-stroke--lead,
  .press-breath__rule-stroke--trail { stroke-dashoffset: 0 !important; opacity: .6 !important; }
  .press-breath__rule-bead--lead,
  .press-breath__rule-bead--trail,
  .press-breath__mark-bead { opacity: 1 !important; transform: none !important; }
  .press-breath__mark-line { opacity: 1 !important; transform: none !important; }
}

.press-breath__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

.press-breath__rule {
  display: block;
  width: 100%;
  height: clamp(4px, .6vw, 8px);
  color: var(--press-breath-tone);
  opacity: .85;
}

.press-breath__rule svg { width: 100%; height: 100%; display: block; }

.press-breath__rule-stroke--lead,
.press-breath__rule-stroke--trail {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.5s var(--ease-out) .25s, opacity .9s var(--ease);
}

.press-breath.is-revealed .press-breath__rule-stroke--lead { stroke-dashoffset: 0; }
.press-breath.is-revealed .press-breath__rule-stroke--trail {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset 1.7s var(--ease-out) .55s, opacity .9s var(--ease);
}

.press-breath.is-active .press-breath__rule-stroke--lead {
  animation: pressBreathRulePulse .6s var(--ease-out);
}

@keyframes pressBreathRulePulse {
  0% { opacity: .85; }
  35% { opacity: 1; }
  100% { opacity: .85; }
}

.press-breath__rule-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .4s var(--ease), transform .55s var(--ease-spring);
}

.press-breath__rule-bead--lead {
  transform: scale(.3);
  transition-delay: .2s;
}

.press-breath__rule-bead--trail {
  transform: scale(.5);
  transition-delay: 1.6s;
}

.press-breath.is-revealed .press-breath__rule-bead { opacity: 1; transform: scale(1); }

.press-breath__rule-halo {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .55s var(--ease) 1.85s;
}

.press-breath.is-revealed .press-breath__rule-halo {
  opacity: .55;
}

.press-breath.is-active .press-breath__rule-halo {
  animation: pressBreathHaloBurst .6s var(--ease-out);
}

@keyframes pressBreathHaloBurst {
  0%   { opacity: .55; transform: scale(1); }
  40%  { opacity: 1;   transform: scale(1.6); }
  100% { opacity: 0;   transform: scale(2); }
}

.press-breath__mark {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  color: var(--press-breath-tone);
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 10px);
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity .8s var(--ease-out) 1.95s;
}

.press-breath.is-revealed .press-breath__mark { opacity: .88; }

.press-breath__mark-rule {
  flex: 1 1 auto;
  width: clamp(20px, 5vw, 56px);
  height: 1px;
  background: linear-gradient(to right, transparent, currentColor);
  opacity: .55;
}

.press-breath__mark-rule--alt {
  background: linear-gradient(to left, transparent, currentColor);
}

.press-breath__mark-line {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, .95vw, 13px);
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--press-breath-tone);
  white-space: nowrap;
  opacity: 0;
  transform: translateY(2px);
  transition: opacity .7s var(--ease-out) 2.05s, transform .8s var(--ease-out) 2.05s;
}

.press-breath.is-revealed .press-breath__mark-line {
  opacity: 1;
  transform: none;
}

.press-breath.is-active .press-breath__mark-line {
  animation: pressBreathLinePulse .6s var(--ease-out);
}

@keyframes pressBreathLinePulse {
  0%   { opacity: 1; }
  30%  { opacity: .6; }
  60%  { opacity: 1; }
  100% { opacity: 1; }
}

.press-breath__mark-bead {
  display: inline-block;
  width: clamp(5px, .5vw, 7px);
  height: clamp(5px, .5vw, 7px);
  border-radius: 50%;
  background: var(--press-breath-tone);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--press-breath-tone) 22%, transparent);
  opacity: 0;
  transform: scale(.3);
  transition: opacity .5s var(--ease) 2.15s, transform .6s var(--ease-spring) 2.15s;
}

.press-breath.is-revealed .press-breath__mark-bead { opacity: 1; transform: scale(1); }

@media (max-width: 540px) {
  .press-breath {
    margin: clamp(12px, 3vw, 18px) auto clamp(16px, 3.4vw, 24px);
    row-gap: 6px;
  }
  .press-breath__mark-line {
    font-size: clamp(10.5px, 3.2vw, 12px);
  }
}

/* PRESS IMPACT · a brief, page-wide confirmation that the lever
   pulled. A single radial pulse emanates from the lever's pivot
   upward across the title page and fades within ~1.4s. Applied
   on the body via a class set briefly when the lever pulls. */

.press-impact {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 100vh;
  pointer-events: none;
  z-index: 1;
  background: radial-gradient(ellipse at 50% 38%, color-mix(in srgb, var(--coral) 10%, transparent), transparent 48%);
  opacity: 0;
}

.app--voice-quiet .press-impact {
  background: radial-gradient(ellipse at 50% 38%, color-mix(in srgb, var(--blue) 10%, transparent), transparent 48%);
}

.app--voice-human .press-impact {
  background: radial-gradient(ellipse at 50% 38%, color-mix(in srgb, var(--coral) 10%, transparent), transparent 48%);
}

.app--voice-bold .press-impact {
  background: radial-gradient(ellipse at 50% 38%, color-mix(in srgb, var(--acid) 10%, transparent), transparent 48%);
}

.press-impact.is-stamping {
  animation: pressImpact .6s var(--ease-out);
}

@keyframes pressImpact {
  0%   { opacity: 0; }
  22%  { opacity: 1; }
  100% { opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .press-impact { display: none !important; }
}

/* TITLE-PAGE RHYTHM · tighter spacing between the broadside and
   the prologue, and a quieter prologue presence. When the children
   sit inside .opening the outer chrome is already stripped; here
   we tighten the inner composition so they read as one breath. */

.opening .tb + .reading-prologue {
  margin-top: clamp(16px, 2.2vw, 28px);
}

.opening .reading-prologue {
  padding-top: clamp(14px, 1.8vw, 22px);
  padding-bottom: clamp(14px, 1.8vw, 26px);
}

.opening .reading-prologue__head {
  margin-bottom: clamp(8px, 1vw, 12px);
}

.opening .reading-prologue__lede {
  font-size: clamp(13.5px, 1.18vw, 16px);
  line-height: 1.5;
  max-width: 62ch;
  margin-inline: auto;
  text-align: center;
}

.opening .reading-prologue__readings {
  gap: clamp(6px, .7vw, 10px);
}

.opening .reading-prologue__reading {
  padding: clamp(8px, .9vw, 11px) clamp(12px, 1.4vw, 18px);
  background: linear-gradient(180deg, rgba(28, 36, 52, .12), rgba(14, 20, 32, .22));
}

.opening .reading-prologue__reading-echo {
  font-size: clamp(11px, .95vw, 12.5px);
}

.opening .reading-prologue__thread {
  display: none;
}

.opening .reading-prologue__foot {
  margin-top: clamp(6px, .8vw, 10px);
  padding-top: clamp(6px, .8vw, 10px);
}

.opening .reading-prologue + .press-lever {
  margin-top: clamp(20px, 2.6vw, 36px);
}

.opening .press-lever {
  padding: clamp(14px, 1.6vw, 20px) clamp(16px, 2vw, 26px) clamp(16px, 1.8vw, 22px);
}

.opening .press-lever__head {
  margin-bottom: clamp(6px, .7vw, 10px);
}

.opening .press-lever__main {
  gap: clamp(14px, 2vw, 26px);
  padding-top: clamp(8px, 1vw, 14px);
}

@media (max-width: 720px) {
  .opening .reading-prologue__lede {
    text-align: left;
    max-width: none;
  }
  .opening .press-lever__main {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    text-align: center;
  }
}

/* TITLE BROADSIDE · polish the typography balance and the voice
   selector affordance. The token marks already carry weight; this
   sharpens the spacing between headline lines and the breath below. */

.tb__statement-lines {
  text-wrap: balance;
}

.tb__statement-lines > .tb__line--b {
  gap: clamp(10px, 1.2vw, 18px);
}

.tb__token-mark {
  letter-spacing: .14em;
}

.tb.is-stamping .tb__statement-lines {
  animation: tbStatementPulse .85s var(--ease);
}

@keyframes tbStatementPulse {
  0%   { transform: translateY(0); }
  35%  { transform: translateY(2px) scale(.998); }
  100% { transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .tb.is-stamping .tb__statement-lines { animation: none !important; }
}

/* PRESS LEVER · polish the pull moment. When the lever body
   carries the .is-pulled class the shaft tilts further forward
   with a subtle settled position. The bloom softens. The action
   button settles after a brief press-impact pop. */

.press-lever__lever-shaft-group {
  transition: transform .65s var(--ease-spring), filter .55s var(--ease);
}

.press-lever__lever.is-pulled .press-lever__lever-shaft-group {
  transform: rotate(32deg);
  filter: drop-shadow(0 2px 0 rgba(0, 0, 0, .25));
}

.press-lever.is-open .press-lever__lever {
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--press-lever-tone) 16%, transparent),
    0 0 28px -6px color-mix(in srgb, var(--press-lever-tone) 32%, transparent);
}

.press-lever.is-open .press-lever__action-line {
  text-shadow: 0 0 .04em color-mix(in srgb, var(--press-lever-tone) 22%, transparent);
}

/* When the action button is being stamped, briefly raise the entire
   .press-lever plate by a fraction of a pixel so the press impact
   is felt as a small physical pulse. */

.press-lever.is-stamping .press-lever__bloom {
  animation: pressLeverBloomPulse .6s var(--ease-out);
}

@keyframes pressLeverBloomPulse {
  0%   { opacity: 1; transform: scale(1); }
  40%  { opacity: 1; transform: scale(1.04); }
  100% { opacity: 1; transform: scale(1); }
}

/* READERS NOTE · a subtle inner polish that ties the title page
   and the frontmatter so the seam doesn't shout. */

.hero__body {
  padding-top: clamp(28px, 4vw, 44px);
}

.hero__body .hero__body-plate {
  margin-bottom: clamp(14px, 1.8vw, 22px);
}

/* RUNNING HEADER · tie the press register to the lever moment by
   briefly brightening the voice pip when the lever is pulled. */

.site-header__set-mark {
  transition: transform .55s var(--ease-spring), background .45s var(--ease), box-shadow .55s var(--ease);
}

.app.is-lever-stamping .site-header__set-mark {
  transform: scale(1.4);
  box-shadow: 0 0 0 4px color-mix(in srgb, currentColor 18%, transparent), 0 0 18px color-mix(in srgb, currentColor 38%, transparent);
}

/* MOBILE · tighten mobile layout for the title page stack. */

@media (max-width: 720px) {
  .opening .reading-prologue {
    padding-left: clamp(8px, 3vw, 14px);
    padding-right: clamp(8px, 3vw, 14px);
  }
  .opening .reading-prologue__reading {
    grid-template-columns: minmax(0, 1fr);
    row-gap: 6px;
  }
  .opening .reading-prologue__reading-word {
    justify-self: start;
  }
  .opening .press-lever__head-tag {
    font-size: 9px;
    letter-spacing: .2em;
  }
  .opening .press-lever__action-button {
    grid-template-columns: minmax(0, 1fr) clamp(24px, 6vw, 32px);
  }
}

/* ────────────────────────────────────────────────────────────
   ITERATION 342 · FOLIO IMPRINT — a single composed opening
   dedication. One plate, three breaths: the lead flourish,
   the centered memo, the trail flourish, all set between
   a small press seal and a thread that descends toward
   the title broadside below. Replaces nothing; gives the
   page a hand-pressed opening it earns on arrival.
   ──────────────────────────────────────────────────────────── */

.folio-imprint {
  --imprint-tone: var(--coral);
  position: relative;
  display: grid;
  justify-items: center;
  width: min(100%, 1080px);
  margin: clamp(36px, 5vw, 64px) auto clamp(28px, 3.6vw, 48px);
  padding: 0 clamp(14px, 2.4vw, 28px);
  color: var(--imprint-tone);
  isolation: isolate;
  opacity: 0;
  transform: translateY(8px);
  transition:
    opacity 1.1s var(--ease-out) .15s,
    transform 1.1s var(--ease-out) .15s,
    color .55s var(--ease);
}

.folio-imprint.is-revealed {
  opacity: 1;
  transform: translateY(0);
}

.folio-imprint--quiet { --imprint-tone: var(--blue); }
.folio-imprint--human { --imprint-tone: var(--coral); }
.folio-imprint--bold { --imprint-tone: var(--acid); }

.folio-imprint__defs {
  position: absolute;
  width: 0;
  height: 0;
  pointer-events: none;
  overflow: hidden;
}

.folio-imprint__wash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 50%, color-mix(in srgb, var(--imprint-tone) 6%, transparent), transparent 64%);
  opacity: 0;
  animation: folioImprintWashIn 1.4s var(--ease-out) .25s forwards;
}

@keyframes folioImprintWashIn {
  to { opacity: 1; }
}

.folio-imprint__plate {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(10px, 1.6vw, 22px);
  width: 100%;
  padding: clamp(14px, 2vw, 22px) clamp(6px, 1.2vw, 14px);
  background: transparent;
  border: 0;
  cursor: default;
  color: inherit;
  font: inherit;
  text-align: left;
}

.folio-imprint__plate:focus-visible {
  outline: 1px dashed color-mix(in srgb, var(--imprint-tone) 50%, transparent);
  outline-offset: 6px;
}

.folio-imprint__flourish {
  position: relative;
  display: flex;
  align-items: center;
  gap: clamp(6px, .8vw, 12px);
  min-width: 0;
  color: currentColor;
  opacity: 0;
  transition: opacity .9s var(--ease-out) .35s, transform .9s var(--ease-out) .35s;
}

.folio-imprint.is-revealed .folio-imprint__flourish {
  opacity: 1;
}

.folio-imprint__flourish--lead {
  justify-content: flex-end;
  transform: translateX(-4px);
}

.folio-imprint.is-revealed .folio-imprint__flourish--lead {
  transform: translateX(0);
}

.folio-imprint__flourish--trail {
  justify-content: flex-start;
  transform: translateX(4px);
}

.folio-imprint.is-revealed .folio-imprint__flourish--trail {
  transform: translateX(0);
}

.folio-imprint__flourish svg {
  display: block;
  width: clamp(80px, 14vw, 180px);
  height: clamp(20px, 2.6vw, 32px);
  flex: 1 1 auto;
  min-width: 0;
}

.folio-imprint__flourish-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.4s var(--ease-out) .5s;
}

.folio-imprint.is-revealed .folio-imprint__flourish-stroke {
  stroke-dashoffset: 0;
}

.folio-imprint__flourish-stroke--trail {
  transition-delay: .75s;
}

.folio-imprint.is-revealed .folio-imprint__flourish-stroke--mirror {
  transition-delay: .6s;
}

.folio-imprint__flourish-bead,
.folio-imprint__flourish-halo {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transition: opacity .55s var(--ease) 1.55s, transform .65s var(--ease-spring) 1.55s;
}

.folio-imprint.is-revealed .folio-imprint__flourish-bead,
.folio-imprint.is-revealed .folio-imprint__flourish-halo {
  opacity: 1;
  transform: scale(1);
}

.folio-imprint__flourish-pip {
  display: inline-grid;
  place-items: center;
  width: clamp(20px, 2vw, 26px);
  height: clamp(20px, 2vw, 26px);
  border: 1px solid currentColor;
  border-radius: 50%;
  color: currentColor;
  flex: 0 0 auto;
  opacity: 0;
  transform: scale(.6);
  transition: opacity .55s var(--ease) 1.6s, transform .65s var(--ease-spring) 1.6s, color .35s var(--ease);
}

.folio-imprint.is-revealed .folio-imprint__flourish-pip {
  opacity: 1;
  transform: scale(1);
}

.folio-imprint__flourish-pip--alt {
  order: -1;
}

.folio-imprint__flourish-pip-ring {
  position: absolute;
  inset: 3px;
  border: 1px dashed currentColor;
  border-radius: 50%;
  opacity: .5;
}

.folio-imprint__flourish-pip-bead {
  display: inline-block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
}

.folio-imprint.is-hover .folio-imprint__flourish-pip {
  transform: scale(1.12);
}

.folio-imprint__core {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(12px, 1.8vw, 24px);
  min-width: 0;
  padding: clamp(2px, .4vw, 6px) clamp(8px, 1.4vw, 18px);
}

.folio-imprint__stamp {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: clamp(54px, 5.6vw, 72px);
  height: clamp(54px, 5.6vw, 72px);
  color: currentColor;
  flex: 0 0 auto;
  opacity: 0;
  transform: scale(.7) rotate(-6deg);
  transform-origin: center;
  transition:
    opacity .75s var(--ease) .35s,
    transform .9s var(--ease-spring) .35s,
    color .35s var(--ease);
}

.folio-imprint.is-revealed .folio-imprint__stamp {
  opacity: 1;
  transform: scale(1) rotate(-3deg);
}

.folio-imprint__stamp-halo {
  position: absolute;
  inset: -8px;
  border: 1px dashed color-mix(in srgb, var(--imprint-tone) 28%, transparent);
  border-radius: 50%;
  opacity: 0;
  transform: scale(.85);
  transition: opacity .65s var(--ease) 1s, transform .9s var(--ease-spring) 1s;
}

.folio-imprint.is-revealed .folio-imprint__stamp-halo {
  opacity: .55;
  transform: scale(1);
}

.folio-imprint.is-hover .folio-imprint__stamp {
  transform: scale(1.04) rotate(-1deg);
}

.folio-imprint__memo {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: clamp(6px, .7vw, 10px);
  min-width: 0;
}

.folio-imprint__memo-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1vw, 14px);
  color: currentColor;
  font-family: var(--mono);
  font-size: clamp(8.5px, .8vw, 10.5px);
  font-weight: 500;
  letter-spacing: .26em;
  text-transform: uppercase;
  opacity: 0;
  transform: translateY(-3px);
  transition: opacity .65s var(--ease-out) .45s, transform .65s var(--ease-out) .45s;
}

.folio-imprint.is-revealed .folio-imprint__memo-eyebrow {
  opacity: 1;
  transform: translateY(0);
}

.folio-imprint__memo-rule {
  display: inline-block;
  width: clamp(14px, 2vw, 28px);
  height: 1px;
  background: currentColor;
  opacity: .55;
  flex: 0 0 auto;
}

.folio-imprint__memo-eyebrow-tag {
  display: inline-flex;
  align-items: center;
  gap: clamp(6px, .7vw, 10px);
  white-space: nowrap;
}

.folio-imprint__memo-mark {
  display: inline-grid;
  place-items: center;
  font-family: Georgia, 'Iowan Old Style', serif;
  font-style: italic;
  font-size: 13px;
  letter-spacing: 0;
  color: currentColor;
  opacity: .8;
}

.folio-imprint__memo-mark--alt {
  transform: scaleX(-1);
}

.folio-imprint__memo-line {
  margin: 0;
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.45vw, 19px);
  letter-spacing: -.012em;
  line-height: 1.35;
  text-wrap: balance;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity .85s var(--ease-out) .6s, transform .85s var(--ease-out) .6s;
}

.folio-imprint.is-revealed .folio-imprint__memo-line {
  opacity: 1;
  transform: translateY(0);
}

.folio-imprint__memo-line em {
  font-style: italic;
  color: currentColor;
  font-feature-settings: 'kern' 1, 'liga' 1, 'dlig' 1, 'onum' 1;
  text-shadow: 0 0 .04em color-mix(in srgb, currentColor 16%, transparent);
}

.folio-imprint__memo-line em:nth-of-type(2) {
  color: var(--paper);
  text-shadow: none;
}

.folio-imprint__memo-meta {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: clamp(8px, 1vw, 14px);
  color: var(--muted);
  font-family: var(--mono);
  font-size: clamp(8.5px, .76vw, 9.5px);
  letter-spacing: .22em;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity .7s var(--ease-out) .95s;
}

.folio-imprint.is-revealed .folio-imprint__memo-meta {
  opacity: 1;
}

.folio-imprint__memo-cell {
  display: inline-flex;
  align-items: baseline;
  gap: clamp(6px, .7vw, 10px);
}

.folio-imprint__memo-key {
  color: var(--muted);
  font-family: var(--mono);
}

.folio-imprint__memo-voice {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  color: currentColor;
  font-family: var(--mono);
}

.folio-imprint__memo-voice em {
  color: var(--paper);
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: -.005em;
  text-transform: none;
}

.folio-imprint__memo-voice-letter {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: currentColor;
  font-family: var(--serif);
  font-style: italic;
  font-size: 10px;
  letter-spacing: 0;
  text-transform: none;
}

.folio-imprint__memo-date {
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
}

.folio-imprint__memo-season {
  font-family: var(--serif);
  font-style: italic;
  font-size: 12px;
  letter-spacing: -.005em;
  text-transform: none;
  color: var(--paper);
}

.folio-imprint__memo-season em {
  color: currentColor;
  font-family: var(--mono);
  font-style: normal;
  font-size: 9px;
  letter-spacing: .22em;
  text-transform: uppercase;
}

.folio-imprint__memo-sep {
  color: var(--ink-mist);
  opacity: .55;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0;
}

/* thread — a small descent between the imprint and the title */
.folio-imprint__thread {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 6px;
  margin-top: clamp(6px, .8vw, 12px);
  color: currentColor;
  opacity: 0;
  transition: opacity .85s var(--ease-out) 1.2s;
}

.folio-imprint.is-revealed .folio-imprint__thread {
  opacity: 1;
}

.folio-imprint__thread svg {
  display: block;
  width: clamp(18px, 2vw, 24px);
  height: clamp(36px, 4.4vw, 56px);
}

.folio-imprint__thread-stroke {
  stroke-dasharray: 100 100;
  stroke-dashoffset: 100;
  transition: stroke-dashoffset 1.1s var(--ease-out) 1.3s;
}

.folio-imprint.is-revealed .folio-imprint__thread-stroke {
  stroke-dashoffset: 0;
}

.folio-imprint__thread-bead {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
  transform: scale(.3);
  transition: opacity .45s var(--ease) 2.2s, transform .55s var(--ease-spring) 2.2s;
}

.folio-imprint.is-revealed .folio-imprint__thread-bead {
  opacity: 1;
  transform: scale(1);
}

.folio-imprint__thread-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: currentColor;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(11px, 1vw, 13px);
  letter-spacing: -.005em;
  opacity: 0;
  transform: translateY(-2px);
  transition: opacity .6s var(--ease-out) 1.8s, transform .6s var(--ease-out) 1.8s;
}

.folio-imprint.is-revealed .folio-imprint__thread-tag {
  opacity: .85;
  transform: translateY(0);
}

.folio-imprint__thread-tag-rule {
  display: inline-block;
  width: clamp(14px, 1.6vw, 22px);
  height: 1px;
  background: currentColor;
  opacity: .55;
}

.folio-imprint__thread-tag-mark {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0;
  color: currentColor;
  animation: folioImprintThreadMarkPulse 2.6s var(--ease) 2.6s infinite;
}

@keyframes folioImprintThreadMarkPulse {
  0%, 100% { transform: translateY(0); opacity: .85; }
  50% { transform: translateY(2px); opacity: 1; }
}

@media (max-width: 720px) {
  .folio-imprint {
    margin-top: clamp(28px, 5vw, 44px);
    margin-bottom: clamp(20px, 4vw, 32px);
  }

  .folio-imprint__plate {
    grid-template-columns: minmax(0, 1fr);
    gap: clamp(10px, 2vw, 16px);
  }

  .folio-imprint__flourish {
    justify-content: center;
  }

  .folio-imprint__flourish svg {
    width: clamp(60px, 20vw, 100px);
    height: clamp(16px, 4vw, 22px);
  }

  .folio-imprint__flourish--lead {
    transform: none;
  }

  .folio-imprint__flourish--trail {
    transform: none;
  }

  .folio-imprint__flourish-pip--alt {
    order: 2;
  }

  .folio-imprint__core {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    text-align: center;
    gap: clamp(10px, 2vw, 14px);
    padding: 0;
  }

  .folio-imprint__memo {
    align-items: center;
    text-align: center;
  }

  .folio-imprint__memo-line {
    text-align: center;
  }

  .folio-imprint__memo-meta {
    justify-content: center;
  }

  .folio-imprint__thread svg {
    width: 14px;
    height: 32px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .folio-imprint,
  .folio-imprint__flourish,
  .folio-imprint__stamp,
  .folio-imprint__stamp-halo,
  .folio-imprint__memo-eyebrow,
  .folio-imprint__memo-line,
  .folio-imprint__memo-meta,
  .folio-imprint__thread,
  .folio-imprint__thread-tag,
  .folio-imprint__thread-bead,
  .folio-imprint__flourish-pip,
  .folio-imprint__flourish-bead,
  .folio-imprint__flourish-halo {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
    stroke-dashoffset: 0 !important;
  }

  .folio-imprint__thread-tag-mark {
    animation: none !important;
  }

  .folio-imprint__wash {
    animation: none !important;
    opacity: 1;
  }
}
